    active_guest_thread: u64 = 0x7FFF_2020,
    active_idle_source: u64 = 1,
    last_decoded_op: Op = .invalid,
    last_decoded_len: u8 = 0,
    last_instruction_rip: u64 = 0,

    pub fn init(allocator: std.mem.Allocator) ElfState {
        return initWithMemory(allocator, MEM_SIZE);
    }

    /// Construct an x86-64 state with an address-space size chosen by the
    /// loader.  ELF keeps the historical 64 MiB default, while PE32+ images
    /// commonly have a much larger image and must not be truncated into it.
    pub fn initWithMemory(allocator: std.mem.Allocator, memory_size: u64) ElfState {
        const decode_cache = allocator.alloc(DecodeCacheEntry, PE_DECODE_CACHE_ENTRIES) catch unreachable;
        @memset(decode_cache, .{});
        const memory_len: usize = @intCast(memory_size);
        const mem = allocator.alloc(u8, memory_len) catch unreachable;
        const trace_storage = allocator.alloc(ElfTraceEntry, TRACE_BUFFER_LEN) catch unreachable;
        const heap_allocations = allocator.alloc(WindowsHeapAllocation, INITIAL_WINDOWS_HEAP_ALLOCATIONS) catch unreachable;
        const heap_free_indices = allocator.alloc(usize, INITIAL_WINDOWS_HEAP_ALLOCATIONS) catch unreachable;
        @memset(trace_storage, .{});
        @memset(heap_allocations, .{});
        @memset(heap_free_indices, 0);
        @memset(mem, 0);
        var state: ElfState = .{
            .allocator = allocator,
            .decode_cache = decode_cache,
            .mem = mem,
            .mem_base = MEM_BASE,
            .mem_size = memory_size,
            .trace_storage = trace_storage,
            .windows_heap_allocations = heap_allocations,
            .windows_heap_free_indices = heap_free_indices,
            .trace_syscalls = envFlag("ROSETTE_ELF_TRACE_SYSCALLS"),
            .trace_syscall_bytes = envFlag("ROSETTE_ELF_TRACE_SYSCALL_BYTES"),
            .trace_fd_filter = envU64("ROSETTE_ELF_TRACE_FD"),
            .trace_calls = envFlag("ROSETTE_ELF_TRACE_CALLS"),
            .trace_rip_start = envU64("ROSETTE_ELF_TRACE_START"),
            .trace_rip_end = envU64("ROSETTE_ELF_TRACE_END"),
            .trace_rip_limit = envU64("ROSETTE_ELF_TRACE_LIMIT"),
            .trace_write_address = envU64("ROSETTE_ELF_TRACE_WRITE_ADDRESS"),
            .diagnose_abi = envFlag("ROSETTE_ELF_DIAGNOSE_ABI") or envFlag("ROSETTE_ELF_INTERACTIVE_BRIDGE") or envFlag("ROSETTE_ELF_EDU_BRIDGE"),
        };
        state.trace_allocations = envFlag("ROSETTA_ELF_TRACE_ALLOCATIONS");
        state.trace_formatter = envFlag("ROSETTA_ELF_TRACE_FORMATTER");
        state.trace_formatter_address = envU64("ROSETTA_ELF_TRACE_FORMATTER_ADDRESS");
        state.trace_string_memory = envFlag("ROSETTA_ELF_TRACE_STRING_MEMORY") or envFlag("ROSETTE_ELF_TRACE_STRING_MEMORY");
        state.trace_vector = envFlag("ROSETTE_ELF_TRACE_VECTOR");
        state.trace_utf8 = envFlag("ROSETTE_ELF_TRACE_UTF8");
        state.trace_windows_threads = envFlag("ROSETTA_ELF_TRACE_WINDOWS_THREADS");
        state.trace_windows_messages = envFlag("ROSETTA_ELF_TRACE_WINDOWS_MESSAGES");
        state.trace_windows_audio = envFlag("ROSETTE_ELF_TRACE_WINDOWS_AUDIO") or envFlag("ROSETTA_ELF_TRACE_WINDOWS_AUDIO");
        state.trace_windows_paths = envFlag("ROSETTE_ELF_TRACE_WINDOWS_PATHS");
        state.trace_windows_waits = envFlag("ROSETTE_ELF_TRACE_WINDOWS_WAITS") or envFlag("ROSETTA_ELF_TRACE_WINDOWS_WAITS");
        state.trace_windows_conditions = envFlag("ROSETTE_ELF_TRACE_WINDOWS_CONDITIONS") or envFlag("ROSETTA_ELF_TRACE_WINDOWS_CONDITIONS");
        state.trace_windows_memory = envFlag("ROSETTE_ELF_TRACE_WINDOWS_MEMORY") or envFlag("ROSETTA_ELF_TRACE_WINDOWS_MEMORY");
        state.trace_windows_mappings = envFlag("ROSETTE_ELF_TRACE_WINDOWS_MAPPINGS") or envFlag("ROSETTA_ELF_TRACE_WINDOWS_MAPPINGS");
        state.trace_graphics_progress = envFlag("ROSETTE_ELF_GRAPHICS_PROGRESS_TRACE");
        // A fatal point stops the run by default: a warning is an error until
        // something proves otherwise. `=0` records every one without
        // stopping, and ROSETTE_XENIA_FATAL_POINT_ALLOW=<labels> steps past
        // named ones.
        state.windows_fatal_point_terminate = !envPresentAndFalse("ROSETTE_XENIA_FATAL_POINT_TERMINATE");
        state.configureWindowsFatalPointAllow(envText("ROSETTE_XENIA_FATAL_POINT_ALLOW"));
        state.guest_null_page_fatal = !envPresentAndFalse("ROSETTE_PE64_NULL_PAGE_FATAL");
        log.info("PE64 FATAL POINTS: terminate={} null_page_fatal={} allow=[{s}]; a fatal point stops the run where it was decided. ROSETTE_XENIA_FATAL_POINT_ALLOW=<label,...> steps past named ones, ROSETTE_XENIA_FATAL_POINT_TERMINATE=0 records without stopping, ROSETTE_PE64_NULL_PAGE_FATAL=0 lets a null-page access read zero again", .{
            state.windows_fatal_point_terminate,
            state.guest_null_page_fatal,
            state.windows_fatal_point_allow[0..state.windows_fatal_point_allow_len],
        });
        state.windows_capability_gaps_fatal = !envPresentAndFalse("ROSETTE_PE64_CAPABILITY_GAP_FATAL");
        state.windows_pthread_cond_native = envFlag("ROSETTE_PE64_NATIVE_PTHREAD_COND") or envFlag("ROSETTA_PE64_NATIVE_PTHREAD_COND");
        state.windows_guest_wait_compatibility = envFlag("ROSETTE_PE64_GUEST_WAIT_COMPAT") or envFlag("ROSETTA_PE64_GUEST_WAIT_COMPAT");
        state.xenia_rijndael_accelerator_enabled = envFlag("ROSETTE_PE64_XENIA_RIJNDAEL_ACCELERATOR");
        state.xenia_sha1_accelerator_enabled = envFlag("ROSETTE_PE64_XENIA_SHA1_ACCELERATOR");
        state.xenia_sha1_feed_enabled = !envPresentAndFalse("ROSETTE_PE64_XENIA_SHA1_FEED_ACCELERATOR");
        state.xenia_tabulate_accelerator_enabled = envFlag("ROSETTE_PE64_XENIA_TABULATE_ACCELERATOR");
        state.windows_scheduler.enabled = !envPresentAndFalse("ROSETTE_PE64_GUEST_SCHEDULER");
        if (envU64("ROSETTE_PE64_GUEST_SCHEDULER_QUANTUM")) |quantum| {
            if (quantum != 0) state.windows_scheduler.quantum = quantum;
        }
        if (envU64("ROSETTE_PE64_GUEST_SCHEDULER_SLICE")) |slice| {
            if (slice != 0) state.windows_scheduler.slice = slice;
        }
        if (envU64("ROSETTE_PE64_GUEST_SCHEDULER_EXPLICIT_STRIDE")) |stride| {
            if (stride != 0) state.windows_scheduler.explicit_stride = stride;
        }
        // The progress watchdog is on by default because it is silent unless
        // every observable axis freezes at once; a healthy run pays two
        // comparisons per step and prints nothing.
        state.windows_progress.enabled = !envPresentAndFalse("ROSETTE_PE64_STALL_WATCHDOG");
        // The guest clock's source. Default is the host monotonic clock; the
        // instruction-derived rate published a one-MIPS machine and made
        // every guest timer fire three thousand times too often per unit of
        // work. See `WINDOWS_GUEST_CLOCK_SAMPLE_STRIDE`.
        state.guest_clock.source = if (envEquals("ROSETTE_GUEST_CLOCK", "instructions")) .retired_instructions else .host_monotonic;
        if (envU64("ROSETTE_PE64_STALL_SAMPLE_STEPS")) |interval| {
            if (interval != 0) state.windows_progress.interval = interval;
        }
        if (envU64("ROSETTE_PE64_STALL_SAMPLES")) |samples| {
            if (samples != 0 and samples <= std.math.maxInt(u32)) {
                state.windows_progress.threshold = @intCast(samples);
            }
        }
        state.heap_next = MEM_BASE + (memory_size / 2);
        // Bind the ring to stable heap storage. The state is returned by value,
        // but the storage address remains valid until `deinit`.
        state.trace_ring = execution_history.Ring(ElfTraceEntry).init(trace_storage);
        return state;
    }

    pub fn deinit(self: *ElfState) void {
        if (self.decode_cache.len != 0) self.allocator.free(self.decode_cache);
        self.decode_cache = &.{};
        self.guest_kernel_calls.deinit(self.allocator);
        self.guest_page_protection.deinit(self.allocator);
        self.windows_registry.deinit(self.allocator);
        if (self.windows_guest_output_governors) |governors| self.allocator.destroy(governors);
        self.windows_guest_output_governors = null;
        if (self.windows_host_io) |io| {
            for (&self.windows_files) |*slot| {
                if (slot.standard_stream == null) {
                    if (slot.file) |file| file.close(io);
                }
                slot.* = .{};
            }
            for (&self.windows_finds) |*slot| {
                if (slot.dir) |dir| dir.close(io);
                slot.* = .{};
            }
        }
        for (&self.windows_file_mappings) |*mapping| {
            if (mapping.backing) |backing| std.posix.munmap(backing);
            mapping.* = .{};
        }
        for (&self.windows_memory_views) |*view| view.* = .{};
        for (&self.windows_virtual_allocations) |*allocation| {
            if (allocation.backing) |backing| std.posix.munmap(backing);
            allocation.* = .{};
        }
        self.windows_mapped_ranges = .{};
        // The Vulkan driver, not ElfState, owns these bytes.
        @memset(&self.native_memory_aliases, .{});
        self.native_memory_alias_count = 0;
        if (self.windows_heap_allocations.len != 0) self.allocator.free(self.windows_heap_allocations);
        if (self.windows_heap_free_indices.len != 0) self.allocator.free(self.windows_heap_free_indices);
        if (self.interactive_output_path) |path| self.allocator.free(path);
        self.call_stack.deinit(self.allocator);
        if (self.trace_storage.len != 0) self.allocator.free(self.trace_storage);
        self.allocator.free(self.mem);
    }

    fn captureWindowsGuestContext(self: *const ElfState) WindowsGuestThreadContext {
        var tls_values = [_]u64{0} ** WINDOWS_TLS_SLOT_COUNT;
        const teb = self.regs.segments.gs.base;
        if (teb != 0) {
            const tls_vector = self.read64(teb + 0x58);
            if (self.guestMemoryConst(tls_vector, WINDOWS_TLS_SLOT_COUNT * 8) != null) {
                for (0..WINDOWS_TLS_SLOT_COUNT) |slot| {
                    tls_values[slot] = self.read64(tls_vector + @as(u64, @intCast(slot * 8)));
                }
            }
        }
        return .{
            .regs = self.regs,
            .xmm = self.xmm,
            .ymm_hi = self.ymm_hi,
            .zmm_hi = self.zmm_hi,
            .k = self.k,
            .x87_stack = self.x87_stack,
            .x87_tags = self.x87_tags,
            .x87_top = self.x87_top,
            .x87_status = self.x87_status,
            .x87_control = self.x87_control,
            .tls_values = tls_values,
            .windows_last_error = self.windows_last_error,
            .windows_errno_storage = self.windows_crt_globals.owner_errno_storage,
            .call_stack_depth = self.call_stack.frames.items.len,
            .active_guest_thread = self.active_guest_thread,
            .active_idle_source = self.active_idle_source,
            .last_decoded_op = self.last_decoded_op,
            .last_decoded_len = self.last_decoded_len,
            .last_instruction_rip = self.last_instruction_rip,
        };
    }

    fn restoreWindowsGuestContext(self: *ElfState, context: *const WindowsGuestThreadContext) void {
        self.regs = context.regs;
        self.xmm = context.xmm;
        self.ymm_hi = context.ymm_hi;
        self.zmm_hi = context.zmm_hi;
        self.k = context.k;
        self.x87_stack = context.x87_stack;
        self.x87_tags = context.x87_tags;
        self.x87_top = context.x87_top;
        self.x87_status = context.x87_status;
        self.x87_control = context.x87_control;
        const teb = self.regs.segments.gs.base;
        if (teb != 0) {
            const tls_vector = self.read64(teb + 0x58);
            if (self.guestMemory(tls_vector, WINDOWS_TLS_SLOT_COUNT * 8) != null) {
                for (0..WINDOWS_TLS_SLOT_COUNT) |slot| {
                    self.write64(tls_vector + @as(u64, @intCast(slot * 8)), context.tls_values[slot]);
                }
            }
        }
        self.windows_last_error = context.windows_last_error;
        self.windows_crt_globals.owner_errno_storage = context.windows_errno_storage;
        if (context.call_stack_depth <= self.call_stack.frames.items.len) {
            self.call_stack.frames.items = self.call_stack.frames.items[0..context.call_stack_depth];
        }
        self.active_guest_thread = context.active_guest_thread;
        self.active_idle_source = context.active_idle_source;
        self.last_decoded_op = context.last_decoded_op;
        self.last_decoded_len = context.last_decoded_len;
        self.last_instruction_rip = context.last_instruction_rip;
    }

    /// Return the Windows-visible thread identifier for the currently
    /// executing cooperative context.  The PE executor has one host thread,
    /// but Xenia still uses GetCurrentThreadId to implement recursive mutex
    /// ownership.  Returning one constant for every guest worker makes every
    /// worker look recursive and lets it enter another thread's critical
    /// region.
    pub fn currentWindowsThreadId(self: *const ElfState) u64 {
        if (self.windows_active_guest_thread_slot) |index| {
            const thread_id = self.windows_guest_threads[index].thread_id;
            if (thread_id != 0) return thread_id;
        }
        // The owner context is the process's initial Windows thread.  Its
        // TEB uses the same stable ID, and worker IDs begin at 2.
        return 1;
    }

    /// Monotonic guest time shared by the owner and every cooperative worker
    /// slice. It is deliberately separate from `executed_steps`, which is the
    /// owner-loop progress counter used by scheduling and checkpoint output.
    pub fn windowsGuestClockTicks(self: *const ElfState) u64 {
        return self.guest_clock.ticks;
    }

    /// The frequency the guest is told its performance counter runs at.
    /// Shared with the wait deadlines so the two cannot disagree.
    pub fn windowsGuestClockHz(_: *const ElfState) u64 {
        return WINDOWS_GUEST_CLOCK_HZ;
    }

    /// The guest's wall clock as a FILETIME: the fixed base plus the guest
    /// clock. GetSystemTimeAsFileTime answers from here, and so does every
    /// deadline Rosette derives from a guest wall-clock time, so the two
    /// cannot disagree about when "now" is.
    pub fn windowsGuestFileTime(self: *const ElfState) u64 {
        const ticks = self.guest_clock.ticks;
        const seconds = ticks / WINDOWS_GUEST_CLOCK_HZ;
        const remainder = ticks % WINDOWS_GUEST_CLOCK_HZ;
        return WINDOWS_GUEST_FILETIME_BASE +|
            (seconds *| 10_000_000) +|
            (remainder *| 10_000_000 / WINDOWS_GUEST_CLOCK_HZ);
    }

    /// End the active worker's slice at a yield boundary.
    ///
    /// This is the whole meaning of `YieldProcessor`, `SwitchToThread` and
    /// `Sleep(0)`: the caller has nothing to do and another thread should
    /// run. Rosetta answered all three by returning, so a spin-wait kept the
    /// interpreter for the rest of its slice and the threads that could make
    /// progress waited on a thread that could not.
    ///
    /// Deliberately a request rather than an immediate switch: the service
    /// loop has to save the worker's context and restore the owner's, and
    /// tearing that down from inside an import handler would leave the
    /// register file half-swapped.
    pub fn requestWindowsGuestSliceYield(self: *ElfState) void {
        if (self.windows_active_guest_thread_slot == null) return;
        if (!self.windows_guest_slice_yield_requested) {
            self.windows_guest_slice_yield_requested = true;
            self.windows_guest_slice_yields +|= 1;
        }
    }

    /// A worker read the clock.
    ///
    /// Reads piling up inside one slice are a poll: the thread is waiting for
    /// time to pass, and under one interpreter spinning cannot make time pass,
    /// only keep every other thread from running while it does. Xenia's GPU
    /// frame limiter spins between vblanks by design and its TimerQueue
    /// spin-waits on steady_clock; both now end their slice here instead of
    /// at its limit.
    pub fn noteWindowsGuestClockRead(self: *ElfState) void {
        if (self.windows_active_guest_thread_slot == null) return;
        self.windows_slice_clock_reads +|= 1;
        if (self.windows_slice_clock_reads == WINDOWS_CLOCK_POLL_YIELD_READS) {
            self.windows_clock_poll_yields +|= 1;
            self.requestWindowsGuestSliceYield();
        }
    }

    fn beginWindowsWaitAccounting(
        self: *ElfState,
        thread: *WindowsGuestThread,
        key: u64,
        kind: wait_cost.WaitKind,
        timeout_milliseconds: u64,
        deadline: u64,
    ) void {
        if (thread.wait_cost_site != 0) return;
        const accounting_step = self.totalInterpretedSteps();
        const ticks = self.guest_clock.ticks;
        thread.wait_cost_site = self.windows_wait_cost.begin(key, kind, accounting_step, ticks, timeout_milliseconds);
        thread.wait_cost_start_step = accounting_step;
        thread.wait_cost_start_ticks = ticks;
        thread.wait_cost_deadline = deadline;
        thread.blocked_since_total_steps = accounting_step;
        thread.blocked_since_guest_ticks = ticks;
    }

    fn endWindowsWaitAccounting(self: *ElfState, thread: *WindowsGuestThread, outcome: wait_cost.Outcome) void {
        if (thread.wait_cost_site != 0) {
            self.windows_wait_cost.end(
                thread.wait_cost_site,
                outcome,
                thread.wait_cost_start_step,
                thread.wait_cost_start_ticks,
                self.totalInterpretedSteps(),
                self.guest_clock.ticks,
                thread.wait_cost_deadline,
            );
        }
        thread.wait_cost_site = 0;
        thread.wait_cost_start_step = 0;
        thread.wait_cost_start_ticks = 0;
        thread.wait_cost_deadline = 0;
        thread.blocked_since_total_steps = 0;
        thread.blocked_since_guest_ticks = 0;
    }

    fn endWindowsWaitAccountingIfKind(
        self: *ElfState,
        thread: *WindowsGuestThread,
        kind: wait_cost.WaitKind,
        outcome: wait_cost.Outcome,
    ) void {
        if (thread.wait_cost_site == 0) return;
        const index = @as(usize, thread.wait_cost_site) - 1;
        if (index >= self.windows_wait_cost.count or self.windows_wait_cost.sites[index].kind != kind) return;
        self.endWindowsWaitAccounting(thread, outcome);
    }

    fn endWindowsHandleWaitAccounting(self: *ElfState, thread: *WindowsGuestThread, outcome: wait_cost.Outcome) void {
        if (thread.wait_cost_site == 0) return;
        const index = @as(usize, thread.wait_cost_site) - 1;
        if (index >= self.windows_wait_cost.count) return;
        switch (self.windows_wait_cost.sites[index].kind) {
            .finite_handle, .infinite_handle, .multiple => self.endWindowsWaitAccounting(thread, outcome),
            else => {},
        }
    }

    fn noteWindowsWaitSignal(self: *ElfState, key: u64) void {
        const thread_handle = if (self.windows_active_guest_thread_slot) |slot|
            self.windows_guest_threads[slot].handle
        else
            self.active_guest_thread;
        self.windows_wait_cost.signal(
            key,
            self.totalInterpretedSteps(),
            self.guest_clock.ticks,
            .{ .thread_handle = thread_handle, .rip = self.last_instruction_rip },
        );
    }

    fn endActiveWindowsSrwWaitAccounting(self: *ElfState) void {
        if (self.windows_active_guest_thread_slot) |index| {
            self.endWindowsWaitAccountingIfKind(&self.windows_guest_threads[index], .srw_lock, .signaled);
        }
    }

    /// Park the active worker for a guest-millisecond interval.
    ///
    /// `Sleep(n)` used to return immediately, which turns every timed back-off
    /// in the guest into a busy-wait - including the one Xenia's frame limiter
    /// uses while it waits for a title to open. Returns whether the caller was
    /// a worker that could be parked; the owner has no context to park and
    /// falls back to servicing workers.
    pub fn parkWindowsGuestSleep(self: *ElfState, milliseconds: u64) bool {
        const index = self.windows_active_guest_thread_slot orelse return false;
        if (milliseconds == 0) {
            self.requestWindowsGuestSliceYield();
            return true;
        }
        const thread = &self.windows_guest_threads[index];
        thread.status = .blocked;
        thread.blocked_wait_handle = 0;
        thread.blocked_srw_lock = 0;
        thread.blocked_condition = 0;
        thread.blocked_condition_mutex = 0;
        thread.blocked_wait_timeout = milliseconds;
        thread.blocked_wait_deadline = self.guest_clock.ticks +|
            (milliseconds *| WINDOWS_GUEST_CLOCK_TICKS_PER_MILLISECOND);
        self.beginWindowsWaitAccounting(
            thread,
            0,
            .deadline,
            milliseconds,
            thread.blocked_wait_deadline,
        );
        self.windows_thread_blocks +|= 1;
        self.windows_guest_sleep_parks +|= 1;
        return true;
    }

    /// Park the active worker for `ticks` of the guest clock, the precision
    /// `NtDelayExecution` asks in: 100 ns at a time, which a millisecond
    /// `Sleep` would round away. Zero is a yield.
    pub fn parkWindowsGuestDelayTicks(self: *ElfState, ticks: u64) bool {
        const index = self.windows_active_guest_thread_slot orelse return false;
        if (ticks == 0) {
            self.windows_nt_delay_yields +|= 1;
            self.requestWindowsGuestSliceYield();
            return true;
        }
        const thread = &self.windows_guest_threads[index];
        thread.status = .blocked;
        thread.blocked_wait_handle = 0;
        thread.blocked_srw_lock = 0;
        thread.blocked_condition = 0;
        thread.blocked_condition_mutex = 0;
        thread.blocked_wait_timeout = std.math.divCeil(u64, ticks, WINDOWS_GUEST_CLOCK_TICKS_PER_MILLISECOND) catch 0;
        thread.blocked_wait_deadline = self.guest_clock.ticks +| ticks;
        self.beginWindowsWaitAccounting(
            thread,
            0,
            .deadline,
            thread.blocked_wait_timeout,
            thread.blocked_wait_deadline,
        );
        self.windows_thread_blocks +|= 1;
        self.windows_nt_delay_parks +|= 1;
        return true;
    }

    /// MinGW's PE pthread implementation stores a pointer to its real mutex
    /// record in the first word of pthread_mutex_t.  The record is guest
    /// memory, not a Rosetta wait-object handle, and the condition-variable
    /// entry point reaches us before the image's own unlock/relock sequence.
    /// Resolve only a guest-backed, sufficiently sized record so an
    /// uninitialized/static sentinel cannot be mistaken for a pointer.
    fn windowsPthreadMutexImpl(self: *const ElfState, address: u64) ?u64 {
        if (address == 0 or self.guestMemoryConst(address, 8) == null) return null;
        const impl = self.read64(address);
        if (impl < 0x1000 or self.guestMemoryConst(impl, 0x18) == null) return null;
        return impl;
    }

    pub const WindowsPthreadMutexReleaseResult = enum {
        invalid,
        released,
        already_unlocked,
    };

    pub const WindowsPthreadMutexAcquireResult = union(enum) {
        invalid,
        acquired,
        contended: u64,
    };

    /// Release one MinGW pthread mutex ownership level as the first half of
    /// pthread_cond_wait.  The layout mirrors the PE image's own
    /// pthread_mutex_unlock implementation: state at +0, attributes at +4,
    /// event at +8, recursion depth at +0x10, and owner ID at +0x14.
    /// Rosetta owns the transition while the guest is parked so no host
    /// blocking primitive can strand the single interpreter.
    pub fn releaseWindowsGuestPthreadMutex(self: *ElfState, address: u64) WindowsPthreadMutexReleaseResult {
        const impl = self.windowsPthreadMutexImpl(address) orelse return .invalid;
        const state = self.read32(impl);
        if (state == 0) return .already_unlocked;
        if (state != 1 and state != 2) return .invalid;

        const attributes = self.read32(impl + 4);
        const owner = self.read32(impl + 0x14);
        const current_thread_id: u32 = @truncate(self.currentWindowsThreadId());
        if (attributes != 0 and owner != current_thread_id) return .invalid;

        const recursion = self.read32(impl + 0x10);
        if (recursion != 0) {
            self.write32(impl + 0x10, recursion - 1);
            return .released;
        }

        self.write32(impl + 0x14, std.math.maxInt(u32));
        self.write32(impl, 0);
        if (state == 2) {
            const event = self.read64(impl + 8);
            if (event != 0) {
                if (self.windowsWaitObjectIndex(event) == null) {
                    self.registerWindowsEvent(event, false, false);
                }
                _ = self.signalWindowsWaitObject(event, false);
            }
        }
        return .released;
    }

    /// Try to reacquire the mutex before a condition waiter returns to guest
    /// code.  A contended result carries the mutex's own event handle so the
    /// worker can park on exactly the same object that the image's lock path
    /// would wait on.
    pub fn acquireWindowsGuestPthreadMutex(self: *ElfState, address: u64) WindowsPthreadMutexAcquireResult {
        const impl = self.windowsPthreadMutexImpl(address) orelse return .invalid;
        const state = self.read32(impl);
        const attributes = self.read32(impl + 4);
        const current_thread_id: u32 = @truncate(self.currentWindowsThreadId());
        if (state == 0) {
            self.write32(impl, 1);
            if (attributes != 0) self.write32(impl + 0x14, current_thread_id);
            return .acquired;
        }
        if (state != 1 and state != 2) return .invalid;

        if (attributes != 0 and self.read32(impl + 0x14) == current_thread_id) {
            // Attribute value 2 is the image's recursive mutex mode.  The
            // ordinary mode reports a self-lock failure in the guest; a
            // condition waiter should never need to take that path.
            if (attributes == 2) {
                self.write32(impl + 0x10, self.read32(impl + 0x10) +| 1);
                return .acquired;
            }
            return .invalid;
        }

        const event = self.read64(impl + 8);
        if (event == 0) return .invalid;
        if (self.windowsWaitObjectIndex(event) == null) {
            self.registerWindowsEvent(event, false, false);
        }
        if (state == 1) self.write32(impl, 2);
        return .{ .contended = event };
    }

    fn windowsSrwLockIndex(self: *const ElfState, address: u64) ?usize {
        for (self.windows_srw_locks, 0..) |lock, index| {
            if (lock.address == address) return index;
        }
        return null;
    }

    fn ensureWindowsSrwLock(self: *ElfState, address: u64) ?*WindowsSrwLock {
        if (address == 0 or self.guestMemory(address, 8) == null) return null;
        if (self.windowsSrwLockIndex(address)) |index| return &self.windows_srw_locks[index];
        for (&self.windows_srw_locks) |*lock| {
            if (lock.address == 0) {
                lock.* = .{ .address = address };
                return lock;
            }
        }
        return null;
    }

    pub const WindowsSrwAcquireResult = enum {
        invalid,
        acquired,
        contended,
    };

    pub const WindowsConditionWaitResult = enum {
        invalid,
        resumed,
        blocked,
    };

    pub const WindowsWaitResult = enum {
        invalid,
        signaled,
        yielded,
        blocked,
        timeout,
        unknown,
    };

    fn windowsWaitObjectIndex(self: *const ElfState, handle: u64) ?usize {
        if (handle == 0) return null;
        // Only as far as the highest slot in use. A freed slot below it is
        // the next one filled, so a run holding a few hundred objects scans
        // a few hundred entries however large the table is.
        for (self.windows_wait_objects[0..self.windows_wait_object_high_water], 0..) |*object, index| {
            if (object.handle == handle) return index;
        }
        return null;
    }

    fn ensureWindowsWaitObject(self: *ElfState, handle: u64) ?*WindowsWaitObject {
        if (handle == 0) return null;
        if (self.windowsWaitObjectIndex(handle)) |index| return &self.windows_wait_objects[index];
        for (&self.windows_wait_objects, 0..) |*object, index| {
            if (object.handle == 0) {
                object.* = .{ .handle = handle };
                if (index >= self.windows_wait_object_high_water) self.windows_wait_object_high_water = index + 1;
                return object;
            }
        }
        self.noteWindowsWaitObjectTableFull(handle);
        return null;
    }

    /// `CloseHandle` on an event, mutex, semaphore or thread handle.
    ///
    /// Nothing freed these, so every object a guest ever created held its
    /// slot for the rest of the run: 416 events were registered on
    /// 2026-09-14 before the title drew anything, against a table of 512,
    /// and the object after a full table had no wait model at all. A handle
    /// a parked thread is still waiting on keeps its object until the thread
    /// leaves, as Windows keeps an object alive while a wait holds it.
    /// Returns whether the handle was a wait object.
    pub fn closeWindowsWaitObject(self: *ElfState, handle: u64) bool {
        const index = self.windowsWaitObjectIndex(handle) orelse return false;
        if (self.windows_main_wait_handle == handle) return true;
        for (&self.windows_guest_threads) |*thread| {
            if (thread.status == .blocked and thread.waitsOnHandle(handle)) return true;
        }
        self.windows_wait_objects[index] = .{};
        self.windows_wait_objects_freed +|= 1;
        while (self.windows_wait_object_high_water != 0 and
            self.windows_wait_objects[self.windows_wait_object_high_water - 1].handle == 0)
        {
            self.windows_wait_object_high_water -= 1;
        }
        return true;
    }

    /// CreateFile with every file slot in use.
    pub fn noteWindowsFileTableFull(self: *ElfState) void {
        self.windows_file_table_full +|= 1;
        const occurrence = self.windows_file_table_full;
        if (occurrence == 1) self.windows_fatal_point_events +|= 1;
        if (comptime !@import("builtin").is_test) {
            if (shouldReportWindowsPointOccurrence(occurrence)) {
                var caller_text: [guest_symbol_text_bytes]u8 = undefined;
                log.err("PE64 FATAL POINT: guest-condition label=file-handle-table-full owner=rosette:file-model occurrence={d} import={s} capacity={d} step={d} caller={s}; every file slot holds an open handle, so this open fails with ERROR_TOO_MANY_OPEN_FILES and the guest loses a file Windows would have opened. CloseHandle, fclose and _close free slots; read WINDOWS FILE FAILURES for what was being opened", .{
                    occurrence,
                    if (self.windows_current_import.len == 0) "<unattributed>" else self.windows_current_import,
                    self.windows_files.len,
                    self.executed_steps,
                    self.describeGuestAddressOrUnnamed(self.last_instruction_rip, &caller_text),
                });
            }
        }
        self.terminateForWindowsFatalPoint("file-handle-table-full");
    }

    /// CreateFileMapping with every mapping slot in use.
    pub fn noteWindowsFileMappingTableFull(self: *ElfState, handle: u64) void {
        self.windows_file_mapping_table_full +|= 1;
        const occurrence = self.windows_file_mapping_table_full;
        if (occurrence == 1) self.windows_fatal_point_events +|= 1;
        if (comptime !@import("builtin").is_test) {
            if (shouldReportWindowsPointOccurrence(occurrence)) {
                log.err("PE64 FATAL POINT: guest-condition label=file-mapping-table-full owner=rosette:file-model occurrence={d} handle=0x{x} capacity={d} step={d}; every mapping slot holds a mapping that is open or still has a view, so CreateFileMapping returns NULL. A mapping's slot is freed when its handle is closed and its last view unmapped", .{
                    occurrence,
                    handle,
                    self.windows_file_mappings.len,
                    self.executed_steps,
                });
            }
        }
        self.terminateForWindowsFatalPoint("file-mapping-table-full");
    }

    /// A kernel object with no slot to hold its wait model.
    fn noteWindowsWaitObjectTableFull(self: *ElfState, handle: u64) void {
        self.windows_wait_object_table_full +|= 1;
        const occurrence = self.windows_wait_object_table_full;
        if (occurrence == 1) self.windows_fatal_point_events +|= 1;
        if (comptime !@import("builtin").is_test) {
            if (shouldReportWindowsPointOccurrence(occurrence)) {
                var caller_text: [guest_symbol_text_bytes]u8 = undefined;
                log.err("PE64 FATAL POINT: guest-condition label=wait-object-table-full owner=rosette:wait-model occurrence={d} handle=0x{x} capacity={d} freed_so_far={d} step={d} caller={s}; every slot holds an event, mutex, semaphore or thread handle that has not been closed, so this object has no wait model and any wait on it would be invented. Either the guest holds more than MAX_WINDOWS_WAIT_OBJECTS at once or a close path is not freeing them", .{
                    occurrence,
                    handle,
                    self.windows_wait_objects.len,
                    self.windows_wait_objects_freed,
                    self.executed_steps,
                    self.describeGuestAddressOrUnnamed(self.last_instruction_rip, &caller_text),
                });
            }
        }
        self.terminateForWindowsFatalPoint("wait-object-table-full");
    }

    pub fn registerWindowsTimer(self: *ElfState, handle: u64, manual_reset: bool) void {
        if (self.ensureWindowsWaitObject(handle)) |object| {
            object.* = .{ .handle = handle, .kind = .timer, .manual_reset = manual_reset };
            self.windows_timers_created +|= 1;
        }
    }

    /// SetWaitableTimer. `due` is the guest's LARGE_INTEGER: negative is a
    /// relative interval in 100 ns, positive an absolute FILETIME, which is
    /// measured against `now_filetime` - the same clock the guest's
    /// GetSystemTimePreciseAsFileTime reads, so Xenia's `SetOnceAt` (an
    /// absolute time it computed from that call) lands where it meant.
    pub fn setWindowsTimer(self: *ElfState, handle: u64, due: i64, period_ms: u64, now_filetime: u64, completion_routine: u64) bool {
        const index = self.windowsWaitObjectIndex(handle) orelse return false;
        const object = &self.windows_wait_objects[index];
        if (object.kind != .timer) return false;
        self.refreshWindowsGuestClock();
        const now = self.guest_clock.ticks;
        const relative_100ns: u64 = if (due < 0)
            @as(u64, @bitCast(due)) *% std.math.maxInt(u64)
        else if (@as(u64, @intCast(due)) > now_filetime)
            @as(u64, @intCast(due)) - now_filetime
        else
            0;
        const ticks: u64 = @intCast(@min(
            @as(u128, relative_100ns) * WINDOWS_GUEST_CLOCK_TICKS_PER_MILLISECOND / 10_000,
            std.math.maxInt(u64) / 2,
        ));
        if (object.due_ticks == 0) self.windows_armed_timers +|= 1;
        object.due_ticks = now +| @max(ticks, 1);
        object.period_ticks = period_ms *| WINDOWS_GUEST_CLOCK_TICKS_PER_MILLISECOND;
        object.signaled = false;
        self.windows_next_timer_due = @min(self.windows_next_timer_due, object.due_ticks);
        self.windows_timer_sets +|= 1;
        if (completion_routine != 0) {
            self.windows_timer_completion_routines +|= 1;
            if (self.windows_timer_completion_routines == 1 and !@import("builtin").is_test) {
                var routine_text: [guest_symbol_text_bytes]u8 = undefined;
                log.warn("PE64 waitable timer completion routine not delivered: handle=0x{x} routine={s} step={d}; a completion routine is an APC that runs when the thread that armed the timer next waits alertably, and Rosette has no APC delivery, so the timer signals its waiters but the routine never runs", .{
                    handle,
                    self.describeGuestAddressOrUnnamed(completion_routine, &routine_text),
                    self.executed_steps,
                });
            }
        }
        return true;
    }

    /// CancelWaitableTimer disarms without changing the signalled state.
    pub fn cancelWindowsTimer(self: *ElfState, handle: u64) bool {
        const index = self.windowsWaitObjectIndex(handle) orelse return false;
        const object = &self.windows_wait_objects[index];
        if (object.kind != .timer) return false;
        if (object.due_ticks != 0) self.windows_armed_timers -|= 1;
        object.due_ticks = 0;
        object.period_ticks = 0;
        return true;
    }

    /// Fire a timer whose due tick has passed: signal it and re-arm a
    /// periodic one past `now` (missed periods are skipped, not replayed as
    /// a burst).
    fn advanceWindowsTimer(self: *ElfState, object: *WindowsWaitObject, now: u64) void {
        object.signaled = true;
        self.windows_timer_fires +|= 1;
        if (object.period_ticks != 0) {
            const behind = (now - object.due_ticks) / object.period_ticks + 1;
            object.due_ticks +|= behind *| object.period_ticks;
        } else {
            object.due_ticks = 0;
            self.windows_armed_timers -|= 1;
        }
    }

    fn fireDueWindowsTimers(self: *ElfState, now: u64) u64 {
        if (self.windows_armed_timers == 0 or now < self.windows_next_timer_due) return 0;
        var next: u64 = std.math.maxInt(u64);
        var woken: u64 = 0;
        for (self.windows_wait_objects[0..self.windows_wait_object_high_water]) |*object| {
            if (object.handle == 0 or object.kind != .timer or object.due_ticks == 0) continue;
            if (now >= object.due_ticks) {
                self.advanceWindowsTimer(object, now);
                // A notification timer releases every waiter and stays
                // signalled; a synchronization timer releases one and is
                // consumed by it.
                const released = self.wakeWindowsGuestThreadsForWait(object.handle, object.manual_reset);
                if (!object.manual_reset and released != 0) object.signaled = false;
                woken +|= released;
            }
            if (object.due_ticks != 0) next = @min(next, object.due_ticks);
        }
        self.windows_next_timer_due = next;
        return woken;
    }

    pub fn registerWindowsEvent(self: *ElfState, handle: u64, manual_reset: bool, initial_state: bool) void {
        if (self.ensureWindowsWaitObject(handle)) |object| {
            object.* = .{
                .handle = handle,
                .kind = .event,
                .signaled = initial_state,
                .manual_reset = manual_reset,
            };
            if (self.trace_windows_waits) {
                self.windows_wait_registration_trace_events +|= 1;
                const event = self.windows_wait_registration_trace_events;
                if (event <= 8 or (event & (event - 1)) == 0 or event % 16 == 0) {
                    log.info("PE64 wait object registered: kind=event handle=0x{x} manual_reset={} initial_state={} creator_rip=0x{x} active_thread=0x{x} step={d} event={d}", .{
                        handle,
                        manual_reset,
                        initial_state,
                        self.regs.rip,
                        self.active_guest_thread,
                        self.executed_steps,
                        event,
                    });
                }
            }
        }
    }

    pub fn registerWindowsMutex(self: *ElfState, handle: u64, initially_owned: bool) void {
        if (self.ensureWindowsWaitObject(handle)) |object| {
            object.* = .{
                .handle = handle,
                .kind = .mutex,
                .signaled = !initially_owned,
            };
        }
    }

    pub fn registerWindowsSemaphore(self: *ElfState, handle: u64, initial_count: u64, maximum_count: u64) void {
        if (self.ensureWindowsWaitObject(handle)) |object| {
            const maximum: u32 = @intCast(@min(maximum_count, std.math.maxInt(u32)));
            const count: u32 = @intCast(@min(@min(initial_count, maximum_count), std.math.maxInt(u32)));
            object.* = .{
                .handle = handle,
                .kind = .semaphore,
                .signaled = count != 0,
                .count = count,
                .maximum = maximum,
            };
        }
    }

    pub fn registerWindowsThreadWaitObject(self: *ElfState, handle: u64) void {
        if (self.ensureWindowsWaitObject(handle)) |object| {
            object.* = .{ .handle = handle, .kind = .thread };
        }
    }

    fn windowsWaitObjectReady(self: *const ElfState, handle: u64) ?bool {
        for (&self.windows_guest_threads) |*thread| {
            if (thread.handle == handle and thread.status != .vacant) {
                return thread.status == .completed or thread.status == .failed;
            }
        }
        if (self.windowsWaitObjectIndex(handle)) |index| {
            const object = self.windows_wait_objects[index];
            return switch (object.kind) {
                .semaphore => object.count != 0,
                .timer => object.signaled or (object.due_ticks != 0 and self.guest_clock.ticks >= object.due_ticks),
                else => object.signaled,
            };
        }
        return null;
    }

    fn windowsWaitObjectKindName(self: *const ElfState, handle: u64) []const u8 {
        for (&self.windows_guest_threads) |*thread| {
            if (thread.handle == handle and thread.status != .vacant) return "thread";
        }
        if (self.windowsWaitObjectIndex(handle)) |index| return @tagName(self.windows_wait_objects[index].kind);
        return "unknown";
    }

    pub fn windowsGuestWaitServiceSlice(self: *const ElfState) u64 {
        if (self.windows_scheduler.enabled and self.windows_scheduler.slice != 0) {
            return self.windows_scheduler.slice;
        }
        return WINDOWS_GUEST_THREAD_SERVICE_SLICE;
    }

    /// Service a worker from an explicit owner-side wait/message/lock
    /// boundary subject to the scheduler's separate owner stride.  A real
    /// blocked owner still uses `serviceWindowsGuestThreads` directly from
    /// the outer wait loop; this gate is only for boundaries that return
    /// immediately and can therefore be hit thousands of times in a tight
    /// guest UI loop.
    pub fn serviceWindowsGuestBoundary(self: *ElfState, max_steps: u64) u64 {
        if (max_steps == 0 or self.terminated or self.windows_active_guest_thread_slot != null) return 0;
        if (!self.windows_scheduler.enabled) return self.serviceWindowsGuestThreads(max_steps);
        const policy = &self.windows_scheduler;
        if (self.executed_steps < policy.next_explicit_service_step) {
            policy.explicit_service_skips +|= 1;
            return 0;
        }
        const stride = if (policy.explicit_stride != 0)
            policy.explicit_stride
        else
            WINDOWS_GUEST_THREAD_SERVICE_OWNER_STRIDE;
        policy.next_explicit_service_step = self.executed_steps +| stride;
        const serviced = self.serviceWindowsGuestThreads(max_steps);
        policy.explicit_service_calls +|= 1;
        policy.explicit_serviced_steps +|= serviced;
        return serviced;
    }

    fn traceWindowsWaitDecision(self: *ElfState, handle: u64, timeout: u64, result: WindowsWaitResult) void {
        if (!self.trace_windows_waits) return;
        if (result == .signaled) return;
        self.windows_wait_trace_events +|= 1;
        const event = self.windows_wait_trace_events;
        if (event > 8 and (event & (event - 1)) != 0) return;
        const active_slot = if (self.windows_active_guest_thread_slot) |index| @as(u64, @intCast(index)) else std.math.maxInt(u64);
        var first_runnable_handle: u64 = 0;
        var first_blocked_handle: u64 = 0;
        var first_blocked_wait: u64 = 0;
        var first_blocked_lock: u64 = 0;
        var first_blocked_condition: u64 = 0;
        var first_blocked_condition_mutex: u64 = 0;
        for (&self.windows_guest_threads) |*thread| {
            if (first_runnable_handle == 0 and (thread.status == .runnable or thread.status == .pending)) {
                first_runnable_handle = thread.handle;
            }
            if (first_blocked_handle == 0 and thread.status == .blocked) {
                first_blocked_handle = thread.handle;
                first_blocked_wait = thread.blocked_wait_handle;
                first_blocked_lock = thread.blocked_srw_lock;
                first_blocked_condition = thread.blocked_condition;
                first_blocked_condition_mutex = thread.blocked_condition_mutex;
            }
        }
        log.info("PE64 guest wait decision: result={s} handle=0x{x} kind={s} timeout=0x{x} active_thread=0x{x} active_slot=0x{x} rip=0x{x} return_rip=0x{x} rsp=0x{x} owner_service_steps={d} workers(pending/runnable/blocked)={d}/{d}/{d} first_runnable=0x{x} first_blocked=0x{x} blocked_wait=0x{x} blocked_lock=0x{x} blocked_condition=0x{x} blocked_condition_mutex=0x{x} step={d} event={d}", .{
            @tagName(result),
            handle,
            self.windowsWaitObjectKindName(handle),
            timeout,
            self.active_guest_thread,
            active_slot,
            self.regs.rip,
            self.read64(self.regs.rsp),
            self.regs.rsp,
            self.windows_wait_last_owner_service_steps,
            self.countWindowsWorkers(.pending),
            self.countWindowsWorkers(.runnable),
            self.countWindowsWorkers(.blocked),
            first_runnable_handle,
            first_blocked_handle,
            first_blocked_wait,
            first_blocked_lock,
            first_blocked_condition,
            first_blocked_condition_mutex,
            self.executed_steps,
            event,
        });
    }

    pub fn windowsWaitObjectSignaled(self: *const ElfState, handle: u64) bool {
        return self.windowsWaitObjectReady(handle) orelse false;
    }

    /// Report whether a handle belongs to Rosetta's synthetic Windows wait
    /// table.  NT synchronization calls need to distinguish an unsignaled
    /// known object from an invalid handle; treating both as STATUS_SUCCESS
    /// lets a guest walk past the kernel contract and leaves the real waiter
    /// permanently disconnected from its signaler.
    pub fn windowsWaitObjectKnown(self: *const ElfState, handle: u64) bool {
        if (handle == 0) return false;
        if (self.windowsWaitObjectIndex(handle) != null) return true;
        for (&self.windows_guest_threads) |*thread| {
            if (thread.handle == handle and thread.status != .vacant) return true;
        }
        return false;
    }

    /// Return the current semaphore count for the NT previous-count ABI.
    /// Other wait-object kinds intentionally return null rather than exposing
    /// their signaled bit as a count.
    pub fn windowsWaitObjectSemaphoreCount(self: *const ElfState, handle: u64) ?u32 {
        const index = self.windowsWaitObjectIndex(handle) orelse return null;
        const object = self.windows_wait_objects[index];
        return if (object.kind == .semaphore) object.count else null;
    }

    fn consumeWindowsWaitObject(self: *ElfState, handle: u64) void {
        const index = self.windowsWaitObjectIndex(handle) orelse return;
        const object = &self.windows_wait_objects[index];
        switch (object.kind) {
            .event => {
                if (!object.manual_reset) object.signaled = false;
            },
            .mutex => object.signaled = false,
            .semaphore => {
                if (object.count != 0) object.count -= 1;
                object.signaled = object.count != 0;
            },
            .thread, .generic => {},
            .timer => {
                // Satisfied because its due tick passed before any sweep
                // fired it: fire it here, then a synchronization timer is
                // consumed and a notification timer stays signalled.
                if (object.due_ticks != 0 and self.guest_clock.ticks >= object.due_ticks) self.advanceWindowsTimer(object, self.guest_clock.ticks);
                object.signaled = object.manual_reset;
            },
        }
    }

    fn wakeWindowsGuestThreadsForWait(self: *ElfState, handle: u64, wake_all: bool) u64 {
        var woken: u64 = 0;
        for (&self.windows_guest_threads) |*thread| {
            if (thread.status != .blocked or !thread.waitsOnHandle(handle)) continue;
            const recheck = thread.blocked_wait_handle_count != 0 and thread.blocked_wait_all;
            thread.status = .runnable;
            thread.blocked_wait_handle = 0;
            thread.blocked_wait_timeout = 0;
            thread.blocked_wait_deadline = 0;
            thread.blocked_srw_lock = 0;
            thread.blocked_condition = 0;
            thread.blocked_wait_handle_count = 0;
            thread.blocked_wait_all = false;
            thread.wait_resume = true;
            thread.wait_resume_handle = handle;
            thread.wait_resume_timeout = false;
            thread.wait_resume_recheck = recheck;
            self.windows_thread_unblocks +|= 1;
            self.windows_wait_unblocks +|= 1;
            // A wait-all waiter only looks again; it takes nothing with it,
            // so it is not a transfer the caller should account for.
            if (recheck) continue;
            woken +|= 1;
            if (!wake_all) break;
        }
        return woken;
    }

    /// Wake finite waits whose guest-clock deadline has elapsed.
    ///
    /// The deadline is in the same ticks Rosetta hands the guest from
    /// `QueryPerformanceCounter`, so a thread that sleeps for a millisecond
    /// and a thread that measures a millisecond agree. It is deliberately not
    /// the owner's step counter: that counter stops advancing whenever the
    /// scheduler is running workers, which is most of the run, so a deadline
    /// expressed in it stretches by however much other work the process is
    /// doing.
    fn wakeExpiredWindowsGuestWaits(self: *ElfState) u64 {
        // Refresh the clock here as well as in `step`. A deadline is only
        // reached because time passed, and with the clock read from the host
        // rather than counted from instructions there is a state where no
        // instruction runs: every worker parked on a deadline and the owner
        // in this service loop. The clock would then never advance, nothing
        // would ever wake, and a run that was merely asleep would look
        // deadlocked. Sampling at the point of the question removes the
        // possibility entirely.
        self.refreshWindowsGuestClock();
        var woken: u64 = 0;
        const now = self.guest_clock.ticks;
        // A timer that fires wins over a timeout falling due in the same sweep.
        woken +|= self.fireDueWindowsTimers(now);
        for (&self.windows_guest_threads, 0..) |*thread, slot| {
            if (thread.status != .blocked or thread.blocked_wait_deadline == 0 or
                now < thread.blocked_wait_deadline)
            {
                continue;
            }
            if (thread.blocked_condition != 0) {
                // A timed condition wait ran out. It resumes the way a
                // signalled waiter does, through its mutex, and returns
                // ETIMEDOUT instead of zero.
                self.noteWindowsTimedConditionTimeout(thread, slot, now);
                thread.status = .runnable;
                thread.blocked_condition = 0;
                thread.blocked_wait_deadline = 0;
                thread.condition_resume = true;
                thread.condition_resume_timeout = true;
                thread.wait_resume_timeout = false;
                self.windows_thread_unblocks +|= 1;
                self.windows_condition_timeouts +|= 1;
                woken +|= 1;
                continue;
            }
            const handle = thread.blocked_wait_handle;
            thread.status = .runnable;
            thread.blocked_wait_handle = 0;
            thread.blocked_wait_deadline = 0;
            thread.blocked_srw_lock = 0;
            thread.blocked_condition = 0;
            thread.blocked_condition_mutex = 0;
            thread.blocked_wait_handle_count = 0;
            thread.blocked_wait_all = false;
            thread.wait_resume_recheck = false;
            // A `Sleep` park has no wait object: it already returned to the
            // guest, so it resumes at the instruction after the call and must
            // not be handed a wait result it never asked for.
            thread.wait_resume = handle != 0;
            thread.wait_resume_handle = handle;
            thread.wait_resume_timeout = handle != 0;
            if (handle == 0) self.endWindowsWaitAccountingIfKind(thread, .deadline, .timed_out);
            self.windows_thread_unblocks +|= 1;
            self.windows_wait_unblocks +|= 1;
            woken +|= 1;
        }
        return woken;
    }

    /// Make a synthetic event/mutex/semaphore ready and release any workers
    /// parked on it.  The worker retains a one-shot resume marker so its next
    /// turn retries the original wait and receives WAIT_OBJECT_0 naturally.
    pub fn signalWindowsWaitObject(self: *ElfState, handle: u64, pulse: bool) u64 {
        const index = self.windowsWaitObjectIndex(handle) orelse return 0;
        const object = &self.windows_wait_objects[index];
        self.noteWindowsWaitSignal(handle);
        object.signaled = true;
        const woken = self.wakeWindowsGuestThreadsForWait(handle, object.manual_reset);
        if (object.kind == .semaphore and object.count == 0) object.count = 1;
        if (pulse or (object.kind == .event and !object.manual_reset and woken != 0)) object.signaled = false;
        if (self.trace_windows_waits) {
            self.windows_wait_signal_trace_events +|= 1;
            const event = self.windows_wait_signal_trace_events;
            if (event <= 8 or (event & (event - 1)) == 0) {
                log.info("PE64 wait object signaled: handle=0x{x} kind={s} pulse={} woken={d} signaled_after={} signal_rip=0x{x} active_thread=0x{x} step={d} event={d}", .{
                    handle,
                    @tagName(object.kind),
                    pulse,
                    woken,
                    object.signaled,
                    self.regs.rip,
                    self.active_guest_thread,
                    self.executed_steps,
                    event,
                });
            }
        }
        return woken;
    }

    pub fn resetWindowsWaitObject(self: *ElfState, handle: u64) bool {
        const index = self.windowsWaitObjectIndex(handle) orelse return false;
        const object = &self.windows_wait_objects[index];
        object.signaled = false;
        if (object.kind == .semaphore) object.count = 0;
        return true;
    }

    pub fn releaseWindowsSemaphore(self: *ElfState, handle: u64, release_count: u64) bool {
        const index = self.windowsWaitObjectIndex(handle) orelse return false;
        const object = &self.windows_wait_objects[index];
        if (object.kind != .semaphore or release_count == 0) return false;
        self.noteWindowsWaitSignal(handle);
        const maximum = if (object.maximum == 0) std.math.maxInt(u32) else object.maximum;
        const increment: u32 = @intCast(@min(release_count, std.math.maxInt(u32)));
        object.count = @min(maximum, object.count +| increment);
        // Each woken waiter takes one count with it. A resumed wait returns
        // WAIT_OBJECT_0 without consuming, so leaving the count behind let a
        // single release satisfy the waiter it woke and then the next caller
        // too - a semaphore that over-grants is a lock that admits two.
        while (object.count != 0) {
            if (self.wakeWindowsGuestThreadsForWait(handle, false) == 0) break;
            object.count -= 1;
        }
        object.signaled = object.count != 0;
        return true;
    }

    /// Apply Win32 wait semantics at the cooperative boundary.  A worker
    /// that waits on a known unsignaled object is parked at the import stub;
    /// it is resumed by the object's signal/completion instead of receiving a
    /// fabricated success and spinning through the same wait forever.
    pub fn waitWindowsGuestObject(self: *ElfState, handle: u64, timeout: u64) WindowsWaitResult {
        if (handle == 0) return .invalid;
        self.windows_wait_calls +|= 1;

        if (self.windows_active_guest_thread_slot) |index| {
            const thread = &self.windows_guest_threads[index];
            if (thread.wait_resume and thread.wait_resume_handle == handle) {
                const resumed_by_timeout = thread.wait_resume_timeout;
                const waited_timeout = thread.blocked_wait_timeout;
                thread.wait_resume = false;
                thread.wait_resume_handle = 0;
                thread.wait_resume_timeout = false;
                thread.blocked_wait_timeout = 0;
                self.windows_wait_resumes +|= 1;
                if (resumed_by_timeout) {
                    self.endWindowsHandleWaitAccounting(thread, .timed_out);
                    self.windows_wait_timeouts +|= 1;
                    self.traceWindowsWaitDecision(handle, waited_timeout, .timeout);
                    return .timeout;
                }
                self.endWindowsHandleWaitAccounting(thread, .signaled);
                return .signaled;
            }
        }

        const ready = self.windowsWaitObjectReady(handle) orelse {
            self.windows_wait_unknown_objects +|= 1;
            self.traceWindowsWaitDecision(handle, timeout, .unknown);
            return .unknown;
        };
        if (ready) {
            if (self.windows_main_wait_handle == handle) self.windows_main_wait_handle = 0;
            self.consumeWindowsWaitObject(handle);
            return .signaled;
        }
        if (timeout == 0) {
            self.windows_wait_timeouts +|= 1;
            self.traceWindowsWaitDecision(handle, timeout, .timeout);
            return .timeout;
        }

        if (self.windows_active_guest_thread_slot) |index| {
            const thread = &self.windows_guest_threads[index];
            if (thread.status != .running) return .invalid;
            if (self.windows_guest_wait_compatibility) {
                self.windows_wait_compatibility_yields +|= 1;
                self.traceWindowsWaitDecision(handle, timeout, .yielded);
                return .yielded;
            }
            thread.status = .blocked;
            thread.blocked_wait_handle = handle;
            thread.blocked_wait_timeout = timeout;
            thread.blocked_wait_handle_count = 0;
            thread.blocked_wait_all = false;
            // A Win32 timeout is in guest milliseconds, and Rosetta already
            // publishes a guest clock: one tick per interpreted instruction
            // at `WINDOWS_GUEST_CLOCK_HZ`. Convert through that, so the wait
            // and the guest's own `QueryPerformanceCounter` reading of it
            // measure the same millisecond.
            thread.blocked_wait_deadline = if (timeout == std.math.maxInt(u32))
                0
            else
                self.guest_clock.ticks +|
                    (@max(timeout, @as(u64, 1)) *| WINDOWS_GUEST_CLOCK_TICKS_PER_MILLISECOND);
            thread.blocked_srw_lock = 0;
            thread.blocked_condition = 0;
            thread.blocked_condition_mutex = 0;
            thread.condition_resume = false;
            thread.wait_resume_timeout = false;
            self.beginWindowsWaitAccounting(
                thread,
                handle,
                if (timeout == std.math.maxInt(u32)) .infinite_handle else .finite_handle,
                timeout,
                thread.blocked_wait_deadline,
            );
            self.windows_thread_blocks +|= 1;
            self.windows_wait_blocks +|= 1;
            self.traceWindowsWaitDecision(handle, timeout, .blocked);
            return .blocked;
        }

        // The owner is also Rosetta's UI-loop executor. A host-thread block
        // would strand the deferred UI callback that is supposed to signal
        // this event (Xenia's emulator_thread_event_ is the canonical case).
        // Give queued workers one bounded turn, then complete this boundary
        // as a cooperative yield. The next owner instruction re-enters the
        // wait naturally, while the outer loop remains able to pump the
        // message-only window and execute the callback that will eventually
        // signal the event. Parking the owner here prevents that callback
        // from ever running on the single Rosetta interpreter.
        const serviced = self.serviceWindowsGuestBoundary(self.windowsGuestWaitServiceSlice());
        self.windows_wait_last_owner_service_steps = serviced;
        if (serviced != 0) {
            self.windows_wait_owner_yields +|= 1;
        }

        self.traceWindowsWaitDecision(handle, timeout, .yielded);
        return .yielded;
    }

    /// `WaitForMultipleObjects` with Win32's semantics at the cooperative
    /// boundary.
    ///
    /// A wait-any takes the first ready object and answers its index; a
    /// wait-all takes every object at once or none. A worker with nothing
    /// ready parks on all its handles, and whichever is signalled first
    /// hands itself over as it wakes the thread, the way a single wait does.
    fn waitWindowsGuestObjects(self: *ElfState, handles: []const u64, wait_all: bool, timeout: u64) WindowsMultiWaitResult {
        if (handles.len == 0 or handles.len > WINDOWS_WAIT_MULTIPLE_CAPACITY) return .invalid;
        for (handles) |handle| {
            if (handle == 0) return .invalid;
        }
        self.windows_wait_multiple_calls +|= 1;
        self.windows_wait_calls +|= 1;

        if (self.windows_active_guest_thread_slot) |index| {
            const thread = &self.windows_guest_threads[index];
            if (thread.wait_resume) {
                if (std.mem.indexOfScalar(u64, handles, thread.wait_resume_handle)) |woken_index| {
                    const by_timeout = thread.wait_resume_timeout;
                    const recheck = thread.wait_resume_recheck;
                    thread.wait_resume = false;
                    thread.wait_resume_handle = 0;
                    thread.wait_resume_timeout = false;
                    thread.wait_resume_recheck = false;
                    thread.blocked_wait_timeout = 0;
                    self.windows_wait_resumes +|= 1;
                    if (by_timeout) {
                        self.endWindowsWaitAccountingIfKind(&self.windows_guest_threads[index], .multiple, .timed_out);
                        thread.multi_wait_deadline = 0;
                        self.windows_wait_timeouts +|= 1;
                        return .timeout;
                    }
                    if (!recheck) {
                        self.endWindowsWaitAccountingIfKind(&self.windows_guest_threads[index], .multiple, .signaled);
                        thread.multi_wait_deadline = 0;
                        return .{ .signaled = @intCast(woken_index) };
                    }
                    // A wait-all waiter looks again below, keeping its deadline.
                }
            }
        }

        if (self.takeReadyWindowsWaitObjects(handles, wait_all)) |result| {
            if (self.windows_active_guest_thread_slot) |index| {
                switch (result) {
                    .signaled => self.endWindowsWaitAccountingIfKind(&self.windows_guest_threads[index], .multiple, .signaled),
                    else => {},
                }
            }
            self.clearActiveMultiWaitDeadline();
            return result;
        }
        if (timeout == 0) {
            self.clearActiveMultiWaitDeadline();
            self.windows_wait_timeouts +|= 1;
            return .timeout;
        }

        if (self.windows_active_guest_thread_slot) |index| {
            const thread = &self.windows_guest_threads[index];
            if (thread.status != .running) return .invalid;
            const deadline = if (thread.multi_wait_deadline != 0)
                thread.multi_wait_deadline
            else if (timeout == std.math.maxInt(u32))
                0
            else
                self.guest_clock.ticks +| (@max(timeout, @as(u64, 1)) *| WINDOWS_GUEST_CLOCK_TICKS_PER_MILLISECOND);
            thread.status = .blocked;
            thread.blocked_wait_handle = handles[0];
            thread.blocked_wait_timeout = timeout;
            thread.blocked_wait_deadline = deadline;
            thread.multi_wait_deadline = deadline;
            @memcpy(thread.blocked_wait_handles[0..handles.len], handles);
            thread.blocked_wait_handle_count = @intCast(handles.len);
            thread.blocked_wait_all = wait_all;
            thread.blocked_srw_lock = 0;
            thread.blocked_condition = 0;
            thread.blocked_condition_mutex = 0;
            thread.condition_resume = false;
            thread.wait_resume_timeout = false;
            self.beginWindowsWaitAccounting(thread, handles[0], .multiple, timeout, deadline);
            self.windows_thread_blocks +|= 1;
            self.windows_wait_blocks +|= 1;
            self.windows_wait_multiple_blocks +|= 1;
            return .blocked;
        }

        // The owner cannot park (see `waitWindowsGuestObject`). Give workers
        // a turn, then look again: that turn may have signalled one.
        const serviced = self.serviceWindowsGuestBoundary(self.windowsGuestWaitServiceSlice());
        if (serviced != 0) self.windows_wait_owner_yields +|= 1;
        if (self.takeReadyWindowsWaitObjects(handles, wait_all)) |result| return result;
        if (timeout != std.math.maxInt(u32)) {
            self.windows_wait_timeouts +|= 1;
            return .timeout;
        }
        self.windows_wait_multiple_owner_yields +|= 1;
        return .yielded;
    }

    /// Take the objects a multi-object wait is satisfied by, or null.
    fn takeReadyWindowsWaitObjects(self: *ElfState, handles: []const u64, wait_all: bool) ?WindowsMultiWaitResult {
        var first_ready: ?usize = null;
        var all_ready = true;
        for (handles, 0..) |handle, handle_index| {
            const ready = self.windowsWaitObjectReady(handle) orelse {
                self.windows_wait_unknown_objects +|= 1;
                return .{ .unknown = handle };
            };
            if (ready) {
                if (first_ready == null) first_ready = handle_index;
            } else {
                all_ready = false;
            }
        }
        if (wait_all) {
            if (!all_ready) return null;
            for (handles) |handle| self.consumeWindowsWaitObject(handle);
            return .{ .signaled = 0 };
        }
        const found = first_ready orelse return null;
        self.consumeWindowsWaitObject(handles[found]);
        return .{ .signaled = @intCast(found) };
    }

    fn clearActiveMultiWaitDeadline(self: *ElfState) void {
        if (self.windows_active_guest_thread_slot) |slot| self.windows_guest_threads[slot].multi_wait_deadline = 0;
    }

    /// A wait on a handle with no event, mutex, semaphore or thread behind it.
    ///
    /// Any answer is invented: WAIT_OBJECT_0 claims an object was acquired
    /// that does not exist, and WAIT_TIMEOUT claims time passed for nothing.
    pub fn faultWindowsWaitUnknownHandle(self: *ElfState, handle: u64, api: []const u8) void {
        self.windows_wait_unknown_faults +|= 1;
        const occurrence = self.windows_wait_unknown_faults;
        if (occurrence == 1) self.windows_fatal_point_events +|= 1;
        if (comptime !@import("builtin").is_test) {
            if (shouldReportWindowsPointOccurrence(occurrence)) {
                var caller_text: [guest_symbol_text_bytes]u8 = undefined;
                const slot_plus_one: u8 = if (self.windows_active_guest_thread_slot) |slot| @intCast(@min(slot + 1, 255)) else 0;
                log.err("PE64 FATAL POINT: guest-condition label=wait-unknown-handle owner=rosette:wait-model occurrence={d} api={s} handle=0x{x} step={d} caller={s} thread={s}; Rosette has no event, mutex, semaphore or thread behind this handle, so any wait result it returned would be invented. Find the call that created the handle and give that object a wait model", .{
                    occurrence,
                    api,
                    handle,
                    self.executed_steps,
                    self.describeGuestAddressOrUnnamed(self.last_instruction_rip, &caller_text),
                    self.guestThreadLabel(slot_plus_one),
                });
            }
        }
        self.terminateForWindowsFatalPoint("wait-unknown-handle");
    }

    /// The site a timed wait comes from, by the address it returns to, plus
    /// one; zero when the table is full.
    fn noteWindowsTimedWaitSite(self: *ElfState, caller: u64, slot: usize, milliseconds: u64) u8 {
        for (self.windows_timed_wait_sites[0..self.windows_timed_wait_site_count], 0..) |*site, index| {
            if (site.caller != caller) continue;
            site.waits +|= 1;
            site.last_milliseconds = milliseconds;
            return @intCast(index + 1);
        }
        if (self.windows_timed_wait_site_count == self.windows_timed_wait_sites.len) {
            self.windows_timed_wait_site_overflow +|= 1;
            return 0;
        }
        const index = self.windows_timed_wait_site_count;
        self.windows_timed_wait_sites[index] = .{
            .caller = caller,
            .first_thread_slot_plus_one = @intCast(@min(slot + 1, 255)),
            .waits = 1,
            .last_milliseconds = milliseconds,
        };
        self.windows_timed_wait_site_count += 1;
        return @intCast(index + 1);
    }

    const TimedWaitOutcome = enum { timeout, signalled, immediate };

    fn countWindowsTimedWaitOutcome(self: *ElfState, site: u8, outcome: TimedWaitOutcome) void {
        if (site == 0 or site > self.windows_timed_wait_site_count) return;
        const record = &self.windows_timed_wait_sites[site - 1];
        switch (outcome) {
            .timeout => record.timeouts +|= 1,
            .signalled => record.signalled +|= 1,
            .immediate => record.immediate +|= 1,
        }
    }

    /// Keep the last concrete wait identity beside the site aggregate. The
    /// first ten expiry records already carry this information, but retaining
    /// it here makes the final site line actionable even when the run is too
    /// long for a reader to scroll back to those samples.
    fn rememberWindowsTimedWaitContext(
        self: *ElfState,
        site: u8,
        slot: usize,
        condition: u64,
        mutex: u64,
    ) void {
        if (site == 0 or site > self.windows_timed_wait_site_count) return;
        const record = &self.windows_timed_wait_sites[site - 1];
        record.last_condition = condition;
        record.last_mutex = mutex;
        record.last_thread_handle = self.windows_guest_threads[slot].handle;
        record.last_thread_id = self.windows_guest_threads[slot].thread_id;
    }

    /// Emit the first ten deadline expiries with enough context to identify
    /// the waiter, not merely the fact that a periodic wait happened. The
    /// aggregate counters remain unbounded; only this detailed sample is
    /// bounded so a 500 ms poll cannot dominate a long Xenia run's log.
    fn noteWindowsTimedConditionTimeout(self: *ElfState, thread: *const WindowsGuestThread, slot: usize, now: u64) void {
        if (self.windows_condition_timeout_samples >= WINDOWS_TIMED_CONDITION_TIMEOUT_SAMPLE_LIMIT) return;
        self.windows_condition_timeout_samples += 1;
        if (comptime @import("builtin").is_test) return;

        const site = thread.timed_wait_site;
        const site_index: ?usize = if (site != 0 and @as(usize, site) <= self.windows_timed_wait_site_count)
            @as(usize, site) - 1
        else
            null;
        const caller_address = if (site_index) |index| self.windows_timed_wait_sites[index].caller else 0;
        var caller_text: [guest_symbol_text_bytes]u8 = undefined;
        var rip_text: [guest_symbol_text_bytes]u8 = undefined;
        const caller = if (caller_address == 0)
            if (site == 0) "<site-table-full>" else "<unknown>"
        else
            self.describeGuestAddressOrUnnamed(caller_address, &caller_text);
        const rip = if (thread.context.last_instruction_rip != 0)
            thread.context.last_instruction_rip
        else
            thread.context.regs.rip;
        const thread_name = if (thread.name_len != 0) thread.nameText() else "<unnamed>";
        const last_import = if (thread.last_import_len != 0) thread.lastImportText() else "<none>";
        log.info("PE64 TIMED WAIT TIMEOUT SAMPLE: sample={d}/{d} slot={d} caller={s} thread={s} handle=0x{x} thread_id={d} condition=0x{x} mutex=0x{x} timeout_ms={d} deadline_ticks={d} now_ticks={d} overdue_ticks={d} rip=0x{x} at={s} last_import={s} last_import_step={d} owner_step={d} wait_model=guest_clock_deadline safe_action=return_ETIMEDOUT synthetic_signal=0", .{
            self.windows_condition_timeout_samples,
            WINDOWS_TIMED_CONDITION_TIMEOUT_SAMPLE_LIMIT,
            slot,
            caller,
            thread_name,
            thread.handle,
            thread.thread_id,
            thread.blocked_condition,
            thread.blocked_condition_mutex,
            thread.timed_wait_milliseconds,
            thread.blocked_wait_deadline,
            now,
            now -| thread.blocked_wait_deadline,
            rip,
            self.describeGuestAddressOrUnnamed(rip, &rip_text),
            last_import,
            thread.last_import_step,
            self.executed_steps,
        });
    }

    /// Where timed condition waits come from and how they end, busiest first
    /// up to `limit` sites.
    fn reportWindowsTimedWaitSites(self: *const ElfState, limit: usize) void {
        if (self.windows_timed_wait_site_count == 0) return;
        var timeouts: u64 = 0;
        for (self.windows_timed_wait_sites[0..self.windows_timed_wait_site_count]) |site| timeouts +|= site.timeouts;
        log.info("PE64 TIMED WAIT SITES: {d} site(s), {d} timed condition wait(s), {d} timed out, first_timeout_samples={d}/{d}, suppressed={d}; inspect each site's classification and action: timeout-dominant short waits are polling candidates, while unsignalled long waits need a lost-wakeup investigation", .{
            self.windows_timed_wait_site_count,
            self.windows_condition_timed_waits,
            timeouts,
            self.windows_condition_timeout_samples,
            WINDOWS_TIMED_CONDITION_TIMEOUT_SAMPLE_LIMIT,
            self.windows_condition_timeouts -| @as(u64, self.windows_condition_timeout_samples),
        });
        var printed = [_]bool{false} ** WINDOWS_TIMED_WAIT_SITE_CAPACITY;
        var shown: usize = 0;
        while (shown < @min(limit, self.windows_timed_wait_site_count)) : (shown += 1) {
            var best: ?usize = null;
            for (self.windows_timed_wait_sites[0..self.windows_timed_wait_site_count], 0..) |site, index| {
                if (printed[index]) continue;
                if (best == null or site.waits > self.windows_timed_wait_sites[best.?].waits) best = index;
            }
            const index = best orelse break;
            printed[index] = true;
            const site = self.windows_timed_wait_sites[index];
            const classification = classifyWindowsTimedWaitSite(site);
            var caller_text: [guest_symbol_text_bytes]u8 = undefined;
            log.info("PE64 TIMED WAIT SITES:   caller={s} thread={s} waits={d} timeouts={d} ({d}%) signalled={d} already_past={d} last_timeout_ms={d} condition=0x{x} mutex=0x{x} last_handle=0x{x} last_thread_id={d} classification={s} action={s}{s}", .{
                self.describeGuestAddressOrUnnamed(site.caller, &caller_text),
                self.guestThreadLabel(site.first_thread_slot_plus_one),
                site.waits,
                site.timeouts,
                windowsTimedWaitPercent(site.timeouts, site.waits),
                site.signalled,
                site.immediate,
                site.last_milliseconds,
                site.last_condition,
                site.last_mutex,
                site.last_thread_handle,
                site.last_thread_id,
                classification.label(),
                classification.action(),
                if (site.waits != 0 and site.timeouts == site.waits) " every-wait-timed-out" else "",
            });
        }
        if (self.windows_timed_wait_site_overflow != 0) {
            log.info("PE64 TIMED WAIT SITES:   {d} wait(s) came from sites past the table's {d}", .{ self.windows_timed_wait_site_overflow, self.windows_timed_wait_sites.len });
        }
    }

    /// Publish MinGW's `pthread_cond_timedwait_impl`: the body that both
    /// `pthread_cond_timedwait` and `pthread_cond_timedwait_relative_np`
    /// tail-jump into, with a fourth argument saying which of them it is.
    pub fn configureWindowsTimedConditionEntry(self: *ElfState, entry: ?u64) void {
        self.windows_pthread_cond_timedwait_entry = entry;
        if (entry) |address| {
            log.info("PE64 guest synchronization hooks: pthread_cond_timedwait_impl=0x{x} source=executable-signature; timed condition waits park on the guest clock and the signal and broadcast hooks wake them", .{address});
        }
    }

    /// The milliseconds a winpthreads timed wait asks for, computed as the
    /// image computes them: seconds times 1000 plus the nanoseconds rounded
    /// up, and for an absolute time, less the wall clock the guest reads
    /// through GetSystemTimeAsFileTime. A time already past is zero. Null
    /// for an unreadable timespec, which is left to the image's own code.
    pub fn windowsPthreadTimespecMilliseconds(self: *const ElfState, timespec: u64, relative: bool) ?u64 {
        const bytes = self.guestMemoryConst(timespec, 12) orelse return null;
        const seconds = std.mem.readInt(u64, bytes[0..8], .little);
        const nanoseconds: i32 = @bitCast(std.mem.readInt(u32, bytes[8..12], .little));
        // `addl $0xf423f, %eax; cltq; divq`: a 32-bit add, sign-extended,
        // divided unsigned.
        const rounded: u64 = @bitCast(@as(i64, nanoseconds +% 999_999));
        const requested = (seconds *% 1000) +% (rounded / 1_000_000);
        if (relative) return requested;
        const now = (self.windowsGuestFileTime() -% WINDOWS_FILETIME_UNIX_EPOCH) / 10_000;
        return if (requested >= now) requested - now else 0;
    }

    /// `pthread_cond_timedwait` on Rosette's condition model.
    ///
    /// Untimed waits, signals and broadcasts were already Rosette's; timed
    /// waits ran the image's own semaphore code, which no Rosette signal ever
    /// reaches. A notified timed waiter slept out its whole timeout, and that
    /// semaphore and cancel-event path is where discord-rpc's IO thread spent
    /// 27% of the 2026-09-14 run.
    fn shimWindowsPthreadTimedCondition(self: *ElfState, return_rip: ?u64) bool {
        const slot = self.windows_active_guest_thread_slot orelse return false;
        const condition = self.regs.rcx;
        const mutex = self.regs.rdx;
        if (condition == 0 or mutex == 0) return false;
        var deadline: u64 = 0;
        if (!self.windows_guest_threads[slot].condition_resume) {
            const relative = (self.regs.r9 & 0xFFFF_FFFF) != 0;
            const milliseconds = self.windowsPthreadTimespecMilliseconds(self.regs.r8, relative) orelse return false;
            self.windows_condition_timed_waits +|= 1;
            const site = self.noteWindowsTimedWaitSite(return_rip orelse self.read64(self.regs.rsp), slot, milliseconds);
            self.windows_guest_threads[slot].timed_wait_site = site;
            self.windows_guest_threads[slot].timed_wait_milliseconds = milliseconds;
            self.rememberWindowsTimedWaitContext(site, slot, condition, mutex);
            if (milliseconds == 0) {
                // Already past: ETIMEDOUT with the mutex still held, as the
                // image returns it, and the rest of the slice to someone else.
                self.windows_condition_timed_immediate +|= 1;
                self.countWindowsTimedWaitOutcome(site, .immediate);
                self.windows_condition_hook_events +|= 1;
                self.regs.rax = WINDOWS_PTHREAD_ETIMEDOUT;
                self.completeWindowsPthreadConditionReturn(return_rip);
                self.requestWindowsGuestSliceYield();
                return true;
            }
            // The image treats more than 0xFFFFFFFE milliseconds as INFINITE.
            if (milliseconds <= 0xFFFF_FFFE) {
                deadline = self.guest_clock.ticks +| (milliseconds *| WINDOWS_GUEST_CLOCK_TICKS_PER_MILLISECOND);
            }
        }
        switch (self.waitWindowsGuestConditionUntil(condition, mutex, deadline)) {
            .invalid => return false,
            .blocked => {
                self.windows_condition_hook_events +|= 1;
                return true;
            },
            .resumed => {
                self.windows_condition_hook_events +|= 1;
                const timed_out = self.windows_guest_threads[slot].condition_resume_timeout;
                self.windows_guest_threads[slot].condition_resume_timeout = false;
                self.countWindowsTimedWaitOutcome(self.windows_guest_threads[slot].timed_wait_site, if (timed_out) .timeout else .signalled);
                self.regs.rax = if (timed_out) WINDOWS_PTHREAD_ETIMEDOUT else 0;
                self.completeWindowsPthreadConditionReturn(return_rip);
                return true;
            },
        }
    }

    /// Publish the PE-local pthread condition-variable entry points that the
    /// loader found in executable bytes.  Keeping discovery in the PE intake
    /// and policy in the executor means a rebuilt Xenia image can move these
    /// routines without requiring a Rosetta or Xenia address edit.
    pub fn configureWindowsConditionEntries(
        self: *ElfState,
        wait_entry: ?u64,
        signal_entry: ?u64,
        broadcast_entry: ?u64,
    ) void {
        self.windows_pthread_cond_wait_entry = wait_entry;
        self.windows_pthread_cond_signal_entry = signal_entry;
        self.windows_pthread_cond_broadcast_entry = broadcast_entry;
        if (wait_entry != null or signal_entry != null or broadcast_entry != null) {
            log.info("PE64 guest synchronization hooks: pthread_cond_wait=0x{x} pthread_cond_signal=0x{x} pthread_cond_broadcast=0x{x} source=executable-signature", .{
                wait_entry orelse 0,
                signal_entry orelse 0,
                broadcast_entry orelse 0,
            });
        }
    }

    /// Complete the PE-local MinGW pthread condition functions at their
    /// executable entry points when the cooperative policy is enabled.
    ///
    /// Xenia links these routines into the image instead of importing them,
    /// so the ordinary import dispatcher never sees the wait. Returning
    /// success from the underlying Win32 wait is not equivalent here: the
    /// caller is commonly a predicate loop that assumes the condition wait
    /// only returned after a matching signal. In particular, KernelState's
    /// dispatch worker would otherwise wake on an empty queue and invoke the
    /// list sentinel as a std::function.
    ///
    /// The call boundary deliberately remains at the caller's RIP while a
    /// worker is blocked. The worker context is therefore resumed at the
    /// same direct call, observes the one-shot condition-resume marker, and
    /// this shim completes the call without entering the image's
    /// host-oriented semaphore implementation.
    fn completeWindowsPthreadConditionReturn(self: *ElfState, return_rip: ?u64) void {
        self.regs.rip = return_rip orelse self.readMemVal(self.regs.rsp, .bits64);
        // A tail-jump into the pthread routine inherits the caller's return
        // slot.  Since the shim returns directly to that caller, consume the
        // slot exactly as a real `ret` would.  Direct call sites are
        // intercepted before the executor pushes their return address and
        // must leave RSP unchanged.
        if (return_rip == null) self.regs.rsp +|= 8;
    }

    fn tryWindowsPthreadConditionShim(self: *ElfState, target: u64, return_rip: ?u64) bool {
        if (!self.windows_runtime_enabled or !self.windows_pthread_cond_native) return false;

        if (self.windows_pthread_cond_timedwait_entry) |timed_entry| {
            if (target == timed_entry) return self.shimWindowsPthreadTimedCondition(return_rip);
        }

        if (self.windows_pthread_cond_wait_entry) |wait_entry| {
            if (target == wait_entry) {
                const result = self.waitWindowsGuestCondition(self.regs.rcx, self.regs.rdx);
                switch (result) {
                    .invalid => return false,
                    .blocked => {
                        self.windows_condition_hook_events +|= 1;
                        if (self.trace_windows_conditions) {
                            log.info("PE64 guest condition shim: wait blocked cond=0x{x} mutex=0x{x} thread=0x{x} step={d}", .{
                                self.regs.rcx,
                                self.regs.rdx,
                                self.active_guest_thread,
                                self.executed_steps,
                            });
                        }
                        return true;
                    },
                    .resumed => {
                        self.windows_condition_hook_events +|= 1;
                        self.regs.rax = 0;
                        self.completeWindowsPthreadConditionReturn(return_rip);
                        if (self.trace_windows_conditions) {
                            log.info("PE64 guest condition shim: wait resumed cond=0x{x} mutex=0x{x} thread=0x{x} step={d}", .{
                                self.regs.rcx,
                                self.regs.rdx,
                                self.active_guest_thread,
                                self.executed_steps,
                            });
                        }
                        return true;
                    },
                }
            }
        }

        if (self.windows_pthread_cond_signal_entry) |signal_entry| {
            if (target == signal_entry) {
                const woken = self.signalWindowsGuestCondition(self.regs.rcx, false);
                self.windows_condition_hook_events +|= 1;
                self.regs.rax = 0;
                self.completeWindowsPthreadConditionReturn(return_rip);
                if (self.trace_windows_conditions) {
                    log.info("PE64 guest condition shim: signal cond=0x{x} woken={d} thread=0x{x} step={d}", .{
                        self.regs.rcx,
                        woken,
                        self.active_guest_thread,
                        self.executed_steps,
                    });
                }
                return true;
            }
        }

        if (self.windows_pthread_cond_broadcast_entry) |broadcast_entry| {
            if (target == broadcast_entry) {
                const woken = self.signalWindowsGuestCondition(self.regs.rcx, true);
                self.windows_condition_hook_events +|= 1;
                self.regs.rax = 0;
                self.completeWindowsPthreadConditionReturn(return_rip);
                if (self.trace_windows_conditions) {
                    log.info("PE64 guest condition shim: broadcast cond=0x{x} woken={d} thread=0x{x} step={d}", .{
                        self.regs.rcx,
                        woken,
                        self.active_guest_thread,
                        self.executed_steps,
                    });
                }
                return true;
            }
        }

        return false;
    }

    /// Initialize the Rosetta-side ownership record and the guest SRW word.
    /// The guest word remains present because Xenia also uses the native
    /// layout as a cheap state check around its recursive mutex wrapper.
    pub fn initializeWindowsSrwLock(self: *ElfState, address: u64) bool {
        const lock = self.ensureWindowsSrwLock(address) orelse return false;
        lock.owner_thread_id = 0;
        self.write64(address, 0);
        self.wakeWindowsGuestThreadsForSrwLock(address);
        return true;
    }

    /// Acquire an SRW lock without pretending that a void-returning Win32
    /// API is always immediately successful.  A contended result is handled
    /// by the import layer: worker contexts block and the owner continues.
    pub fn acquireWindowsSrwLock(self: *ElfState, address: u64) WindowsSrwAcquireResult {
        const lock = self.ensureWindowsSrwLock(address) orelse return .invalid;
        const thread_id = self.currentWindowsThreadId();
        if (lock.owner_thread_id == thread_id) {
            // Either a handoff this thread is now collecting, or the owner
            // context finishing a wait it queued for.
            if (self.windows_active_guest_thread_slot == null) lock.owner_waiting = false;
            self.endActiveWindowsSrwWaitAccounting();
            return .acquired;
        }
        if (lock.owner_thread_id != 0 or self.read64(address) != 0) {
            self.windows_srw_lock_contentions +|= 1;
            lock.contentions +|= 1;
            if (self.windows_guest_wait_compatibility) {
                // Xenia's startup worker uses this lock boundary as a
                // cooperative scheduling point. Keep Rosetta moving while
                // retaining one authoritative owner record for the worker
                // that proceeds; ReleaseSRWLockExclusive accepts the same
                // policy below if the image-side owner was not observable.
                lock.owner_thread_id = thread_id;
                self.write64(address, 1);
                self.windows_srw_compatibility_acquires +|= 1;
                self.endActiveWindowsSrwWaitAccounting();
                return .acquired;
            }
            return .contended;
        }
        lock.owner_thread_id = thread_id;
        self.write64(address, 1);
        if (self.windows_active_guest_thread_slot == null) lock.owner_waiting = false;
        self.endActiveWindowsSrwWaitAccounting();
        return .acquired;
    }

    /// Queue the owner context behind an SRW lock it could not take.
    pub fn noteWindowsOwnerSrwWait(self: *ElfState, address: u64) void {
        if (self.windows_active_guest_thread_slot != null) return;
        const index = self.windowsSrwLockIndex(address) orelse return;
        const lock = &self.windows_srw_locks[index];
        if (lock.owner_waiting) return;
        self.windows_srw_wait_sequence +|= 1;
        lock.owner_waiting = true;
        lock.owner_wait_sequence = self.windows_srw_wait_sequence;
    }

    /// Give a released SRW lock directly to its longest waiter.
    ///
    /// Waking every waiter and letting them race is fair on a preemptive
    /// scheduler and starvation on this one. On the 2026-09-13 run Xenia's
    /// global mutex took 235,910 contentions: one thread held it in
    /// `EntryTable::GetOrCreate`'s "entry still compiling" loop - unlock,
    /// yield, relock - while the thread doing that compile waited for the
    /// same lock. Each release woke the compiler, and the looping thread
    /// relocked before the compiler was ever scheduled. The title's main
    /// thread was waiting on the compiler, so the whole title stopped.
    ///
    /// Ownership is assigned here, before anyone runs. The waiter retries
    /// `AcquireSRWLockExclusive` at its own call site, finds itself the
    /// owner, and proceeds; the thread that released it finds the lock taken
    /// and blocks behind it. That is the order Windows produces when the
    /// released thread really yields.
    fn handOffWindowsSrwLock(self: *ElfState, lock: *WindowsSrwLock, address: u64) void {
        self.noteWindowsWaitSignal(address);
        var chosen: ?usize = null;
        var chosen_sequence: u64 = std.math.maxInt(u64);
        for (&self.windows_guest_threads, 0..) |*thread, index| {
            if (thread.status != .blocked or thread.blocked_srw_lock != address) continue;
            if (thread.thread_id == 0) {
                // No identity to hand ownership to. Wake it to race, which
                // is what every waiter did before.
                thread.status = .runnable;
                thread.blocked_srw_lock = 0;
                self.windows_thread_unblocks +|= 1;
                continue;
            }
            if (thread.srw_wait_sequence < chosen_sequence) {
                chosen = index;
                chosen_sequence = thread.srw_wait_sequence;
            }
        }
        const address_is_guest = self.guestMemory(address, 8) != null;
        if (lock.owner_waiting and lock.owner_wait_sequence < chosen_sequence) {
            lock.owner_thread_id = 1;
            if (address_is_guest) self.write64(address, 1);
            lock.handoffs +|= 1;
            self.windows_srw_handoffs +|= 1;
            return;
        }
        if (chosen) |index| {
            const thread = &self.windows_guest_threads[index];
            lock.owner_thread_id = thread.thread_id;
            if (address_is_guest) self.write64(address, 1);
            thread.status = .runnable;
            thread.blocked_srw_lock = 0;
            thread.blocked_wait_handle = 0;
            thread.blocked_wait_timeout = 0;
            thread.blocked_wait_deadline = 0;
            thread.wait_resume_timeout = false;
            thread.srw_wait_sequence = 0;
            lock.handoffs +|= 1;
            self.windows_srw_handoffs +|= 1;
            self.windows_thread_unblocks +|= 1;
            // Run the new owner next. It holds the lock from this instant,
            // and every other contender now waits on a thread the circular
            // scan might not reach for a whole rotation. On the 2026-09-13
            // run Xenia's global mutex changed hands 67,362 times and four
            // threads sat queued on it at exit: a short critical section
            // turned into a convoy that every kernel call joined.
            self.windows_preferred_next_guest_thread = index;
            self.windows_srw_directed_handoffs +|= 1;
            self.requestWindowsGuestSliceYield();
            return;
        }
        lock.owner_thread_id = 0;
        if (address_is_guest) self.write64(address, 0);
    }

    /// Who holds an SRW lock, in words a report can print.
    fn describeWindowsSrwOwner(self: *const ElfState, owner_thread_id: u64, buffer: []u8) []const u8 {
        if (owner_thread_id == 0) return "none";
        if (owner_thread_id == 1) return "owner-context (the process's initial thread)";
        for (&self.windows_guest_threads) |*thread| {
            if (thread.status == .vacant or thread.thread_id != owner_thread_id) continue;
            return std.fmt.bufPrint(buffer, "'{s}' {s}", .{
                if (thread.name_len != 0) thread.nameText() else "<unnamed by the guest>",
                @tagName(thread.status),
            }) catch "a thread whose name did not fit";
        }
        return "a thread id no live record carries";
    }

    fn windowsSrwWaiterCount(self: *const ElfState, lock: WindowsSrwLock) u32 {
        var waiters: u32 = @intFromBool(lock.owner_waiting);
        for (self.windows_guest_threads) |thread| {
            if (thread.status == .blocked and thread.blocked_srw_lock == lock.address) waiters += 1;
        }
        return waiters;
    }

    /// Release the owner record before waking blocked workers.  Xenia's
    /// xe_global_mutex clears its recursive owner word immediately before
    /// calling ReleaseSRWLockExclusive, so the SRW record is the authority
    /// that prevents a different worker from entering during the handoff.
    pub fn releaseWindowsSrwLock(self: *ElfState, address: u64) void {
        const thread_id = self.currentWindowsThreadId();
        if (self.windowsSrwLockIndex(address)) |index| {
            const lock = &self.windows_srw_locks[index];
            if (lock.owner_thread_id == 0 or lock.owner_thread_id == thread_id or self.windows_guest_wait_compatibility) {
                self.handOffWindowsSrwLock(lock, address);
            } else {
                self.windows_srw_lock_release_mismatches +|= 1;
            }
            return;
        }
        // A lock can be released after an image-side zeroing operation that
        // Rosetta did not observe. Keep the guest word recoverable, but do
        // not manufacture an ownership record for it.
        if (self.guestMemory(address, 8) != null) {
            self.write64(address, 0);
            self.wakeWindowsGuestThreadsForSrwLock(address);
        }
    }

    /// Mark the active worker as waiting for an SRW lock.  The import handler
    /// leaves RIP at the call site, so waking the context retries the acquire
    /// naturally; no synthetic return or guest stack mutation is needed.
    pub fn blockWindowsGuestThreadOnSrwLock(self: *ElfState, address: u64) bool {
        const index = self.windows_active_guest_thread_slot orelse return false;
        const thread = &self.windows_guest_threads[index];
        if (thread.status != .running) return false;
        thread.status = .blocked;
        thread.blocked_srw_lock = address;
        self.windows_srw_wait_sequence +|= 1;
        thread.srw_wait_sequence = self.windows_srw_wait_sequence;
        thread.blocked_condition = 0;
        thread.blocked_condition_mutex = 0;
        thread.blocked_wait_handle = 0;
        thread.blocked_wait_timeout = 0;
        thread.blocked_wait_deadline = 0;
        thread.wait_resume = false;
        thread.wait_resume_handle = 0;
        thread.wait_resume_timeout = false;
        self.beginWindowsWaitAccounting(thread, address, .srw_lock, 0, 0);
        self.windows_thread_blocks +|= 1;
        if (self.trace_windows_threads and
            (self.windows_thread_blocks <= 8 or self.windows_thread_blocks % 1024 == 0))
        {
            log.info("Windows guest worker blocked on SRW lock: handle=0x{x} thread_id={d} lock=0x{x} rip=0x{x} blocks={d}", .{
                thread.handle,
                thread.thread_id,
                address,
                self.regs.rip,
                self.windows_thread_blocks,
            });
        }
        return true;
    }

    /// Park a worker at pthread_cond_wait until the matching signal or
    /// broadcast arrives.  Returning success immediately is not a harmless
    /// degraded import here: libstdc++ assumes that a condition wait only
    /// returns after its predicate may have changed, and Xenia consequently
    /// dereferences its condition-variable list sentinel as a callback.
    pub fn waitWindowsGuestCondition(self: *ElfState, address: u64, mutex_address: u64) WindowsConditionWaitResult {
        return self.waitWindowsGuestConditionUntil(address, mutex_address, 0);
    }

    /// A condition wait that also ends when the guest clock reaches
    /// `deadline`, in guest ticks; zero waits for a signal alone. However it
    /// ends, the waiter retakes its mutex before it returns, and which way it
    /// ended is left in `condition_resume_timeout`.
    pub fn waitWindowsGuestConditionUntil(self: *ElfState, address: u64, mutex_address: u64, deadline: u64) WindowsConditionWaitResult {
        const index = self.windows_active_guest_thread_slot orelse return .invalid;
        if (address == 0 or self.windows_guest_threads[index].status != .running) return .invalid;
        self.windows_condition_wait_calls +|= 1;

        if (self.windows_guest_threads[index].condition_resume) {
            const mutex = self.windows_guest_threads[index].blocked_condition_mutex;
            if (mutex == 0) {
                const timed_out = self.windows_guest_threads[index].condition_resume_timeout;
                self.windows_guest_threads[index].condition_resume = false;
                self.windows_condition_wait_resumes +|= 1;
                self.endWindowsWaitAccounting(
                    &self.windows_guest_threads[index],
                    if (timed_out) .timed_out else .signaled,
                );
                return .resumed;
            }

            switch (self.acquireWindowsGuestPthreadMutex(mutex)) {
                .acquired => {
                    const timed_out = self.windows_guest_threads[index].condition_resume_timeout;
                    self.windows_guest_threads[index].condition_resume = false;
                    self.windows_guest_threads[index].blocked_condition_mutex = 0;
                    self.windows_guest_threads[index].wait_resume = false;
                    self.windows_guest_threads[index].wait_resume_handle = 0;
                    self.windows_condition_wait_resumes +|= 1;
                    self.windows_condition_mutex_reacquires +|= 1;
                    self.endWindowsWaitAccounting(
                        &self.windows_guest_threads[index],
                        if (timed_out) .timed_out else .signaled,
                    );
                    return .resumed;
                },
                .invalid => {
                    self.windows_condition_mutex_release_failures +|= 1;
                    return .invalid;
                },
                .contended => |wait_handle| {
                    // A mutex release may have woken this worker between the
                    // condition notification and this retry.  Consume that
                    // one-shot marker before testing the mutex again; if it
                    // is still contended below, the next SetEvent will arm a
                    // fresh marker.
                    if (self.windows_guest_threads[index].wait_resume and
                        self.windows_guest_threads[index].wait_resume_handle == wait_handle)
                    {
                        self.windows_guest_threads[index].wait_resume = false;
                        self.windows_guest_threads[index].wait_resume_handle = 0;
                    }
                    self.windows_guest_threads[index].status = .blocked;
                    self.windows_guest_threads[index].blocked_srw_lock = 0;
                    self.windows_guest_threads[index].blocked_condition = 0;
                    self.windows_guest_threads[index].blocked_wait_handle = wait_handle;
                    self.windows_guest_threads[index].blocked_wait_timeout = 0;
                    self.windows_guest_threads[index].blocked_wait_deadline = 0;
                    self.windows_guest_threads[index].wait_resume_timeout = false;
                    self.windows_thread_blocks +|= 1;
                    self.windows_condition_mutex_reacquire_blocks +|= 1;
                    return .blocked;
                },
            }
        }

        // POSIX condition waits release their mutex as part of entering the
        // wait.  The old Rosetta hook only recorded the condition address,
        // leaving the MinGW mutex in the acquired state and making the owner
        // thread's later pthread_mutex_lock wait forever on its event.
        switch (self.releaseWindowsGuestPthreadMutex(mutex_address)) {
            .invalid => {
                self.windows_condition_mutex_release_failures +|= 1;
                return .invalid;
            },
            .released, .already_unlocked => {
                self.windows_condition_mutex_releases +|= 1;
            },
        }

        const thread = &self.windows_guest_threads[index];
        thread.status = .blocked;
        thread.blocked_srw_lock = 0;
        thread.blocked_condition = address;
        thread.blocked_condition_mutex = mutex_address;
        thread.blocked_wait_handle = 0;
        thread.blocked_wait_timeout = 0;
        thread.blocked_wait_deadline = deadline;
        thread.condition_resume_timeout = false;
        thread.wait_resume = false;
        thread.wait_resume_handle = 0;
        thread.wait_resume_timeout = false;
        self.beginWindowsWaitAccounting(
            thread,
            address,
            if (deadline != 0) .timed_condition else .condition,
            if (deadline == 0) 0 else thread.timed_wait_milliseconds,
            deadline,
        );
        self.windows_thread_blocks +|= 1;
        self.windows_condition_wait_blocks +|= 1;
        if (self.trace_windows_threads and
            (self.windows_thread_blocks <= 8 or self.windows_thread_blocks % 1024 == 0))
        {
            log.info("Windows guest worker blocked on condition variable: handle=0x{x} thread_id={d} condition=0x{x} mutex=0x{x} rip=0x{x} blocks={d}", .{
                thread.handle,
                thread.thread_id,
                address,
                mutex_address,
                self.regs.rip,
                self.windows_thread_blocks,
            });
        }
        return .blocked;
    }

    /// Wake one waiter for pthread_cond_signal or all waiters for
    /// pthread_cond_broadcast.  The waiter retains a one-shot resume marker;
    /// on its next turn the import completes instead of parking again.
    pub fn signalWindowsGuestCondition(self: *ElfState, address: u64, broadcast: bool) u64 {
        if (address == 0) return 0;
        if (broadcast) {
            self.windows_condition_broadcast_calls +|= 1;
        } else {
            self.windows_condition_signal_calls +|= 1;
        }
        self.noteWindowsWaitSignal(address);
        var woken: u64 = 0;
        for (&self.windows_guest_threads) |*thread| {
            if (thread.status != .blocked or thread.blocked_condition != address) continue;
            thread.status = .runnable;
            thread.blocked_condition = 0;
            thread.blocked_srw_lock = 0;
            thread.blocked_wait_handle = 0;
            thread.blocked_wait_timeout = 0;
            thread.blocked_wait_deadline = 0;
            thread.condition_resume = true;
            thread.condition_resume_timeout = false;
            thread.wait_resume_timeout = false;
            self.windows_thread_unblocks +|= 1;
            self.windows_condition_unblocks +|= 1;
            woken +|= 1;
            if (!broadcast) break;
        }
        return woken;
    }

    fn wakeWindowsGuestThreadsForSrwLock(self: *ElfState, address: u64) void {
        for (&self.windows_guest_threads) |*thread| {
            if (thread.status != .blocked or thread.blocked_srw_lock != address) continue;
            thread.status = .runnable;
            thread.blocked_srw_lock = 0;
            thread.blocked_wait_handle = 0;
            thread.blocked_wait_timeout = 0;
            thread.blocked_wait_deadline = 0;
            thread.wait_resume_timeout = false;
            self.windows_thread_unblocks +|= 1;
        }
    }

    /// Install the PE loader's static TLS contract before any CRT code runs.
    /// Static TLS uses the image-provided module slot, while TlsAlloc/FlsAlloc
    /// use the remaining dynamic slots.  Keeping the two authorities explicit
    /// prevents a non-null static block from being interpreted as a pthread
    /// object by __pthread_self_lite.
    pub fn configureWindowsStaticTls(
        self: *ElfState,
        module_index: u32,
        template_start: u64,
        template_length: u64,
        block_bytes: u64,
    ) bool {
        if (module_index >= WINDOWS_TLS_SLOT_COUNT or template_length > block_bytes) return false;
        if (self.guestMemoryConst(template_start, template_length) == null) return false;
        self.windows_static_tls_index = module_index;
        self.windows_static_tls_template_start = template_start;
        self.windows_static_tls_template_length = template_length;
        self.windows_static_tls_block_bytes = @max(WINDOWS_TLS_BLOCK_BYTES, block_bytes);
        self.windows_next_tls = @max(self.windows_next_tls, @as(u32, module_index) + 1);
        return true;
    }

    fn allocateWindowsGuestThreadEnvironment(
        self: *ElfState,
        stack_base: u64,
        stack_limit: u64,
        thread_id: u64,
    ) ?WindowsGuestThreadEnvironment {
        if (self.windows_process_peb == 0) {
            log.err("Windows guest thread environment rejected: process PEB is not initialized thread_id={d}", .{thread_id});
            return null;
        }
        const teb = self.guestAlloc(WINDOWS_TEB_BYTES, WINDOWS_PAGE_SIZE) orelse return null;
        const tls_block = self.guestAlloc(self.windows_static_tls_block_bytes, WINDOWS_PAGE_SIZE) orelse return null;
        const tls_vector = teb + 0x1000;

        if (self.windows_static_tls_template_length != 0) {
            const source = self.guestMemoryConst(
                self.windows_static_tls_template_start,
                self.windows_static_tls_template_length,
            ) orelse return null;
            const destination = self.guestMemory(tls_block, self.windows_static_tls_template_length) orelse return null;
            @memcpy(destination, source);
        }

        self.write64(teb + WINDOWS_TEB_STACK_BASE_OFFSET, stack_base);
        self.write64(teb + WINDOWS_TEB_STACK_LIMIT_OFFSET, stack_limit);
        self.write64(teb + WINDOWS_TEB_SELF_OFFSET, teb);
        self.write64(teb + WINDOWS_TEB_CLIENT_ID_PROCESS_OFFSET, 1);
        self.write64(teb + WINDOWS_TEB_CLIENT_ID_THREAD_OFFSET, thread_id);
        self.write64(teb + WINDOWS_TEB_TLS_POINTER_OFFSET, tls_vector);
        if (self.windows_static_tls_index) |index| {
            self.write64(tls_vector + @as(u64, index) * 8, tls_block);
        }
        self.write64(teb + WINDOWS_TEB_PEB_OFFSET, self.windows_process_peb);
        self.write32(teb + WINDOWS_TEB_LAST_ERROR_OFFSET, 0);
        return .{ .teb = teb, .tls_block = tls_block };
    }

    /// Queue a Windows thread entry point for cooperative execution.  A
    /// successful Win32 handle is not enough here: the start routine must be
    /// retained and eventually run with a private guest stack, otherwise
    /// Xenia's graphics setup thread never reaches Vulkan initialization.
    pub fn enqueueWindowsGuestThread(
        self: *ElfState,
        handle: u64,
        start_routine: u64,
        argument: u64,
        requested_stack_size: u64,
        preferred: bool,
    ) bool {
        if (handle == 0 or start_routine == 0 or self.addrToOffset(start_routine) == null) return false;
        for (&self.windows_guest_threads) |*slot| {
            if (slot.status != .vacant and slot.handle == handle) return false;
        }

        var free_index: ?usize = null;
        for (&self.windows_guest_threads, 0..) |*slot, index| {
            if (slot.status == .vacant) {
                free_index = index;
                break;
            }
        }
        const index = free_index orelse self.recycleFinishedWindowsGuestThreadSlot() orelse {
            self.noteWindowsGuestThreadTableFull(start_routine, argument, handle);
            return false;
        };

        const stack_size = if (requested_stack_size == 0)
            WINDOWS_GUEST_THREAD_STACK_SIZE
        else
            std.math.clamp(requested_stack_size, 64 * 1024, WINDOWS_GUEST_THREAD_MAX_STACK_SIZE);
        const thread_id = self.windows_next_thread_id;
        self.windows_next_thread_id +|= 1;
        self.windows_guest_threads[index] = .{
            .status = .pending,
            .handle = handle,
            .start_routine = start_routine,
            .argument = argument,
            .thread_id = thread_id,
            .stack_size = stack_size,
            .preferred = preferred,
            .created_step = self.executed_steps,
            .creator_rip = self.last_instruction_rip,
            .creator_slot = if (self.windows_active_guest_thread_slot) |slot| @intCast(@min(slot + 1, 255)) else 0,
        };
        self.registerWindowsThreadWaitObject(handle);
        if (self.trace_windows_threads) {
            self.windows_thread_queue_trace_events +|= 1;
            const event = self.windows_thread_queue_trace_events;
            if (event <= 8 or (event & (event - 1)) == 0) {
                log.info("Windows guest thread queued: handle=0x{x} start=0x{x} argument=0x{x} stack_size={d} preferred={} slot={d} creator_rip=0x{x} active_thread=0x{x} step={d} event={d}", .{
                    handle,
                    start_routine,
                    argument,
                    stack_size,
                    preferred,
                    index,
                    self.regs.rip,
                    self.active_guest_thread,
                    self.executed_steps,
                    event,
                });
            }
        }
        return true;
    }

    /// Empty the slot of the earliest-created finished thread for a new one.
    ///
    /// A finished thread kept its slot for the rest of the run, so the
    /// thirty-third CreateThread of a run failed however many of the first
    /// thirty-two had exited, and a title loading its content starts and
    /// finishes threads continuously. What a finished thread's handle still
    /// owes a waiter, that it reads as signalled, lives on in its wait
    /// object; its stack, TEB and TLS block go back to the guest heap, which
    /// zeroes a block before handing it out again.
    fn recycleFinishedWindowsGuestThreadSlot(self: *ElfState) ?usize {
        var oldest: ?usize = null;
        for (&self.windows_guest_threads, 0..) |*thread, index| {
            if (thread.status != .completed and thread.status != .failed) continue;
            if (self.windows_active_guest_thread_slot) |active| {
                if (active == index) continue;
            }
            if (oldest) |current| {
                if (thread.created_step >= self.windows_guest_threads[current].created_step) continue;
            }
            oldest = index;
        }
        const index = oldest orelse return null;
        const finished = &self.windows_guest_threads[index];
        if (self.windowsWaitObjectIndex(finished.handle)) |wait_index| {
            self.windows_wait_objects[wait_index].signaled = true;
        }
        for ([_]u64{ finished.stack_base, finished.teb, finished.tls_block }) |base| {
            if (base != 0) _ = self.releaseGuestAllocation(base);
        }
        self.windows_guest_threads[index] = .{};
        self.windows_thread_slots_recycled +|= 1;
        return index;
    }

    /// CreateThread with every slot holding a thread that has not finished.
    fn noteWindowsGuestThreadTableFull(self: *ElfState, start_routine: u64, argument: u64, handle: u64) void {
        self.windows_thread_table_full +|= 1;
        const occurrence = self.windows_thread_table_full;
        if (occurrence == 1) self.windows_fatal_point_events +|= 1;
        if (comptime !@import("builtin").is_test) {
            if (shouldReportWindowsPointOccurrence(occurrence)) {
                var start_text: [guest_symbol_text_bytes]u8 = undefined;
                log.err("PE64 FATAL POINT: guest-condition label=guest-thread-table-full owner=rosette:scheduler occurrence={d} start={s} argument=0x{x} handle=0x{x} capacity={d} reused_so_far={d} step={d}; every slot holds a thread that has not finished, so CreateThread returns NULL and the caller's thread never exists. Raise MAX_WINDOWS_GUEST_THREADS, or read PE64 GUEST THREADS for threads that should have exited", .{
                    occurrence,
                    self.describeGuestAddressOrUnnamed(start_routine, &start_text),
                    argument,
                    handle,
                    self.windows_guest_threads.len,
                    self.windows_thread_slots_recycled,
                    self.executed_steps,
                });
            }
        }
        self.terminateForWindowsFatalPoint("guest-thread-table-full");
    }

    /// Hold a freshly queued thread at a suspend count of one, as
    /// `CREATE_SUSPENDED` asks: it is not scheduled until `ResumeThread`.
    pub fn suspendWindowsGuestThreadAtCreation(self: *ElfState, handle: u64) void {
        const index = self.windowsGuestThreadIndex(handle) orelse return;
        self.windows_guest_threads[index].suspend_count = 1;
        self.windows_thread_suspended_creations +|= 1;
    }

    /// The thread id Rosette assigned a handle, for `lpThreadId`.
    pub fn windowsGuestThreadId(self: *const ElfState, handle: u64) ?u64 {
        const index = self.windowsGuestThreadIndex(handle) orelse return null;
        return self.windows_guest_threads[index].thread_id;
    }

    fn windowsGuestThreadIndex(self: *const ElfState, handle: u64) ?usize {
        if (handle == WINDOWS_CURRENT_THREAD_PSEUDO_HANDLE) return self.windows_active_guest_thread_slot;
        for (&self.windows_guest_threads, 0..) |*thread, index| {
            if (thread.status != .vacant and thread.handle == handle) return index;
        }
        return null;
    }

    /// `SuspendThread` and `ResumeThread`: the previous count, or (DWORD)-1.
    ///
    /// A thread that suspends itself yields at once; the scheduler does not
    /// choose it again until another thread brings its count back to zero.
    pub fn changeWindowsGuestThreadSuspension(self: *ElfState, handle: u64, suspending: bool) u64 {
        const failure: u64 = std.math.maxInt(u32);
        const index = self.windowsGuestThreadIndex(handle) orelse {
            self.windows_last_error = 6; // ERROR_INVALID_HANDLE
            return failure;
        };
        const thread = &self.windows_guest_threads[index];
        const previous = thread.suspend_count;
        if (suspending) {
            if (previous >= WINDOWS_MAXIMUM_SUSPEND_COUNT) {
                self.windows_last_error = 156; // ERROR_SIGNAL_REFUSED
                return failure;
            }
            thread.suspend_count = previous + 1;
            self.windows_thread_suspend_calls +|= 1;
            if (self.windows_active_guest_thread_slot == index) self.requestWindowsGuestSliceYield();
        } else {
            if (previous != 0) thread.suspend_count = previous - 1;
            self.windows_thread_resume_calls +|= 1;
        }
        self.windows_last_error = 0;
        return previous;
    }

    fn windowsGuestRegisterDigest(self: *const ElfState) u64 {
        const r = self.regs;
        var digest: u64 = r.rflags;
        for ([_]u64{ r.rax, r.rbx, r.rcx, r.rdx, r.rsi, r.rdi, r.rbp, r.rsp, r.r8, r.r9, r.r10, r.r11, r.r12, r.r13, r.r14, r.r15 }) |value| {
            digest = (digest ^ value) *% 0x9E37_79B9_7F4A_7C15;
        }
        return digest;
    }

    /// A slice that came back to the same instruction with every register the
    /// same, and made no kernel call, is a user-mode spin: the title polling a
    /// flag another thread sets. Under cooperative scheduling it takes an
    /// equal turn from the threads that would set it; on 2026-09-16
    /// XThread001A spent 19% of the run in one 256-byte loop. Each spinning
    /// slice doubles the turns the thread gives away, up to
    /// WINDOWS_GUEST_SPIN_MAX_BACKOFF; any other slice resets it.
    fn noteWindowsGuestSliceShape(self: *ElfState, index: usize, repeated_state: bool, kernel_calls_before: u64) void {
        const thread = &self.windows_guest_threads[index];
        if (!repeated_state or thread.kernel_calls != kernel_calls_before) {
            thread.spin_backoff = 0;
            return;
        }
        self.windows_spin_slices +|= 1;
        thread.spin_backoff = if (thread.spin_backoff == 0) 1 else @min(thread.spin_backoff *| 2, WINDOWS_GUEST_SPIN_MAX_BACKOFF);
        thread.spin_skip_remaining = thread.spin_backoff;
    }

    fn nextWindowsGuestThread(self: *const ElfState) ?usize {
        if (self.windows_preferred_next_guest_thread) |preferred| {
            if (preferred < self.windows_guest_threads.len and
                self.windows_guest_threads[preferred].status == .runnable and
                self.windows_guest_threads[preferred].suspend_count == 0)
            {
                return preferred;
            }
        }
        const start = if (self.windows_last_serviced_guest_thread_slot) |last|
            (last + 1) % self.windows_guest_threads.len
        else
            0;

        // Give a freshly-created Win32 worker the first service opportunity
        // so Xenia's graphics setup thread is not behind CRT bookkeeping.
        // Once one slot has run, use a true circular scan: a worker that
        // parks in a loop must not starve the other graphics workers forever.
        if (self.windows_last_serviced_guest_thread_slot == null) {
            for (0..self.windows_guest_threads.len) |offset| {
                const index = (start + offset) % self.windows_guest_threads.len;
                const slot = &self.windows_guest_threads[index];
                if ((slot.status == .pending or slot.status == .runnable) and slot.preferred and slot.suspend_count == 0) return index;
            }
        }
        for (0..self.windows_guest_threads.len) |offset| {
            const index = (start + offset) % self.windows_guest_threads.len;
            const slot = &self.windows_guest_threads[index];
            if ((slot.status == .pending or slot.status == .runnable) and slot.suspend_count == 0) return index;
        }
        return null;
    }

    fn finishWindowsGuestThread(self: *ElfState) void {
        const index = self.windows_active_guest_thread_slot orelse {
            self.faulted = true;
            self.exit_code = 127;
            self.termination_reason = .runtime_invariant_failure;
            self.terminated = true;
            log.err("Windows guest thread return without an active thread context at rip=0x{x}", .{self.regs.rip});
            return;
        };
        self.endWindowsWaitAccounting(&self.windows_guest_threads[index], .aborted);
        self.windows_guest_threads[index].status = .completed;
        self.windows_thread_completions +|= 1;
        if (self.windowsWaitObjectIndex(self.windows_guest_threads[index].handle)) |wait_index| {
            self.noteWindowsWaitSignal(self.windows_guest_threads[index].handle);
            self.windows_wait_objects[wait_index].signaled = true;
            _ = self.wakeWindowsGuestThreadsForWait(self.windows_guest_threads[index].handle, true);
        }
        const parent = self.windows_parent_guest_context;
        self.restoreWindowsGuestContext(&parent);
        self.windows_active_guest_thread_slot = null;
        self.windows_parent_guest_context_valid = false;
        // Nothing runs on a finished thread's stack, and Windows frees it at
        // exit. Holding it until the slot was reused kept megabytes per
        // finished thread out of the guest heap; on 2026-09-14 the heap ran
        // out and the title's next thread never got a stack at all.
        const finished_stack = self.windows_guest_threads[index].stack_base;
        if (finished_stack != 0 and self.releaseGuestAllocation(finished_stack)) {
            self.windows_guest_threads[index].stack_base = 0;
            self.windows_thread_stacks_released +|= 1;
        }
        if (self.diagnose_abi or self.trace_windows_threads) {
            log.info("Windows guest thread complete handle=0x{x} start=0x{x} steps={d} parent_rip=0x{x}", .{
                self.windows_guest_threads[index].handle,
                self.windows_guest_threads[index].start_routine,
                self.windows_guest_threads[index].executed_steps,
                self.regs.rip,
            });
        }
    }

    /// Complete the currently serviced Windows worker when a noreturn thread
    /// API such as `_endthreadex` is reached.  The API must not be modelled as
    /// an ordinary zero-returning import: returning to its next instruction
    /// falls through into the next PE symbol because the wrapper has no
    /// epilogue after the real Windows runtime terminates the thread.
    pub fn terminateActiveWindowsGuestThread(self: *ElfState, exit_code: u64) bool {
        if (self.windows_active_guest_thread_slot == null) return false;
        self.regs.rax = exit_code;
        self.finishWindowsGuestThread();
        return true;
    }

    /// Run one queued Windows thread for a bounded slice.  The slice is a
    /// cooperative scheduling point, not a second host thread: all memory,
    /// import, graphics, and exception state remains owned by the same PE
    /// state, while each runnable entry retains a complete CPU context when it
    /// yields.  This keeps startup deterministic and prevents a worker loop
    /// from making the host UI unresponsive.
    pub fn serviceWindowsGuestThreads(self: *ElfState, max_steps: u64) u64 {
        if (max_steps == 0 or self.windows_active_guest_thread_slot != null or self.terminated) return 0;
        _ = self.wakeExpiredWindowsGuestWaits();
        var index = self.nextWindowsGuestThread() orelse return 0;
        // A thread backing off from a user-mode spin gives its turn to the
        // next runnable thread. Bounded by the table, so a run in which every
        // runnable thread spins still runs one of them.
        var passes: usize = 0;
        while (self.windows_guest_threads[index].spin_skip_remaining != 0 and passes < self.windows_guest_threads.len) : (passes += 1) {
            self.windows_guest_threads[index].spin_skip_remaining -= 1;
            self.windows_spin_turns_given +|= 1;
            self.windows_last_serviced_guest_thread_slot = index;
            self.windows_preferred_next_guest_thread = null;
            index = self.nextWindowsGuestThread() orelse return 0;
        }
        // A preference is for one scheduling decision only.
        self.windows_preferred_next_guest_thread = null;
        self.windows_thread_service_calls +|= 1;
        self.windows_last_serviced_guest_thread_slot = index;
        self.windows_last_service_owner_step = self.executed_steps;
        self.windows_active_guest_thread_slot = index;
        self.windows_parent_guest_context = self.captureWindowsGuestContext();
        self.windows_parent_guest_context_valid = true;

        const first_run = self.windows_guest_threads[index].status == .pending;
        if (first_run) {
            const stack_base = self.guestAlloc(self.windows_guest_threads[index].stack_size, 0x1000) orelse {
                self.windows_guest_threads[index].status = .failed;
                self.windows_thread_failures +|= 1;
                self.windows_active_guest_thread_slot = null;
                self.windows_parent_guest_context_valid = false;
                log.err("Windows guest thread stack allocation failed: handle=0x{x} start=0x{x} size={d}", .{
                    self.windows_guest_threads[index].handle,
                    self.windows_guest_threads[index].start_routine,
                    self.windows_guest_threads[index].stack_size,
                });
                return 0;
            };
            const allocated_stack_end = stack_base + self.windows_guest_threads[index].stack_size;
            const stack_top = allocated_stack_end - WINDOWS_GUEST_THREAD_ENTRY_RESERVE;
            const initial_parent = self.windows_parent_guest_context;
            var context = initial_parent;
            context.regs = .{};
            context.regs.segments = initial_parent.regs.segments;
            const environment = self.allocateWindowsGuestThreadEnvironment(
                allocated_stack_end,
                stack_base,
                self.windows_guest_threads[index].thread_id,
            ) orelse {
                self.windows_guest_threads[index].status = .failed;
                self.windows_thread_failures +|= 1;
                self.windows_active_guest_thread_slot = null;
                self.windows_parent_guest_context_valid = false;
                log.err("Windows guest thread environment allocation failed: handle=0x{x} start=0x{x} thread_id={d}", .{
                    self.windows_guest_threads[index].handle,
                    self.windows_guest_threads[index].start_routine,
                    self.windows_guest_threads[index].thread_id,
                });
                return 0;
            };
            context.regs.segments.gs.base = environment.teb;
            context.regs.mxcsr = initial_parent.regs.mxcsr;
            context.regs.rflags = 2;
            context.regs.rcx = self.windows_guest_threads[index].argument;
            context.tls_values = [_]u64{0} ** WINDOWS_TLS_SLOT_COUNT;
            if (self.windows_static_tls_index) |static_index| {
                context.tls_values[static_index] = environment.tls_block;
            }
            context.windows_last_error = 0;
            context.windows_errno_storage = 0;
            // RSP must be 8 mod 16 at a normal Windows x64 callee entry:
            // [RSP] is the synthetic return address and [RSP+8..+0x27] is
            // the four-slot home area.  The reserved cushion keeps all of
            // those addresses below allocated_stack_end.
            context.regs.rsp = (stack_top & ~@as(u64, 0xF)) - 8;
            context.regs.rip = self.windows_guest_threads[index].start_routine;
            context.active_guest_thread = self.windows_guest_threads[index].handle;
            context.active_idle_source = initial_parent.active_idle_source;
            self.windows_guest_threads[index].stack_base = stack_base;
            self.windows_guest_threads[index].teb = environment.teb;
            self.windows_guest_threads[index].tls_block = environment.tls_block;
            self.windows_guest_threads[index].synthetic_return_slot = context.regs.rsp;
            self.windows_guest_threads[index].context = context;
            self.write64(context.regs.rsp, SYNTHETIC_WINDOWS_THREAD_RETURN);
        }

        self.windows_guest_threads[index].status = .running;
        const context = self.windows_guest_threads[index].context;
        self.restoreWindowsGuestContext(&context);
        if (self.diagnose_abi or self.trace_windows_threads) {
            // The Win32 wrapper receives two different opaque start records:
            // xe::threading::ThreadStartRoutine stores its std::function
            // invoker at +0x18, while the MinGW pthread wrapper stores the
            // pthread entry at +0x10 and its argument at +0x08.  Reporting
            // those targets makes a cooperative worker trace actionable
            // without walking an incomplete host stack.
            const dispatch_target = if (self.windows_guest_threads[index].start_routine == 0x1401310f0)
                self.read64(context.regs.rcx +| 0x18)
            else if (self.windows_guest_threads[index].start_routine == 0x14051502b)
                self.read64(context.regs.rcx +| 0x10)
            else
                0;
            const dispatch_argument = if (self.windows_guest_threads[index].start_routine == 0x14051502b)
                self.read64(context.regs.rcx +| 0x08)
            else
                0;
            const dispatch_vtable = if (dispatch_argument != 0) self.read64(dispatch_argument) else 0;
            log.info("Windows guest thread service start handle=0x{x} start=0x{x} argument=0x{x} dispatch=0x{x} dispatch_argument=0x{x} dispatch_vtable=0x{x} resumed={} rip=0x{x} rsp=0x{x} return_slot=0x{x} return_value=0x{x} stack=[0x{x},0x{x})", .{
                self.windows_guest_threads[index].handle,
                self.windows_guest_threads[index].start_routine,
                self.windows_guest_threads[index].argument,
                dispatch_target,
                dispatch_argument,
                dispatch_vtable,
                !first_run,
                self.regs.rip,
                self.regs.rsp,
                self.windows_guest_threads[index].synthetic_return_slot,
                self.read64(self.windows_guest_threads[index].synthetic_return_slot),
                self.windows_guest_threads[index].stack_base,
                self.windows_guest_threads[index].stack_base +| self.windows_guest_threads[index].stack_size,
            });
        }

        var executed: u64 = 0;
        self.windows_guest_slice_yield_requested = false;
        self.windows_slice_clock_reads = 0;
        const slice_kernel_calls = self.windows_guest_threads[index].kernel_calls;
        var spin_probe_rip: u64 = 0;
        var spin_probe_state: u64 = 0;
        var slice_repeated_state = false;
        while (!self.terminated and self.windows_active_guest_thread_slot != null and executed < max_steps) : (executed += 1) {
            const continue_running = self.step();
            if (executed == WINDOWS_GUEST_SPIN_PROBE_AT) {
                spin_probe_rip = self.regs.rip;
                spin_probe_state = self.windowsGuestRegisterDigest();
            } else if (!slice_repeated_state and executed > WINDOWS_GUEST_SPIN_PROBE_AT and
                executed <= WINDOWS_GUEST_SPIN_PROBE_AT + WINDOWS_GUEST_SPIN_PROBE_SPAN and
                self.regs.rip == spin_probe_rip and self.windowsGuestRegisterDigest() == spin_probe_state)
            {
                slice_repeated_state = true;
            }
            // A yield boundary ends the slice here rather than inside the
            // import handler, so the tail below still saves this worker's
            // context and restores the owner's.
            //
            // Not on the first instruction, though: a switch costs two
            // register-file copies, and a spin-wait whose inner loop is a
            // dozen instructions would otherwise pay that every dozen. The
            // floor keeps the yield meaningful - a spinner gets a couple of
            // hundred instructions instead of ten thousand - without letting
            // the switch dominate what it saved.
            if (self.windows_guest_slice_yield_requested and executed >= WINDOWS_GUEST_YIELD_MINIMUM_SLICE) {
                self.windows_guest_slice_yield_requested = false;
                break;
            }
            self.windows_thread_service_steps +|= 1;
            self.windows_guest_threads[index].executed_steps +|= 1;
            self.windows_worker_executed_steps +|= 1;
            // Every sixty-fourth instruction, note where this thread is. See
            // `code_low` for why a per-thread code window is the measurement
            // and a per-thread rip is not.
            if ((executed & 0x3F) == 0) {
                self.windows_guest_threads[index].code.sample(self.regs.rip);
            }
            if (self.regs.rip == 0) {
                if (self.last_decoded_op == .ret) {
                    // A worker entry is given a synthetic return slot.  A
                    // guest routine that consumes that slot and returns
                    // without a caller has completed its Windows thread; it
                    // must not turn the scheduler's next decode into a
                    // process-wide failure at address zero.
                    const thread = self.windows_guest_threads[index];
                    log.info("Windows guest thread returned through null RIP; completing worker locally: handle=0x{x} start=0x{x} steps={d}", .{
                        thread.handle,
                        thread.start_routine,
                        thread.executed_steps,
                    });
                    self.finishWindowsGuestThread();
                    break;
                }
                const thread = self.windows_guest_threads[index];
                log.err("Windows guest thread reached null RIP: handle=0x{x} start=0x{x} last_op={s} last_len={d} rsp=0x{x} rsp_value=0x{x} rbp=0x{x} entry_slot=0x{x} entry_value=0x{x} stack=[0x{x},0x{x}) call_depth={d}", .{
                    thread.handle,
                    thread.start_routine,
                    @tagName(self.last_decoded_op),
                    self.last_decoded_len,
                    self.regs.rsp,
                    self.read64(self.regs.rsp),
                    self.regs.rbp,
                    thread.synthetic_return_slot,
                    self.read64(thread.synthetic_return_slot),
                    thread.stack_base,
                    thread.stack_base +| thread.stack_size,
                    self.call_stack.frames.items.len,
                });
            }
            if (self.windows_guest_threads[index].status == .blocked) break;
            if (!continue_running) break;
            // A spin proven by a repeated state gains nothing from the rest
            // of its slice: 2026-09-16 spent ~8% of every instruction running
            // detected spins out to the full quantum. Hand the turn back now.
            if (slice_repeated_state and self.windows_guest_threads[index].kernel_calls == slice_kernel_calls) break;
        }

        if (self.terminated) {
            self.exit_fault_regs = self.regs;
            self.exit_fault_thread_slot = index;
            self.windows_guest_threads[index].status = .failed;
            self.windows_thread_failures +|= 1;
            if (self.windows_parent_guest_context_valid) {
                const parent = self.windows_parent_guest_context;
                self.restoreWindowsGuestContext(&parent);
            }
            self.windows_active_guest_thread_slot = null;
            self.windows_parent_guest_context_valid = false;
            return executed;
        }
        if (self.windows_active_guest_thread_slot != null) {
            self.windows_guest_threads[index].context = self.captureWindowsGuestContext();
            const blocked = self.windows_guest_threads[index].status == .blocked;
            if (!blocked) {
                self.windows_guest_threads[index].status = .runnable;
                self.windows_thread_yields +|= 1;
                self.noteWindowsGuestSliceShape(index, slice_repeated_state, slice_kernel_calls);
            }
            const parent = self.windows_parent_guest_context;
            self.restoreWindowsGuestContext(&parent);
            self.windows_active_guest_thread_slot = null;
            self.windows_parent_guest_context_valid = false;
            if ((self.diagnose_abi or self.trace_windows_threads) and !blocked) {
                log.info("Windows guest thread service yield handle=0x{x} slice={d} rip=0x{x} rsp=0x{x}", .{
                    self.windows_guest_threads[index].handle,
                    executed,
                    self.windows_guest_threads[index].context.regs.rip,
                    self.windows_guest_threads[index].context.regs.rsp,
                });
            } else if (self.trace_windows_threads and blocked and
                (self.windows_thread_blocks <= 8 or self.windows_thread_blocks % 1024 == 0))
            {
                if (self.windows_guest_threads[index].blocked_srw_lock != 0) {
                    log.info("Windows guest thread service block handle=0x{x} lock=0x{x} rip=0x{x} rsp=0x{x}", .{
                        self.windows_guest_threads[index].handle,
                        self.windows_guest_threads[index].blocked_srw_lock,
                        self.windows_guest_threads[index].context.regs.rip,
                        self.windows_guest_threads[index].context.regs.rsp,
                    });
                } else {
                    log.info("Windows guest thread service block handle=0x{x} condition=0x{x} rip=0x{x} rsp=0x{x}", .{
                        self.windows_guest_threads[index].handle,
                        self.windows_guest_threads[index].blocked_condition,
                        self.windows_guest_threads[index].context.regs.rip,
                        self.windows_guest_threads[index].context.regs.rsp,
                    });
                }
            }
        }
        return executed;
    }

    /// Give one queued Windows worker a bounded turn while the owner thread
    /// is inside a long compute region.  The explicit PAUSE/wait/message
    /// boundaries remain the low-latency path; this policy is the fallback for
    /// code such as Xenia's image hashing that can run for millions of guest
    /// instructions without crossing one.  It never nests because the worker
    /// context makes `windows_active_guest_thread_slot` non-null while its
    /// slice is executing.
    fn maybeRunWindowsGuestScheduler(self: *ElfState) void {
        const policy = &self.windows_scheduler;
        if (!policy.enabled or !self.windows_runtime_enabled or self.terminated or
            self.windows_active_guest_thread_slot != null)
        {
            return;
        }
        if (self.executed_steps < policy.next_service_step) return;

        policy.next_service_step = self.executed_steps +| policy.quantum;
        if (self.nextWindowsGuestThread() == null) return;

        const serviced = self.serviceWindowsGuestThreads(policy.slice);
        policy.service_calls +|= 1;
        policy.serviced_steps +|= serviced;
        if (self.trace_windows_threads and
            (policy.service_calls <= 8 or policy.service_calls % 1024 == 0))
        {
            log.info(
                "Windows guest scheduler quantum: owner_step={d} serviced_steps={d} scheduler_calls={d} scheduler_steps={d} worker_calls={d} worker_yields={d} runnable={d}",
                .{
                    self.executed_steps,
                    serviced,
                    policy.service_calls,
                    policy.serviced_steps,
                    self.windows_thread_service_calls,
                    self.windows_thread_yields,
                    self.countWindowsWorkers(.runnable) + self.countWindowsWorkers(.pending),
                },
            );
        }
    }

    pub fn requestWindowsUiQuit(self: *ElfState) void {
        self.windows_ui_quit_requested = true;
    }

    fn captureWindowsClassName(self: *const ElfState, record: *WindowsWindowClass, name_ptr: u64, wide: bool) void {
        record.name_ptr = name_ptr;
        record.name_len = 0;
        record.wide = wide;
        @memset(record.name[0..], 0);
        if (name_ptr == 0) return;

        if (wide) {
            while (record.name_len < record.name.len - 1) {
                const address = name_ptr +| @as(u64, @intCast(record.name_len * 2));
                if (self.guestMemoryConst(address, 2) == null) break;
                const unit = self.read16(address);
                if (unit == 0) break;
                record.name[record.name_len] = if (unit <= 0x7f) @intCast(unit) else '?';
                record.name_len += 1;
            }
        } else {
            while (record.name_len < record.name.len - 1) {
                const address = name_ptr +| @as(u64, @intCast(record.name_len));
                if (self.guestMemoryConst(address, 1) == null) break;
                const byte = self.read8(address);
                if (byte == 0) break;
                record.name[record.name_len] = byte;
                record.name_len += 1;
            }
        }
    }

    fn windowsClassMatches(self: *const ElfState, record: *const WindowsWindowClass, class_name: u64, wide: bool) bool {
        if (!record.valid or class_name == 0) return false;
        if (class_name <= 0xffff and record.atom == @as(u16, @intCast(class_name))) return true;
        if (record.name_ptr == class_name) return true;
        if (record.name_len == 0) return false;

        for (0..record.name_len) |index| {
            const address = class_name +| if (wide)
                @as(u64, @intCast(index * 2))
            else
                @as(u64, @intCast(index));
            const actual: u8 = if (wide) blk: {
                if (self.guestMemoryConst(address, 2) == null) return false;
                const unit = self.read16(address);
                if (unit > 0x7f) return false;
                break :blk @intCast(unit);
            } else blk: {
                if (self.guestMemoryConst(address, 1) == null) return false;
                break :blk self.read8(address);
            };
            if (actual != record.name[index]) return false;
        }

        const terminator = class_name +| if (wide)
            @as(u64, @intCast(record.name_len * 2))
        else
            @as(u64, @intCast(record.name_len));
        if (self.guestMemoryConst(terminator, if (wide) 2 else 1) == null) return false;
        return if (wide) self.read16(terminator) == 0 else self.read8(terminator) == 0;
    }

    fn windowsClassIndex(self: *const ElfState, class_name: u64, wide: bool) ?usize {
        for (self.windows_window_classes, 0..) |record, index| {
            if (self.windowsClassMatches(&record, class_name, wide)) return index;
        }
        return null;
    }

    /// Register the guest WndProc carried by a WNDCLASS/WNDCLASSEX record.
    /// The structure layout is the same through `lpfnWndProc` and
    /// `lpszClassName` for the A/W and Ex/non-Ex variants on Win64.
    pub fn registerWindowsWindowClass(self: *ElfState, class_info: u64, wide: bool) u64 {
        if (class_info == 0 or self.guestMemoryConst(class_info, 72) == null) return 0;
        const wnd_proc = self.read64(class_info + 8);
        const class_name = self.read64(class_info + 64);
        if (wnd_proc == 0 or class_name == 0) return 0;

        if (self.windowsClassIndex(class_name, wide)) |existing| {
            self.windows_window_classes[existing].wnd_proc = wnd_proc;
            return self.windows_window_classes[existing].atom;
        }

        var free_index: ?usize = null;
        for (self.windows_window_classes, 0..) |record, index| {
            if (!record.valid) {
                free_index = index;
                break;
            }
        }
        const index = free_index orelse return 0;
        const atom = self.windows_next_window_class_atom;
        self.windows_next_window_class_atom +|= 1;
        if (self.windows_next_window_class_atom == 0) self.windows_next_window_class_atom = 1;

        var record = WindowsWindowClass{
            .valid = true,
            .atom = if (atom == 0) 1 else atom,
            .wnd_proc = wnd_proc,
            .wide = wide,
        };
        self.captureWindowsClassName(&record, class_name, wide);
        self.windows_window_classes[index] = record;
        return record.atom;
    }

    /// Install a synthetic HWND and retain the guest `lpParam` as its
    /// GWLP_USERDATA.  Real Win32 sends WM_NCCREATE during CreateWindowEx;
    /// recording that result here gives the guest WndProc the same state
    /// without recursively running creation messages before the import has
    /// returned its HWND.
    pub fn createWindowsWindow(
        self: *ElfState,
        handle: u64,
        class_name: u64,
        user_data: u64,
        message_only: bool,
        style: u64,
        ex_style: u64,
        wide: bool,
    ) bool {
        if (handle == 0 or self.windowsWindowIndex(handle) != null) return false;
        var free_index: ?usize = null;
        for (self.windows_windows, 0..) |record, index| {
            if (!record.valid) {
                free_index = index;
                break;
            }
        }
        const index = free_index orelse return false;
        const class_index = self.windowsClassIndex(class_name, wide);
        self.windows_windows[index] = .{
            .valid = true,
            .handle = handle,
            .class_atom = if (class_index) |class_index_value| self.windows_window_classes[class_index_value].atom else 0,
            .wnd_proc = if (class_index) |class_index_value| self.windows_window_classes[class_index_value].wnd_proc else 0,
            .user_data = user_data,
            .style = @truncate(style),
            .ex_style = @truncate(ex_style),
            .message_only = message_only,
        };
        if (message_only) self.windows_message_window_handle = handle;
        return true;
    }

    fn windowsWindowIndex(self: *const ElfState, handle: u64) ?usize {
        for (self.windows_windows, 0..) |record, index| {
            if (record.valid and record.handle == handle) return index;
        }
        return null;
    }

    pub fn isWindowsWindowHandle(self: *const ElfState, handle: u64) bool {
        return self.windowsWindowIndex(handle) != null;
    }

    pub fn windowsWindowProc(self: *const ElfState, handle: u64) ?u64 {
        const index = self.windowsWindowIndex(handle) orelse return null;
        const proc = self.windows_windows[index].wnd_proc;
        return if (proc == 0) null else proc;
    }

    pub fn windowsWindowLong(self: *const ElfState, handle: u64, index: i64) ?u64 {
        const window_index = self.windowsWindowIndex(handle) orelse return null;
        const record = self.windows_windows[window_index];
        return switch (index) {
            WINDOWS_GWLP_USERDATA => record.user_data,
            WINDOWS_GWL_STYLE => record.style,
            WINDOWS_GWL_EXSTYLE => record.ex_style,
            WINDOWS_GCLP_WNDPROC => record.wnd_proc,
            else => null,
        };
    }

    pub fn setWindowsWindowLong(self: *ElfState, handle: u64, index: i64, value: u64) ?u64 {
        const window_index = self.windowsWindowIndex(handle) orelse return null;
        const previous = self.windowsWindowLong(handle, index) orelse return null;
        switch (index) {
            WINDOWS_GWLP_USERDATA => self.windows_windows[window_index].user_data = value,
            WINDOWS_GWL_STYLE => self.windows_windows[window_index].style = @truncate(value),
            WINDOWS_GWL_EXSTYLE => self.windows_windows[window_index].ex_style = @truncate(value),
            else => return null,
        }
        return previous;
    }

    pub fn destroyWindowsWindow(self: *ElfState, handle: u64) bool {
        const index = self.windowsWindowIndex(handle) orelse return false;
        self.windows_windows[index] = .{};
        if (self.windows_message_window_handle == handle) self.windows_message_window_handle = 0;
        return true;
    }

    /// Mark a window's update region non-empty.  This is the model behind
    /// InvalidateRect/InvalidateRgn/RedrawWindow: Win32 records the request
    /// and defers WM_PAINT generation to the message pump.  A null HWND
    /// invalidates every drawable window, matching the Win32 contract for a
    /// null window handle.
    pub fn invalidateWindowsWindow(self: *ElfState, handle: u64) bool {
        if (handle == 0) {
            var marked = false;
            for (&self.windows_windows) |*record| {
                if (!record.valid or record.message_only) continue;
                if (!record.update_region_pending) self.windows_paint_requests +|= 1;
                record.update_region_pending = true;
                marked = true;
            }
            return marked;
        }
        const index = self.windowsWindowIndex(handle) orelse return false;
        if (self.windows_windows[index].message_only) return false;
        if (!self.windows_windows[index].update_region_pending) self.windows_paint_requests +|= 1;
        self.windows_windows[index].update_region_pending = true;
        return true;
    }

    /// Clear a window's update region.  ValidateRect/ValidateRgn and the
    /// BeginPaint/EndPaint pair all end the pending paint; without this the
    /// pump would keep regenerating WM_PAINT forever, exactly as real Win32
    /// does for a WndProc that never validates.
    pub fn validateWindowsWindow(self: *ElfState, handle: u64) bool {
        if (handle == 0) {
            var cleared = false;
            for (&self.windows_windows) |*record| {
                if (!record.valid) continue;
                if (record.update_region_pending) cleared = true;
                record.update_region_pending = false;
            }
            return cleared;
        }
        const index = self.windowsWindowIndex(handle) orelse return false;
        const cleared = self.windows_windows[index].update_region_pending;
        self.windows_windows[index].update_region_pending = false;
        return cleared;
    }

    pub fn windowsWindowHasPendingPaint(self: *const ElfState, handle: u64) bool {
        const index = self.windowsWindowIndex(handle) orelse return false;
        return self.windows_windows[index].update_region_pending;
    }

    pub fn windowsPendingPaintCount(self: *const ElfState) usize {
        var count: usize = 0;
        for (self.windows_windows) |record| {
            if (record.valid and record.update_region_pending) count += 1;
        }
        return count;
    }

    /// Produce the WM_PAINT a pump call should return, if any window still
    /// has a non-empty update region and the caller's filter accepts it.
    /// WM_PAINT is generated rather than dequeued, so the region stays set
    /// until the guest validates it; a PeekMessage without PM_REMOVE and a
    /// GetMessage therefore observe the same pending paint.
    pub fn pendingWindowsPaintMessage(
        self: *ElfState,
        filter_hwnd: u64,
        minimum: u64,
        maximum: u64,
    ) ?WindowsMessage {
        const minimum_message: u32 = @truncate(minimum);
        const maximum_message: u32 = @truncate(maximum);
        if (minimum_message > maximum_message and !(minimum_message == 0 and maximum_message == 0)) return null;
        for (self.windows_windows) |record| {
            if (!record.valid or !record.update_region_pending) continue;
            const message = WindowsMessage{ .hwnd = record.handle, .message = WINDOWS_WM_PAINT };
            if (!windowsMessageMatches(message, filter_hwnd, minimum_message, maximum_message)) continue;
            // A WM_PAINT that no WndProc can receive would spin the pump
            // forever without ever reaching the guest's painter.  Report the
            // window as having nothing to paint instead; the stall report
            // names the window if this is the reason no frame is produced.
            if (record.wnd_proc == 0) continue;
            self.windows_paint_deliveries +|= 1;
            return message;
        }
        return null;
    }

    fn enqueueWindowsMessage(self: *ElfState, message: WindowsMessage) bool {
        if (self.windows_message_count >= self.windows_messages.len) {
            self.windows_message_drops +|= 1;
            return false;
        }
        self.windows_messages[self.windows_message_tail] = message;
        self.windows_message_tail = (self.windows_message_tail + 1) % self.windows_messages.len;
        self.windows_message_count += 1;
        self.windows_message_posts +|= 1;
        return true;
    }

    pub fn postWindowsMessage(self: *ElfState, hwnd: u64, message: u32, wparam: u64, lparam: u64) bool {
        if (hwnd == 0 or !self.isWindowsWindowHandle(hwnd)) {
            self.windows_message_drops +|= 1;
            return false;
        }
        return self.enqueueWindowsMessage(.{ .hwnd = hwnd, .message = message, .wparam = wparam, .lparam = lparam });
    }

    pub fn postWindowsQuit(self: *ElfState, exit_code: u64) void {
        self.windows_ui_quit_code = exit_code;
        self.windows_ui_quit_requested = true;
        _ = self.enqueueWindowsMessage(.{ .message = 0, .wparam = exit_code });
    }

    fn windowsMessageMatches(message: WindowsMessage, filter_hwnd: u64, minimum: u32, maximum: u32) bool {
        if (filter_hwnd != 0 and message.hwnd != filter_hwnd) return false;
        if (minimum == 0 and maximum == 0) return true;
        return message.message >= minimum and message.message <= maximum;
    }

    pub fn dequeueWindowsMessage(self: *ElfState, filter_hwnd: u64, minimum: u64, maximum: u64, remove: bool) ?WindowsMessage {
        const minimum_message: u32 = @truncate(minimum);
        const maximum_message: u32 = @truncate(maximum);
        if (minimum_message > maximum_message and !(minimum_message == 0 and maximum_message == 0)) return null;

        for (0..self.windows_message_count) |offset| {
            const index = (self.windows_message_head + offset) % self.windows_messages.len;
            const message = self.windows_messages[index];
            if (!windowsMessageMatches(message, filter_hwnd, minimum_message, maximum_message)) continue;
            if (!remove) return message;

            var shift = offset;
            while (shift + 1 < self.windows_message_count) : (shift += 1) {
                const current = (self.windows_message_head + shift) % self.windows_messages.len;
                const next = (self.windows_message_head + shift + 1) % self.windows_messages.len;
                self.windows_messages[current] = self.windows_messages[next];
            }
            self.windows_message_tail = (self.windows_message_tail + self.windows_messages.len - 1) % self.windows_messages.len;
            self.windows_messages[self.windows_message_tail] = .{};
            self.windows_message_count -= 1;
            self.windows_message_deliveries +|= 1;
            return message;
        }
        return null;
    }

    /// Reserve a properly aligned nested Windows callback frame.  The
    /// original DispatchMessage return address stays above the callback's
    /// 32-byte home area, so a WndProc can use the normal Microsoft x64 ABI.
    pub fn beginWindowsMessageDispatch(self: *ElfState, return_rip: u64, return_is_direct: bool) bool {
        if (self.windows_message_dispatch_frame_count >= self.windows_message_dispatch_frames.len) return false;
        const return_rsp = self.regs.rsp;
        if (return_rsp < 40) return false;
        const callback_rsp = return_rsp - 40;
        if (self.guestMemory(callback_rsp, 40) == null) return false;

        const frame_index = self.windows_message_dispatch_frame_count;
        self.windows_message_dispatch_frames[frame_index] = .{
            .return_rip = return_rip,
            .return_rsp = return_rsp,
            .return_is_direct = return_is_direct,
        };
        self.windows_message_dispatch_frame_count += 1;
        self.regs.rsp = callback_rsp;
        self.write64(callback_rsp, SYNTHETIC_WINDOWS_MESSAGE_RETURN);
        if (self.guestMemory(callback_rsp + 8, 32)) |home| @memset(home, 0);
        return true;
    }

    pub fn finishWindowsMessageDispatch(self: *ElfState) bool {
        if (self.windows_message_dispatch_frame_count == 0) {
            self.faulted = true;
            self.exit_code = 127;
            self.termination_reason = .runtime_invariant_failure;
            self.terminated = true;
            log.err("Windows message callback returned without a dispatch frame rip=0x{x}", .{self.regs.rip});
            return false;
        }
        const frame_index = self.windows_message_dispatch_frame_count - 1;
        const frame = self.windows_message_dispatch_frames[frame_index];
        self.windows_message_dispatch_frame_count = frame_index;
        const expected_callback_rsp = (frame.return_rsp -| 40) + 8;
        if ((self.trace_windows_messages or self.diagnose_abi) and !frame.return_is_direct and self.regs.rsp != expected_callback_rsp) {
            log.warn("Windows message callback changed stack unexpectedly callback_rsp=0x{x} expected_after_ret=0x{x} return_rsp=0x{x}", .{
                self.regs.rsp,
                expected_callback_rsp,
                frame.return_rsp,
            });
        }
        self.regs.rsp = if (frame.return_is_direct) frame.return_rsp else frame.return_rsp +| 8;
        self.regs.rip = frame.return_rip;
        return true;
    }

    /// Enter a WinMM CALLBACK_FUNCTION callback using a guest-only nested
    /// frame.  The callback has the normal 32-byte Microsoft home area plus
    /// one stack argument, while the original waveOutWrite continuation stays
    /// above it.  This mirrors the message-dispatch protocol but uses its own
    /// marker and frame stack so an audio completion can never consume a UI
    /// callback frame.
    pub fn beginWindowsAudioCallback(self: *ElfState, return_rip: u64, return_is_direct: bool) bool {
        if (self.windows_audio_callback_frame_count >= self.windows_audio_callback_frames.len) return false;
        const return_rsp = self.regs.rsp;
        if (return_rsp < 48) return false;
        const callback_rsp = return_rsp - 48;
        if (self.guestMemory(callback_rsp, 48) == null) return false;

        const frame_index = self.windows_audio_callback_frame_count;
        self.windows_audio_callback_frames[frame_index] = .{
            .return_rip = return_rip,
            .return_rsp = return_rsp,
            .return_is_direct = return_is_direct,
        };
        self.windows_audio_callback_frame_count += 1;
        self.regs.rsp = callback_rsp;
        self.write64(callback_rsp, SYNTHETIC_WINDOWS_AUDIO_RETURN);
        if (self.guestMemory(callback_rsp + 8, 32)) |home| @memset(home, 0);
        self.write64(callback_rsp + 40, 0);
        return true;
    }

    pub fn finishWindowsAudioCallback(self: *ElfState) bool {
        if (self.windows_audio_callback_frame_count == 0) {
            self.faulted = true;
            self.exit_code = 127;
            self.termination_reason = .runtime_invariant_failure;
            self.terminated = true;
            log.err("Windows audio callback returned without a callback frame rip=0x{x}", .{self.regs.rip});
            return false;
        }
        const frame_index = self.windows_audio_callback_frame_count - 1;
        const frame = self.windows_audio_callback_frames[frame_index];
        self.windows_audio_callback_frame_count = frame_index;
        const expected_callback_rsp = (frame.return_rsp -| 48) + 8;
        if ((self.trace_windows_audio or self.diagnose_abi) and !frame.return_is_direct and self.regs.rsp != expected_callback_rsp) {
            log.warn("Windows audio callback changed stack unexpectedly callback_rsp=0x{x} expected_after_ret=0x{x} return_rsp=0x{x}", .{
                self.regs.rsp,
                expected_callback_rsp,
                frame.return_rsp,
            });
        }
        self.regs.rsp = if (frame.return_is_direct) frame.return_rsp else frame.return_rsp +| 8;
        self.regs.rip = frame.return_rip;
        // waveOutWrite's return value is independent of the callback's
        // internal semaphore operation.
        self.regs.rax = 0;
        return true;
    }

    const windows_exception_frame_magic: u64 = 0x3148_4556_4553_4F52; // "ROSEVEH1"
    const windows_status_access_violation: u32 = 0xC000_0005;
    const windows_exception_continue_execution: u32 = 0xFFFF_FFFF;
    const windows_context_bytes: u64 = 0x4D0;
    const windows_exception_record_bytes: u64 = 0xA0;
    const windows_exception_header_bytes: u64 = 0x30;
    /// A handler that faults inside itself is dispatched again, as on
    /// Windows; past this depth Rosette stops and performs the access.
    const windows_exception_nesting_limit: u32 = 8;

    /// Record the protection a guest applied to a range.
    pub fn noteGuestPageProtection(
        self: *ElfState,
        address: u64,
        length: u64,
        protect: u32,
        api: []const u8,
        caller_rip: u64,
    ) void {
        const protection = guest_page_protection.fromWindows(protect) orelse {
            if ((protect & 0x100) != 0) {
                self.guest_page_protection_guard_requests +|= 1;
            } else if (protect != 0) {
                self.guest_page_protection_unmodelled_values +|= 1;
            }
            return;
        };
        const outcome = self.guest_page_protection.set(self.allocator, address, length, protection);
        if (outcome.allocation_failed) {
            log.warn("PE64 GUEST PAGE PROTECTION: could not allocate a protection page for [0x{x},+0x{x}) from {s}; accesses to it will not fault", .{ address, length, api });
        }
        // An accessible request has no fault semantics to enforce. Xenia's
        // context allocator makes one such request at a high candidate
        // address; reporting it as an unenforced protection warning obscures
        // the meaningful case, where PAGE_NOACCESS or PAGE_READONLY would
        // escape the table. Keep counting the request in the table for
        // diagnostics, but only emit the warning for a restriction that was
        // actually lost.
        if (outcome.outside_window and protection != .accessible and self.guest_page_protection.requests_outside_window == 1) {
            log.warn("PE64 GUEST PAGE PROTECTION: {s} asked for {s} at 0x{x}, above the 0x{x} window the table models; it is counted and not enforced", .{
                api,
                protection.label(),
                address,
                guest_page_protection.window_end,
            });
        }
        if (protection != .accessible and outcome.pages_changed != 0 and self.guest_page_protection_restrict_events < 16) {
            self.guest_page_protection_restrict_events += 1;
            var caller_text: [guest_symbol_text_bytes]u8 = undefined;
            log.info("PE64 GUEST PAGE PROTECTION: {s} made [0x{x},0x{x}) {s} ({d} page(s)) caller=0x{x} ({s}); an interpreted access that violates it now raises an access violation through the guest's vectored exception handler", .{
                api,
                address,
                address +| length,
                protection.label(),
                outcome.pages_changed,
                caller_rip,
                self.describeGuestAddressOrUnnamed(caller_rip, &caller_text),
            });
        }
    }

    pub fn clearGuestPageProtection(self: *ElfState, address: u64, length: u64) void {
        _ = self.guest_page_protection.set(self.allocator, address, length, .accessible);
    }

    /// The Windows `PAGE_*` value recorded for an address.
    pub fn guestPageProtectionFlags(self: *const ElfState, address: u64) u32 {
        return self.guest_page_protection.get(address).toWindows();
    }

    /// Note an interpreted access to a protected page, returning whether a
    /// store must be withheld.
    ///
    /// Only the first violation in an instruction is raised, as a CPU stops
    /// at its first faulting access.
    fn noteGuestOperandAccess(self: *ElfState, address: u64, size: Size, is_write: bool, value: u64) bool {
        const width: u8 = switch (size) {
            .bits8 => 1,
            .bits16 => 2,
            .bits32 => 4,
            .bits64 => 8,
        };
        if (!self.guest_page_protection.faults(address, width, is_write)) return false;
        if (self.guest_access_violation_pending) return is_write;
        self.guest_access_violation_pending = true;
        self.guest_access_violation = .{
            .address = address,
            .instruction_rip = self.last_instruction_rip,
            .value = value,
            .width = width,
            .is_write = is_write,
            .protection = self.guest_page_protection.get(address),
        };
        return is_write;
    }

    fn guestAccessViolationSite(self: *ElfState, page: u64) ?*GuestAccessViolationSite {
        for (self.guest_access_violation_sites[0..self.guest_access_violation_site_count]) |*site| {
            if (site.page == page) return site;
        }
        if (self.guest_access_violation_site_count >= self.guest_access_violation_sites.len) {
            self.guest_access_violation_site_overflow +|= 1;
            return null;
        }
        const site = &self.guest_access_violation_sites[self.guest_access_violation_site_count];
        self.guest_access_violation_site_count += 1;
        site.* = .{ .page = page, .first_step = self.executed_steps };
        return site;
    }

    /// Raise the pending access violation through the guest's vectored
    /// exception handler, or perform the access if nobody can take it.
    ///
    /// The fallback is the behaviour Rosette always had, so a process with
    /// protected pages and no handler - or a handler that declines - runs
    /// exactly as before and is merely counted.
    fn raiseGuestAccessViolation(self: *ElfState) void {
        const fault = self.guest_access_violation;
        self.guest_access_violation_pending = false;
        self.guest_access_violations_raised +|= 1;
        if (fault.is_write) {
            self.guest_access_violation_writes +|= 1;
        } else {
            self.guest_access_violation_reads +|= 1;
        }
        const page = fault.address & ~(guest_page_protection.page_size - 1);
        if (self.guestAccessViolationSite(page)) |site| {
            site.protection = fault.protection;
            if (fault.is_write) site.writes +|= 1 else site.reads +|= 1;
            site.last_rip = fault.instruction_rip;
            site.last_offset = fault.address - page;
            site.last_value = fault.value;
        }
        if (self.windows_vectored_exception_handler == 0) {
            self.guest_access_violations_without_handler +|= 1;
            self.completeSuppressedGuestAccess(fault.address, fault.width, fault.is_write, fault.value);
            return;
        }
        if (self.guest_exception_dispatches_in_flight >= windows_exception_nesting_limit) {
            self.guest_access_violations_nesting_refused +|= 1;
            self.completeSuppressedGuestAccess(fault.address, fault.width, fault.is_write, fault.value);
            return;
        }
        if (!self.enterWindowsExceptionDispatch(fault)) {
            self.guest_access_violations_frame_refused +|= 1;
            self.completeSuppressedGuestAccess(fault.address, fault.width, fault.is_write, fault.value);
            return;
        }
        self.guest_access_violations_dispatched +|= 1;
    }

    fn completeSuppressedGuestAccess(self: *ElfState, address: u64, width: u8, is_write: bool, value: u64) void {
        if (!is_write) return;
        switch (width) {
            1 => self.write8(address, @truncate(value)),
            2 => self.write16(address, @truncate(value)),
            4 => self.write32(address, @truncate(value)),
            else => self.write64(address, value),
        }
    }

    /// Call the guest's vectored exception handler with an access violation.
    ///
    /// The frame is built on the faulting thread's stack, below its current
    /// stack pointer, in the order `KiUserExceptionDispatcher` leaves it:
    ///
    ///   call_rsp        synthetic return address
    ///   +0x08..+0x28    home space for the handler's one argument
    ///   +0x28           Rosette header: magic, fault, post-instruction rip,
    ///                   withheld value, width and direction
    ///   +0x58           EXCEPTION_POINTERS
    ///   +0x68           EXCEPTION_RECORD
    ///   +0x108          CONTEXT (x64, 0x4D0 bytes)
    ///
    /// `call_rsp` is 8 modulo 16, as it is on entry to any function, so the
    /// header, the record and the CONTEXT are all 16-byte aligned. Nothing is
    /// kept on the host side: the return path reads the header back from the
    /// stack, so the frame belongs to the thread by construction.
    fn enterWindowsExceptionDispatch(self: *ElfState, fault: GuestAccessViolation) bool {
        const post_rip = self.regs.rip;
        if (self.regs.rsp < 0x10000) return false;
        const call_rsp = ((self.regs.rsp - 0x800) & ~@as(u64, 0xF)) - 8;
        const header = call_rsp + 0x28;
        const pointers = header + windows_exception_header_bytes;
        const record = pointers + 0x10;
        const context = record + windows_exception_record_bytes;
        const top = context + windows_context_bytes;
        const frame = self.guestMemory(call_rsp, top - call_rsp) orelse return false;
        @memset(frame, 0);

        self.write64(header, windows_exception_frame_magic);
        self.write64(header + 8, fault.address);
        self.write64(header + 16, post_rip);
        self.write64(header + 24, fault.value);
        self.write64(header + 32, @as(u64, fault.width) | (@as(u64, @intFromBool(fault.is_write)) << 8));

        self.write32(record, windows_status_access_violation);
        self.write64(record + 16, fault.instruction_rip); // ExceptionAddress
        self.write32(record + 24, 2); // NumberParameters
        self.write64(record + 32, @intFromBool(fault.is_write)); // 0 read, 1 write
        self.write64(record + 40, fault.address);

        self.writeGuestExceptionContext(context, fault.instruction_rip);

        self.write64(pointers, record);
        self.write64(pointers + 8, context);

        self.write64(call_rsp, SYNTHETIC_WINDOWS_EXCEPTION_RETURN);
        self.regs.rcx = pointers;
        self.regs.rsp = call_rsp;
        self.regs.rip = self.windows_vectored_exception_handler;
        self.guest_exception_dispatches_in_flight +|= 1;
        return true;
    }

    /// The x64 CONTEXT a Windows exception handler reads and rewrites.
    fn writeGuestExceptionContext(self: *ElfState, context: u64, rip: u64) void {
        self.write32(context + 0x30, 0x0010_001F); // CONTEXT_ALL (AMD64)
        self.write32(context + 0x34, self.regs.mxcsr);
        self.write16(context + 0x38, 0x33); // CS
        self.write16(context + 0x3a, 0x2b); // DS
        self.write16(context + 0x3c, 0x2b); // ES
        self.write16(context + 0x3e, 0x53); // FS
        self.write16(context + 0x40, 0x2b); // GS
        self.write16(context + 0x42, 0x2b); // SS
        self.write32(context + 0x44, self.regs.rflags);
        self.write64(context + 0x78, self.regs.rax);
        self.write64(context + 0x80, self.regs.rcx);
        self.write64(context + 0x88, self.regs.rdx);
        self.write64(context + 0x90, self.regs.rbx);
        self.write64(context + 0x98, self.regs.rsp);
        self.write64(context + 0xa0, self.regs.rbp);
        self.write64(context + 0xa8, self.regs.rsi);
        self.write64(context + 0xb0, self.regs.rdi);
        self.write64(context + 0xb8, self.regs.r8);
        self.write64(context + 0xc0, self.regs.r9);
        self.write64(context + 0xc8, self.regs.r10);
        self.write64(context + 0xd0, self.regs.r11);
        self.write64(context + 0xd8, self.regs.r12);
        self.write64(context + 0xe0, self.regs.r13);
        self.write64(context + 0xe8, self.regs.r14);
        self.write64(context + 0xf0, self.regs.r15);
        self.write64(context + 0xf8, rip);
        self.write32(context + 0x118, self.regs.mxcsr); // FltSave.MxCsr
        for (0..16) |index| {
            if (self.guestMemory(context + 0x1a0 + index * 16, 16)) |destination| {
                @memcpy(destination, &self.xmm[index]);
            }
        }
    }

    /// The handler returned. Take its verdict and its CONTEXT.
    fn finishWindowsExceptionDispatch(self: *ElfState) void {
        const header = self.regs.rsp +% 0x20;
        if (self.guestMemoryConst(header, windows_exception_header_bytes) == null or
            self.read64(header) != windows_exception_frame_magic)
        {
            self.faulted = true;
            self.exit_code = 127;
            self.termination_reason = .runtime_invariant_failure;
            self.terminated = true;
            log.err("PE64 GUEST ACCESS VIOLATION: a return reached the exception dispatch marker without Rosette's frame above it rsp=0x{x}; the handler did not return through the frame it was called with", .{self.regs.rsp});
            return;
        }
        const context = header + windows_exception_header_bytes + 0x10 + windows_exception_record_bytes;
        const verdict: u32 = @truncate(self.regs.rax);
        const fault_address = self.read64(header + 8);
        const post_rip = self.read64(header + 16);
        const value = self.read64(header + 24);
        const shape = self.read64(header + 32);
        const width: u8 = @truncate(shape);
        const is_write = ((shape >> 8) & 1) != 0;

        self.regs.rax = self.read64(context + 0x78);
        self.regs.rcx = self.read64(context + 0x80);
        self.regs.rdx = self.read64(context + 0x88);
        self.regs.rbx = self.read64(context + 0x90);
        self.regs.rsp = self.read64(context + 0x98);
        self.regs.rbp = self.read64(context + 0xa0);
        self.regs.rsi = self.read64(context + 0xa8);
        self.regs.rdi = self.read64(context + 0xb0);
        self.regs.r8 = self.read64(context + 0xb8);
        self.regs.r9 = self.read64(context + 0xc0);
        self.regs.r10 = self.read64(context + 0xc8);
        self.regs.r11 = self.read64(context + 0xd0);
        self.regs.r12 = self.read64(context + 0xd8);
        self.regs.r13 = self.read64(context + 0xe0);
        self.regs.r14 = self.read64(context + 0xe8);
        self.regs.r15 = self.read64(context + 0xf0);
        self.regs.rflags = self.read32(context + 0x44);
        for (0..16) |index| {
            if (self.guestMemoryConst(context + 0x1a0 + index * 16, 16)) |source| {
                @memcpy(&self.xmm[index], source[0..16]);
            }
        }
        self.guest_exception_dispatches_in_flight -|= 1;

        const page = fault_address & ~(guest_page_protection.page_size - 1);
        var site: ?*GuestAccessViolationSite = null;
        for (self.guest_access_violation_sites[0..self.guest_access_violation_site_count]) |*candidate| {
            if (candidate.page == page) site = candidate;
        }
        if (verdict == windows_exception_continue_execution) {
            self.regs.rip = self.read64(context + 0xf8);
            self.guest_access_violations_handled +|= 1;
            if (site) |record| record.handled +|= 1;
            return;
        }
        // EXCEPTION_CONTINUE_SEARCH. Windows would try frame handlers and
        // then end the process. Rosette performs the access it withheld and
        // continues after the instruction, which is the behaviour every run
        // before this one had - reported, so it is never mistaken for a
        // delivered fault.
        self.regs.rip = post_rip;
        self.completeSuppressedGuestAccess(fault_address, width, is_write, value);
        self.guest_access_violations_unhandled +|= 1;
        if (site) |record| {
            record.unhandled +|= 1;
            if (record.unhandled == 1) {
                log.warn("PE64 GUEST ACCESS VIOLATION: the vectored handler declined a {s} at 0x{x}; Windows would have terminated the process, Rosette performed the access and continued", .{
                    if (is_write) "write" else "read",
                    fault_address,
                });
            }
        }
    }

    pub fn addrToOffset(self: *const ElfState, vaddr: u64) ?u64 {
        if (vaddr < self.mem_base) return null;
        const off = vaddr - self.mem_base;
        if (off >= self.mem_size) return null;
        return off;
    }

    /// Classify one fixed `VirtualAlloc` against what already backs it, and
    /// record the answer.
    ///
    /// This is the reservation-versus-commit distinction the
    /// `guest-heap-commit-unreserved` failure point asks Rosetta not to
    /// lose. It changes no behaviour: the allocation still succeeds, because
    /// refusing a commit the guest has already convinced itself it may make
    /// would end a run over bookkeeping. It changes what the run can say.
    pub fn noteWindowsAllocationDisposition(
        self: *ElfState,
        requested_base: u64,
        length: u64,
        reserve_requested: bool,
        commit_requested: bool,
        served: bool,
        caller_rip: u64,
    ) WindowsAllocationDisposition {
        const span = @max(length, @as(u64, 1));
        const disposition: WindowsAllocationDisposition = blk: {
            if (!served) break :blk .refused;
            if (requested_base == 0) break :blk .reserved_new;
            if (reserve_requested and !commit_requested) {
                break :blk if (self.windowsVirtualAllocationContains(requested_base, span))
                    .reserve_over_existing
                else
                    .reserved_new;
            }
            if (!commit_requested) break :blk .reserved_new;
            // Commit. Which backing covers it decides everything.
            if (self.addrToOffset(requested_base) != null) break :blk .committed_in_image;
            if (self.windowsMappedRangeContains(requested_base, span)) break :blk .committed_in_mapped_view;
            if (self.windowsVirtualAllocationContains(requested_base, span)) break :blk .committed_in_reservation;
            break :blk .committed_unbacked;
        };
        self.windows_allocation_dispositions[@intFromEnum(disposition)] +|= 1;
        if (disposition == .committed_unbacked) {
            self.noteWindowsUnbackedCommit(requested_base, span, caller_rip);
        } else if (disposition == .refused) {
            self.noteWindowsAllocationRefusal(
                requested_base,
                span,
                reserve_requested,
                commit_requested,
                caller_rip,
            );
        }
        return disposition;
    }

    /// Move only the known Xenia CPU-context allocator to its next contract
    /// candidate. Generic fixed-address callers still receive the normal
    /// Windows failure on an occupied range; silently relocating those would
    /// change their pointer semantics. The ThreadState allocator, by contrast,
    /// explicitly walks this candidate sequence and only needs a unique slot.
    pub fn relocateWindowsThreadContextAllocation(
        self: *ElfState,
        requested_base: u64,
        length: u64,
        caller_rip: u64,
    ) ?u64 {
        if (!xenia_guest_address_map.isContextCandidate(requested_base)) return null;
        var caller_text: [guest_symbol_text_bytes]u8 = undefined;
        const caller = self.describeGuestAddressOrUnnamed(caller_rip, &caller_text);
        if (std.mem.indexOf(u8, caller, "xe::cpu::ThreadState") == null) return null;

        var candidate = requested_base;
        while (xenia_guest_address_map.nextContextCandidate(candidate)) |next| {
            candidate = next;
            if (self.windowsGuestRangeContains(candidate, length)) continue;
            if (self.createWindowsVirtualAllocation(candidate, length)) return candidate;
        }
        return null;
    }

    pub fn noteWindowsAllocationRelocation(
        self: *ElfState,
        requested_base: u64,
        actual_base: u64,
        length: u64,
        caller_rip: u64,
    ) WindowsAllocationDisposition {
        self.windows_allocation_dispositions[@intFromEnum(WindowsAllocationDisposition.relocated)] +|= 1;
        const accounting_step = self.totalInterpretedSteps();
        for (self.windows_allocation_relocations[0..self.windows_allocation_relocation_count]) |*record| {
            if (record.requested_base == requested_base and record.actual_base == actual_base and record.caller_rip == caller_rip) {
                record.occurrences +|= 1;
                record.last_step = accounting_step;
                return .relocated;
            }
        }
        if (self.windows_allocation_relocation_count >= self.windows_allocation_relocations.len) {
            for (self.windows_allocation_relocation_overflow_records[0..self.windows_allocation_relocation_overflow_record_count]) |*record| {
                if (record.requested_base == requested_base and record.actual_base == actual_base and record.caller_rip == caller_rip) {
                    record.occurrences +|= 1;
                    record.last_step = accounting_step;
                    self.windows_allocation_relocation_overflow +|= 1;
                    return .relocated;
                }
            }
            if (self.windows_allocation_relocation_overflow_record_count < self.windows_allocation_relocation_overflow_records.len) {
                const overflow_record = &self.windows_allocation_relocation_overflow_records[self.windows_allocation_relocation_overflow_record_count];
                overflow_record.* = .{
                    .requested_base = requested_base,
                    .actual_base = actual_base,
                    .length = length,
                    .caller_rip = caller_rip,
                    .step = accounting_step,
                    .last_step = accounting_step,
                    .occurrences = 1,
                };
                self.windows_allocation_relocation_overflow_record_count += 1;
            }
            self.windows_allocation_relocation_overflow +|= 1;
            return .relocated;
        }
        const record = &self.windows_allocation_relocations[self.windows_allocation_relocation_count];
        record.* = .{
            .requested_base = requested_base,
            .actual_base = actual_base,
            .length = length,
            .caller_rip = caller_rip,
            .step = accounting_step,
            .last_step = accounting_step,
            .occurrences = 1,
        };
        self.windows_allocation_relocation_count += 1;
        var caller_text: [guest_symbol_text_bytes]u8 = undefined;
        log.info("PE64 Windows memory contract: fixed allocation relocated requested=0x{x} actual=0x{x} length={d} step={d} caller=0x{x} ({s}); the Xenia context allocator received the next unique candidate", .{
            requested_base,
            actual_base,
            length,
            accounting_step,
            caller_rip,
            self.describeGuestAddressOrUnnamed(caller_rip, &caller_text),
        });
        return .relocated;
    }

    fn noteWindowsUnbackedCommit(self: *ElfState, base: u64, length: u64, caller_rip: u64) void {
        for (self.windows_unbacked_commits[0..self.windows_unbacked_commit_count]) |*record| {
            if (record.caller_rip == caller_rip) {
                record.occurrences +|= 1;
                return;
            }
        }
        if (self.windows_unbacked_commit_count >= self.windows_unbacked_commits.len) {
            self.windows_unbacked_commit_overflow +|= 1;
            return;
        }
        const record = &self.windows_unbacked_commits[self.windows_unbacked_commit_count];
        record.* = .{
            .base = base,
            .length = length,
            .caller_rip = caller_rip,
            .step = self.executed_steps,
            .occurrences = 1,
        };
        self.windows_unbacked_commit_count += 1;
        var caller_text: [guest_symbol_text_bytes]u8 = undefined;
        log.info("PE64 Windows memory contract: commit on unreserved address base=0x{x} length={d} step={d} caller=0x{x} ({s}); Windows would have failed this with ERROR_INVALID_ADDRESS, Rosette serves it and records the divergence rather than ending the run over bookkeeping the guest has already lost", .{
            base,
            length,
            self.executed_steps,
            caller_rip,
            self.describeGuestAddressOrUnnamed(caller_rip, &caller_text),
        });
    }

    fn noteWindowsAllocationRefusal(
        self: *ElfState,
        requested_base: u64,
        length: u64,
        reserve_requested: bool,
        commit_requested: bool,
        caller_rip: u64,
    ) void {
        const reason: WindowsAllocationRefusalReason = if (requested_base != 0 and reserve_requested and
            self.windowsVirtualAllocationContains(requested_base, length))
            .reserve_over_existing
        else
            .allocation_backend_refused;
        for (self.windows_allocation_refusals[0..self.windows_allocation_refusal_count]) |*record| {
            if (record.caller_rip == caller_rip and record.reason == reason) {
                record.occurrences +|= 1;
                return;
            }
        }
        if (self.windows_allocation_refusal_count >= self.windows_allocation_refusals.len) {
            self.windows_allocation_refusal_overflow +|= 1;
            return;
        }
        const record = &self.windows_allocation_refusals[self.windows_allocation_refusal_count];
        record.* = .{
            .base = requested_base,
            .length = length,
            .caller_rip = caller_rip,
            .step = self.executed_steps,
            .occurrences = 1,
            .reason = reason,
            .reserve_requested = reserve_requested,
            .commit_requested = commit_requested,
        };
        self.windows_allocation_refusal_count += 1;
        var caller_text: [guest_symbol_text_bytes]u8 = undefined;
        log.info("PE64 Windows memory contract: allocation refusal: reason={s} base=0x{x} length={d} reserve={} commit={} step={d} caller=0x{x} ({s}); this request was not served and remains distinct from a commit Rosette promoted", .{
            reason.label(),
            requested_base,
            length,
            reserve_requested,
            commit_requested,
            self.executed_steps,
            caller_rip,
            self.describeGuestAddressOrUnnamed(caller_rip, &caller_text),
        });
    }

    /// What every fixed allocation this run made was, relative to its backing.
    pub fn reportWindowsMemoryContract(self: *const ElfState) void {
        var total: u64 = 0;
        for (self.windows_allocation_dispositions) |count| total +|= count;
        if (total == 0) return;
        log.info("PE64 MEMORY CONTRACT: {d} fixed allocation request(s); a commit is only sound when something already backs its address", .{total});
        inline for (@typeInfo(WindowsAllocationDisposition).@"enum".fields) |field| {
            const disposition: WindowsAllocationDisposition = @enumFromInt(field.value);
            const count = self.windows_allocation_dispositions[field.value];
            if (count != 0) {
                log.info("PE64 MEMORY CONTRACT:   {s:<26} {d}{s}", .{
                    disposition.label(),
                    count,
                    if (disposition.divergesFromWindows()) "  <- Windows would have failed these" else "",
                });
            }
        }
        for (self.windows_allocation_refusals[0..self.windows_allocation_refusal_count]) |*record| {
            var caller_text: [guest_symbol_text_bytes]u8 = undefined;
            log.info("PE64 MEMORY CONTRACT:   refusal x{d} reason={s} base=0x{x} length={d} reserve={} commit={} first_step={d} caller={s}", .{
                record.occurrences,
                record.reason.label(),
                record.base,
                record.length,
                record.reserve_requested,
                record.commit_requested,
                record.step,
                self.describeGuestAddressOrUnnamed(record.caller_rip, &caller_text),
            });
        }
        for (self.windows_allocation_relocations[0..self.windows_allocation_relocation_count]) |*record| {
            var caller_text: [guest_symbol_text_bytes]u8 = undefined;
            log.info("PE64 MEMORY CONTRACT:   relocated x{d} requested=0x{x} actual=0x{x} length={d} first_step={d} last_step={d} caller={s}", .{
                record.occurrences,
                record.requested_base,
                record.actual_base,
                record.length,
                record.step,
                record.last_step,
                self.describeGuestAddressOrUnnamed(record.caller_rip, &caller_text),
            });
        }
        if (self.windows_allocation_relocation_overflow != 0) {
            log.info("PE64 MEMORY CONTRACT:   {d} further relocation request(s) exceeded the primary bounded table; retained_overflow_sites={d} digest_capacity={d}", .{
                self.windows_allocation_relocation_overflow,
                self.windows_allocation_relocation_overflow_record_count,
                self.windows_allocation_relocation_overflow_records.len,
            });
            for (self.windows_allocation_relocation_overflow_records[0..self.windows_allocation_relocation_overflow_record_count]) |*record| {
                var caller_text: [guest_symbol_text_bytes]u8 = undefined;
                log.info("PE64 MEMORY CONTRACT:     overflow_digest x{d} requested=0x{x} actual=0x{x} length={d} first_step={d} last_step={d} caller={s}", .{
                    record.occurrences,
                    record.requested_base,
                    record.actual_base,
                    record.length,
                    record.step,
                    record.last_step,
                    self.describeGuestAddressOrUnnamed(record.caller_rip, &caller_text),
                });
            }
        }
        if (self.windows_allocation_refusal_overflow != 0) {
            log.info("PE64 MEMORY CONTRACT:   {d} further refusal site(s) did not fit the bounded table", .{self.windows_allocation_refusal_overflow});
        }
        // A generic refusal is still a real finding. Xenia's
        // `AllocateContext` is handled above by giving it the next candidate
        // in its own `pos32` sequence, so a remaining reserve conflict now
        // identifies a caller Rosetta has not yet safely mapped.
        var reserve_conflicts: u64 = 0;
        var other_refusals: u64 = 0;
        for (self.windows_allocation_refusals[0..self.windows_allocation_refusal_count]) |*record| {
            if (record.reason == .reserve_over_existing) {
                reserve_conflicts +|= record.occurrences;
            } else {
                other_refusals +|= record.occurrences;
            }
        }
        if (reserve_conflicts != 0) {
            log.info("PE64 MEMORY CONTRACT:   {d} reserve-over-existing request(s) remain after known Xenia context relocation; these are unresolved fixed-address callers and require a new mapping policy", .{reserve_conflicts});
        }
        if (other_refusals != 0) {
            log.info("PE64 MEMORY CONTRACT:   {d} refusal(s) were NOT an occupancy conflict - Rosette could not back the range at all, which is a finding", .{other_refusals});
        }
        if (self.windows_unbacked_commit_count == 0) {
            log.info("PE64 MEMORY CONTRACT:   verdict: every commit landed inside something that already backed it", .{});
            return;
        }
        var caller_text: [guest_symbol_text_bytes]u8 = undefined;
        for (self.windows_unbacked_commits[0..self.windows_unbacked_commit_count]) |*record| {
            log.info("PE64 MEMORY CONTRACT:   unbacked commit x{d} base=0x{x} length={d} first_step={d} caller={s}", .{
                record.occurrences,
                record.base,
                record.length,
                record.step,
                self.describeGuestAddressOrUnnamed(record.caller_rip, &caller_text),
            });
        }
        if (self.windows_unbacked_commit_overflow != 0) {
            log.info("PE64 MEMORY CONTRACT:   {d} further unbacked commit site(s) did not fit the bounded table", .{self.windows_unbacked_commit_overflow});
        }
        log.info("PE64 MEMORY CONTRACT:   verdict: {d} commit site(s) had no reservation behind them. Xenia's own BaseHeap prints `attempting commit on unreserved page` for the same condition and then promotes the request; the two ledgers now agree on which addresses those are", .{self.windows_unbacked_commit_count});
    }

    fn trimWindowsFileMappingCount(self: *ElfState) void {
        while (self.windows_file_mapping_count != 0 and
            self.windows_file_mappings[self.windows_file_mapping_count - 1].backing == null)
        {
            self.windows_file_mapping_count -= 1;
        }
    }

    fn trimWindowsMemoryViewCount(self: *ElfState) void {
        while (self.windows_memory_view_count != 0 and
            self.windows_memory_views[self.windows_memory_view_count - 1].length == 0)
        {
            self.windows_memory_view_count -= 1;
        }
    }

    fn trimWindowsVirtualAllocationCount(self: *ElfState) void {
        while (self.windows_virtual_allocation_count != 0 and
            self.windows_virtual_allocations[self.windows_virtual_allocation_count - 1].backing == null)
        {
            self.windows_virtual_allocation_count -= 1;
        }
    }

    /// The PE runner switches this on only for an explicitly requested full
    /// instruction-ring capture. The always-useful last RIP remains updated
    /// even when the ring is disabled.
    pub fn configureWindowsTraceRing(self: *ElfState) void {
        self.trace_ring_enabled = envFlag("ROSETTE_ELF_TRACE_RING");
    }

    /// Install the PE loader's executable section map before the image starts
    /// executing.  A missing range is a conservative fallback: decodeAt
    /// keeps its byte comparison whenever this table is empty, so an image
    /// route can never trade correctness for a cache hit.
    pub fn configureWindowsExecutableRanges(
        self: *ElfState,
        ranges: []const WindowsExecutableRange,
    ) void {
        self.windows_executable_range_count = @min(ranges.len, self.windows_executable_ranges.len);
        for (self.windows_executable_ranges[0..self.windows_executable_range_count], 0..) |*destination, index| {
            destination.* = ranges[index];
        }
        for (self.windows_executable_ranges[self.windows_executable_range_count..]) |*destination| {
            destination.* = .{};
        }
    }

    pub fn windowsVirtualAllocationContains(self: *const ElfState, address: u64, count: u64) bool {
        const end = std.math.add(u64, address, count) catch return false;
        for (self.windows_virtual_allocations[0..self.windows_virtual_allocation_count]) |allocation| {
            if (allocation.length == 0 or allocation.backing == null or address < allocation.guest_base) continue;
            const allocation_end = std.math.add(u64, allocation.guest_base, allocation.length) catch continue;
            if (end <= allocation_end) return true;
        }
        return false;
    }

    fn windowsMappedRangeContains(self: *const ElfState, address: u64, count: u64) bool {
        const end = std.math.add(u64, address, count) catch return false;
        for (self.windows_memory_views[0..self.windows_memory_view_count]) |view| {
            if (view.length == 0 or address < view.guest_base) continue;
            const view_end = std.math.add(u64, view.guest_base, view.length) catch continue;
            if (end <= view_end) return true;
        }
        return false;
    }

    pub fn windowsGuestRangeContains(self: *const ElfState, address: u64, count: u64) bool {
        if (count == 0) return true;
        if (self.addrToOffset(address)) |offset| {
            const count_usize = std.math.cast(usize, count) orelse return false;
            const offset_usize = std.math.cast(usize, offset) orelse return false;
            return offset_usize <= self.mem.len and count_usize <= self.mem.len - offset_usize;
        }
        if (self.windowsMappedRangeContains(address, count)) return true;
        if (self.windowsVirtualAllocationContains(address, count)) return true;
        if (self.nativeMemoryAlias(address, count) != null) return true;
        return false;
    }

    fn nativeMemoryAlias(self: *const ElfState, address: u64, count: u64) ?[]u8 {
        if (address < native_alias_address_base or address >= native_alias_address_limit) return null;
        const length = std.math.cast(usize, count) orelse return null;
        for (self.native_memory_aliases[0..self.native_memory_alias_count]) |alias| {
            const bytes = alias.bytes orelse continue;
            if (address < alias.guest_base) continue;
            const offset = std.math.cast(usize, address - alias.guest_base) orelse continue;
            if (offset <= bytes.len and length <= bytes.len - offset) return bytes[offset..][0..length];
        }
        return null;
    }

    pub fn borrowNativeMemory(self: *ElfState, bytes: []u8) ?u64 {
        if (bytes.len == 0 or bytes.len > 64 * 1024 * 1024) return null;
        // Preserve the native pointer's low 32 bits. Therefore guest_pointer
        // minus map offset retains every native alignment up to 4 GiB. These
        // are address-space slots only: no multi-gigabyte backing is allocated.
        const native_low = @intFromPtr(bytes.ptr) & (native_alias_alignment - 1);
        const span = std.mem.alignForward(u64, @as(u64, @intCast(bytes.len)) + native_low, native_alias_alignment);
        for (&self.native_memory_aliases, 0..) |*alias, index| {
            if (alias.bytes != null or alias.reserved_span < span or !self.windowsViewRangeIsFree(alias.slot_base, span)) continue;
            alias.guest_base = alias.slot_base + native_low;
            alias.bytes = bytes;
            self.native_memory_alias_count = @max(self.native_memory_alias_count, index + 1);
            return alias.guest_base;
        }
        var candidate = self.native_memory_alias_next;
        // Bounded address search. Guest mappings can legitimately occupy a
        // candidate; never overlap them or silently change their ownership.
        for (0..256) |_| {
            const next = std.math.add(u64, candidate, span + native_alias_alignment) catch return null;
            if (next > native_alias_address_limit) return null;
            if (self.windowsViewRangeIsFree(candidate, span)) {
                for (&self.native_memory_aliases, 0..) |*alias, index| {
                    if (alias.bytes != null) continue;
                    alias.* = .{ .guest_base = candidate + native_low, .bytes = bytes, .reserved_span = span, .slot_base = candidate };
                    self.native_memory_alias_count = @max(self.native_memory_alias_count, index + 1);
                    self.native_memory_alias_next = next;
                    return alias.guest_base;
                }
                return null;
            }
            candidate = next;
        }
        return null;
    }

    pub fn releaseNativeMemory(self: *ElfState, guest_base: u64) void {
        for (self.native_memory_aliases[0..self.native_memory_alias_count]) |*alias| {
            if (alias.guest_base == guest_base) alias.bytes = null;
        }
        while (self.native_memory_alias_count != 0 and self.native_memory_aliases[self.native_memory_alias_count - 1].bytes == null) self.native_memory_alias_count -= 1;
    }

    fn windowsMappingIndex(self: *const ElfState, handle: u64) ?usize {
        if (handle == 0) return null;
        for (self.windows_file_mappings[0..self.windows_file_mapping_count], 0..) |mapping, index| {
            if (mapping.guest_handle == handle and mapping.backing != null) return index;
        }
        return null;
    }

    fn windowsViewRangeIsFree(self: *const ElfState, guest_base: u64, length: u64) bool {
        const end = std.math.add(u64, guest_base, length) catch return false;
        const ordinary_end = std.math.add(u64, self.mem_base, self.mem_size) catch std.math.maxInt(u64);
        if (guest_base < ordinary_end and end > self.mem_base) return false;
        for (self.native_memory_aliases[0..self.native_memory_alias_count]) |alias| {
            const bytes = alias.bytes orelse continue;
            if (guest_base < alias.guest_base + bytes.len and end > alias.guest_base) return false;
        }
        for (self.windows_memory_views[0..self.windows_memory_view_count]) |view| {
            if (view.length == 0) continue;
            const view_end = std.math.add(u64, view.guest_base, view.length) catch std.math.maxInt(u64);
            if (guest_base < view_end and end > view.guest_base) return false;
        }
        for (self.windows_virtual_allocations[0..self.windows_virtual_allocation_count]) |allocation| {
            if (allocation.length == 0) continue;
            const allocation_end = std.math.add(u64, allocation.guest_base, allocation.length) catch std.math.maxInt(u64);
            if (guest_base < allocation_end and end > allocation.guest_base) return false;
        }
        return true;
    }

    fn windowsMappingHasViews(self: *const ElfState, mapping_index: usize) bool {
        for (self.windows_memory_views[0..self.windows_memory_view_count]) |view| {
            if (view.length != 0 and view.mapping_index == mapping_index) return true;
        }
        return false;
    }

    fn releaseClosedWindowsMapping(self: *ElfState, mapping_index: usize) void {
        const mapping = &self.windows_file_mappings[mapping_index];
        if (!mapping.closed or self.windowsMappingHasViews(mapping_index)) return;
        if (mapping.backing) |backing| std.posix.munmap(backing);
        mapping.* = .{};
        self.trimWindowsFileMappingCount();
    }

    /// Create the Rosetta backing for a Windows file mapping.  When the
    /// Win32 handle names an authorized guest file, preserve that file's
    /// contents through a host `mmap` rather than silently replacing it with
    /// anonymous zero pages.  A zero maximum size means "the current file
    /// size" for CreateFileMapping; this is the path used by Xenia's
    /// `MappedMemory::Open` for an XISO.
    pub fn createWindowsMemoryMapping(
        self: *ElfState,
        handle: u64,
        requested_length: u64,
        source_handle: u64,
    ) bool {
        if (handle == 0 or requested_length == std.math.maxInt(u64)) return false;

        var host_fd: std.posix.fd_t = -1;
        var file_size: ?u64 = null;
        var media_authorized = false;
        if (source_handle != std.math.maxInt(u64)) {
            const io = self.windows_host_io orelse return false;
            for (self.windows_files) |slot| {
                if (slot.file == null or slot.guest_handle != source_handle) continue;
                if (!slot.readable) return false;
                const stat = slot.file.?.stat(io) catch return false;
                host_fd = slot.file.?.handle;
                file_size = stat.size;
                media_authorized = slot.media_authorized;
                break;
            }
            if (host_fd < 0) return false;
        }

        var effective_length = requested_length;
        if (file_size) |size| {
            if (effective_length == 0) effective_length = size;
            if (effective_length > size) return false;
        }
        if (effective_length == 0) return false;

        const inclusive_length = std.math.add(u64, effective_length, 1) catch return false;
        const page_size: u64 = @intCast(std.heap.page_size_min);
        const rounded_length = std.math.add(u64, inclusive_length, page_size - 1) catch return false;
        const mapping_length = rounded_length & ~(page_size - 1);
        const length: usize = std.math.cast(usize, mapping_length) orelse return false;
        const prot: std.posix.PROT = if (file_size != null)
            @bitCast(@as(u32, 0x1))
        else
            @bitCast(@as(u32, 0x1 | 0x2));
        const flags: std.posix.MAP = if (file_size != null)
            @bitCast(@as(u32, 0x2))
        else
            @bitCast(@as(u32, 0x1000 | 0x2));
        const backing = std.posix.mmap(null, length, prot, flags, host_fd, 0) catch |err| {
            log.err("PE64 Windows CreateFileMapping failed: handle=0x{x} requested_length={d} mapped_length={d} reason={s}", .{
                handle,
                effective_length,
                mapping_length,
                @errorName(err),
            });
            return false;
        };

        for (&self.windows_file_mappings, 0..) |*mapping, mapping_index| {
            if (mapping.backing == null) {
                mapping.* = .{
                    .guest_handle = handle,
                    .length = mapping_length,
                    .backing = backing,
                    .media_authorized = media_authorized,
                };
                if (mapping_index >= self.windows_file_mapping_count) {
                    self.windows_file_mapping_count = mapping_index + 1;
                }
                if (media_authorized and self.windows_media_mapping_trace_events < 8) {
                    self.windows_media_mapping_trace_events += 1;
                    log.info("PE64 Windows media mapping: handle=0x{x} source_handle=0x{x} requested_length={d} mapped_length={d} backing=0x{x}", .{
                        handle,
                        source_handle,
                        effective_length,
                        mapping_length,
                        @intFromPtr(backing.ptr),
                    });
                }
                if (self.diagnose_abi) {
                    log.info("PE64 Windows CreateFileMapping: handle=0x{x} source_handle=0x{x} file_backed={} requested_length={d} mapped_length={d} backing=0x{x}", .{
                        handle,
                        source_handle,
                        file_size != null,
                        effective_length,
                        mapping_length,
                        @intFromPtr(backing.ptr),
                    });
                }
                if (self.trace_windows_mappings and self.windows_mapping_trace_events < 16) {
                    self.windows_mapping_trace_events += 1;
                    log.info("PE64 Windows mapping trace: create index={d} handle=0x{x} source_handle=0x{x} length={d} backing=0x{x} file_backed={}", .{
                        mapping_index,
                        handle,
                        source_handle,
                        mapping_length,
                        @intFromPtr(backing.ptr),
                        file_size != null,
                    });
                }
                return true;
            }
        }
        std.posix.munmap(backing);
        self.noteWindowsFileMappingTableFull(handle);
        return false;
    }

    /// Reserve/commit a fixed anonymous Windows range.  The native Xenia
    /// build uses VirtualAlloc for memory outside its file mapping (the code
    /// cache's 0x80000000 indirection table is the first such allocation),
    /// so returning a normal Rosetta heap address would silently corrupt the
    /// pointer contract.  A sparse host mapping gives those exact guest
    /// addresses real storage without reserving the range in the host VM.
    pub fn createWindowsVirtualAllocation(self: *ElfState, guest_base: u64, requested_length: u64) bool {
        if (guest_base == 0 or requested_length == 0) return false;
        // A driver-owned Vulkan alias is not a VirtualAlloc reservation.
        if (self.nativeMemoryAlias(guest_base, 1) != null) return false;
        const page_size: u64 = @intCast(std.heap.page_size_min);
        if (guest_base % page_size != 0) return false;
        const rounded_length = std.math.add(u64, requested_length, page_size - 1) catch return false;
        const allocation_length = rounded_length & ~(page_size - 1);
        if (self.windowsGuestRangeContains(guest_base, allocation_length)) return true;
        if (!self.windowsViewRangeIsFree(guest_base, allocation_length)) return false;
        const length = std.math.cast(usize, allocation_length) orelse return false;
        const prot: std.posix.PROT = @bitCast(@as(u32, 0x1 | 0x2));
        const flags: std.posix.MAP = @bitCast(@as(u32, 0x1000 | 0x2));
        const backing = std.posix.mmap(null, length, prot, flags, -1, 0) catch |err| {
            log.err("PE64 Windows VirtualAlloc fixed mapping failed: guest_base=0x{x} requested_length={d} mapped_length={d} reason={s}", .{
                guest_base,
                requested_length,
                allocation_length,
                @errorName(err),
            });
            return false;
        };

        for (&self.windows_virtual_allocations, 0..) |*allocation, allocation_index| {
            if (allocation.backing == null) {
                if (!self.indexWindowsMappedRange(.{
                    .base = guest_base,
                    .length = allocation_length,
                    .kind = .virtual_allocation,
                    .slot = allocation_index,
                })) {
                    std.posix.munmap(backing);
                    return false;
                }
                allocation.* = .{
                    .guest_base = guest_base,
                    .length = allocation_length,
                    .backing = backing,
                };
                if (allocation_index >= self.windows_virtual_allocation_count) {
                    self.windows_virtual_allocation_count = allocation_index + 1;
                }
                if (self.diagnose_abi) {
                    log.info("PE64 Windows VirtualAlloc fixed: guest_base=0x{x} requested_length={d} mapped_length={d} backing=0x{x}", .{
                        guest_base,
                        requested_length,
                        allocation_length,
                        @intFromPtr(backing.ptr),
                    });
                }
                return true;
            }
        }
        std.posix.munmap(backing);
        log.err("PE64 Windows VirtualAlloc rejected: allocation table exhausted guest_base=0x{x} length={d}", .{ guest_base, allocation_length });
        return false;
    }

    pub fn releaseWindowsVirtualAllocation(self: *ElfState, guest_base: u64, requested_length: u64, allocation_type: u64) bool {
        const release_type: u64 = 0x8000; // MEM_RELEASE
        if ((allocation_type & release_type) == 0) return self.windowsGuestRangeContains(guest_base, requested_length);
        for (self.windows_virtual_allocations[0..self.windows_virtual_allocation_count], 0..) |*allocation, allocation_index| {
            if (allocation.backing == null or allocation.guest_base != guest_base) continue;
            const expected_length = if (requested_length == 0) allocation.length else requested_length;
            if (requested_length != 0 and expected_length > allocation.length) return false;
            self.windows_mapped_ranges.remove(.virtual_allocation, allocation_index);
            self.invalidateMappedDecodeCache();
            if (allocation.backing) |backing| std.posix.munmap(backing);
            allocation.* = .{};
            self.trimWindowsVirtualAllocationCount();
            if (self.diagnose_abi) log.info("PE64 Windows VirtualFree release: guest_base=0x{x} length={d}", .{ guest_base, expected_length });
            return true;
        }
        return false;
    }

    /// Publish one guest view of a Windows mapping.  The returned value is a
    /// guest address, never the host backing pointer.  A fixed view that
    /// overlaps the PE's ordinary address range is rejected just as the real
    /// Windows VM would reject Xenia's first candidate; Xenia then retries at
    /// its next 8 GiB placement.
    pub fn mapWindowsMemoryView(
        self: *ElfState,
        handle: u64,
        requested_base: u64,
        requested_length: u64,
        backing_offset: u64,
    ) ?u64 {
        const mapping_index = self.windowsMappingIndex(handle) orelse return null;
        const mapping = self.windows_file_mappings[mapping_index];
        if (backing_offset % @as(u64, @intCast(std.heap.page_size_min)) != 0) return null;
        if (backing_offset >= mapping.length) return null;
        const length = if (requested_length == 0)
            mapping.length - backing_offset
        else
            requested_length;
        if (length == 0) return null;
        const end_offset = std.math.add(u64, backing_offset, length) catch return null;
        if (end_offset > mapping.length) return null;

        var guest_base = requested_base;
        if (guest_base == 0) {
            const alignment: u64 = 0x1_0000;
            guest_base = (self.windows_next_memory_view_base + alignment - 1) & ~(alignment - 1);
            while (!self.windowsViewRangeIsFree(guest_base, length)) {
                guest_base = std.math.add(u64, guest_base, alignment) catch return null;
            }
            self.windows_next_memory_view_base = std.math.add(u64, guest_base, length) catch return null;
        } else if (guest_base % @as(u64, @intCast(std.heap.page_size_min)) != 0) {
            return null;
        }
        if (!self.windowsViewRangeIsFree(guest_base, length)) return null;

        for (&self.windows_memory_views, 0..) |*view, view_index| {
            if (view.length == 0) {
                if (!self.indexWindowsMappedRange(.{
                    .base = guest_base,
                    .length = length,
                    .kind = .memory_view,
                    .slot = view_index,
                })) return null;
                view.* = .{
                    .guest_base = guest_base,
                    .length = length,
                    .mapping_index = mapping_index,
                    .backing_offset = backing_offset,
                };
                if (view_index >= self.windows_memory_view_count) {
                    self.windows_memory_view_count = view_index + 1;
                }
                if (guest_base == 0xA000_0000 and backing_offset == 0 and
                    length >= 0x0FFF_F000)
                {
                    self.windows_code_cache_view = view_index;
                }
                const media_mapping = self.windows_file_mappings[mapping_index];
                if (media_mapping.media_authorized and self.windows_media_mapping_trace_events < 8) {
                    self.windows_media_mapping_trace_events += 1;
                    log.info("PE64 Windows media view: mapping=0x{x} guest_base=0x{x} length={d} backing_offset=0x{x}", .{
                        handle,
                        guest_base,
                        length,
                        backing_offset,
                    });
                }
                if (self.diagnose_abi) {
                    log.info("PE64 Windows MapViewOfFile: handle=0x{x} guest_base=0x{x} length={d} backing_offset=0x{x}", .{
                        handle,
                        guest_base,
                        length,
                        backing_offset,
                    });
                }
                if (self.trace_windows_mappings and self.windows_mapping_trace_events < 16) {
                    self.windows_mapping_trace_events += 1;
                    log.info("PE64 Windows mapping trace: view event={d} mapping_index={d} handle=0x{x} guest_base=0x{x} length={d} backing_offset=0x{x} backing=0x{x}", .{
                        self.windows_mapping_trace_events,
                        mapping_index,
                        handle,
                        guest_base,
                        length,
                        backing_offset,
                        @intFromPtr(mapping.backing.?.ptr),
                    });
                }
                return guest_base;
            }
        }
        log.err("PE64 Windows MapViewOfFile rejected: view table exhausted handle=0x{x} guest_base=0x{x} length={d}", .{ handle, guest_base, length });
        return null;
    }

    pub fn unmapWindowsMemoryView(self: *ElfState, guest_base: u64) bool {
        for (self.windows_memory_views[0..self.windows_memory_view_count], 0..) |*view, view_index| {
            if (view.length == 0 or view.guest_base != guest_base) continue;
            const mapping_index = view.mapping_index;
            self.windows_mapped_ranges.remove(.memory_view, view_index);
            self.invalidateMappedDecodeCache();
            if (self.windows_code_cache_view == view_index) self.windows_code_cache_view = null;
            view.* = .{};
            self.trimWindowsMemoryViewCount();
            self.releaseClosedWindowsMapping(mapping_index);
            if (self.diagnose_abi) log.info("PE64 Windows UnmapViewOfFile: guest_base=0x{x}", .{guest_base});
            return true;
        }
        return false;
    }

    pub fn closeWindowsMemoryMapping(self: *ElfState, handle: u64) bool {
        const mapping_index = self.windowsMappingIndex(handle) orelse return false;
        self.windows_file_mappings[mapping_index].closed = true;
        self.releaseClosedWindowsMapping(mapping_index);
        if (self.diagnose_abi) log.info("PE64 Windows CloseHandle mapping: handle=0x{x} views_remaining={}", .{ handle, self.windowsMappingHasViews(mapping_index) });
        return true;
    }

    fn windowsMappedMemoryConst(self: *const ElfState, address: u64, count: u64) ?[]const u8 {
        if (self.nativeMemoryAlias(address, count)) |bytes| return bytes;
        if (self.windowsIndexedMemory(address, count)) |slice| return slice.bytes;
        if (count > std.math.maxInt(usize)) return null;
        const end = std.math.add(u64, address, count) catch return null;
        const count_usize: usize = @intCast(count);
        for (self.windows_memory_views[0..self.windows_memory_view_count]) |view| {
            if (view.length == 0 or address < view.guest_base) continue;
            const view_end = std.math.add(u64, view.guest_base, view.length) catch continue;
            if (end > view_end) continue;
            const mapping = self.windows_file_mappings[view.mapping_index];
            const backing = mapping.backing orelse continue;
            const backing_offset = std.math.add(u64, view.backing_offset, address - view.guest_base) catch return null;
            const offset: usize = std.math.cast(usize, backing_offset) orelse return null;
            if (offset > backing.len or count_usize > backing.len - offset) return null;
            return backing[offset..][0..count_usize];
        }
        for (self.windows_virtual_allocations[0..self.windows_virtual_allocation_count]) |allocation| {
            if (allocation.length == 0 or address < allocation.guest_base) continue;
            const allocation_end = std.math.add(u64, allocation.guest_base, allocation.length) catch continue;
            if (end > allocation_end) continue;
            const backing = allocation.backing orelse continue;
            const offset = std.math.cast(usize, address - allocation.guest_base) orelse return null;
            if (offset > backing.len or count_usize > backing.len - offset) return null;
            return backing[offset..][0..count_usize];
        }
        return null;
    }

    /// Resolve instruction bytes from a Rosette-owned Windows mapping. Xenia's
    /// JIT code cache lives outside the PE image (commonly at
    /// 0xa0000000), so treating every non-image RIP as a decode failure stops
    /// immediately after the first native Vulkan frame is submitted.
    fn windowsMappedCodeMemoryConst(self: *const ElfState, address: u64, count: u64) ?WindowsMappedCodeSlice {
        if (count > std.math.maxInt(usize)) return null;
        const end = std.math.add(u64, address, count) catch return null;
        const count_usize: usize = @intCast(count);
        if (self.windows_code_cache_view) |index| {
            const view = self.windows_memory_views[index];
            const view_end = std.math.add(u64, view.guest_base, view.length) catch 0;
            if (view.length != 0 and address >= view.guest_base and end <= view_end) {
                const mapping = self.windows_file_mappings[view.mapping_index];
                const backing = mapping.backing orelse return null;
                const backing_offset = std.math.add(u64, view.backing_offset, address - view.guest_base) catch return null;
                const offset: usize = std.math.cast(usize, backing_offset) orelse return null;
                if (offset > backing.len or count_usize > backing.len - offset) return null;
                return .{
                    .bytes = backing[offset..][0..count_usize],
                    .guest_base = view.guest_base,
                    .length = view.length,
                    .kind = .memory_view,
                    .source_index = view.mapping_index,
                    .generation = mapping.code_generation,
                };
            }
        }
        if (self.windowsIndexedMemory(address, count)) |slice| return slice;
        for (self.windows_memory_views[0..self.windows_memory_view_count]) |view| {
            if (view.length == 0 or address < view.guest_base) continue;
            const view_end = std.math.add(u64, view.guest_base, view.length) catch continue;
            if (end > view_end) continue;
            const mapping = self.windows_file_mappings[view.mapping_index];
            const backing = mapping.backing orelse continue;
            const backing_offset = std.math.add(u64, view.backing_offset, address - view.guest_base) catch return null;
            const offset: usize = std.math.cast(usize, backing_offset) orelse return null;
            if (offset > backing.len or count_usize > backing.len - offset) return null;
            return .{
                .bytes = backing[offset..][0..count_usize],
                .guest_base = view.guest_base,
                .length = view.length,
                .kind = .memory_view,
                .source_index = view.mapping_index,
                .generation = mapping.code_generation,
            };
        }
        for (self.windows_virtual_allocations[0..self.windows_virtual_allocation_count], 0..) |allocation, allocation_index| {
            if (allocation.length == 0 or address < allocation.guest_base) continue;
            const allocation_end = std.math.add(u64, allocation.guest_base, allocation.length) catch continue;
            if (end > allocation_end) continue;
            const backing = allocation.backing orelse continue;
            const offset = std.math.cast(usize, address - allocation.guest_base) orelse return null;
            if (offset > backing.len or count_usize > backing.len - offset) return null;
            return .{
                .bytes = backing[offset..][0..count_usize],
                .guest_base = allocation.guest_base,
                .length = allocation.length,
                .kind = .virtual_allocation,
                .source_index = allocation_index,
                .generation = allocation.code_generation,
            };
        }
        return null;
    }

    fn windowsMappedMemory(self: *ElfState, address: u64, count: u64) ?[]u8 {
        if (self.nativeMemoryAlias(address, count)) |bytes| return bytes;
        if (self.windowsIndexedMemory(address, count)) |slice| return @constCast(slice.bytes);
        if (count > std.math.maxInt(usize)) return null;
        const end = std.math.add(u64, address, count) catch return null;
        const count_usize: usize = @intCast(count);
        for (self.windows_memory_views[0..self.windows_memory_view_count]) |view| {
            if (view.length == 0 or address < view.guest_base) continue;
            const view_end = std.math.add(u64, view.guest_base, view.length) catch continue;
            if (end > view_end) continue;
            const mapping = self.windows_file_mappings[view.mapping_index];
            const backing = mapping.backing orelse continue;
            const backing_offset = std.math.add(u64, view.backing_offset, address - view.guest_base) catch return null;
            const offset: usize = std.math.cast(usize, backing_offset) orelse return null;
            if (offset > backing.len or count_usize > backing.len - offset) return null;
            return backing[offset..][0..count_usize];
        }
        for (self.windows_virtual_allocations[0..self.windows_virtual_allocation_count]) |allocation| {
            if (allocation.length == 0 or address < allocation.guest_base) continue;
            const allocation_end = std.math.add(u64, allocation.guest_base, allocation.length) catch continue;
            if (end > allocation_end) continue;
            const backing = allocation.backing orelse continue;
            const offset = std.math.cast(usize, address - allocation.guest_base) orelse return null;
            if (offset > backing.len or count_usize > backing.len - offset) return null;
            return backing[offset..][0..count_usize];
        }
        return null;
    }

    /// Invalidate decode entries after a guest write through a mapped
    /// allocation. Xenia aliases the code-cache mapping at multiple guest
    /// addresses, so the token belongs to the backing mapping rather than to
    /// one view. The decode path still compares bytes when it observes a new
    /// token; this helper only makes the fast path safe.
    fn bumpWindowsMappedCodeGeneration(self: *ElfState, address: u64, count: u64) void {
        if (count == 0) return;
        if (self.windows_mapped_ranges.find(address, count)) |range| {
            const generation = switch (range.kind) {
                .memory_view => &self.windows_file_mappings[self.windows_memory_views[range.slot].mapping_index].code_generation,
                .virtual_allocation => &self.windows_virtual_allocations[range.slot].code_generation,
            };
            if (generation.* == std.math.maxInt(u64)) {
                self.invalidateMappedDecodeCache();
                generation.* = 1;
            } else generation.* += 1;
            return;
        }
        const end = std.math.add(u64, address, count) catch return;
        for (self.windows_memory_views[0..self.windows_memory_view_count]) |view| {
            if (view.length == 0 or address < view.guest_base) continue;
            const view_end = std.math.add(u64, view.guest_base, view.length) catch continue;
            if (end > view_end) continue;
            self.windows_file_mappings[view.mapping_index].code_generation +|= 1;
            return;
        }
        for (self.windows_virtual_allocations[0..self.windows_virtual_allocation_count]) |*allocation| {
            if (allocation.length == 0 or address < allocation.guest_base) continue;
            const allocation_end = std.math.add(u64, allocation.guest_base, allocation.length) catch continue;
            if (end > allocation_end) continue;
            allocation.code_generation +|= 1;
            return;
        }
    }

    fn invalidateMappedDecodeCache(self: *ElfState) void {
        // Recreated mappings may reuse both a table slot and generation 1.
        // Their old decodes must not survive that lifetime boundary.
        for (self.decode_cache) |*entry| if (entry.mapped_source) {
            entry.valid = false;
        };
    }

    fn indexWindowsMappedRange(self: *ElfState, range: mapped_ranges.Range) bool {
        if (!self.windows_mapped_ranges.insert(range)) {
            log.err("PE64 mapped range index refused: base=0x{x} length={d} kind={s} slot={d}; no backing was published", .{ range.base, range.length, @tagName(range.kind), range.slot });
            return false;
        }
        self.invalidateMappedDecodeCache();
        return true;
    }

    fn windowsIndexedMemory(self: *const ElfState, address: u64, count: u64) ?WindowsMappedCodeSlice {
        const range = self.windows_mapped_ranges.find(address, count) orelse return null;
        switch (range.kind) {
            .memory_view => {
                const view = self.windows_memory_views[range.slot];
                if (view.guest_base != range.base or view.length != range.length) return null;
                const mapping = self.windows_file_mappings[view.mapping_index];
                const backing = mapping.backing orelse return null;
                const offset = std.math.add(u64, view.backing_offset, address - range.base) catch return null;
                if (offset > backing.len or count > backing.len - offset) return null;
                return .{ .bytes = backing[@intCast(offset)..][0..@intCast(count)], .guest_base = range.base, .length = range.length, .kind = .memory_view, .source_index = view.mapping_index, .generation = mapping.code_generation };
            },
            .virtual_allocation => {
                const allocation = self.windows_virtual_allocations[range.slot];
                if (allocation.guest_base != range.base or allocation.length != range.length) return null;
                const backing = allocation.backing orelse return null;
                const offset = address - range.base;
                if (offset > backing.len or count > backing.len - offset) return null;
                return .{ .bytes = backing[@intCast(offset)..][0..@intCast(count)], .guest_base = range.base, .length = range.length, .kind = .virtual_allocation, .source_index = range.slot, .generation = allocation.code_generation };
            },
        }
    }

    /// Invalidate image decode entries only when a write overlaps an
    /// executable PE section.  Writes to `.data`, TLS and runtime bookkeeping
    /// are common during bootstrap and must not force every hot image loop to
    /// re-read and compare its instruction bytes.
    fn bumpWindowsImageCodeGeneration(self: *ElfState, address: u64, count: u64) void {
        if (count == 0 or self.windows_executable_range_count == 0) return;
        const end = std.math.add(u64, address, count) catch return;
        for (self.windows_executable_ranges[0..self.windows_executable_range_count]) |range| {
            if (range.length == 0) continue;
            const range_end = std.math.add(u64, range.guest_base, range.length) catch continue;
            if (address >= range_end or end <= range.guest_base) continue;
            // Saturation would make a later write indistinguishable from the
            // previous one.  This is practically unreachable, but clearing
            // the tiny cache makes the invariant explicit even in a fuzzed
            // or very long-lived PE session.
            if (self.windows_image_code_generation == std.math.maxInt(u64)) {
                self.windows_image_code_generation = 1;
                for (self.decode_cache) |*entry| entry.valid = false;
            } else {
                self.windows_image_code_generation += 1;
            }
            return;
        }
    }

    /// Return the current image-code generation only when the complete
    /// instruction lies in an executable PE section. A malformed control
    /// transfer into `.data` remains on the conservative byte-checked path;
    /// the generation proof must never turn an invalid/non-executable fetch
    /// into a stale decode.
    fn windowsImageCodeGenerationFor(self: *const ElfState, address: u64, count: usize) ?u64 {
        if (!self.windows_runtime_enabled or self.windows_executable_range_count == 0) return null;
        const end = std.math.add(u64, address, @as(u64, @intCast(count))) catch return null;
        for (self.windows_executable_ranges[0..self.windows_executable_range_count]) |range| {
            if (range.length == 0 or address < range.guest_base) continue;
            const range_end = std.math.add(u64, range.guest_base, range.length) catch continue;
            if (end <= range_end) return self.windows_image_code_generation;
        }
        return null;
    }

    pub fn read8(self: *const ElfState, vaddr: u64) u8 {
        if (self.addrToOffset(vaddr)) |off| return self.mem[off];
        if (self.windowsMappedMemoryConst(vaddr, 1)) |bytes| return bytes[0];
        return 0;
    }

    pub fn read16(self: *const ElfState, vaddr: u64) u16 {
        if (self.addrToOffset(vaddr)) |off| {
            if (off + 2 <= self.mem.len) return std.mem.readInt(u16, self.mem[off..][0..2], .little);
        } else if (self.windowsMappedMemoryConst(vaddr, 2)) |bytes| {
            return std.mem.readInt(u16, bytes[0..2], .little);
        }
        return 0;
    }

    pub fn read32(self: *const ElfState, vaddr: u64) u32 {
        if (self.addrToOffset(vaddr)) |off| {
            if (off + 4 <= self.mem.len) return std.mem.readInt(u32, self.mem[off..][0..4], .little);
        } else if (self.windowsMappedMemoryConst(vaddr, 4)) |bytes| {
            return std.mem.readInt(u32, bytes[0..4], .little);
        }
        return 0;
    }

    pub fn read64(self: *const ElfState, vaddr: u64) u64 {
        if (self.addrToOffset(vaddr)) |off| {
            if (off + 8 <= self.mem.len) return std.mem.readInt(u64, self.mem[off..][0..8], .little);
        } else if (self.windowsMappedMemoryConst(vaddr, 8)) |bytes| {
            return std.mem.readInt(u64, bytes[0..8], .little);
        }
        return 0;
    }

    pub fn write8(self: *ElfState, vaddr: u64, val: u8) void {
        self.traceGuestWrite(vaddr, 1, val);
        if (self.addrToOffset(vaddr)) |off| {
            if (off < self.mem.len) {
                self.mem[off] = val;
                self.bumpWindowsImageCodeGeneration(vaddr, 1);
            }
        } else if (self.windowsMappedMemory(vaddr, 1)) |bytes| {
            bytes[0] = val;
            self.bumpWindowsMappedCodeGeneration(vaddr, 1);
        }
    }

    pub fn write16(self: *ElfState, vaddr: u64, val: u16) void {
        self.traceGuestWrite(vaddr, 2, val);
        if (self.addrToOffset(vaddr)) |off| {
            if (off + 2 <= self.mem.len) {
                std.mem.writeInt(u16, self.mem[off..][0..2], val, .little);
                self.bumpWindowsImageCodeGeneration(vaddr, 2);
            }
        } else if (self.windowsMappedMemory(vaddr, 2)) |bytes| {
            std.mem.writeInt(u16, bytes[0..2], val, .little);
            self.bumpWindowsMappedCodeGeneration(vaddr, 2);
        }
    }

    pub fn write32(self: *ElfState, vaddr: u64, val: u32) void {
        self.traceGuestWrite(vaddr, 4, val);
        self.traceWindowsMappedWrite(vaddr, 4, val);
        if (self.addrToOffset(vaddr)) |off| {
            if (off + 4 <= self.mem.len) {
                std.mem.writeInt(u32, self.mem[off..][0..4], val, .little);
                self.bumpWindowsImageCodeGeneration(vaddr, 4);
            }
        } else if (self.windowsMappedMemory(vaddr, 4)) |bytes| {
            std.mem.writeInt(u32, bytes[0..4], val, .little);
            self.bumpWindowsMappedCodeGeneration(vaddr, 4);
        }
    }

    pub fn write64(self: *ElfState, vaddr: u64, val: u64) void {
        self.traceGuestWrite(vaddr, 8, val);
        self.traceWindowsMappedWrite(vaddr, 8, val);
        if (self.addrToOffset(vaddr)) |off| {
            if (off + 8 <= self.mem.len) {
                std.mem.writeInt(u64, self.mem[off..][0..8], val, .little);
                self.bumpWindowsImageCodeGeneration(vaddr, 8);
            }
        } else if (self.windowsMappedMemory(vaddr, 8)) |bytes| {
            std.mem.writeInt(u64, bytes[0..8], val, .little);
            self.bumpWindowsMappedCodeGeneration(vaddr, 8);
        }
    }

    fn traceWindowsMappedWrite(self: *ElfState, address: u64, width: u8, value: u64) void {
        if (!self.trace_windows_memory or address < 0x40_0000_0000 or self.addrToOffset(address) != null or
            self.windows_memory_trace_events >= 64)
        {
            return;
        }
        const mapped = self.windowsMappedMemoryConst(address, width) != null;
        self.windows_memory_trace_events += 1;
        log.info("PE64 Windows mapped write: address=0x{x} width={d} value=0x{x} mapped={} guest_range={} rip=0x{x} op={s} step={d}", .{
            address,
            width,
            value,
            mapped,
            self.windowsGuestRangeContains(address, width),
            self.regs.rip,
            @tagName(self.last_decoded_op),
            self.executed_steps,
        });
    }

    fn traceGuestWrite(self: *const ElfState, vaddr: u64, width: u8, value: u64) void {
        const watch = self.trace_write_address orelse return;
        const write_end = vaddr +| @as(u64, width);
        const watch_end = watch +| 8;
        if (vaddr >= watch_end or write_end <= watch) return;
        if (comptime @import("builtin").is_test) return;

        log.info("trace guest write address=0x{x} width={d} value=0x{x} watch=0x{x} rip=0x{x} op={s} len={d} rsp=0x{x} ret=0x{x}", .{
            vaddr,
            width,
            value,
            watch,
            self.regs.rip,
            @tagName(self.last_decoded_op),
            self.last_decoded_len,
            self.regs.rsp,
            self.read64(self.regs.rsp),
        });
    }

    pub fn push(self: *ElfState, val: u64) void {
        self.regs.rsp -|= 8;
        const address = self.regs.rsp +% x64_decoder.segmentBase(&self.regs, .ss, .long64);
        self.write64(address, val);
    }

    pub fn pop(self: *ElfState) u64 {
        const address = self.regs.rsp +% x64_decoder.segmentBase(&self.regs, .ss, .long64);
        const val = self.read64(address);
        self.regs.rsp +|= 8;
        return val;
    }

    fn completeWindowsQsortWithoutFrame(self: *ElfState, direct_return_rip: ?u64) void {
        self.regs.rax = 0;
        self.regs.rip = if (direct_return_rip) |rip| rip else self.pop();
    }

    fn failWindowsQsort(self: *ElfState, direct_return_rip: ?u64, detail: []const u8) void {
        if (comptime !@import("builtin").is_test) {
            log.warn("Windows qsort refused: {s} base=0x{x} nmemb={d} size={d} comparator=0x{x} rip=0x{x}", .{
                detail,
                self.regs.rcx,
                self.regs.rdx,
                self.regs.r8,
                self.regs.r9,
                self.regs.rip,
            });
        }
        self.completeWindowsQsortWithoutFrame(direct_return_rip);
    }

    fn finishWindowsQsort(self: *ElfState) void {
        if (self.windows_qsort_frame_count == 0) {
            self.faulted = true;
            self.exit_code = 127;
            self.termination_reason = .runtime_invariant_failure;
            self.terminated = true;
            log.err("Windows qsort callback completed without an active sort frame rip=0x{x}", .{self.regs.rip});
            return;
        }
        const frame_index = self.windows_qsort_frame_count - 1;
        const frame = self.windows_qsort_frames[frame_index];
        self.windows_qsort_frame_count = frame_index;
        self.regs.rax = 0;
        self.regs.rip = if (frame.return_is_direct) frame.return_rip else self.pop();
        if (self.diagnose_abi) {
            log.info("Windows qsort complete elements={d} element_size={d} comparisons={d} continuation=0x{x}", .{
                frame.nmemb,
                frame.element_size,
                frame.callback_count,
                self.regs.rip,
            });
        }
    }

    fn continueWindowsQsort(self: *ElfState) void {
        if (self.windows_qsort_frame_count == 0) {
            self.faulted = true;
            self.exit_code = 127;
            self.termination_reason = .runtime_invariant_failure;
            self.terminated = true;
            log.err("Windows qsort continuation has no active sort frame rip=0x{x}", .{self.regs.rip});
            return;
        }

        const frame_index = self.windows_qsort_frame_count - 1;
        const frame = &self.windows_qsort_frames[frame_index];
        if (frame.awaiting_comparison) {
            frame.awaiting_comparison = false;
            const comparison: i32 = @bitCast(@as(u32, @truncate(self.regs.rax)));
            if (comparison < 0) {
                const current_address = frame.base + frame.j * frame.element_size;
                const previous_address = frame.base + (frame.j - 1) * frame.element_size;
                const current = self.guestMemory(current_address, frame.element_size) orelse {
                    self.faulted = true;
                    self.exit_code = 127;
                    self.termination_reason = .runtime_invariant_failure;
                    self.terminated = true;
                    log.err("Windows qsort comparator produced an invalid current element address=0x{x}", .{current_address});
                    return;
                };
                const previous = self.guestMemory(previous_address, frame.element_size) orelse {
                    self.faulted = true;
                    self.exit_code = 127;
                    self.termination_reason = .runtime_invariant_failure;
                    self.terminated = true;
                    log.err("Windows qsort comparator produced an invalid previous element address=0x{x}", .{previous_address});
                    return;
                };
                const element_size: usize = @intCast(frame.element_size);
                @memcpy(frame.scratch[0..element_size], current);
                @memcpy(current, previous);
                @memcpy(previous, frame.scratch[0..element_size]);
                if (frame.j > 1) {
                    frame.j -= 1;
                } else {
                    frame.i += 1;
                    frame.j = frame.i;
                }
            } else {
                frame.i += 1;
                frame.j = frame.i;
            }
        }

        if (frame.i >= frame.nmemb) {
            self.finishWindowsQsort();
            return;
        }

        const left_address = frame.base + frame.j * frame.element_size;
        const right_address = frame.base + (frame.j - 1) * frame.element_size;
        frame.callback_count +|= 1;
        frame.awaiting_comparison = true;
        self.push(x64_linux_runtime.SYNTHETIC_QSORT_RETURN);
        self.regs.rcx = left_address;
        self.regs.rdx = right_address;
        self.regs.r8 = 0;
        self.regs.r9 = 0;
        self.regs.rip = frame.comparator;
    }

    /// Start a guest-side insertion sort for the Microsoft CRT `qsort`
    /// import. The import handler has already identified the PE ABI; this
    /// method owns the callback stack and resumes the original caller only
    /// after every comparator call has returned.
    pub fn beginWindowsQsort(
        self: *ElfState,
        base: u64,
        nmemb: u64,
        element_size: u64,
        comparator: u64,
        direct_return_rip: ?u64,
    ) bool {
        if (nmemb <= 1) {
            self.completeWindowsQsortWithoutFrame(direct_return_rip);
            return true;
        }
        if (base == 0 or comparator == 0) {
            self.failWindowsQsort(direct_return_rip, "null base or comparator");
            return true;
        }
        if (element_size == 0 or element_size > MAX_WINDOWS_QSORT_ELEMENT_BYTES) {
            self.failWindowsQsort(direct_return_rip, "element size exceeds bounded guest scratch storage");
            return true;
        }
        if (nmemb > MAX_WINDOWS_QSORT_ELEMENTS) {
            self.failWindowsQsort(direct_return_rip, "element count exceeds bounded callback work");
            return true;
        }
        const byte_count = std.math.mul(u64, nmemb, element_size) catch {
            self.failWindowsQsort(direct_return_rip, "element range overflows guest address width");
            return true;
        };
        _ = std.math.add(u64, base, byte_count) catch {
            self.failWindowsQsort(direct_return_rip, "element range overflows guest address width");
            return true;
        };
        if (self.guestMemory(base, byte_count) == null) {
            self.failWindowsQsort(direct_return_rip, "element range is outside guest memory");
            return true;
        }
        if (self.addrToOffset(comparator) == null) {
            self.failWindowsQsort(direct_return_rip, "comparator is outside the guest image");
            return true;
        }
        if (self.windows_qsort_frame_count >= self.windows_qsort_frames.len) {
            self.failWindowsQsort(direct_return_rip, "nested qsort frame capacity exhausted");
            return true;
        }
        if (direct_return_rip == null and self.read64(self.regs.rsp) == 0) {
            self.failWindowsQsort(direct_return_rip, "caller continuation is null");
            return true;
        }

        const frame_index = self.windows_qsort_frame_count;
        self.windows_qsort_frames[frame_index] = .{
            .base = base,
            .nmemb = nmemb,
            .element_size = element_size,
            .comparator = comparator,
            .return_rip = direct_return_rip orelse 0,
            .return_is_direct = direct_return_rip != null,
        };
        self.windows_qsort_frame_count += 1;
        self.continueWindowsQsort();
        return true;
    }

    /// Register one guest CRT termination callback without exposing a host
    /// function pointer. The ordinary and quick-exit tables are bounded and
    /// LIFO, matching the C runtime contract; the executable TLS callback is
    /// a separate one-slot callback with the Windows DLL_PROCESS_DETACH ABI.
    pub fn registerWindowsCrtAtexit(self: *ElfState, function: u64, quick: bool, is_thread_local: bool) bool {
        const globals = &self.windows_crt_globals;
        var rejected = false;
        var rejection_reason: []const u8 = "";
        if (globals.termination_complete or function == 0 or self.guestMemory(function, 1) == null) {
            rejected = true;
            rejection_reason = if (globals.termination_complete)
                "termination-already-complete"
            else if (function == 0)
                "null-callback"
            else
                "callback-outside-guest-memory";
        } else if (is_thread_local) {
            if (globals.thread_local_callback != 0) {
                rejected = true;
                rejection_reason = "thread-local-slot-occupied";
            } else {
                globals.thread_local_callback = function;
            }
        } else if (quick) {
            if (globals.quick_count >= globals.quick_callbacks.len) {
                rejected = true;
                rejection_reason = "quick-exit-table-full";
            } else {
                globals.quick_callbacks[globals.quick_count] = .{ .function = function };
                globals.quick_count += 1;
            }
        } else if (globals.normal_count >= globals.normal_callbacks.len) {
            rejected = true;
            rejection_reason = "normal-exit-table-full";
        } else {
            globals.normal_callbacks[globals.normal_count] = .{ .function = function };
            globals.normal_count += 1;
        }

        if (rejected) {
            globals.callback_rejections +|= 1;
            log.warn("PE64 CRT callback registration rejected: callback=0x{x} quick={} thread_local={} reason={s} normal_count={d}/{d} quick_count={d}/{d} termination_complete={} step={d}", .{
                function,
                quick,
                is_thread_local,
                rejection_reason,
                globals.normal_count,
                globals.normal_callbacks.len,
                globals.quick_count,
                globals.quick_callbacks.len,
                globals.termination_complete,
                self.executed_steps,
            });
            return false;
        }
        globals.callback_registrations +|= 1;
        if (self.diagnose_abi) {
            log.info("PE64 CRT callback registered: callback=0x{x} quick={} thread_local={} normal={d} quick_count={d} thread_local_callback=0x{x}", .{
                function,
                quick,
                is_thread_local,
                globals.normal_count,
                globals.quick_count,
                globals.thread_local_callback,
            });
        }
        return true;
    }

    fn returnFromWindowsCrtImport(self: *ElfState, direct_return_rip: ?u64) void {
        self.regs.rip = if (direct_return_rip) |return_rip| return_rip else self.pop();
    }

    fn failWindowsCrtExit(self: *ElfState, detail: []const u8) void {
        const globals = &self.windows_crt_globals;
        globals.exit_running = false;
        globals.exit_mode = .none;
        globals.thread_local_pending = false;
        globals.termination_complete = true;
        self.faulted = true;
        self.exit_code = 127;
        self.termination_reason = .runtime_invariant_failure;
        self.terminated = true;
        log.err("PE64 CRT exit protocol failure: {s} rip=0x{x} step={d}", .{ detail, self.regs.rip, self.executed_steps });
    }

    fn finishWindowsCrtExit(self: *ElfState) void {
        const globals = &self.windows_crt_globals;
        const code = globals.pending_exit_code;
        const return_to_caller = globals.exit_return_to_caller;
        const return_is_direct = globals.exit_return_is_direct;
        const return_rip = globals.exit_return_rip;
        const return_rsp = globals.exit_return_rsp;

        globals.exit_running = false;
        globals.exit_mode = .none;
        globals.thread_local_pending = false;
        globals.normal_count = 0;
        globals.quick_count = 0;
        globals.thread_local_callback = 0;
        globals.termination_complete = true;

        if (return_to_caller) {
            self.regs.rax = 0;
            self.regs.rsp = return_rsp;
            self.returnFromWindowsCrtImport(if (return_is_direct) return_rip else null);
            if (self.diagnose_abi) {
                log.info("PE64 CRT exit complete: returning cexit-style call code=0x{x} continuation=0x{x}", .{ code, self.regs.rip });
            }
            return;
        }

        self.exit_code = code;
        self.termination_reason = .exit_syscall;
        self.terminated = true;
        log.info("PE64 CRT exit complete: code=0x{x} callbacks={d} step={d}", .{
            code,
            globals.callback_invocations,
            self.executed_steps,
        });
    }

    fn continueWindowsCrtExit(self: *ElfState) void {
        const globals = &self.windows_crt_globals;
        if (!globals.exit_running) {
            self.failWindowsCrtExit("completion without an active exit");
            return;
        }

        // Every callback starts from the original import frame. A callback's
        // ordinary RET consumes the synthetic marker and leaves RSP eight
        // bytes below this point; resetting it here prevents nested callbacks
        // from accumulating stack drift.
        self.regs.rsp = globals.exit_return_rsp;
        while (true) {
            var callback: u64 = 0;
            var thread_local_callback = false;
            switch (globals.exit_mode) {
                .normal => {
                    if (globals.normal_count != 0) {
                        globals.normal_count -= 1;
                        callback = globals.normal_callbacks[globals.normal_count].function;
                        globals.normal_callbacks[globals.normal_count] = .{};
                    } else if (globals.thread_local_pending) {
                        globals.thread_local_pending = false;
                        callback = globals.thread_local_callback;
                        globals.thread_local_callback = 0;
                        thread_local_callback = true;
                    }
                },
                .quick => {
                    if (globals.quick_count != 0) {
                        globals.quick_count -= 1;
                        callback = globals.quick_callbacks[globals.quick_count].function;
                        globals.quick_callbacks[globals.quick_count] = .{};
                    }
                },
                .none => {},
            }

            if (callback == 0) {
                self.finishWindowsCrtExit();
                return;
            }
            if (self.guestMemory(callback, 1) == null) {
                globals.callback_rejections +|= 1;
                self.failWindowsCrtExit("callback became invalid before invocation");
                return;
            }

            const return_rsp = globals.exit_return_rsp;
            if (return_rsp < 40) {
                self.failWindowsCrtExit("callback frame would underflow the guest stack");
                return;
            }
            const callback_rsp = return_rsp - 40;
            if (self.guestMemory(callback_rsp, 40) == null) {
                self.failWindowsCrtExit("callback frame is outside guest memory");
                return;
            }
            self.regs.rsp = callback_rsp;
            self.write64(callback_rsp, SYNTHETIC_WINDOWS_CRT_EXIT_RETURN);
            if (self.guestMemory(callback_rsp + 8, 32)) |home| @memset(home, 0);
            self.regs.rcx = 0;
            self.regs.rdx = 0; // DLL_PROCESS_DETACH for the TLS callback.
            self.regs.r8 = 0;
            self.regs.r9 = 0;
            self.regs.rip = callback;
            globals.callback_invocations +|= 1;
            if (self.diagnose_abi) {
                log.info("PE64 CRT callback invoke: callback=0x{x} quick={} thread_local={} remaining_normal={d} remaining_quick={d} step={d}", .{
                    callback,
                    globals.exit_mode == .quick,
                    thread_local_callback,
                    globals.normal_count,
                    globals.quick_count,
                    self.executed_steps,
                });
            }
            return;
        }
    }

    /// Begin the guest-owned CRT exit protocol. `run_callbacks` distinguishes
    /// `exit`/`quick_exit`/`_cexit` from `_exit`/`_c_exit`; the latter skip all
    /// cleanup by contract. A non-returning exit terminates the emulated
    /// guest, while cexit-style calls return through their original ABI
    /// continuation after the callbacks drain.
    pub fn beginWindowsCrtExit(
        self: *ElfState,
        code: u64,
        quick: bool,
        run_callbacks: bool,
        return_to_caller: bool,
        direct_return_rip: ?u64,
    ) bool {
        const globals = &self.windows_crt_globals;
        if (globals.exit_running) {
            if (return_to_caller) {
                self.regs.rax = 0;
                self.returnFromWindowsCrtImport(direct_return_rip);
                return true;
            }
            globals.pending_exit_code = code;
            globals.exit_running = false;
            globals.exit_mode = .none;
            globals.termination_complete = true;
            self.exit_code = code;
            self.termination_reason = .exit_syscall;
            self.terminated = true;
            log.info("PE64 CRT nested non-returning exit: code=0x{x} step={d}", .{ code, self.executed_steps });
            return true;
        }
        if (globals.termination_complete) {
            if (return_to_caller) {
                self.regs.rax = 0;
                self.returnFromWindowsCrtImport(direct_return_rip);
            } else {
                self.exit_code = code;
                self.termination_reason = .exit_syscall;
                self.terminated = true;
            }
            return true;
        }

        globals.pending_exit_code = code;
        globals.exit_mode = if (!run_callbacks) .none else if (quick) .quick else .normal;
        globals.exit_running = true;
        globals.exit_return_to_caller = return_to_caller;
        globals.exit_return_is_direct = direct_return_rip != null;
        globals.exit_return_rip = direct_return_rip orelse 0;
        globals.exit_return_rsp = self.regs.rsp;
        globals.thread_local_pending = globals.exit_mode == .normal and globals.thread_local_callback != 0;

        if (!run_callbacks) {
            self.finishWindowsCrtExit();
            return true;
        }
        self.continueWindowsCrtExit();
        return true;
    }

    fn failWindowsInitTerm(self: *ElfState, begin: u64, end: u64, detail: []const u8) void {
        self.faulted = true;
        self.exit_code = 127;
        self.termination_reason = .runtime_invariant_failure;
        self.terminated = true;
        if (comptime !@import("builtin").is_test) {
            log.err("invalid Windows CRT initializer table at rip=0x{x}: range=0x{x}..0x{x} {s}", .{ self.regs.rip, begin, end, detail });
        }
    }

    fn finishWindowsInitTerm(self: *ElfState, result: u64) void {
        if (self.windows_initterm_frame_count == 0) {
            self.failWindowsInitTerm(0, 0, "completion without an active frame");
            return;
        }
        const frame_index = self.windows_initterm_frame_count - 1;
        const frame = self.windows_initterm_frames[frame_index];
        self.windows_initterm_frame_count = frame_index;
        self.regs.rax = result;
        self.regs.rip = if (frame.return_is_direct) frame.return_rip else self.pop();
        if (self.diagnose_abi) {
            log.info("Windows CRT initializer table complete callbacks={d} result=0x{x} continuation=0x{x}", .{
                frame.callback_count,
                result,
                self.regs.rip,
            });
        }
    }

    fn continueWindowsInitTerm(self: *ElfState) void {
        if (self.windows_initterm_frame_count == 0) {
            self.failWindowsInitTerm(0, 0, "completion without an active frame");
            return;
        }

        const frame_index = self.windows_initterm_frame_count - 1;
        // `_initterm_e` stops when an initializer reports a nonzero result.
        // The normal `_initterm` callbacks are void and their RAX value is not
        // part of the contract.
        if (self.windows_initterm_frames[frame_index].returns_error and self.regs.rax != 0) {
            self.finishWindowsInitTerm(self.regs.rax);
            return;
        }

        while (self.windows_initterm_frames[frame_index].begin < self.windows_initterm_frames[frame_index].end) {
            const target_slot = self.windows_initterm_frames[frame_index].begin;
            self.windows_initterm_frames[frame_index].begin = target_slot + 8;
            const target = self.read64(target_slot);
            if (target == 0) continue;

            if (self.addrToOffset(target) == null) {
                self.failWindowsInitTerm(
                    target_slot,
                    self.windows_initterm_frames[frame_index].end,
                    "initializer target is outside the guest image",
                );
                return;
            }

            self.windows_initterm_frames[frame_index].callback_count +|= 1;
            self.push(x64_linux_runtime.SYNTHETIC_INITTERM_RETURN);
            self.regs.rip = target;
            if (self.diagnose_abi) {
                log.info("Windows CRT initializer callback {d} target=0x{x} next_slot=0x{x} end=0x{x}", .{
                    self.windows_initterm_frames[frame_index].callback_count,
                    target,
                    self.windows_initterm_frames[frame_index].begin,
                    self.windows_initterm_frames[frame_index].end,
                });
            }
            return;
        }

        self.finishWindowsInitTerm(0);
    }

    /// Start a guest-side walk of a Microsoft CRT `_initterm` table. The PE
    /// import stub has already placed its original return address on the guest
    /// stack, while the direct-call shortcut supplies the continuation here;
    /// both are preserved until every non-null initializer has returned.
    pub fn beginWindowsInitTerm(
        self: *ElfState,
        begin: u64,
        end: u64,
        direct_return_rip: ?u64,
        returns_error: bool,
    ) bool {
        if (begin > end or (begin & 7) != 0 or (end & 7) != 0) {
            self.failWindowsInitTerm(begin, end, "unaligned or reversed range");
            return true;
        }
        const byte_count = end - begin;
        if (byte_count > MAX_WINDOWS_INITTERM_ENTRIES * 8) {
            self.failWindowsInitTerm(begin, end, "initializer table exceeds bounded entry count");
            return true;
        }
        if (byte_count != 0 and self.guestMemory(begin, byte_count) == null) {
            self.failWindowsInitTerm(begin, end, "initializer table is outside guest memory");
            return true;
        }
        if (self.windows_initterm_frame_count >= self.windows_initterm_frames.len) {
            self.failWindowsInitTerm(begin, end, "initializer nesting exceeds bounded frame count");
            return true;
        }

        const frame_index = self.windows_initterm_frame_count;
        self.windows_initterm_frames[frame_index] = .{
            .begin = begin,
            .end = end,
            .return_rip = direct_return_rip orelse 0,
            .return_is_direct = direct_return_rip != null,
            .returns_error = returns_error,
        };
        self.windows_initterm_frame_count += 1;
        self.continueWindowsInitTerm();
        return true;
    }

    pub fn loadElf(self: *ElfState, elf_bytes: []const u8) !void {
        const plan = try elf_loader.planExecutableLoad(self.mem.len, elf_bytes, STACK_SIZE);
        self.mem_base = plan.mem_base;
        self.image_low = plan.image_low;
        self.image_high = plan.image_high;
        self.heap_next = plan.heap_start;
        self.regs.rip = try elf_loader.loadExecutableSegments(self.mem_base, self.mem, elf_bytes);
        log.info("load plan: guest_base=0x{x} image=[0x{x}, 0x{x}) heap=0x{x} entry=0x{x}", .{
            plan.mem_base,
            plan.image_low,
            plan.image_high,
            plan.heap_start,
            plan.entry,
        });
    }

    pub fn startLibcMain(self: *ElfState, main_addr: u64, argc: u64, argv: u64) void {
        self.pending_main_addr = main_addr;
        self.pending_argc = argc;
        self.pending_argv = argv;
        self.init_index = 0;
        self.libc_start_main_trampolined = true;
        self.scheduleNextInitOrMain();
    }

    fn scheduleNextInitOrMain(self: *ElfState) void {
        while (self.init_index < self.init_functions.len) {
            const target = self.init_functions[self.init_index];
            self.init_index += 1;
            if (target == 0 or self.addrToOffset(target) == null) continue;
            self.regs.rdi = self.pending_argc;
            self.regs.rsi = self.pending_argv;
            self.regs.rdx = 0;
            self.push(SYNTHETIC_INIT_RETURN);
            self.regs.rip = target;
            log.info("running ELF init function {d}/{d} at 0x{x}", .{
                self.init_index,
                self.init_functions.len,
                target,
            });
            return;
        }
        self.startMainAfterInit();
    }

    fn startMainAfterInit(self: *ElfState) void {
        self.regs.rdi = self.pending_argc;
        self.regs.rsi = self.pending_argv;
        self.regs.rdx = 0;
        self.push(SYNTHETIC_MAIN_RETURN);
        self.regs.rip = self.pending_main_addr;
    }

    fn handleSyntheticRip(self: *ElfState) bool {
        if (self.regs.rip == SYNTHETIC_WINDOWS_THREAD_RETURN) {
            self.finishWindowsGuestThread();
            return true;
        }
        if (self.regs.rip == SYNTHETIC_WINDOWS_MESSAGE_RETURN) {
            _ = self.finishWindowsMessageDispatch();
            return true;
        }
        if (self.regs.rip == SYNTHETIC_WINDOWS_AUDIO_RETURN) {
            _ = self.finishWindowsAudioCallback();
            return true;
        }
        if (self.regs.rip == SYNTHETIC_WINDOWS_EXCEPTION_RETURN) {
            self.finishWindowsExceptionDispatch();
            return true;
        }
        if (self.regs.rip == SYNTHETIC_WINDOWS_CRT_EXIT_RETURN) {
            self.continueWindowsCrtExit();
            return true;
        }
        if (self.regs.rip == x64_linux_runtime.SYNTHETIC_PTHREAD_ONCE_RETURN) {
            const once_control = self.pop();
            if (once_control != 0) self.write32(once_control, 1);
            self.regs.rax = 0;
            // The word below the once-control is either the original return
            // address of an import stub or the direct continuation saved by
            // the dynamic-call shortcut. Both paths therefore share the same
            // guest-only completion protocol.
            self.regs.rip = self.pop();
            return true;
        }
        if (self.regs.rip == x64_linux_runtime.SYNTHETIC_INITTERM_RETURN) {
            self.continueWindowsInitTerm();
            return true;
        }
        if (self.regs.rip == x64_linux_runtime.SYNTHETIC_QSORT_RETURN) {
            self.continueWindowsQsort();
            return true;
        }
        if (self.regs.rip == SYNTHETIC_INIT_RETURN) {
            self.scheduleNextInitOrMain();
            return true;
        }
        if (self.regs.rip == SYNTHETIC_MAIN_RETURN) {
            self.exit_code = self.regs.rax;
            self.termination_reason = .exit_syscall;
            self.terminated = true;
            return true;
        }
        return false;
    }

    fn copyUnresolvedImportName(destination: []u8, source: []const u8) usize {
        @memset(destination, 0);
        const count = @min(destination.len, source.len);
        if (count != 0) @memcpy(destination[0..count], source[0..count]);
        return count;
    }

    fn shouldReportWindowsPointOccurrence(occurrences: u64) bool {
        return occurrences <= 2 or (occurrences & (occurrences - 1)) == 0;
    }

    fn terminateForWindowsFatalPoint(self: *ElfState, label: []const u8) void {
        self.terminateForWindowsFatalPointWith(label, .runtime_invariant_failure, 125);
    }

    /// Stop the run at a fatal point, unless the operator allowed its label.
    fn terminateForWindowsFatalPointWith(
        self: *ElfState,
        label: []const u8,
        reason: exit_diagnostics.TerminationReason,
        exit_code: u64,
    ) void {
        if (self.terminated) return;
        if (self.windowsFatalPointAllowed(label)) {
            self.windows_fatal_point_allowed_events +|= 1;
            const allowed = self.windows_fatal_point_allowed_events;
            if (shouldReportWindowsPointOccurrence(allowed)) {
                log.warn("PE64 FATAL POINT ALLOWED: label={s} step={d} rip=0x{x} allowed_events={d}; ROSETTE_XENIA_FATAL_POINT_ALLOW names this label, so the run steps past it and everything after this line is gathered on top of a known failure", .{
                    label,
                    self.executed_steps,
                    self.regs.rip,
                    allowed,
                });
            }
            return;
        }
        if (!self.windows_fatal_point_terminate) return;
        self.faulted = true;
        self.exit_code = exit_code;
        self.termination_reason = reason;
        self.terminated = true;
        if (comptime !@import("builtin").is_test) {
            var at_text: [guest_symbol_text_bytes]u8 = undefined;
            const slot_plus_one: u8 = if (self.windows_active_guest_thread_slot) |slot| @intCast(@min(slot + 1, 255)) else 0;
            log.err("PE64 FATAL POINT TERMINATION: label={s} step={d} rip=0x{x} at={s} thread={s}; the run stops where this was decided. ROSETTE_XENIA_FATAL_POINT_ALLOW={s} steps past this label to reach the next one, and ROSETTE_XENIA_FATAL_POINT_TERMINATE=0 records every fatal point without stopping", .{
                label,
                self.executed_steps,
                self.regs.rip,
                self.describeGuestAddressOrUnnamed(self.regs.rip, &at_text),
                self.guestThreadLabel(slot_plus_one),
                label,
            });
        }
    }

    /// Keep the operator's allow-list: labels separated by commas, spaces or
    /// semicolons.
    pub fn configureWindowsFatalPointAllow(self: *ElfState, text: ?[]const u8) void {
        const value = text orelse "";
        const count = @min(value.len, self.windows_fatal_point_allow.len);
        @memcpy(self.windows_fatal_point_allow[0..count], value[0..count]);
        self.windows_fatal_point_allow_len = count;
    }

    fn windowsFatalPointAllowed(self: *const ElfState, label: []const u8) bool {
        var labels = std.mem.tokenizeAny(u8, self.windows_fatal_point_allow[0..self.windows_fatal_point_allow_len], ", ;");
        while (labels.next()) |candidate| {
            if (std.mem.eql(u8, candidate, label)) return true;
        }
        return false;
    }

    /// Make a genuine unimplemented PE64 export an explicit emulated-guest
    /// failure. This is intentionally not a host crash: the caller gets a
    /// deterministic termination record, the source-of-truth log names the
    /// exact DLL/export, and the host remains available for the next run.
    /// Setting `ROSETTE_PE64_CAPABILITY_GAP_FATAL=0` is reserved for a
    /// deliberate compatibility experiment and still leaves a warning in
    /// the log; the default is fail-closed.
    pub fn terminateForWindowsCapabilityGap(self: *ElfState, dll_name: []const u8, function_name: []const u8) bool {
        if (self.terminated) return true;
        self.windows_capability_gap_events +|= 1;
        if (!self.windows_capability_gaps_fatal) {
            log.warn("PE64 CAPABILITY GAP CONTINUED: dll={s} export={s} step={d} rip=0x{x}; compatibility override is active", .{
                dll_name,
                function_name,
                self.executed_steps,
                self.regs.rip,
            });
            return false;
        }
        self.faulted = true;
        self.exit_code = 127;
        self.termination_reason = .runtime_invariant_failure;
        self.terminated = true;
        if (comptime !@import("builtin").is_test) {
            log.err("PE64 CAPABILITY GAP FATAL: dll={s} export={s} step={d} rip=0x{x}; the emulated guest was terminated before an unimplemented ABI answer could corrupt state", .{
                dll_name,
                function_name,
                self.executed_steps,
                self.regs.rip,
            });
        }
        return true;
    }

    fn noteWindowsGuestCondition(self: *ElfState, condition: xenia_fatal_condition_map.Condition, line: []const u8) void {
        var entry: ?*WindowsGuestFailurePoint = null;
        for (self.windows_guest_failure_points[0..self.windows_guest_failure_point_count]) |*candidate| {
            if (std.mem.eql(u8, candidate.labelText(), condition.label)) {
                entry = candidate;
                break;
            }
        }
        if (entry == null) {
            if (self.windows_guest_failure_point_count >= self.windows_guest_failure_points.len) {
                self.windows_guest_failure_point_overflow +|= 1;
                log.err("PE64 FATAL POINT: guest-condition-ledger-overflow label={s} step={d} rip=0x{x}", .{
                    condition.label,
                    self.executed_steps,
                    self.regs.rip,
                });
                return;
            }
            entry = &self.windows_guest_failure_points[self.windows_guest_failure_point_count];
            entry.?.* = .{};
            entry.?.label_len = copyUnresolvedImportName(&entry.?.label, condition.label);
            entry.?.owner_len = copyUnresolvedImportName(&entry.?.owner, condition.owner.label());
            entry.?.line_len = copyUnresolvedImportName(&entry.?.line, line);
            entry.?.first_step = self.executed_steps;
            entry.?.first_rip = self.regs.rip;
            self.windows_guest_failure_point_count += 1;
        }

        const record = entry.?;
        record.occurrences +|= 1;
        record.last_step = self.executed_steps;
        record.last_rip = self.regs.rip;
        // A condition below its declared threshold is the design it names
        // (Xenia's XamState commits three unreserved pages on every start);
        // it is reported, and only the occurrence that makes it decisive is
        // a fatal point.
        const decisive = record.occurrences >= condition.repeats;
        if (shouldReportWindowsPointOccurrence(record.occurrences) or record.occurrences == condition.repeats) {
            if (decisive) {
                log.err("PE64 FATAL POINT: guest-condition label={s} owner={s} occurrence={d} of {d} step={d} rip=0x{x} line={s} remedy={s}", .{
                    record.labelText(),
                    record.ownerText(),
                    record.occurrences,
                    condition.repeats,
                    self.executed_steps,
                    self.regs.rip,
                    record.lineText(),
                    condition.remedy,
                });
            } else {
                log.info("PE64 emulator design event: label={s} owner={s} occurrence={d} below the {d} that make it decisive step={d} rip=0x{x} line={s}; at this count the line is the emulator's own documented behaviour, not a fault, and only the decisive occurrence is a fatal point. remedy={s}", .{
                    record.labelText(),
                    record.ownerText(),
                    record.occurrences,
                    condition.repeats,
                    self.executed_steps,
                    self.regs.rip,
                    record.lineText(),
                    condition.remedy,
                });
            }
        }
        if (decisive) {
            // Counted once, at the occurrence that makes it decisive: a
            // condition below its threshold is the design it names and is
            // not a fatal point the run met.
            if (record.occurrences == condition.repeats) self.windows_fatal_point_events +|= 1;
            self.terminateForWindowsFatalPoint(record.labelText());
        }
    }

    /// Print what Rosette knows about a guest line that reports a failure.
    ///
    /// A guest failure line is a claim about a conclusion, not about a cause.
    /// `Presenter: Failed to create a DXGI factory` is Xenia saying what it
    /// decided; it cannot say what Rosette answered that made it decide so,
    /// and the 2026-09-12 run printed exactly that line and nothing else -
    /// while Rosette itself held the export, the HRESULT it chose, the guest
    /// address that called it and the step it happened at.
    ///
    /// This is the other half. Each line's row in the warning table names
    /// which of Rosette's own ledgers is the counterpart, and this walks it.
    /// Nothing is printed for a line with no counterpart: "Rosette has no
    /// record of taking part in this" is a different and equally useful
    /// finding from "Rosette refused something", and inventing a cause for
    /// the first is how a log stops being evidence.
    fn substantiateGuestAdvisory(self: *const ElfState, line: []const u8) void {
        switch (xenia_warning_severity_map.evidenceFor(line)) {
            .none => {},
            .dxgi_factory => self.substantiateFromImportLedger(
                "dxgi.dll",
                "CreateDXGIFactory",
                "dxgi.dll has no host backend on macOS, so Rosette answers the factory call with an HRESULT refusal rather than a null pointer the guest would dereference. Xenia uses the factory for one thing: the DXGI UI tick thread in Presenter, which paces UI-thread repaints against a monitor's vertical blank. Without an IDXGIOutput, Presenter::AreDXGIUITicksWaitable is false, so Presenter::WaitForUITickFromUIThread returns immediately and UI painting is unpaced rather than blocked. It is not on the path to GraphicsSystem::MarkVblank, which the GPU frame limiter drives from a Clock::QueryGuestTickCount delta with no DXGI involvement",
            ),
            .vulkan_shader_creation => self.substantiateVulkanShaderCreation(),
            .guest_font_policy => log.warn(
                "PE64 guest advisory substantiation: Rosette's own font policy decided this. CJK font granted={}; the decision is Rosette's, not a missing host font, and ROSETTE_XENIA_GUEST_CJK_FONT selects it",
                .{self.windows_cjk_font_granted},
            ),
            .guest_heap_commit => log.warn(
                "PE64 guest advisory substantiation: see PE64 MEMORY CONTRACT for how Rosette classified this commit against what already backed the address; a commit Rosette relocated is listed there with its requested and actual addresses",
                .{},
            ),
            .vulkan_device_selection => log.info(
                "PE64 guest advisory substantiation: the adapter the guest is choosing between is the one Rosette's Vulkan bridge enumerated; see the macho-processor Vulkan milestone lines for the device and the features verified against the host",
                .{},
            ),
        }
    }

    /// The refusal ledger rows for one DLL whose export names start with a
    /// prefix, printed under the guest line they explain.
    fn substantiateFromImportLedger(
        self: *const ElfState,
        dll_name: []const u8,
        name_prefix: []const u8,
        consequence: []const u8,
    ) void {
        // The observed-refusal ledger, not the contract-fallback one: the
        // second holds only names Rosette has no handler for, and a refusal
        // from a handler it does have is exactly as load-bearing to the guest.
        const ledger = &self.windows_import_refusals;
        var matched: usize = 0;
        var caller_text: [guest_symbol_text_bytes]u8 = undefined;
        for (ledger.entries[0..ledger.count]) |*entry| {
            if (!entry.used) continue;
            if (!std.ascii.eqlIgnoreCase(entry.dll(), dll_name)) continue;
            if (!std.mem.startsWith(u8, entry.name(), name_prefix)) continue;
            matched += 1;
            log.warn(
                "PE64 guest advisory substantiation: Rosette answered {s}!{s} x{d} with 0x{x} ({s}, convention={s}); first at step {d} from {s} (rip=0x{x}), args=0x{x},0x{x}",
                .{
                    entry.dll(),
                    entry.name(),
                    entry.calls,
                    entry.value,
                    @tagName(entry.outcome),
                    @tagName(entry.convention),
                    entry.first_step,
                    self.describeGuestAddressOrUnnamed(entry.first_caller_rip, &caller_text),
                    entry.first_caller_rip,
                    entry.first_arg0,
                    entry.first_arg1,
                },
            );
        }
        if (matched == 0) {
            // The guest reported a failure Rosette has no record of causing.
            // That is a finding of its own: the decision was made inside the
            // guest, or on a path that answers without recording.
            log.warn(
                "PE64 guest advisory substantiation: Rosette has no ledger entry for {s}!{s}*. Either the guest decided this without calling out, or the call was served on a path that does not record - and the second is a hole in this instrument, not evidence about the guest",
                .{ dll_name, name_prefix },
            );
            return;
        }
        log.warn("PE64 guest advisory substantiation: consequence: {s}", .{consequence});
    }

    /// What Rosette's Vulkan bridge saw around a guest shader-creation
    /// failure. The bridge forwards these to the real driver, so the counters
    /// say whether the refusal was Rosette's or MoltenVK's.
    fn substantiateVulkanShaderCreation(self: *const ElfState) void {
        const graphics = &self.windows_graphics;
        log.warn(
            "PE64 guest advisory substantiation: Rosette's Vulkan bridge observed vk_calls={d} native_vk_calls={d} with native_vk_failures={d}, ordering_violations={d} and unmodeled={d}. Zero aggregate failures do NOT prove every shader creation reached the driver or that the guest consumed its published handle. Read the positive per-entry create ledger below; reconcile attempts, publications, bridge refusals and driver results against the guest warning",
            .{
                graphics.vulkan_calls,
                graphics.native_vulkan_calls,
                graphics.native_vulkan_failures,
                graphics.ordering_violations,
                graphics.unmodeled_calls,
            },
        );
        if (graphics.hooks.report_present_chain_full) |callback| {
            callback(graphics.hooks.native_context);
        } else {
            log.warn("PE64 guest advisory substantiation: native create-ledger reporting hook is unavailable; aggregate counters cannot locate this shader failure", .{});
        }
    }

    /// The eight-hex-digit XThread id Xenia prints after a log level marker
    /// (`!> F8000014 ...`), or null.
    fn guestLogLineThreadToken(line: []const u8) ?[]const u8 {
        const markers = [_][]const u8{ "!> ", "w> ", "x> ", "i> ", "d> " };
        for (markers) |marker| {
            const at = std.mem.indexOf(u8, line, marker) orelse continue;
            const start = at + marker.len;
            if (line.len < start + 8) continue;
            const token = line[start .. start + 8];
            var hex = true;
            for (token) |byte| {
                if (!std.ascii.isHex(byte)) hex = false;
            }
            if (hex) return token;
        }
        return null;
    }

    /// Which guest thread wrote a log line, and the kernel export it last
    /// entered.
    ///
    /// Xenia names every guest thread `<name> (<id>)` and prefixes every log
    /// line with that id, and the kernel census records each thread's most
    /// recent export. Joining the two turns "ResolvePath() failed" into the
    /// call that asked for the path. Xenia's logger is asynchronous, so this
    /// is the last export the thread had entered when the line arrived - an
    /// attribution, stated as one.
    fn describeGuestLogLineOrigin(self: *const ElfState, line: []const u8, buffer: []u8) []const u8 {
        const token = guestLogLineThreadToken(line) orelse return "";
        for (&self.windows_guest_threads) |*thread| {
            if (thread.status == .vacant or thread.name_len == 0) continue;
            const name = thread.nameText();
            const at = std.mem.indexOf(u8, name, token) orelse continue;
            if (at == 0 or name[at - 1] != '(') continue;
            if (at + token.len >= name.len or name[at + token.len] != ')') continue;
            const slot = self.guest_kernel_calls.slotAt(thread.last_kernel_slot);
            return std.fmt.bufPrint(buffer, " emitted_by='{s}' last_kernel_call={s}!{s} at_step={d}", .{
                name,
                if (slot) |entry| entry.module.moduleName() else "<none>",
                if (slot) |entry| entry.export_name else "<none>",
                thread.last_kernel_step,
            }) catch "";
        }
        return "";
    }

    /// The empty `ResolvePath()` form is only an expected optional-probe
    /// advisory when the asynchronous Xenia log can be joined to the kernel
    /// census. The XEX header metadata path can issue the same optional empty
    /// object-name probe as the file/status path. Without one of those origins,
    /// the same text stays a fault: a new VFS failure must not become quiet
    /// merely because it happens to have empty parentheses.
    fn isConfirmedEmptyResolvePathProbe(line: []const u8, origin: []const u8) bool {
        if (!xenia_warning_severity_map.isEmptyResolvePath(line)) return false;
        return std.mem.indexOf(u8, origin, "last_kernel_call=xboxkrnl.exe!NtCreateFile") != null or
            std.mem.indexOf(u8, origin, "last_kernel_call=xboxkrnl.exe!RtlNtStatusToDosError") != null or
            std.mem.indexOf(u8, origin, "last_kernel_call=xboxkrnl.exe!RtlImageXexHeaderField") != null;
    }

    fn noteWindowsGuestWarning(self: *ElfState, line: []const u8) void {
        self.windows_guest_warning_lines +|= 1;
        // Xenia prints its adapter list, its chosen device and its capability
        // narration at warning level. Recording those as fatal points with
        // `log.err` trains a reader to skim the block that also holds the real
        // ones, so an informational line is noted once, quietly, and never
        // enters the failure-point ledger.
        if (xenia_warning_severity_map.isUnresolvedImport(line)) self.windows_guest_unresolved_import_lines +|= 1;
        var origin_text: [192]u8 = undefined;
        // An empty path is joined to the VFS ledger first: that record was
        // taken synchronously inside the call that asked, while the thread's
        // last kernel call is only what it had reached by the time Xenia's
        // asynchronous logger printed the line.
        var ledger_text: [384]u8 = undefined;
        const ledger_origin = if (xenia_warning_severity_map.isEmptyResolvePath(line))
            self.describeVfsResolveFor("", &ledger_text)
        else
            "";
        const origin = if (ledger_origin.len != 0) ledger_origin else self.describeGuestLogLineOrigin(line, &origin_text);
        const empty_path_probe = isConfirmedEmptyResolvePathProbe(line, origin) or ledger_origin.len != 0;
        const severity = if (empty_path_probe) .advisory else xenia_warning_severity_map.classify(line);
        if (severity == .informational) {
            self.windows_guest_informational_lines +|= 1;
            if (xenia_warning_severity_map.bareModuleLookupName(line)) |module| {
                const occurrence = self.noteGuestModuleLookupLine(module);
                if (shouldReportWindowsPointOccurrence(occurrence)) {
                    var resolve_text: [384]u8 = undefined;
                    log.info("PE64 guest module lookup: module={s} occurrence={d} unresolved_imports_so_far={d}{s}; {s}", .{
                        module,
                        occurrence,
                        self.windows_guest_unresolved_import_lines,
                        self.describeVfsResolveFor(module, &resolve_text),
                        if (occurrence == 1) xenia_warning_severity_map.bare_module_lookup_reason else "PE64 GUEST MODULE LOOKUPS at exit carries the total",
                    });
                }
            } else {
                log.info("PE64 guest narration: {s}", .{line});
            }
            return;
        }
        const advisory = severity == .advisory;
        const reason: []const u8 = if (empty_path_probe)
            "the asynchronous echo of the synchronous vfs-empty-object-name fatal point, which stopped the run or was stepped past by ROSETTE_XENIA_FATAL_POINT_ALLOW; that line carries the NtCreateFile request behind the empty name"
        else if (xenia_warning_severity_map.entryFor(line)) |entry|
            entry.reason
        else
            "";

        for (self.windows_guest_warning_points[0..self.windows_guest_warning_point_count]) |*entry| {
            if (!std.mem.eql(u8, entry.lineText(), line)) continue;
            entry.occurrences +|= 1;
            entry.last_step = self.executed_steps;
            if (shouldReportWindowsPointOccurrence(entry.occurrences)) {
                if (advisory) {
                    log.warn("PE64 guest advisory: occurrence={d} step={d} rip=0x{x} line={s}", .{
                        entry.occurrences,
                        self.executed_steps,
                        self.regs.rip,
                        entry.lineText(),
                    });
                } else {
                    log.err("PE64 FATAL POINT: guest-warning label={s} occurrence={d} step={d} rip=0x{x} line={s}{s}{s}{s}", .{
                        xenia_warning_severity_map.labelFor(line),
                        entry.occurrences,
                        self.executed_steps,
                        self.regs.rip,
                        entry.lineText(),
                        if (reason.len != 0) " classification=" else "",
                        reason,
                        origin,
                    });
                }
            }
            return;
        }
        if (self.windows_guest_warning_point_count >= self.windows_guest_warning_points.len) {
            self.windows_guest_warning_point_overflow +|= 1;
            return;
        }
        var entry = &self.windows_guest_warning_points[self.windows_guest_warning_point_count];
        entry.* = .{};
        entry.line_len = copyUnresolvedImportName(&entry.line, line);
        entry.first_step = self.executed_steps;
        entry.last_step = self.executed_steps;
        entry.occurrences = 1;
        entry.advisory = advisory;
        self.windows_guest_warning_point_count += 1;
        if (advisory) {
            self.windows_guest_advisory_lines +|= 1;
            // An advisory is a real degradation, so it is retained and
            // reported - but it is not a fatal point, and counting it as one
            // is what made the summary's `unique=` number unreadable.
            log.warn("PE64 guest advisory: step={d} rip=0x{x} line={s} classification={s}{s}", .{
                self.executed_steps,
                self.regs.rip,
                entry.lineText(),
                reason,
                origin,
            });
            self.substantiateGuestAdvisory(line);
            // An empty resolve already had its synchronous fatal point; its
            // echo is not a second one.
            const echoed = empty_path_probe and self.guest_vfs_empty_name_faults != 0;
            if (!echoed and !xenia_warning_severity_map.continuationFor(line).continues()) {
                const label = xenia_warning_severity_map.labelFor(line);
                self.windows_fatal_point_events +|= 1;
                if (comptime !@import("builtin").is_test) {
                    log.err("PE64 FATAL POINT: guest-advisory label={s} step={d} rip=0x{x} line={s}; a degradation is survivable only on a named ground - a Rosette policy decision or the emulator's documented design - and this row has neither, so the run treats it as the error it probably is{s}", .{
                        label,
                        self.executed_steps,
                        self.regs.rip,
                        entry.lineText(),
                        origin,
                    });
                }
                self.terminateForWindowsFatalPoint(label);
            }
            return;
        }
        self.windows_fatal_point_events +|= 1;
        const label = xenia_warning_severity_map.labelFor(line);
        log.err("PE64 FATAL POINT: guest-warning label={s} occurrence=1 step={d} rip=0x{x} line={s}{s}{s}{s}", .{
            label,
            self.executed_steps,
            self.regs.rip,
            entry.lineText(),
            if (reason.len != 0) " classification=" else "",
            reason,
            origin,
        });
        self.terminateForWindowsFatalPoint(label);
    }

    /// Where governed guest output goes: straight to the host descriptor.
    const GuestOutputHostSink = struct {
        fd: std.posix.fd_t,
        failures: *u64,

        pub fn emit(self: GuestOutputHostSink, bytes: []const u8) void {
            var written: usize = 0;
            while (written < bytes.len) {
                const result = std.c.write(self.fd, bytes.ptr + written, bytes.len - written);
                if (result <= 0) {
                    self.failures.* +|= 1;
                    return;
                }
                written += @intCast(result);
            }
        }
    };

    /// Write guest stdout/stderr bytes to the host through the flood
    /// governor, and return the count the guest is told was written.
    ///
    /// The guest's write always succeeds in full: a log sink that throttles is
    /// Rosette's decision, and a guest that retried a short write would turn
    /// the throttle into a spin. Rosette's classifier is fed separately by
    /// the caller, so it still sees every byte.
    pub fn writeWindowsGuestStandardOutput(self: *ElfState, host_fd: std.posix.fd_t, stream_fd: u64, bytes: []const u8) usize {
        const sink = GuestOutputHostSink{ .fd = host_fd, .failures = &self.windows_guest_output_host_write_failures };
        const governors = self.windows_guest_output_governors orelse blk: {
            const created = self.allocator.create([2]guest_output_governor.Governor) catch {
                sink.emit(bytes);
                return bytes.len;
            };
            created.* = .{ .{}, .{} };
            self.windows_guest_output_governors = created;
            break :blk created;
        };
        const index: usize = if (stream_fd == 2) 1 else 0;
        self.windows_guest_output_host_fds[index] = host_fd;
        governors[index].feed(bytes, sink);
        return bytes.len;
    }

    fn flushWindowsGuestOutputGovernors(self: *ElfState) void {
        const governors = self.windows_guest_output_governors orelse return;
        for (governors, 0..) |*governor, index| {
            const fd = self.windows_guest_output_host_fds[index];
            if (fd < 0) continue;
            governor.flush(GuestOutputHostSink{ .fd = fd, .failures = &self.windows_guest_output_host_write_failures });
        }
    }

    /// What the guest output governor admitted and withheld.
    pub fn reportWindowsGuestOutputGovernor(self: *ElfState) void {
        self.flushWindowsGuestOutputGovernors();
        const governors = self.windows_guest_output_governors orelse {
            log.info("PE64 GUEST OUTPUT GOVERNOR: the guest wrote nothing to stdout or stderr", .{});
            return;
        };
        const labels = [_][]const u8{ "stdout", "stderr" };
        for (governors, 0..) |*governor, index| {
            if (governor.lines == 0) continue;
            log.info("PE64 GUEST OUTPUT GOVERNOR: {s} lines={d} written={d} ({d} bytes) withheld_repeats={d} withheld_over_budget={d} ({d} bytes) notices={d} distinct_tracked={d} untracked={d} host_write_failures={d}; every exact line reaches this log {d} times and then only at powers of two, and at most {d} MiB of guest output is written", .{
                labels[index],
                governor.lines,
                governor.passed_lines,
                governor.passed_bytes,
                governor.withheld_repeat_lines,
                governor.withheld_budget_lines,
                governor.withheld_bytes,
                governor.notices,
                governor.distinct_tracked,
                governor.untracked_lines,
                self.windows_guest_output_host_write_failures,
                guest_output_governor.repeat_allowance,
                governor.byte_budget / (1024 * 1024),
            });
            for (&governor.examples) |*example| {
                if (example.count == 0) continue;
                log.info("PE64 GUEST OUTPUT GOVERNOR:   x{d} {s}", .{ example.count, example.textSlice() });
            }
        }
    }

    /// Count one `device not found` line for a bare module name, by name.
    fn noteGuestModuleLookupLine(self: *ElfState, module: []const u8) u64 {
        self.windows_guest_module_lookup_lines +|= 1;
        const name = module[0..@min(module.len, GUEST_MODULE_NAME_BYTES)];
        for (self.windows_guest_module_lookups[0..self.windows_guest_module_lookup_count]) |*entry| {
            if (!std.mem.eql(u8, entry.nameText(), name)) continue;
            entry.lines +|= 1;
            return entry.lines;
        }
        if (self.windows_guest_module_lookup_count == GUEST_MODULE_LOOKUP_CAPACITY) {
            self.windows_guest_module_lookup_overflow +|= 1;
            return self.windows_guest_module_lookup_lines;
        }
        const entry = &self.windows_guest_module_lookups[self.windows_guest_module_lookup_count];
        self.windows_guest_module_lookup_count += 1;
        entry.* = .{ .lines = 1, .first_step = self.executed_steps, .name_len = @intCast(name.len) };
        @memcpy(entry.name[0..name.len], name);
        return 1;
    }

    /// Every bare module name Xenia's lookups printed, joined to the VFS
    /// ledger and to Xenia's own unresolved-import warnings.
    fn reportGuestModuleLookups(self: *const ElfState) void {
        if (self.windows_guest_module_lookup_count == 0 and self.windows_guest_unresolved_import_lines == 0) return;
        log.info("PE64 GUEST MODULE LOOKUPS: {d} device-not-found line(s) for {d} bare module name(s); unresolved_imports={d}", .{
            self.windows_guest_module_lookup_lines,
            self.windows_guest_module_lookup_count,
            self.windows_guest_unresolved_import_lines,
        });
        for (self.windows_guest_module_lookups[0..self.windows_guest_module_lookup_count]) |*entry| {
            var resolve_text: [384]u8 = undefined;
            const matched_device_path = self.guestVfsMatchedDevicePath(entry.nameText());
            log.info("PE64 GUEST MODULE LOOKUPS:   module={s} lines={d} first_step={d} matched_device_path={s}{s}", .{
                entry.nameText(),
                entry.lines,
                entry.first_step,
                if (matched_device_path.len == 0) "<none>" else matched_device_path,
                self.describeVfsResolveFor(entry.nameText(), &resolve_text),
            });
        }
        const verdict: []const u8 = if (self.windows_guest_unresolved_import_lines == 0)
            "no import went unbound. Each line is Xenia's GetModule or UserModule::Dump trying a bare module name as a path before matching loaded modules by name; the VFS cannot find a device for a name with no device prefix, and the lookup continues. Where the VFS ledger reports a found game:-device DLL with the same stem, that is the loaded-module evidence. A module that were really missing would be followed by Xenia's 'an import variable was not resolved' warning, and there was none"
        else
            "Xenia reported unbound imports: a title module imports an ordinal nothing loaded exports. The FATAL POINT lines carrying 'an import variable was not resolved' name the library and ordinal, and the module named above is the one to look for on the disc";
        log.info("PE64 GUEST MODULE LOOKUPS:   verdict: {s}", .{verdict});
    }

    fn processWindowsGuestOutputLine(self: *ElfState, line: []const u8, truncated: bool) void {
        if (line.len == 0) return;
        if (xenia_fatal_condition_map.match(line)) |condition| {
            self.noteWindowsGuestCondition(condition, line);
            if (truncated) self.windows_guest_output_truncated_lines +|= 1;
            return;
        }
        const is_warning = std.mem.indexOf(u8, line, "w> ") != null or
            std.mem.indexOf(u8, line, "!> ") != null or
            std.mem.indexOf(u8, line, "x> ") != null;
        if (is_warning) self.noteWindowsGuestWarning(line);
        if (truncated) self.windows_guest_output_truncated_lines +|= 1;
    }

    /// Observe bytes written by the PE guest to stdout/stderr. This is the
    /// Rosette-side equivalent of a logger hook: no Xenia source change is
    /// needed, and partial writes are reassembled before matching phrases.
    pub fn noteWindowsGuestOutput(self: *ElfState, bytes: []const u8) void {
        for (bytes) |byte| {
            if (byte == '\r') continue;
            if (byte == '\n') {
                self.processWindowsGuestOutputLine(
                    self.windows_guest_output_line[0..self.windows_guest_output_line_len],
                    self.windows_guest_output_line_truncated,
                );
                self.windows_guest_output_line_len = 0;
                self.windows_guest_output_line_truncated = false;
                continue;
            }
            if (self.windows_guest_output_line_len < self.windows_guest_output_line.len) {
                self.windows_guest_output_line[self.windows_guest_output_line_len] = byte;
                self.windows_guest_output_line_len += 1;
            } else {
                self.windows_guest_output_line_truncated = true;
            }
        }
    }

    fn flushWindowsGuestOutput(self: *ElfState) void {
        self.flushWindowsGuestOutputGovernors();
        if (self.windows_guest_output_line_len == 0) return;
        self.processWindowsGuestOutputLine(
            self.windows_guest_output_line[0..self.windows_guest_output_line_len],
            self.windows_guest_output_line_truncated,
        );
        self.windows_guest_output_line_len = 0;
        self.windows_guest_output_line_truncated = false;
    }

    fn logWindowsGuestFailurePointSummary(self: *const ElfState) void {
        self.reportGuestModuleLookups();
        // Below its threshold a condition is the design it names. XamState
        // commits three pages at 0x80D00000/10000/20000 without reserving
        // them on every start (src/xenia/kernel/xam/xam_state.cc), and
        // BaseHeap::AllocFixed says so once each; listing that as a FATAL
        // POINT SUMMARY ENTRY made Xenia's documented behaviour read as the
        // run's defect.
        for (self.windows_guest_failure_points[0..self.windows_guest_failure_point_count]) |entry| {
            const repeats: u64 = if (xenia_fatal_condition_map.conditionForLabel(entry.labelText())) |condition| condition.repeats else 1;
            if (entry.occurrences >= repeats) continue;
            log.info("PE64 EMULATOR DESIGN EVENTS: label={s} owner={s} occurrences={d} of the {d} that would make it a fatal point first_step={d} last_step={d} line={s}; below its threshold this is the emulator's documented behaviour, so it is reported here and not counted as a fatal point", .{
                entry.labelText(),
                entry.ownerText(),
                entry.occurrences,
                repeats,
                entry.first_step,
                entry.last_step,
                entry.lineText(),
            });
        }
        if (self.windows_fatal_point_events == 0 and self.windows_guest_output_truncated_lines == 0) return;
        log.err("PE64 FATAL POINT SUMMARY: unique={d} known={d} warning_lines={d} informational={d} advisory={d} known_overflow={d} generic_overflow={d} truncated_lines={d} terminate_policy={} allowed={d} allow=[{s}] null_page_accesses={d} vfs_empty_name_faults={d}", .{
            self.windows_fatal_point_events,
            self.windows_guest_failure_point_count,
            self.windows_guest_warning_lines,
            self.windows_guest_informational_lines,
            self.windows_guest_advisory_lines,
            self.windows_guest_failure_point_overflow,
            self.windows_guest_warning_point_overflow,
            self.windows_guest_output_truncated_lines,
            self.windows_fatal_point_terminate,
            self.windows_fatal_point_allowed_events,
            self.windows_fatal_point_allow[0..self.windows_fatal_point_allow_len],
            self.guest_null_page_accesses,
            self.guest_vfs_empty_name_faults,
        });
        for (self.windows_guest_failure_points[0..self.windows_guest_failure_point_count]) |entry| {
            const entry_repeats: u64 = if (xenia_fatal_condition_map.conditionForLabel(entry.labelText())) |condition| condition.repeats else 1;
            if (entry.occurrences < entry_repeats) continue;
            log.err("PE64 FATAL POINT SUMMARY ENTRY: label={s} owner={s} occurrences={d} first_step={d} last_step={d} first_rip=0x{x} last_rip=0x{x} line={s}", .{
                entry.labelText(),
                entry.ownerText(),
                entry.occurrences,
                entry.first_step,
                entry.last_step,
                entry.first_rip,
                entry.last_rip,
                entry.lineText(),
            });
        }
        for (self.windows_guest_warning_points[0..self.windows_guest_warning_point_count]) |entry| {
            if (entry.advisory) {
                log.warn("PE64 GUEST ADVISORY SUMMARY: occurrences={d} first_step={d} last_step={d} line={s}", .{
                    entry.occurrences,
                    entry.first_step,
                    entry.last_step,
                    entry.lineText(),
                });
            } else {
                log.err("PE64 FATAL POINT SUMMARY WARNING: occurrences={d} first_step={d} last_step={d} line={s}", .{
                    entry.occurrences,
                    entry.first_step,
                    entry.last_step,
                    entry.lineText(),
                });
            }
        }
    }

    /// Record one unresolved import without putting an instruction-wide trace
    /// on the successful path.  Repeated calls to the same symbol are folded
    /// into one record so a bad polling loop cannot flood the terminal or the
    /// detailed `.rosette` log.
    pub fn recordUnresolvedWindowsImport(self: *ElfState, stub: WindowsImportStub) bool {
        const return_rip = self.read64(self.regs.rsp);
        const caller_rip = self.last_instruction_rip;
        for (self.windows_unresolved_imports[0..self.windows_unresolved_import_count]) |*record| {
            if (record.is_dynamic == stub.is_dynamic and
                std.mem.eql(u8, record.dllName(), stub.dll_name) and
                std.mem.eql(u8, record.functionName(), stub.function_name))
            {
                record.occurrences +|= 1;
                record.last_return_rip = return_rip;
                record.last_caller_rip = caller_rip;
                record.last_step = self.executed_steps;
                return false;
            }
        }

        if (self.windows_unresolved_import_count >= self.windows_unresolved_imports.len) return false;
        var record = &self.windows_unresolved_imports[self.windows_unresolved_import_count];
        record.* = .{
            .is_dynamic = stub.is_dynamic,
            .stub_address = self.regs.rip,
            .first_return_rip = return_rip,
            .first_caller_rip = caller_rip,
            .first_step = self.executed_steps,
            .first_rsp = self.regs.rsp,
            .first_rcx = self.regs.rcx,
            .first_rdx = self.regs.rdx,
            .first_r8 = self.regs.r8,
            .first_r9 = self.regs.r9,
            .last_return_rip = return_rip,
            .last_caller_rip = caller_rip,
            .last_step = self.executed_steps,
            .occurrences = 1,
        };
        // The whole-record assignment above intentionally clears the fixed
        // buffers as well. Copy the names afterwards; assigning the lengths
        // inside that literal would be overwritten by the zeroed arrays and
        // make every later occurrence look like a new symbol.
        record.dll_name_len = copyUnresolvedImportName(&record.dll_name, stub.dll_name);
        record.function_name_len = copyUnresolvedImportName(&record.function_name, stub.function_name);
        self.windows_unresolved_import_count += 1;
        return true;
    }

    /// Record the library a module handle names.
    pub fn noteWindowsLoadedModule(self: *ElfState, handle: u64, module_name: []const u8) void {
        if (handle == 0 or module_name.len == 0) return;
        for (self.windows_loaded_modules[0..self.windows_loaded_module_count]) |*entry| {
            if (entry.handle == handle) return;
        }
        if (self.windows_loaded_module_count >= self.windows_loaded_modules.len) {
            self.windows_loaded_module_overflow +|= 1;
            return;
        }
        var entry = &self.windows_loaded_modules[self.windows_loaded_module_count];
        entry.handle = handle;
        entry.name_len = copyBoundedName(&entry.name, module_name);
        self.windows_loaded_module_count += 1;
    }

    /// The library a module handle names, or an empty slice when this run did
    /// not issue the handle. Empty is not "kernel32": a lookup against an
    /// unknown handle has to stay attributable to nothing.
    pub fn windowsLoadedModuleName(self: *const ElfState, handle: u64) []const u8 {
        if (handle == 0) return "";
        for (self.windows_loaded_modules[0..self.windows_loaded_module_count]) |*entry| {
            if (entry.handle == handle) return entry.moduleName();
        }
        return "";
    }

    fn recordDynamicRefusal(
        records: []WindowsDynamicRefusal,
        count: *u32,
        scope: []const u8,
        name: []const u8,
        is_gap: bool,
        caller_rip: u64,
    ) bool {
        for (records[0..count.*]) |*record| {
            if (std.mem.eql(u8, record.nameText(), name) and std.mem.eql(u8, record.scopeText(), scope)) {
                record.occurrences +|= 1;
                return false;
            }
        }
        if (count.* >= records.len) return false;
        var record = &records[count.*];
        record.scope_len = copyBoundedName(&record.scope, scope);
        record.name_len = copyBoundedName(&record.name, name);
        record.occurrences = 1;
        record.is_gap = is_gap;
        record.first_caller_rip = caller_rip;
        count.* += 1;
        return true;
    }

    /// A `LoadLibrary` Rosetta answered with ERROR_MOD_NOT_FOUND.
    ///
    /// `is_gap` separates a decision from a hole: Direct3D is refused on
    /// purpose and every caller has a fallback, while a library nobody has
    /// written a package for is a finding. A log that spells them the same
    /// way buries the second in the first.
    pub fn noteWindowsModuleRefusal(
        self: *ElfState,
        api: []const u8,
        module_path: []const u8,
        reason: []const u8,
        is_gap: bool,
        fallback: []const u8,
        caller_rip: u64,
    ) void {
        self.windows_module_refusal_events +|= 1;
        if (is_gap) self.windows_module_refusal_gaps +|= 1;
        if (recordDynamicRefusal(
            &self.windows_module_refusals,
            &self.windows_module_refusal_count,
            api,
            module_path,
            is_gap,
            caller_rip,
        )) {
            var caller_text: [guest_symbol_text_bytes]u8 = undefined;
            log.info("PE64 Windows module refused: api={s} module='{s}' result=absent classification={s} reason={s} fallback={s} caller=0x{x} ({s})", .{
                api,
                module_path,
                if (is_gap) "GAP-no-package-models-this-library" else "deliberate-Rosette-policy",
                reason,
                fallback,
                caller_rip,
                self.describeGuestAddressOrUnnamed(caller_rip, &caller_text),
            });
        }
    }

    /// A `GetProcAddress` Rosetta answered with NULL.
    pub fn noteWindowsProcAddressRefusal(
        self: *ElfState,
        dll_name: []const u8,
        function_name: []const u8,
        caller_rip: u64,
    ) void {
        self.windows_proc_refusal_events +|= 1;
        if (recordDynamicRefusal(
            &self.windows_proc_refusals,
            &self.windows_proc_refusal_count,
            dll_name,
            function_name,
            true,
            caller_rip,
        )) {
            var caller_text: [guest_symbol_text_bytes]u8 = undefined;
            log.info("PE64 Windows export refused: module='{s}' name={s} result=NULL classification=GAP-name-not-in-Rosette's-import-inventory caller=0x{x} ({s}); a stub here would have promised behaviour the call cannot deliver", .{
                if (dll_name.len == 0) "<unattributed>" else dll_name,
                function_name,
                caller_rip,
                self.describeGuestAddressOrUnnamed(caller_rip, &caller_text),
            });
        }
    }

    /// A `GetProcAddress` refused on purpose: an optional export whose caller
    /// has a documented path for NULL.
    ///
    /// Reported apart from a gap, and with the path named. The same
    /// `GAP-name-not-in-Rosette's-import-inventory` wording used to cover
    /// `WaitOnAddress`, which the catalogue already refuses by decision because
    /// SDL builds its semaphores on kernel objects without it.
    pub fn noteWindowsProcAddressPolicyRefusal(
        self: *ElfState,
        dll_name: []const u8,
        function_name: []const u8,
        caller_rip: u64,
        fallback: []const u8,
        api_set_host: []const u8,
    ) void {
        self.windows_proc_refusal_events +|= 1;
        if (recordDynamicRefusal(
            &self.windows_proc_refusals,
            &self.windows_proc_refusal_count,
            dll_name,
            function_name,
            false,
            caller_rip,
        )) {
            var caller_text: [guest_symbol_text_bytes]u8 = undefined;
            log.info("PE64 Windows export refused: module='{s}'{s}{s} name={s} result=NULL classification=deliberate-Rosette-policy fallback={s} caller=0x{x} ({s}); the caller asked through GetProcAddress because the export is optional, and NULL sends it down the path named here", .{
                if (dll_name.len == 0) "<unattributed>" else dll_name,
                if (api_set_host.len != 0) " (official API-set contract, forwards to " else "",
                if (api_set_host.len != 0) api_set_host else "",
                function_name,
                fallback,
                caller_rip,
                self.describeGuestAddressOrUnnamed(caller_rip, &caller_text),
            });
        }
    }

    /// A C runtime import handed a pointer Rosette could not read.
    ///
    /// The CRT dereferences its arguments; on Windows an unmapped or null
    /// pointer here is an access violation in the caller, never an empty
    /// string. Rosette's reader used to know only the PE image, so `strlen`
    /// answered 0 for every string in Xenia's guest address space and
    /// `RtlInitAnsiString` built every name the title opened with Length 0.
    pub fn noteWindowsCrtUnreadable(self: *ElfState, address: u64, length: u64) void {
        self.noteWindowsCrtUnreadableFrom(address, length, 0);
    }

    /// A C-runtime string or memory function handed a pointer Rosette cannot
    /// read. `return_rip` is where the import returns to, or zero if unknown.
    ///
    /// The first report named only the import thunk as the caller, and the
    /// 2026-09-14 occurrences (a memcpy of 0xFFFFFFFF00000000 bytes, then one
    /// from 0xFFFFFFFF00000001) could not be traced to the code that built
    /// those arguments. The return address and the argument registers can.
    pub fn noteWindowsCrtUnreadableFrom(self: *ElfState, address: u64, length: u64, return_rip: u64) void {
        self.windows_crt_unreadable_pointers +|= 1;
        const occurrence = self.windows_crt_unreadable_pointers;
        if (occurrence == 1) self.windows_fatal_point_events +|= 1;
        // No address space holds a region this long, so the pointer was never
        // the question: the length was wrong before the call was made.
        const impossible_length = length > (@as(u64, 1) << 47);
        if (comptime !@import("builtin").is_test) {
            if (shouldReportWindowsPointOccurrence(occurrence)) {
                var caller_text: [guest_symbol_text_bytes]u8 = undefined;
                var return_text: [guest_symbol_text_bytes]u8 = undefined;
                const slot_plus_one: u8 = if (self.windows_active_guest_thread_slot) |slot| @intCast(@min(slot + 1, 255)) else 0;
                log.err("PE64 FATAL POINT: guest-condition label=crt-pointer-unreadable owner={s} occurrence={d} import={s} address=0x{x} length={d} (0x{x}) step={d} caller={s} return={s} rcx=0x{x} rdx=0x{x} r8=0x{x} r9=0x{x} thread={s}; {s}", .{
                    if (address == 0) "guest:caller" else if (impossible_length) "unknown:length-not-a-size" else "rosette:memory-model",
                    occurrence,
                    if (self.windows_current_import.len == 0) "<unattributed>" else self.windows_current_import,
                    address,
                    length,
                    length,
                    self.executed_steps,
                    self.describeGuestAddressOrUnnamed(self.last_instruction_rip, &caller_text),
                    if (return_rip == 0) "<unknown>" else self.describeGuestAddressOrUnnamed(return_rip, &return_text),
                    self.regs.rcx,
                    self.regs.rdx,
                    self.regs.r8,
                    self.regs.r9,
                    self.guestThreadLabel(slot_plus_one),
                    if (address == 0)
                        "the caller passed NULL to a function that dereferences it, which is a crash on Windows; the caller is the defect"
                    else if (impossible_length)
                        "no address space holds a region this long, so the length was wrong before the call was made. Disassemble the function at return= and follow how it built the length register: if every input to that arithmetic is ordinary guest state, Rosette executed the arithmetic wrongly; if one came back from an import, that import's answer is the defect"
                    else
                        "Windows would read this address, so Rosette serving no region for it is the defect: find which allocation or file-mapping view should cover it in PE64 MEMORY CONTRACT and the view table",
                });
            }
        }
        self.terminateForWindowsFatalPoint("crt-pointer-unreadable");
    }

    /// One worker turn served from inside an idle `GetMessage`.
    pub fn noteGetMessageIdleTurn(self: *ElfState, steps: u64) void {
        self.windows_get_message_idle_turns +|= 1;
        self.windows_get_message_idle_steps +|= steps;
    }

    /// A module-name pointer Rosetta could not read as a name.
    ///
    /// Deliberately not a refusal. Deciding a library is absent from bytes
    /// that are not a library name reports a loadable library as missing and
    /// sends a reader after a package that already exists, so the load is
    /// allowed and the *read* is what gets reported.
    pub fn noteWindowsUnreadableModuleName(
        self: *ElfState,
        api: []const u8,
        raw: []const u8,
        pointer: u64,
        caller_rip: u64,
    ) void {
        self.windows_unreadable_module_names +|= 1;
        if (self.windows_unreadable_module_names > 8) return;
        var caller_text: [guest_symbol_text_bytes]u8 = undefined;
        var escaped: [64]u8 = undefined;
        var written: usize = 0;
        for (raw) |byte| {
            if (written + 4 > escaped.len) break;
            if (byte >= 0x20 and byte <= 0x7E) {
                escaped[written] = byte;
                written += 1;
            } else {
                _ = std.fmt.bufPrint(escaped[written..], "\\x{x:0>2}", .{byte}) catch break;
                written += 4;
            }
        }
        log.warn("PE64 Windows module name unreadable: api={s} pointer=0x{x} bytes='{s}' caller=0x{x} ({s}); the load is allowed rather than refused, because a refusal decided from bytes that are not a name would report a loadable library as absent", .{
            api,
            pointer,
            escaped[0..written],
            caller_rip,
            self.describeGuestAddressOrUnnamed(caller_rip, &caller_text),
        });
    }

    /// The ordered set of things that must happen before a Xenia frame can
    /// reach the screen, and which of them this run reached.
    ///
    /// The presentation chain already answers "did anything present?" This
    /// answers the question a reader actually has next: *what is the first
    /// thing that has not happened, and whose job is it?* Every stage names
    /// an owner, because the fix for a Rosette stage and the fix for a Xenia
    /// stage are in different repositories - and because a stage owned by the
    /// title is not a defect at all until the title has been given a chance
    /// to reach it.
    ///
    /// Stages are ordered by dependency. Reporting anything past the first
    /// unmet one as a problem would be reporting a consequence.
    fn firstFrameChainStages(self: *const ElfState) [FIRST_FRAME_STAGE_COUNT]ChainStage {
        const graphics = &self.windows_graphics;
        const font_samples = self.fontAtlasFrontierSamples();
        // The atlas build is a stage rather than a footnote: it sits on the
        // UI thread between "the presenter has a surface" and "the window
        // paints", so no amount of GPU readiness gets past it. Rosette's own
        // font mapping decides how much work it is.
        const font_atlas_left = font_samples == 0 or
            !self.classifyGuestFrontier(self.regs.rip).workload.isBoundedComputation();
        // Samples that prove the title's own code has run at all, as opposed
        // to Xenia still preparing to run it.
        const title_running_samples = self.frontierSamplesFor(.cpu_execution) +|
            self.frontierSamplesFor(.kernel_services) +|
            self.frontierSamplesFor(.gpu_command_processing) +|
            self.frontierSamplesFor(.presentation);

        const stages = [FIRST_FRAME_STAGE_COUNT]ChainStage{
            .{
                .name = "host_window",
                .owner = "rosette:appkit-bridge",
                .met = graphics.window_ready,
                .evidence = "window_create_attempts",
                .value = graphics.window_create_attempts,
            },
            .{
                .name = "vulkan_instance",
                .owner = "rosette:vulkan-bridge",
                .met = graphics.instance_ready,
                .evidence = "instance_creations",
                .value = graphics.instance_creations,
            },
            .{
                .name = "vulkan_device",
                .owner = "rosette:vulkan-bridge",
                .met = graphics.device_ready,
                .evidence = "device_creations",
                .value = graphics.device_creations,
            },
            .{
                .name = "graphics_queue",
                .owner = "rosette:vulkan-bridge",
                .met = graphics.queue_ready,
                .evidence = "queue_acquisitions",
                .value = graphics.queue_acquisitions,
            },
            .{
                .name = "guest_surface",
                .owner = "xenia:ui-thread",
                .met = graphics.surface_ready,
                .evidence = "surface_creations",
                .value = graphics.surface_creations,
            },
            .{
                .name = "guest_swapchain",
                .owner = "xenia:ui-thread",
                .met = graphics.swapchain_ready,
                .evidence = "swapchain_creations",
                .value = graphics.swapchain_creations,
            },
            .{
                .name = "ui_font_atlas",
                .owner = "xenia:ui-thread",
                .met = font_atlas_left,
                .evidence = "frontier_samples_in_atlas_build",
                .value = font_samples,
            },
            .{
                // Include worker-local code-cache execution. A UI-thread
                // checkpoint alone misses the title even while it is running.
                .name = "title_code_running",
                .owner = "xenia:emulator-thread",
                .met = self.windows_title_code_fetches != 0 or title_running_samples != 0,
                .evidence = if (self.windows_title_code_fetches != 0) "title_worker_code_cache_fetches" else "frontier_samples_in_guest_code",
                .value = if (self.windows_title_code_fetches != 0) self.windows_title_code_fetches else title_running_samples,
            },
            .{
                .name = "window_paint_requested",
                .owner = "xenia:ui-thread",
                .met = self.windows_paint_requests != 0,
                .evidence = "paint_requests",
                .value = self.windows_paint_requests,
            },
            .{
                .name = "window_paint_delivered",
                .owner = "rosette:message-pump",
                .met = self.windows_paint_deliveries != 0,
                .evidence = "paint_deliveries",
                .value = self.windows_paint_deliveries,
            },
            .{
                .name = "command_recording",
                .owner = "xenia:ui-thread",
                .met = graphics.command_calls != 0,
                .evidence = "command_calls",
                .value = graphics.command_calls,
            },
            .{
                .name = "image_acquire",
                .owner = "xenia:ui-thread",
                .met = graphics.image_acquires != 0,
                .evidence = "image_acquires",
                .value = graphics.image_acquires,
            },
            .{
                .name = "queue_submit",
                .owner = "xenia:ui-thread",
                .met = graphics.queue_submits != 0,
                .evidence = "queue_submits",
                .value = graphics.queue_submits,
            },
            .{
                .name = "present",
                .owner = "xenia:ui-thread",
                .met = graphics.presents != 0,
                .evidence = "presents",
                .value = graphics.presents,
            },
        };

        return stages;
    }

    /// The earliest unmet precondition, or null when a frame could be shown.
    ///
    /// Separate from the report so the verdict can be asserted rather than
    /// read out of a log. A chain whose ordering is wrong still prints a
    /// plausible-looking answer; it just blames the wrong owner.
    pub fn firstFrameWall(self: *const ElfState) ?ChainStage {
        for (self.firstFrameChainStages()) |stage| {
            if (!stage.observable) continue;
            if (!stage.met) return stage;
        }
        return null;
    }

    pub fn reportFirstFrameChain(self: *const ElfState) void {
        const stages = self.firstFrameChainStages();
        var met_count: usize = 0;
        var first_unmet: ?usize = null;
        for (stages, 0..) |stage, index| {
            if (!stage.observable) continue;
            if (stage.met) {
                met_count += 1;
            } else if (first_unmet == null) {
                first_unmet = index;
            }
        }

        log.info("PE64 FIRST FRAME CHAIN: {d}/{d} preconditions met; stages are ordered by dependency, so only the first unmet one is a finding. This chain measures transport only: every stage of it can be met by a window showing one colour, and PE64 GUEST OUTPUT CHAIN is the one that asks whether a picture exists", .{
            met_count,
            stages.len,
        });
        for (stages, 0..) |stage, index| {
            var unobservable_text: [224]u8 = undefined;
            const marker: []const u8 = if (!stage.observable)
                std.fmt.bufPrint(&unobservable_text, "unobservable ({s})", .{stage.unobservable_reason}) catch "unobservable"
            else if (stage.met)
                "met"
            else if (first_unmet != null and index == first_unmet.?)
                "UNMET <- the wall"
            else
                "unmet (downstream of the wall)";
            log.info("PE64 FIRST FRAME CHAIN:   {s:<24} owner={s:<24} {s} ({s}={d})", .{
                stage.name,
                stage.owner,
                marker,
                stage.evidence,
                stage.value,
            });
        }

        var frontier_text: [320]u8 = undefined;
        log.info("PE64 FIRST FRAME CHAIN:   guest frontier at exit: rip=0x{x} {s}", .{
            self.regs.rip,
            self.describeGuestFrontier(self.regs.rip, &frontier_text),
        });
        if (self.guest_frontier_samples != 0) {
            log.info("PE64 FIRST FRAME CHAIN:   frontier histogram over {d} checkpoint sample(s):", .{self.guest_frontier_samples});
            inline for (@typeInfo(xenia_guest_frontier_map.Workload).@"enum".fields) |field| {
                const workload: xenia_guest_frontier_map.Workload = @enumFromInt(field.value);
                const samples = self.frontierSamplesFor(workload);
                if (samples != 0) {
                    log.info("PE64 FIRST FRAME CHAIN:     {s:<26} {d} sample(s) ({d}%) bounded={}", .{
                        workload.label(),
                        samples,
                        samples * 100 / self.guest_frontier_samples,
                        workload.isBoundedComputation(),
                    });
                }
            }
        }
        if (first_unmet) |index| {
            log.info("PE64 FIRST FRAME CHAIN:   verdict: '{s}' is the earliest unmet precondition and it belongs to {s}", .{
                stages[index].name,
                stages[index].owner,
            });
        } else {
            log.info("PE64 FIRST FRAME CHAIN:   verdict: every precondition for a first frame was met", .{});
        }
    }

    /// The export shims whose entry proves a milestone, joined into a label.
    ///
    /// Comptime, because the witness table is comptime and the answer is one
    /// fixed string per stage. A stage with no shim witness gets an empty
    /// label, which the report prints as nothing rather than as a witness
    /// that read zero - an absent witness and a silent one are not the same
    /// claim, and only one of them is about the title.
    fn witnessLabel(comptime milestone: []const u8) []const u8 {
        return comptime blk: {
            var label: []const u8 = "";
            for (xenia_kernel_shim_map.witnesses) |witness| {
                if (!std.mem.eql(u8, witness.milestone, milestone)) continue;
                label = if (label.len == 0)
                    witness.export_name
                else
                    label ++ "+" ++ witness.export_name;
            }
            break :blk label;
        };
    }

    /// Whether either of a stage's witnesses fired.
    ///
    /// The implementation and the shim answer the same question and fail
    /// differently: an optimiser can inline the first out of existence, and
    /// nothing can reach the second except the guest. Requiring both would
    /// make an inlined build look like a stalled title, which is the exact
    /// mistake `GraphicsSystem::MarkVblank` cost this project two runs ago.
    fn guestStageMet(self: *const ElfState, comptime milestone: []const u8) bool {
        if (self.guestMilestoneStageHits(milestone) != 0) return true;
        return self.guest_kernel_calls.witnessHitsFor(milestone) != 0;
    }

    /// A virtual Xenia function can be entered through the base symbol or
    /// through the implementation selected by the object's vtable. Both
    /// entries answer the same chain question, so the stage must observe the
    /// pair rather than treating a zero in the base row as a stalled GPU.
    fn guestMilestoneStageHitsAny(
        self: *const ElfState,
        comptime primary: []const u8,
        comptime alternate: []const u8,
    ) u64 {
        return self.guestMilestoneStageHits(primary) +| self.guestMilestoneStageHits(alternate);
    }

    fn guestStageMetAny(
        self: *const ElfState,
        comptime primary: []const u8,
        comptime alternate: []const u8,
    ) bool {
        if (self.guestMilestoneStageHitsAny(primary, alternate) != 0) return true;
        return self.guest_kernel_calls.witnessHitsFor(primary) != 0 or
            self.guest_kernel_calls.witnessHitsFor(alternate) != 0;
    }

    fn guestMilestoneStageObservableAny(
        self: *const ElfState,
        comptime primary: []const u8,
        comptime alternate: []const u8,
    ) bool {
        return self.guestMilestoneStageObservable(primary) or
            self.guestMilestoneStageObservable(alternate);
    }

    fn guestMilestoneStageUnobservableReasonAny(
        self: *const ElfState,
        comptime primary: []const u8,
        comptime alternate: []const u8,
    ) []const u8 {
        if (self.guestMilestoneStageObservableAny(primary, alternate)) return "observable";
        if (!self.guestMilestoneArmed(primary) and !self.guestMilestoneArmed(alternate)) {
            return "this image does not name the base or Vulkan virtual-override symbol";
        }
        if (!self.guestMilestoneArmed(primary)) return self.guestMilestoneUnobservableReason(alternate);
        return self.guestMilestoneUnobservableReason(primary);
    }

    /// The stages between a window that can carry a frame and a window that
    /// carries the title's picture.
    ///
    /// Every stage's evidence is an entry count on one of Xenia's own
    /// functions, except the last two, which are Rosette's. That split is the
    /// point: the transport chain is built entirely from what Rosette can
    /// see, and what Rosette can see cannot distinguish a frame with a
    /// picture from a frame without one. Both look like acquire, clear,
    /// submit, present.
    ///
    /// A row whose symbol the image does not contain reports `unresolved`
    /// rather than `unmet`. Those are different claims: one says Rosette
    /// cannot see the stage, the other says the guest did not reach it, and
    /// reading the first as the second would blame a title for a stripped
    /// binary.
    fn guestOutputChainStages(self: *const ElfState) [GUEST_OUTPUT_STAGE_COUNT]ChainStage {
        const graphics = &self.windows_graphics;
        const m = struct {
            const launch = "_ZN2xe8Emulator14CompleteLaunchERKNSt10filesystem7__cxx114pathESt17basic_string_viewIcSt11char_traitsIcEE";
            const thread = "_ZN2xe6kernel7XThread7ExecuteEv";
            const backend = "_ZN2xe3gpu6vulkan20VulkanGraphicsSystem5SetupEPNS_3cpu9ProcessorEPNS_6kernel11KernelStateEPNS_2ui18WindowedAppContextEb";
            const vblank = "_ZN2xe3gpu14GraphicsSystem10MarkVblankEv";
            const cp_init = "_ZN2xe3gpu16CommandProcessor10InitializeEv";
            const cp_thread = "_ZN2xe3gpu16CommandProcessor16WorkerThreadMainEv";
            const video_mode = "_ZN2xe6kernel8xboxkrnl16VdQueryVideoModeEPNS0_12X_VIDEO_MODEEb";
            const interrupt = "_ZN2xe3gpu14GraphicsSystem20SetInterruptCallbackEjj";
            const ring = "_ZN2xe3gpu14GraphicsSystem20InitializeRingBufferEjj";
            const read_thunk = "_ZN2xe3gpu14GraphicsSystem17ReadRegisterThunkEPvPS1_j";
            const write_thunk = "_ZN2xe3gpu14GraphicsSystem18WriteRegisterThunkEPvPS1_jj";
            const write_pointer = "_ZN2xe3gpu16CommandProcessor18UpdateWritePointerEj";
            const primary = "_ZN2xe3gpu16CommandProcessor20ExecutePrimaryBufferEjj";
            const packet = "_ZN2xe3gpu16CommandProcessor18ExecutePacketType3Ej";
            const primary_vulkan = "_ZN2xe3gpu6vulkan22VulkanCommandProcessor20ExecutePrimaryBufferEjj";
            const packet_vulkan = "_ZN2xe3gpu6vulkan22VulkanCommandProcessor18ExecutePacketType3Ej";
            const swap = "_ZN2xe3gpu6vulkan22VulkanCommandProcessor9IssueSwapEjjj";
            const refresh = "_ZN2xe2ui9Presenter18RefreshGuestOutputEjjjjSt8functionIFbRNS1_25GuestOutputRefreshContextEEE";
            const paint = "_ZN2xe2ui9Presenter17PaintFromUIThreadEb";
        };
        const ring_when_unmet: []const u8 = if (self.guestMilestoneHitsNamed(m.write_pointer) != 0)
            "the title handed Xenia a ring and direct MMIO reached UpdateWritePointer, but the GPU worker never entered ExecutePrimaryBuffer (base or Vulkan override). No interpreted access violation was needed; inspect the write-pointer wake path (NtSetEventBoostPriority) and PE64 GUEST THREADS for the GPU Commands wait"
        else if (self.guestMilestoneHitsNamed(m.write_thunk) != 0 or self.guestMilestoneHitsNamed(m.read_thunk) != 0)
            "the title reached Xenia's graphics register callbacks but no UpdateWritePointer was observed. Compare the direct MMIO milestone counts with PE64 GUEST ACCESS VIOLATIONS to find the missing register handoff"
        else
            "the ring exists but ExecutePrimaryBuffer has not run. Check whether UpdateWritePointer was observed through direct MMIO callbacks or through the protected-page fault chain; the first zero in PE64 GUEST ACCESS VIOLATIONS identifies the missing handoff";

        const packet_headers = self.guestMilestoneHitsNamed("_ZN2xe3gpu6vulkan22VulkanCommandProcessor13ExecutePacketEv");
        const register_packets = self.guestMilestoneHitsNamed("_ZN2xe3gpu6vulkan22VulkanCommandProcessor18ExecutePacketType0Ej") +|
            self.guestMilestoneHitsNamed("_ZN2xe3gpu6vulkan22VulkanCommandProcessor18ExecutePacketType1Ej");
        const type3_handler_entries = self.gpuType3HandlerEntries();
        const swap_when_unmet: []const u8 = if (self.gpu_indirect_buffers_seen != 0 and
            self.gpu_indirect_draw_packets == 0 and self.gpu_ring_draw_packets == 0)
            "the title has not asked for its front buffer to be shown, and PE64 GPU RING says why that is expected: the indirect buffers it submitted carry no DRAW_INDX and no XE_SWAP, so it has initialised the device and set state but has not drawn. VdSwap in PE64 GUEST KERNEL CALLS is the independent witness and it cannot be inlined away"
        else
            "the title has drawn, if it has drawn, but never asked for its front buffer to be shown. A black window is still the expected outcome from here; VdSwap in PE64 GUEST KERNEL CALLS is the independent witness and it cannot be inlined away";
        const ring_pm4_when_unmet: []const u8 = if (self.gpu_ring_alias_mismatches != 0)
            "the title's virtual view of its ring and Xenia's physical view of the same pages disagree, so the GPU reads a different page from the one the title writes. That is Rosette's file-mapping aliasing; PE64 GPU RING shows the windows"
        else if (self.gpu_ring_type3_packets != 0)
            "Rosette's decode of the ring windows found type 3 packets and neither Xenia's type 3 dispatcher nor any of its opcode handlers ran; PE64 GPU RING lists them, and the disagreement is about where the command processor's reader starts"
        else if (self.gpu_ring_dwords_decoded != 0 and self.gpu_ring_zero_dwords == self.gpu_ring_dwords_decoded)
            "every dword the write pointer covered is zero, and Xenia skips a zero header without calling any executor. The title moved the write pointer over memory that holds no commands; PE64 GPU RING shows the windows and the alias checks that clear the mapping"
        else if (register_packets != 0 or self.gpu_ring_type0_packets != 0)
            "the ring carried register writes (type 0/1) and no type 3 command. The title is configuring the GPU without yet asking it to do anything; PE64 GPU RING shows the windows"
        else if (packet_headers != 0)
            "the command processor read packet headers and none reached an executor, so every header was 0, 0x0BADF00D or 0xCDCDCDCD; PE64 GPU RING shows the dwords"
        else
            "the ring advanced but no packet executor ran. PE64 GPU RING decodes the dwords each write-pointer update covered, and its Xenia executed line says which kind of header Xenia read";

        return [GUEST_OUTPUT_STAGE_COUNT]ChainStage{
            .{
                .name = "vulkan_backend_chosen",
                .owner = "xenia:emulator",
                .met = self.guestStageMet(m.backend),
                .evidence = "VulkanGraphicsSystem_Setup_entries",
                .value = self.guestMilestoneStageHits(m.backend),
                .observable = self.guestMilestoneStageObservable(m.backend),
                .unobservable_reason = self.guestMilestoneUnobservableReason(m.backend),
                .witness = witnessLabel(m.backend),
                .witness_value = self.guest_kernel_calls.witnessHitsFor(m.backend),
                .witness_armed = self.guest_kernel_calls.witnessArmedFor(m.backend),
                .when_unmet = "Xenia never built a Vulkan graphics system. Either --gpu selected another backend, or Setup threw before its first instruction. Read the launcher's argument line and PE64 DYNAMIC REFUSALS: a refused D3D12.dll is expected and harmless, a refused vulkan-1.dll is not",
            },
            .{
                .name = "gpu_command_processor_up",
                .owner = "xenia:emulator",
                .met = self.guestStageMet(m.cp_init),
                .evidence = "CommandProcessor_Initialize_entries",
                .value = self.guestMilestoneStageHits(m.cp_init),
                .observable = self.guestMilestoneStageObservable(m.cp_init),
                .unobservable_reason = self.guestMilestoneUnobservableReason(m.cp_init),
                .witness = witnessLabel(m.cp_init),
                .witness_value = self.guest_kernel_calls.witnessHitsFor(m.cp_init),
                .witness_armed = self.guest_kernel_calls.witnessArmedFor(m.cp_init),
                .when_unmet = "the graphics system exists but its command processor did not come up, so there is nothing on the other end of the ring. This is Xenia's own bring-up and no title action can affect it; read the Vulkan device and queue rows of the first-frame chain, because Initialize creates its command pools from them",
            },
            .{
                .name = "gpu_thread_reading",
                .owner = "xenia:gpu-thread",
                .met = self.guestStageMet(m.cp_thread),
                .evidence = "CommandProcessor_WorkerThreadMain_entries",
                .value = self.guestMilestoneStageHits(m.cp_thread),
                .observable = self.guestMilestoneStageObservable(m.cp_thread),
                .unobservable_reason = self.guestMilestoneUnobservableReason(m.cp_thread),
                .witness = witnessLabel(m.cp_thread),
                .witness_value = self.guest_kernel_calls.witnessHitsFor(m.cp_thread),
                .witness_armed = self.guest_kernel_calls.witnessArmedFor(m.cp_thread),
                .when_unmet = "the command processor was built but its worker thread never entered the read loop. That is a thread that did not start or a wait that did not return; PE64 GUEST THREADS names it and says what it is blocked on",
            },
            .{
                // A title that waits for vertical blank before drawing makes
                // no progress at all while this is zero, and the run looks
                // like a GPU fault instead of a stopped clock.
                .name = "display_clock_ticking",
                .owner = "xenia:emulator",
                .met = self.guestStageMet(m.vblank),
                // Which of the two witnesses the count came from, because
                // `MarkVblank_entries=0` alongside a met stage would read as
                // a contradiction rather than as an inlined body.
                .evidence = if (self.guestMilestoneInlinedAway(m.vblank))
                    "EmulateCPInterruptDPC_entries (MarkVblank was inlined away)"
                else
                    "MarkVblank_entries",
                .value = self.guestMilestoneStageHits(m.vblank),
                .observable = self.guestMilestoneStageObservable(m.vblank),
                .unobservable_reason = if (self.guestMilestoneInlinedAway(m.vblank))
                    "MarkVblank was inlined into its callers and KernelState::EmulateCPInterruptDPC, its witness, is not in this image either"
                else
                    self.guestMilestoneUnobservableReason(m.vblank),
                .when_unmet = "the emulated display clock is stopped. Read PE64 STEP BUDGET's guest_clock= first: a guest millisecond that costs far more than a real one starves the frame limiter, and that is what this looked like before the clock moved to the host monotonic source",
            },
            .{
                .name = "emulator_launched",
                .owner = "xenia:emulator",
                .met = self.guestStageMet(m.launch),
                .evidence = "CompleteLaunch_entries",
                .value = self.guestMilestoneStageHits(m.launch),
                .observable = self.guestMilestoneStageObservable(m.launch),
                .unobservable_reason = self.guestMilestoneUnobservableReason(m.launch),
                .witness = witnessLabel(m.launch),
                .witness_value = self.guest_kernel_calls.witnessHitsFor(m.launch),
                .witness_armed = self.guest_kernel_calls.witnessArmedFor(m.launch),
                .when_unmet = "the module was never accepted, so no title thread was ever created. This is a loading failure and not a graphics one; read PE64 AUDIT INPUTS and the XEX/ISO lines, because a title that cannot be read cannot be launched",
            },
            .{
                .name = "title_thread_started",
                .owner = "guest-title",
                .met = self.guestStageMet(m.thread),
                .evidence = "XThread_Execute_entries",
                .value = self.guestMilestoneStageHits(m.thread),
                .observable = self.guestMilestoneStageObservable(m.thread),
                .unobservable_reason = self.guestMilestoneUnobservableReason(m.thread),
                .witness = witnessLabel(m.thread),
                .witness_value = self.guest_kernel_calls.witnessHitsFor(m.thread),
                .witness_armed = self.guest_kernel_calls.witnessArmedFor(m.thread),
                .when_unmet = "no guest thread ever began running translated PowerPC. Everything below this line is unreachable by definition; the investigation is in the loader, not in graphics",
            },
            .{
                .name = "title_queried_video_mode",
                .owner = "guest-title",
                .met = self.guestStageMet(m.video_mode),
                .evidence = "VdQueryVideoMode_entries",
                .value = self.guestMilestoneStageHits(m.video_mode),
                .observable = self.guestMilestoneStageObservable(m.video_mode),
                .unobservable_reason = self.guestMilestoneUnobservableReason(m.video_mode),
                .witness = witnessLabel(m.video_mode),
                .witness_value = self.guest_kernel_calls.witnessHitsFor(m.video_mode),
                .witness_armed = self.guest_kernel_calls.witnessArmedFor(m.video_mode),
                .when_unmet = "the title is running but has not asked the kernel about the display. Read PE64 GUEST KERNEL CALLS: it names every export the title HAS called, in order, and the boot phase they place it in. A title with thousands of calls and no Vd* is stuck before D3D device creation, and the last export it called says where",
            },
            .{
                .name = "title_took_gpu_interrupt",
                .owner = "guest-title",
                .met = self.guestStageMet(m.interrupt),
                .evidence = "SetInterruptCallback_entries",
                .value = self.guestMilestoneStageHits(m.interrupt),
                .observable = self.guestMilestoneStageObservable(m.interrupt),
                .unobservable_reason = self.guestMilestoneUnobservableReason(m.interrupt),
                .witness = witnessLabel(m.interrupt),
                .witness_value = self.guest_kernel_calls.witnessHitsFor(m.interrupt),
                .witness_armed = self.guest_kernel_calls.witnessArmedFor(m.interrupt),
                .when_unmet = "the title has not registered a GPU interrupt handler, so every vertical blank the emulator raises is delivered to nobody. A title that waits on vblank before its first draw cannot leave this state on its own",
            },
            .{
                .name = "title_gave_gpu_a_ring",
                .owner = "guest-title",
                .met = self.guestStageMet(m.ring),
                .evidence = "InitializeRingBuffer_entries",
                .value = self.guestMilestoneStageHits(m.ring),
                .observable = self.guestMilestoneStageObservable(m.ring),
                .unobservable_reason = self.guestMilestoneUnobservableReason(m.ring),
                .witness = witnessLabel(m.ring),
                .witness_value = self.guest_kernel_calls.witnessHitsFor(m.ring),
                .witness_armed = self.guest_kernel_calls.witnessArmedFor(m.ring),
                .when_unmet = "the title has not handed Xenia a command ring. Nothing the command processor does can produce a frame until it does; the ring's address comes from the title's own physical allocation, so a memory failure upstream presents exactly like this",
            },
            .{
                .name = "ring_carried_work",
                .owner = "xenia:gpu-thread",
                .met = self.guestStageMetAny(m.primary, m.primary_vulkan),
                .evidence = "ExecutePrimaryBuffer_entries (base/Vulkan override)",
                .value = self.guestMilestoneStageHitsAny(m.primary, m.primary_vulkan),
                .observable = self.guestMilestoneStageObservableAny(m.primary, m.primary_vulkan),
                .unobservable_reason = self.guestMilestoneStageUnobservableReasonAny(m.primary, m.primary_vulkan),
                .witness = witnessLabel(m.primary),
                .witness_value = self.guest_kernel_calls.witnessHitsFor(m.primary) +| self.guest_kernel_calls.witnessHitsFor(m.primary_vulkan),
                .witness_armed = self.guest_kernel_calls.witnessArmedFor(m.primary) or self.guest_kernel_calls.witnessArmedFor(m.primary_vulkan),
                .when_unmet = ring_when_unmet,
            },
            .{
                .name = "ring_carried_pm4",
                .owner = "xenia:gpu-thread",
                // The dispatcher is inlined into ExecutePacket in this build;
                // a handler only a type 3 packet reaches is the same fact.
                .met = self.guestStageMetAny(m.packet, m.packet_vulkan) or type3_handler_entries != 0,
                .evidence = "ExecutePacketType3_entries (base/Vulkan override) + type 3 opcode handler entries",
                .value = self.guestMilestoneStageHitsAny(m.packet, m.packet_vulkan) +| type3_handler_entries,
                .observable = self.guestMilestoneStageObservableAny(m.packet, m.packet_vulkan) or type3_handler_entries != 0,
                .unobservable_reason = self.guestMilestoneStageUnobservableReasonAny(m.packet, m.packet_vulkan),
                .witness = witnessLabel(m.packet),
                .witness_value = self.guest_kernel_calls.witnessHitsFor(m.packet) +| self.guest_kernel_calls.witnessHitsFor(m.packet_vulkan),
                .witness_armed = self.guest_kernel_calls.witnessArmedFor(m.packet) or self.guest_kernel_calls.witnessArmedFor(m.packet_vulkan),
                .when_unmet = ring_pm4_when_unmet,
            },
            .{
                .name = "title_requested_swap",
                .owner = "guest-title",
                .met = self.guestStageMet(m.swap),
                .evidence = "IssueSwap_entries",
                .value = self.guestMilestoneStageHits(m.swap),
                .observable = self.guestMilestoneStageObservable(m.swap),
                .unobservable_reason = self.guestMilestoneUnobservableReason(m.swap),
                .witness = witnessLabel(m.swap),
                .witness_value = self.guest_kernel_calls.witnessHitsFor(m.swap),
                .witness_armed = self.guest_kernel_calls.witnessArmedFor(m.swap),
                .when_unmet = swap_when_unmet,
            },
            .{
                .name = "guest_output_published",
                .owner = "xenia:gpu-thread",
                .met = self.guestStageMet(m.refresh),
                .evidence = "RefreshGuestOutput_entries",
                .value = self.guestMilestoneStageHits(m.refresh),
                .observable = self.guestMilestoneStageObservable(m.refresh),
                .unobservable_reason = self.guestMilestoneUnobservableReason(m.refresh),
                .witness = witnessLabel(m.refresh),
                .witness_value = self.guest_kernel_calls.witnessHitsFor(m.refresh),
                .witness_armed = self.guest_kernel_calls.witnessArmedFor(m.refresh),
                .when_unmet = "a swap was requested but no finished frame reached the presenter's mailbox. This is the one stage between the title's request and Rosette's window, and it is Xenia's; read the mailbox line below for which end is waiting",
            },
            .{
                // Rosette's own evidence again from here. A draw, a dispatch
                // or a copy is the only Vulkan traffic that can carry a
                // picture; a render pass that clears and ends carries a
                // colour.
                .name = "frame_carried_a_draw",
                .owner = "rosette:vulkan-bridge",
                .met = graphics.content_commands != 0,
                .evidence = "content_commands",
                .value = graphics.content_commands,
                .when_unmet = "frames reached Rosette's bridge but none of them carried a draw, a dispatch or a copy. A render pass that clears and ends is a colour, not a picture; this is the stage that separates the two and it is the only one that can",
            },
            .{
                // One paint is what Xenia does when nothing asks for a
                // second. After the first frame the presenter repaints only
                // when guest output is refreshed or a UI drawer asks, so a
                // count of one here is not a stall - it is the honest number
                // of frames the title requested.
                .name = "paints_are_repeating",
                .owner = "xenia:ui-thread",
                .met = self.guestMilestoneStageHits(m.paint) > 1,
                .evidence = "PaintFromUIThread_entries",
                .value = self.guestMilestoneStageHits(m.paint),
                .observable = self.guestMilestoneStageObservable(m.paint),
                .when_unmet = "the window painted at most once. After the first frame Xenia paints only when guest output is refreshed or a UI drawer asks, so this is a consequence of the stages above and never a finding of its own",
            },
        };
    }

    /// The earliest guest-output stage the run has not reached.
    pub fn guestOutputWall(self: *const ElfState) ?ChainStage {
        for (self.guestOutputChainStages()) |stage| {
            if (!stage.observable) continue;
            if (!stage.met) return stage;
        }
        return null;
    }

    pub fn reportGuestOutputChain(self: *const ElfState) void {
        const stages = self.guestOutputChainStages();
        var met_count: usize = 0;
        var observable_count: usize = 0;
        var first_unmet: ?usize = null;
        for (stages, 0..) |stage, index| {
            if (!stage.observable) continue;
            observable_count += 1;
            if (stage.met) {
                met_count += 1;
            } else if (first_unmet == null) {
                first_unmet = index;
            }
        }
        if (observable_count == 0) {
            log.info("PE64 GUEST OUTPUT CHAIN: not observable in this run: {d} of {d} milestone symbols resolved against the image, so every stage would read unmet whether or not the guest reached it", .{
                self.guest_milestones_resolved,
                GUEST_MILESTONE_COUNT,
            });
            return;
        }
        log.info("PE64 GUEST OUTPUT CHAIN: {d}/{d} observable stages met ({d} not observable in this image); this chain asks whether the title's picture exists, which the first-frame chain cannot: every stage of that one is met by a window showing a single colour", .{
            met_count,
            observable_count,
            stages.len - observable_count,
        });
        for (stages, 0..) |stage, index| {
            const marker: []const u8 = if (!stage.observable)
                "unobservable (this image does not name the symbol)"
            else if (stage.met)
                "met"
            else if (first_unmet != null and index == first_unmet.?)
                "UNMET <- the wall"
            else
                "unmet (downstream of the wall)";
            log.info("PE64 GUEST OUTPUT CHAIN:   {s:<24} owner={s:<22} {s} ({s}={d})", .{
                stage.name,
                stage.owner,
                marker,
                stage.evidence,
                stage.value,
            });
            // The second witness, from the guest side of the boundary. It is
            // printed for every stage that has one, met or not, because the
            // interesting cases are the ones where the two disagree.
            if (stage.witness.len != 0) {
                if (!stage.witness_armed) {
                    log.info("PE64 GUEST OUTPUT CHAIN:     witness {s}: NOT ARMED - this image does not name the export shim, so nothing here can see whether the title called it", .{
                        stage.witness,
                    });
                } else if (stage.witness_value != 0 and stage.value == 0) {
                    log.info("PE64 GUEST OUTPUT CHAIN:     witness {s}={d} while its Xenia-side implementation reads 0: the title DID call this, and the call between the shim and the implementation was inlined. The implementation's zero measures the build, not the run", .{
                        stage.witness,
                        stage.witness_value,
                    });
                } else if (stage.witness_value == 0 and stage.value != 0) {
                    log.info("PE64 GUEST OUTPUT CHAIN:     witness {s}=0 while the implementation reads {d}: Xenia reached this on its own and the title never asked for it, so the count is not evidence of the title's progress", .{
                        stage.witness,
                        stage.value,
                    });
                } else {
                    log.info("PE64 GUEST OUTPUT CHAIN:     witness {s}={d} (the guest-side export shim; nothing inside the image branches to it, so its count is the title's own act)", .{
                        stage.witness,
                        stage.witness_value,
                    });
                }
            }
            // What to do about it. Printed for every unmet stage rather than
            // only the wall: a reader who has already fixed the wall wants to
            // know what the next one will ask of them, and `unmet (downstream
            // of the wall)` has said nothing for five runs.
            if (stage.observable and !stage.met and stage.when_unmet.len != 0) {
                log.info("PE64 GUEST OUTPUT CHAIN:     -> {s}", .{stage.when_unmet});
            }
        }
        // The mailbox has two ends and they fail differently. A painter that
        // polls an empty mailbox is waiting for the title; a producer that
        // fills one nobody reads is a dropped frame. `ConsumeGuestOutput` is
        // entered on every paint whether or not a frame was there, so its
        // entry count is a poll count and never belonged in the chain as a
        // stage - it read `met` on the 2026-09-12 run while the producer had
        // run zero times.
        const polls = self.guestMilestoneHitsNamed("_ZN2xe2ui9Presenter18ConsumeGuestOutputERjPNS1_21GuestOutputPropertiesEPNS1_22GuestOutputPaintConfigE");
        const publishes = self.guestMilestoneHitsNamed("_ZN2xe2ui9Presenter18RefreshGuestOutputEjjjjSt8functionIFbRNS1_25GuestOutputRefreshContextEEE");
        if (polls != 0 or publishes != 0) {
            log.info("PE64 GUEST OUTPUT CHAIN:   guest output mailbox: the painter polled it {d} time(s), the GPU thread filled it {d} time(s); a poll is not a frame, and more polls than fills is the painter waiting on the title rather than a frame being dropped", .{
                polls,
                publishes,
            });
        }
        if (first_unmet) |index| {
            log.info("PE64 GUEST OUTPUT CHAIN:   verdict: '{s}' is the earliest stage the title has not reached and it belongs to {s}", .{
                stages[index].name,
                stages[index].owner,
            });
            // A wall the title owns used to end the report. It is the case
            // that needs the most saying, because "the title has not done X"
            // is not a diagnosis until something says what it did instead -
            // and the kernel census is the only thing in Rosette that can.
            if (std.mem.eql(u8, stages[index].owner, "guest-title")) {
                const census = &self.guest_kernel_calls;
                if (census.armed == 0) {
                    log.info("PE64 GUEST OUTPUT CHAIN:   the wall belongs to the title and no kernel export shim is armed, so nothing in this run can say what the title did instead. That is the gap to close before this verdict can be acted on", .{});
                } else if (census.distinct_entered == 0) {
                    log.info("PE64 GUEST OUTPUT CHAIN:   the wall belongs to the title, and the title has not made one kernel call out of {d} armed export(s). It is running translated code that has never reached an import thunk; read PE64 GUEST CODE PROGRESS for whether that code is advancing", .{
                        census.armed,
                    });
                } else {
                    log.info("PE64 GUEST OUTPUT CHAIN:   the wall belongs to the title, which has made {d} call(s) across {d} distinct kernel export(s) and reached boot phase '{s}'. PE64 GUEST KERNEL CALLS below lists them in the order it first made them; the last row of that list is where it stopped asking for new things", .{
                        census.total_calls,
                        census.distinct_entered,
                        census.furthest_phase.label(),
                    });
                    if (census.slotAt(census.last_slot)) |latest| {
                        log.info("PE64 GUEST OUTPUT CHAIN:   its most recent kernel call of any kind was {s} at step {d}", .{
                            latest.export_name,
                            census.last_step,
                        });
                    }
                }
                self.reportGuestTitleThreadForWall();
            }
        } else {
            log.info("PE64 GUEST OUTPUT CHAIN:   verdict: the title produced output and the window is repainting it", .{});
        }
    }

    /// Where a worker thread is right now: its live RIP when it is the one
    /// executing, its parked RIP otherwise.
    /// Which symbol the vblank count came from in this image.
    ///
    /// `MarkVblank` when the build kept it out of line, its witness when the
    /// build inlined it, and a marker when neither can be seen. Printing the
    /// number without the source is how `MarkVblank_entries=0` was read for
    /// two runs as a stopped display clock.
    fn vblankWitnessName(self: *const ElfState) []const u8 {
        const vblank = "_ZN2xe3gpu14GraphicsSystem10MarkVblankEv";
        if (!self.guestMilestoneArmed(vblank)) return "no witness: this image names neither symbol";
        if (!self.guestMilestoneInlinedAway(vblank)) return "GraphicsSystem::MarkVblank";
        const proxy = xenia_guest_milestone_map.inlineProxyOf(vblank);
        if (proxy.len != 0 and self.guestMilestoneArmed(proxy)) {
            return "KernelState::EmulateCPInterruptDPC, because MarkVblank was inlined into the frame limiter";
        }
        return "no witness: MarkVblank was inlined away and its stand-in is not in this image";
    }

    /// Describe a wait handle that turns out to be another guest thread.
    ///
    /// Returns an empty slice when the handle names something else - an
    /// event, a mutant, an object Rosette does not track as a thread - so the
    /// caller's line is unchanged in that case. Naming only what is certain
    /// keeps the annotation from becoming a guess.
    fn describeWindowsWaitTarget(self: *const ElfState, handle: u64, buffer: []u8) []const u8 {
        if (handle == 0) return "";
        const interpreted = self.totalInterpretedSteps();
        for (&self.windows_guest_threads) |*candidate| {
            if (candidate.status == .vacant) continue;
            if (candidate.handle != handle) continue;
            const share = if (interpreted == 0) 0 else @divTrunc(candidate.executed_steps *| 100, interpreted);
            return std.fmt.bufPrint(buffer, " (thread '{s}' {s}, {d}% of the run)", .{
                if (candidate.name_len != 0) candidate.nameText() else "unnamed by the guest",
                @tagName(candidate.status),
                share,
            }) catch "";
        }
        return "";
    }

    /// Distinguish a real wait cycle from a join chain whose target is still
    /// runnable. A bare blocked handle cannot answer that question: the main
    /// thread in the observed run waited on a live XThread, and the live
    /// XThread was itself the one doing useful work. Follow only the bounded
    /// guest-thread edges and keep non-thread objects as a separate verdict.
    fn windowsJoinVerdict(self: *const ElfState, handle: u64) []const u8 {
        if (handle == 0) return "not_thread_join";
        var current = handle;
        var seen: [8]u64 = [_]u64{0} ** 8;
        var depth: usize = 0;
        while (depth < seen.len) : (depth += 1) {
            for (seen[0..depth]) |previous| {
                if (previous == current) return "join_cycle";
            }
            seen[depth] = current;
            const index = self.windowsGuestThreadIndex(current) orelse return if (depth == 0) "not_thread_join" else "chain_to_non_thread";
            const thread = &self.windows_guest_threads[index];
            switch (thread.status) {
                .completed, .failed => return if (depth == 0) "target_completed" else "chain_reaches_completed",
                .pending, .runnable, .running => return if (depth == 0) "active_target" else "chain_reaches_active_target",
                .blocked => {
                    if (thread.blocked_wait_handle == 0) return if (depth == 0) "target_blocked" else "chain_reaches_blocked_target";
                    current = thread.blocked_wait_handle;
                },
                .vacant => return "not_thread_join",
            }
        }
        return "join_chain_too_deep";
    }

    /// Read guest bytes for the spin disassembler.
    ///
    /// Routed through the same two sources `decodeAt` uses, so a loop in a
    /// JIT buffer disassembles exactly as one in the image does. A separate
    /// path here would be a second answer to "what bytes are at this
    /// address", and the two would drift.
    fn readGuestCodeForSpin(context: *const anyopaque, address: u64, out: []u8) usize {
        const self: *const ElfState = @ptrCast(@alignCast(context));
        if (self.addrToOffset(address)) |offset| {
            if (offset >= self.mem.len) return 0;
            const available = @min(out.len, self.mem.len - offset);
            @memcpy(out[0..available], self.mem[offset..][0..available]);
            return available;
        }
        // Ask for the whole window, halving until the mapping can supply it.
        // This asked for one byte, so every instruction in Xenia's code cache
        // reached the decoder as a single byte and a JIT spin decoded as
        // nothing: "0 instruction(s) decoded" on the 2026-09-13 run.
        var wanted: usize = out.len;
        while (wanted != 0) : (wanted /= 2) {
            if (self.windowsMappedCodeMemoryConst(address, wanted)) |generated| {
                const available = @min(wanted, generated.bytes.len);
                @memcpy(out[0..available], generated.bytes[0..available]);
                return available;
            }
        }
        return 0;
    }

    /// Where a Rosette address sits in Xenia's guest memory, as a log suffix.
    ///
    /// Xenia's translated code addresses guest memory as membase plus the
    /// guest address. A spin in its code cache that reads `[rdi+0x7fc80714]`
    /// is a title polling a GPU register, and the symbolizer can only call
    /// that address "guest heap".
    fn describeXeniaGuestAddress(self: *const ElfState, address: u64, buffer: []u8) []const u8 {
        const membase = self.xeniaVirtualMembase() orelse return "";
        if (address < membase) return "";
        const offset = address - membase;
        if (offset >= 0x1_0000_0000) {
            if (offset < 0x1_2000_0000) return std.fmt.bufPrint(buffer, " xenia_physical=0x{x}", .{offset - 0x1_0000_0000}) catch "";
            return "";
        }
        if (offset >= 0x7FC8_0000 and offset < 0x7FD0_0000) {
            const index: u16 = @truncate((offset & 0xFFFF) / 4);
            return std.fmt.bufPrint(buffer, " xenia_guest=0x{x} gpu_register=0x{x:0>4} {s}", .{ offset, index, xenosRegisterName(index) }) catch "";
        }
        if (offset >= 0x7FEA_0000 and offset < 0x7FEB_0000) {
            return std.fmt.bufPrint(buffer, " xenia_guest=0x{x} apu_register=0x{x:0>4}", .{ offset, (offset & 0xFFFF) / 4 }) catch "";
        }
        return std.fmt.bufPrint(buffer, " xenia_guest=0x{x}", .{offset}) catch "";
    }

    /// Disassemble the loop a thread is going round in, and name what it
    /// reads.
    ///
    /// The report a run needs once the wall belongs to the guest. "A thread
    /// is busy at an address" is not a finding - a thread rasterizing a font
    /// atlas looks the same. What separates them is whether the addresses
    /// move, and if they do not, what the unmoving code reads and who is
    /// supposed to write it.
    fn reportGuestThreadSpin(self: *const ElfState, index: usize) void {
        const thread = &self.windows_guest_threads[index];
        const bounds = thread.code.recentBounds() orelse return;
        const registers = if (self.windows_active_guest_thread_slot == index)
            &self.regs
        else
            &thread.context.regs;
        const listing = spin_anatomy.disassemble(
            .{ .context = self, .read = readGuestCodeForSpin },
            registers,
            bounds.low,
            bounds.high,
        );
        var where: [guest_symbol_text_bytes]u8 = undefined;
        log.info("PE64 SPIN ANATOMY: thread 0x{x} '{s}' is looping in [0x{x},0x{x}) ({d} bytes, {s}); {d} instruction(s) decoded{s}", .{
            thread.handle,
            if (thread.name_len != 0) thread.nameText() else "unnamed by the guest",
            bounds.low,
            bounds.high + 1,
            bounds.high - bounds.low + 1,
            self.describeGuestAddressOrUnnamed(bounds.low, &where),
            listing.count,
            if (listing.truncated) " (window longer than the instrument reads; this is a prefix)" else "",
        });
        if (listing.undecodable_at) |address| {
            // A window that will not decode is a finding in itself: the
            // thread is not executing what this instrument thinks it is.
            log.info("PE64 SPIN ANATOMY:   decoding stopped at 0x{x}: either the bytes are not instructions or the address is not mapped, and both mean the sampled window is not the loop", .{address});
        }
        for (listing.slice()) |instruction| {
            if (instruction.memory) |address| {
                var target: [guest_symbol_text_bytes]u8 = undefined;
                var xenia_text: [96]u8 = undefined;
                log.info("PE64 SPIN ANATOMY:     0x{x}: {s:<28} reads/writes 0x{x} ({s}){s} base={s} displacement=0x{x}", .{
                    instruction.address,
                    @tagName(instruction.op),
                    address,
                    self.describeGuestAddressOrUnnamed(address, &target),
                    self.describeXeniaGuestAddress(address, &xenia_text),
                    if (instruction.base_reg) |reg| @tagName(reg) else "<none>",
                    instruction.displacement,
                });
            } else {
                log.info("PE64 SPIN ANATOMY:     0x{x}: {s}", .{ instruction.address, @tagName(instruction.op) });
            }
        }
        // The addresses the loop touches, with what is in them now. For a
        // poll this is the whole answer: the thread is waiting for one of
        // these to change, and whoever writes it has not.
        var touched: [8]u64 = undefined;
        const touched_count = listing.touchedAddresses(&touched);
        for (touched[0..touched_count]) |address| {
            if (self.guestMemoryConst(address, 8) == null) {
                log.info("PE64 SPIN ANATOMY:   polls 0x{x}: not mapped, so the loop is reading memory nothing backs", .{address});
                continue;
            }
            var target: [guest_symbol_text_bytes]u8 = undefined;
            var xenia_text: [96]u8 = undefined;
            log.info("PE64 SPIN ANATOMY:   polls 0x{x} ({s}){s} = 0x{x}; if this loop is waiting, that is the value that has to change and whoever writes it has not", .{
                address,
                self.describeGuestAddressOrUnnamed(address, &target),
                self.describeXeniaGuestAddress(address, &xenia_text),
                self.read64(address),
            });
        }
        if (touched_count == 0) {
            log.info("PE64 SPIN ANATOMY:   the loop reads no memory, so it is not waiting on anything: it is computing, or turning on a register a fault or an interrupt is meant to change", .{});
        }
        if (thread.last_import_len != 0) {
            log.info("PE64 SPIN ANATOMY:   the last boundary this thread crossed was {s} at step {d}, {d} import call(s) into its life. That is what it was in the middle of when it stopped getting anywhere", .{
                thread.lastImportText(),
                thread.last_import_step,
                thread.import_calls,
            });
        } else {
            log.info("PE64 SPIN ANATOMY:   this thread has never called a Windows import, so nothing it does crosses a boundary Rosette can name. Its whole life is inside code the guest generated", .{});
        }
        if (thread.last_milestone != 0) {
            const milestone = xenia_guest_milestone_map.milestones[thread.last_milestone - 1];
            log.info("PE64 SPIN ANATOMY:   the last named guest function it entered was {s} at step {d}", .{ milestone.readable, thread.last_milestone_step });
        }
        log.info("PE64 SPIN ANATOMY:   registers: rax=0x{x} rbx=0x{x} rcx=0x{x} rdx=0x{x} rsi=0x{x} rdi=0x{x} rbp=0x{x} rsp=0x{x} r12=0x{x} r13=0x{x} r14=0x{x} r15=0x{x}", .{
            registers.rax, registers.rbx, registers.rcx, registers.rdx,
            registers.rsi, registers.rdi, registers.rbp, registers.rsp,
            registers.r12, registers.r13, registers.r14, registers.r15,
        });
    }

    /// Record a region of the guest's address space.
    ///
    /// Called by the loader for the image's sections and the thunk area, and
    /// by the Win32 surface for allocations. Bounded and silent on overflow;
    /// the report states the overflow count rather than each drop.
    pub fn noteGuestRegion(
        self: *ElfState,
        address: u64,
        length: u64,
        kind: guest_address_space.RegionKind,
        label: []const u8,
    ) void {
        _ = self.guest_regions.insert(address, length, kind, label);
    }

    /// Record an allocation the guest made, so a thread later found executing
    /// inside it can be told what it is running.
    pub fn noteGuestExecutableAllocation(self: *ElfState, address: u64, length: u64, protection: u32) void {
        self.noteGuestExecutableAllocationFrom(address, length, protection, 0);
    }

    /// The same, labelled with the code that asked for it.
    ///
    /// A region reading `generated-code+0x44b` says the thread is in memory
    /// the guest generated. A region reading
    /// `generated-code:X64CodeCache::AllocateCode+0x44b` says which part of
    /// the guest generated it, and that is usually the whole answer: a
    /// translator's first page holds its dispatch thunks, and a thread going
    /// round inside those is not running the title's code at all.
    pub fn noteGuestExecutableAllocationFrom(
        self: *ElfState,
        address: u64,
        length: u64,
        protection: u32,
        caller_rip: u64,
    ) void {
        if (!guest_address_space.protectionAllowsExecute(protection)) return;
        var caller_text: [guest_symbol_text_bytes]u8 = undefined;
        const label = if (caller_rip == 0)
            "guest-allocated executable memory"
        else blk: {
            const described = self.describeGuestAddress(caller_rip, &caller_text);
            break :blk if (described.len == 0) "guest-allocated executable memory" else described;
        };
        var covered: u64 = 0;
        while (covered < length) : (covered +|= guest_address_space.discovered_code_granule) {
            if (!self.guest_regions.extend(
                address +| covered,
                guest_address_space.discovered_code_granule,
                .generated_code,
                label,
            )) return;
        }
    }

    /// Every region Rosette recorded, and how much of the run asked about it.
    pub fn reportGuestAddressSpace(self: *const ElfState) void {
        const map = &self.guest_regions;
        if (map.count == 0) return;
        log.info("PE64 ADDRESS SPACE: {d} region(s) recorded; {d} lookup(s) landed in none of them. A guest address with no symbol still has an owner, and this is the table that names it", .{
            map.count,
            map.unmapped_lookups,
        });
        for (map.regions[0..map.count]) |*region| {
            log.info("PE64 ADDRESS SPACE:   [0x{x},0x{x}) {d} bytes {s:<20} executable={} lookups={d} {s}", .{
                region.start,
                region.end,
                region.length(),
                region.kind.label(),
                region.kind.isCode(),
                region.lookups,
                region.label(),
            });
        }
        if (map.overflow != 0) {
            log.info("PE64 ADDRESS SPACE:   {d} region(s) did not fit the bounded table", .{map.overflow});
        }
    }

    /// The address of one of the CRT's timezone globals.
    ///
    /// `__daylight`, `__timezone` and `__tzname` are accessor *functions* that
    /// return pointers the caller dereferences without checking. A stub
    /// returning zero is therefore not a wrong timezone - it is a null
    /// dereference in the guest, which is why these three are handled here
    /// rather than left to the ABI fallback.
    ///
    /// One block holds all three: an `int` daylight flag, a `long` offset,
    /// and a two-entry array of `char *` pointing at the names. Rosette
    /// reports UTC, so the flag is zero, the offset is zero, and both names
    /// are "UTC".
    pub fn windowsTimezoneGlobal(self: *ElfState, name: []const u8) u64 {
        if (self.windows_timezone_block == 0) {
            //  +0  int   daylight
            //  +8  long  timezone
            // +16  char *tzname[2]
            // +32  "UTC\0" the two names share
            const block = self.guestAlloc(64, 16) orelse return 0;
            self.windows_timezone_block = block;
            self.write32(block + 0, 0);
            self.write64(block + 8, 0);
            const text = block + 32;
            if (self.guestMemory(text, 4)) |bytes| @memcpy(bytes, "UTC\x00");
            self.write64(block + 16, text);
            self.write64(block + 24, text);
        }
        const block = self.windows_timezone_block;
        if (std.mem.eql(u8, name, "__daylight")) return block + 0;
        if (std.mem.eql(u8, name, "__timezone")) return block + 8;
        return block + 16; // __tzname
    }

    /// The static `struct tm` `gmtime` returns a pointer into.
    ///
    /// The C library's contract is that the result points at storage the
    /// library owns and the next call overwrites. Allocating per call would
    /// leak; returning null would be a guest crash.
    pub fn windowsStaticTmBuffer(self: *ElfState) u64 {
        if (self.windows_static_tm == 0) {
            self.windows_static_tm = self.guestAlloc(64, 16) orelse 0;
        }
        return self.windows_static_tm;
    }

    /// Carry an `OutputDebugString` into Rosette's own log.
    ///
    /// Rosette is the debugger this call is addressed to. Discarding the text
    /// would throw away the one channel a guest has for saying something no
    /// counter can express, and the first few are usually the interesting
    /// ones - so they are logged, then counted.
    pub fn noteWindowsDebugString(self: *ElfState, text: []const u8) void {
        self.windows_debug_strings +|= 1;
        if (text.len == 0) return;
        if (self.windows_debug_strings <= 32) {
            log.info("PE64 guest debug string #{d}: {s}", .{ self.windows_debug_strings, text });
        } else if (self.windows_debug_strings == 33) {
            log.info("PE64 guest debug string: further OutputDebugString calls are counted rather than printed", .{});
        }
    }

    /// Record the name the guest gave one of its threads.
    ///
    /// `handle` is the Win32 thread handle, or the `GetCurrentThread`
    /// pseudo-handle, in which case the name lands on whichever worker is
    /// executing - which is what `xe::threading::set_name(name)` means.
    ///
    /// Returns whether a slot took the name. A false is not an error: a guest
    /// can name a thread Rosette runs on the owner loop rather than in a
    /// worker slot, and a report that says nothing about that thread is
    /// better than one that labels the wrong one.
    pub fn setWindowsGuestThreadName(self: *ElfState, handle: u64, name: []const u8) bool {
        if (name.len == 0) return false;
        const slot = self.windowsGuestThreadSlotForName(handle) orelse return false;
        const thread = &self.windows_guest_threads[slot];
        const length = @min(name.len, WINDOWS_GUEST_THREAD_NAME_BYTES);
        // Printable ASCII only: the name goes straight into a log line, and a
        // guest is free to put anything in the string it hands the API.
        var written: usize = 0;
        for (name[0..length]) |byte| {
            thread.name[written] = if (byte >= 0x20 and byte < 0x7F) byte else '?';
            written += 1;
        }
        thread.name_len = @intCast(written);
        return true;
    }

    fn windowsGuestThreadSlotForName(self: *const ElfState, handle: u64) ?usize {
        // The `GetCurrentThread` pseudo-handle names the caller, which under
        // a cooperative scheduler is the worker holding the slice.
        if (handle == 0 or handle == std.math.maxInt(u64) - 1) return self.windows_active_guest_thread_slot;
        for (&self.windows_guest_threads, 0..) |*thread, index| {
            if (thread.status == .vacant) continue;
            if (thread.handle == handle) return index;
        }
        return self.windows_active_guest_thread_slot;
    }

    fn windowsGuestThreadRip(self: *const ElfState, index: usize) u64 {
        if (self.windows_active_guest_thread_slot) |active| {
            if (active == index) return self.regs.rip;
        }
        return self.windows_guest_threads[index].context.regs.rip;
    }

    /// The live worker holding the largest share of the run, if any. A
    /// completed worker may retain historical instruction steps in its table
    /// slot, but it cannot be the source of current starvation or slowdown.
    fn busiestWindowsGuestThread(self: *const ElfState) ?usize {
        var best: ?usize = null;
        for (&self.windows_guest_threads, 0..) |*thread, index| {
            if (!isLiveWindowsGuestThread(thread.status)) continue;
            if (thread.executed_steps == 0) continue;
            if (best == null or thread.executed_steps > self.windows_guest_threads[best.?].executed_steps) {
                best = index;
            }
        }
        return best;
    }

    /// One line naming the thread that is spending the run.
    ///
    /// The frontier sampler reads `self.regs.rip`, which at a checkpoint is
    /// always the owner - so on a run where the workers hold ninety percent
    /// of the budget the frontier histogram describes the one thread that is
    /// doing the least. This is the line that says who the other ninety
    /// percent belongs to.
    /// Roll each thread's code-page fingerprint into the previous window and
    /// start a new one. Called once per checkpoint, so the report reads
    /// "where this thread has been lately" rather than "everywhere it has
    /// ever been", which saturates and says nothing.
    fn rollGuestThreadCodeWindows(self: *ElfState) void {
        for (&self.windows_guest_threads) |*thread| {
            if (thread.status == .vacant) continue;
            thread.code.roll();
        }
    }

    fn logGuestThreadShare(self: *const ElfState) void {
        const index = self.busiestWindowsGuestThread() orelse return;
        const thread = &self.windows_guest_threads[index];
        const interpreted = self.totalInterpretedSteps();
        if (interpreted == 0) return;
        var live: usize = 0;
        var created: usize = 0;
        var completed: usize = 0;
        var failed: usize = 0;
        for (&self.windows_guest_threads) |*candidate| {
            switch (candidate.status) {
                .vacant => {},
                .completed => {
                    created += 1;
                    completed += 1;
                },
                .failed => {
                    created += 1;
                    failed += 1;
                },
                else => {
                    created += 1;
                    if (isLiveWindowsGuestThread(candidate.status)) live += 1;
                },
            }
        }
        var where: [guest_symbol_text_bytes]u8 = undefined;
        var start: [guest_symbol_text_bytes]u8 = undefined;
        log.info("PE64 THREAD SHARE: {d} live worker(s), {d} created ({d} completed, {d} failed); busiest handle=0x{x}{s}{s}{s} status={s} steps={d} ({d}% of the run) at={s} rip=0x{x} pages~{d} start={s}", .{
            live,
            created,
            completed,
            failed,
            thread.handle,
            if (thread.name_len != 0) " name='" else "",
            thread.nameText(),
            if (thread.name_len != 0) "'" else "",
            @tagName(thread.status),
            thread.executed_steps,
            @divTrunc(thread.executed_steps *| 100, interpreted),
            self.describeGuestAddressOrUnnamed(self.windowsGuestThreadRip(index), &where),
            self.windowsGuestThreadRip(index),
            thread.codePages(),
            self.describeGuestAddressOrUnnamed(thread.start_routine, &start),
        });
    }

    /// Every guest worker, what it has spent, and where it is.
    ///
    /// Nothing else in the run reports this. The checkpoint's `workers(...)`
    /// tuple counts statuses, the frontier samples only the owner, and the
    /// scheduler line totals the slices without saying who took them - so a
    /// run in which one thread spins and thirteen starve looks exactly like a
    /// run in which the work is shared.
    pub fn reportGuestThreads(self: *const ElfState) void {
        const interpreted = self.totalInterpretedSteps();
        var created: usize = 0;
        var live: usize = 0;
        var completed: usize = 0;
        var failed: usize = 0;
        var vacant: usize = 0;
        for (&self.windows_guest_threads) |*thread| {
            switch (thread.status) {
                .vacant => vacant += 1,
                .completed => {
                    created += 1;
                    completed += 1;
                },
                .failed => {
                    created += 1;
                    failed += 1;
                },
                else => {
                    created += 1;
                    if (isLiveWindowsGuestThread(thread.status)) live += 1;
                },
            }
        }
        const worker_steps = self.windows_worker_executed_steps;
        if (created == 0) {
            log.info("PE64 GUEST THREADS: no guest worker threads were created", .{});
            return;
        }
        // Keep lifecycle counts explicit. A completed one-shot worker is a
        // valid Windows outcome and is not evidence that a requested thread
        // failed to start; only a failed status or a refused creation is a
        // lifecycle defect.
        log.info("PE64 GUEST THREADS: created={d} live={d} completed={d} failed={d} vacant={d} capacity={d}; completed workers are normal one-shot exits, while failed={d} or refused={d} identify lifecycle loss", .{
            created,
            live,
            completed,
            failed,
            vacant,
            self.windows_guest_threads.len,
            failed,
            self.windows_thread_table_full,
        });
        if (self.windows_thread_suspended_creations != 0 or self.windows_thread_suspend_calls != 0 or self.windows_thread_resume_calls != 0) {
            log.info("PE64 GUEST THREADS: suspension created_suspended={d} suspend_calls={d} resume_calls={d}; a thread whose suspend count is not zero is never scheduled, as CREATE_SUSPENDED and SuspendThread promise", .{
                self.windows_thread_suspended_creations,
                self.windows_thread_suspend_calls,
                self.windows_thread_resume_calls,
            });
        }
        log.info("PE64 GUEST THREADS: {d} live (active statuses pending/runnable/running/blocked; table holds {d} slots and gives a finished thread's slot to a new one when it is full; {d} reused, {d} refused); workers ran {d} of {d} interpreted instruction(s) ({d}%), the owner ran {d}", .{
            live,
            self.windows_guest_threads.len,
            self.windows_thread_slots_recycled,
            self.windows_thread_table_full,
            worker_steps,
            interpreted,
            if (interpreted == 0) 0 else @divTrunc(worker_steps *| 100, interpreted),
            self.executed_steps,
        });
        var spinning_threads: usize = 0;
        for (&self.windows_guest_threads, 0..) |*thread, index| {
            if (!isLiveWindowsGuestThread(thread.status)) continue;
            var where: [guest_symbol_text_bytes]u8 = undefined;
            var start: [guest_symbol_text_bytes]u8 = undefined;
            const share = if (interpreted == 0) 0 else @divTrunc(thread.executed_steps *| 100, interpreted);
            // The raw rip is printed beside the symbol because the two
            // answer different questions: a thread whose rip lies outside the
            // image has no symbol by construction - it is running in a JIT
            // buffer or a Rosette thunk - and `<unnamed>` alone cannot say
            // which of those it is.
            log.info("PE64 GUEST THREADS:   handle=0x{x} {s:<9} steps={d} ({d}%) name='{s}' at={s} rip=0x{x} code_span={d}B pages~{d} start={s}{s}", .{
                thread.handle,
                @tagName(thread.status),
                thread.executed_steps,
                share,
                if (thread.name_len != 0) thread.nameText() else "<unnamed by the guest>",
                self.describeGuestAddressOrUnnamed(self.windowsGuestThreadRip(index), &where),
                self.windowsGuestThreadRip(index),
                thread.codeSpan(),
                thread.codePages(),
                self.describeGuestAddressOrUnnamed(thread.start_routine, &start),
                if (self.windows_active_guest_thread_slot == index) " <- executing now" else "",
            });
            if (thread.suspend_count != 0) {
                log.info("PE64 GUEST THREADS:     suspended suspend_count={d}: created suspended or suspended since, and not resumed; the scheduler will not run it until ResumeThread brings the count to zero", .{thread.suspend_count});
            }
            // A busy thread inside a handful of pages is spinning; the same
            // thread across dozens is working. Only said where it can be
            // wrong to guess: a thread with a real share of the run.
            if (share >= 5 and thread.code.samples != 0) {
                if (thread.code.isSpin()) {
                    log.info("PE64 GUEST THREADS:     this thread spent {d}% of the run going round [0x{x},0x{x}] - {d} byte(s), {d} page(s). That is a spin, not progress; PE64 SPIN ANATOMY says what it reads", .{
                        share,
                        thread.code.recentBounds().?.low,
                        thread.code.recentBounds().?.high,
                        thread.code.recentSpan(),
                        thread.codePages(),
                    });
                    spinning_threads += 1;
                } else {
                    // Both ends named. `code_span` is a subtraction across
                    // whatever regions the thread has touched, so a thread
                    // that runs in Xenia's JIT cache and calls into the image
                    // reports gigabytes and reads as chaos; the two region
                    // names say what it actually straddles, which for the
                    // title's own thread is the whole shape of what it does.
                    var low_text: [guest_symbol_text_bytes]u8 = undefined;
                    var high_text: [guest_symbol_text_bytes]u8 = undefined;
                    log.info("PE64 GUEST THREADS:     {d}% of the run across {d} page(s), lifetime code=[0x{x},0x{x}]: broad execution footprint, NOT proof of progress or absence of a multi-function polling loop. Those ends are {s} and {s}", .{
                        share,
                        thread.codePages(),
                        thread.code.low,
                        thread.code.high,
                        self.describeGuestAddressOrUnnamed(thread.code.low, &low_text),
                        self.describeGuestAddressOrUnnamed(thread.code.high, &high_text),
                    });
                }
            }
            if (share >= 5) {
                for (thread.code.heat.top(), 0..) |candidate, rank| {
                    if (candidate.count == 0) continue;
                    var hotspot_text: [guest_symbol_text_bytes]u8 = undefined;
                    log.info("PE64 CPU HOTSPOT: thread=0x{x} name='{s}' rank={d} region=0x{x} at={s} samples={d} count_lower/upper={d}/{d}; 256-byte lifetime candidate, one sample per ~1024 worker instructions; not a wall-time or spin verdict", .{ thread.handle, if (thread.name_len != 0) thread.nameText() else "<unnamed>", rank + 1, candidate.address, self.describeGuestAddressOrUnnamed(candidate.address, &hotspot_text), thread.code.heat.samples, candidate.count - candidate.error_bound, candidate.count });
                }
            }
            // What this thread last asked the emulated kernel for. For every
            // thread but the title's this is a curiosity; for the title's it
            // is the only narrative there is, because everything it runs in
            // between is translated PowerPC with no name.
            if (thread.kernel_calls != 0) {
                const last_call = self.guest_kernel_calls.slotAt(thread.last_kernel_slot);
                log.info("PE64 GUEST THREADS:     kernel calls={d}; the last was {s}!{s} at step {d}", .{
                    thread.kernel_calls,
                    if (last_call) |slot| slot.module.moduleName() else "<unknown>",
                    if (last_call) |slot| slot.export_name else "<none recorded>",
                    thread.last_kernel_step,
                });
            } else if (thread.entered_xenia_title) {
                log.info("PE64 GUEST THREADS:     this thread runs the title and has made no kernel call at all; it is executing translated PowerPC that never reaches an import thunk, which PE64 GUEST CODE PROGRESS can say is new code or a loop", .{});
            }
            if (thread.status == .blocked) {
                // When the object being waited on is another guest thread,
                // name it. A wait graph printed as bare handles has to be
                // reassembled by hand from the handle column above it, and
                // the whole question a reader has is "who is it waiting for,
                // and is that one making progress?".
                var target_text: [96]u8 = undefined;
                const target = self.describeWindowsWaitTarget(thread.blocked_wait_handle, &target_text);
                const join = self.windowsJoinVerdict(thread.blocked_wait_handle);
                const blocked_age_steps = if (thread.blocked_since_total_steps == 0)
                    0
                else
                    self.totalInterpretedSteps() -| thread.blocked_since_total_steps;
                const blocked_age_ticks = if (thread.blocked_since_guest_ticks == 0)
                    0
                else
                    self.guest_clock.ticks -| thread.blocked_since_guest_ticks;
                var owner_text: [128]u8 = undefined;
                const lock_owner: []const u8 = blk: {
                    if (thread.blocked_srw_lock == 0) break :blk "";
                    const lock_index = self.windowsSrwLockIndex(thread.blocked_srw_lock) orelse break :blk " (no lock record)";
                    const lock = self.windows_srw_locks[lock_index];
                    var name_text: [96]u8 = undefined;
                    break :blk std.fmt.bufPrint(&owner_text, " (held by {s}, {d} waiting)", .{
                        self.describeWindowsSrwOwner(lock.owner_thread_id, &name_text),
                        self.windowsSrwWaiterCount(lock),
                    }) catch "";
                };
                log.info("PE64 GUEST THREADS:     blocked_on wait=0x{x}{s} join={s} age_steps={d} age_ticks={d} lock=0x{x}{s} condition=0x{x} timeout={d} deadline={d}", .{
                    thread.blocked_wait_handle,
                    target,
                    join,
                    blocked_age_steps,
                    blocked_age_ticks,
                    thread.blocked_srw_lock,
                    lock_owner,
                    thread.blocked_condition,
                    thread.blocked_wait_timeout,
                    thread.blocked_wait_deadline,
                });
            }
        }
        if (spinning_threads != 0) {
            for (&self.windows_guest_threads, 0..) |*thread, index| {
                if (!isLiveWindowsGuestThread(thread.status)) continue;
                const share = if (interpreted == 0) 0 else @divTrunc(thread.executed_steps *| 100, interpreted);
                if (share < 5 or !thread.code.isSpin()) continue;
                self.reportGuestThreadSpin(index);
            }
        }
        if (self.busiestWindowsGuestThread()) |index| {
            const thread = &self.windows_guest_threads[index];
            const share = if (interpreted == 0) 0 else @divTrunc(thread.executed_steps *| 100, interpreted);
            var where: [guest_symbol_text_bytes]u8 = undefined;
            const described = self.describeGuestAddressOrUnnamed(self.windowsGuestThreadRip(index), &where);
            const named = if (thread.name_len != 0) thread.nameText() else "unnamed by the guest";
            if (share >= 50) {
                log.info("PE64 GUEST THREADS:   verdict: one worker holds {d}% of the run ('{s}') and it is sitting in {s}. A cooperative scheduler cannot make progress the busiest thread is not making, so read that symbol before anything downstream of it", .{ share, named, described });
            } else {
                log.info("PE64 GUEST THREADS:   verdict: the busiest worker holds {d}% of the run ('{s}'), in {s}; no single thread is monopolising the interpreter", .{ share, named, described });
            }
        }
    }

    const WindowsBlockedCause = enum {
        timed_condition,
        condition,
        finite_handle,
        infinite_handle,
        srw_lock,
        deadline,
        unknown,

        fn label(self: WindowsBlockedCause) []const u8 {
            return switch (self) {
                .timed_condition => "timed_condition",
                .condition => "condition",
                .finite_handle => "finite_handle",
                .infinite_handle => "infinite_handle",
                .srw_lock => "srw_lock",
                .deadline => "deadline",
                .unknown => "unknown",
            };
        }

        fn action(self: WindowsBlockedCause) []const u8 {
            return switch (self) {
                .timed_condition => "ETIMEDOUT is returned at the guest-clock deadline; do not synthesize a signal, and inspect signal/broadcast only if this condition carries graphics work",
                .condition => "find the signal or broadcast owner; Rosette wakes a waiter only after a real guest notification",
                .finite_handle => "allow the guest-clock timeout to expire; inspect the producer if output depends on this wait and it keeps expiring",
                .infinite_handle => "find SetEvent, ReleaseSemaphore, or thread completion for this handle; a runnable producer makes this a legitimate wait, not a Rosette deadlock",
                .srw_lock => "find the releasing owner; Rosette directs the oldest waiter during the handoff",
                .deadline => "this is an expected deadline park, not an object wait; verify the guest clock reaches the stored deadline",
                .unknown => "the blocked state has no recognized wait model; add the missing Rosette wait boundary before changing wake policy",
            };
        }
    };

    fn classifyWindowsBlockedThread(thread: *const WindowsGuestThread) WindowsBlockedCause {
        if (thread.blocked_condition != 0) {
            return if (thread.timed_wait_site != 0 or thread.timed_wait_milliseconds != 0)
                .timed_condition
            else
                .condition;
        }
        if (thread.blocked_srw_lock != 0) return .srw_lock;
        if (thread.blocked_wait_handle != 0) {
            return if (thread.blocked_wait_deadline != 0) .finite_handle else .infinite_handle;
        }
        if (thread.blocked_wait_deadline != 0) return .deadline;
        return .unknown;
    }

    /// The finding is the thing a run can act on; the blocked cause above is
    /// only the shape of the wait.  In particular, an infinite wait on a
    /// thread that is itself active is a live join chain, while an infinite
    /// wait on a thread that is not ready is a real upstream dependency.  The
    /// same distinction is made for condition and finite-handle waits by
    /// consulting the duration ledger for this live waiter.
    const WindowsBlockedFinding = enum {
        expected_deadline,
        periodic_timeout_poll,
        active_join_chain,
        join_target_not_ready,
        join_cycle,
        unsignalled_condition,
        condition_producer_pending,
        timeout_hotspot,
        producer_not_ready,
        active_wait_with_history,
        lock_owner_pending,
        ready_but_blocked,
        missing_wait_model,

        fn label(self: WindowsBlockedFinding) []const u8 {
            return switch (self) {
                .expected_deadline => "expected_deadline",
                .periodic_timeout_poll => "periodic_timeout_poll",
                .active_join_chain => "active_join_chain",
                .join_target_not_ready => "join_target_not_ready",
                .join_cycle => "join_cycle",
                .unsignalled_condition => "unsignalled_condition",
                .condition_producer_pending => "condition_producer_pending",
                .timeout_hotspot => "timeout_hotspot",
                .producer_not_ready => "producer_not_ready",
                .active_wait_with_history => "active_wait_with_history",
                .lock_owner_pending => "lock_owner_pending",
                .ready_but_blocked => "ready_but_blocked",
                .missing_wait_model => "missing_wait_model",
            };
        }

        fn priority(self: WindowsBlockedFinding) u8 {
            return switch (self) {
                .expected_deadline => 10,
                .periodic_timeout_poll => 20,
                .active_join_chain => 25,
                .timeout_hotspot => 60,
                .producer_not_ready, .condition_producer_pending => 70,
                .active_wait_with_history => 5,
                .lock_owner_pending, .unsignalled_condition => 80,
                .join_target_not_ready => 85,
                .join_cycle => 95,
                .missing_wait_model, .ready_but_blocked => 100,
            };
        }

        fn isLivenessFinding(self: WindowsBlockedFinding) bool {
            return switch (self) {
                .expected_deadline, .periodic_timeout_poll, .active_join_chain, .timeout_hotspot, .active_wait_with_history => false,
                else => true,
            };
        }

        fn isExpected(self: WindowsBlockedFinding) bool {
            return self == .expected_deadline or self == .active_join_chain;
        }

        fn action(self: WindowsBlockedFinding) []const u8 {
            return switch (self) {
                .expected_deadline => "verify guest-clock advancement to the stored deadline; this park is expected pacing",
                .periodic_timeout_poll => "correlate the timed caller with its optional-service producer; repeated expiry is cost, not a missing signal by itself",
                .active_join_chain => "the join chain reaches an active target; monitor target progress before calling this a deadlock",
                .join_target_not_ready => "inspect the target thread's last import/status and the event that completes it; this join is upstream of screen output",
                .join_cycle => "break the join cycle or repair the thread-completion edge; no timeout can resolve an infinite cycle",
                .unsignalled_condition => "find the signal/broadcast owner for this condition; no notification is recorded for the active waiter",
                .condition_producer_pending => "inspect the condition producer and signal ordering; prior signals exist but this waiter remains active",
                .timeout_hotspot => "inspect the finite-handle producer and decide whether repeated expiry is intentional polling or missing work",
                .producer_not_ready => "find SetEvent, ReleaseSemaphore, thread completion, or the producer for this handle; do not synthesize readiness",
                .active_wait_with_history => "signals or completions have occurred for this active handle; retain it as producer context, not as an unresolved blocker",
                .lock_owner_pending => "find the releasing SRW owner and its last progress point; the oldest waiter should be handed off on release",
                .ready_but_blocked => "the object is ready while the thread is still blocked; audit wake consumption and scheduler state before continuing",
                .missing_wait_model => "add the missing Rosette wait boundary; answering this wait would invent progress",
            };
        }
    };

    fn windowsWaitCostSiteForThread(self: *const ElfState, thread: *const WindowsGuestThread) ?*const wait_cost.Site {
        if (thread.wait_cost_site != 0) {
            const index = @as(usize, thread.wait_cost_site) - 1;
            if (index < self.windows_wait_cost.count) return &self.windows_wait_cost.sites[index];
        }
        const cause = classifyWindowsBlockedThread(thread);
        const kind: wait_cost.WaitKind = switch (cause) {
            .timed_condition => .timed_condition,
            .condition => .condition,
            .finite_handle => .finite_handle,
            .infinite_handle => .infinite_handle,
            .srw_lock => .srw_lock,
            .deadline => .deadline,
            .unknown => return null,
        };
        const key = switch (cause) {
            .timed_condition, .condition => thread.blocked_condition,
            .finite_handle, .infinite_handle => thread.blocked_wait_handle,
            .srw_lock => thread.blocked_srw_lock,
            .deadline => 0,
            .unknown => 0,
        };
        return wait_cost.siteAt(&self.windows_wait_cost, key, kind);
    }

    /// Find the oldest currently blocked thread represented by a ledger site.
    /// The wait token is the authoritative join; the field-based fallback is
    /// for a site whose token could not be allocated because the bounded
    /// ledger was full. A diagnostic must be able to say that no waiter was
    /// found instead of borrowing an unrelated thread with a similar handle.
    fn windowsWaiterSlotForSite(self: *const ElfState, site_index: usize, site: wait_cost.Site) ?usize {
        var selected: ?usize = null;
        var selected_start: u64 = std.math.maxInt(u64);
        for (&self.windows_guest_threads, 0..) |*thread, index| {
            if (thread.status != .blocked) continue;
            var matches = false;
            if (thread.wait_cost_site != 0) {
                const accounted_index = @as(usize, thread.wait_cost_site) - 1;
                matches = accounted_index == site_index;
            } else {
                matches = switch (site.kind) {
                    .condition, .timed_condition => thread.blocked_condition == site.key,
                    .finite_handle, .infinite_handle, .multiple => thread.waitsOnHandle(site.key),
                    .srw_lock => thread.blocked_srw_lock == site.key,
                    .deadline => false,
                };
            }
            if (!matches) continue;
            const start = if (thread.blocked_since_total_steps == 0)
                std.math.maxInt(u64)
            else
                thread.blocked_since_total_steps;
            if (selected == null or start < selected_start) {
                selected = index;
                selected_start = start;
            }
        }
        return selected;
    }

    /// Emit the causal snapshot behind a newly material liveness/cost
    /// finding. The ordinary ranked report is intentionally repeatable; this
    /// path is a bounded trigger that preserves the state at the first
    /// actionable observation, including the producer-side evidence needed
    /// to decide whether the problem is in the guest or in Rosetta's wake
    /// model.
    fn reportWindowsWaitEscalation(
        self: *ElfState,
        site_index: usize,
        site: *const wait_cost.Site,
        classification: wait_cost.Classification,
    ) void {
        const waiter_slot = self.windowsWaiterSlotForSite(site_index, site.*);
        var waiter_handle: u64 = 0;
        var waiter_thread_id: u64 = 0;
        var waiter_name: []const u8 = "<no current blocked waiter>";
        var waiter_age_steps: u64 = 0;
        var waiter_age_ticks: u64 = 0;
        var waiter_condition: u64 = 0;
        var waiter_mutex: u64 = 0;
        var waiter_wait_handle: u64 = 0;
        var waiter_last_import: []const u8 = "<not retained>";
        var waiter_last_import_step: u64 = 0;
        var waiter_rip: u64 = 0;
        var waiter_kernel_step: u64 = 0;
        var waiter_slot_text: ?usize = null;
        var kernel_module: []const u8 = "<none>";
        var kernel_export: []const u8 = "<none>";

        if (waiter_slot) |slot| {
            const thread = &self.windows_guest_threads[slot];
            waiter_slot_text = slot;
            waiter_handle = thread.handle;
            waiter_thread_id = thread.thread_id;
            waiter_name = if (thread.name_len != 0) thread.nameText() else "<unnamed>";
            waiter_age_steps = if (thread.blocked_since_total_steps == 0)
                0
            else
                self.totalInterpretedSteps() -| thread.blocked_since_total_steps;
            waiter_age_ticks = if (thread.blocked_since_guest_ticks == 0)
                0
            else
                self.guest_clock.ticks -| thread.blocked_since_guest_ticks;
            waiter_condition = thread.blocked_condition;
            waiter_mutex = thread.blocked_condition_mutex;
            waiter_wait_handle = thread.blocked_wait_handle;
            waiter_last_import = if (thread.last_import_len != 0) thread.lastImportText() else "<none>";
            waiter_last_import_step = thread.last_import_step;
            waiter_rip = self.windowsGuestThreadRip(slot);
            waiter_kernel_step = thread.last_kernel_step;
            if (self.guest_kernel_calls.slotAt(thread.last_kernel_slot)) |entry| {
                kernel_module = entry.module.moduleName();
                kernel_export = entry.export_name;
            }
        }

        const site_age_steps = if (site.first_step == 0)
            0
        else
            self.totalInterpretedSteps() -| site.first_step;
        const site_age_ticks = if (site.first_ticks == 0)
            0
        else
            self.guest_clock.ticks -| site.first_ticks;
        const age_steps = if (waiter_slot != null) waiter_age_steps else site_age_steps;
        const age_ticks = if (waiter_slot != null) waiter_age_ticks else site_age_ticks;
        const site_handle = if (site.kind == .finite_handle or site.kind == .infinite_handle or site.kind == .multiple)
            site.key
        else
            waiter_wait_handle;

        var rip_text: [guest_symbol_text_bytes]u8 = undefined;
        const rip_description = if (waiter_slot != null)
            self.describeGuestAddressOrUnnamed(waiter_rip, &rip_text)
        else
            "<not available>";
        var signal_rip_text: [guest_symbol_text_bytes]u8 = undefined;
        const signal_rip_description = if (site.last_signal_rip != 0)
            self.describeGuestAddressOrUnnamed(site.last_signal_rip, &signal_rip_text)
        else
            "<none>";

        var mutex_state: u32 = 0;
        var mutex_owner_thread_id: u64 = 0;
        var mutex_model: []const u8 = "not_observed";
        var mutex_owner_text_buffer: [128]u8 = undefined;
        var mutex_owner_text: []const u8 = "not_observed";
        if (waiter_mutex != 0) {
            if (self.windowsPthreadMutexImpl(waiter_mutex)) |impl| {
                mutex_state = self.read32(impl);
                mutex_owner_thread_id = @as(u64, self.read32(impl + 0x14));
                mutex_model = if (mutex_state == 0) "unlocked" else "owned_or_contended";
                mutex_owner_text = self.describeWindowsSrwOwner(mutex_owner_thread_id, &mutex_owner_text_buffer);
            } else {
                mutex_model = "unreadable";
                mutex_owner_text = "unreadable";
            }
        }

        var object_kind: []const u8 = "none";
        var readiness: []const u8 = "not_applicable";
        if (site_handle != 0) {
            object_kind = self.windowsWaitObjectKindName(site_handle);
            readiness = if (self.windowsWaitObjectReady(site_handle)) |ready|
                if (ready) "ready" else "not_ready"
            else
                "unmodeled";
        }

        const pending_workers = self.countWindowsWorkers(.pending);
        const runnable_workers = self.countWindowsWorkers(.runnable);
        const running_workers = self.countWindowsWorkers(.running);
        const blocked_workers = self.countWindowsWorkers(.blocked);
        const timeout_percent = if (site.waits == 0)
            0
        else
            @min(@as(u64, 100), (site.timed_out *| 100) / site.waits);
        const timeout_tick_percent = if (site.total_ticks == 0)
            0
        else
            @min(@as(u64, 100), (site.timed_out_ticks *| 100) / site.total_ticks);

        if (classification == .unsignalled_condition) {
            log.warn("PE64 WAIT ESCALATION: class=unsignalled_condition severity=critical trigger=sustained_absence_of_notification site={d} key=0x{x} kind={s} waiter_slot={?d} waiter_thread=0x{x} thread_id={d} name='{s}' age_steps={d} age_ticks={d} wait_started_step={d} wait_last_step={d} wait_started_ticks={d} wait_last_ticks={d} condition=0x{x} mutex=0x{x} mutex_model={s} mutex_state={d} mutex_owner_thread_id={d} mutex_owner={s}", .{
                site_index,
                site.key,
                site.kind.label(),
                waiter_slot_text,
                waiter_handle,
                waiter_thread_id,
                waiter_name,
                age_steps,
                age_ticks,
                site.first_step,
                site.last_step,
                site.first_ticks,
                site.last_ticks,
                waiter_condition,
                waiter_mutex,
                mutex_model,
                mutex_state,
                mutex_owner_thread_id,
                mutex_owner_text,
            });
            log.warn("PE64 WAIT ESCALATION:   context=unsignalled_condition last_import={s} last_import_step={d} rip=0x{x} at={s} last_kernel={s}!{s} last_kernel_step={d} total_steps={d} guest_ticks={d} workers(pending/runnable/running/blocked)={d}/{d}/{d}/{d} condition_signal_calls={d} condition_broadcast_calls={d} matching_notifications={d} last_signal_step={d} action=capture_the_predicate_writer_and_signal_or_broadcast_owner; Rosetta_keeps_the_waiter_blocked_until_real_notification", .{
                waiter_last_import,
                waiter_last_import_step,
                waiter_rip,
                rip_description,
                kernel_module,
                kernel_export,
                waiter_kernel_step,
                self.totalInterpretedSteps(),
                self.guest_clock.ticks,
                pending_workers,
                runnable_workers,
                running_workers,
                blocked_workers,
                self.windows_condition_signal_calls,
                self.windows_condition_broadcast_calls,
                site.signals,
                site.last_signal_step,
            });
            return;
        }

        log.warn("PE64 WAIT ESCALATION: class=timeout_hotspot severity=high trigger=timeout_cost_threshold site={d} key=0x{x} kind={s} handle=0x{x} object_kind={s} readiness={s} waiter_slot={?d} waiter_thread=0x{x} thread_id={d} name='{s}' age_steps={d} age_ticks={d} last_import={s} last_import_step={d} rip=0x{x} at={s} timeout_ms={d} waits={d} active={d} signaled={d} timeouts={d} ({d}%)", .{
            site_index,
            site.key,
            site.kind.label(),
            site_handle,
            object_kind,
            readiness,
            waiter_slot_text,
            waiter_handle,
            waiter_thread_id,
            waiter_name,
            age_steps,
            age_ticks,
            waiter_last_import,
            waiter_last_import_step,
            waiter_rip,
            rip_description,
            site.last_timeout_milliseconds,
            site.waits,
            site.active,
            site.signaled,
            site.timed_out,
            timeout_percent,
        });
        log.warn("PE64 WAIT ESCALATION:   context=timeout_hotspot signals={d} total_guest_ticks={d} timeout_guest_ticks={d} ({d}%) max_wait_ticks={d} max_timeout_overshoot_ticks={d} first_step={d} last_step={d} last_timeout_step={d} last_signal_step={d} last_signal_thread=0x{x} last_signal_rip=0x{x} last_signal_at={s} workers(pending/runnable/running/blocked)={d}/{d}/{d}/{d} producer_evidence={s} action=inspect_the_producer_and_decide_polling_vs_missing_work; Rosetta_does_not_convert_expiry_into_success", .{
            site.signals,
            site.total_ticks,
            site.timed_out_ticks,
            timeout_tick_percent,
            site.max_ticks,
            site.max_timeout_overshoot_ticks,
            site.first_step,
            site.last_step,
            site.last_timeout_step,
            site.last_signal_step,
            site.last_signal_thread_handle,
            site.last_signal_rip,
            signal_rip_description,
            pending_workers,
            runnable_workers,
            running_workers,
            blocked_workers,
            if (waiter_slot == null) "no_current_waiter_at_capture" else "current_waiter_recorded",
        });
    }

    /// Turn repeated ledger classifications into bounded events. The
    /// periodic report remains the durable summary; these events are the
    /// handoff a human can use to inspect the next run without reconstructing
    /// the cause from several heartbeats.
    fn reportWindowsWaitEscalations(self: *ElfState) void {
        const total_steps = self.totalInterpretedSteps();
        for (self.windows_wait_cost.sites[0..self.windows_wait_cost.count], 0..) |*site, index| {
            const classification = wait_cost.classify(site.*);
            switch (classification) {
                .unsignalled_condition => {
                    if (site.active == 0) continue;
                    const age_steps = if (site.first_step == 0) 0 else total_steps -| site.first_step;
                    const age_ticks = if (site.first_ticks == 0) 0 else self.guest_clock.ticks -| site.first_ticks;
                    if (age_steps < WINDOWS_WAIT_ESCALATION_MIN_AGE_STEPS and
                        age_ticks < WINDOWS_WAIT_ESCALATION_MIN_AGE_TICKS)
                    {
                        continue;
                    }
                    if (!site.claimUnsignalledEscalation()) continue;
                    self.windows_wait_unsignalled_escalations +|= 1;
                    self.reportWindowsWaitEscalation(index, site, classification);
                },
                .timeout_hotspot => {
                    if (!site.claimTimeoutHotspotEscalation()) continue;
                    self.windows_wait_timeout_hotspot_escalations +|= 1;
                    self.reportWindowsWaitEscalation(index, site, classification);
                },
                else => {},
            }
        }
    }

    fn classifyWindowsBlockedFinding(self: *const ElfState, thread: *const WindowsGuestThread) WindowsBlockedFinding {
        const cause = classifyWindowsBlockedThread(thread);
        switch (cause) {
            .unknown => return .missing_wait_model,
            .deadline => return .expected_deadline,
            .srw_lock => return .lock_owner_pending,
            .timed_condition, .condition => {
                if (self.windowsWaitCostSiteForThread(thread)) |site| {
                    return switch (wait_cost.classify(site.*)) {
                        .periodic_timeout_poll => .periodic_timeout_poll,
                        .lost_wakeup_candidate => .unsignalled_condition,
                        .unsignalled_condition => .unsignalled_condition,
                        .mixed_timeout_signal => .condition_producer_pending,
                        .pending_producer => .condition_producer_pending,
                        else => if (cause == .timed_condition) .periodic_timeout_poll else .condition_producer_pending,
                    };
                }
                return if (cause == .timed_condition) .periodic_timeout_poll else .unsignalled_condition;
            },
            .finite_handle => {
                if (self.windowsWaitCostSiteForThread(thread)) |site| {
                    if (wait_cost.classify(site.*) == .timeout_hotspot) return .timeout_hotspot;
                }
                return .producer_not_ready;
            },
            .infinite_handle => {
                if (self.windowsWaitObjectReady(thread.blocked_wait_handle)) |ready| {
                    if (ready) return .ready_but_blocked;
                }
                const join = self.windowsJoinVerdict(thread.blocked_wait_handle);
                if (std.mem.eql(u8, join, "active_target") or
                    std.mem.eql(u8, join, "chain_reaches_active_target"))
                {
                    return .active_join_chain;
                }
                if (std.mem.eql(u8, join, "join_cycle") or
                    std.mem.eql(u8, join, "join_chain_too_deep"))
                {
                    return .join_cycle;
                }
                if (!std.mem.eql(u8, join, "not_thread_join")) return .join_target_not_ready;
                // A semaphore/event can remain actively waited on while its
                // producer continues to signal it. That is a live background
                // service, not the same finding as a handle that has never
                // produced a completion. Preserve it as context so the
                // upstream report does not inflate liveness debt with healthy
                // history (ASYNC_IO in the long run is the concrete case).
                if (self.windowsWaitCostSiteForThread(thread)) |site| {
                    if (wait_cost.classify(site.*) == .healthy) return .active_wait_with_history;
                }
                return .producer_not_ready;
            },
        }
    }

    /// Print the bounded wait graph that sits underneath the thread report.
    ///
    /// A timed condition timeout is not a lost wakeup by itself: the guest
    /// requested a deadline and the correct Rosette action is to return
    /// ETIMEDOUT. Likewise, an infinite join on a runnable thread is not a
    /// deadlock. This report names the cause, the object state, and the
    /// producer status so the next run can target the actual missing signal
    /// instead of shortening every wait.
    fn reportWindowsBlockedDiagnostics(self: *const ElfState, limit: usize) void {
        var blocked: usize = 0;
        var timed_conditions: usize = 0;
        var conditions: usize = 0;
        var finite_handles: usize = 0;
        var infinite_handles: usize = 0;
        var srw_locks: usize = 0;
        var deadlines: usize = 0;
        var unknown: usize = 0;
        for (&self.windows_guest_threads) |*thread| {
            if (thread.status != .blocked) continue;
            blocked += 1;
            switch (classifyWindowsBlockedThread(thread)) {
                .timed_condition => timed_conditions += 1,
                .condition => conditions += 1,
                .finite_handle => finite_handles += 1,
                .infinite_handle => infinite_handles += 1,
                .srw_lock => srw_locks += 1,
                .deadline => deadlines += 1,
                .unknown => unknown += 1,
            }
        }
        if (blocked == 0) return;
        log.info("PE64 BLOCKED WAIT DIAGNOSTICS: blocked={d} timed_condition={d} condition={d} finite_handle={d} infinite_handle={d} srw_lock={d} deadline={d} unknown={d}; waits remain cooperative and only a real signal, completion, or guest-clock deadline may make a blocked thread runnable", .{
            blocked,
            timed_conditions,
            conditions,
            finite_handles,
            infinite_handles,
            srw_locks,
            deadlines,
            unknown,
        });

        var shown: usize = 0;
        for (&self.windows_guest_threads, 0..) |*thread, index| {
            if (thread.status != .blocked or shown == limit) continue;
            shown += 1;
            const cause = classifyWindowsBlockedThread(thread);
            const finding = self.classifyWindowsBlockedFinding(thread);
            const wait_site = self.windowsWaitCostSiteForThread(thread);
            var target_text: [128]u8 = undefined;
            const target = self.describeWindowsWaitTarget(thread.blocked_wait_handle, &target_text);
            const join = self.windowsJoinVerdict(thread.blocked_wait_handle);
            const blocked_age_steps = if (thread.blocked_since_total_steps == 0)
                0
            else
                self.totalInterpretedSteps() -| thread.blocked_since_total_steps;
            const blocked_age_ticks = if (thread.blocked_since_guest_ticks == 0)
                0
            else
                self.guest_clock.ticks -| thread.blocked_since_guest_ticks;
            const object_kind = if (thread.blocked_wait_handle != 0)
                self.windowsWaitObjectKindName(thread.blocked_wait_handle)
            else
                "none";
            const readiness = if (thread.blocked_wait_handle == 0)
                "not_applicable"
            else if (self.windowsWaitObjectReady(thread.blocked_wait_handle)) |ready|
                if (ready) "ready" else "not_ready"
            else
                "unmodeled";
            const last_import = if (thread.last_import_len != 0) thread.lastImportText() else "<none>";
            const site_classification = if (wait_site) |site| wait_cost.classify(site.*) else .no_data;
            const site_key = if (wait_site) |site| site.key else 0;
            const site_waits = if (wait_site) |site| site.waits else 0;
            const site_signals = if (wait_site) |site| site.signals else 0;
            const site_timeouts = if (wait_site) |site| site.timed_out else 0;
            log.info("PE64 BLOCKED WAIT DIAGNOSTICS:   slot={d} thread=0x{x} name='{s}' cause={s} finding={s} priority={d} wait_handle=0x{x} kind={s} readiness={s}{s} join={s} age_steps={d} age_ticks={d} condition=0x{x} mutex=0x{x} lock=0x{x} timeout_ms={d} deadline_ticks={d} last_import={s} last_import_step={d} thread_steps={d} wait_site=0x{x} site_classification={s} site_waits={d} site_signals={d} site_timeouts={d} action={s} finding_action={s}", .{
                index,
                thread.handle,
                if (thread.name_len != 0) thread.nameText() else "<unnamed>",
                cause.label(),
                finding.label(),
                finding.priority(),
                thread.blocked_wait_handle,
                object_kind,
                readiness,
                target,
                join,
                blocked_age_steps,
                blocked_age_ticks,
                thread.blocked_condition,
                thread.blocked_condition_mutex,
                thread.blocked_srw_lock,
                thread.blocked_wait_timeout,
                thread.blocked_wait_deadline,
                last_import,
                thread.last_import_step,
                thread.executed_steps,
                site_key,
                site_classification.label(),
                site_waits,
                site_signals,
                site_timeouts,
                cause.action(),
                finding.action(),
            });
        }
        if (shown != blocked) {
            log.info("PE64 BLOCKED WAIT DIAGNOSTICS:   {d} blocked thread(s) omitted after bounded sample of {d}; aggregate counts above remain complete", .{ blocked - shown, limit });
        }
    }

    /// Turn the raw wait graph and duration ledger into a short ranked action
    /// list.  The full reports remain the audit trail; this report is the
    /// answer to "what do I inspect first?" and is emitted at heartbeats and
    /// at exit so a long run does not require reconstructing a finding from
    /// lines written hours apart.
    fn reportWindowsWaitFindings(self: *ElfState) void {
        var blocked: usize = 0;
        var liveness_blocks: usize = 0;
        var cost_blocks: usize = 0;
        var expected_blocks: usize = 0;
        var expected_deadlines: usize = 0;
        var periodic_polls: usize = 0;
        var active_join_chains: usize = 0;
        var join_targets_not_ready: usize = 0;
        var join_cycles: usize = 0;
        var conditions_without_signal: usize = 0;
        var condition_producers_pending: usize = 0;
        var timeout_hotspots: usize = 0;
        var producers_not_ready: usize = 0;
        var active_wait_contexts: usize = 0;
        var locks_pending: usize = 0;
        var ready_but_blocked: usize = 0;
        var missing_models: usize = 0;

        for (&self.windows_guest_threads) |*thread| {
            if (thread.status != .blocked) continue;
            blocked += 1;
            const finding = self.classifyWindowsBlockedFinding(thread);
            if (finding.isLivenessFinding()) liveness_blocks += 1;
            if (finding == .timeout_hotspot or finding == .periodic_timeout_poll) cost_blocks += 1;
            if (finding.isExpected()) expected_blocks += 1;
            switch (finding) {
                .expected_deadline => expected_deadlines += 1,
                .periodic_timeout_poll => periodic_polls += 1,
                .active_join_chain => active_join_chains += 1,
                .join_target_not_ready => join_targets_not_ready += 1,
                .join_cycle => join_cycles += 1,
                .unsignalled_condition => conditions_without_signal += 1,
                .condition_producer_pending => condition_producers_pending += 1,
                .timeout_hotspot => timeout_hotspots += 1,
                .producer_not_ready => producers_not_ready += 1,
                .active_wait_with_history => active_wait_contexts += 1,
                .lock_owner_pending => locks_pending += 1,
                .ready_but_blocked => ready_but_blocked += 1,
                .missing_wait_model => missing_models += 1,
            }
        }

        var site_liveness: usize = 0;
        var site_cost: usize = 0;
        var site_expected: usize = 0;
        var site_healthy: usize = 0;
        for (self.windows_wait_cost.sites[0..self.windows_wait_cost.count]) |site| {
            const classification = wait_cost.classify(site);
            if (classification.isActionable()) site_liveness += 1;
            if (classification.isCostHotspot()) site_cost += 1;
            if (classification == .expected_deadline) site_expected += 1;
            if (classification == .healthy) site_healthy += 1;
        }

        if (blocked == 0 and self.windows_wait_cost.count == 0) return;
        self.reportWindowsWaitEscalations();
        log.info("PE64 WAIT FINDINGS: blocked={d} liveness_blocks={d} cost_blocks={d} expected_blocks={d} wait_sites={d} site_liveness={d} site_cost={d} site_expected={d} site_healthy={d}; liveness findings can stop progress, cost findings explain slowdown, expected findings are not defects", .{
            blocked,
            liveness_blocks,
            cost_blocks,
            expected_blocks,
            self.windows_wait_cost.count,
            site_liveness,
            site_cost,
            site_expected,
            site_healthy,
        });
        if (self.windows_wait_unsignalled_escalations != 0 or self.windows_wait_timeout_hotspot_escalations != 0) {
            log.info("PE64 WAIT ESCALATIONS: unsignalled_condition={d} timeout_hotspot={d}; each count is a bounded forensic trigger, not a synthetic wake or success result", .{
                self.windows_wait_unsignalled_escalations,
                self.windows_wait_timeout_hotspot_escalations,
            });
        }
        log.info("PE64 WAIT FINDINGS: blocked_by_class expected_deadline={d} periodic_poll={d} active_join_chain={d} join_target_not_ready={d} join_cycle={d} unsignalled_condition={d} condition_producer_pending={d} timeout_hotspot={d} producer_not_ready={d} active_wait_with_history={d} lock_owner_pending={d} ready_but_blocked={d} missing_wait_model={d}; ranked entries below include the exact waiter, object, last import, and next action", .{
            expected_deadlines,
            periodic_polls,
            active_join_chains,
            join_targets_not_ready,
            join_cycles,
            conditions_without_signal,
            condition_producers_pending,
            timeout_hotspots,
            producers_not_ready,
            active_wait_contexts,
            locks_pending,
            ready_but_blocked,
            missing_models,
        });

        var selected_threads = [_]bool{false} ** MAX_WINDOWS_GUEST_THREADS;
        var shown_threads: usize = 0;
        while (shown_threads < 8) : (shown_threads += 1) {
            var best_index: ?usize = null;
            var best_priority: u8 = 0;
            var best_age: u64 = 0;
            for (&self.windows_guest_threads, 0..) |*thread, index| {
                if (thread.status != .blocked or selected_threads[index]) continue;
                const finding = self.classifyWindowsBlockedFinding(thread);
                const age = if (thread.blocked_since_total_steps == 0)
                    0
                else
                    self.totalInterpretedSteps() -| thread.blocked_since_total_steps;
                if (best_index == null or finding.priority() > best_priority or
                    (finding.priority() == best_priority and age > best_age))
                {
                    best_index = index;
                    best_priority = finding.priority();
                    best_age = age;
                }
            }
            const index = best_index orelse break;
            selected_threads[index] = true;
            const thread = &self.windows_guest_threads[index];
            const finding = self.classifyWindowsBlockedFinding(thread);
            var target_text: [128]u8 = undefined;
            const target = self.describeWindowsWaitTarget(thread.blocked_wait_handle, &target_text);
            const join = self.windowsJoinVerdict(thread.blocked_wait_handle);
            const object_kind = if (thread.blocked_wait_handle != 0)
                self.windowsWaitObjectKindName(thread.blocked_wait_handle)
            else
                "none";
            const readiness = if (thread.blocked_wait_handle == 0)
                "not_applicable"
            else if (self.windowsWaitObjectReady(thread.blocked_wait_handle)) |ready|
                if (ready) "ready" else "not_ready"
            else
                "unmodeled";
            const last_import = if (thread.last_import_len != 0) thread.lastImportText() else "<none>";
            log.info("PE64 WAIT FINDINGS:   blocked_rank={d} slot={d} class={s} priority={d} thread=0x{x} name='{s}' age_steps={d} wait_handle=0x{x} kind={s} readiness={s}{s} join={s} condition=0x{x} lock=0x{x} timeout_ms={d} deadline_ticks={d} last_import={s} last_import_step={d} thread_steps={d} action={s}", .{
                shown_threads + 1,
                index,
                finding.label(),
                finding.priority(),
                thread.handle,
                if (thread.name_len != 0) thread.nameText() else "<unnamed>",
                best_age,
                thread.blocked_wait_handle,
                object_kind,
                readiness,
                target,
                join,
                thread.blocked_condition,
                thread.blocked_srw_lock,
                thread.blocked_wait_timeout,
                thread.blocked_wait_deadline,
                last_import,
                thread.last_import_step,
                thread.executed_steps,
                finding.action(),
            });
        }

        var selected_sites = [_]bool{false} ** wait_cost.Ledger.capacity;
        var shown_sites: usize = 0;
        while (shown_sites < 8) : (shown_sites += 1) {
            var best_index: ?usize = null;
            var best_priority: u8 = 0;
            var best_timeout_ticks: u64 = 0;
            var best_waits: u64 = 0;
            for (self.windows_wait_cost.sites[0..self.windows_wait_cost.count], 0..) |site, index| {
                if (selected_sites[index]) continue;
                const classification = wait_cost.classify(site);
                if (best_index == null or classification.priority() > best_priority or
                    (classification.priority() == best_priority and site.timed_out_ticks > best_timeout_ticks) or
                    (classification.priority() == best_priority and site.timed_out_ticks == best_timeout_ticks and site.waits > best_waits))
                {
                    best_index = index;
                    best_priority = classification.priority();
                    best_timeout_ticks = site.timed_out_ticks;
                    best_waits = site.waits;
                }
            }
            const index = best_index orelse break;
            selected_sites[index] = true;
            const site = self.windows_wait_cost.sites[index];
            const classification = wait_cost.classify(site);
            const timeout_percent = if (site.waits == 0)
                0
            else
                @min(@as(u64, 100), (site.timed_out *| 100) / site.waits);
            const timeout_tick_percent = if (site.total_ticks == 0)
                0
            else
                @min(@as(u64, 100), (site.timed_out_ticks *| 100) / site.total_ticks);
            log.info("PE64 WAIT FINDINGS:   site_rank={d} key=0x{x} kind={s} class={s} priority={d} waits={d} active={d} signaled={d} timeouts={d} ({d}%) timeout_ticks={d} ({d}%) signals={d} timeout_ms={d} max_ticks={d} max_overshoot_ticks={d} first_step={d} last_step={d} first_ticks={d} last_ticks={d} last_signal_step={d} last_signal_thread=0x{x} last_signal_rip=0x{x} action={s}", .{
                shown_sites + 1,
                site.key,
                site.kind.label(),
                classification.label(),
                classification.priority(),
                site.waits,
                site.active,
                site.signaled,
                site.timed_out,
                timeout_percent,
                site.timed_out_ticks,
                timeout_tick_percent,
                site.signals,
                site.last_timeout_milliseconds,
                site.max_ticks,
                site.max_timeout_overshoot_ticks,
                site.first_step,
                site.last_step,
                site.first_ticks,
                site.last_ticks,
                site.last_signal_step,
                site.last_signal_thread_handle,
                site.last_signal_rip,
                classification.action(),
            });
        }
    }

    /// Put wait evidence ahead of the last-mile screen verdict.  A screen
    /// chain can be perfectly instrumented and still be downstream of a
    /// worker that never reaches its producer, a join whose target never
    /// completes, or a wait model Rosette does not understand.  This compact
    /// precedence line makes that causal order explicit at exit without
    /// asking the reader to reconstruct it from the full blocked-thread
    /// sample above.
    fn reportWindowsUpstreamWaitPriority(self: *const ElfState) void {
        var blocked: usize = 0;
        var actionable: usize = 0;
        var unknown: usize = 0;
        var conditions: usize = 0;
        var srw_locks: usize = 0;
        var finite_handles: usize = 0;
        var finite_pending: usize = 0;
        var timeout_hotspots: usize = 0;
        var periodic_polls: usize = 0;
        var producer_handles_pending: usize = 0;
        var unready_joins: usize = 0;
        var join_cycles: usize = 0;
        var active_join_chains: usize = 0;
        var active_wait_contexts: usize = 0;
        var ready_but_blocked: usize = 0;
        var deadlines: usize = 0;
        var oldest_age_steps: u64 = 0;
        var oldest_thread: u64 = 0;

        for (&self.windows_guest_threads) |*thread| {
            if (thread.status != .blocked) continue;
            blocked += 1;
            const finding = self.classifyWindowsBlockedFinding(thread);
            if (finding.isLivenessFinding()) actionable += 1;
            if (finding == .timeout_hotspot) timeout_hotspots += 1;
            if (finding == .periodic_timeout_poll) periodic_polls += 1;
            const cause = classifyWindowsBlockedThread(thread);
            switch (cause) {
                .unknown => unknown += 1,
                .condition, .timed_condition => conditions += @intFromBool(cause == .condition),
                .srw_lock => srw_locks += 1,
                .finite_handle => {
                    finite_handles += 1;
                    if (finding == .producer_not_ready) finite_pending += 1;
                },
                .deadline => deadlines += 1,
                .infinite_handle => {},
            }

            const age_steps = if (thread.blocked_since_total_steps == 0)
                0
            else
                self.totalInterpretedSteps() -| thread.blocked_since_total_steps;
            if (age_steps > oldest_age_steps) {
                oldest_age_steps = age_steps;
                oldest_thread = thread.handle;
            }

            if (cause == .infinite_handle) {
                const join = self.windowsJoinVerdict(thread.blocked_wait_handle);
                const active_chain = std.mem.eql(u8, join, "active_target") or
                    std.mem.eql(u8, join, "chain_reaches_active_target");
                if (active_chain) {
                    active_join_chains += 1;
                } else if (std.mem.eql(u8, join, "join_cycle") or
                    std.mem.eql(u8, join, "join_chain_too_deep"))
                {
                    join_cycles += 1;
                } else if (!std.mem.eql(u8, join, "not_thread_join")) {
                    // Only a thread object is a join. Other kernel handles
                    // must not inflate the join count merely because their
                    // current state is not ready.
                    if (self.windowsWaitObjectReady(thread.blocked_wait_handle)) |ready| {
                        if (!ready) unready_joins += 1;
                    } else {
                        unready_joins += 1;
                    }
                } else switch (finding) {
                    .producer_not_ready => producer_handles_pending += 1,
                    .active_wait_with_history => active_wait_contexts += 1,
                    .ready_but_blocked => ready_but_blocked += 1,
                    else => {},
                }
            }
        }

        var timed_waits: u64 = 0;
        var timed_timeouts: u64 = 0;
        var timed_ticks: u64 = 0;
        var timed_total_ticks: u64 = 0;
        for (self.windows_wait_cost.sites[0..self.windows_wait_cost.count]) |site| {
            if (site.kind != .timed_condition) continue;
            timed_waits +|= site.waits;
            timed_timeouts +|= site.timed_out;
            timed_ticks +|= site.timed_out_ticks;
            timed_total_ticks +|= site.total_ticks;
        }
        const timeout_percent = if (timed_waits == 0)
            0
        else
            @min(@as(u64, 100), (timed_timeouts *| 100) / timed_waits);
        const timeout_tick_percent = if (timed_total_ticks == 0)
            0
        else
            @min(@as(u64, 100), (timed_ticks *| 100) / timed_total_ticks);
        if (blocked == 0 and timed_waits == 0) return;

        const verdict = if (unknown != 0)
            "missing_wait_model"
        else if (ready_but_blocked != 0)
            "ready_but_blocked"
        else if (join_cycles != 0)
            "join_cycle_or_depth"
        else if (unready_joins != 0)
            "join_target_not_ready"
        else if (conditions != 0 or srw_locks != 0)
            "unsignalled_condition_or_lock"
        else if (producer_handles_pending != 0 or finite_pending != 0)
            "producer_or_handle_pending"
        else
            "no_unresolved_upstream_wait";
        log.info("PE64 UPSTREAM WAIT PRIORITY: verdict={s} blocked={d} actionable={d} unknown={d} condition={d} srw_lock={d} finite_handle={d} finite_pending={d} timeout_hotspots={d} periodic_polls={d} infinite_handle_pending={d} infinite_join_unready={d} join_cycles={d} active_join_chains={d} active_wait_contexts={d} ready_but_blocked={d} expected_deadlines={d} oldest_blocked_steps={d} oldest_thread=0x{x} timed_condition_timeouts={d}/{d} ({d}%) timeout_guest_ticks={d}/{d} ({d}%); screen validity is downstream of these waits, so resolve this verdict before interpreting SCREEN VALIDITY CHAIN", .{
            verdict,
            blocked,
            actionable,
            unknown,
            conditions,
            srw_locks,
            finite_handles,
            finite_pending,
            timeout_hotspots,
            periodic_polls,
            producer_handles_pending,
            unready_joins,
            join_cycles,
            active_join_chains,
            active_wait_contexts,
            ready_but_blocked,
            deadlines,
            oldest_age_steps,
            oldest_thread,
            timed_timeouts,
            timed_waits,
            timeout_percent,
            timed_ticks,
            timed_total_ticks,
            timeout_tick_percent,
        });
    }

    /// Report the cost of synchronization separately from its correctness
    /// counters. A timeout count alone cannot tell a harmless one-shot delay
    /// from a 99%-timeout poll that consumed the interpreter; duration and
    /// overshoot make that distinction explicit and keep producer evidence
    /// beside the consumer that waited for it.
    fn reportWindowsWaitCost(self: *const ElfState) void {
        const ledger = &self.windows_wait_cost;
        if (ledger.count == 0 and ledger.dropped_sites == 0 and ledger.unmatched_signals == 0) return;
        var waits: u64 = 0;
        var active: u64 = 0;
        var signals: u64 = 0;
        var signaled: u64 = 0;
        var timeouts: u64 = 0;
        var timeout_ticks: u64 = 0;
        var total_ticks: u64 = 0;
        var max_ticks: u64 = 0;
        var max_overshoot: u64 = 0;
        var site_liveness: u64 = 0;
        var site_cost: u64 = 0;
        var site_expected: u64 = 0;
        for (ledger.sites[0..ledger.count]) |site| {
            waits +|= site.waits;
            active +|= site.active;
            signals +|= site.signals;
            signaled +|= site.signaled;
            timeouts +|= site.timed_out;
            timeout_ticks +|= site.timed_out_ticks;
            total_ticks +|= site.total_ticks;
            max_ticks = @max(max_ticks, site.max_ticks);
            max_overshoot = @max(max_overshoot, site.max_timeout_overshoot_ticks);
            const classification = wait_cost.classify(site);
            if (classification.isActionable()) site_liveness +|= 1;
            if (classification.isCostHotspot()) site_cost +|= 1;
            if (classification == .expected_deadline) site_expected +|= 1;
        }
        const timeout_percent = if (waits == 0) 0 else @min(@as(u64, 100), (timeouts *| 100) / waits);
        const timeout_tick_percent = if (total_ticks == 0) 0 else @min(@as(u64, 100), (timeout_ticks *| 100) / total_ticks);
        log.info("PE64 WAIT COST: sites={d} waits={d} active={d} signaled={d} timeouts={d} ({d}%) signals={d} unmatched_signals={d} total_guest_ticks={d} timeout_guest_ticks={d} ({d}%) max_wait_ticks={d} max_timeout_overshoot_ticks={d} classified(liveness/cost/expected)={d}/{d}/{d} dropped_sites={d} dropped_events={d}; timeout share is the direct poll/blocked-wait cost, not a liveness verdict", .{
            ledger.count,
            waits,
            active,
            signaled,
            timeouts,
            timeout_percent,
            signals,
            ledger.unmatched_signals,
            total_ticks,
            timeout_ticks,
            timeout_tick_percent,
            max_ticks,
            max_overshoot,
            site_liveness,
            site_cost,
            site_expected,
            ledger.dropped_sites,
            ledger.dropped_events,
        });
        for (ledger.sites[0..ledger.count]) |site| {
            if (site.waits == 0 and site.signals == 0 and site.active == 0) continue;
            const site_timeout_percent = if (site.waits == 0) 0 else @min(@as(u64, 100), (site.timed_out *| 100) / site.waits);
            const site_timeout_tick_percent = if (site.total_ticks == 0)
                0
            else
                @min(@as(u64, 100), (site.timed_out_ticks *| 100) / site.total_ticks);
            const classification = wait_cost.classify(site);
            log.info("PE64 WAIT COST:   key=0x{x} kind={s} waits={d} active={d} signaled={d} timeouts={d} ({d}%) signals={d} total_ticks={d} timeout_ticks={d} ({d}%) max_ticks={d} max_overshoot_ticks={d} first_step={d} last_step={d} last_signal_step={d} last_timeout_step={d} timeout_ms={d} classification={s} action={s}", .{
                site.key,
                site.kind.label(),
                site.waits,
                site.active,
                site.signaled,
                site.timed_out,
                site_timeout_percent,
                site.signals,
                site.total_ticks,
                site.timed_out_ticks,
                site_timeout_tick_percent,
                site.max_ticks,
                site.max_timeout_overshoot_ticks,
                site.first_step,
                site.last_step,
                site.last_signal_step,
                site.last_timeout_step,
                site.last_timeout_milliseconds,
                classification.label(),
                classification.action(),
            });
        }
    }

    /// Every armed milestone, its entry count, and the step it was first
    /// reached at.
    ///
    /// A chain collapses a count to a boolean, and the counts carry the rest
    /// of the story: one entry into `PaintFromUIThread` and one thousand are
    /// the same `met`. Written at exit rather than at every checkpoint,
    /// because the chain rows already carry each stage's own count and
    /// sixteen mostly-unchanged lines per wall move is how a log stops being
    /// read.
    /// Name the thread that owns a guest-title wall, and say what it is doing.
    ///
    /// A verdict that ends at "this belongs to the title" leaves a reader to
    /// find the title's thread in a list of fifteen and work out for
    /// themselves whether it is running, blocked, or going round in a loop.
    /// The thread is identified by having entered `XThread::Execute`, which
    /// is the only thing in the table that means "translated PowerPC ran on
    /// this thread".
    fn reportGuestTitleThreadForWall(self: *const ElfState) void {
        const interpreted = self.totalInterpretedSteps();
        var found = false;
        for (&self.windows_guest_threads, 0..) |*thread, index| {
            if (thread.status == .vacant or !thread.entered_xenia_title) continue;
            found = true;
            var where: [guest_symbol_text_bytes]u8 = undefined;
            const share = if (interpreted == 0) 0 else @divTrunc(thread.executed_steps *| 100, interpreted);
            log.info("PE64 GUEST OUTPUT CHAIN:   the title runs on thread '{s}' (handle=0x{x}), which is {s}, holds {d}% of the run, and is at {s} rip=0x{x}", .{
                if (thread.name_len != 0) thread.nameText() else "<unnamed by the guest>",
                thread.handle,
                @tagName(thread.status),
                share,
                self.describeGuestAddressOrUnnamed(self.windowsGuestThreadRip(index), &where),
                self.windowsGuestThreadRip(index),
            });
            if (thread.code.isSpin()) {
                const bounds = thread.code.recentBounds().?;
                log.info("PE64 GUEST OUTPUT CHAIN:   and it is spinning inside [0x{x},0x{x}]; PE64 SPIN ANATOMY names the address it polls, and that address - not the stage below - is the thing to make change", .{
                    bounds.low,
                    bounds.high,
                });
            } else if (thread.status == .blocked) {
                log.info("PE64 GUEST OUTPUT CHAIN:   and it is blocked on wait=0x{x} with timeout={d}; a title parked on a wait cannot reach the stage above it, and whoever owns that object is the finding", .{
                    thread.blocked_wait_handle,
                    thread.blocked_wait_timeout,
                });
            }
        }
        if (!found) {
            log.info("PE64 GUEST OUTPUT CHAIN:   no thread has entered XThread::Execute, so no thread is running translated PowerPC and the wall's owner has not started", .{});
        }
    }

    /// Entries into a milestone, and the step it last happened at.
    fn guestMilestoneActivity(self: *const ElfState, mangled: []const u8) struct { hits: u64, last_step: u64, armed: bool } {
        const index = xenia_guest_milestone_map.indexOf(mangled) orelse
            return .{ .hits = 0, .last_step = 0, .armed = false };
        return .{
            .hits = self.guest_milestone_hits[index],
            .last_step = self.guest_milestone_last_step[index],
            .armed = self.guest_milestone_addresses[index] != 0,
        };
    }

    /// Combine the base and Vulkan override rows for a virtual GPU method.
    /// Unlike an inline proxy these are alternative implementations, so both
    /// counts represent real work and are added rather than maxed.
    fn guestMilestoneActivityAny(
        self: *const ElfState,
        comptime primary: []const u8,
        comptime alternate: []const u8,
    ) struct { hits: u64, last_step: u64, armed: bool } {
        const first = self.guestMilestoneActivity(primary);
        const second = self.guestMilestoneActivity(alternate);
        return .{
            .hits = first.hits +| second.hits,
            .last_step = @max(first.last_step, second.last_step),
            .armed = first.armed or second.armed,
        };
    }

    /// Whether the title is walking through its own program or looping inside
    /// code it already has.
    ///
    /// The one question the guest output chain cannot ask. Between two kernel
    /// calls a title executes translated PowerPC, and Rosette has no name for
    /// any of it: the 2026-09-12 run had `Main XThread` holding 22% of the
    /// interpreter at an address inside Xenia's JIT cache, and every report
    /// that looked at it could say only that it was busy.
    ///
    /// Xenia translates a guest function the first time control reaches it,
    /// so the count of translations is a progress axis a spin cannot advance
    /// - which is exactly the property `rosette-external-progress-axis`
    /// demands and no counter in this file had.
    pub fn reportGuestCodeProgress(self: *const ElfState) void {
        const defined = self.guestMilestoneActivity("_ZN2xe3cpu3ppc11PPCFrontend14DefineFunctionEPNS0_13GuestFunctionEj");
        const resolved = self.guestMilestoneActivity("_ZN2xe3cpu9Processor15ResolveFunctionEj");
        const trapped = self.guestMilestoneActivity("_ZN2xe3cpu7backend3x6414TrapDebugBreakEPvy");
        const bad_pm4 = self.guestMilestoneActivity("_ZN2xe3gpu16CommandProcessor22HitUnimplementedOpcodeEjj");
        if (!defined.armed and !resolved.armed and !trapped.armed) {
            log.info("PE64 GUEST CODE PROGRESS: not observable; this image names none of Xenia's PowerPC translation entry points, so nothing here can say whether the title is reaching new code", .{});
            return;
        }
        log.info("PE64 GUEST CODE PROGRESS: guest functions translated={d} guest addresses resolved={d}; a translation is the title reaching code it has never run, so this count is a progress axis a spin cannot advance", .{
            defined.hits,
            resolved.hits,
        });
        if (defined.hits == 0) {
            log.info("PE64 GUEST CODE PROGRESS:   not one guest function was translated. Either no title code has run at all, or this build translates ahead of time and the axis does not apply here; check XThread_Execute in the chain above before reading this as a stall", .{});
        } else {
            const interpreted = self.totalInterpretedSteps();
            const quiet = interpreted -| defined.last_step;
            const share = if (interpreted == 0) @as(u64, 0) else quiet * 100 / interpreted;
            if (share >= 25) {
                log.info("PE64 GUEST CODE PROGRESS:   the last translation was at step {d}, {d} step(s) and {d}% of the run ago. The title has been executing code it already had for that whole span: it is looping, not advancing, and the loop is the finding rather than whatever it last asked the kernel for", .{
                    defined.last_step,
                    quiet,
                    share,
                });
            } else {
                log.info("PE64 GUEST CODE PROGRESS:   the last translation was at step {d}, {d} step(s) ago ({d}% of the run). The title is still reaching code it has not run before, so it is advancing through its own program and a stage that reads unmet is one it has not got to yet", .{
                    defined.last_step,
                    quiet,
                    share,
                });
            }
        }
        // A guest trap is the title reporting a failure of its own, and it is
        // the only witness in the table whose zero is the good outcome.
        if (trapped.armed) {
            if (trapped.hits == 0) {
                log.info("PE64 GUEST CODE PROGRESS:   guest traps=0; the title has not executed a PowerPC trap instruction, so it has not hit an assertion of its own", .{});
            } else {
                log.warn("PE64 GUEST CODE PROGRESS:   guest traps={d}, last at step {d}. A PowerPC trap is what the title's own assertions compile to: it has decided something is wrong. Whatever it checked is upstream of every unmet stage below it", .{
                    trapped.hits,
                    trapped.last_step,
                });
            }
        }
        if (bad_pm4.armed and bad_pm4.hits != 0) {
            log.warn("PE64 GUEST CODE PROGRESS:   the command processor hit {d} PM4 opcode(s) it cannot decode, last at step {d}; that is a gap in this Xenia build, not in the title", .{
                bad_pm4.hits,
                bad_pm4.last_step,
            });
        }
    }

    /// Whether guest page protection is being enforced, and whether a
    /// protected access reached the guest's handler.
    ///
    /// The last row is the one the ring wall needs: a title's write to the
    /// ring write pointer travels fault -> vectored handler -> MMIO handler
    /// -> register callback -> `UpdateWritePointer` -> `ExecutePrimaryBuffer`,
    /// and every hop has a count. The first zero is where it stopped.
    pub fn reportGuestAccessViolations(self: *const ElfState) void {
        const table = &self.guest_page_protection;
        var handler_text: [guest_symbol_text_bytes]u8 = undefined;
        log.info("PE64 GUEST ACCESS VIOLATIONS: protected pages no_access={d} read_only={d} from {d} request(s) (guard={d} unmodelled_values={d} outside_window={d}); vectored handler={s}", .{
            table.no_access_pages,
            table.read_only_pages,
            table.requests,
            self.guest_page_protection_guard_requests,
            self.guest_page_protection_unmodelled_values,
            table.requests_outside_window,
            if (self.windows_vectored_exception_handler == 0)
                "none registered"
            else
                self.describeGuestAddressOrUnnamed(self.windows_vectored_exception_handler, &handler_text),
        });
        log.info("PE64 GUEST ACCESS VIOLATIONS:   raised={d} (reads={d} writes={d}) dispatched={d} handled={d} unhandled={d} no_handler={d} frame_refused={d} nesting_refused={d}", .{
            self.guest_access_violations_raised,
            self.guest_access_violation_reads,
            self.guest_access_violation_writes,
            self.guest_access_violations_dispatched,
            self.guest_access_violations_handled,
            self.guest_access_violations_unhandled,
            self.guest_access_violations_without_handler,
            self.guest_access_violations_frame_refused,
            self.guest_access_violations_nesting_refused,
        });
        for (self.guest_access_violation_sites[0..self.guest_access_violation_site_count]) |*site| {
            var rip_text: [guest_symbol_text_bytes]u8 = undefined;
            log.info("PE64 GUEST ACCESS VIOLATIONS:   page=0x{x} {s} reads={d} writes={d} handled={d} unhandled={d} first_step={d} last_offset=0x{x} last_value=0x{x} last_rip=0x{x} ({s})", .{
                site.page,
                site.protection.label(),
                site.reads,
                site.writes,
                site.handled,
                site.unhandled,
                site.first_step,
                site.last_offset,
                site.last_value,
                site.last_rip,
                self.describeGuestAddressOrUnnamed(site.last_rip, &rip_text),
            });
        }
        if (self.guest_access_violation_site_overflow != 0) {
            log.info("PE64 GUEST ACCESS VIOLATIONS:   {d} fault(s) on further pages were counted but not itemised", .{self.guest_access_violation_site_overflow});
        }

        const vectored = self.guestMilestoneActivity("_ZN2xe24ExceptionHandlerCallbackEP19_EXCEPTION_POINTERS");
        const mmio = self.guestMilestoneActivity("_ZN2xe3cpu11MMIOHandler17ExceptionCallbackEPNS_9ExceptionE");
        const write_thunk = self.guestMilestoneActivity("_ZN2xe3gpu14GraphicsSystem18WriteRegisterThunkEPvPS1_jj");
        const read_thunk = self.guestMilestoneActivity("_ZN2xe3gpu14GraphicsSystem17ReadRegisterThunkEPvPS1_j");
        const write_pointer = self.guestMilestoneActivity("_ZN2xe3gpu16CommandProcessor18UpdateWritePointerEj");
        const primary = self.guestMilestoneActivityAny(
            "_ZN2xe3gpu16CommandProcessor20ExecutePrimaryBufferEjj",
            "_ZN2xe3gpu6vulkan22VulkanCommandProcessor20ExecutePrimaryBufferEjj",
        );
        if (!(mmio.armed or write_thunk.armed or read_thunk.armed or write_pointer.armed or primary.armed)) return;
        log.info("PE64 GUEST ACCESS VIOLATIONS:   register delivery: faults_raised={d} -> dispatched={d} -> ExceptionHandlerCallback={d} -> MMIOHandler::ExceptionCallback={d} -> WriteRegisterThunk={d} (ReadRegisterThunk={d}) -> UpdateWritePointer={d} -> ExecutePrimaryBuffer(base/Vulkan)={d}", .{
            self.guest_access_violations_raised,
            self.guest_access_violations_dispatched,
            vectored.hits,
            mmio.hits,
            write_thunk.hits,
            read_thunk.hits,
            write_pointer.hits,
            primary.hits,
        });
        const direct_mmio = write_thunk.hits != 0 or read_thunk.hits != 0;
        const verdict: []const u8 = if (primary.hits != 0)
            "the register callback and command-processor path reached ExecutePrimaryBuffer (base or Vulkan override)"
        else if (write_pointer.hits != 0 and self.guest_access_violations_raised == 0)
            "direct MMIO callbacks reached UpdateWritePointer while ExecutePrimaryBuffer (base and Vulkan override) remained at zero; no interpreted access violation was needed, so the remaining wall is the GPU worker's write-pointer wake path"
        else if (direct_mmio and self.guest_access_violations_raised == 0)
            "direct MMIO callbacks handled register traffic without an interpreted access violation; page-protection fault counters are not this run's delivery path, and no write-pointer update was observed"
        else if (table.no_access_pages == 0)
            "no page was ever made no-access, so a register access cannot fault and cannot reach the register callbacks. Either the register block was never protected or its protection request was not recorded; the PAGE PROTECTION lines at start-up say which"
        else if (self.guest_access_violations_raised == 0)
            "register pages are protected and no interpreted access touched them: the title has not yet read or written a GPU register"
        else if (self.guest_access_violations_dispatched == 0)
            "protected accesses faulted but none was dispatched; no_handler, frame_refused and nesting_refused above say why"
        else if (vectored.armed and vectored.hits == 0)
            "faults were dispatched but not into ExceptionHandlerCallback, so the handler Rosette called is not the one that owns the register pages"
        else if (mmio.armed and mmio.hits == 0)
            "the vectored handler ran and never offered a fault to the MMIO handler"
        else if (write_thunk.hits == 0 and read_thunk.hits == 0)
            "the MMIO handler saw the faults and reached no register callback: the faulting instruction was not a load or store it can decode, or the address fell outside its ranges"
        else if (write_pointer.hits == 0)
            "register accesses reach the graphics system, and none of them moved the ring write pointer: the title has not yet asked the GPU to run anything"
        else if (primary.hits == 0)
            "the write pointer moved and the command processor did not execute the ring; from here the wall is Xenia's GPU thread"
        else
            "a register write travelled the whole path into the ring";
        log.info("PE64 GUEST ACCESS VIOLATIONS:   verdict: {s}", .{verdict});
    }

    /// Which SRW locks threads fought over, who holds each, and who waits.
    pub fn reportGuestLockContention(self: *const ElfState) void {
        var tracked: usize = 0;
        var contended: usize = 0;
        for (self.windows_srw_locks) |lock| {
            if (lock.address == 0) continue;
            tracked += 1;
            if (lock.contentions != 0) contended += 1;
        }
        log.info("PE64 LOCK CONTENTION: srw_locks={d} contended={d} contentions={d} handoffs={d} directed={d}; a release hands an SRW lock to its longest waiter and schedules that waiter next, because under one cooperative interpreter a waiter woken to race for it loses to whichever thread is already running, and one left for the circular scan holds the lock while it waits its turn", .{
            tracked,
            contended,
            self.windows_srw_lock_contentions,
            self.windows_srw_handoffs,
            self.windows_srw_directed_handoffs,
        });
        var shown: usize = 0;
        for (self.windows_srw_locks) |lock| {
            if (shown == 8) break;
            if (lock.address == 0) continue;
            const waiters = self.windowsSrwWaiterCount(lock);
            if (lock.contentions == 0 and waiters == 0) continue;
            shown += 1;
            var lock_text: [guest_symbol_text_bytes]u8 = undefined;
            var owner_text: [96]u8 = undefined;
            log.info("PE64 LOCK CONTENTION:   lock=0x{x} ({s}) owner={s} waiters={d} contentions={d} handoffs={d}", .{
                lock.address,
                self.describeGuestAddressOrUnnamed(lock.address, &lock_text),
                self.describeWindowsSrwOwner(lock.owner_thread_id, &owner_text),
                waiters,
                lock.contentions,
                lock.handoffs,
            });
            for (self.windows_guest_threads) |thread| {
                if (thread.thread_id == 0 or thread.thread_id != lock.owner_thread_id) continue;
                if (thread.status != .completed and thread.status != .failed) continue;
                log.warn("PE64 LOCK CONTENTION:     held by a thread that has exited. Windows never releases an SRW lock for a dead owner, so every waiter on it is blocked for good; the owner's last kernel call and import say what it was doing when it left", .{});
            }
        }
    }

    /// Every kernel export the title called, in the order it first called
    /// them, with the boot phase they place it in.
    ///
    /// This is the report the guest output chain has needed since it was
    /// written. The chain can say `title_queried_video_mode` is the wall; it
    /// cannot say what the title asked for *instead*, because until the
    /// export shims were armed nothing in Rosette could see a single act of
    /// the translated PowerPC. A stage reading zero is the absence of a
    /// diagnosis. This is the diagnosis.
    pub fn reportGuestKernelCalls(self: *const ElfState) void {
        const census = &self.guest_kernel_calls;
        if (census.armed == 0) {
            log.info("PE64 GUEST KERNEL CALLS: no export shim was armed this run, so the title's kernel traffic is unobservable; the arming line at start-up says why", .{});
            return;
        }
        const phase = census.furthest_phase;
        log.info("PE64 GUEST KERNEL CALLS: {d} distinct export(s) entered out of {d} this build serves, {d} call(s) total; boot phase reached: {s}", .{
            census.distinct_entered,
            census.armed_trampolines,
            census.total_calls,
            phase.label(),
        });
        if (census.distinct_entered == 0) {
            log.info("PE64 GUEST KERNEL CALLS:   the title has not made one kernel call. {s}", .{
                xenia_kernel_shim_map.BootPhase.no_kernel_contact.advice(),
            });
            // The one way this whole census could be silently wrong, said out
            // loud so the next run settles it rather than inheriting it.
            log.info("PE64 GUEST KERNEL CALLS:   this counts entry by call and by tail jump, at the registered trampoline's exact address. A translator that reaches its handler some third way - a computed dispatch that lands past the prologue, say - would read zero here while the title called constantly; the guest-code progress line above is the independent check on that", .{});
            if (census.forwarder_calls != 0) {
                log.warn("PE64 GUEST KERNEL CALLS:   but {d} `_entry` forwarder call(s) were seen with no trampoline entry at all, which is impossible if the trampolines are what the guest reaches. The census is watching the wrong address and every zero above is unreliable", .{
                    census.forwarder_calls,
                });
            }
        } else {
            // The two symbols answer the same question and are counted
            // apart, so their disagreement is readable rather than lost.
            if (census.forwarder_calls == 0) {
                log.info("PE64 GUEST KERNEL CALLS:   no `_entry` forwarder was entered, so this build inlined every one of them into its trampolines; a census armed on the forwarders would have read zero for all {d} of these calls", .{
                    census.total_calls,
                });
            } else if (census.forwarder_calls < census.total_calls) {
                const ratio_hundredths = @divTrunc(census.forwarder_calls *| 10_000, census.total_calls);
                log.info("PE64 GUEST KERNEL CALLS:   {d} of {d} title call(s) crossed a retained out-of-line `_entry` body ({d}.{d}%); these are implementation-layout crossings, not failed exports or additional guest calls, and the remaining calls were inlined into their trampolines", .{
                    census.forwarder_calls,
                    census.total_calls,
                    ratio_hundredths / 100,
                    ratio_hundredths % 100,
                });
            }
            if (census.forwarder_calls != 0) {
                var top_forwarders: [8]?*const kernel_call_census.Slot = [_]?*const kernel_call_census.Slot{null} ** 8;
                const top_count = census.topForwarders(&top_forwarders);
                log.info("PE64 GUEST KERNEL CALLS:   retained `_entry` body census (top {d}; a body is counted only for the calls that actually crossed it):", .{top_count});
                for (top_forwarders[0..top_count]) |entry| {
                    const trampoline = census.findExportOfKind(entry.?.export_name, .trampoline);
                    log.info("PE64 GUEST KERNEL CALLS:     forwarder={s}!{s} crossings={d} trampoline_calls={d} subsystem={s}", .{
                        entry.?.module.moduleName(),
                        entry.?.export_name,
                        entry.?.hits,
                        if (trampoline) |slot| slot.hits else 0,
                        entry.?.subsystem.label(),
                    });
                }
                if (top_count == 0) {
                    log.info("PE64 GUEST KERNEL CALLS:     no retained forwarder body has a nonzero hit count; the aggregate is from a stale/partial report and should be treated as inconsistent", .{});
                }
            }
            if (census.tail_jump_entries != 0) {
                log.info("PE64 GUEST KERNEL CALLS:   {d} of {d} entries arrived by tail jump rather than call; that is the translator's dispatch, not the title's behaviour, and it is reported so a count that moves between builds has an explanation", .{
                    census.tail_jump_entries,
                    census.total_calls,
                });
            }
            log.info("PE64 GUEST KERNEL CALLS:   {s}", .{phase.advice()});
            if (xenia_kernel_shim_map.nextPhase(phase)) |next| {
                const progress = census.phaseProgress(next);
                log.info("PE64 GUEST KERNEL CALLS:   the next phase is '{s}' and the title has called {d} of its {d} marker export(s) ({d} of them armed in this image); that phase is the one to make happen", .{
                    next.label(),
                    progress.called,
                    progress.declared,
                    progress.armed,
                });
            }
        }

        // Where the calls went. A reader looking for graphics wants to know
        // in one line whether any of the traffic was graphics at all.
        log.info("PE64 GUEST KERNEL CALLS:   step accounting total_interpreted_steps={d} owner_steps={d} worker_steps={d}; every first_step/last_step uses the combined denominator", .{
            self.totalInterpretedSteps(),
            self.executed_steps,
            self.windows_worker_executed_steps,
        });
        const synchronization_exports = [_][]const u8{
            "RtlEnterCriticalSection",
            "RtlLeaveCriticalSection",
            "KeWaitForSingleObject",
            "KeWaitForMultipleObjects",
            "NtWaitForSingleObject",
            "NtWaitForMultipleObjects",
            "NtDelayExecution",
            "WaitForSingleObject",
            "WaitForMultipleObjects",
        };
        for (synchronization_exports) |export_name| {
            if (census.findExport(export_name)) |slot| {
                if (slot.hits != 0) {
                    log.info("PE64 GUEST SYNCHRONIZATION COST: export={s} calls={d} first_step={d} last_step={d} subsystem={s}; this is guest synchronization overhead, separate from Rosetta's blocked-wait ledger", .{
                        export_name,
                        slot.hits,
                        slot.first_step,
                        slot.last_step,
                        slot.subsystem.label(),
                    });
                }
            }
        }
        const totals = census.subsystemTotals();
        inline for (@typeInfo(xenia_kernel_shim_map.Subsystem).@"enum".fields) |field| {
            const subsystem: xenia_kernel_shim_map.Subsystem = @enumFromInt(field.value);
            const total = totals[field.value];
            // A subsystem with nothing armed is not a fact about the title,
            // and one with no calls is only worth a row when the chain
            // depends on it - a zero there is the finding.
            if (total.armed != 0 and (total.calls != 0 or subsystem.feedsGuestOutput())) {
                log.info("PE64 GUEST KERNEL CALLS:   {s:<15} armed={d:<4} entered={d:<4} calls={d}{s}", .{
                    subsystem.label(),
                    total.armed,
                    total.distinct,
                    total.calls,
                    if (subsystem.feedsGuestOutput() and total.calls == 0)
                        "  <- the guest output chain is built entirely out of this subsystem and the title has not touched it"
                    else
                        "",
                });
            }
        }

        // Every graphics export, called or not. This is the list a reader
        // needs when the wall belongs to the title: the ones with a count are
        // what it did ask for, and the zeros are what it has not asked for
        // yet.
        var video_armed: u32 = 0;
        for (census.slots) |slot| {
            if (slot.address == 0 or slot.subsystem != .video or slot.kind != .trampoline) continue;
            video_armed += 1;
        }
        if (video_armed != 0) {
            log.info("PE64 GUEST KERNEL CALLS:   the {d} graphics export(s) this build serves, and what the title has asked of each:", .{video_armed});
            for (census.slots) |slot| {
                if (slot.address == 0 or slot.subsystem != .video or slot.kind != .trampoline) continue;
                if (slot.hits == 0) continue;
                log.info("PE64 GUEST KERNEL CALLS:     {s:<46} calls={d} first_step={d} last_step={d}", .{
                    slot.export_name,
                    slot.hits,
                    slot.first_step,
                    slot.last_step,
                });
            }
            var uncalled: u32 = 0;
            for (census.slots) |slot| {
                if (slot.address == 0 or slot.subsystem != .video or slot.kind != .trampoline or slot.hits != 0) continue;
                uncalled += 1;
            }
            if (uncalled != 0) {
                log.info("PE64 GUEST KERNEL CALLS:     never called ({d}):", .{uncalled});
                var line: [512]u8 = undefined;
                var used: usize = 0;
                var shutdown_only: u32 = 0;
                var optional_display_queries: u32 = 0;
                for (census.slots) |slot| {
                    if (slot.address == 0 or slot.subsystem != .video or slot.kind != .trampoline or slot.hits != 0) continue;
                    if (std.mem.eql(u8, slot.export_name, "VdShutdownEngines")) {
                        shutdown_only += 1;
                    } else if (std.mem.eql(u8, slot.export_name, "VdSetDisplayModeOverride") or
                        std.mem.eql(u8, slot.export_name, "VdQueryRealVideoMode") or
                        std.mem.eql(u8, slot.export_name, "VdQueryVideoFlags") or
                        std.mem.eql(u8, slot.export_name, "VdEnableDisableClockGating") or
                        std.mem.eql(u8, slot.export_name, "VdGetGraphicsAsicID"))
                    {
                        optional_display_queries += 1;
                    }
                    if (slot.export_name.len + 1 > line.len) continue;
                    const needed = slot.export_name.len + @as(usize, if (used == 0) 0 else 1);
                    if (used + needed > line.len) {
                        log.info("PE64 GUEST KERNEL CALLS:       {s}", .{line[0..used]});
                        used = 0;
                    }
                    if (used != 0) {
                        line[used] = ' ';
                        used += 1;
                    }
                    @memcpy(line[used .. used + slot.export_name.len], slot.export_name);
                    used += slot.export_name.len;
                }
                if (used != 0) log.info("PE64 GUEST KERNEL CALLS:       {s}", .{line[0..used]});
                if (shutdown_only != 0) {
                    log.info("PE64 GUEST KERNEL CALLS:       {d} never-called graphics export(s) are shutdown-only (VdShutdownEngines); their zero is expected until the title tears the device down, not a live rendering gap", .{shutdown_only});
                }
                if (optional_display_queries != 0) {
                    log.info("PE64 GUEST KERNEL CALLS:       {d} never-called graphics export(s) are optional display/policy queries (mode override, physical mode, video flags, clock gating, ASIC identity); their zero does not block output when the run already crossed VdQueryVideoMode/VdSetDisplayMode/VdGetCurrentDisplayInformation/VdSwap", .{optional_display_queries});
                }
            }
        }

        // The narrative tail. What the title reached for last is where it
        // stopped, and for a guest whose own instructions Rosette cannot name
        // this is the only account of its progress that exists.
        if (census.distinct_entered != 0) {
            const shown = @min(@as(usize, 12), census.distinct_entered);
            log.info("PE64 GUEST KERNEL CALLS:   the last {d} export(s) the title reached for, newest first; the top row is where it stopped making new kinds of request:", .{shown});
            var index: usize = 0;
            while (index < shown) : (index += 1) {
                const slot = census.nthLatestFirstEntry(index) orelse break;
                log.info("PE64 GUEST KERNEL CALLS:     first_step={d:<12} last_step={d:<12} {s}!{s} [{s}] calls={d}", .{
                    slot.first_step,
                    slot.last_step,
                    slot.module.moduleName(),
                    slot.export_name,
                    slot.subsystem.label(),
                    slot.hits,
                });
            }
            if (census.busiest()) |busy| {
                log.info("PE64 GUEST KERNEL CALLS:   busiest: {s} with {d} call(s); a kernel export entered far more than its neighbours is usually a poll, and a poll that never ends is the shape of a title waiting for something Rosette has not delivered", .{
                    busy.export_name,
                    busy.hits,
                });
            }
            if (census.slotAt(census.last_slot)) |latest| {
                const total_steps = self.totalInterpretedSteps();
                const quiet = total_steps -| census.last_step;
                log.info("PE64 GUEST KERNEL CALLS:   the most recent call of any kind was {s} at step {d}, which is {d} step(s) before the run ended; a title that has been silent for most of the run is not making requests Rosette could be failing", .{
                    latest.export_name,
                    census.last_step,
                    quiet,
                });
            }
        }

        // Who did the asking, in one line. The per-thread detail belongs in
        // PE64 GUEST THREADS, where a thread's status and share are beside
        // it; printing the whole list twice under two headings is how a
        // reader stops trusting either one.
        var busiest_caller: ?*const WindowsGuestThread = null;
        var attributed: u64 = 0;
        for (&self.windows_guest_threads) |*thread| {
            if (thread.status == .vacant or thread.kernel_calls == 0) continue;
            attributed +|= thread.kernel_calls;
            if (busiest_caller == null or thread.kernel_calls > busiest_caller.?.kernel_calls) {
                busiest_caller = thread;
            }
        }
        if (busiest_caller) |thread| {
            log.info("PE64 GUEST KERNEL CALLS:   the thread that asked most was '{s}' with {d} call(s); PE64 GUEST THREADS carries the rest, each beside its status and share", .{
                if (thread.name_len != 0) thread.nameText() else "<unnamed by the guest>",
                thread.kernel_calls,
            });
        }
        if (attributed != census.total_calls) {
            log.info("PE64 GUEST KERNEL CALLS:   {d} of {d} call(s) were made while Rosette's active-thread slot was unset and are counted but unattributed; that is a gap in the attribution, not in the census", .{
                census.total_calls -| attributed,
                census.total_calls,
            });
        }

        self.reportGuestKernelCoverage();
    }

    /// What the console publishes that this Xenia build does not implement.
    ///
    /// Static: it is a join between the Xbox 360's own export tables and the
    /// shims this image carries, and it says nothing about the run. It is
    /// here because "what is missing" had no answer at all before it, in any
    /// form - a title that calls an export Xenia does not implement reaches
    /// the unimplemented-export path, and no counter anywhere in Rosette
    /// could name what it had asked for.
    fn reportGuestKernelCoverage(self: *const ElfState) void {
        const census = &self.guest_kernel_calls;
        var published_total: u32 = 0;
        var implemented_total: u32 = 0;
        inline for (xenia_kernel_shim_map.modules) |module| {
            const row = kernel_call_census.coverageForModule(census, module);
            published_total += row.published;
            implemented_total += row.implemented;
        }
        log.info("PE64 KERNEL EXPORT COVERAGE: this Xenia build implements {d} of the {d} export(s) the console publishes across xboxkrnl/xam/xbdm ({d}%); a title that calls one of the other {d} reaches Xenia's unimplemented-export path", .{
            implemented_total,
            published_total,
            if (published_total == 0) @as(u32, 0) else implemented_total * 100 / published_total,
            published_total - implemented_total,
        });
        // Only the subsystems a chain depends on get a row of their own. The
        // rest are in the total above and a reader looking for a picture does
        // not need to walk them.
        inline for ([_]xenia_kernel_shim_map.Subsystem{ .video, .audio, .memory, .scheduling }) |subsystem| {
            const row = kernel_call_census.coverageFor(census, .xboxkrnl, subsystem);
            if (row.published != 0) {
                log.info("PE64 KERNEL EXPORT COVERAGE:   xboxkrnl {s:<12} published={d:<4} implemented={d:<4} missing={d}", .{
                    subsystem.label(),
                    row.published,
                    row.implemented,
                    row.published - row.implemented,
                });
            }
        }
        // Name the graphics ones. They are the shortest list that can change
        // a verdict: an unimplemented `Vd*` the title calls stops the guest
        // output chain dead and presents exactly like a title that never
        // asked.
        var buffer: [24][]const u8 = undefined;
        const missing = kernel_call_census.missingExports(census, .xboxkrnl, .video, &buffer);
        if (missing.len != 0) {
            log.info("PE64 KERNEL EXPORT COVERAGE:   graphics exports the console publishes and this build does not serve (first {d}):", .{missing.len});
            var line: [512]u8 = undefined;
            var used: usize = 0;
            for (missing) |name| {
                if (name.len + 1 > line.len) continue;
                if (used + name.len + 1 > line.len) {
                    log.info("PE64 KERNEL EXPORT COVERAGE:     {s}", .{line[0..used]});
                    used = 0;
                }
                if (used != 0) {
                    line[used] = ' ';
                    used += 1;
                }
                @memcpy(line[used .. used + name.len], name);
                used += name.len;
            }
            if (used != 0) log.info("PE64 KERNEL EXPORT COVERAGE:     {s}", .{line[0..used]});
            log.info("PE64 KERNEL EXPORT COVERAGE:   an unimplemented graphics export is not automatically a fault: most of these are HDCP, closed captioning and WSS, which no title needs to draw. It becomes one the moment PE64 GUEST KERNEL CALLS shows the title stalled in display-query", .{});
        }
    }

    pub fn reportGuestMilestones(self: *const ElfState) void {
        log.info("PE64 GUEST MILESTONES: {d} of {d} symbols armed; filter_misses={d}", .{
            self.guest_milestones_resolved,
            GUEST_MILESTONE_COUNT,
            self.guest_milestone_filter_misses,
        });
        var inlined_away: usize = 0;
        inline for (xenia_guest_milestone_map.milestones, 0..) |milestone, index| {
            if (self.guest_milestone_addresses[index] == 0) {
                log.info("PE64 GUEST MILESTONES:   {s:<40} unresolved (this image does not contain the symbol; its stage cannot be observed)", .{milestone.readable});
            } else {
                // An armed address with no entries and no direct branch to it
                // anywhere in the image is an out-of-line body the compiler
                // inlined into its callers. Printing that zero unqualified is
                // what let one build decision read as a stopped emulator.
                const reach = self.guestMilestoneReach(milestone.mangled);
                if (reach == .unreachable_inlined) inlined_away += 1;
                log.info("PE64 GUEST MILESTONES:   {s:<40} entries={d} reach={s} call_sites={d} vtable_refs={d} first_step={d} entry=0x{x} owner={s}{s}{s}{s}", .{
                    milestone.readable,
                    self.guest_milestone_hits[index],
                    reach.label(),
                    self.guest_milestone_call_sites[index],
                    self.guest_milestone_data_refs[index],
                    self.guest_milestone_first_step[index],
                    self.guest_milestone_addresses[index],
                    milestone.owner.label(),
                    if (milestone.proxy_only) " role=witness" else "",
                    if (reach == .unreachable_inlined) " INLINED-AWAY: nothing branches here and nothing stores this address, so this zero measures the build and not the run" else "",
                    if (reach == .unreachable_inlined and milestone.inline_proxy.len != 0) " (read its witness row instead)" else "",
                });
                self.reportGuestMilestoneCallers(index);
            }
        }
        if (!self.guest_milestone_call_sites_counted) {
            log.info("PE64 GUEST MILESTONES:   call-site census did not run on this route, so a zero entry count cannot be separated from an inlined body", .{});
        } else if (inlined_away != 0) {
            log.info("PE64 GUEST MILESTONES:   {d} armed symbol(s) are unreachable in this image: nothing branches to them and nothing stores their address. A tracepoint counts calls, and an optimizer that inlines a body leaves the out-of-line copy in the symbol table with nothing reaching it; read those rows through the witness they name, never as guest progress. reach=indirect is the opposite case - a virtual function has no call site either, and its zero is the guest", .{inlined_away});
        }
    }

    /// Split a milestone's entries by the call site they came from.
    ///
    /// Silent for a row with one caller, which is most of them. A witness row
    /// is the case this exists for: `EmulateCPInterruptDPC` stands in for the
    /// inlined `MarkVblank`, and three other places in the image also call
    /// it, so its total is a superset of the vblank count and reading it as
    /// the display rate overstates it.
    fn reportGuestMilestoneCallers(self: *const ElfState, index: usize) void {
        var distinct: usize = 0;
        for (self.guest_milestone_callers[index]) |caller| {
            if (caller != 0) distinct += 1;
        }
        if (distinct <= 1 and self.guest_milestone_caller_overflow[index] == 0) return;
        var caller_text: [guest_symbol_text_bytes]u8 = undefined;
        for (self.guest_milestone_callers[index], self.guest_milestone_caller_hits[index]) |caller, hits| {
            if (caller == 0) continue;
            log.info("PE64 GUEST MILESTONES:       from {s} (0x{x}) x{d}", .{
                self.describeGuestAddressOrUnnamed(caller, &caller_text),
                caller,
                hits,
            });
        }
        if (self.guest_milestone_caller_overflow[index] != 0) {
            log.info("PE64 GUEST MILESTONES:       and {d} entr(y/ies) from further call sites that did not fit the split", .{self.guest_milestone_caller_overflow[index]});
        }
    }

    /// Re-emit the first-frame and audio chains when their verdict moves.
    ///
    /// A full block at every checkpoint would repeat a dozen unchanged lines
    /// every fifty million steps and bury the checkpoint that mattered; a
    /// block only at exit is lost to every killed run. Emitting on change is
    /// the only version that is both readable and durable, and the "wall has
    /// moved" line is itself the progress signal a reader wants.
    pub fn reportRunChainsIfChanged(self: *ElfState, steps: u64) void {
        const frame_wall = self.firstFrameWall();
        const audio_wall = self.audioChainWall();
        const output_wall = self.guestOutputWall();
        const frame_name = if (frame_wall) |stage| stage.name else "<none>";
        const audio_name = if (audio_wall) |stage| stage.name else "<none>";
        const output_name = if (output_wall) |stage| stage.name else "<none>";

        const frame_moved = !std.mem.eql(u8, frame_name, self.reported_first_frame_wall);
        const audio_moved = !std.mem.eql(u8, audio_name, self.reported_audio_wall);
        const output_moved = !std.mem.eql(u8, output_name, self.reported_guest_output_wall);
        const refusals_moved = self.windows_module_refusal_events != self.reported_refusal_events or
            self.windows_proc_refusal_events != self.reported_proc_refusal_events;
        if (!frame_moved and !audio_moved and !output_moved and !refusals_moved and self.run_chains_reported) return;

        if (frame_moved and self.run_chains_reported) {
            log.info("PE64 FIRST FRAME CHAIN: the wall moved at step {d}: '{s}' -> '{s}'", .{
                steps,
                self.reported_first_frame_wall,
                frame_name,
            });
        }
        if (audio_moved and self.run_chains_reported) {
            log.info("PE64 AUDIO CHAIN: the wall moved at step {d}: '{s}' -> '{s}'", .{
                steps,
                self.reported_audio_wall,
                audio_name,
            });
        }
        if (output_moved and self.run_chains_reported) {
            log.info("PE64 GUEST OUTPUT CHAIN: the wall moved at step {d}: '{s}' -> '{s}'", .{
                steps,
                self.reported_guest_output_wall,
                output_name,
            });
        }
        self.reported_first_frame_wall = frame_name;
        self.reported_audio_wall = audio_name;
        self.reported_guest_output_wall = output_name;
        self.reported_refusal_events = self.windows_module_refusal_events;
        self.reported_proc_refusal_events = self.windows_proc_refusal_events;
        self.run_chains_reported = true;

        if (frame_moved) self.reportFirstFrameChain();
        if (output_moved) self.reportGuestOutputChain();
        if (audio_moved) self.reportAudioChain();
        if (refusals_moved) self.reportWindowsDynamicRefusals();
        self.reportWindowsMemoryContract();
    }

    /// Everything this run told the guest it did not have, in one block.
    ///
    /// Split by whether Rosetta *chose* the refusal or simply has no answer,
    /// because those are different work items: the first needs nothing, the
    /// second names a package somebody has to write.
    pub fn reportWindowsDynamicRefusals(self: *const ElfState) void {
        if (self.windows_module_refusal_events == 0 and
            self.windows_proc_refusal_events == 0 and
            self.windows_unreadable_module_names == 0) return;

        var module_gaps: u32 = 0;
        for (self.windows_module_refusals[0..self.windows_module_refusal_count]) |*record| {
            if (record.is_gap) module_gaps += 1;
        }
        log.info("PE64 DYNAMIC REFUSALS: modules={d} ({d} gap, {d} deliberate) in {d} call(s), exports={d} in {d} call(s), unreadable_names={d}", .{
            self.windows_module_refusal_count,
            module_gaps,
            self.windows_module_refusal_count - module_gaps,
            self.windows_module_refusal_events,
            self.windows_proc_refusal_count,
            self.windows_proc_refusal_events,
            self.windows_unreadable_module_names,
        });
        var caller_text: [guest_symbol_text_bytes]u8 = undefined;
        for (self.windows_module_refusals[0..self.windows_module_refusal_count]) |*record| {
            log.info("PE64 DYNAMIC REFUSALS:   {s} module '{s}' via {s} x{d} fallback={s} first_caller={s}", .{
                if (record.is_gap) "GAP     " else "policy  ",
                record.nameText(),
                record.scopeText(),
                record.occurrences,
                x64_linux_runtime.windowsModuleFallback(record.nameText()),
                self.describeGuestAddressOrUnnamed(record.first_caller_rip, &caller_text),
            });
        }
        var export_gaps: usize = 0;
        for (self.windows_proc_refusals[0..self.windows_proc_refusal_count]) |*record| {
            // A name Rosette declines on purpose is a decision, not a to-do.
            // Printing both as `GAP` put `WinUsb_ReadIsochPipeAsap` on the
            // work list, when answering it NULL is the whole reason libusb
            // never asks for the four isochronous entry points behind it.
            const deliberate = x64_linux_runtime.isDeliberateExportRefusal(record.scopeText(), record.nameText());
            if (!deliberate) export_gaps += 1;
            log.info("PE64 DYNAMIC REFUSALS:   {s} export {s} from '{s}' x{d} first_caller={s}", .{
                if (deliberate) "policy  " else "GAP     ",
                record.nameText(),
                if (record.scopeText().len == 0) "<unattributed>" else record.scopeText(),
                record.occurrences,
                self.describeGuestAddressOrUnnamed(record.first_caller_rip, &caller_text),
            });
        }
        if (module_gaps == 0 and export_gaps == 0) {
            log.info("PE64 DYNAMIC REFUSALS:   verdict: every refusal was a Rosette policy decision; no library or export is missing", .{});
        } else {
            log.info("PE64 DYNAMIC REFUSALS:   verdict: {d} module gap(s) and {d} export gap(s) name work Rosette has not done; each one is a per-DLL package under pkg/dll/win32/", .{
                module_gaps,
                export_gaps,
            });
        }
    }

    /// Say once whether the guest was given a CJK font, and what it costs.
    ///
    /// This is a Rosette policy decision that lands squarely on the guest's
    /// time-to-first-frame, so it belongs in the log next to the graphics
    /// evidence rather than in a source comment nobody reads during a run.
    pub fn noteGuestCjkFontDecision(self: *ElfState, granted: bool, detail: []const u8) void {
        if (self.windows_cjk_font_decision_reported) return;
        self.windows_cjk_font_decision_reported = true;
        self.windows_cjk_font_granted = granted;
        if (granted) {
            log.info("PE64 guest font policy: CJK font granted (host='{s}'). Xenia will merge the Japanese glyph ranges into its ImGui atlas and build that atlas twice, on the UI thread, before the window can paint. Expect several hundred million guest steps inside stb_truetype first; set ROSETTE_XENIA_GUEST_CJK_FONT=0 to skip it.", .{detail});
        } else {
            log.info("PE64 guest font policy: CJK font withheld (reason: {s}). Xenia takes its documented fallback and Japanese characters render as boxes; the ImGui atlas stays ASCII-sized so the first frame is not behind a full glyph rasterization. Set ROSETTE_XENIA_GUEST_CJK_FONT=1 to grant it.", .{
                if (detail.len == 0) "not requested by policy" else detail,
            });
        }
    }

    /// Install the guest symbol resolver. Called once, by the image loader.
    pub fn installGuestSymbolResolver(
        self: *ElfState,
        resolver: GuestSymbolResolver,
        symbol_count: u32,
        coverage_percent: u32,
    ) void {
        self.guest_symbol_resolver = resolver;
        self.guest_symbol_count = symbol_count;
        self.guest_symbol_coverage_percent = coverage_percent;
        self.xenia_clock = .{ .symbols = xenia_clock_probe.Symbols.discover(resolver) };
        self.armGuestMilestones();
    }

    /// Resolve the milestone table against this image and build the filter.
    ///
    /// Called once, from `installGuestSymbolResolver`, because a milestone
    /// can only be armed after there is something to resolve names with. A
    /// resolver with no `address_of` arms nothing and leaves every row
    /// unresolved, which the report states rather than hides.
    fn armGuestMilestones(self: *ElfState) void {
        self.guest_milestones_armed = true;
        const resolver = self.guest_symbol_resolver orelse return;
        const address_of = resolver.address_of orelse return;
        var resolved: u32 = 0;
        inline for (xenia_guest_milestone_map.milestones, 0..) |milestone, index| {
            if (address_of(resolver.context, milestone.mangled)) |address| {
                self.guest_milestone_addresses[index] = address;
                const bit = guestMilestoneFilterBit(address);
                self.guest_milestone_slot[bit] = if (self.guest_milestone_slot[bit] == 0)
                    @intCast(index + 1)
                else
                    milestone_slot_collision;
                resolved += 1;
            }
        }
        self.guest_milestone_filter_populated = resolved != 0;
        self.guest_milestones_resolved = resolved;
    }

    /// Record that the guest called the entry point of a milestone.
    ///
    /// Placed on the call paths rather than on every step: a C++ member
    /// function is reached by `call`, direct or indirect, and paying a bit
    /// test per instruction to also catch a tail jump would cost more than
    /// the answer is worth.
    fn noteGuestMilestoneEntry(self: *ElfState, target: u64) void {
        const bit = guestMilestoneFilterBit(target);
        const slot = self.guest_milestone_slot[bit];
        if (slot == 0) return;
        if (slot != milestone_slot_collision) {
            // The common case: this bit belongs to exactly one armed address,
            // so a filter hit costs one comparison rather than a scan.
            const index = @as(usize, slot) - 1;
            if (self.guest_milestone_addresses[index] != target) {
                self.guest_milestone_filter_misses +|= 1;
                return;
            }
            self.recordGuestMilestone(index, target);
            return;
        }
        for (self.guest_milestone_addresses, 0..) |address, index| {
            if (address != target) continue;
            self.recordGuestMilestone(index, target);
            return;
        }
        self.guest_milestone_filter_misses +|= 1;
    }

    /// Xenia's `CommandProcessor::UpdateWritePointer` publishes the ring
    /// pointer and then calls `Win32Event::SetBoostPriority` through its
    /// vtable.  The PE image's indirect host/dynamic-import edge is not
    /// observable in every execution route, so keep a narrowly scoped repair
    /// at the proven milestone: follow only the command-processor event
    /// fields established by Xenia, verify the handle belongs to Rosetta's
    /// wait table, and signal that exact object.  The milestone hook runs
    /// before the function body, so it also publishes the exact write-pointer
    /// argument before waking the worker; otherwise the worker observes the
    /// old empty ring and sleeps again.  This is intentionally not a general
    /// GPU wake or a handle guess.
    fn repairXeniaGpuWritePointerWake(self: *ElfState) void {
        const command_processor = self.regs.rcx;
        const write_pointer: u32 = @truncate(self.regs.rdx);
        if (command_processor == 0 or
            self.guestMemoryConst(command_processor +| 0x260, 8) == null or
            self.guestMemoryConst(command_processor +| 0x268, 4) == null)
        {
            self.windows_gpu_write_pointer_wake_repair_misses +|= 1;
            log.warn("PE64 GPU write-pointer wake repair miss: reason=command_processor_unmapped this=0x{x} write_ptr=0x{x} step={d} misses={d}", .{
                command_processor,
                write_pointer,
                self.executed_steps,
                self.windows_gpu_write_pointer_wake_repair_misses,
            });
            return;
        }
        const event_object = self.read64(command_processor +| 0x260);
        if (event_object == 0 or self.guestMemoryConst(event_object +| 8, 8) == null) {
            self.windows_gpu_write_pointer_wake_repair_misses +|= 1;
            log.warn("PE64 GPU write-pointer wake repair miss: reason=event_object_unmapped this=0x{x} event=0x{x} write_ptr=0x{x} step={d} misses={d}", .{
                command_processor,
                event_object,
                write_pointer,
                self.executed_steps,
                self.windows_gpu_write_pointer_wake_repair_misses,
            });
            return;
        }
        const handle = self.read64(event_object +| 8);
        if (self.windowsWaitObjectIndex(handle) == null) {
            self.windows_gpu_write_pointer_wake_repair_misses +|= 1;
            log.warn("PE64 GPU write-pointer wake repair miss: reason=unregistered_event_handle this=0x{x} event=0x{x} handle=0x{x} write_ptr=0x{x} step={d} misses={d}", .{
                command_processor,
                event_object,
                handle,
                write_pointer,
                self.executed_steps,
                self.windows_gpu_write_pointer_wake_repair_misses,
            });
            return;
        }
        // The milestone is observed on entry, before Xenia's `xchgl
        // 0x268(%this), edx`. Mirror that one proven side effect before
        // waking the auto-reset event. The function body immediately repeats
        // the same exchange, so this preserves its contract and only restores
        // the ordering the worker relies on.
        self.write32(command_processor +| 0x268, write_pointer);
        const woken = self.signalWindowsWaitObject(handle, false);
        self.windows_gpu_write_pointer_wake_repairs +|= 1;
        log.info("PE64 GPU write-pointer wake repair: this=0x{x} event=0x{x} handle=0x{x} write_ptr=0x{x} woken={d} signaled_after={} step={d} repairs={d} misses={d}", .{
            command_processor,
            event_object,
            handle,
            write_pointer,
            woken,
            self.windowsWaitObjectSignaled(handle),
            self.executed_steps,
            self.windows_gpu_write_pointer_wake_repairs,
            self.windows_gpu_write_pointer_wake_repair_misses,
        });
    }

    fn recordGuestMilestone(self: *ElfState, index: usize, target: u64) void {
        // Which call site this entry came from. Four comparisons on a path
        // taken a few hundred thousand times in a run, against a witness row
        // whose total is otherwise unreadable.
        const caller = self.last_instruction_rip;
        const accounting_step = self.totalInterpretedSteps();
        var placed = false;
        for (&self.guest_milestone_callers[index], 0..) |*slot, slot_index| {
            if (slot.* == caller) {
                self.guest_milestone_caller_hits[index][slot_index] +|= 1;
                placed = true;
                break;
            }
            if (slot.* == 0) {
                slot.* = caller;
                self.guest_milestone_caller_hits[index][slot_index] = 1;
                placed = true;
                break;
            }
        }
        if (!placed) self.guest_milestone_caller_overflow[index] +|= 1;
        if (self.windows_active_guest_thread_slot) |slot| {
            if (index == comptime xenia_guest_milestone_map.indexOf("_ZN2xe6kernel7XThread7ExecuteEv").?) {
                self.windows_guest_threads[slot].entered_xenia_title = true;
            }
            self.windows_guest_threads[slot].last_milestone = @intCast(index + 1);
            self.windows_guest_threads[slot].last_milestone_step = accounting_step;
        }
        if (self.guest_milestone_hits[index] == 0) {
            self.guest_milestone_first_step[index] = accounting_step;
            const milestone = xenia_guest_milestone_map.milestones[index];
            log.info("PE64 GUEST MILESTONE: {s} reached for the first time at step {d} rip=0x{x} owner={s} chain={s}; {s}", .{
                milestone.readable,
                accounting_step,
                target,
                milestone.owner.label(),
                milestone.chain.label(),
                milestone.proves,
            });
        }
        self.guest_milestone_hits[index] +|= 1;
        self.guest_milestone_last_step[index] = accounting_step;
        // Arguments first: the wake repair below signals objects and must not
        // be what a ring decode reads its write pointer from.
        if (self.windows_runtime_enabled) self.noteGuestMilestoneArguments(index);
        if (self.windows_runtime_enabled and
            index == comptime xenia_guest_milestone_map.indexOf("_ZN2xe3gpu16CommandProcessor18UpdateWritePointerEj").?)
        {
            self.repairXeniaGpuWritePointerWake();
        }
    }

    /// Read the arguments of the milestones whose arguments are the evidence.
    ///
    /// Called at the `call`, before the return address is pushed, so the
    /// Windows x64 argument registers still hold what the caller passed:
    /// `rcx` is `this` for a member function, then `rdx`, `r8`, `r9`.
    fn noteGuestMilestoneArguments(self: *ElfState, index: usize) void {
        const map = xenia_guest_milestone_map;
        if (index == comptime map.indexOf("_ZN2xe3gpu14GraphicsSystem18WriteRegisterThunkEPvPS1_jj").?) {
            // WriteRegisterThunk(ppc_context, graphics_system, addr, value)
            _ = self.noteGpuRegisterAccess(@truncate(self.regs.r8), true, @truncate(self.regs.r9));
        } else if (index == comptime map.indexOf("_ZN2xe3gpu14GraphicsSystem17ReadRegisterThunkEPvPS1_j").?) {
            // ReadRegisterThunk(ppc_context, graphics_system, addr) -> value
            if (self.noteGpuRegisterAccess(@truncate(self.regs.r8), false, 0)) |slot| {
                self.armGuestReturnCapture(.gpu_register_read, @intCast(slot));
            }
        } else if (index == comptime map.indexOf("_ZN2xe3gpu14GraphicsSystem20InitializeRingBufferEjj").?) {
            // InitializeRingBuffer(this, ptr, size_log2)
            self.gpu_ring_base = @truncate(self.regs.rdx);
            self.gpu_ring_size_log2 = @truncate(self.regs.r8);
            self.gpu_ring_initialized = true;
            self.gpu_ring_last_write_index = 0;
        } else if (index == comptime map.indexOf("_ZN2xe3gpu14GraphicsSystem26EnableReadPointerWriteBackEjj").?) {
            self.gpu_ring_rptr_writeback = @truncate(self.regs.rdx);
        } else if (index == comptime map.indexOf("_ZN2xe3gpu16CommandProcessor18UpdateWritePointerEj").?) {
            // UpdateWritePointer(this, value)
            self.noteGpuRingWritePointer(@truncate(self.regs.rdx));
        } else if (index == comptime map.indexOf("_ZN2xe3vfs17VirtualFileSystem11ResolvePathESt17basic_string_viewIcSt11char_traitsIcEE").?) {
            self.noteGuestVfsResolveEntry();
        } else if (index == comptime map.indexOf("_ZN2xe3apu11AudioSystem11SubmitFrameEyPf").?) {
            // SubmitFrame(this, index, samples)
            self.noteAudioTitleFrame(self.regs.r8);
        }
    }

    fn activeReturnCapture(self: *ElfState) *GuestReturnCapture {
        if (self.windows_active_guest_thread_slot) |slot| return &self.windows_guest_threads[slot].return_capture;
        return &self.owner_return_capture;
    }

    fn armGuestReturnCapture(self: *ElfState, kind: GuestReturnCaptureKind, tag: u32) void {
        const capture = self.activeReturnCapture();
        if (capture.kind != .none) {
            // A capture this thread never returned from - an unwind, a
            // longjmp - is replaced rather than leaked.
            self.guest_return_captures_replaced +|= 1;
        } else {
            self.guest_return_captures_armed +|= 1;
        }
        capture.* = .{ .kind = kind, .return_rsp = self.regs.rsp, .tag = tag };
    }

    /// Called from the `ret` arm, after the pop, while any capture is armed.
    fn completeGuestReturnCapture(self: *ElfState) void {
        const capture = self.activeReturnCapture();
        if (capture.kind == .none or capture.return_rsp != self.regs.rsp) return;
        const finished = capture.*;
        capture.* = .{};
        self.guest_return_captures_armed -|= 1;
        self.guest_return_captures_completed +|= 1;
        switch (finished.kind) {
            .none => {},
            .gpu_register_read => {
                if (finished.tag >= self.gpu_register_traffic_count) return;
                const entry = &self.gpu_register_traffic[finished.tag];
                const value: u32 = @truncate(self.regs.rax);
                if (entry.read_returns != 0 and value != entry.last_read_value) entry.read_value_changes +|= 1;
                entry.read_returns +|= 1;
                entry.last_read_value = value;
            },
            .vfs_resolve => {
                if (finished.tag >= self.guest_vfs_resolve_count) return;
                const entry = &self.guest_vfs_resolves[finished.tag];
                if (self.regs.rax == 0) {
                    entry.not_found +|= 1;
                    self.guest_vfs_resolve_not_found +|= 1;
                    // An empty name has no device to be missing from. The
                    // line Xenia prints for it arrives later through an
                    // asynchronous logger; this is the synchronous moment,
                    // with the request that produced it still in hand.
                    if (entry.path_len == 0 and !entry.truncated) self.faultGuestVfsEmptyName(entry);
                } else {
                    entry.found +|= 1;
                }
            },
        }
    }

    /// Count one register access by Xenos index, returning its ledger slot.
    fn noteGpuRegisterAccess(self: *ElfState, address: u32, is_write: bool, value: u32) ?usize {
        const register: u16 = @truncate((address & 0xFFFF) / 4);
        if (is_write) self.gpu_register_writes +|= 1 else self.gpu_register_reads +|= 1;
        const count = self.gpu_register_traffic_count;
        const slot = blk: {
            // A poll reads one register over and over; check the last hit
            // before scanning.
            if (self.gpu_register_last_slot < count and self.gpu_register_traffic[self.gpu_register_last_slot].index == register) {
                break :blk self.gpu_register_last_slot;
            }
            for (self.gpu_register_traffic[0..count], 0..) |*entry, entry_index| {
                if (entry.index == register) break :blk entry_index;
            }
            if (count == GPU_REGISTER_TRAFFIC_CAPACITY) {
                self.gpu_register_traffic_overflow +|= 1;
                return null;
            }
            self.gpu_register_traffic[count] = .{ .index = register, .first_step = self.executed_steps };
            self.gpu_register_traffic_count += 1;
            break :blk count;
        };
        self.gpu_register_last_slot = slot;
        const entry = &self.gpu_register_traffic[slot];
        if (is_write) {
            entry.writes +|= 1;
            entry.last_write_value = value;
        } else {
            entry.reads +|= 1;
        }
        entry.last_step = self.executed_steps;
        entry.last_thread_slot = if (self.windows_active_guest_thread_slot) |thread| @intCast(@min(thread + 1, 255)) else 0;
        return slot;
    }

    /// The Rosette address of Xenia's guest address zero, found from the
    /// views Xenia mapped: the 1 GiB view of mapping offset 0 whose mapping
    /// also has the physical view 4 GiB above it at offset 0x100000000.
    fn xeniaVirtualMembase(self: *const ElfState) ?u64 {
        for (self.windows_memory_views[0..self.windows_memory_view_count]) |view| {
            if (view.length < 0x4000_0000 or view.backing_offset != 0) continue;
            const physical = std.math.add(u64, view.guest_base, 0x1_0000_0000) catch continue;
            for (self.windows_memory_views[0..self.windows_memory_view_count]) |candidate| {
                if (candidate.length == 0 or candidate.mapping_index != view.mapping_index) continue;
                if (candidate.guest_base == physical and candidate.backing_offset == 0x1_0000_0000) return view.guest_base;
            }
        }
        return null;
    }

    /// Reads ring dwords through Xenia's physical view, and checks them
    /// against the title's virtual aliases of the same pages.
    const GpuRingSource = struct {
        state: *const ElfState,
        membase: u64,
        base: u32,

        fn physicalAddress(self: GpuRingSource, ring_index: u64) u64 {
            return (@as(u64, self.base) & 0x1FFF_FFFF) + ring_index * 4;
        }

        pub fn readDword(self: GpuRingSource, ring_index: u64) ?u32 {
            const bytes = self.state.guestMemoryConst(self.membase + 0x1_0000_0000 + self.physicalAddress(ring_index), 4) orelse return null;
            return std.mem.readInt(u32, bytes[0..4], .big);
        }

        /// How many aliases were readable, and how many disagreed.
        pub fn aliasCheck(self: GpuRingSource, ring_index: u64, physical_value: u32) struct { checked: u16, mismatched: u16 } {
            var checked: u16 = 0;
            var mismatched: u16 = 0;
            // Xenia maps its 4 KiB and 64 KiB physical heaps at 0xA0000000
            // and 0xC0000000 onto the same mapping offsets as the physical
            // view; a title writes its ring through one of them.
            for ([_]u64{ 0xA000_0000, 0xC000_0000 }) |alias| {
                const bytes = self.state.guestMemoryConst(self.membase + alias + self.physicalAddress(ring_index), 4) orelse continue;
                checked += 1;
                if (std.mem.readInt(u32, bytes[0..4], .big) != physical_value) mismatched += 1;
            }
            return .{ .checked = checked, .mismatched = mismatched };
        }
    };

    /// Decode the dwords between two write-pointer values the way Xenia's
    /// `ExecutePacket` walks them: a header of 0, 0x0BADF00D or 0xCDCDCDCD is
    /// skipped, a type 0 or type 3 header carries `count + 1` payload dwords,
    /// a type 1 header two.
    fn decodeGpuRingWindow(source: anytype, window: *GpuRingWindow, from: u64, span: u64, ring_dwords: u64) void {
        var cursor: u64 = 0;
        var payload: u64 = 0;
        const limit = @min(span, GPU_RING_WINDOW_DECODE_LIMIT);
        while (cursor < limit) : (cursor += 1) {
            const ring_index = (from + cursor) % ring_dwords;
            const dword = source.readDword(ring_index) orelse break;
            window.readable = true;
            window.decoded += 1;
            if (window.first_dword_count < GPU_RING_WINDOW_FIRST_DWORDS) {
                window.first_dwords[window.first_dword_count] = dword;
                window.first_dword_count += 1;
            }
            if (dword == 0) window.zero_dwords += 1;
            if (cursor < GPU_RING_WINDOW_ALIAS_CHECKS) {
                const alias = source.aliasCheck(ring_index, dword);
                window.alias_checks +|= alias.checked;
                window.alias_mismatches +|= alias.mismatched;
            }
            if (payload != 0) {
                payload -= 1;
                continue;
            }
            if (dword == 0 or dword == 0x0BAD_F00D or dword == 0xCDCD_CDCD) {
                if (dword != 0) window.marker_dwords += 1;
                continue;
            }
            switch (dword >> 30) {
                0 => {
                    window.type0 += 1;
                    payload = ((dword >> 16) & 0x3FFF) + 1;
                },
                1 => {
                    window.type1 += 1;
                    payload = 2;
                },
                2 => window.type2 += 1,
                else => {
                    window.type3 += 1;
                    const opcode: u8 = @truncate((dword >> 8) & 0x7F);
                    if (window.type3_opcode_count < GPU_RING_WINDOW_OPCODES) {
                        window.type3_opcodes[window.type3_opcode_count] = opcode;
                        window.type3_opcode_count += 1;
                    }
                    switch (opcode) {
                        0x22, 0x34, 0x35, 0x36 => window.draw_packets += 1,
                        0x64 => window.swap_packets += 1,
                        0x37, 0x3F => if (window.indirect_buffers < GPU_RING_WINDOW_INDIRECT_BUFFERS) {
                            // ExecutePacketType3_INDIRECT_BUFFER reads the
                            // list pointer and its length as the next two
                            // dwords.
                            if (source.readDword((from + cursor + 1) % ring_dwords)) |address| {
                                if (source.readDword((from + cursor + 2) % ring_dwords)) |length| {
                                    window.indirect_addresses[window.indirect_buffers] = address & 0x1FFF_FFFF;
                                    window.indirect_dwords[window.indirect_buffers] = length & 0xF_FFFF;
                                    window.indirect_buffers += 1;
                                }
                            }
                        },
                        else => {},
                    }
                    payload = ((dword >> 16) & 0x3FFF) + 1;
                },
            }
        }
    }

    fn noteGpuRingWritePointer(self: *ElfState, write_index: u32) void {
        self.gpu_ring_updates +|= 1;
        const from = self.gpu_ring_last_write_index;
        self.gpu_ring_last_write_index = write_index;
        if (!self.gpu_ring_initialized or self.gpu_ring_size_log2 >= 29) return;
        // Xenia: primary_buffer_size_ = 1 << (size_log2 + 3) bytes.
        const ring_dwords: u64 = (@as(u64, 1) << @intCast(self.gpu_ring_size_log2 + 3)) / 4;
        if (ring_dwords == 0) return;
        const to = @as(u64, write_index) % ring_dwords;
        const start = @as(u64, from) % ring_dwords;
        const span = if (to >= start) to - start else ring_dwords - start + to;
        var window = GpuRingWindow{
            .step = self.executed_steps,
            .from_index = from,
            .to_index = write_index,
            .dwords = @intCast(@min(span, std.math.maxInt(u32))),
        };
        if (self.xeniaVirtualMembase()) |membase| {
            const source = GpuRingSource{ .state = self, .membase = membase, .base = self.gpu_ring_base };
            decodeGpuRingWindow(source, &window, start, span, ring_dwords);
            for (window.indirect_addresses[0..window.indirect_buffers], window.indirect_dwords[0..window.indirect_buffers]) |address, dwords| {
                self.decodeGpuIndirectBuffer(membase, address, dwords);
            }
        }
        if (!window.readable and span != 0) self.gpu_ring_unreadable_updates +|= 1;
        self.gpu_ring_dwords_decoded +|= window.decoded;
        self.gpu_ring_zero_dwords +|= window.zero_dwords;
        self.gpu_ring_type0_packets +|= window.type0;
        self.gpu_ring_type3_packets +|= window.type3;
        self.gpu_ring_alias_mismatches +|= window.alias_mismatches;
        self.gpu_ring_draw_packets +|= window.draw_packets;
        self.gpu_ring_swap_packets +|= window.swap_packets;
        // Keep the first windows, and let the last slot track the newest.
        const slot = @min(self.gpu_ring_window_count, GPU_RING_WINDOW_CAPACITY - 1);
        self.gpu_ring_windows[slot] = window;
        if (self.gpu_ring_window_count < GPU_RING_WINDOW_CAPACITY) self.gpu_ring_window_count += 1;
    }

    /// Decode one indirect buffer the ring pointed at.
    ///
    /// A Direct3D title's primary ring is mostly ME_INIT and INDIRECT_BUFFER;
    /// the state, the draws and the swap live in the buffers those packets
    /// name. A decode that stops at the ring can say the title submitted work
    /// and never what the work was.
    fn decodeGpuIndirectBuffer(self: *ElfState, membase: u64, address: u32, dwords: u32) void {
        self.gpu_indirect_buffers_seen +|= 1;
        var window = GpuRingWindow{ .step = self.executed_steps, .from_index = address, .to_index = dwords, .dwords = dwords };
        if (dwords != 0) {
            const source = GpuRingSource{ .state = self, .membase = membase, .base = address };
            decodeGpuRingWindow(source, &window, 0, dwords, dwords);
            if (!window.readable) self.gpu_indirect_buffers_unreadable +|= 1;
        }
        self.gpu_indirect_type3_packets +|= window.type3;
        self.gpu_indirect_draw_packets +|= window.draw_packets;
        self.gpu_indirect_swap_packets +|= window.swap_packets;
        const slot = @min(self.gpu_indirect_buffer_count, GPU_INDIRECT_BUFFER_CAPACITY - 1);
        self.gpu_indirect_buffers[slot] = window;
        if (self.gpu_indirect_buffer_count < GPU_INDIRECT_BUFFER_CAPACITY) self.gpu_indirect_buffer_count += 1;
    }

    /// Record the path `VirtualFileSystem::ResolvePath` was given.
    ///
    /// `ResolvePath(this, std::string_view path)`: a 16-byte aggregate, which
    /// the Windows x64 convention passes by reference, so `rdx` points at
    /// libstdc++'s `{ size_t length; const char* data; }`.
    fn noteGuestVfsResolveEntry(self: *ElfState) void {
        self.guest_vfs_resolve_calls +|= 1;
        const view = self.guestMemoryConst(self.regs.rdx, 16) orelse {
            self.guest_vfs_resolve_unreadable +|= 1;
            return;
        };
        const length = std.mem.readInt(u64, view[0..8], .little);
        const data = std.mem.readInt(u64, view[8..16], .little);
        if (length > 4096) {
            self.guest_vfs_resolve_unreadable +|= 1;
            return;
        }
        const shown = @min(length, GUEST_VFS_PATH_BYTES);
        const path: []const u8 = if (shown == 0)
            ""
        else
            self.guestMemoryConst(data, shown) orelse {
                self.guest_vfs_resolve_unreadable +|= 1;
                return;
            };
        const slot = blk: {
            for (self.guest_vfs_resolves[0..self.guest_vfs_resolve_count], 0..) |*entry, entry_index| {
                if (std.mem.eql(u8, entry.pathText(), path)) break :blk entry_index;
            }
            if (self.guest_vfs_resolve_count == GUEST_VFS_RESOLVE_CAPACITY) {
                self.guest_vfs_resolve_overflow +|= 1;
                return;
            }
            const entry_index = self.guest_vfs_resolve_count;
            self.guest_vfs_resolve_count += 1;
            const entry = &self.guest_vfs_resolves[entry_index];
            entry.* = .{ .first_step = self.executed_steps, .path_len = @intCast(path.len), .truncated = length > shown };
            @memcpy(entry.path[0..path.len], path);
            break :blk entry_index;
        };
        const entry = &self.guest_vfs_resolves[slot];
        entry.calls +|= 1;
        entry.last_step = self.executed_steps;
        entry.caller_rip = self.last_instruction_rip;
        if (self.windows_active_guest_thread_slot) |thread_slot| {
            entry.thread_slot = @intCast(@min(thread_slot + 1, 255));
            entry.kernel_slot = self.windows_guest_threads[thread_slot].last_kernel_slot;
        } else {
            entry.thread_slot = 0;
            entry.kernel_slot = 0;
        }
        self.armGuestReturnCapture(.vfs_resolve, @intCast(slot));
    }

    /// Whether `path` is a module name rather than a path into a guest device.
    fn guestVfsPathIsBareModuleName(path: []const u8) bool {
        return path.len != 0 and
            std.mem.indexOfScalar(u8, path, ':') == null and
            std.mem.indexOfScalar(u8, path, '\\') == null and
            std.mem.indexOfScalar(u8, path, '/') == null;
    }

    fn guestVfsPathBasename(path: []const u8) []const u8 {
        var start: usize = 0;
        for (path, 0..) |character, index| {
            if (character == ':' or character == '\\' or character == '/') start = index + 1;
        }
        return path[start..];
    }

    fn guestVfsModuleStem(path: []const u8) []const u8 {
        const basename = guestVfsPathBasename(path);
        if (basename.len >= 4 and std.ascii.eqlIgnoreCase(basename[basename.len - 4 ..], ".dll")) {
            return basename[0 .. basename.len - 4];
        }
        return basename;
    }

    fn guestVfsModuleNamesEqual(lhs: []const u8, rhs: []const u8) bool {
        const lhs_stem = guestVfsModuleStem(lhs);
        const rhs_stem = guestVfsModuleStem(rhs);
        return lhs_stem.len != 0 and rhs_stem.len != 0 and std.ascii.eqlIgnoreCase(lhs_stem, rhs_stem);
    }

    /// Return the explicit, found device path that proves a bare module-name
    /// miss was only the first half of Xenia's loaded-module lookup. Only DLL
    /// paths qualify: a bare name matching `\\Device\\Harddisk0`, for
    /// example, would be a false reconciliation rather than module evidence.
    fn guestVfsMatchedDevicePath(self: *const ElfState, module_name: []const u8) []const u8 {
        if (!guestVfsPathIsBareModuleName(module_name)) return "";
        for (self.guest_vfs_resolves[0..self.guest_vfs_resolve_count]) |*candidate| {
            const path = candidate.pathText();
            const basename = guestVfsPathBasename(path);
            if (candidate.found == 0 or path.len == 0 or guestVfsPathIsBareModuleName(path)) continue;
            if (basename.len < 4 or !std.ascii.eqlIgnoreCase(basename[basename.len - 4 ..], ".dll")) continue;
            if (guestVfsModuleNamesEqual(module_name, path)) return path;
        }
        return "";
    }

    fn classifyGuestVfsResolves(self: *const ElfState) GuestVfsResolveSummary {
        var summary: GuestVfsResolveSummary = .{};
        for (self.guest_vfs_resolves[0..self.guest_vfs_resolve_count]) |*entry| {
            const path = entry.pathText();
            if (path.len == 0) {
                summary.empty_path_not_found +|= entry.not_found;
                continue;
            }
            if (guestVfsPathIsBareModuleName(path)) {
                summary.bare_module_calls +|= entry.calls;
                summary.bare_module_not_found +|= entry.not_found;
                summary.bare_module_paths +|= 1;
                if (self.guestVfsMatchedDevicePath(path).len != 0) {
                    summary.bare_module_paths_reconciled +|= 1;
                } else {
                    summary.bare_module_unmatched_not_found +|= entry.not_found;
                }
                continue;
            }
            summary.device_path_not_found +|= entry.not_found;
        }
        return summary;
    }

    /// The VFS ledger's record of `path`, as a suffix for a log line, or an
    /// empty slice when Xenia was never seen resolving it.
    fn describeVfsResolveFor(self: *const ElfState, path: []const u8, buffer: []u8) []const u8 {
        for (self.guest_vfs_resolves[0..self.guest_vfs_resolve_count]) |*entry| {
            if (!std.mem.eql(u8, entry.pathText(), path)) continue;
            var caller_text: [guest_symbol_text_bytes]u8 = undefined;
            const kernel = self.guest_kernel_calls.slotAt(entry.kernel_slot);
            const matched_device_path = self.guestVfsMatchedDevicePath(path);
            return std.fmt.bufPrint(buffer, " vfs_ledger=[calls={d} found={d} not_found={d} matched_device_path={s} caller={s} during={s}!{s} thread={s} first_step={d}]", .{
                entry.calls,
                entry.found,
                entry.not_found,
                if (matched_device_path.len == 0) "<none>" else matched_device_path,
                self.describeGuestAddressOrUnnamed(entry.caller_rip, &caller_text),
                if (kernel) |slot| slot.module.moduleName() else "<none>",
                if (kernel) |slot| slot.export_name else "<none>",
                self.guestThreadLabel(entry.thread_slot),
                entry.first_step,
            }) catch "";
        }
        return "";
    }

    /// A report's name for a thread slot recorded as slot plus one.
    fn guestThreadLabel(self: *const ElfState, slot_plus_one: u8) []const u8 {
        if (slot_plus_one == 0) return "owner-context";
        const thread = &self.windows_guest_threads[slot_plus_one - 1];
        if (thread.status == .vacant) return "<exited>";
        return if (thread.name_len != 0) thread.nameText() else "<unnamed by the guest>";
    }

    /// Whether the PCM the title submits is silence.
    ///
    /// `AudioSystem::SubmitFrame(index, samples)` receives the title's frame
    /// already translated to a host pointer: six channels of 256 big-endian
    /// float samples. Every call is checked for the first few thousand, and
    /// one in sixteen after, which is enough to see a title start producing
    /// sound and cheap enough to leave on.
    fn noteAudioTitleFrame(self: *ElfState, samples: u64) void {
        self.audio_title_frames_seen +|= 1;
        const seen = self.audio_title_frames_seen;
        if (seen > 4096 and seen % 16 != 0) return;
        const bytes = self.guestMemoryConst(samples, 6 * 256 * 4) orelse return;
        self.audio_title_frames_checked +|= 1;
        for (bytes) |byte| {
            if (byte == 0) continue;
            self.audio_title_frames_nonzero +|= 1;
            if (self.audio_title_first_nonzero_step == 0) self.audio_title_first_nonzero_step = self.executed_steps;
            return;
        }
    }

    /// A Xenos register index's name, for the registers a title touches
    /// before it draws. Anything else is printed by index.
    /// The value Xenia's `GraphicsSystem::ReadRegister` returns for a
    /// register it answers without consulting the register file, or null.
    fn xeniaConstantRegisterRead(index: u16) ?u32 {
        return switch (index) {
            0x0F00 => 0x0810_0748, // RB_EDRAM_TIMING
            0x0F01 => 0x0000_200E, // RB_BC_CONTROL
            0x1951 => 0x0000_0001, // interrupt status: vblank
            0x1961 => 0x0500_02D0, // AVIVO_D1MODE_VIEWPORT_SIZE: 1280x720
            else => null,
        };
    }

    /// A type 3 opcode's name, from the values in `lib/gpu/pm4.zig`.
    fn pm4OpcodeLabel(opcode: u8) []const u8 {
        return switch (opcode) {
            0x10 => "NOP",
            0x21 => "REG_RMW",
            0x22 => "DRAW_INDX",
            0x23 => "VIZ_QUERY",
            0x25 => "SET_STATE",
            0x26 => "WAIT_FOR_IDLE",
            0x27 => "IM_LOAD",
            0x2B => "IM_LOAD_IMMEDIATE",
            0x2C => "IM_STORE",
            0x2D => "SET_CONSTANT",
            0x2E => "LOAD_CONSTANT_CONTEXT",
            0x2F => "LOAD_ALU_CONSTANT",
            0x34 => "DRAW_INDX_BIN",
            0x35 => "DRAW_INDX_2_BIN",
            0x36 => "DRAW_INDX_2",
            0x37 => "INDIRECT_BUFFER_PFD",
            0x3B => "INVALIDATE_STATE",
            0x3C => "WAIT_REG_MEM",
            0x3D => "MEM_WRITE",
            0x3E => "REG_TO_MEM",
            0x3F => "INDIRECT_BUFFER",
            0x44 => "COND_EXEC",
            0x45 => "COND_WRITE",
            0x46 => "EVENT_WRITE",
            0x48 => "ME_INIT",
            0x4A => "SET_SHADER_BASES",
            0x4B => "SET_BIN_BASE_OFFSET",
            0x4F => "MEM_WRITE_CNTR",
            0x50 => "SET_BIN_MASK",
            0x51 => "SET_BIN_SELECT",
            0x52 => "WAIT_REG_EQ",
            0x53 => "WAIT_REG_GTE",
            0x54 => "INTERRUPT",
            0x55 => "SET_CONSTANT2",
            0x56 => "SET_SHADER_CONSTANTS",
            0x58 => "EVENT_WRITE_SHD",
            0x59 => "EVENT_WRITE_CFL",
            0x5A => "EVENT_WRITE_EXT",
            0x5B => "EVENT_WRITE_ZPD",
            0x5C => "WAIT_UNTIL_READ",
            0x5D => "WAIT_IB_PFD_COMPLETE",
            0x5E => "CONTEXT_UPDATE",
            0x60 => "SET_BIN_MASK_LO",
            0x61 => "SET_BIN_MASK_HI",
            0x62 => "SET_BIN_SELECT_LO",
            0x63 => "SET_BIN_SELECT_HI",
            0x64 => "XE_SWAP",
            else => "unnamed",
        };
    }

    /// Entries into Xenia's type 3 opcode handlers, and into the
    /// indirect-buffer walk only a type 3 packet reaches.
    ///
    /// `ExecutePacketType3` is inlined into `ExecutePacket` in this build, so
    /// its own tracepoint reads zero while the handlers it dispatches to run.
    /// On 2026-09-13 ME_INIT=1 and ExecuteIndirectBuffer=5 with the
    /// dispatcher at 0, and the chain called the ring its wall.
    fn gpuType3HandlerEntries(self: *const ElfState) u64 {
        return self.guestMilestoneHitsNamed("_ZN2xe3gpu6vulkan22VulkanCommandProcessor26ExecutePacketType3_ME_INITEjj") +|
            self.guestMilestoneHitsNamed("_ZN2xe3gpu6vulkan22VulkanCommandProcessor34ExecutePacketType3_INDIRECT_BUFFEREjj") +|
            self.guestMilestoneHitsNamed("_ZN2xe3gpu6vulkan22VulkanCommandProcessor21ExecuteIndirectBufferEjj") +|
            self.guestMilestoneHitsNamed("_ZN2xe3gpu6vulkan22VulkanCommandProcessor31ExecutePacketType3_WAIT_REG_MEMEjj") +|
            self.guestMilestoneHitsNamed("_ZN2xe3gpu6vulkan22VulkanCommandProcessor28ExecutePacketType3_INTERRUPTEjj");
    }

    fn xenosRegisterName(index: u16) []const u8 {
        return switch (index) {
            0x01C0 => "CP_RB_BASE",
            0x01C1 => "CP_RB_CNTL",
            0x01C3 => "CP_RB_RPTR_ADDR",
            0x01C4 => "CP_RB_RPTR",
            0x01C5 => "CP_RB_WPTR",
            0x01C6 => "CP_RB_WPTR_DELAY",
            0x01CC => "CP_IB1_BASE",
            0x01CD => "CP_IB1_BUFSZ",
            0x01CE => "CP_IB2_BASE",
            0x01CF => "CP_IB2_BUFSZ",
            0x01DD => "SCRATCH_ADDR",
            0x01DC => "SCRATCH_UMSK",
            0x0F00 => "RB_EDRAM_TIMING",
            0x0F01 => "RB_BC_CONTROL",
            0x1844 => "AVIVO_D1GRPH_PRIMARY_SURFACE_ADDRESS",
            0x194C => "D1MODE_V_COUNTER",
            0x1951 => "D1MODE_INTERRUPT_STATUS",
            0x1961 => "AVIVO_D1MODE_VIEWPORT_SIZE",
            else => "",
        };
    }

    /// Every Xenos register the title read or wrote, with what it read back.
    pub fn reportGpuRegisterTraffic(self: *const ElfState) void {
        if (self.gpu_register_reads == 0 and self.gpu_register_writes == 0) {
            log.info("PE64 GPU REGISTER TRAFFIC: the title has not reached GraphicsSystem's register callbacks; nothing it did touched the GPU's registers", .{});
            return;
        }
        log.info("PE64 GPU REGISTER TRAFFIC: reads={d} writes={d} registers={d} overflow={d} read_values_captured={d}; captured at GraphicsSystem::ReadRegisterThunk/WriteRegisterThunk, with each read's value taken at its return", .{
            self.gpu_register_reads,
            self.gpu_register_writes,
            self.gpu_register_traffic_count,
            self.gpu_register_traffic_overflow,
            self.guest_return_captures_completed,
        });
        var order: [GPU_REGISTER_TRAFFIC_CAPACITY]usize = undefined;
        const count = self.gpu_register_traffic_count;
        for (0..count) |index| order[index] = index;
        // Busiest first; a poll is the row a reader needs.
        std.mem.sort(usize, order[0..count], self, struct {
            fn busier(state: *const ElfState, left: usize, right: usize) bool {
                const a = state.gpu_register_traffic[left];
                const b = state.gpu_register_traffic[right];
                return a.reads +| a.writes > b.reads +| b.writes;
            }
        }.busier);
        var polled_unchanging: ?usize = null;
        var constant_polled: ?usize = null;
        for (order[0..@min(count, 16)]) |index| {
            const entry = &self.gpu_register_traffic[index];
            log.info("PE64 GPU REGISTER TRAFFIC:   reg=0x{x:0>4} {s:<36} reads={d} writes={d} last_read=0x{x} read_value_changes={d} last_write=0x{x} first_step={d} last_step={d} last_thread={s}", .{
                entry.index,
                xenosRegisterName(entry.index),
                entry.reads,
                entry.writes,
                entry.last_read_value,
                entry.read_value_changes,
                entry.last_write_value,
                entry.first_step,
                entry.last_step,
                self.guestThreadLabel(entry.last_thread_slot),
            });
            if (entry.read_returns >= 1000 and entry.read_value_changes == 0) {
                if (xeniaConstantRegisterRead(entry.index) != null) {
                    if (constant_polled == null) constant_polled = index;
                } else if (polled_unchanging == null) {
                    polled_unchanging = index;
                }
            }
        }
        if (polled_unchanging) |index| {
            const entry = &self.gpu_register_traffic[index];
            log.info("PE64 GPU REGISTER TRAFFIC:   verdict: the title read reg 0x{x:0>4} {s} {d} times and it returned 0x{x} every time. A title reads one register that often only when it is waiting for it to change, so the writer of that register is the thing it is waiting on", .{
                entry.index,
                xenosRegisterName(entry.index),
                entry.read_returns,
                entry.last_read_value,
            });
        } else {
            log.info("PE64 GPU REGISTER TRAFFIC:   verdict: no register was polled a thousand times without changing", .{});
        }
        if (constant_polled) |index| {
            const entry = &self.gpu_register_traffic[index];
            log.info("PE64 GPU REGISTER TRAFFIC:   reg 0x{x:0>4} {s} was read {d} times and returned 0x{x} every time, and it cannot do otherwise: GraphicsSystem::ReadRegister answers it with the constant 0x{x} without consulting the register file, so no writer exists to wait on. Beside {d} vblank interrupt dispatch(es), it is the title's interrupt handler reading its cause once per interrupt, not a poll", .{
                entry.index,
                xenosRegisterName(entry.index),
                entry.read_returns,
                entry.last_read_value,
                xeniaConstantRegisterRead(entry.index).?,
                self.guestMilestoneStageHits("_ZN2xe3gpu14GraphicsSystem10MarkVblankEv"),
            });
        }
    }

    /// What each write-pointer update moved the ring over.
    pub fn reportGpuRing(self: *const ElfState) void {
        if (!self.gpu_ring_initialized) {
            log.info("PE64 GPU RING: the title has not called VdInitializeRingBuffer, so there is no ring to decode", .{});
            return;
        }
        const membase = self.xeniaVirtualMembase();
        const ring_dwords: u64 = if (self.gpu_ring_size_log2 < 29) (@as(u64, 1) << @intCast(self.gpu_ring_size_log2 + 3)) / 4 else 0;
        log.info("PE64 GPU RING: base=0x{x} size_log2={d} ({d} dwords) rptr_writeback=0x{x} write_pointer_updates={d} decoded_dwords={d} zero_dwords={d} type0_packets={d} type3_packets={d} alias_mismatches={d} unreadable_updates={d} membase=0x{x} indirect_buffers={d} indirect_unreadable={d} indirect_type3={d} draws={d} swaps={d}", .{
            self.gpu_ring_base,
            self.gpu_ring_size_log2,
            ring_dwords,
            self.gpu_ring_rptr_writeback,
            self.gpu_ring_updates,
            self.gpu_ring_dwords_decoded,
            self.gpu_ring_zero_dwords,
            self.gpu_ring_type0_packets,
            self.gpu_ring_type3_packets,
            self.gpu_ring_alias_mismatches,
            self.gpu_ring_unreadable_updates,
            membase orelse 0,
            self.gpu_indirect_buffers_seen,
            self.gpu_indirect_buffers_unreadable,
            self.gpu_indirect_type3_packets,
            self.gpu_ring_draw_packets +| self.gpu_indirect_draw_packets,
            self.gpu_ring_swap_packets +| self.gpu_indirect_swap_packets,
        });
        for (self.gpu_ring_windows[0..self.gpu_ring_window_count]) |*window| {
            var opcode_text: [256]u8 = undefined;
            var opcode_used: usize = 0;
            for (window.type3_opcodes[0..window.type3_opcode_count]) |opcode| {
                const piece = std.fmt.bufPrint(opcode_text[opcode_used..], "{s}0x{x:0>2}:{s}", .{ if (opcode_used == 0) "" else ",", opcode, pm4OpcodeLabel(opcode) }) catch break;
                opcode_used += piece.len;
            }
            var dword_text: [96]u8 = undefined;
            var dword_used: usize = 0;
            for (window.first_dwords[0..window.first_dword_count]) |dword| {
                const piece = std.fmt.bufPrint(dword_text[dword_used..], "{s}{x:0>8}", .{ if (dword_used == 0) "" else " ", dword }) catch break;
                dword_used += piece.len;
            }
            log.info("PE64 GPU RING:   step={d} write_index 0x{x}->0x{x} ({d} dwords, {d} decoded{s}) zero={d} markers={d} type0={d} type1={d} type2={d} type3={d} opcodes=[{s}] alias_checks={d} alias_mismatches={d} first=[{s}]", .{
                window.step,
                window.from_index,
                window.to_index,
                window.dwords,
                window.decoded,
                if (window.readable) "" else ", unreadable",
                window.zero_dwords,
                window.marker_dwords,
                window.type0,
                window.type1,
                window.type2,
                window.type3,
                opcode_text[0..opcode_used],
                window.alias_checks,
                window.alias_mismatches,
                dword_text[0..dword_used],
            });
        }
        for (self.gpu_indirect_buffers[0..self.gpu_indirect_buffer_count]) |*buffer| {
            var opcode_text: [256]u8 = undefined;
            var opcode_used: usize = 0;
            for (buffer.type3_opcodes[0..buffer.type3_opcode_count]) |opcode| {
                const piece = std.fmt.bufPrint(opcode_text[opcode_used..], "{s}0x{x:0>2}:{s}", .{ if (opcode_used == 0) "" else ",", opcode, pm4OpcodeLabel(opcode) }) catch break;
                opcode_used += piece.len;
            }
            var dword_text: [96]u8 = undefined;
            var dword_used: usize = 0;
            for (buffer.first_dwords[0..buffer.first_dword_count]) |dword| {
                const piece = std.fmt.bufPrint(dword_text[dword_used..], "{s}{x:0>8}", .{ if (dword_used == 0) "" else " ", dword }) catch break;
                dword_used += piece.len;
            }
            log.info("PE64 GPU RING:   indirect buffer step={d} address=0x{x:0>8} dwords={d} ({d} decoded{s}) zero={d} type0={d} type1={d} type3={d} draws={d} swaps={d} nested_indirect_buffers={d} opcodes=[{s}] first=[{s}]", .{
                buffer.step,
                buffer.from_index,
                buffer.dwords,
                buffer.decoded,
                if (buffer.readable or buffer.dwords == 0) "" else ", unreadable",
                buffer.zero_dwords,
                buffer.type0,
                buffer.type1,
                buffer.type3,
                buffer.draw_packets,
                buffer.swap_packets,
                buffer.indirect_buffers,
                opcode_text[0..opcode_used],
                dword_text[0..dword_used],
            });
        }
        const map_name = struct {
            const packet = "_ZN2xe3gpu6vulkan22VulkanCommandProcessor13ExecutePacketEv";
            const type0 = "_ZN2xe3gpu6vulkan22VulkanCommandProcessor18ExecutePacketType0Ej";
            const type1 = "_ZN2xe3gpu6vulkan22VulkanCommandProcessor18ExecutePacketType1Ej";
            const type3 = "_ZN2xe3gpu6vulkan22VulkanCommandProcessor18ExecutePacketType3Ej";
            const me_init = "_ZN2xe3gpu6vulkan22VulkanCommandProcessor26ExecutePacketType3_ME_INITEjj";
            const indirect = "_ZN2xe3gpu6vulkan22VulkanCommandProcessor34ExecutePacketType3_INDIRECT_BUFFEREjj";
            const walk = "_ZN2xe3gpu6vulkan22VulkanCommandProcessor21ExecuteIndirectBufferEjj";
            const wait = "_ZN2xe3gpu6vulkan22VulkanCommandProcessor31ExecutePacketType3_WAIT_REG_MEMEjj";
            const interrupt = "_ZN2xe3gpu6vulkan22VulkanCommandProcessor28ExecutePacketType3_INTERRUPTEjj";
        };
        log.info("PE64 GPU RING:   Xenia executed: ExecutePacket={d} Type0={d} Type1={d} Type3={d} ME_INIT={d} INDIRECT_BUFFER={d} ExecuteIndirectBuffer={d} WAIT_REG_MEM={d} INTERRUPT={d}", .{
            self.guestMilestoneHitsNamed(map_name.packet),
            self.guestMilestoneHitsNamed(map_name.type0),
            self.guestMilestoneHitsNamed(map_name.type1),
            self.guestMilestoneHitsNamed(map_name.type3),
            self.guestMilestoneHitsNamed(map_name.me_init),
            self.guestMilestoneHitsNamed(map_name.indirect),
            self.guestMilestoneHitsNamed(map_name.walk),
            self.guestMilestoneHitsNamed(map_name.wait),
            self.guestMilestoneHitsNamed(map_name.interrupt),
        });
        const handler_entries = self.gpuType3HandlerEntries();
        const dispatcher_entries = self.guestMilestoneHitsNamed(map_name.type3);
        const draws = self.gpu_ring_draw_packets +| self.gpu_indirect_draw_packets;
        const swaps = self.gpu_ring_swap_packets +| self.gpu_indirect_swap_packets;
        var verdict_buffer: [640]u8 = undefined;
        const verdict: []const u8 = if (self.gpu_ring_updates == 0)
            "the title initialised a ring and has not moved its write pointer"
        else if (membase == null)
            "Rosette could not find Xenia's physical view among the mapped views, so the ring was not decoded; the view table at start-up says why"
        else if (self.gpu_ring_alias_mismatches != 0)
            "Xenia's physical view of the ring and the title's virtual alias of the same pages disagree. The GPU thread reads a different page from the one the title writes, which is a defect in Rosette's file-mapping aliasing, not the title"
        else if (self.gpu_ring_dwords_decoded != 0 and self.gpu_ring_zero_dwords == self.gpu_ring_dwords_decoded)
            "every dword the write pointer covered is zero, through the physical view and the title's aliases alike. Xenia skips a zero header without calling an executor, so the ring advanced over memory that holds no commands: the title moved the pointer before writing, or wrote somewhere this base does not point"
        else if (self.gpu_ring_type3_packets != 0 and dispatcher_entries == 0 and handler_entries == 0)
            "the ring windows hold type 3 packets and neither Xenia's type 3 dispatcher nor any of its opcode handlers ran, so Xenia's reader and this decode disagree about where the window starts"
        else if (draws != 0 or swaps != 0)
            std.fmt.bufPrint(&verdict_buffer, "the title's command stream carries {d} draw packet(s) and {d} XE_SWAP packet(s); the ring is doing its job, and a missing picture is downstream of it", .{ draws, swaps }) catch "the title's command stream carries draw or swap packets"
        else if (handler_entries != 0 or dispatcher_entries != 0)
            std.fmt.bufPrint(&verdict_buffer, "Xenia executed the ring's type 3 packets (opcode handler entries={d}, ExecutePacketType3 row={d}: the dispatcher is inlined into ExecutePacket, so its own row reads zero and the handler rows are the witness). The {d} indirect buffer(s) decoded above carry no DRAW_INDX and no XE_SWAP: the title has initialised its device and set state and has not drawn or presented, so the next wall is the title's, not the ring's", .{ handler_entries, dispatcher_entries, self.gpu_indirect_buffers_seen }) catch "Xenia executed the ring's type 3 packets and no draw or swap has been submitted yet"
        else if (self.gpu_ring_type3_packets == 0 and self.gpu_ring_type0_packets != 0)
            "the ring carried register writes (type 0) and no type 3 command yet: the title is configuring the GPU and has not asked it to do anything"
        else
            "the ring windows decoded as shown; compare them with what Xenia executed above";
        log.info("PE64 GPU RING:   verdict: {s}", .{verdict});
    }

    /// Every path Xenia's VFS was asked to resolve, with who asked.
    pub fn reportGuestVfsResolves(self: *const ElfState) void {
        if (!self.guestMilestoneArmed("_ZN2xe3vfs17VirtualFileSystem11ResolvePathESt17basic_string_viewIcSt11char_traitsIcEE")) {
            log.info("PE64 GUEST VFS RESOLVES: VirtualFileSystem::ResolvePath is not named in this image, so path lookups are unobservable", .{});
            return;
        }
        log.info("PE64 GUEST VFS RESOLVES: file requests captured={d} unreadable={d} empty_name_faults={d}; each NtCreateFile/NtOpenFile object name is read at the export trampoline, so an empty resolve names the request that produced it", .{
            self.guest_file_requests_captured,
            self.guest_file_requests_unreadable,
            self.guest_vfs_empty_name_faults,
        });
        const summary = self.classifyGuestVfsResolves();
        log.info("PE64 GUEST VFS RESOLVES: calls={d} distinct_paths={d} not_found={d} bare_module_calls={d} bare_module_not_found={d} bare_module_paths_reconciled={d}/{d} unmatched_bare_module_not_found={d} empty_path_not_found={d} device_path_not_found={d} unreadable_arguments={d} overflow={d}; a bare-module miss is expected when Xenia probes a name before matching its loaded module, while device_path_not_found is the real missing-device count", .{
            self.guest_vfs_resolve_calls,
            self.guest_vfs_resolve_count,
            self.guest_vfs_resolve_not_found,
            summary.bare_module_calls,
            summary.bare_module_not_found,
            summary.bare_module_paths_reconciled,
            summary.bare_module_paths,
            summary.bare_module_unmatched_not_found,
            summary.empty_path_not_found,
            summary.device_path_not_found,
            self.guest_vfs_resolve_unreadable,
            self.guest_vfs_resolve_overflow,
        });
        if (summary.device_path_not_found == 0 and summary.bare_module_unmatched_not_found == 0) {
            log.info("PE64 GUEST VFS ROUTING: verified all observed device-prefixed paths resolved; bare-module probes reconciled={d}/{d}, unmatched_bare_module_not_found=0. Repeated bare-name warnings are module-name probes, not missing mounted devices", .{
                summary.bare_module_paths_reconciled,
                summary.bare_module_paths,
            });
        }
        var order: [GUEST_VFS_RESOLVE_CAPACITY]usize = undefined;
        const count = self.guest_vfs_resolve_count;
        for (0..count) |index| order[index] = index;
        std.mem.sort(usize, order[0..count], self, struct {
            fn busier(state: *const ElfState, left: usize, right: usize) bool {
                return state.guest_vfs_resolves[left].calls > state.guest_vfs_resolves[right].calls;
            }
        }.busier);
        for (order[0..@min(count, 16)]) |index| {
            const entry = &self.guest_vfs_resolves[index];
            const path = entry.pathText();
            const bare_module_name = guestVfsPathIsBareModuleName(path);
            const matched_device_path = if (bare_module_name) self.guestVfsMatchedDevicePath(path) else "";
            const kind: []const u8 = if (path.len == 0)
                "empty path"
            else if (bare_module_name)
                "bare name: no device prefix, so a module lookup continues by name"
            else
                "device path";
            const classification: []const u8 = if (path.len == 0)
                "empty-path-probe"
            else if (matched_device_path.len != 0)
                "expected-module-name-probe"
            else if (bare_module_name)
                "unmatched-module-name-probe"
            else
                "device-path-resolution";
            var caller_text: [guest_symbol_text_bytes]u8 = undefined;
            const kernel = self.guest_kernel_calls.slotAt(entry.kernel_slot);
            log.info("PE64 GUEST VFS RESOLVES:   path='{s}'{s} calls={d} found={d} not_found={d} matched_device_path={s} classification={s} caller={s} during={s}!{s} thread={s} first_step={d} kind={s}", .{
                path,
                if (entry.truncated) "..." else "",
                entry.calls,
                entry.found,
                entry.not_found,
                if (matched_device_path.len == 0) "<none>" else matched_device_path,
                classification,
                self.describeGuestAddressOrUnnamed(entry.caller_rip, &caller_text),
                if (kernel) |slot| slot.module.moduleName() else "<none>",
                if (kernel) |slot| slot.export_name else "<none>",
                self.guestThreadLabel(entry.thread_slot),
                entry.first_step,
                kind,
            });
        }
    }

    /// Hold a WinMM writer to its stream's real-time rate.
    ///
    /// Returns the milliseconds the writer must wait before this buffer is
    /// accepted, or zero to accept it now. `waveOutWrite` completes a buffer
    /// the moment it is accepted, because SDL's worker waits for WOM_DONE
    /// before it writes again; with nothing else holding it back, SDL's audio
    /// thread wrote 3.4 million buffers in the 2026-09-13 run, 6.7 GB of
    /// them dropped by the device, and held a tenth of the interpreter the
    /// title needed. A real device completes a buffer when it has played it.
    /// This lets the accepted audio run at most a device queue's depth ahead
    /// of the host clock, and parks the writer - retrying the same call - for
    /// the rest. A writer slower than real time never waits.
    pub fn paceWindowsWaveOutWrite(self: *ElfState, device: *WindowsWaveOutDevice, length: u32) u64 {
        if (self.windows_active_guest_thread_slot == null or length == 0) return 0;
        const bytes_per_second = @as(u64, device.sample_rate) * @as(u64, device.block_align);
        if (bytes_per_second == 0) return 0;
        const now = monotonicNanoseconds();
        if (now == 0) return 0;
        if (device.paced_until_ns < now) device.paced_until_ns = now;
        const lead = device.paced_until_ns - now;
        if (lead > WINDOWS_WAVE_OUT_PACING_LEAD_NS) {
            const excess = lead - WINDOWS_WAVE_OUT_PACING_LEAD_NS;
            const wait_ms = @max(@as(u64, 1), (excess + std.time.ns_per_ms - 1) / std.time.ns_per_ms);
            device.pacing_waits +|= 1;
            self.windows_audio_pacing_waits +|= 1;
            self.windows_audio_pacing_wait_ms +|= wait_ms;
            return wait_ms;
        }
        const duration = (@as(u128, length) * std.time.ns_per_s) / bytes_per_second;
        device.paced_until_ns +|= @intCast(@min(duration, std.math.maxInt(u64)));
        return 0;
    }

    pub fn windowsRegistryOpen(self: *ElfState, parent: u64, subkey: []const u8, create: bool) windows_registry_model.OpenResult {
        return self.windows_registry.openKey(self.allocator, parent, subkey, create);
    }

    pub fn windowsRegistryClose(self: *ElfState, handle: u64) u32 {
        return self.windows_registry.closeKey(handle);
    }

    pub fn windowsRegistryIsHandle(self: *const ElfState, handle: u64) bool {
        return self.windows_registry.isKnownHandle(handle);
    }

    pub fn windowsRegistrySet(self: *ElfState, handle: u64, name: []const u8, value_type: u32, data: []const u8) u32 {
        return self.windows_registry.setValue(self.allocator, handle, name, value_type, data);
    }

    pub fn windowsRegistryQuery(self: *ElfState, handle: u64, name: []const u8) windows_registry_model.QueryResult {
        return self.windows_registry.queryValue(handle, name);
    }

    pub fn windowsRegistryGet(self: *ElfState, handle: u64, subkey: []const u8, name: []const u8) windows_registry_model.QueryResult {
        return self.windows_registry.getValue(handle, subkey, name);
    }

    pub fn windowsRegistryDeleteValue(self: *ElfState, handle: u64, name: []const u8) u32 {
        return self.windows_registry.deleteValue(self.allocator, handle, name);
    }

    pub fn windowsRegistryFit(value_size: usize, has_buffer: bool, has_size: bool, capacity: u32) windows_registry_model.Fit {
        return windows_registry_model.fitValue(value_size, has_buffer, has_size, capacity);
    }

    pub fn windowsRegistryTypeAllowed(value_type: u32, flags: u32) bool {
        return windows_registry_model.typeAllowed(value_type, flags);
    }

    pub fn reportWindowsRegistry(self: *const ElfState) void {
        const registry = &self.windows_registry;
        if (registry.opens == 0 and registry.queries == 0 and registry.values_written == 0) return;
        log.info("PE64 GUEST REGISTRY: keys={d} values={d} value_bytes={d} opens={d} opens_missing={d} keys_created={d} values_written={d} queries={d} queries_found={d} capacity_refusals={d} invalid_handles={d}; the registry the guest owns, rooted in this run: a key it did not create reads ERROR_FILE_NOT_FOUND, as on a Windows machine without it", .{
            registry.keyCount(),
            registry.valueCount(),
            registry.value_bytes,
            registry.opens,
            registry.opens_missing,
            registry.keys_created,
            registry.values_written,
            registry.queries,
            registry.queries_found,
            registry.capacity_refusals,
            registry.invalid_handles,
        });
    }

    /// Offer one image symbol to the kernel-call census.
    ///
    /// Called once per symbol at load time, from whichever loader holds the
    /// symbol table. Most symbols are not shims and are rejected in a few
    /// instructions; the ones that are keep a borrowed slice of the image's
    /// string table, which outlives this state in every caller.
    pub fn armGuestKernelShim(self: *ElfState, mangled: []const u8, address: u64) void {
        self.guest_kernel_symbols_offered +|= 1;
        _ = self.guest_kernel_calls.arm(self.allocator, mangled, address);
    }

    /// Report what the arming pass found, once, so a run whose image has no
    /// shims says so rather than printing an empty census later.
    pub fn reportGuestKernelShimArming(self: *const ElfState) void {
        if (self.guest_kernel_symbols_offered == 0) {
            log.info("PE64 GUEST KERNEL CALLS: not armed; nothing offered this run a symbol table, so every export reads zero for a reason that has nothing to do with the title", .{});
            return;
        }
        if (self.guest_kernel_calls.armed == 0) {
            log.info("PE64 GUEST KERNEL CALLS: 0 export shims armed from {d} symbol(s); this image does not carry Xenia's `<Export>_entry` functions, so the title's kernel traffic cannot be observed", .{
                self.guest_kernel_symbols_offered,
            });
            return;
        }
        log.info("PE64 GUEST KERNEL CALLS: armed {d} registered kernel export trampoline(s) and {d} `_entry` forwarder(s) from {d} image symbol(s) across xboxkrnl/xam/xbdm. The trampoline is what a title's import resolves to and nothing but the guest reaches it, so entry into one is the only event in the program that proves the title acted{s}", .{
            self.guest_kernel_calls.armed_trampolines,
            self.guest_kernel_calls.armed - self.guest_kernel_calls.armed_trampolines,
            self.guest_kernel_symbols_offered,
            if (self.guest_kernel_calls.overflowed != 0) " (SOME DID NOT FIT: the census is incomplete)" else "",
        });
        if (self.guest_kernel_calls.overflowed != 0) {
            log.warn("PE64 GUEST KERNEL CALLS: {d} shim(s) did not fit the census table; raise kernel_call_census.slot_count", .{
                self.guest_kernel_calls.overflowed,
            });
        }
    }

    /// Record that the guest entered a kernel export shim.
    ///
    /// On the interpreter's call path, next to `noteGuestMilestoneEntry`. The
    /// census rejects an address outside the armed range in two comparisons,
    /// which is what almost every call is.
    fn noteGuestKernelCall(self: *ElfState, target: u64) void {
        self.noteGuestKernelEntry(target, false);
    }

    /// The same, for a tail jump. Kept apart in the count because which
    /// instruction a translator reaches its handler with is a property of the
    /// translator; a census that could not tell them apart would read zero
    /// for a title that was calling constantly.
    fn noteGuestKernelTailJump(self: *ElfState, target: u64) void {
        self.noteGuestKernelEntry(target, true);
    }

    fn noteGuestKernelEntry(self: *ElfState, target: u64, via_jump: bool) void {
        const accounting_step = self.totalInterpretedSteps();
        const slot_index = self.guest_kernel_calls.note(target, accounting_step);
        if (slot_index == 0) return;
        if (via_jump) self.guest_kernel_calls.tail_jump_entries +|= 1;
        if (self.guest_kernel_calls.slotAt(slot_index)) |slot| {
            if (slot.kind == .trampoline and isGuestFileRequestExport(slot.export_name)) self.captureGuestFileRequest(slot_index);
        }
        if (self.windows_active_guest_thread_slot) |slot| {
            const thread = &self.windows_guest_threads[slot];
            thread.last_kernel_slot = slot_index;
            thread.last_kernel_step = accounting_step;
            thread.kernel_calls +|= 1;
        }
    }

    /// The kernel exports whose object name an empty `ResolvePath` can come from.
    fn isGuestFileRequestExport(export_name: []const u8) bool {
        return std.mem.eql(u8, export_name, "NtCreateFile") or std.mem.eql(u8, export_name, "NtOpenFile");
    }

    fn activeGuestFileRequest(self: *ElfState) *GuestFileRequest {
        if (self.windows_active_guest_thread_slot) |slot| return &self.windows_guest_threads[slot].file_request;
        return &self.owner_file_request;
    }

    /// Guest memory the way Xenia's `TranslateVirtual` reaches it: membase
    /// plus the address, and one host page further for the 0xE0000000 heap.
    fn xeniaGuestBytes(self: *const ElfState, membase: u64, guest_address: u32, count: u64) ?[]const u8 {
        const adjust: u64 = if (guest_address >= 0xE000_0000) 0x1000 else 0;
        return self.guestMemoryConst(membase + guest_address + adjust, count);
    }

    fn readHostU64(self: *const ElfState, address: u64) ?u64 {
        const bytes = self.guestMemoryConst(address, 8) orelse return null;
        return std.mem.readInt(u64, bytes[0..8], .little);
    }

    /// Read `NtCreateFile`/`NtOpenFile`'s object name from the PPC context.
    ///
    /// Both take `(handle_out, desired_access, object_attributes, ...)` in
    /// r3, r4 and r5. `X_OBJECT_ATTRIBUTES` is `{root_directory, name_ptr,
    /// attributes}` and `X_ANSI_STRING` is `{length, maximum_length,
    /// pointer}`, all big-endian. The trampoline's only argument is the
    /// context, in rcx at the moment the guest reaches it.
    fn captureGuestFileRequest(self: *ElfState, kernel_slot: u32) void {
        const context = self.regs.rcx;
        const request = self.activeGuestFileRequest();
        request.* = .{ .captured = true, .step = self.executed_steps, .kernel_slot = kernel_slot, .context = context };
        self.guest_file_requests_captured +|= 1;
        self.captureGuestFileRequestFields(request, context) catch {
            request.unreadable = true;
            self.guest_file_requests_unreadable +|= 1;
        };
    }

    fn captureGuestFileRequestFields(self: *const ElfState, request: *GuestFileRequest, context: u64) error{Unreadable}!void {
        const membase = self.readHostU64(context + PPC_CONTEXT_VIRTUAL_MEMBASE) orelse return error.Unreadable;
        request.link_register = @truncate(self.readHostU64(context + PPC_CONTEXT_LINK_REGISTER) orelse return error.Unreadable);
        request.desired_access = @truncate(self.readHostU64(context + ppcContextGpr(4)) orelse return error.Unreadable);
        request.object_attributes = @truncate(self.readHostU64(context + ppcContextGpr(5)) orelse return error.Unreadable);
        if (request.object_attributes == 0) return;
        const attributes = self.xeniaGuestBytes(membase, request.object_attributes, 12) orelse return error.Unreadable;
        request.depth = 1;
        request.root_directory = std.mem.readInt(u32, attributes[0..4], .big);
        request.name_pointer = std.mem.readInt(u32, attributes[4..8], .big);
        if (request.name_pointer == 0) return;
        const name = self.xeniaGuestBytes(membase, request.name_pointer, 8) orelse return error.Unreadable;
        request.depth = 2;
        request.name_length = std.mem.readInt(u16, name[0..2], .big);
        request.name_maximum = std.mem.readInt(u16, name[2..4], .big);
        request.name_buffer = std.mem.readInt(u32, name[4..8], .big);
        if (request.name_buffer == 0) return;
        const buffer = self.xeniaGuestBytes(membase, request.name_buffer, GUEST_FILE_REQUEST_PREVIEW_BYTES) orelse
            self.xeniaGuestBytes(membase, request.name_buffer, 1) orelse return error.Unreadable;
        request.depth = 3;
        var used: usize = 0;
        for (buffer) |byte| {
            if (byte == 0) break;
            request.preview[used] = if (byte >= 0x20 and byte < 0x7F and byte != '"') byte else '?';
            used += 1;
        }
        request.preview_len = @intCast(used);
    }

    fn classifyGuestFileRequestName(request: *const GuestFileRequest) GuestFileNameShape {
        if (!request.captured) return .unattributed;
        if (request.unreadable) return .unreadable;
        if (request.object_attributes == 0) return .no_object_attributes;
        if (request.name_pointer == 0) return .no_name;
        if (request.name_length == 0) return if (request.preview_len != 0) .zero_length_with_text else .zero_length_empty;
        // A non-zero length over bytes Rosette could not show still makes a
        // non-empty std::string in Xenia.
        if (request.preview_len == 0) return .named;
        for (request.previewText()[0..@min(request.preview_len, request.name_length)]) |byte| {
            if (!std.ascii.isWhitespace(byte)) return .named;
        }
        return .blank_text;
    }

    /// `ResolvePath` failed on an empty path: stop, citing the request behind it.
    fn faultGuestVfsEmptyName(self: *ElfState, resolve: *const GuestVfsResolve) void {
        self.guest_vfs_empty_name_faults +|= 1;
        const occurrence = self.guest_vfs_empty_name_faults;
        if (occurrence == 1) self.windows_fatal_point_events +|= 1;
        if (comptime !@import("builtin").is_test) {
            if (shouldReportWindowsPointOccurrence(occurrence)) self.reportGuestVfsEmptyName(resolve, occurrence);
        }
        self.terminateForWindowsFatalPoint("vfs-empty-object-name");
    }

    fn reportGuestVfsEmptyName(self: *ElfState, resolve: *const GuestVfsResolve, occurrence: u64) void {
        const request = self.activeGuestFileRequest();
        const shape = classifyGuestFileRequestName(request);
        const kernel = self.guest_kernel_calls.slotAt(request.kernel_slot);
        var caller_text: [guest_symbol_text_bytes]u8 = undefined;
        const slot_plus_one: u8 = if (self.windows_active_guest_thread_slot) |slot| @intCast(@min(slot + 1, 255)) else 0;
        log.err("PE64 FATAL POINT: guest-condition label=vfs-empty-object-name owner={s} occurrence={d} step={d} thread={s} resolve_caller={s} request={s}!{s} request_step={d} steps_since_request={d} title_lr=0x{x:0>8} desired_access=0x{x} object_attributes=0x{x:0>8} root_directory=0x{x} object_name=0x{x:0>8} length={d} maximum={d} buffer=0x{x:0>8} preview=\"{s}\" capture_depth={d} shape={s}; {s}", .{
            shape.owner(),
            occurrence,
            self.executed_steps,
            self.guestThreadLabel(slot_plus_one),
            self.describeGuestAddressOrUnnamed(resolve.caller_rip, &caller_text),
            if (kernel) |entry| entry.module.moduleName() else "<none>",
            if (kernel) |entry| entry.export_name else "<none>",
            request.step,
            self.executed_steps -| request.step,
            request.link_register,
            request.desired_access,
            request.object_attributes,
            request.root_directory,
            request.name_pointer,
            request.name_length,
            request.name_maximum,
            request.name_buffer,
            request.previewText(),
            request.depth,
            @tagName(shape),
            shape.meaning(),
        });
    }

    /// How many times the guest entered a milestone, by its table row.
    pub fn guestMilestoneHits(self: *const ElfState, index: usize) u64 {
        if (index >= self.guest_milestone_hits.len) return 0;
        return self.guest_milestone_hits[index];
    }

    /// The same, by mangled name, for a caller that knows what it wants
    /// rather than where it sits.
    pub fn guestMilestoneHitsNamed(self: *const ElfState, mangled: []const u8) u64 {
        const index = xenia_guest_milestone_map.indexOf(mangled) orelse return 0;
        return self.guest_milestone_hits[index];
    }

    /// The armed milestone entry addresses, in table order, for the image
    /// reader to scan the executable sections against. Zero where the image
    /// did not name the symbol; the census skips those.
    pub fn guestMilestoneAddresses(self: *const ElfState) []const u64 {
        return self.guest_milestone_addresses[0..];
    }

    /// Record the call-site census the image reader produced.
    ///
    /// Supplied by the PE route rather than computed here: the count needs
    /// the image's executable sections and their file offsets, which are the
    /// loader's business and not the interpreter's.
    pub fn noteGuestMilestoneCallSites(self: *ElfState, counts: []const u32) void {
        self.guest_milestone_call_sites_counted = true;
        for (counts, 0..) |sites, index| {
            if (index >= self.guest_milestone_call_sites.len) break;
            self.guest_milestone_call_sites[index] = sites;
        }
    }

    /// Record how many stored pointers to each milestone the image contains.
    ///
    /// Supplied alongside the call-site census and read with it: the two
    /// together decide whether an armed address is reachable at all.
    pub fn noteGuestMilestoneDataReferences(self: *ElfState, counts: []const u32) void {
        for (counts, 0..) |refs, index| {
            if (index >= self.guest_milestone_data_refs.len) break;
            self.guest_milestone_data_refs[index] = refs;
        }
    }

    /// How a milestone's entry can be reached in this image.
    pub const MilestoneReach = enum {
        /// The image does not name the symbol.
        unresolved,
        /// At least one direct `call`/`jmp` branches to it.
        direct,
        /// No direct branch, but its address is stored somewhere: a vtable
        /// slot, a dispatch table, a callback registration. A virtual
        /// function looks like this, and a zero entry count on one is real
        /// evidence about the guest.
        indirect,
        /// Neither branched to nor stored, and never entered. The compiler
        /// inlined the body into its callers and left the out-of-line copy
        /// behind; the address cannot be reached and its zero says nothing.
        unreachable_inlined,
        /// The census did not run on this route, so nothing can be said.
        uncounted,

        pub fn label(self: MilestoneReach) []const u8 {
            return switch (self) {
                .unresolved => "unresolved",
                .direct => "direct",
                .indirect => "indirect",
                .unreachable_inlined => "inlined-away",
                .uncounted => "uncounted",
            };
        }
    };

    /// Why a milestone-backed stage cannot be observed, in the words that
    /// send a reader to the right place. The two causes are unrelated: an
    /// image that does not carry the symbol, and an image whose optimizer
    /// left the symbol unreachable.
    pub fn guestMilestoneUnobservableReason(self: *const ElfState, mangled: []const u8) []const u8 {
        return switch (self.guestMilestoneReach(mangled)) {
            .unresolved => "this image does not name the symbol",
            .unreachable_inlined => "the symbol's body was inlined into its callers and nothing branches to the copy left behind, so it can never be entered",
            .uncounted => "the call-site census did not run on this route",
            .direct, .indirect => "observable",
        };
    }

    pub fn guestMilestoneReach(self: *const ElfState, mangled: []const u8) MilestoneReach {
        const index = xenia_guest_milestone_map.indexOf(mangled) orelse return .unresolved;
        if (self.guest_milestone_addresses[index] == 0) return .unresolved;
        if (!self.guest_milestone_call_sites_counted) return .uncounted;
        if (self.guest_milestone_call_sites[index] != 0) return .direct;
        if (self.guest_milestone_data_refs[index] != 0) return .indirect;
        // Entered at least once settles it whatever the scans found: the
        // guest reached an address the image analysis called unreachable, so
        // the analysis is what is wrong.
        if (self.guest_milestone_hits[index] != 0) return .indirect;
        return .unreachable_inlined;
    }

    /// Whether an armed milestone cannot be reached at all in this image, so
    /// a zero entry count measures the build and not the run.
    ///
    /// The strict reading of `.unreachable_inlined`: no direct branch, no
    /// stored pointer, never entered. Anything weaker was the 2026-09-12
    /// mistake - three virtual functions have no call site either, and
    /// calling those inlined threw away three real findings.
    pub fn guestMilestoneInlinedAway(self: *const ElfState, mangled: []const u8) bool {
        return self.guestMilestoneReach(mangled) == .unreachable_inlined;
    }

    /// The count a chain stage should read for a milestone.
    ///
    /// `@max` of the row's own entries and its inline proxy's, never the sum:
    /// when the body was *not* inlined the proxy is called by it, so adding
    /// them would double every vblank. When it was, the row reads zero and
    /// the proxy carries the whole count.
    pub fn guestMilestoneStageHits(self: *const ElfState, mangled: []const u8) u64 {
        const own = self.guestMilestoneHitsNamed(mangled);
        const proxy = xenia_guest_milestone_map.inlineProxyOf(mangled);
        if (proxy.len == 0) return own;
        return @max(own, self.guestMilestoneHitsNamed(proxy));
    }

    /// Whether this run can observe a stage at all.
    ///
    /// Armed is not enough. A symbol the optimizer inlined away can never be
    /// entered, so reporting its zero as an unmet stage - and letting it
    /// become the wall the whole chain is read against - states a fact about
    /// the guest that no evidence supports. Such a row is observable only
    /// through its proxy, if it declared one.
    pub fn guestMilestoneStageObservable(self: *const ElfState, mangled: []const u8) bool {
        const proxy = xenia_guest_milestone_map.inlineProxyOf(mangled);
        if (proxy.len != 0 and self.guestMilestoneArmed(proxy) and !self.guestMilestoneInlinedAway(proxy)) return true;
        return self.guestMilestoneArmed(mangled) and !self.guestMilestoneInlinedAway(mangled);
    }

    /// Whether the image contained the symbol at all. A milestone that could
    /// not be armed reads as zero hits, and zero hits from an unarmed row
    /// says nothing about the guest.
    pub fn guestMilestoneArmed(self: *const ElfState, mangled: []const u8) bool {
        const index = xenia_guest_milestone_map.indexOf(mangled) orelse return false;
        return self.guest_milestone_addresses[index] != 0;
    }

    /// The bare symbol name covering an address, written into `buffer`.
    ///
    /// Separate from `describeGuestAddress` because the frontier classifier
    /// matches on the name alone: appending `+0x1f0` first and stripping it
    /// again would be a round trip through text for no reason.
    pub fn guestSymbolAt(self: *const ElfState, address: u64, buffer: []u8) ?GuestSymbol {
        const resolver = self.guest_symbol_resolver orelse return null;
        return resolver.resolve(resolver.context, address, buffer);
    }

    /// `name+0xoffset` for an address, or an empty slice when the image does
    /// not name it. An empty return is a fact about the image, never a
    /// failure: a caller prints `symbol=<unnamed>` and moves on.
    pub fn describeGuestAddress(self: *const ElfState, address: u64, buffer: []u8) []const u8 {
        var name_storage: [guest_symbol_text_bytes]u8 = undefined;
        if (self.guestSymbolAt(address, &name_storage)) |symbol| {
            return std.fmt.bufPrint(buffer, "{s}+0x{x}", .{ symbol.name, symbol.offset }) catch symbol.name[0..@min(symbol.name.len, buffer.len)];
        }
        // No symbol is not no answer. An address outside the image is still
        // somewhere: a thunk Rosette laid down, a block the guest allocated
        // executable, its heap, a stack. Saying which turns a bare hex number
        // into a fact about who owns the code running there.
        return self.guest_regions.describe(address, buffer);
    }

    /// The same text, but never empty: unnamed addresses render as a marker a
    /// log reader can grep for.
    pub fn describeGuestAddressOrUnnamed(self: *const ElfState, address: u64, buffer: []u8) []const u8 {
        const described = self.describeGuestAddress(address, buffer);
        // `<unmapped>` and `<unnamed>` are different findings. The first says
        // the address belongs to nothing Rosette has recorded, which for a
        // rip is a control-flow escape; the second used to be printed for
        // both, and hid the distinction.
        return if (described.len == 0) "<unmapped>" else described;
    }

    /// What the guest is doing at an address, from its symbol.
    pub fn classifyGuestFrontier(self: *const ElfState, address: u64) xenia_guest_frontier_map.Classification {
        var name_storage: [guest_symbol_text_bytes]u8 = undefined;
        const symbol = self.guestSymbolAt(address, &name_storage) orelse
            return xenia_guest_frontier_map.classify("");
        return xenia_guest_frontier_map.classify(symbol.name);
    }

    /// Whether the current guest frontier sits in work that finishes on its
    /// own given more steps.
    ///
    /// This is the suppression gate for every "nothing downstream happened"
    /// predictor in this file. A font atlas being rasterized, a shader being
    /// translated, or a XEX being decrypted all look identical to a stall
    /// from a downstream counter, and accusing the downstream subsystem for
    /// them sends a reader to the wrong place - which is exactly what the
    /// 2026-09-11 `present-chain-no-presents` verdict did.
    pub fn guestFrontierIsBoundedComputation(self: *const ElfState) bool {
        return self.classifyGuestFrontier(self.regs.rip).isBoundedComputation();
    }

    /// Add the current frontier to the workload histogram. Called only at the
    /// graphics checkpoints, so the cost is per-checkpoint and not per-step.
    pub fn sampleGuestFrontier(self: *ElfState) void {
        const classification = self.classifyGuestFrontier(self.regs.rip);
        self.guest_frontier_samples +|= 1;
        self.guest_frontier_workload_samples[@intFromEnum(classification.workload)] +|= 1;
    }

    fn frontierSamplesFor(self: *const ElfState, workload: xenia_guest_frontier_map.Workload) u64 {
        return self.guest_frontier_workload_samples[@intFromEnum(workload)];
    }

    /// Samples spent anywhere in the ImGui font atlas build.
    fn fontAtlasFrontierSamples(self: *const ElfState) u64 {
        return self.frontierSamplesFor(.font_rasterization) +|
            self.frontierSamplesFor(.font_atlas_packing) +|
            self.frontierSamplesFor(.font_atlas_build);
    }

    /// One line describing where the guest is and what it is doing there.
    /// Written into `buffer`; always non-empty.
    pub fn describeGuestFrontier(self: *const ElfState, address: u64, buffer: []u8) []const u8 {
        var symbol_storage: [guest_symbol_text_bytes]u8 = undefined;
        const symbol = self.describeGuestAddressOrUnnamed(address, &symbol_storage);
        const classification = self.classifyGuestFrontier(address);
        return std.fmt.bufPrint(buffer, "symbol={s} workload={s} owner={s} bounded={}", .{
            symbol,
            classification.workload.label(),
            classification.owner.label(),
            classification.isBoundedComputation(),
        }) catch symbol[0..@min(symbol.len, buffer.len)];
    }

    /// Ask the Vulkan forwarder to describe the presentation chain, if this
    /// state has one. A PE run reaches the forwarder through the graphics
    /// hooks; a state with no forwarder simply has nothing to say.
    fn notePresentChainFailurePoint(self: *ElfState, steps: u64) void {
        const graphics = &self.windows_graphics;
        if (!graphics.swapchain_ready) {
            self.windows_present_no_work_checkpoints = 0;
            self.windows_present_no_submit_checkpoints = 0;
            return;
        }

        const guest_frame_never_started = graphics.image_acquires == 0 and
            graphics.command_calls == 0 and graphics.queue_submits == 0 and graphics.presents == 0;
        // A frontier inside a computation that terminates is a horizon, not a
        // stall. Counting a checkpoint there would eventually accuse the
        // presentation chain for a font atlas, a shader translation, or a XEX
        // decryption that was going to finish - which is what the 2026-09-11
        // run's `guest_never_reached_first_frame_frontier` verdict did while
        // the UI thread was rasterizing glyphs. The checkpoint is held rather
        // than reset: if the guest leaves the bounded work and still produces
        // nothing, the accusation resumes from where it was.
        const frontier = self.classifyGuestFrontier(self.regs.rip);
        if (guest_frame_never_started and !frontier.isBoundedComputation()) {
            self.windows_present_no_work_checkpoints +|= 1;
        } else if (!guest_frame_never_started) {
            self.windows_present_no_work_checkpoints = 0;
        } else if (!self.windows_present_bounded_work_reported) {
            self.windows_present_bounded_work_reported = true;
            log.info("PE64 present chain deferred: the guest frontier is inside {s} ({s}), which finishes on its own; no-presents cannot be a verdict until it does. steps={d} rip=0x{x} owner={s}", .{
                frontier.workload.label(),
                frontier.matched,
                steps,
                self.regs.rip,
                frontier.owner.label(),
            });
        }
        if (graphics.queue_submits != 0 and graphics.presents == 0) {
            self.windows_present_no_submit_checkpoints +|= 1;
        } else {
            self.windows_present_no_submit_checkpoints = 0;
        }

        if (self.windows_present_no_work_checkpoints >= 3 and !self.windows_present_no_work_reported) {
            self.windows_present_no_work_reported = true;
            self.windows_fatal_point_events +|= 1;
            var frontier_text: [320]u8 = undefined;
            log.err("PE64 FATAL POINT: present-chain-no-presents verdict=no_presents stage={s} checkpoints={d} steps={d} rip=0x{x} {s} last_op={s} active_thread=0x{x} vk_calls={d} native_vk_calls={d} swapchain_ready={} acquires={d} command_calls={d} submits={d} presents={d} last_call={s} last_failure={s} diagnosis=guest_never_reached_first_frame_frontier", .{
                @tagName(graphics.phase),
                self.windows_present_no_work_checkpoints,
                steps,
                self.regs.rip,
                self.describeGuestFrontier(self.regs.rip, &frontier_text),
                @tagName(self.last_decoded_op),
                self.active_guest_thread,
                graphics.vulkan_calls,
                graphics.native_vulkan_calls,
                graphics.swapchain_ready,
                graphics.image_acquires,
                graphics.command_calls,
                graphics.queue_submits,
                graphics.presents,
                std.mem.sliceTo(&graphics.last_call, 0),
                std.mem.sliceTo(&graphics.last_failure, 0),
            });
            self.terminateForWindowsFatalPoint("present-chain-no-presents");
        }
        if (self.windows_present_no_submit_checkpoints >= 3 and !self.windows_present_no_submit_reported) {
            self.windows_present_no_submit_reported = true;
            self.windows_fatal_point_events +|= 1;
            log.err("PE64 FATAL POINT: present-chain-no-present-after-submit verdict=no_presents stage={s} checkpoints={d} steps={d} rip=0x{x} last_op={s} active_thread=0x{x} acquires={d} command_calls={d} submits={d} presents={d} last_call={s} last_failure={s} diagnosis=guest_submitted_work_but_no_present_returned", .{
                @tagName(graphics.phase),
                self.windows_present_no_submit_checkpoints,
                steps,
                self.regs.rip,
                @tagName(self.last_decoded_op),
                self.active_guest_thread,
                graphics.image_acquires,
                graphics.command_calls,
                graphics.queue_submits,
                graphics.presents,
                std.mem.sliceTo(&graphics.last_call, 0),
                std.mem.sliceTo(&graphics.last_failure, 0),
            });
            self.terminateForWindowsFatalPoint("present-chain-no-present-after-submit");
        }
    }

    fn reportPresentChainCheckpoint(self: *ElfState) void {
        const progress_callback = self.windows_graphics.hooks.update_present_diagnostics;
        if (progress_callback) |callback| {
            // The forwarder's `guest_progress` line is the first thing a
            // reader looks at in a no-presents block, and an opcode name is
            // not enough to tell an expensive computation from a stall. Carry
            // the frontier's symbol and workload across the same seam rather
            // than widening the C-ABI hook.
            var composed: [256]u8 = undefined;
            var frontier_text: [192]u8 = undefined;
            const opcode = @tagName(self.last_decoded_op);
            const operation = std.fmt.bufPrint(&composed, "{s} in {s}", .{
                opcode,
                self.describeGuestFrontier(self.regs.rip, &frontier_text),
            }) catch opcode;
            callback(
                self.windows_graphics.hooks.native_context,
                self.executed_steps,
                self.regs.rip,
                self.active_guest_thread,
                operation.ptr,
                operation.len,
                @intFromBool(self.classifyGuestFrontier(self.regs.rip).isBoundedComputation()),
            );
        }
        self.notePresentChainFailurePoint(self.executed_steps);
        if (self.windows_graphics.hooks.report_present_chain) |callback| {
            callback(self.windows_graphics.hooks.native_context);
        }
    }

    pub fn reportPresentChainFinal(self: *ElfState) void {
        if (!self.windows_runtime_enabled or self.windows_present_chain_final_reported) return;
        self.windows_present_chain_final_reported = true;
        if (self.windows_graphics.hooks.report_present_chain_full) |callback| {
            callback(self.windows_graphics.hooks.native_context);
        } else if (self.windows_graphics.hooks.report_present_chain) |callback| {
            callback(self.windows_graphics.hooks.native_context);
        }
    }

    fn windowsScreenValiditySnapshot(self: *const ElfState) screen_validity.Snapshot {
        const graphics = &self.windows_graphics;
        const guest_presents = if (graphics.guest_present_observed) graphics.presents else 0;
        const has_content_command = graphics.content_commands != 0;
        const has_present = guest_presents != 0;
        return .{
            .step = self.totalInterpretedSteps(),
            .guest_presents = guest_presents,
            .guest_acquires = graphics.image_acquires,
            .presents_with_target = if (has_present and graphics.image_acquires != 0) 1 else 0,
            .presents_with_content = if (has_present and has_content_command) 1 else 0,
            .presents_clear_only = if (has_present and !has_content_command and graphics.fill_commands != 0) 1 else 0,
            .presents_without_target = if (has_present and graphics.image_acquires == 0) 1 else 0,
            .presents_without_write = if (has_present and !has_content_command and graphics.fill_commands == 0) 1 else 0,
            .content_commands = graphics.content_commands,
            .native_present_requests = if (graphics.native_vulkan_forwarding) 0 else graphics.native_diagnostic_attempts,
            .native_present_completions = if (graphics.native_vulkan_forwarding) 0 else graphics.native_diagnostic_frames,
            .native_queue_submits = if (graphics.native_vulkan_forwarding) graphics.queue_submits else 0,
            .expected_width = graphics.window_width,
            .expected_height = graphics.window_height,
            // The ELF state owns the logical extent, but it does not own a
            // private AppKit drawable readback. Keep this unknown rather than
            // promoting the requested window size into pixel evidence.
            .extent_observed = false,
            .drawable_owner = if (graphics.native_vulkan_forwarding and graphics.swapchain_ready)
                .guest_swapchain
            else if (graphics.native_presenter_ready)
                .native_presenter
            else
                .unknown,
            .pixel_probe_attempts = 0,
            .pixel_probe_successes = 0,
            .pixel_evidence = .unavailable,
            .window_available = graphics.native_window_ready,
            .window_chain_intact = graphics.native_window_ready and
                (graphics.native_vulkan_forwarding or graphics.native_presenter_ready),
            .window_user_visible = graphics.native_window_visible,
            .window_visible_fraction_percent = if (graphics.native_window_visible) 100 else 0,
        };
    }

    /// Emit a Rosetta-owned, fail-closed screen verdict. A successful guest
    /// present or native diagnostic frame proves transport only. Without a
    /// bounded pixel readback and source provenance this report must never
    /// say that a detailed picture reached the user.
    pub fn reportWindowsScreenValidity(self: *ElfState) void {
        const snapshot = self.windowsScreenValiditySnapshot();
        const evaluation = self.windows_screen_validity.observe(snapshot);
        const first_blocking = if (evaluation.first_blocking) |stage| stage.label() else "none";
        const content_class = if (snapshot.content_commands != 0)
            "content_commands_observed"
        else if (self.windows_graphics.fill_commands != 0)
            "clear_or_uniform_only"
        else
            "no_content_or_fill_commands";
        log.info("PE64 SCREEN VALIDITY: verdict={s} first_blocking={s} screen_stage={s} content_class={s} guest_presents={d} acquires={d} content_commands={d} fill_commands={d} native_forwarding={} native_diagnostic_frames={d} pixel_evidence={s} pixel_probe_successes={d} window_visible={} visible_fraction={d}% observations={d}; valid_on_screen is fail-closed until detailed pixel evidence and source provenance are observed", .{
            evaluation.verdict.label(),
            first_blocking,
            evaluation.record(.screen_valid).status.label(),
            content_class,
            snapshot.guest_presents,
            snapshot.guest_acquires,
            snapshot.content_commands,
            self.windows_graphics.fill_commands,
            self.windows_graphics.native_vulkan_forwarding,
            self.windows_graphics.native_diagnostic_frames,
            snapshot.pixel_evidence.label(),
            snapshot.pixel_probe_successes,
            snapshot.window_user_visible,
            snapshot.window_visible_fraction_percent,
            self.windows_screen_validity.observations,
        });
        if (evaluation.first_blocking) |stage| {
            log.info("PE64 SCREEN VALIDITY:   action={s} evidence={s} owner={s}; transport and content provenance remain separate contracts", .{
                evaluation.action(),
                evaluation.record(stage).evidence,
                evaluation.record(stage).owner.label(),
            });
        }
    }

    /// Record which import raised a file failure and with what error.
    pub fn noteWindowsFileFailure(self: *ElfState, error_code: u32) void {
        self.noteWindowsFileFailureDetail(error_code, "", 0);
    }

    /// The same, with the path or file it concerned and where it came from.
    pub fn noteWindowsFileFailureDetail(self: *ElfState, error_code: u32, subject: []const u8, caller: u64) void {
        const api = if (self.windows_current_import.len == 0) "<unattributed>" else self.windows_current_import;
        self.windows_file_failure_ledger.note(api, error_code, subject, caller);
    }

    /// Report the Windows file operations this run could not serve.
    ///
    /// Silent when nothing failed. Expected answers - a pipe with no server,
    /// the end of an enumeration, a probe for an optional file - are
    /// informational; a missing path on an open, and any I/O failure on an
    /// open handle, warn, each with the first path it concerned and the
    /// caller. A run whose only failures are expected prints no warning.
    pub fn reportWindowsFileFailures(self: *const ElfState) void {
        const ledger = &self.windows_file_failure_ledger;
        if (ledger.isEmpty()) return;
        var actionable_entries: usize = 0;
        var actionable_calls: u64 = 0;
        for (ledger.entries[0..ledger.count]) |*entry| {
            if (entry.class.expected()) continue;
            actionable_entries += 1;
            actionable_calls +|= entry.count;
        }
        if (actionable_entries == 0) {
            log.info("WINDOWS FILE FAILURES: distinct={d} calls={d}, every one an expected answer (a pipe with no server, an enumeration's end or an optional-file probe); none is a path Rosette could not serve", .{ ledger.count, ledger.total });
        } else {
            log.warn("WINDOWS FILE FAILURES: distinct={d} calls={d} actionable={d} in {d} call(s); a large not-found count against a lookup API is a guest probing for optional files, while a failure on an open or a write is a path Rosetta could not serve", .{ ledger.count, ledger.total, actionable_entries, actionable_calls });
        }
        for (ledger.entries[0..ledger.count]) |*entry| {
            var caller_text: [guest_symbol_text_bytes]u8 = undefined;
            const caller = if (entry.first_caller == 0) "<not recorded>" else self.describeGuestAddressOrUnnamed(entry.first_caller, &caller_text);
            const subject = if (entry.subject_length == 0) "<none>" else entry.subject();
            if (entry.class.expected()) {
                log.info("WINDOWS FILE FAILURE:   {s} x{d} error={d} ({s}) class={s} first_subject='{s}' first_caller={s}; {s}", .{ entry.name(), entry.count, entry.error_code, windowsFileErrorLabel(entry.error_code), @tagName(entry.class), subject, caller, entry.class.meaning() });
            } else {
                log.warn("WINDOWS FILE FAILURE:   {s} x{d} error={d} ({s}) class={s} first_subject='{s}' first_caller={s}; {s}", .{ entry.name(), entry.count, entry.error_code, windowsFileErrorLabel(entry.error_code), @tagName(entry.class), subject, caller, entry.class.meaning() });
            }
        }
        if (ledger.overflow != 0) {
            log.warn("WINDOWS FILE FAILURES:   {d} further failures did not fit the bounded ledger", .{ledger.overflow});
        }
    }

    /// Record that an import completed through the deterministic ABI
    /// fallback.  Called from the Win32 surface, which does not know how the
    /// executor wants to keep evidence.
    pub fn noteWindowsImportFallback(
        self: *ElfState,
        dll_name: []const u8,
        name: []const u8,
        fallback: x64_linux_runtime.ImportFallback,
    ) void {
        _ = self.windows_import_fallbacks.note(
            dll_name,
            name,
            fallback,
            self.executed_steps,
            self.last_instruction_rip,
            self.regs.rcx,
            self.regs.rdx,
        );
    }

    /// Classify one import answer and keep it if it spelled failure.
    ///
    /// Called once per import, from the single point every dispatch returns
    /// through. Cheap on the common path: a cached convention lookup and one
    /// comparison. The conventions where zero is an ordinary answer - a count
    /// of none, a void return - can never produce a refusal, so a report of
    /// these is not diluted by calls that did nothing wrong.
    pub fn noteWindowsImportAnswer(
        self: *ElfState,
        dll_name: []const u8,
        name: []const u8,
        value: u64,
        last_error_before: u32,
    ) void {
        self.noteWindowsThreadImport(name);
        // What this name's own package declared, or - for a library nobody
        // has written down - what the spelling suggests. The first can be
        // used to accuse someone; the second cannot.
        const judgement = self.windows_import_answer_cache.judge(dll_name, name);
        if (judgement.declared) self.windows_import_answers_declared +|= 1;
        const convention = judgement.convention;
        if (!judgement.valueIsRefusal(value)) {
            if (judgement.decisive) {
                self.windows_import_answers_classified +|= 1;
            } else {
                self.windows_import_answers_unjudged +|= 1;
            }
            return;
        }
        // A failing value under a judgement that can be trusted is a refusal
        // outright.
        if (judgement.decisive) {
            self.windows_import_answers_classified +|= 1;
            self.recordWindowsImportRefusal(&self.windows_import_refusals, dll_name, name, convention, value);
            self.windows_import_refusal_events +|= 1;
            return;
        }
        // Under an inferred convention a zero cannot be read from the value
        // alone - `WAIT_OBJECT_0` and `VK_SUCCESS` are both zero and both
        // success. Windows' own rule breaks the tie: a BOOL that fails sets
        // `GetLastError`. A call that set one during this dispatch meant the
        // zero; a call that set nothing is either an ordinary negative answer
        // or a handler refusing silently, and those go on the audit list.
        self.windows_import_answers_unjudged +|= 1;
        if (self.windows_last_error != last_error_before and self.windows_last_error != 0) {
            self.windows_import_refusal_events +|= 1;
            self.recordWindowsImportRefusal(&self.windows_import_refusals, dll_name, name, convention, value);
            return;
        }
        self.windows_import_unexplained_events +|= 1;
        self.recordWindowsImportRefusal(&self.windows_import_unexplained_zeros, dll_name, name, convention, value);
    }

    /// Remember, per thread, the last import it called.
    ///
    /// One bounded copy per import - about ninety thousand in a Xenia run -
    /// against a question no other instrument answers.
    fn noteWindowsThreadImport(self: *ElfState, name: []const u8) void {
        const slot = self.windows_active_guest_thread_slot orelse return;
        const thread = &self.windows_guest_threads[slot];
        thread.import_calls +|= 1;
        thread.last_import_step = self.totalInterpretedSteps();
        const length = @min(name.len, WINDOWS_GUEST_THREAD_NAME_BYTES);
        @memcpy(thread.last_import[0..length], name[0..length]);
        thread.last_import_len = @intCast(length);
    }

    fn recordWindowsImportRefusal(
        self: *ElfState,
        ledger: *x64_linux_runtime.ImportFallbackLedger,
        dll_name: []const u8,
        name: []const u8,
        convention: x64_linux_runtime.ImportReturnConvention,
        value: u64,
    ) void {
        _ = ledger.note(
            dll_name,
            name,
            .{
                .convention = convention,
                .outcome = .refused,
                .value = value,
                .last_error = null,
                .hazard = false,
            },
            self.executed_steps,
            self.last_instruction_rip,
            self.regs.rcx,
            self.regs.rdx,
        );
    }

    /// Every import answer this run gave that the guest reads as a failure.
    ///
    /// The point of the block is that a guest failure message can be matched
    /// against it. Xenia says "Failed to create a DXGI factory"; the reader
    /// needs the export, the value, the caller and the step, and needs them
    /// for every such answer rather than for the one name somebody wired by
    /// hand. Hard refusals first - an HRESULT or NTSTATUS failure is a branch
    /// the guest takes, while a NULL handle is very often a probe whose
    /// absence the guest expects - then by how often it happened.
    pub fn reportWindowsImportRefusals(self: *const ElfState) void {
        const ledger = &self.windows_import_refusals;
        if (self.windows_import_answers_classified == 0) return;
        if (ledger.isEmpty()) {
            log.info(
                "PE64 IMPORT REFUSALS: none; {d} answer(s) were judged against an explicit ABI rule and every one read as success ({d} further answer(s) use a convention the contract infers from the name, where zero is success as often as it is failure, and are not judged)",
                .{ self.windows_import_answers_classified, self.windows_import_answers_unjudged },
            );
            return;
        }
        log.warn(
            "PE64 IMPORT REFUSALS: {d} name(s) in {d} call(s) of {d} judged answer(s), {d} of which had a declared ABI; every value Rosette returned that the guest's own ABI reads as failure, whichever handler produced it. A guest error message is explained by the row whose caller and step match it. {d} answer(s) are not judged: no package declares them and their convention is only inferred from the name, where a zero is success as often as failure",
            .{ ledger.count, self.windows_import_refusal_events, self.windows_import_answers_classified, self.windows_import_answers_declared, self.windows_import_answers_unjudged },
        );

        var order: [x64_linux_runtime.ImportFallbackLedger.capacity]usize = undefined;
        const ranked = ledger.rankedInto(&order);
        var caller_text: [guest_symbol_text_bytes]u8 = undefined;
        // Two passes so the refusals the guest branches on are read first.
        for ([_]bool{ true, false }) |hard_pass| {
            for (order[0..ranked]) |index| {
                const entry = &ledger.entries[index];
                if (!entry.used) continue;
                if (x64_linux_runtime.importRefusalIsHard(entry.convention) != hard_pass) continue;
                log.warn(
                    "PE64 IMPORT REFUSAL:   {s} {s}!{s} [{s}] x{d} returned=0x{x} convention={s} first_step={d} first_caller={s} first_args=0x{x},0x{x}; {s}",
                    .{
                        if (hard_pass) "hard  " else "soft  ",
                        entry.dll(),
                        entry.name(),
                        entry.subsystem.label(),
                        entry.calls,
                        entry.value,
                        @tagName(entry.convention),
                        entry.first_step,
                        self.describeGuestAddressOrUnnamed(entry.first_caller_rip, &caller_text),
                        entry.first_arg0,
                        entry.first_arg1,
                        if (self.windowsImportIsUnimplemented(entry.dll(), entry.name()))
                            "Rosette does not implement this name; the value is its ABI contract's refusal"
                        else
                            "a handler answered this deliberately; the value is what that handler decided, not a gap",
                    },
                );
            }
        }
        if (ledger.overflow_names != 0) {
            log.warn("PE64 IMPORT REFUSALS:   {d} further name(s) in {d} call(s) did not fit the bounded ledger", .{ ledger.overflow_names, ledger.overflow_calls });
        }
        log.warn(
            "PE64 IMPORT REFUSALS:   a hard refusal is one the guest branches on (HRESULT/NTSTATUS/LSTATUS/WSA); a soft one is a FALSE or a NULL, which for a probe is the expected answer. Read the hard rows against the guest's own error lines before treating any of them as a defect",
            .{},
        );
        self.reportCapabilityGaps();
    }

    /// For each library this run was refused by, what Rosette would have to
    /// Report the actual guest-owned CRT state, including the callback and
    /// termination tables. A count of zero is meaningful here: it says the
    /// run did not register or consume a callback, not that the CRT pointers
    /// were silently left null.
    pub fn reportWindowsCrtState(self: *const ElfState) void {
        const globals = &self.windows_crt_globals;
        log.info("PE64 CRT STATE: module_path_a=0x{x} module_path_w=0x{x} owner_errno=0x{x} normal_callbacks_remaining={d} quick_callbacks_remaining={d} thread_local_callback=0x{x} exit_mode={s} exit_running={} termination_complete={} registered={d} invoked={d} rejected={d} capability_gap_events={d} capability_gap_policy={s}", .{
            globals.module_path_a,
            globals.module_path_w,
            globals.owner_errno_storage,
            globals.normal_count,
            globals.quick_count,
            globals.thread_local_callback,
            @tagName(globals.exit_mode),
            globals.exit_running,
            globals.termination_complete,
            globals.callback_registrations,
            globals.callback_invocations,
            globals.callback_rejections,
            self.windows_capability_gap_events,
            if (self.windows_capability_gaps_fatal) "fatal" else "continue",
        });
    }

    /// Report only capability work that actually fell through the runtime
    /// contract, rather than every deliberate refusal value.
    ///
    /// A hand-written handler can return an ABI refusal because an optional
    /// host service is absent; that is evidence of a decision, not a missing
    /// library. The inventory remains useful for a true generic fallback, but
    /// it must never be selected from the value-classified refusal ledger.
    fn reportCapabilityGaps(self: *const ElfState) void {
        const ledger = &self.windows_import_fallbacks;
        var reported: usize = 0;
        var unenumerated: usize = 0;
        for (ledger.entries[0..ledger.count]) |*entry| {
            if (!entry.used) continue;
            if (!x64_linux_runtime.isCapabilityGap(entry.dll(), entry.name())) continue;
            // One inventory per library, not per name: the work is the
            // library, and printing it once per refused export would repeat
            // the same four paragraphs.
            var already = false;
            for (ledger.entries[0..ledger.count]) |*earlier| {
                if (earlier == entry) break;
                if (!earlier.used) continue;
                if (std.ascii.eqlIgnoreCase(earlier.dll(), entry.dll())) already = true;
            }
            if (already) continue;
            const inventory = x64_linux_runtime.importCapabilityGapFor(entry.dll()) orelse {
                unenumerated += 1;
                continue;
            };
            reported += 1;
            log.warn("PE64 CAPABILITY GAP: {s} - {s}", .{ inventory.dll_name, inventory.summary });
            for (inventory.conditions) |condition| {
                log.warn("PE64 CAPABILITY GAP:   needs: {s}", .{condition.requirement});
                log.warn("PE64 CAPABILITY GAP:     blocked by: {s}", .{condition.blocked_by});
                log.warn("PE64 CAPABILITY GAP:     without it: {s}{s}", .{
                    condition.consequence,
                    if (condition.blocks_first_frame) " [BLOCKS A FIRST FRAME]" else "",
                });
            }
            if (!inventory.blocksFirstFrame()) {
                log.warn("PE64 CAPABILITY GAP:   none of {s}'s conditions block a first frame, so this is standing work rather than the thing to do next", .{inventory.dll_name});
            }
        }
        if (reported == 0 and unenumerated == 0) {
            log.info(
                "PE64 CAPABILITY STATUS: no unresolved import capability gaps; every fallback was a modeled/policy answer or an explicitly audited dynamic refusal",
                .{},
            );
        } else if (unenumerated != 0) {
            // An absent inventory is not an empty one. Saying "nothing is
            // missing" about a library nobody has looked at would be the
            // same class of mistake as reading an inlined symbol's zero as
            // guest progress.
            log.warn("PE64 CAPABILITY GAP: {d} refused librar(y/ies) have no written inventory. That is nobody having enumerated them, not nothing being missing; add one under pkg/dll/win32/capability-gap when a refusal turns out to matter", .{unenumerated});
        }
    }

    /// The BOOL and handle returns that were zero and said nothing about why.
    ///
    /// Deliberately its own block. Windows' rule is that a failing BOOL sets
    /// `GetLastError`, so a handler that returns FALSE and sets nothing is
    /// either answering an honest no or refusing silently - and the value
    /// alone cannot say which. Reported as an audit list rather than as
    /// findings, because most of it is honest and the few that are not are
    /// worth reading every line for. `VirtualProtect` returning FALSE on
    /// every call for the whole life of this project was one of them.
    pub fn reportWindowsUnexplainedZeros(self: *const ElfState) void {
        const ledger = &self.windows_import_unexplained_zeros;
        if (ledger.isEmpty()) return;
        log.info(
            "PE64 IMPORT ZERO AUDIT: {d} name(s) in {d} call(s) returned FALSE or NULL and set no error code. Windows sets one when a BOOL call fails, so each of these is either an honest negative answer or a handler refusing without saying so - the value cannot tell them apart, and this list is the one to read line by line",
            .{ ledger.count, self.windows_import_unexplained_events },
        );
        var order: [x64_linux_runtime.ImportFallbackLedger.capacity]usize = undefined;
        const ranked = ledger.rankedInto(&order);
        var caller_text: [guest_symbol_text_bytes]u8 = undefined;
        for (order[0..ranked]) |index| {
            const entry = &ledger.entries[index];
            if (!entry.used) continue;
            log.info("PE64 IMPORT ZERO AUDIT:   {s}!{s} [{s}] x{d} convention={s} first_step={d} first_caller={s}", .{
                entry.dll(),
                entry.name(),
                entry.subsystem.label(),
                entry.calls,
                @tagName(entry.convention),
                entry.first_step,
                self.describeGuestAddressOrUnnamed(entry.first_caller_rip, &caller_text),
            });
        }
        if (ledger.overflow_names != 0) {
            log.info("PE64 IMPORT ZERO AUDIT:   {d} further name(s) in {d} call(s) did not fit the bounded ledger", .{ ledger.overflow_names, ledger.overflow_calls });
        }
    }

    /// Whether this name reached the generic contract fallback, meaning
    /// Rosette has no handler for it.
    fn windowsImportIsUnimplemented(self: *const ElfState, dll_name: []const u8, name: []const u8) bool {
        const ledger = &self.windows_import_fallbacks;
        for (ledger.entries[0..ledger.count]) |*entry| {
            if (!entry.used) continue;
            if (!std.mem.eql(u8, entry.name(), name)) continue;
            if (!std.ascii.eqlIgnoreCase(entry.dll(), dll_name)) continue;
            return true;
        }
        return false;
    }

    /// Report the imports this run completed through the ABI fallback.
    ///
    /// A healthy run says nothing here: the report is emitted only when a
    /// fallback has been taken that has not been described yet.  `full` asks
    /// for every entry (the end-of-run summary); otherwise only the entries
    /// added since the last report are printed, so a long run does not repeat
    /// what it already said.
    ///
    /// Detail is spent only where there is something to decide.  An import
    /// that was refused, or that answered something it had not earned, gets
    /// a line; the rest -- calls with no observable result -- collapse into
    /// one line naming them, because a screen of "safe to leave
    /// unimplemented" buries the few that are not.
    pub fn reportWindowsImportFallbacks(self: *ElfState, full: bool) void {
        const ledger = &self.windows_import_fallbacks;
        if (ledger.isEmpty()) return;
        if (!full and ledger.unreported_count == 0) return;

        var order: [x64_linux_runtime.ImportFallbackLedger.capacity]usize = undefined;
        const ranked = ledger.rankedInto(&order);
        const needsDetail = x64_linux_runtime.ImportFallbackLedger.entryNeedsDetail;

        var detailed: usize = 0;
        var collapsed: usize = 0;
        for (order[0..ranked]) |index| {
            const entry = &ledger.entries[index];
            if (!full and !entry.unreported) continue;
            if (needsDetail(entry.*)) detailed += 1 else collapsed += 1;
        }
        if (detailed == 0 and collapsed == 0) return;

        const unearned = ledger.hazardCount();
        if (unearned == 0) {
            log.warn(
                "IMPORT CONTRACT REFUSALS: names={d} refused={d} calls={d} new={d}; modeled Windows imports that returned an explicit ABI refusal because the optional host service is unavailable",
                .{ ledger.count, ledger.refusedCount(), ledger.total_calls, ledger.unreported_count },
            );
        } else {
            log.warn(
                "IMPORT CONTRACT REFUSALS: names={d} refused={d} unearned_answers={d} calls={d} new={d}; modeled Windows imports that returned an explicit ABI refusal because the optional host service is unavailable",
                .{ ledger.count, ledger.refusedCount(), unearned, ledger.total_calls, ledger.unreported_count },
            );
        }
        for (order[0..ranked]) |index| {
            const entry = &ledger.entries[index];
            if (!full and !entry.unreported) continue;
            if (!needsDetail(entry.*)) continue;
            log.warn(
                "IMPORT CONTRACT REFUSAL:   {s}!{s} [{s}{s}] calls={d} convention={s} returned=0x{x} first_step={d} first_caller=0x{x} first_args=0x{x},0x{x}; {s}",
                .{
                    entry.dll(),
                    entry.name(),
                    entry.subsystem.label(),
                    if (entry.subsystem.startupCritical()) ", startup-critical" else "",
                    entry.calls,
                    @tagName(entry.convention),
                    entry.value,
                    entry.first_step,
                    entry.first_caller_rip,
                    entry.first_arg0,
                    entry.first_arg1,
                    x64_linux_runtime.importFallbackAdvice(.{
                        .convention = entry.convention,
                        .outcome = entry.outcome,
                        .value = entry.value,
                        .last_error = null,
                        .hazard = entry.hazard,
                    }),
                },
            );
        }
        if (collapsed != 0) {
            // One line for everything with no observable result.  The names
            // are still here so nothing has to be guessed, but they do not
            // each get a verdict they do not need.
            var buffer: [512]u8 = undefined;
            var used: usize = 0;
            var listed: usize = 0;
            for (order[0..ranked]) |index| {
                const entry = &ledger.entries[index];
                if (!full and !entry.unreported) continue;
                if (needsDetail(entry.*)) continue;
                const written = std.fmt.bufPrint(
                    buffer[used..],
                    "{s}{s} x{d}",
                    .{ if (listed == 0) "" else ", ", entry.name(), entry.calls },
                ) catch break;
                used += written.len;
                listed += 1;
            }
            log.warn(
                "IMPORT CONTRACT REFUSALS:   {d} with no observable result (explicitly modeled no-op/refusal): {s}{s}",
                .{ collapsed, buffer[0..used], if (listed < collapsed) ", ..." else "" },
            );
        }
        if (ledger.overflow_names > 0) {
            log.warn(
                "IMPORT CONTRACT REFUSALS:   {d} further distinct names did not fit the bounded ledger; raise ImportFallbackLedger.capacity to see them",
                .{ledger.overflow_names},
            );
        }
        if (detailed != 0) {
            log.warn(
                "IMPORT CONTRACT REFUSALS: add stateful behavior in the owning pkg/dll/win32/<dll> package and its Rosetta dispatcher when one of these refusals blocks the guest; the convention above is the value the guest is being told today",
                .{},
            );
        }
        ledger.markReported();
    }

    fn handleWindowsImportStub(self: *ElfState) bool {
        const stub = self.windowsImportStubAt(self.regs.rip) orelse return false;
        if (self.diagnose_abi) {
            log.info("PE64 Windows import: {s}!{s} rip=0x{x} rcx=0x{x} rdx=0x{x} r8=0x{x} r9=0x{x} rsp=0x{x}", .{
                stub.dll_name,
                stub.function_name,
                self.regs.rip,
                self.regs.rcx,
                self.regs.rdx,
                self.regs.r8,
                self.regs.r9,
                self.regs.rsp,
            });
        }
        if (self.tryNativeWindowsVulkan(stub.function_name, null)) return !self.terminated;
        if (x64_linux_runtime.tryWindowsFunction(self, stub.dll_name, stub.function_name, null)) return true;
        if (!self.windows_unknown_imports_fatal) {
            // Diagnostic/non-strict mode is useful while inventorying a new
            // Windows image: keep the call boundary valid and make the
            // fallback visible through the degraded counter instead of
            // turning an intentionally permissive run into a host crash.
            const first_observation = self.recordUnresolvedWindowsImport(stub);
            self.windows_unknown_import_calls +|= 1;
            // An unresolved name has the same hazard as a recognized one:
            // a bare zero is `ERROR_SUCCESS`/`S_OK` for whole families of the
            // Win32 ABI.  The contract derives the refusal from the name's
            // shape, so an image Rosetta has never inventoried is refused
            // honestly rather than told its call worked.
            const fallback = x64_linux_runtime.importFallbackFor(stub.dll_name, stub.function_name);
            if (first_observation) {
                log.warn("unresolved Windows import continued with an ABI refusal: {s}!{s} dynamic={} convention={s} returned=0x{x} rip=0x{x} return=0x{x} caller=0x{x} step={d}", .{
                    stub.dll_name,
                    stub.function_name,
                    stub.is_dynamic,
                    @tagName(fallback.convention),
                    fallback.value,
                    self.regs.rip,
                    self.read64(self.regs.rsp),
                    self.last_instruction_rip,
                    self.executed_steps,
                });
            }
            self.windows_degraded_import_calls +|= 1;
            self.noteWindowsImportFallback(stub.dll_name, stub.function_name, fallback);
            if (fallback.last_error) |last_error| self.windows_last_error = last_error;
            self.regs.rax = fallback.value;
            self.regs.rip = self.pop();
            return true;
        }
        self.terminateForUnresolvedWindowsImport(stub.dll_name, stub.function_name);
        return true;
    }

    pub fn localSymbolAddress(self: *const ElfState, name: []const u8) ?u64 {
        for (self.local_symbols) |symbol| {
            if (std.mem.eql(u8, symbol.name, name)) return symbol.value;
        }
        return null;
    }

    pub fn localSymbolNameAt(self: *const ElfState, address: u64) ?[]const u8 {
        for (self.local_symbols) |symbol| {
            if (symbol.value == address) return symbol.name;
        }
        return null;
    }

    fn nearestLocalSymbol(self: *const ElfState, address: u64) ?exit_diagnostics.SymbolizedAddress {
        if (address < self.image_low or address >= self.image_high) return null;
        var best: ?elf_loader.Symbol = null;
        for (self.local_symbols) |symbol| {
            if (symbol.value == 0 or symbol.value > address) continue;
            if (best == null or symbol.value > best.?.value) best = symbol;
        }
        const symbol = best orelse return null;
        return .{ .address = symbol.value, .symbol = symbol.name, .symbol_offset = address - symbol.value };
    }

    fn recordTrace(self: *ElfState, decoded: DecodedInsn) void {
        self.last_instruction_rip = self.regs.rip;
        if (self.windows_runtime_enabled and !self.trace_ring_enabled) return;
        self.trace_ring.push(.{
            .rip = self.regs.rip,
            .op = decoded.op,
            .len = decoded.len,
            .rsp = self.regs.rsp,
            .rax = self.regs.rax,
            .rcx = self.regs.rcx,
            .rdx = self.regs.rdx,
        });
    }

    /// Keep the Win32 callback investigation local to a real guest callback
    /// frame. The pending-function WndProc is the hand-off from Xenia's UI
    /// loop to its graphics setup queue; tracing every PE call would drown the
    /// useful edge in CRT noise, while tracing only this frame exposes both
    /// the direct queue dispatcher and its std::function target.
    fn traceWindowsCallbackCall(self: *const ElfState, kind: []const u8, target: u64, operand: u64, next_rip: u64) void {
        if (!self.trace_windows_messages or self.windows_message_dispatch_frame_count == 0) return;
        log.info("Windows callback call: kind={s} source_rip=0x{x} target=0x{x} symbol={s} operand=0x{x} next_rip=0x{x} rsp=0x{x} rcx=0x{x} rdx=0x{x} r8=0x{x} r9=0x{x} stack0=0x{x} stack1=0x{x}", .{
            kind,
            self.regs.rip,
            target,
            self.localSymbolNameAt(target) orelse "",
            operand,
            next_rip,
            self.regs.rsp,
            self.regs.rcx,
            self.regs.rdx,
            self.regs.r8,
            self.regs.r9,
            self.read64(self.regs.rsp),
            self.read64(self.regs.rsp +| 8),
        });
    }

    pub fn guestAlloc(self: *ElfState, requested_size: u64, requested_alignment: u64) ?u64 {
        const size = if (requested_size == 0) 1 else requested_size;
        if (size > std.math.maxInt(usize)) {
            if (self.windows_runtime_enabled) log.err("PE64 guest allocation rejected: size={d} exceeds host index width rip=0x{x} op={s} len={d} rsp=0x{x} return=0x{x} rcx=0x{x} rdx=0x{x} r8=0x{x} r9=0x{x}", .{
                size,
                self.regs.rip,
                @tagName(self.last_decoded_op),
                self.last_decoded_len,
                self.regs.rsp,
                self.read64(self.regs.rsp),
                self.regs.rcx,
                self.regs.rdx,
                self.regs.r8,
                self.regs.r9,
            });
            return null;
        }

        var alignment = if (requested_alignment <= 1) @as(u64, 1) else requested_alignment;
        if ((alignment & (alignment - 1)) != 0) {
            var rounded: u64 = 1;
            while (rounded < alignment) {
                if (rounded > (std.math.maxInt(u64) >> 1)) return null;
                rounded <<= 1;
            }
            alignment = rounded;
        }

        if (self.reuseGuestHeapAllocation(size, alignment)) |reused| {
            if (self.trace_allocations and !@import("builtin").is_test) {
                log.info("PE64 guest allocation reused address=0x{x} requested={d} size={d} alignment={d} free={d} reused={d} rip=0x{x} op={s} len={d} rsp=0x{x} ret=0x{x}", .{
                    reused,
                    requested_size,
                    size,
                    alignment,
                    self.windows_heap_free_count,
                    self.windows_heap_reused_allocations,
                    self.regs.rip,
                    @tagName(self.last_decoded_op),
                    self.last_decoded_len,
                    self.regs.rsp,
                    self.read64(self.regs.rsp),
                });
            }
            return reused;
        }

        const mask = alignment - 1;
        if (self.heap_next > std.math.maxInt(u64) - mask) {
            if (self.windows_runtime_enabled) log.err("PE64 guest allocation rejected: heap cursor overflow heap_next=0x{x} alignment={d}", .{ self.heap_next, alignment });
            return null;
        }
        const aligned = (self.heap_next + mask) & ~mask;
        const heap_limit = if (self.guest_heap_limit != 0)
            self.guest_heap_limit
        else
            self.mem_base + self.mem_size - STACK_SIZE;
        if (aligned >= heap_limit or size > heap_limit - aligned) {
            if (self.windows_runtime_enabled) log.err("PE64 guest allocation rejected: request={d} align={d} heap_next=0x{x} aligned=0x{x} limit=0x{x} mem_base=0x{x} mem_size=0x{x} rip=0x{x} op={s} rsp=0x{x} return=0x{x}", .{
                size,
                alignment,
                self.heap_next,
                aligned,
                heap_limit,
                self.mem_base,
                self.mem_size,
                self.regs.rip,
                @tagName(self.last_decoded_op),
                self.regs.rsp,
                self.read64(self.regs.rsp),
            });
            return null;
        }
        const off = self.addrToOffset(aligned) orelse {
            if (self.windows_runtime_enabled) log.err("PE64 guest allocation rejected: aligned address outside guest range aligned=0x{x} mem_base=0x{x} mem_size=0x{x}", .{ aligned, self.mem_base, self.mem_size });
            return null;
        };
        const size_usize: usize = @intCast(size);
        if (off > self.mem.len or size_usize > self.mem.len - off) {
            if (self.windows_runtime_enabled) log.err("PE64 guest allocation rejected: offset={d} size={d} backing_bytes={d}", .{ off, size_usize, self.mem.len });
            return null;
        }

        @memset(self.mem[off..][0..size_usize], 0);
        if (self.windows_heap_allocation_count == self.windows_heap_allocations.len) {
            if (!self.growGuestHeapProvenance()) {
                // The guest allocation itself is still valid.  Keep running
                // rather than converting a host bookkeeping OOM into a guest
                // allocation failure; the first failure is recorded once and
                // the final diagnostics expose how many records were missed.
                self.windows_heap_provenance_untracked_allocations +|= 1;
            }
        }
        if (self.windows_heap_allocation_count < self.windows_heap_allocations.len) {
            self.windows_heap_allocations[self.windows_heap_allocation_count] = .{
                .guest_base = aligned,
                .length = size,
                .active = true,
            };
            self.windows_heap_allocation_count += 1;
            self.windows_heap_allocations_live += 1;
        }
        self.heap_next = aligned + size;
        if (self.trace_allocations and !@import("builtin").is_test) {
            log.info("PE64 guest allocation address=0x{x} requested={d} alignment={d} next=0x{x} rip=0x{x} op={s} len={d} rsp=0x{x} ret=0x{x} rcx=0x{x} rdx=0x{x} r8=0x{x} r9=0x{x}", .{
                aligned,
                requested_size,
                alignment,
                self.heap_next,
                self.regs.rip,
                @tagName(self.last_decoded_op),
                self.last_decoded_len,
                self.regs.rsp,
                self.read64(self.regs.rsp),
                self.regs.rcx,
                self.regs.rdx,
                self.regs.r8,
                self.regs.r9,
            });
        }
        return aligned;
    }

    fn growWindowsHeapFreeList(self: *ElfState) bool {
        const old_capacity = self.windows_heap_free_indices.len;
        const base_capacity = @max(old_capacity, @as(usize, 1));
        const new_capacity = std.math.mul(usize, base_capacity, 2) catch {
            self.windows_heap_free_list_growth_failures +|= 1;
            return false;
        };
        var grown: []usize = undefined;
        if (old_capacity == 0) {
            grown = self.allocator.alloc(usize, new_capacity) catch {
                self.windows_heap_free_list_growth_failures +|= 1;
                return false;
            };
        } else {
            grown = self.allocator.realloc(self.windows_heap_free_indices, new_capacity) catch {
                self.windows_heap_free_list_growth_failures +|= 1;
                if (self.windows_runtime_enabled and self.windows_heap_free_list_growth_failures == 1) {
                    log.err("PE64 guest allocation free-list growth failed: capacity={d}; released blocks remain unavailable", .{old_capacity});
                }
                return false;
            };
        }
        @memset(grown[old_capacity..], 0);
        self.windows_heap_free_indices = grown;
        if (self.windows_runtime_enabled) {
            log.info("PE64 guest allocation free-list grew: capacity={d} free={d} live={d}", .{
                new_capacity,
                self.windows_heap_free_count,
                self.windows_heap_allocations_live,
            });
        }
        return true;
    }

    fn rememberGuestHeapFreeIndex(self: *ElfState, allocation_index: usize) void {
        if (self.windows_heap_free_count == self.windows_heap_free_indices.len and
            !self.growWindowsHeapFreeList())
        {
            return;
        }
        if (self.windows_heap_free_count < self.windows_heap_free_indices.len) {
            self.windows_heap_free_indices[self.windows_heap_free_count] = allocation_index;
            self.windows_heap_free_count += 1;
        }
    }

    /// Reuse a released block without changing the address-ordered
    /// provenance table.  Only exact logical lengths are eligible: splitting
    /// a tombstone would require recording a new address-range remainder and
    /// would make the binary-search lifetime table ambiguous.  A reused block
    /// is cleared before it is published to the guest, matching fresh
    /// `guestAlloc` storage and preventing stale contents from crossing CRT
    /// object lifetimes.
    fn reuseGuestHeapAllocation(self: *ElfState, size: u64, alignment: u64) ?u64 {
        const mask = alignment - 1;
        var position = self.windows_heap_free_count;
        while (position != 0) {
            position -= 1;
            const allocation_index = self.windows_heap_free_indices[position];
            if (allocation_index >= self.windows_heap_allocation_count or
                self.windows_heap_allocations[allocation_index].active or
                self.windows_heap_allocations[allocation_index].length == 0)
            {
                const last_position = self.windows_heap_free_count - 1;
                self.windows_heap_free_indices[position] = self.windows_heap_free_indices[last_position];
                self.windows_heap_free_count = last_position;
                continue;
            }

            const record = self.windows_heap_allocations[allocation_index];
            if (record.length != size or (record.guest_base & mask) != 0) continue;
            const off = self.addrToOffset(record.guest_base) orelse continue;
            const size_usize: usize = @intCast(size);
            if (off > self.mem.len or size_usize > self.mem.len - off) continue;

            const last_position = self.windows_heap_free_count - 1;
            self.windows_heap_free_indices[position] = self.windows_heap_free_indices[last_position];
            self.windows_heap_free_count = last_position;
            self.windows_heap_allocations[allocation_index].active = true;
            self.windows_heap_allocations_live += 1;
            self.windows_heap_reused_allocations +|= 1;
            @memset(self.mem[off..][0..size_usize], 0);
            return record.guest_base;
        }
        return null;
    }

    /// Grow the address-ordered PE allocation-provenance table.
    ///
    /// Freed records remain as tombstones so the binary-search lookup keeps
    /// its address ordering.  Their exact block indices are tracked separately
    /// by `windows_heap_free_indices`, allowing physical storage reuse without
    /// changing the table's sorted address invariant.
    fn growGuestHeapProvenance(self: *ElfState) bool {
        const old_capacity = self.windows_heap_allocations.len;
        const base_capacity = @max(old_capacity, @as(usize, 1));
        const new_capacity = std.math.mul(usize, base_capacity, 2) catch {
            self.windows_heap_provenance_growth_failures +|= 1;
            return false;
        };
        const grown = self.allocator.realloc(self.windows_heap_allocations, new_capacity) catch {
            self.windows_heap_provenance_growth_failures +|= 1;
            if (self.windows_runtime_enabled and self.windows_heap_provenance_growth_failures == 1) {
                log.err("PE64 guest allocation provenance table growth failed: capacity={d}; guest allocations continue without records", .{old_capacity});
            }
            return false;
        };
        @memset(grown[old_capacity..], .{});
        self.windows_heap_allocations = grown;
        if (self.windows_runtime_enabled) {
            log.info("PE64 guest allocation provenance table grew: capacity={d} records={d} live={d} free={d}; released records remain address-ordered tombstones while exact blocks are reusable", .{ new_capacity, self.windows_heap_allocation_count, self.windows_heap_allocations_live, self.windows_heap_free_count });
        }
        return true;
    }

    fn findGuestHeapAllocation(self: *const ElfState, guest_base: u64) ?usize {
        var lower: usize = 0;
        var upper = self.windows_heap_allocation_count;
        while (lower < upper) {
            const middle = lower + (upper - lower) / 2;
            const record = self.windows_heap_allocations[middle];
            if (record.guest_base < guest_base) {
                lower = middle + 1;
            } else {
                upper = middle;
            }
        }
        if (lower < self.windows_heap_allocation_count and self.windows_heap_allocations[lower].guest_base == guest_base) {
            return lower;
        }
        return null;
    }

    /// Release the logical ownership of a PE heap block.  The backing bytes
    /// remain in flat guest memory until an exact-size allocation reuses them;
    /// the active bit makes a later realloc/free of a stale pointer
    /// diagnosable instead of silently valid.  The old logical length is
    /// retained so the free-list path can match the block safely.
    pub fn releaseGuestAllocation(self: *ElfState, guest_base: u64) bool {
        if (guest_base == 0) return true;
        const index = self.findGuestHeapAllocation(guest_base) orelse return false;
        if (!self.windows_heap_allocations[index].active) return false;
        self.windows_heap_allocations[index].active = false;
        if (self.windows_heap_allocations_live != 0) self.windows_heap_allocations_live -= 1;
        self.rememberGuestHeapFreeIndex(index);
        return true;
    }

    /// Implement the content-preserving realloc contract used by the PE CRT
    /// and Win32 heap APIs.  `guestAlloc` intentionally zeroes fresh blocks;
    /// that gives `_recalloc` and the newly grown tail the required zero-fill
    /// behavior, while the old bytes are copied before the old record is
    /// retired.  Shrinks stay in place and only reduce the logical extent.
    pub fn reallocateGuest(
        self: *ElfState,
        old_guest_base: u64,
        requested_size: u64,
        requested_alignment: u64,
    ) ?u64 {
        if (old_guest_base == 0) {
            if (requested_size == 0) return null;
            return self.guestAlloc(requested_size, requested_alignment);
        }
        if (requested_size == 0) {
            _ = self.releaseGuestAllocation(old_guest_base);
            return null;
        }

        const old_index = self.findGuestHeapAllocation(old_guest_base) orelse {
            if (self.windows_runtime_enabled) log.err("PE64 realloc rejected unknown block: address=0x{x} requested={d} rip=0x{x}", .{ old_guest_base, requested_size, self.regs.rip });
            return null;
        };
        const old_record = self.windows_heap_allocations[old_index];
        if (!old_record.active or old_record.length == 0) {
            if (self.windows_runtime_enabled) log.err("PE64 realloc rejected inactive block: address=0x{x} requested={d} rip=0x{x}", .{ old_guest_base, requested_size, self.regs.rip });
            return null;
        }
        if (requested_size <= old_record.length) {
            self.windows_heap_allocations[old_index].length = requested_size;
            return old_guest_base;
        }

        const new_guest_base = self.guestAlloc(requested_size, requested_alignment) orelse return null;
        const old_offset = self.addrToOffset(old_guest_base) orelse {
            _ = self.releaseGuestAllocation(new_guest_base);
            return null;
        };
        const new_offset = self.addrToOffset(new_guest_base) orelse {
            _ = self.releaseGuestAllocation(new_guest_base);
            return null;
        };
        const copy_length: usize = @intCast(@min(old_record.length, requested_size));
        @memcpy(self.mem[new_offset..][0..copy_length], self.mem[old_offset..][0..copy_length]);
        _ = self.releaseGuestAllocation(old_guest_base);
        return new_guest_base;
    }

    /// Register a Rosetta-owned address for a Windows function obtained
    /// through GetProcAddress or a Vulkan proc-address query. The executable
    /// only sees a guest address; the state intercepts that address before it
    /// attempts to decode synthetic bytes.
    pub fn registerWindowsImportStub(self: *ElfState, dll_name: []const u8, function_name: []const u8) ?u64 {
        for (self.windows_stub_storage[0..self.windows_stub_count]) |stub| {
            if (std.mem.eql(u8, stub.dll_name, dll_name) and std.mem.eql(u8, stub.function_name, function_name)) {
                return stub.address;
            }
        }
        const address = self.guestAlloc(16, 16) orelse return null;
        return if (self.registerWindowsImportStubAt(address, dll_name, function_name)) address else null;
    }

    /// Attach a Windows import descriptor to an already materialised PE IAT
    /// thunk. Direct imports and GetProcAddress results must converge on the
    /// same dispatcher; a byte stub that merely returns zero would bypass the
    /// ABI/runtime and make Vulkan initialization appear to succeed while no
    /// host call occurred.
    pub fn registerWindowsImportStubAt(self: *ElfState, address: u64, dll_name: []const u8, function_name: []const u8) bool {
        if (address == 0 or function_name.len == 0) return false;
        for (self.windows_stub_storage[0..self.windows_stub_count]) |stub| {
            if (stub.address == address) {
                return std.mem.eql(u8, stub.dll_name, dll_name) and
                    std.mem.eql(u8, stub.function_name, function_name);
            }
        }
        if (self.windows_stub_count >= self.windows_stub_storage.len) return false;
        self.windows_stub_storage[self.windows_stub_count] = .{
            .address = address,
            .dll_name = dll_name,
            .function_name = function_name,
        };
        self.windows_stub_count += 1;
        // Keep the address decodable if a caller inspects the thunk outside
        // the fast dispatcher check. F4 is the PE route's explicit import
        // sentinel and is intercepted before normal instruction execution.
        self.write8(address, 0xF4);
        return true;
    }

    pub fn windowsImportStubAt(self: *const ElfState, address: u64) ?WindowsImportStub {
        if (self.windows_direct_stub_count != 0) {
            const direct_bytes = std.math.mul(u64, @intCast(self.windows_direct_stub_count), 16) catch return null;
            const direct_end = std.math.add(u64, self.windows_direct_stub_base, direct_bytes) catch return null;
            if (address >= self.windows_direct_stub_base and address < direct_end) {
                const delta = address - self.windows_direct_stub_base;
                if ((delta & 0xF) != 0) return null;
                const index: usize = @intCast(delta >> 4);
                if (index < self.windows_direct_stub_count) {
                    const stub = self.windows_stub_storage[index];
                    return if (stub.address == address) stub else null;
                }
                return null;
            }
            // Direct PE code lives below the thunk range, while dynamically
            // published proc-address stubs are allocated after that range.
            // This early return is what keeps normal instruction dispatch
            // independent of the total import count.
            if (address < self.windows_direct_stub_base or
                self.windows_stub_count <= self.windows_dynamic_stub_start or
                address < direct_end)
            {
                return null;
            }
        }

        const dynamic_start = @min(self.windows_dynamic_stub_start, self.windows_stub_count);
        for (self.windows_stub_storage[dynamic_start..self.windows_stub_count]) |stub| {
            if (stub.address == address) {
                var dynamic_stub = stub;
                dynamic_stub.is_dynamic = true;
                return dynamic_stub;
            }
        }
        return null;
    }

    /// Compatibility hook used by the shared Mach-O Vulkan forwarder when it
    /// publishes a proc-address token. The Windows route intentionally keeps
    /// proc queries on Microsoft-ABI import stubs, so no SysV token is exposed
    /// to the PE instruction loop; retaining the hook lets the generic
    /// forwarder compile against the same state interface without fabricating
    /// an executable guest address.
    pub fn registerSyntheticThunk(_: *ElfState, _: u64, _: u64, _: []const u8) void {}

    pub fn terminateForUnresolvedWindowsImport(self: *ElfState, dll_name: []const u8, function_name: []const u8) void {
        // `tryFunction` can terminate before the import-stub dispatcher sees
        // the result. Make termination idempotent so that both routes record
        // one observation rather than inflating the inventory.
        if (self.terminated and self.termination_reason == .unresolved_import_result) return;
        const stub = WindowsImportStub{
            .address = self.regs.rip,
            .dll_name = dll_name,
            .function_name = function_name,
            .is_dynamic = self.windowsImportStubAt(self.regs.rip) != null and
                self.windowsImportStubAt(self.regs.rip).?.is_dynamic,
        };
        _ = self.recordUnresolvedWindowsImport(stub);
        self.windows_unknown_import_calls +|= 1;
        self.faulted = true;
        self.exit_code = 127;
        self.termination_reason = .unresolved_import_result;
        self.terminated = true;
        // Expected refusal tests inspect the recorded fault directly. Keep
        // the production error, without making a negative test fail solely
        // because Zig's test runner counts error-level messages as failures.
        if (comptime !@import("builtin").is_test) log.err("unresolved Windows import: {s}!{s} dynamic={} at rip=0x{x} return=0x{x} caller=0x{x} step={d}", .{
            dll_name,
            function_name,
            stub.is_dynamic,
            self.regs.rip,
            self.read64(self.regs.rsp),
            self.last_instruction_rip,
            self.executed_steps,
        });
    }

    /// Give the host-side Windows route one opportunity to own a Vulkan
    /// import. The callback receives this state opaquely so the executor does
    /// not depend on the host forwarder's module graph; a missing callback is
    /// an ordinary fallback to the explicit modelled Windows runtime.
    pub fn tryNativeWindowsVulkan(self: *ElfState, name: []const u8, direct_return_rip: ?u64) bool {
        const callback = self.windows_graphics.hooks.native_vulkan_dispatch orelse return false;
        if (name.len == 0) return false;
        if (callback(
            self.windows_graphics.hooks.native_context,
            @ptrCast(self),
            name.ptr,
            name.len,
            direct_return_rip orelse 0,
            if (direct_return_rip != null) 1 else 0,
        ) != 0) return true;
        if (!std.mem.startsWith(u8, name, "vk")) return false;
        // Once a native bridge owns the route, falling back to synthetic
        // handles / successful no-op commands would corrupt the same session.
        if (comptime !@import("builtin").is_test) {
            log.err("PE64 Vulkan native dispatch refused {s}; stopping before synthetic graphics fallback", .{name});
        }
        self.terminateForUnresolvedWindowsImport("vulkan-1.dll", name);
        return true;
    }

    /// Host CAMetalLayer lookup for the native Vulkan adapter. The callback is
    /// intentionally a host-only pointer-returning seam; no caller may write
    /// this value into guest memory.
    pub fn nativeMetalLayerHostPointer(self: *const ElfState) usize {
        const callback = self.windows_graphics.hooks.native_metal_layer_host_pointer orelse return 0;
        return callback(self.windows_graphics.hooks.native_context);
    }

    /// Hand the layer's `drawableSize` to the Vulkan driver, or take it back.
    ///
    /// The bridge sizes the layer from the view until a swapchain exists,
    /// because something has to. After that the property is MoltenVK's: it
    /// writes `drawableSize` from the swapchain's `imageExtent` and reads a
    /// change it did not make as the swapchain going out of date. The window
    /// bridge used to write it from every event pump, which the guest's
    /// message loop calls once per `GetMessage`.
    ///
    /// Returns whether the ownership actually moved, so the caller can log
    /// the transition once rather than on every swapchain create. The move
    /// is one way for the life of the run: the bridge only needed the
    /// property before the first swapchain existed, and a resize is handled
    /// by the swapchain being recreated, which sets it again.
    pub fn setNativeMetalDrawableOwner(self: *const ElfState, owned_by_swapchain: bool) bool {
        const callback = self.windows_graphics.hooks.native_metal_drawable_owner orelse return false;
        return callback(self.windows_graphics.hooks.native_context, @intFromBool(owned_by_swapchain)) != 0;
    }

    /// Set the host layer extent before a real Vulkan swapchain is created.
    /// Returning false means the host could not prove that the layer now has
    /// the requested pixels; the caller must not silently create a swapchain
    /// whose images and drawable disagree.
    pub fn prepareNativeMetalDrawable(self: *const ElfState, width: u32, height: u32) bool {
        const callback = self.windows_graphics.hooks.native_metal_drawable_prepare orelse return false;
        return callback(self.windows_graphics.hooks.native_context, width, height) != 0;
    }

    pub fn validateNativeMetalLayerToken(_: *const ElfState, token: u64) bool {
        return token == 0xCAFE_BABE_0000_0001;
    }

    pub fn nativeWindowWidth(self: *const ElfState) u32 {
        return self.windows_graphics.window_width;
    }

    pub fn nativeWindowHeight(self: *const ElfState) u32 {
        return self.windows_graphics.window_height;
    }

    /// Called by the real Vulkan forwarder once its guest surface is bound to
    /// the host layer. Keep this observation separate from the synthetic
    /// Windows ledger; the latter still records the guest ABI transition.
    pub fn noteNativeVulkanSurfaceBound(self: *ElfState, _: u64, _: u64, _: u64) void {
        self.windows_graphics.native_vulkan_forwarding = true;
    }

    pub fn terminateUnimplemented(self: *ElfState, d: DecodedInsn) void {
        self.faulted = true;
        self.exit_code = 127;
        self.termination_reason = .unimplemented_instruction;
        self.terminated = true;
        // Keep the production failure visible, while avoiding an intentional
        // negative-path unit test being reclassified as a test-runner error
        // solely because it exercises this fatal diagnostic.
        if (comptime !@import("builtin").is_test) {
            log.err("unimplemented x86-64 instruction at rip=0x{x}: {s}", .{ self.regs.rip, @tagName(d.op) });
        }
    }

    fn raiseDivideError(self: *ElfState) void {
        self.faulted = true;
        self.exit_code = 127;
        self.termination_reason = .divide_by_zero;
        self.terminated = true;
        if (comptime !@import("builtin").is_test) {
            log.err("x86 divide error at rip=0x{x} op={s}", .{ self.regs.rip, @tagName(self.last_decoded_op) });
        }
    }

    fn sibAddr(self: *const ElfState, d: *DecodedInsn) void {
        d.addr = x64_decoder.resolveMemoryAddress(&self.regs, .{
            .displacement = d.addr,
            .has_index = d.sib_has_index,
            .index_reg = d.sib_index_reg,
            .scale = d.sib_scale,
            .has_base = d.sib_has_base,
            .base_reg = d.sib_base_reg,
            .rip_relative = d.rip_relative,
            .segment = d.segment,
        }, self.regs.rip +% d.len, .bits64, .long64, true);
    }

    /// Worker execution is invisible to the owner's checkpoint histogram.
    /// Require both XThread::Execute on this worker and a fetch inside the
    /// tracked Xenia code-cache view; heap trampolines and other workers do
    /// not establish this stage. This proves entry into translated execution,
    /// not a swap or a picture (those retain independent evidence).
    fn noteWindowsTitleCodeFetch(self: *ElfState, address: u64) void {
        const slot = self.windows_active_guest_thread_slot orelse return;
        if (!self.windows_guest_threads[slot].entered_xenia_title) return;
        const index = self.windows_code_cache_view orelse return;
        const view = self.windows_memory_views[index];
        if (address >= view.guest_base and address - view.guest_base < view.length) {
            self.windows_title_code_fetches +|= 1;
        }
    }

    /// Up to sixteen instruction bytes at `address`, from the image or from a
    /// Rosette-owned code mapping.
    fn guestInstructionBytes(self: *const ElfState, address: u64, buffer: *[16]u8) []const u8 {
        if (self.addrToOffset(address)) |offset| {
            if (offset < self.mem.len) {
                const count = @min(self.mem.len - offset, buffer.len);
                @memcpy(buffer[0..count], self.mem[offset..][0..count]);
                return buffer[0..count];
            }
        }
        var count: u64 = buffer.len;
        while (count != 0) : (count -= 1) {
            if (self.windowsMappedCodeMemoryConst(address, count)) |slice| {
                const available: usize = @intCast(@min(slice.bytes.len, count));
                @memcpy(buffer[0..available], slice.bytes[0..available]);
                return buffer[0..available];
            }
        }
        return buffer[0..0];
    }

    fn decodeAt(self: *ElfState) ?DecodedInsn {
        const fetch_address = self.regs.rip +% x64_decoder.segmentBase(&self.regs, .cs, .long64);
        var bytes: []const u8 = undefined;
        var remaining: usize = 0;
        var mapped_code: ?WindowsMappedCodeSlice = null;
        if (self.addrToOffset(fetch_address)) |off| {
            remaining = self.mem.len - off;
            bytes = self.mem[off..];
        } else if (self.windowsMappedCodeMemoryConst(fetch_address, PE_MAX_INSTRUCTION_LENGTH)) |generated| {
            bytes = generated.bytes;
            remaining = bytes.len;
            mapped_code = generated;
            self.windows_generated_code_fetches +|= 1;
            self.noteWindowsTitleCodeFetch(fetch_address);
            if (self.windows_runtime_enabled and self.windows_generated_code_fetches == 1) {
                log.info("PE64 generated code execution: rip=0x{x} mapping={s} range=[0x{x},0x{x})", .{
                    fetch_address,
                    @tagName(generated.kind),
                    generated.guest_base,
                    generated.guest_base +| generated.length,
                });
            }
        } else {
            if (self.windows_runtime_enabled) {
                log.err("PE64 decode fetch outside guest image or mapped generated code: rip=0x{x} fetch=0x{x} mem=[0x{x},0x{x}) mem_len=0x{x} cs_base=0x{x} thread=0x{x} last_rip=0x{x} last_op={s} last_len={d} rsp=0x{x} stack0=0x{x} stack1=0x{x}", .{
                    self.regs.rip,
                    fetch_address,
                    self.mem_base,
                    self.mem_base +| self.mem_size,
                    self.mem.len,
                    self.regs.segments.cs.base,
                    self.active_guest_thread,
                    self.last_instruction_rip,
                    @tagName(self.last_decoded_op),
                    self.last_decoded_len,
                    self.regs.rsp,
                    self.read64(self.regs.rsp),
                    self.read64(self.regs.rsp +| 8),
                });
            }
            return null;
        }
        if (remaining == 0) {
            if (self.windows_runtime_enabled) {
                log.err("PE64 decode fetch at guest-image end: rip=0x{x} fetch=0x{x} off=0x{x} mem_len=0x{x} thread=0x{x}", .{
                    self.regs.rip,
                    fetch_address,
                    self.addrToOffset(fetch_address) orelse 0,
                    self.mem.len,
                    self.active_guest_thread,
                });
            }
            return null;
        }
        const cache_index = peDecodeCacheIndex(fetch_address);
        const cache_entry = &self.decode_cache[cache_index];
        var d: DecodedInsn = undefined;
        var decoded_segment: x64_decoder.Segment = .ds;
        const cached_len = @as(usize, cache_entry.decoded.len);
        const same_source = cache_entry.valid and cache_entry.fetch_address == fetch_address and
            cache_entry.mapped_source == (mapped_code != null) and
            (if (mapped_code) |generated|
                cache_entry.source_index == generated.source_index and cache_entry.source_kind == generated.kind
            else
                true) and
            cached_len != 0 and cached_len <= remaining and
            cached_len <= PE_MAX_INSTRUCTION_LENGTH;
        const image_generation = self.windowsImageCodeGenerationFor(fetch_address, cached_len);
        const cache_hit = same_source and
            (if (mapped_code) |generated|
                cache_entry.source_generation == generated.generation
            else if (image_generation) |generation|
                cache_entry.source_generation == generation
            else
                std.mem.eql(u8, cache_entry.bytes[0..cached_len], bytes[0..cached_len]));
        if (cache_hit) {
            self.decode_cache_hits +|= 1;
            d = cache_entry.decoded;
            decoded_segment = cache_entry.segment;
        } else {
            // A mapping-wide generation can move because another JIT
            // function was emitted. Re-check the old bytes before paying for
            // a fresh decode: most such changes are unrelated to this entry,
            // so the old decode can simply be re-armed for the new generation.
            const bytes_match = same_source and
                std.mem.eql(u8, cache_entry.bytes[0..cached_len], bytes[0..cached_len]);
            if (bytes_match) {
                self.decode_cache_rearms +|= 1;
                d = cache_entry.decoded;
                decoded_segment = cache_entry.segment;
                if (mapped_code) |generated| cache_entry.source_generation = generated.generation;
                if (mapped_code == null) {
                    if (self.windowsImageCodeGenerationFor(fetch_address, cached_len)) |generation| {
                        cache_entry.source_generation = generation;
                    }
                }
            } else {
                self.decode_cache_misses +|= 1;
                if (cache_entry.valid and cache_entry.fetch_address != fetch_address) self.decode_cache_collisions +|= 1;
                d = decodeInsn(bytes);
                const decoded_len = @as(usize, d.len);
                if (decoded_len != 0 and decoded_len <= remaining and decoded_len <= PE_MAX_INSTRUCTION_LENGTH) {
                    const prefixes = x64_decoder.decodeLegacyPrefixes(bytes);
                    const base: ?RegId = if (d.sib_has_base) d.sib_base_reg else null;
                    decoded_segment = x64_decoder.selectSegment(.explicit_data, base, prefixes.segment_override);
                    cache_entry.* = .{
                        .valid = true,
                        .fetch_address = fetch_address,
                        .mapped_source = mapped_code != null,
                        .source_kind = if (mapped_code) |generated| generated.kind else .memory_view,
                        .source_index = if (mapped_code) |generated| generated.source_index else 0,
                        .source_generation = if (mapped_code) |generated|
                            generated.generation
                        else if (self.windowsImageCodeGenerationFor(fetch_address, decoded_len)) |generation|
                            generation
                        else
                            0,
                        .segment = decoded_segment,
                        .decoded = d,
                    };
                    @memcpy(cache_entry.bytes[0..decoded_len], bytes[0..decoded_len]);
                }
            }
        }
        // The shared decoder records the address-size bit in `d`, but the
        // executor still needs the raw segment override to select DS versus
        // SS for an explicit memory operand. This was computed on a cache
        // fill and carried by the entry on a hit.
        const addr_size: Size = if (d.has_0x67) .bits32 else .bits64;
        d.segment = decoded_segment;
        // Relative control instructions keep their signed displacement in
        // `addr` (and `imm`) for highway.relativeControl.  They are marked
        // rip_relative by the legacy decoder, but that flag describes the
        // encoding rather than a data-memory operand.  Resolving them here
        // would turn the displacement into an absolute address, then the
        // executor would add RIP a second time.  Only data-memory operands
        // need effective-address resolution at this stage.
        const relative_control = switch (d.op) {
            .call_rel32, .jmp_rel8, .jcc_rel8, .jcc_rel32 => true,
            else => false,
        };
        // Register-form instructions never consume d.addr.  The decoder
        // still carries the ModRM displacement field for a uniform decoded
        // shape, but resolving it here needlessly reads live segment/base
        // state on the overwhelmingly common register path.  Memory forms,
        // including LEA and absolute disp-only operands, retain the full
        // effective-address calculation.
        if (!relative_control and !d.is_reg_form) {
            d.addr = x64_decoder.resolveMemoryAddress(&self.regs, .{
                .displacement = d.addr,
                .has_index = d.sib_has_index,
                .index_reg = d.sib_index_reg,
                .scale = d.sib_scale,
                .has_base = d.sib_has_base,
                .base_reg = d.sib_base_reg,
                .rip_relative = d.rip_relative,
                .segment = d.segment,
            }, self.regs.rip +% d.len, addr_size, .long64, d.op != .lea_reg_mem);
        }
        return d;
    }

    /// Move the guest performance counter forward.
    ///
    /// Called from `step`, which is the one boundary the owner loop and every
    /// cooperative worker share, so the counter advances for whichever thread
    /// is running. See `WINDOWS_GUEST_CLOCK_SAMPLE_STRIDE` for why the source
    /// is the host's monotonic clock rather than the instruction count.
    ///
    /// Never decreases. A performance counter that goes backwards makes a
    /// guest computing `now - then` see an enormous unsigned interval, and
    /// every deadline in the run is computed that way.
    fn advanceWindowsGuestClock(self: *ElfState) void {
        // The host clock is read here rather than inside `guest_clock.zig` so
        // that file has no syscall in it and stays testable without one. On
        // the strided path the read happens every 512 steps; the branch that
        // decides is one predictable compare.
        if (self.guest_clock.source == .retired_instructions) {
            self.guest_clock.advance(0);
            return;
        }
        self.guest_clock.stride +|= 1;
        if (self.guest_clock.stride < WINDOWS_GUEST_CLOCK_SAMPLE_STRIDE) return;
        self.guest_clock.refresh(monotonicNanoseconds());
    }

    /// Sample the host clock now, whatever the stride says.
    ///
    /// The stride exists to keep the read off the per-instruction path. A
    /// caller that is about to decide something *because* of the time has to
    /// ask for the current answer instead.
    fn refreshWindowsGuestClock(self: *ElfState) void {
        self.guest_clock.refresh(monotonicNanoseconds());
    }

    fn step(self: *ElfState) bool {
        // `step` is the one boundary shared by the owner loop and every
        // cooperative Windows worker. Advancing the Windows performance
        // counter here keeps Xenia's worker-owned frame limiter progressing
        // even while the owner is parked in a wait service loop.
        self.advanceWindowsGuestClock();
        if (self.handleSyntheticRip()) return !self.terminated;
        if (self.handleWindowsImportStub()) return !self.terminated;
        if (x64_linux_runtime.tryWindowsGuestCompatibility(self)) return !self.terminated;
        const decoded = self.decodeAt() orelse {
            self.faulted = true;
            self.exit_code = 127;
            self.termination_reason = .decode_failed;
            self.terminated = true;
            return false;
        };
        if (self.trace_string_memory) {
            switch (self.regs.rip) {
                0x14011b6f0 => {
                    const haystack_view = self.regs.rcx;
                    const needle_view = self.regs.rdx;
                    const haystack_length = self.read64(haystack_view);
                    const haystack_data = self.read64(haystack_view +| 8);
                    const needle_length = self.read64(needle_view);
                    const needle_data = self.read64(needle_view +| 8);
                    log.info("PE utf8 find_any_of entry haystack_view=0x{x} data=0x{x} length={d} bytes={any} needle_view=0x{x} data=0x{x} length={d} bytes={any}", .{
                        haystack_view,
                        haystack_data,
                        haystack_length,
                        if (haystack_length == 0) &[_]u8{} else self.guestMemoryConst(haystack_data, @min(haystack_length, 64)) orelse &[_]u8{},
                        needle_view,
                        needle_data,
                        needle_length,
                        if (needle_length == 0) &[_]u8{} else self.guestMemoryConst(needle_data, @min(needle_length, 64)) orelse &[_]u8{},
                    });
                },
                0x140134c80 => {
                    const view = self.regs.rdx;
                    const length = self.read64(view);
                    const data = self.read64(view +| 8);
                    const preview_len: usize = @intCast(@min(length, 64));
                    log.info("PE EscapeString entry result=0x{x} view=0x{x} data=0x{x} length={d} bytes={any}", .{
                        self.regs.rcx,
                        view,
                        data,
                        length,
                        if (preview_len == 0) &[_]u8{} else self.guestMemoryConst(data, preview_len) orelse &[_]u8{},
                    });
                },
                0x140134cc9,
                0x140134d06,
                0x140134e33,
                => log.info("PE EscapeString find_any_of return rip=0x{x} result=0x{x}", .{ self.regs.rip, self.regs.rax }),
                0x140134e5a => {
                    const view = self.regs.rdx;
                    const length = self.read64(view);
                    const data = self.read64(view +| 8);
                    log.info("PE EscapeString escape-basic call view=0x{x} data=0x{x} length={d} bytes={any}", .{
                        view,
                        data,
                        length,
                        if (length == 0) &[_]u8{} else self.guestMemoryConst(data, @min(length, 64)) orelse &[_]u8{},
                    });
                },
                0x140134f6d => {
                    const view = self.regs.rdi;
                    const length = self.read64(view);
                    const data = self.read64(view +| 8);
                    log.info("PE EscapeString plain-string path view=0x{x} data=0x{x} length={d} bytes={any}", .{
                        view,
                        data,
                        length,
                        if (length == 0) &[_]u8{} else self.guestMemoryConst(data, @min(length, 64)) orelse &[_]u8{},
                    });
                },
                else => {},
            }
        }
        if (decoded.op == .invalid) {
            // Through the code mappings as well as the image: Xenia's JIT
            // cache is a mapping, and the 2026-09-14 fault at 0xa0535c03
            // printed `bytes={ }` because only the image was read.
            var fetched_bytes: [16]u8 = undefined;
            const opcode_bytes = self.guestInstructionBytes(self.regs.rip, &fetched_bytes);
            var fault_symbol_text: [guest_symbol_text_bytes]u8 = undefined;
            const fault_slot_plus_one: u8 = if (self.windows_active_guest_thread_slot) |slot| @intCast(@min(slot + 1, 255)) else 0;
            // Name the opcode-map slot, not just the bytes.  Hand-decoding a
            // VEX prefix to find out which instruction is missing is the slow
            // part of acting on this fault, and the coordinates printed here
            // are the same ones the decoder's opcode census reports, so the
            // gap can be looked up directly.
            var encoding_buffer: [96]u8 = undefined;
            log.err("invalid instruction at rip=0x{x} ({s}) thread={s}: encoding={s} bytes={any}; this opcode slot has no decoder entry -- see ISA/decoding/coverage.zig for the census of what does, and if the address is generated code, add the form to the Xenia JIT corpus (tools/gen_xenia_jit_corpus.py)", .{
                self.regs.rip,
                self.describeGuestAddressOrUnnamed(self.regs.rip, &fault_symbol_text),
                self.guestThreadLabel(fault_slot_plus_one),
                x64_decoder.coverage.describeEncoding(&encoding_buffer, opcode_bytes),
                opcode_bytes,
            });
            self.faulted = true;
            self.exit_code = 127;
            self.termination_reason = .invalid_instruction;
            self.terminated = true;
            return false;
        }
        self.last_decoded_op = decoded.op;
        self.last_decoded_len = decoded.len;
        self.recordTrace(decoded);
        if (self.trace_formatter and self.regs.rip == 0x1400ccf50 and
            (self.trace_formatter_address == null or self.trace_formatter_address.? == self.regs.r8))
        {
            const appender = self.regs.r8;
            log.info("formatter entry appender=0x{x} caller=0x{x} data=0x{x} offset=0x{x} end=0x{x} callback=0x{x} rsp=0x{x} thread=0x{x}", .{
                appender,
                self.read64(self.regs.rsp),
                self.read64(appender),
                self.read64(appender +| 8),
                self.read64(appender +| 0x10),
                self.read64(appender +| 0x18),
                self.regs.rsp,
                self.active_guest_thread,
            });
        }
        // A Windows process can block before its message loop exists.  The
        // bundled Xenia runtime does exactly that: the creating thread enters
        // an internal pthread_spin_lock while the newly-created worker is
        // expected to initialize the shared state and release the lock.  A
        // single cooperative interpreter must service that worker at the
        // architectural PAUSE wait point; waiting for GetMessage here would
        // deadlock the process before any UI or Vulkan import is reachable.
        const is_pause = decoded.op == .nop and decoded.len == 2 and
            self.read8(self.regs.rip) == 0xF3 and self.read8(self.regs.rip +| 1) == 0x90;
        const worker_service_due = if (self.windows_last_service_owner_step) |last|
            self.executed_steps >= last +| WINDOWS_GUEST_THREAD_SERVICE_OWNER_STRIDE
        else
            true;
        if (is_pause and self.windows_runtime_enabled and
            self.windows_active_guest_thread_slot == null and worker_service_due and self.nextWindowsGuestThread() != null)
        {
            _ = self.serviceWindowsGuestThreads(WINDOWS_GUEST_THREAD_SERVICE_SLICE);
            if (self.terminated) return false;
        }
        const trace_this = shouldTraceRip(self, self.regs.rip);
        var trace_rip: u64 = 0;
        var trace_flags_before: u64 = 0;
        if (trace_this) {
            trace_rip = self.regs.rip;
            trace_flags_before = self.regs.rflags;
            log.info("trace before rip=0x{x} thread=0x{x} op={s} len={d} addr=0x{x} dst={s} src={s} cond={s} rax=0x{x} rcx=0x{x} rdx=0x{x} rsi=0x{x} rdi=0x{x} r8=0x{x} r9=0x{x} r10=0x{x} r11=0x{x} r12=0x{x} r13=0x{x} r14=0x{x} r15=0x{x} rsp=0x{x} ret=0x{x} rbp=0x{x} flags=0x{x}", .{
                trace_rip,
                self.active_guest_thread,
                @tagName(decoded.op),
                decoded.len,
                decoded.addr,
                @tagName(decoded.dst_reg),
                @tagName(decoded.src_reg),
                @tagName(decoded.cond),
                self.regs.rax,
                self.regs.rcx,
                self.regs.rdx,
                self.regs.rsi,
                self.regs.rdi,
                self.regs.r8,
                self.regs.r9,
                self.regs.r10,
                self.regs.r11,
                self.regs.r12,
                self.regs.r13,
                self.regs.r14,
                self.regs.r15,
                self.regs.rsp,
                self.read64(self.regs.rsp),
                self.regs.rbp,
                self.regs.rflags,
            });
            // Xenia's Xbyak emitter materializes an Address displacement in
            // a stack object before passing it through CodeGenerator::mov.
            // Keep this narrowly keyed to the compiled PushStackpoint store
            // so an opt-in RIP trace can distinguish a bad guest store from
            // a later vector/address-object corruption without adding normal
            // run noise.
            if (self.regs.rip == 0x140b18098 and decoded.op == .mov_mem64_imm32) {
                log.info("trace Xbyak displacement store before address=0x{x} value=0x{x} immediate=0x{x} rsp=0x{x}", .{
                    decoded.addr,
                    self.read64(decoded.addr),
                    decoded.imm,
                    self.regs.rsp,
                });
            }
            if (self.regs.rip == 0x1405b953e) {
                const address_object = self.regs.rsi;
                log.info("trace Xbyak opAddr displacement read before address_object=0x{x} displacement_address=0x{x} value=0x{x} bytes={any}", .{
                    address_object,
                    address_object +| 0x20,
                    self.read64(address_object +| 0x20),
                    self.guestMemoryConst(address_object, 0x28) orelse &[_]u8{},
                });
            }
            if (self.regs.rip == 0x1405b9980) {
                const regexp_object = self.regs.rdx;
                log.info("trace Xbyak setSIB displacement read before regexp=0x{x} displacement_address=0x{x} value=0x{x} bytes={any}", .{
                    regexp_object,
                    regexp_object +| 0x18,
                    self.read64(regexp_object +| 0x18),
                    self.guestMemoryConst(regexp_object, 0x20) orelse &[_]u8{},
                });
            }
            if (self.trace_vector) {
                switch (decoded.op) {
                    .vcvtss2sd,
                    .vcvtsi2sd_xmm_reg,
                    .vcvtsi2sd_xmm_mem,
                    .vdivsd,
                    .vucomisd,
                    => log.info("trace scalar-sse rip=0x{x} op={s} xmm0=0x{x} xmm1=0x{x} xmm2=0x{x} xmm3=0x{x} xmm4=0x{x} xmm5=0x{x} xmm6=0x{x} xmm7=0x{x}", .{
                        self.regs.rip,
                        @tagName(decoded.op),
                        std.mem.readInt(u64, self.xmm[0][0..8], .little),
                        std.mem.readInt(u64, self.xmm[1][0..8], .little),
                        std.mem.readInt(u64, self.xmm[2][0..8], .little),
                        std.mem.readInt(u64, self.xmm[3][0..8], .little),
                        std.mem.readInt(u64, self.xmm[4][0..8], .little),
                        std.mem.readInt(u64, self.xmm[5][0..8], .little),
                        std.mem.readInt(u64, self.xmm[6][0..8], .little),
                        std.mem.readInt(u64, self.xmm[7][0..8], .little),
                    }),
                    else => {},
                }
            }
            if (self.trace_utf8) {
                // This is intentionally opt-in and lives behind the existing
                // RIP trace gate.  The Windows PE uses the same utfcpp
                // helpers for xe::to_utf16. The Windows libstdc++ ABI stores
                // a string_view as {length, data}; logging it in the more
                // familiar {data, length} order produces a convincing but
                // completely false multi-gigabyte input diagnosis.
                if (self.regs.rip == 0x14011f930) {
                    const current = self.read64(self.regs.rcx);
                    const end = self.regs.rdx;
                    const remaining = if (end >= current) end - current else 0;
                    const preview_len: usize = @intCast(@min(remaining, 32));
                    log.info("trace utf8::next iterator=0x{x} current=0x{x} end=0x{x} remaining={d} bytes={any}", .{
                        self.regs.rcx,
                        current,
                        end,
                        remaining,
                        if (preview_len == 0) &[_]u8{} else self.guestMemoryConst(current, preview_len) orelse &[_]u8{},
                    });
                } else if (self.regs.rip == 0x1401307a0) {
                    const source_view = self.regs.rdx;
                    const length = self.read64(source_view);
                    const source = self.read64(source_view +| 8);
                    const preview_len: usize = @intCast(@min(length, 64));
                    log.info("trace threading::set_name view=0x{x} source=0x{x} length={d} bytes={any}", .{
                        source_view,
                        source,
                        length,
                        if (preview_len == 0) &[_]u8{} else self.guestMemoryConst(source, preview_len) orelse &[_]u8{},
                    });
                } else if (self.regs.rip == 0x140122950) {
                    const source_view = self.regs.rdx;
                    const length = self.read64(source_view);
                    const source = self.read64(source_view +| 8);
                    const preview_len: usize = @intCast(@min(length, 64));
                    log.info("trace xe::to_utf16 source_view=0x{x} source=0x{x} length={d} bytes={any}", .{
                        source_view,
                        source,
                        length,
                        if (preview_len == 0) &[_]u8{} else self.guestMemoryConst(source, preview_len) orelse &[_]u8{},
                    });
                }
            }
            switch (decoded.op) {
                .cmp_mem32_imm8 => {
                    log.info("trace memory rip=0x{x} op=cmp_mem32_imm8 address=0x{x} value=0x{x} immediate=0x{x}", .{
                        self.regs.rip,
                        decoded.addr,
                        self.readMemVal(decoded.addr, .bits32),
                        decoded.imm,
                    });
                    // The PE probe currently reaches libstdc++'s regex
                    // compiler.  Its scanner is embedded immediately after
                    // the compiler object; include its state only under the
                    // existing RIP trace gate so a token mismatch can be
                    // attributed without adding normal-run noise.
                    const scanner = self.regs.rsi +| 8;
                    const current = self.read64(scanner +| 0xb0);
                    const end = self.read64(scanner +| 0xb8);
                    const remaining = if (end >= current) end - current else 0;
                    const preview_len: usize = @intCast(@min(remaining, 16));
                    log.info("trace regex scanner scanner=0x{x} state=0x{x} token=0x{x} current=0x{x} end=0x{x} remaining={d} next=0x{x} preview={any}", .{
                        scanner,
                        self.read32(scanner +| 0x88),
                        self.read32(scanner +| 0x90),
                        current,
                        end,
                        remaining,
                        self.read8(current),
                        if (preview_len == 0) &[_]u8{} else self.guestMemoryConst(current, preview_len) orelse &[_]u8{},
                    });
                },
                .mov_reg32_mem32 => {
                    log.info("trace 32-bit memory-load address=0x{x} bytes={any}", .{
                        decoded.addr,
                        self.guestMemoryConst(decoded.addr, 80) orelse &[_]u8{},
                    });
                },
                else => {},
            }
            switch (decoded.op) {
                .vmovups_xmm_mem,
                .vmovups_ymm_mem,
                .vmovaps_xmm_mem,
                .vmovaps_ymm_mem,
                => {
                    const width: usize = if (decoded.vector_256) 32 else 16;
                    log.info("trace vector-load address=0x{x} width={d} xmm_dst={d} xmm_src={d} legacy_sse={} bytes={any}", .{
                        decoded.addr,
                        width,
                        decoded.xmm_dst,
                        decoded.xmm_src,
                        decoded.legacy_sse,
                        self.guestMemoryConst(decoded.addr, width) orelse &[_]u8{},
                    });
                },
                else => {},
            }
        }
        x64_interpreter.execute(self, decoded);
        // The fault is raised here, at the boundary, rather than from inside
        // the memory access: the instruction has finished, so the CONTEXT
        // handed to the guest describes a consistent machine.
        if (self.guest_access_violation_pending) self.raiseGuestAccessViolation();
        if (trace_this) {
            log.info("trace transition rip=0x{x} next_rip=0x{x} op={s} len={d} thread=0x{x} addr=0x{x} cond={s} flags_before=0x{x} flags_after=0x{x}", .{
                trace_rip,
                self.regs.rip,
                @tagName(decoded.op),
                decoded.len,
                self.active_guest_thread,
                decoded.addr,
                @tagName(decoded.cond),
                trace_flags_before,
                self.regs.rflags,
            });
            if (decoded.op == .mov_mem8_reg8 and self.regs.rip == 0x14011f219) {
                const source_value = self.decodedRegVal(decoded.src_reg, decoded.src_high8, .bits8);
                log.info("trace byte-store rip=0x{x} address=0x{x} src={s} high8={} source=0x{x} stored=0x{x} rdi=0x{x} r13=0x{x}", .{
                    self.regs.rip -| decoded.len,
                    decoded.addr,
                    @tagName(decoded.src_reg),
                    decoded.src_high8,
                    source_value,
                    self.read8(decoded.addr),
                    self.regs.rdi,
                    self.regs.r13,
                });
            }
            log.info("trace after  rip=0x{x} rax=0x{x} rcx=0x{x} rdx=0x{x} rsi=0x{x} rdi=0x{x} r8=0x{x} r9=0x{x} r10=0x{x} r11=0x{x} r12=0x{x} r13=0x{x} r14=0x{x} r15=0x{x} rsp=0x{x} rbp=0x{x} flags=0x{x}", .{
                self.regs.rip,
                self.regs.rax,
                self.regs.rcx,
                self.regs.rdx,
                self.regs.rsi,
                self.regs.rdi,
                self.regs.r8,
                self.regs.r9,
                self.regs.r10,
                self.regs.r11,
                self.regs.r12,
                self.regs.r13,
                self.regs.r14,
                self.regs.r15,
                self.regs.rsp,
                self.regs.rbp,
                self.regs.rflags,
            });
            if (self.regs.rip == 0x140b180a1 and decoded.op == .mov_mem64_imm32) {
                const displacement_address = self.regs.rsp +| 0x60;
                log.info("trace Xbyak displacement store after address=0x{x} value=0x{x} expected=0x130 rsp=0x{x}", .{
                    displacement_address,
                    self.read64(displacement_address),
                    self.regs.rsp,
                });
            }
            if (self.trace_vector) {
                switch (decoded.op) {
                    .vcvtss2sd,
                    .vcvtsi2sd_xmm_reg,
                    .vcvtsi2sd_xmm_mem,
                    .vdivsd,
                    .vucomisd,
                    => log.info("trace scalar-sse after rip=0x{x} op={s} xmm0=0x{x} xmm1=0x{x} xmm2=0x{x} xmm3=0x{x} xmm4=0x{x} xmm5=0x{x} xmm6=0x{x} xmm7=0x{x} flags=0x{x}", .{
                        self.regs.rip,
                        @tagName(decoded.op),
                        std.mem.readInt(u64, self.xmm[0][0..8], .little),
                        std.mem.readInt(u64, self.xmm[1][0..8], .little),
                        std.mem.readInt(u64, self.xmm[2][0..8], .little),
                        std.mem.readInt(u64, self.xmm[3][0..8], .little),
                        std.mem.readInt(u64, self.xmm[4][0..8], .little),
                        std.mem.readInt(u64, self.xmm[5][0..8], .little),
                        std.mem.readInt(u64, self.xmm[6][0..8], .little),
                        std.mem.readInt(u64, self.xmm[7][0..8], .little),
                        self.regs.rflags,
                    }),
                    else => {},
                }
            }
            switch (decoded.op) {
                .vmovups_mem_xmm,
                .vmovups_mem_ymm,
                .vmovaps_mem_xmm,
                .vmovaps_mem_ymm,
                => {
                    const width: usize = if (decoded.vector_256) 32 else 16;
                    log.info("trace vector-store address=0x{x} width={d} xmm_dst={d} xmm_src={d} legacy_sse={} bytes={any}", .{
                        decoded.addr,
                        width,
                        decoded.xmm_dst,
                        decoded.xmm_src,
                        decoded.legacy_sse,
                        self.guestMemoryConst(decoded.addr, width) orelse &[_]u8{},
                    });
                },
                else => {},
            }
        }
        return !self.terminated;
    }

    pub fn run(self: *ElfState) void {
        self.runWithLimit(2_000_000);
    }

    fn sampleWindowsProgress(self: *const ElfState) WindowsProgressSample {
        const graphics = &self.windows_graphics;
        var vacant: u64 = 0;
        var pending: u64 = 0;
        var runnable: u64 = 0;
        var running: u64 = 0;
        var blocked: u64 = 0;
        var completed: u64 = 0;
        var failed: u64 = 0;
        for (&self.windows_guest_threads) |*thread| {
            switch (thread.status) {
                .vacant => vacant += 1,
                .pending => pending += 1,
                .runnable => runnable += 1,
                .running => running += 1,
                .blocked => blocked += 1,
                .completed => completed += 1,
                .failed => failed += 1,
            }
        }
        return .{
            .import_calls = self.windows_import_calls +% self.windows_unknown_import_calls,
            .graphics_calls = graphics.vulkan_calls +% graphics.native_vulkan_calls +% graphics.command_calls,
            .graphics_frames = graphics.queue_submits +% graphics.presents,
            .message_traffic = self.windows_message_posts,
            .paint_traffic = self.windows_paint_requests,
            .worker_traffic = self.windows_thread_service_calls +% self.windows_thread_yields +%
                self.windows_thread_blocks +% self.windows_thread_unblocks +%
                self.windows_thread_completions +% self.windows_thread_failures,
            .file_traffic = self.windows_file_open_calls +% self.windows_file_read_calls +%
                self.windows_file_write_calls,
            .worker_states = (vacant << 56) | (pending << 48) | (runnable << 40) |
                (running << 32) | (blocked << 24) | (completed << 16) | (failed << 8),
            .rip_low = self.windows_progress.window_rip_low,
            .rip_high = self.windows_progress.window_rip_high,
        };
    }

    fn countWindowsWorkers(self: *const ElfState, status: WindowsGuestThreadStatus) usize {
        var total: usize = 0;
        for (&self.windows_guest_threads) |*thread| {
            if (thread.status == status) total += 1;
        }
        return total;
    }

    /// One bounded, actionable block describing a run that has stopped making
    /// observable progress.  Emitted at most once per escalation step of a
    /// stall episode, and never at all while any axis is still moving.
    fn reportWindowsStall(self: *ElfState, sample: WindowsProgressSample) void {
        const watchdog = &self.windows_progress;
        const frozen_steps = @as(u64, watchdog.frozen_samples) *| watchdog.interval;
        const graphics = &self.windows_graphics;
        log.warn(
            "PE64 STALL: no observable progress for {d} steps ({d} samples) episode={d} step={d} rip=0x{x} last_op={s} active_thread_slot={?d}",
            .{
                frozen_steps,
                watchdog.frozen_samples,
                watchdog.episodes,
                self.executed_steps,
                self.regs.rip,
                @tagName(self.last_decoded_op),
                self.windows_active_guest_thread_slot,
            },
        );
        log.warn(
            "PE64 STALL:   code visited in the last window: [0x{x},0x{x}] span={d} bytes",
            .{ sample.rip_low, sample.rip_high, sample.rip_high -| sample.rip_low },
        );
        log.warn(
            "PE64 STALL:   frozen axes: imports={d} vulkan_calls={d} submits={d} presents={d} messages={d} paint(requests/deliveries)={d}/{d} workers(service/yield/complete/fail)={d}/{d}/{d}/{d} file_io={d}",
            .{
                sample.import_calls,
                sample.graphics_calls,
                graphics.queue_submits,
                graphics.presents,
                sample.message_traffic,
                self.windows_paint_requests,
                self.windows_paint_deliveries,
                self.windows_thread_service_calls,
                self.windows_thread_yields,
                self.windows_thread_completions,
                self.windows_thread_failures,
                sample.file_traffic,
            },
        );
        for (&self.windows_guest_threads, 0..) |*thread, index| {
            if (thread.status == .vacant) continue;
            log.warn(
                "PE64 STALL:   worker[{d}] handle=0x{x} start=0x{x} status={s} steps={d}",
                .{ index, thread.handle, thread.start_routine, @tagName(thread.status), thread.executed_steps },
            );
        }

        // Verdicts.  Each is a rule about Rosetta's own boundaries, so they
        // apply to any PE, and each one names who is accountable rather than
        // just restating the symptom.
        const waiting_workers = self.countWindowsWorkers(.pending) + self.countWindowsWorkers(.runnable);
        const blocked_workers = self.countWindowsWorkers(.blocked);
        if (waiting_workers != 0 and self.windows_active_guest_thread_slot == null) {
            log.warn(
                "PE64 STALL:   VERDICT worker starvation: {d} queued guest thread(s) are runnable and the main thread has not reached a cooperative service point (PAUSE, Wait*, or the message pump) in this window. Rosetta is servicing them now as a backstop; if that unblocks the run, the real fix is a service point on whatever the main thread is spinning on.",
                .{waiting_workers},
            );
        }
        if (blocked_workers != 0) {
            log.warn(
                "PE64 STALL:   VERDICT {d} worker(s) are blocked on Rosetta-owned synchronization objects; SRW contentions={d} unblocks={d}. This is a synchronization wait, not an instruction decode failure.",
                .{ blocked_workers, self.windows_srw_lock_contentions, self.windows_thread_unblocks },
            );
        }
        if (self.windows_paint_requests != 0 and self.windows_paint_deliveries == 0) {
            log.warn(
                "PE64 STALL:   VERDICT paint requests are not being delivered: the guest asked for {d} repaint(s) and the pump generated none. Check that the requesting window has a registered WndProc and that the guest is pumping messages.",
                .{self.windows_paint_requests},
            );
        }
        if (self.windows_paint_deliveries != 0 and graphics.presents == 0) {
            log.warn(
                "PE64 STALL:   VERDICT the guest is being painted but never presents: {d} WM_PAINT delivered, {d} queue submits, 0 presents. The break is inside the guest's painter or the Vulkan surface it acquired, not in message delivery.",
                .{ self.windows_paint_deliveries, graphics.queue_submits },
            );
        }
        if (!self.windows_import_fallbacks.isEmpty()) {
            log.warn(
                "PE64 STALL:   NOTE {d} import name(s) completed through an explicit ABI contract refusal in this run ({d} calls). If the stalled code is waiting on something one of them should have produced, the IMPORT CONTRACT REFUSALS block above names them.",
                .{ self.windows_import_fallbacks.count, self.windows_import_fallbacks.total_calls },
            );
        }
        if (waiting_workers == 0 and self.windows_paint_requests == 0) {
            log.warn(
                "PE64 STALL:   VERDICT the guest is executing inside a {d}-byte code window without crossing any boundary Rosetta instruments. That is either a compute loop or a spin on guest memory; run with ROSETTE_ELF_TRACE_RIP=0x{x} to see what it reads.",
                .{ sample.rip_high -| sample.rip_low, self.regs.rip },
            );
        }
        log.warn(
            "PE64 STALL: this report repeats on an escalating schedule and stops as soon as any axis moves. Set ROSETTE_PE64_STALL_WATCHDOG=0 to silence it, ROSETTE_PE64_STALL_SAMPLE_STEPS / ROSETTE_PE64_STALL_SAMPLES to retune it.",
            .{},
        );
    }

    /// A guest can run its message loop briskly -- so no progress axis looks
    /// frozen -- while every frame it paints stops before the screen.  That is
    /// invisible to the freeze detector by construction, so it gets its own
    /// check: Rosetta has handed the guest N paints and the guest has
    /// presented none of them.
    ///
    /// The claim is only made once there are enough paints for it to mean
    /// something, and then only on an escalating schedule, so a startup that
    /// legitimately paints nothing yet stays silent.
    fn checkWindowsPaintReachesScreen(self: *ElfState) void {
        const delivered = self.windows_paint_deliveries;
        if (delivered < WINDOWS_PAINT_WITHOUT_PRESENT_THRESHOLD) return;
        if (self.windows_graphics.presents != 0) return;
        const watchdog = &self.windows_progress;
        const due = if (watchdog.paint_without_present_reported_at == 0)
            WINDOWS_PAINT_WITHOUT_PRESENT_THRESHOLD
        else
            watchdog.paint_without_present_reported_at *| 4;
        if (delivered < due) return;
        watchdog.paint_without_present_reported_at = delivered;
        log.warn(
            "PE64 PAINT NEVER REACHES THE SCREEN: {d} WM_PAINT delivered, {d} guest paint requests, {d} queue submits, 0 presents, step={d}. Message delivery is working; the break is downstream of the guest's WndProc -- its painter, the surface it acquired, or the swapchain it presents to.",
            .{ delivered, self.windows_paint_requests, self.windows_graphics.queue_submits, self.executed_steps },
        );
    }

    /// Sample the progress axes and, when every one of them has been frozen
    /// for long enough, report it once and unblock any starved worker.
    fn checkWindowsProgress(self: *ElfState) void {
        const watchdog = &self.windows_progress;
        if (!watchdog.enabled or !self.windows_runtime_enabled) return;
        if (self.executed_steps < watchdog.next_sample_step) return;
        watchdog.next_sample_step = self.executed_steps +| watchdog.interval;

        const sample = self.sampleWindowsProgress();
        watchdog.window_rip_low = std.math.maxInt(u64);
        watchdog.window_rip_high = 0;
        self.checkWindowsPaintReachesScreen();

        const frozen = watchdog.have_previous and sample.matches(watchdog.previous);
        watchdog.previous = sample;
        watchdog.have_previous = true;

        if (!frozen) {
            if (watchdog.reported) {
                log.info(
                    "PE64 STALL CLEARED: progress resumed at step {d} rip=0x{x} after {d} frozen sample(s)",
                    .{ self.executed_steps, self.regs.rip, watchdog.frozen_samples },
                );
            }
            watchdog.frozen_samples = 0;
            watchdog.reported = false;
            watchdog.next_report_at = 0;
            return;
        }

        watchdog.frozen_samples +|= 1;
        if (watchdog.frozen_samples < watchdog.threshold) return;
        if (!watchdog.reported) {
            watchdog.episodes +|= 1;
            watchdog.next_report_at = watchdog.frozen_samples;
        }
        if (watchdog.frozen_samples < watchdog.next_report_at) return;

        watchdog.reported = true;
        watchdog.next_report_at = watchdog.frozen_samples *| 2;
        self.reportWindowsStall(sample);

        // Starvation backstop.  The cooperative scheduler normally runs a
        // worker at a PAUSE, a Wait, or a message-pump call.  A main thread
        // that reaches none of those starves every worker forever, and no
        // amount of diagnostics fixes that -- so give the queue a slice here.
        // This is bounded, happens only inside a declared stall, and is
        // reported, so it can never quietly paper over a scheduling defect.
        if (self.windows_active_guest_thread_slot == null and self.nextWindowsGuestThread() != null) {
            const serviced = self.serviceWindowsGuestThreads(WINDOWS_GUEST_THREAD_SERVICE_SLICE);
            watchdog.backstop_services +|= 1;
            log.warn(
                "PE64 STALL:   starvation backstop serviced a queued worker for {d} step(s) (backstop activations: {d})",
                .{ serviced, watchdog.backstop_services },
            );
        }
    }

    /// Every guest instruction this run has interpreted, owner and workers.
    ///
    /// `runWithLimit` counts its own loop iterations, and every worker step
    /// runs inside a `serviceWindowsGuestThreads` call nested in one of them.
    /// So the checkpoint's `steps=` is the *owner's* share, not the run's
    /// work, and once the cooperative scheduler starts giving workers most of
    /// the budget the two diverge by an order of magnitude.
    fn totalInterpretedSteps(self: *const ElfState) u64 {
        // The scheduler's slice totals miss every worker turn served from a
        // wait, a sleep or an idle GetMessage. On 2026-09-14 that was 97% of
        // the run: 6.8B worker instructions against a denominator of 240M,
        // and a thread share of 2843%.
        return self.executed_steps +| self.windows_worker_executed_steps;
    }

    /// What the run bought for its wall clock, and where it went.
    ///
    /// Every other counter in the checkpoint measures the guest. None of them
    /// can tell "the title needs more instructions than this run executed"
    /// from "the title is stuck", and those are the two readings a black
    /// window is always between. This line is the denominator.
    ///
    /// It reports the *total* rate, because the first version of it reported
    /// the owner loop's rate and nothing else. On the 2026-09-12 run that
    /// read as a fall from 2.5M to 140K steps/s and looked like a runaway
    /// table; the real rate was a steady 1.5M instructions/s, and what had
    /// actually changed was that the workers went from ~0% of the budget to
    /// ~90% of it. A denominator that measures one thread of a cooperative
    /// scheduler is not a denominator.
    fn logStepBudget(self: *ElfState, steps: u64) void {
        _ = steps;
        const now = monotonicNanoseconds();
        if (now == 0) return;
        const interpreted = self.totalInterpretedSteps();
        if (self.run_first_checkpoint_nanos == 0) {
            self.run_first_checkpoint_nanos = now;
            self.run_last_checkpoint_nanos = now;
            self.run_last_checkpoint_steps = interpreted;
            return;
        }
        const total_nanos = now -| self.run_first_checkpoint_nanos;
        const window_nanos = now -| self.run_last_checkpoint_nanos;
        const worker_steps = interpreted -| self.executed_steps;
        const window_steps = interpreted -| self.run_last_checkpoint_steps;
        self.run_last_checkpoint_nanos = now;
        self.run_last_checkpoint_steps = interpreted;
        if (total_nanos == 0) return;

        const nanos_per_second: u64 = 1_000_000_000;
        // A 1e9 multiplier saturates u64 after 18.4B instructions. The latest
        // run retired 25.7B, so its printed lifetime rate falsely fell to 10M
        // while the window remained 13-14M. Widen before multiplying.
        const total_rate = instructionRate(interpreted, total_nanos);
        const window_rate = if (window_nanos == 0) total_rate else instructionRate(window_steps, window_nanos);
        const worker_percent = if (interpreted == 0) 0 else @divTrunc(worker_steps *| 100, interpreted);
        const pump_nanos = self.windows_graphics.event_pump_nanos;
        const pump_percent = if (total_nanos == 0) 0 else @divTrunc(pump_nanos *| 100, total_nanos);
        const guest_nanos = @divTrunc(self.guest_clock.ticks *| nanos_per_second, WINDOWS_GUEST_CLOCK_HZ);
        const dilation_tenths = if (total_nanos == 0) 0 else @divTrunc(guest_nanos *| 10, total_nanos);
        log.info("PE64 STEP BUDGET: interpreted={d} (owner={d} workers={d}, {d}% of the run is worker threads) elapsed={d}s window={d} in {d}ms rate(window/run)={d}/{d} instructions/s host_event_pump=serviced={d} requests={d} stride_declined={d} {d}ms ({d}%); guest_clock={d}s of {d}s real (x{d}.{d} dilation, source={s}); the owner's own step counter is not the run's work, so read this rate and not the checkpoint's steps=", .{
            interpreted,
            self.executed_steps,
            worker_steps,
            worker_percent,
            @divTrunc(total_nanos, nanos_per_second),
            window_steps,
            @divTrunc(window_nanos, 1_000_000),
            window_rate,
            total_rate,
            self.windows_graphics.event_pump_calls,
            self.windows_graphics.event_pump_calls +| self.windows_graphics.event_pump_skips,
            self.windows_graphics.event_pump_skips,
            @divTrunc(pump_nanos, 1_000_000),
            pump_percent,
            // What the guest believes has elapsed, against what has. Every
            // timed wait the guest makes is denominated in this clock, so a
            // large gap either way is the reason a frame limiter, a timeout
            // or a watchdog behaves nothing like it does on hardware.
            @divTrunc(self.guest_clock.ticks, WINDOWS_GUEST_CLOCK_HZ),
            @divTrunc(total_nanos, nanos_per_second),
            // Reported to one decimal, in integers: a dilation the run does
            // not state is a dilation nobody accounts for, and it is the
            // multiplier on how often every repeating guest timer runs.
            @divTrunc(dilation_tenths, 10),
            dilation_tenths % 10,
            if ((self.guest_clock.source == .retired_instructions))
                "retired instructions (ROSETTE_GUEST_CLOCK=instructions): a guest millisecond is a thousand instructions, so every guest timer fires far more often per unit of work than on hardware"
            else if (self.guest_clock.host_unavailable)
                "host monotonic clock, with gaps filled from instruction count because the host clock could not be read"
            else
                "host monotonic clock: a guest millisecond is a real millisecond, so guest timers fire at the rate they were written for",
        });
        self.reportXeniaClock(now);
    }

    fn reportXeniaClock(self: *ElfState, now: u64) void {
        const snapshot = xenia_clock_probe.Snapshot.read(self, self.xenia_clock.symbols) orelse {
            log.info("PE64 XENIA TIME PLANE: status=unavailable required_clock_symbols_or_bytes_missing=true; Windows guest_clock alone cannot prove Xbox clock progress", .{});
            return;
        };
        const observation = self.xenia_clock.observe(snapshot, now);
        log.info("PE64 XENIA TIME PLANE: status={s} frequency={d} ticks={d} host_ticks={d} ratio={d}/{d} scalar={d} no_scaling={} raw_source={} window(host_ms/xbox_ms)={d}/{d} xbox_speed={d}.{d:0>3} host_tick_delta={d}; read_only=true; stalled means inspect UpdateGuestClock/lock owner, not synthesize time or interrupts", .{
            @tagName(observation.status),      snapshot.frequency,          snapshot.guest_ticks, snapshot.host_ticks,
            snapshot.ratio_num,                snapshot.ratio_den,          snapshot.scalar,      snapshot.no_scaling,
            snapshot.raw_source,               observation.host_ms,         observation.guest_ms, observation.speed_permille / 1000,
            observation.speed_permille % 1000, observation.host_tick_delta,
        });
    }

    /// The run's pulse, taken on every instruction executed, not the owner's.
    ///
    /// Every periodic report was keyed to the owner's step counter. Once a
    /// title runs, the owner is mostly the scheduler serving workers: on
    /// 2026-09-14 it advanced 24M steps in the last seven minutes while the
    /// workers ran 6.8B, so the log fell silent at owner step 200M and a run
    /// executing sixteen million instructions a second read as one that had
    /// stopped.
    fn logRunHeartbeat(self: *ElfState, steps: u64) void {
        const interpreted = steps +| self.windows_worker_executed_steps;
        self.run_next_heartbeat_instructions = interpreted +| WINDOWS_RUN_HEARTBEAT_INSTRUCTIONS;
        self.run_heartbeats +|= 1;
        log.info("PE64 HEARTBEAT: #{d} interpreted={d} owner_steps={d} workers={d}; one every {d} instructions whichever thread runs them, because the owner's checkpoint stops arriving once the owner is mostly serving workers", .{
            self.run_heartbeats,
            interpreted,
            steps,
            self.windows_worker_executed_steps,
            WINDOWS_RUN_HEARTBEAT_INSTRUCTIONS,
        });
        self.logStepBudget(steps);
        self.logGuestThreadShare();
        self.logGuestSchedulingHealth();
        self.reportWindowsTimedWaitSites(4);
        self.reportWindowsBlockedDiagnostics(8);
        self.reportWindowsWaitFindings();
        self.reportRunChainsIfChanged(steps);
    }

    /// The denominator and the scheduler's health at exit. The periodic
    /// copies stop at the last checkpoint, and a run ended from its window
    /// never reaches another one.
    pub fn reportRunThroughput(self: *ElfState) void {
        self.logStepBudget(self.executed_steps);
        self.logGuestThreadShare();
        self.logGuestSchedulingHealth();
        self.reportWindowsTimedWaitSites(WINDOWS_TIMED_WAIT_SITE_CAPACITY);
        // The heartbeat is intentionally bounded; the final report is not.
        // A live wait graph is evidence, so do not discard the last two
        // blocked workers merely because an older sample cap was sixteen.
        self.reportWindowsBlockedDiagnostics(self.windows_guest_threads.len);
        self.reportWindowsWaitCost();
        self.reportWindowsWaitFindings();
        self.reportWindowsUpstreamWaitPriority();
    }

    /// The boundaries that decide whether a worker's turn is work or waste,
    /// and the tables that bound how many threads and kernel objects a title
    /// can hold.
    fn logGuestSchedulingHealth(self: *const ElfState) void {
        var threads_live: usize = 0;
        var threads_created: usize = 0;
        var threads_completed: usize = 0;
        var threads_failed: usize = 0;
        var threads_vacant: usize = 0;
        for (&self.windows_guest_threads) |*thread| {
            switch (thread.status) {
                .vacant => threads_vacant += 1,
                .completed => {
                    threads_created += 1;
                    threads_completed += 1;
                },
                .failed => {
                    threads_created += 1;
                    threads_failed += 1;
                },
                else => {
                    threads_created += 1;
                    if (isLiveWindowsGuestThread(thread.status)) threads_live += 1;
                },
            }
        }
        var wait_objects_live: usize = 0;
        for (self.windows_wait_objects[0..self.windows_wait_object_high_water]) |*object| {
            if (object.handle != 0) wait_objects_live += 1;
        }
        log.info("PE64 guest scheduling health: timed_condition_waits={d} immediate_timeouts={d} deadline_timeouts={d} nt_delay(parks/yields)={d}/{d} sleep_parks={d} clock_poll_yields={d} slice_yields={d} threads(live/capacity/reused/refused)={d}/{d}/{d}/{d} wait_objects(live/high_water/capacity/freed/refused)={d}/{d}/{d}/{d}/{d} timers(created/set/fired/armed/routines_not_delivered)={d}/{d}/{d}/{d}/{d} thread_stacks_released={d} spin(slices/turns_given)={d}/{d}; a refused thread or wait object is a fatal point, and a high water near capacity is the table the next title outgrows", .{
            self.windows_condition_timed_waits,
            self.windows_condition_timed_immediate,
            self.windows_condition_timeouts,
            self.windows_nt_delay_parks,
            self.windows_nt_delay_yields,
            self.windows_guest_sleep_parks,
            self.windows_clock_poll_yields,
            self.windows_guest_slice_yields,
            threads_live,
            self.windows_guest_threads.len,
            self.windows_thread_slots_recycled,
            self.windows_thread_table_full,
            wait_objects_live,
            self.windows_wait_object_high_water,
            self.windows_wait_objects.len,
            self.windows_wait_objects_freed,
            self.windows_wait_object_table_full,
            self.windows_timers_created,
            self.windows_timer_sets,
            self.windows_timer_fires,
            self.windows_armed_timers,
            self.windows_timer_completion_routines,
            self.windows_thread_stacks_released,
            self.windows_spin_slices,
            self.windows_spin_turns_given,
        });
        log.info("PE64 guest thread lifecycle: created={d} live={d} completed={d} failed={d} vacant={d} capacity={d}; completed is a normal one-shot exit, failed/refused is the missing-thread signal", .{
            threads_created,
            threads_live,
            threads_completed,
            threads_failed,
            threads_vacant,
            self.windows_guest_threads.len,
        });
    }

    fn logGraphicsProgress(self: *ElfState, steps: u64) void {
        self.logStepBudget(steps);
        self.logGuestThreadShare();
        self.logGuestSchedulingHealth();
        self.rollGuestThreadCodeWindows();
        var vacant: u32 = 0;
        var pending: u32 = 0;
        var runnable: u32 = 0;
        var running: u32 = 0;
        var blocked: u32 = 0;
        var completed: u32 = 0;
        var failed: u32 = 0;
        for (&self.windows_guest_threads) |*thread| {
            switch (thread.status) {
                .vacant => vacant += 1,
                .pending => pending += 1,
                .runnable => runnable += 1,
                .running => running += 1,
                .blocked => blocked += 1,
                .completed => completed += 1,
                .failed => failed += 1,
            }
        }
        const active_thread = if (self.windows_active_guest_thread_slot) |index|
            self.windows_guest_threads[index].handle
        else
            0;
        log.info("PE64 GUEST CLOCK/VBLANK: clock_ticks={d} owner_steps={d} worker_steps={d} vblanks={d} (via {s}) scheduler_calls={d} active_thread=0x{x}; worker-side time must advance independently of the owner loop", .{
            self.guest_clock.ticks,
            self.executed_steps,
            self.windows_thread_service_steps,
            self.guestMilestoneStageHits("_ZN2xe3gpu14GraphicsSystem10MarkVblankEv"),
            self.vblankWitnessName(),
            self.windows_thread_service_calls,
            active_thread,
        });
        log.info("PE64 graphics progress: steps={d} rip=0x{x} last_op={s} active_thread=0x{x} workers(vacant/pending/runnable/running/completed/failed)={d}/{d}/{d}/{d}/{d}/{d} vk_calls={d} native_vk_calls={d} native_vk_pre_ready={d} native_vk_failures={d} commands={d} submits={d} presents={d} rijndael_accel_calls={d} heap_records={d} heap_live={d} heap_capacity={d} heap_growth_failures={d} heap_untracked={d} phase={s} last_call={s} ordering_violations={d} unmodeled={d}", .{
            steps,
            self.regs.rip,
            @tagName(self.last_decoded_op),
            active_thread,
            vacant,
            pending,
            runnable,
            running,
            completed,
            failed,
            self.windows_graphics.vulkan_calls,
            self.windows_graphics.native_vulkan_calls,
            self.windows_graphics.native_vulkan_pre_ready_calls,
            self.windows_graphics.native_vulkan_failures,
            self.windows_graphics.command_calls,
            self.windows_graphics.queue_submits,
            self.windows_graphics.presents,
            self.xenia_rijndael_accelerated_calls,
            self.windows_heap_allocation_count,
            self.windows_heap_allocations_live,
            self.windows_heap_allocations.len,
            self.windows_heap_provenance_growth_failures,
            self.windows_heap_provenance_untracked_allocations,
            @tagName(self.windows_graphics.phase),
            std.mem.sliceTo(&self.windows_graphics.last_call, 0),
            self.windows_graphics.ordering_violations,
            self.windows_graphics.unmodeled_calls,
        });
        log.info("PE64 GPU/heap lifetime: gpu_wake_repairs={d} gpu_wake_repair_misses={d} heap_records={d} heap_live={d} heap_free={d} heap_reused={d} heap_capacity={d} heap_growth_failures={d} heap_free_growth_failures={d} heap_untracked={d}", .{
            self.windows_gpu_write_pointer_wake_repairs,
            self.windows_gpu_write_pointer_wake_repair_misses,
            self.windows_heap_allocation_count,
            self.windows_heap_allocations_live,
            self.windows_heap_free_count,
            self.windows_heap_reused_allocations,
            self.windows_heap_allocations.len,
            self.windows_heap_provenance_growth_failures,
            self.windows_heap_free_list_growth_failures,
            self.windows_heap_provenance_untracked_allocations,
        });
        // The line above says where the guest is; this one says what it is
        // doing there. Without it a reader has a hexadecimal address and no
        // way to tell an expensive computation from a stall.
        self.sampleGuestFrontier();
        var frontier_text: [320]u8 = undefined;
        log.info("PE64 guest frontier: steps={d} rip=0x{x} {s} named_symbols={d} image_coverage={d}%", .{
            steps,
            self.regs.rip,
            self.describeGuestFrontier(self.regs.rip, &frontier_text),
            self.guest_symbol_count,
            self.guest_symbol_coverage_percent,
        });
        log.info("PE64 guest scheduler: enabled={} quantum={d} slice={d} explicit_stride={d} scheduler_calls={d} scheduler_steps={d} explicit_calls={d} explicit_steps={d} explicit_skips={d} worker_calls={d} worker_yields={d} backstop_calls={d} blocked={d} unblocked={d}", .{
            self.windows_scheduler.enabled,
            self.windows_scheduler.quantum,
            self.windows_scheduler.slice,
            self.windows_scheduler.explicit_stride,
            self.windows_scheduler.service_calls,
            self.windows_scheduler.serviced_steps,
            self.windows_scheduler.explicit_service_calls,
            self.windows_scheduler.explicit_serviced_steps,
            self.windows_scheduler.explicit_service_skips,
            self.windows_thread_service_calls,
            self.windows_thread_yields,
            self.windows_progress.backstop_services,
            self.windows_thread_blocks,
            self.windows_thread_unblocks,
        });
        log.info("PE64 guest synchronization: blocked={d} unblocked={d} lock_contentions={d} release_mismatches={d} condition_hooks={d} condition_waits={d} condition_blocks={d} condition_resumes={d} condition_signals={d} condition_broadcasts={d} condition_unblocks={d} wait_calls={d} wait_blocks={d} wait_resumes={d} wait_unblocks={d} wait_timeouts={d} wait_unknown={d} wait_owner_yields={d} wait_compat_yields={d} srw_compat_acquires={d} wait_multiple(calls/blocks/owner_yields)={d}/{d}/{d} wait_unknown_faults={d} get_message_idle(turns/steps)={d}/{d} crt_unreadable={d}", .{
            blocked,
            self.windows_thread_unblocks,
            self.windows_srw_lock_contentions,
            self.windows_srw_lock_release_mismatches,
            self.windows_condition_hook_events,
            self.windows_condition_wait_calls,
            self.windows_condition_wait_blocks,
            self.windows_condition_wait_resumes,
            self.windows_condition_signal_calls,
            self.windows_condition_broadcast_calls,
            self.windows_condition_unblocks,
            self.windows_wait_calls,
            self.windows_wait_blocks,
            self.windows_wait_resumes,
            self.windows_wait_unblocks,
            self.windows_wait_timeouts,
            self.windows_wait_unknown_objects,
            self.windows_wait_owner_yields,
            self.windows_wait_compatibility_yields,
            self.windows_srw_compatibility_acquires,
            self.windows_wait_multiple_calls,
            self.windows_wait_multiple_blocks,
            self.windows_wait_multiple_owner_yields,
            self.windows_wait_unknown_faults,
            self.windows_get_message_idle_turns,
            self.windows_get_message_idle_steps,
            self.windows_crt_unreadable_pointers,
        });
        self.reportWindowsBlockedDiagnostics(16);
    }

    fn logGraphicsStop(self: *const ElfState) void {
        var vacant: u32 = 0;
        var pending: u32 = 0;
        var runnable: u32 = 0;
        var running: u32 = 0;
        var blocked: u32 = 0;
        var completed: u32 = 0;
        var failed: u32 = 0;
        for (&self.windows_guest_threads) |*thread| {
            switch (thread.status) {
                .vacant => vacant += 1,
                .pending => pending += 1,
                .runnable => runnable += 1,
                .running => running += 1,
                .blocked => blocked += 1,
                .completed => completed += 1,
                .failed => failed += 1,
            }
        }
        const active_thread = if (self.windows_active_guest_thread_slot) |index|
            self.windows_guest_threads[index].handle
        else
            0;
        log.info("PE64 GUEST CLOCK/VBLANK: clock_ticks={d} owner_steps={d} worker_steps={d} vblanks={d} (via {s}) scheduler_calls={d} active_thread=0x{x}", .{
            self.guest_clock.ticks,
            self.executed_steps,
            self.windows_thread_service_steps,
            self.guestMilestoneStageHits("_ZN2xe3gpu14GraphicsSystem10MarkVblankEv"),
            self.vblankWitnessName(),
            self.windows_thread_service_calls,
            active_thread,
        });
        log.info("PE64 execution stop: terminated={} faulted={} reason={s} exit=0x{x} steps={d} rip=0x{x} last_op={s} active_thread=0x{x} workers(vacant/pending/runnable/running/completed/failed)={d}/{d}/{d}/{d}/{d}/{d} vk_calls={d} native_vk_calls={d} native_vk_pre_ready={d} native_vk_failures={d} commands={d} submits={d} presents={d} rijndael_accel_calls={d} rijndael_accel_failures={d} heap_records={d} heap_capacity={d} heap_growth_failures={d} heap_untracked={d} phase={s} last_call={s} last_failure={s} ui_quit={} ui_quit_code=0x{x}", .{
            self.terminated,
            self.faulted,
            @tagName(self.termination_reason),
            self.exit_code,
            self.executed_steps,
            self.regs.rip,
            @tagName(self.last_decoded_op),
            active_thread,
            vacant,
            pending,
            runnable,
            running,
            completed,
            failed,
            self.windows_graphics.vulkan_calls,
            self.windows_graphics.native_vulkan_calls,
            self.windows_graphics.native_vulkan_pre_ready_calls,
            self.windows_graphics.native_vulkan_failures,
            self.windows_graphics.command_calls,
            self.windows_graphics.queue_submits,
            self.windows_graphics.presents,
            self.xenia_rijndael_accelerated_calls,
            self.xenia_rijndael_accelerator_failures,
            self.windows_heap_allocation_count,
            self.windows_heap_allocations.len,
            self.windows_heap_provenance_growth_failures,
            self.windows_heap_provenance_untracked_allocations,
            @tagName(self.windows_graphics.phase),
            std.mem.sliceTo(&self.windows_graphics.last_call, 0),
            std.mem.sliceTo(&self.windows_graphics.last_failure, 0),
            self.windows_ui_quit_requested,
            self.windows_ui_quit_code,
        });
        log.info("PE64 GPU/heap lifetime: gpu_wake_repairs={d} gpu_wake_repair_misses={d} heap_records={d} heap_live={d} heap_free={d} heap_reused={d} heap_capacity={d} heap_growth_failures={d} heap_free_growth_failures={d} heap_untracked={d}", .{
            self.windows_gpu_write_pointer_wake_repairs,
            self.windows_gpu_write_pointer_wake_repair_misses,
            self.windows_heap_allocation_count,
            self.windows_heap_allocations_live,
            self.windows_heap_free_count,
            self.windows_heap_reused_allocations,
            self.windows_heap_allocations.len,
            self.windows_heap_provenance_growth_failures,
            self.windows_heap_free_list_growth_failures,
            self.windows_heap_provenance_untracked_allocations,
        });
        self.logWindowsGuestFailurePointSummary();
        log.info("PE64 Xenia accelerators: rijndael_calls={d} rijndael_failures={d} sha1_blocks={d} sha1_failures={d} sha1_feed_spans={d} sha1_feed_bytes={d} sha1_feed_declines={d} sha1_feed_steps_saved~={d}", .{
            self.xenia_rijndael_accelerated_calls,
            self.xenia_rijndael_accelerator_failures,
            self.xenia_sha1_accelerated_blocks,
            self.xenia_sha1_accelerator_failures,
            self.xenia_sha1_feed_spans,
            self.xenia_sha1_feed_bytes,
            self.xenia_sha1_feed_declines,
            // The interpreted loop is eleven instructions per byte; stating
            // the estimate keeps the accelerator's value measurable instead
            // of assumed.
            self.xenia_sha1_feed_bytes *| 11,
        });
        log.info("PE64 Xenia metadata table accelerator: strings={d} failures={d}", .{
            self.xenia_tabulate_accelerated_strings,
            self.xenia_tabulate_accelerator_failures,
        });
        log.info("PE64 Xenia kernel SHA1 feed: spans={d} bytes={d} estimated_instructions_avoided~={d} max_native_turn_bytes=262144; hash and final guest iterations are preserved, not bypassed", .{
            self.xenia_sha1_kernel_feed_spans,
            self.xenia_sha1_kernel_feed_bytes,
            self.xenia_sha1_kernel_feed_bytes *| 11,
        });
        log.info("PE64 generated code: instruction_fetches={d}", .{self.windows_generated_code_fetches});
        log.info("PE64 DECODE CACHE: entries={d} hits={d} generation_rearms={d} fresh_decodes={d} address_collisions={d} hit_percent={d}; full source address/kind/index/generation checked; mapped_ranges={d} range_mutations={d} lookup=max_8_base_comparisons", .{
            PE_DECODE_CACHE_ENTRIES,          self.decode_cache_hits,               self.decode_cache_rearms,
            self.decode_cache_misses,         self.decode_cache_collisions,         windowsTimedWaitPercent(self.decode_cache_hits +| self.decode_cache_rearms, self.decode_cache_hits +| self.decode_cache_rearms +| self.decode_cache_misses),
            self.windows_mapped_ranges.count, self.windows_mapped_ranges.mutations,
        });
        log.info("PE64 guest scheduler: enabled={} quantum={d} slice={d} explicit_stride={d} scheduler_calls={d} scheduler_steps={d} explicit_calls={d} explicit_steps={d} explicit_skips={d} worker_calls={d} worker_yields={d} backstop_calls={d} blocked={d} unblocked={d}", .{
            self.windows_scheduler.enabled,
            self.windows_scheduler.quantum,
            self.windows_scheduler.slice,
            self.windows_scheduler.explicit_stride,
            self.windows_scheduler.service_calls,
            self.windows_scheduler.serviced_steps,
            self.windows_scheduler.explicit_service_calls,
            self.windows_scheduler.explicit_serviced_steps,
            self.windows_scheduler.explicit_service_skips,
            self.windows_thread_service_calls,
            self.windows_thread_yields,
            self.windows_progress.backstop_services,
            self.windows_thread_blocks,
            self.windows_thread_unblocks,
        });
        log.info("PE64 guest synchronization: blocked={d} unblocked={d} lock_contentions={d} release_mismatches={d} condition_hooks={d} condition_waits={d} condition_blocks={d} condition_resumes={d} condition_signals={d} condition_broadcasts={d} condition_unblocks={d} wait_calls={d} wait_blocks={d} wait_resumes={d} wait_unblocks={d} wait_timeouts={d} wait_unknown={d} wait_owner_yields={d} wait_compat_yields={d} srw_compat_acquires={d} wait_multiple(calls/blocks/owner_yields)={d}/{d}/{d} wait_unknown_faults={d} get_message_idle(turns/steps)={d}/{d} crt_unreadable={d}", .{
            blocked,
            self.windows_thread_unblocks,
            self.windows_srw_lock_contentions,
            self.windows_srw_lock_release_mismatches,
            self.windows_condition_hook_events,
            self.windows_condition_wait_calls,
            self.windows_condition_wait_blocks,
            self.windows_condition_wait_resumes,
            self.windows_condition_signal_calls,
            self.windows_condition_broadcast_calls,
            self.windows_condition_unblocks,
            self.windows_wait_calls,
            self.windows_wait_blocks,
            self.windows_wait_resumes,
            self.windows_wait_unblocks,
            self.windows_wait_timeouts,
            self.windows_wait_unknown_objects,
            self.windows_wait_owner_yields,
            self.windows_wait_compatibility_yields,
            self.windows_srw_compatibility_acquires,
            self.windows_wait_multiple_calls,
            self.windows_wait_multiple_blocks,
            self.windows_wait_multiple_owner_yields,
            self.windows_wait_unknown_faults,
            self.windows_get_message_idle_turns,
            self.windows_get_message_idle_steps,
            self.windows_crt_unreadable_pointers,
        });
    }

    /// Open the host output device for a guest wave format.
    ///
    /// A refusal is not an error the caller escalates: the guest's wave device
    /// stays open on the clocked null sink and the audio report says which
    /// sink is in use. Claiming the open failed would stop a guest that can
    /// run perfectly well without a speaker.
    pub fn openWindowsHostAudio(self: *ElfState, sample_rate: u32, channels: u32, bits_per_sample: u32, is_float: bool) bool {
        const hooks = self.windows_audio_hooks;
        const open = hooks.open orelse return false;
        self.windows_audio_host_open_attempts +|= 1;
        const opened = open(hooks.context, sample_rate, channels, bits_per_sample, @intFromBool(is_float)) != 0;
        if (!opened) {
            self.windows_audio_host_open_failures +|= 1;
            log.info("PE64 Windows audio: host device refused format rate={d} channels={d} bits={d} float={}; the guest keeps its clocked null sink", .{
                sample_rate,
                channels,
                bits_per_sample,
                is_float,
            });
            return false;
        }
        self.windows_audio_host_connected = true;
        log.info("PE64 Windows audio: host device opened rate={d} channels={d} bits={d} float={}; guest frames are now audible", .{
            sample_rate,
            channels,
            bits_per_sample,
            is_float,
        });
        return true;
    }

    /// Copy one guest wave buffer into the host device.
    pub fn submitWindowsHostAudio(self: *ElfState, data: u64, length: u32) void {
        if (!self.windows_audio_host_connected or length == 0) return;
        const hooks = self.windows_audio_hooks;
        const submit = hooks.submit orelse return;
        const bytes = self.guestMemoryConst(data, length) orelse return;
        const accepted = submit(hooks.context, bytes.ptr, length);
        self.windows_audio_host_bytes_accepted +|= accepted;
        self.windows_audio_host_bytes_dropped +|= (length -| accepted);
    }

    pub fn closeWindowsHostAudio(self: *ElfState) void {
        if (!self.windows_audio_host_connected) return;
        const hooks = self.windows_audio_hooks;
        if (hooks.close) |close| close(hooks.context);
        self.windows_audio_host_connected = false;
    }

    /// What is consuming the guest's frames, proved rather than assumed.
    ///
    /// A device that was opened and has never served a callback is not a host
    /// device: from every counter the guest can see it is indistinguishable
    /// from the null sink, and only the callback count separates them.
    fn windowsAudioSinkLabel(self: *const ElfState) []const u8 {
        if (!self.windows_audio_host_connected) return "clocked_null_sink";
        const hooks = self.windows_audio_hooks;
        const served = if (hooks.callbacks_served) |callbacks| callbacks(hooks.context) else 0;
        return if (served != 0) "host_device" else "opened_but_silent";
    }

    /// The ordered set of things that must happen before a guest frame is
    /// audible, and which of them this run reached.
    ///
    /// Silence is the least legible failure in the runtime: every stage
    /// produces silence when it breaks, and silence when the stage above it
    /// breaks, so the symptom carries no information. This is the same
    /// earliest-broken-stage rule `lib/audio` applies to the modelled mixer,
    /// applied to the path a Windows guest actually takes.
    fn audioChainStages(self: *const ElfState) [AUDIO_STAGE_COUNT]ChainStage {
        const hooks = self.windows_audio_hooks;
        var host_played: u64 = 0;
        var host_dropped: u64 = 0;
        var host_underruns: u64 = 0;
        if (hooks.transfer_counters) |counters| {
            counters(hooks.context, &host_played, &host_dropped, &host_underruns);
        }
        const served = if (hooks.callbacks_served) |callbacks| callbacks(hooks.context) else 0;
        const m = struct {
            const setup = "_ZN2xe3apu11AudioSystem5SetupEPNS_6kernel11KernelStateE";
            const register = "_ZN2xe3apu11AudioSystem14RegisterClientEjjPy";
            const driver = "_ZN2xe3apu3sdl14SDLAudioDriver10InitializeEv";
            const submit = "_ZN2xe3apu11AudioSystem11SubmitFrameEyPf";
        };

        return [AUDIO_STAGE_COUNT]ChainStage{
            .{
                .name = "apu_backend_created",
                .owner = "xenia:emulator",
                .met = self.guestMilestoneHitsNamed(m.setup) != 0,
                .evidence = "AudioSystem_Setup_entries",
                .value = self.guestMilestoneHitsNamed(m.setup),
                .observable = self.guestMilestoneArmed(m.setup),
            },
            .{
                // Xenia touches no host audio API until the guest asks for a
                // port: the driver is created from RegisterClient, and
                // SDL_InitSubSystem lives inside the driver. A run with no
                // WinMM traffic and nothing here is a title that has not
                // asked for sound, not a backend Rosette failed to provide -
                // and the old chain blamed the apu factory for it.
                .name = "title_registered_audio_client",
                .owner = "guest-title",
                .met = self.guestMilestoneHitsNamed(m.register) != 0 or
                    self.guest_kernel_calls.witnessHitsFor(m.register) != 0,
                .evidence = "RegisterClient_entries",
                .value = self.guestMilestoneHitsNamed(m.register),
                .observable = self.guestMilestoneArmed(m.register),
                .witness = witnessLabel(m.register),
                .witness_value = self.guest_kernel_calls.witnessHitsFor(m.register),
                .witness_armed = self.guest_kernel_calls.witnessArmedFor(m.register),
                .when_unmet = "the title has not asked the kernel for an audio port. Xenia creates no driver and calls no host audio API until it does, so nothing here is Rosette's yet",
            },
            .{
                .name = "sdl_driver_initialized",
                .owner = "xenia:audio-driver",
                .met = self.guestMilestoneHitsNamed(m.driver) != 0,
                .evidence = "SDLAudioDriver_Initialize_entries",
                .value = self.guestMilestoneHitsNamed(m.driver),
                .observable = self.guestMilestoneArmed(m.driver),
            },
            .{
                .name = "backend_reached_rosette",
                .owner = "xenia:apu-factory",
                .met = self.windows_audio_import_calls != 0,
                .evidence = "winmm_import_calls",
                .value = self.windows_audio_import_calls,
            },
            .{
                .name = "guest_wave_device_open",
                .owner = "xenia:audio-driver",
                .met = self.windows_audio_open_successes != 0,
                .evidence = "wave_opens",
                .value = self.windows_audio_open_successes,
            },
            .{
                .name = "host_device_open",
                .owner = "rosette:coreaudio",
                .met = self.windows_audio_host_connected,
                .evidence = "host_open_attempts",
                .value = self.windows_audio_host_open_attempts,
            },
            .{
                .name = "title_submitted_pcm",
                .owner = "guest-title",
                .met = self.guestMilestoneHitsNamed(m.submit) != 0 or
                    self.guest_kernel_calls.witnessHitsFor(m.submit) != 0,
                .evidence = "SubmitFrame_entries",
                .value = self.guestMilestoneHitsNamed(m.submit),
                .observable = self.guestMilestoneArmed(m.submit),
                .witness = witnessLabel(m.submit),
                .witness_value = self.guest_kernel_calls.witnessHitsFor(m.submit),
                .witness_armed = self.guest_kernel_calls.witnessArmedFor(m.submit),
                .when_unmet = "the title has produced no PCM. Frames can still be silent once it does, but nothing before this point can be",
            },
            .{
                .name = "guest_wrote_frames",
                .owner = "xenia:audio-worker",
                .met = self.windows_audio_write_calls != 0,
                .evidence = "wave_writes",
                .value = self.windows_audio_write_calls,
            },
            .{
                .name = "frames_carry_signal",
                .owner = "guest-title",
                .met = self.windows_audio_nonzero_buffers != 0,
                .evidence = "nonzero_buffers",
                .value = self.windows_audio_nonzero_buffers,
            },
            .{
                .name = "host_device_asked_for_audio",
                .owner = "rosette:coreaudio",
                .met = served != 0,
                .evidence = "device_callbacks",
                .value = served,
            },
            .{
                .name = "device_bytes_delivered",
                .owner = "rosette:coreaudio",
                .met = host_played != 0,
                .evidence = "device_played_bytes",
                .value = host_played,
            },
        };
    }

    /// The earliest unmet audio stage, or null when frames reached a device
    /// that consumed them.
    pub fn audioChainWall(self: *const ElfState) ?ChainStage {
        for (self.audioChainStages()) |stage| {
            if (!stage.observable) continue;
            if (!stage.met) return stage;
        }
        return null;
    }

    pub fn reportAudioChain(self: *const ElfState) void {
        const hooks = self.windows_audio_hooks;
        var host_played: u64 = 0;
        var host_dropped: u64 = 0;
        var host_underruns: u64 = 0;
        if (hooks.transfer_counters) |counters| {
            counters(hooks.context, &host_played, &host_dropped, &host_underruns);
        }
        const stages = self.audioChainStages();
        var met_count: usize = 0;
        var observable_count: usize = 0;
        var first_unmet: ?usize = null;
        for (stages, 0..) |stage, index| {
            if (!stage.observable) continue;
            observable_count += 1;
            if (stage.met) {
                met_count += 1;
            } else if (first_unmet == null) {
                first_unmet = index;
            }
        }

        log.info("PE64 AUDIO CHAIN: {d}/{d} observable stages met ({d} not observable in this image); sink={s}", .{
            met_count,
            observable_count,
            stages.len - observable_count,
            self.windowsAudioSinkLabel(),
        });
        const audio_policy = if (self.windows_audio_environment_queries == 0)
            "not_queried"
        else if (self.windows_audio_environment_driver.len != 0)
            self.windows_audio_environment_driver
        else
            "unset_or_unrecognized";
        log.info("PE64 AUDIO CHAIN: completions waveOutWrite={d} WOM_DONE_callbacks={d} callback_failures={d} nonzero_buffers={d} pacing_waits={d} ({d} requested writer-park ms, NOT host-blocked ms); cooperative pacing leaves other workers runnable. A CALLBACK_FUNCTION client needs WOM_DONE before writing again", .{
            self.windows_audio_write_calls,
            self.windows_audio_callback_dispatches,
            self.windows_audio_callback_failures,
            self.windows_audio_nonzero_buffers,
            self.windows_audio_pacing_waits,
            self.windows_audio_pacing_wait_ms,
        });
        const xma_writes = self.guestMilestoneHitsNamed("_ZN2xe3apu10XmaDecoder13WriteRegisterEjj");
        const xma_work = self.guestMilestoneHitsNamed("_ZN2xe3apu10XmaContext4WorkEv");
        const title_signal_verdict: []const u8 = if (self.audio_title_frames_checked == 0)
            "no frame the title submitted was readable, so the title's side of the signal is unmeasured"
        else if (self.audio_title_frames_nonzero == 0 and xma_writes == 0)
            "all sampled readable title frames are silence and no XMA decoder register entry was observed; nonsilent title audio has not been proven, not a lost host-device signal"
        else if (self.audio_title_frames_nonzero == 0 and xma_work == 0)
            "the title wrote XMA decoder registers and no XMA context ever did work, so its compressed audio is not being decoded and its frames are silence"
        else if (self.audio_title_frames_nonzero == 0)
            "XMA contexts decode, and all sampled readable title frames are still silence"
        else if (self.windows_audio_nonzero_buffers == 0)
            "the title submits audible frames and every buffer written to WinMM is silence: the signal is lost between Xenia's SDL driver and waveOutWrite"
        else
            "the title's frames carry signal and so do the buffers written to the device";
        log.info("PE64 AUDIO CHAIN: title signal frames_checked={d} nonzero={d} first_nonzero_step={d} xma_register_writes={d} xma_context_work={d}; {s}", .{
            self.audio_title_frames_checked,
            self.audio_title_frames_nonzero,
            self.audio_title_first_nonzero_step,
            xma_writes,
            xma_work,
            title_signal_verdict,
        });
        log.info("PE64 AUDIO POLICY: SDL_AUDIODRIVER guest_queries={d} selected={s}", .{
            self.windows_audio_environment_queries,
            audio_policy,
        });
        for (stages, 0..) |stage, index| {
            const marker: []const u8 = if (!stage.observable)
                "unobservable (this image does not name the symbol)"
            else if (stage.met)
                "met"
            else if (first_unmet != null and index == first_unmet.?)
                "UNMET <- the wall"
            else
                "unmet (downstream of the wall)";
            log.info("PE64 AUDIO CHAIN:   {s:<28} owner={s:<22} {s} ({s}={d})", .{
                stage.name,
                stage.owner,
                marker,
                stage.evidence,
                stage.value,
            });
            if (stage.witness.len != 0 and stage.witness_armed) {
                log.info("PE64 AUDIO CHAIN:     witness {s}={d} (the guest-side export shim, which only the title can reach)", .{
                    stage.witness,
                    stage.witness_value,
                });
            }
            if (stage.observable and !stage.met and stage.when_unmet.len != 0) {
                log.info("PE64 AUDIO CHAIN:     -> {s}", .{stage.when_unmet});
            }
        }
        if (host_dropped != 0 or host_underruns != 0) {
            log.info("PE64 AUDIO CHAIN:   pacing: dropped_bytes={d} (guest ahead of the device) underruns={d} (guest behind it)", .{
                host_dropped,
                host_underruns,
            });
        }
        if (first_unmet) |index| {
            log.info("PE64 AUDIO CHAIN:   verdict: '{s}' is the earliest unmet stage and it belongs to {s}", .{
                stages[index].name,
                stages[index].owner,
            });
            if (std.mem.eql(u8, stages[index].name, "title_registered_audio_client")) {
                log.info("PE64 AUDIO CHAIN:   the title has not asked for an audio port. Xenia creates no driver and calls no host audio API until it does, so there is nothing here for Rosette to have failed at; this stage moves when the title does", .{});
            }
            if (std.mem.eql(u8, stages[index].name, "backend_reached_rosette")) {
                // Keep this branch as the single failure-point owner so a
                // startup snapshot cannot claim XAudio2 was used.
                if (self.windows_audio_environment_queries == 0) {
                    log.info("PE64 AUDIO CHAIN:   no WinMM boundary was observed and SDL_AUDIODRIVER was never queried; the audio worker did not reach SDL initialization in this observation window", .{});
                } else if (self.windows_audio_environment_driver.len != 0) {
                    log.info("PE64 AUDIO CHAIN:   SDL selected {s}, but no WinMM boundary was observed; the next finding is the SDL/WinMM dispatch boundary or an audio worker that stopped before device discovery", .{self.windows_audio_environment_driver});
                } else {
                    log.info("PE64 AUDIO CHAIN:   SDL_AUDIODRIVER was unset or unrecognized, so SDL used its compiled driver order; Rosetta did not claim a wave device", .{});
                }
            }
        } else {
            log.info("PE64 AUDIO CHAIN:   verdict: guest frames reached a host device that consumed them", .{});
        }
    }

    fn logWindowsAudioStop(self: *const ElfState) void {
        const hooks = self.windows_audio_hooks;
        var host_played: u64 = 0;
        var host_dropped: u64 = 0;
        var host_underruns: u64 = 0;
        if (hooks.transfer_counters) |counters| {
            counters(hooks.context, &host_played, &host_dropped, &host_underruns);
        }
        const served = if (hooks.callbacks_served) |callbacks| callbacks(hooks.context) else 0;
        log.info("PE64 Windows audio host: sink={s} device_open={} open={d}/{d} bytes_accepted={d} bytes_dropped={d} device_callbacks={d} device_played_bytes={d} device_underruns={d}; a zero callback count is the reading that proves the host never asked for audio", .{
            self.windowsAudioSinkLabel(),
            self.windows_audio_host_connected,
            self.windows_audio_host_open_attempts -| self.windows_audio_host_open_failures,
            self.windows_audio_host_open_attempts,
            self.windows_audio_host_bytes_accepted,
            self.windows_audio_host_bytes_dropped,
            served,
            host_played,
            host_underruns,
        });
        log.info("PE64 Windows audio: sink={s} host_output={s} imports={d} format_queries={d} open={d}/{d} format_rejections={d} prepare={d} unprepare={d} reset={d} write={d} close={d} buffers={d}/{d} callbacks={d} callback_failures={d} bytes={d} nonzero_buffers={d} last_data=0x{x} last_bytes={d} last_checksum=0x{x}", .{
            self.windowsAudioSinkLabel(),
            if (self.windows_audio_host_connected) "connected" else "not_connected",
            self.windows_audio_import_calls,
            self.windows_audio_format_queries,
            self.windows_audio_open_successes,
            self.windows_audio_open_calls,
            self.windows_audio_format_rejections,
            self.windows_audio_prepare_calls,
            self.windows_audio_unprepare_calls,
            self.windows_audio_reset_calls,
            self.windows_audio_write_calls,
            self.windows_audio_close_calls,
            self.windows_audio_buffers_submitted,
            self.windows_audio_buffers_completed,
            self.windows_audio_callback_dispatches,
            self.windows_audio_callback_failures,
            self.windows_audio_bytes_submitted,
            self.windows_audio_nonzero_buffers,
            self.windows_audio_last_data,
            self.windows_audio_last_bytes,
            self.windows_audio_last_checksum,
        });
    }

    /// Execute with a caller-selected bound.  The ELF command keeps its
    /// historical limit, while PE32+ launch sessions need a visible and
    /// bounded policy of their own so a Windows image cannot silently run
    /// forever during bring-up.
    pub fn runWithLimit(self: *ElfState, max_steps: u64) void {
        var steps: u64 = 0;
        const watch_progress = self.windows_runtime_enabled and self.windows_progress.enabled;
        if (watch_progress) self.windows_progress.next_sample_step = self.windows_progress.interval;
        const checkpoint_interval: u64 = 50_000_000;
        var next_checkpoint_step: u64 = 0;
        while (!self.terminated and (max_steps == 0 or steps < max_steps)) : (steps +|= 1) {
            self.executed_steps = steps;
            if (self.windows_runtime_enabled and
                steps +| self.windows_worker_executed_steps >= self.run_next_heartbeat_instructions)
            {
                self.logRunHeartbeat(steps);
            }
            if (watch_progress) {
                // Two comparisons per step is the whole per-instruction cost
                // of the watchdog; everything else happens once per sample
                // window.
                const rip = self.regs.rip;
                if (rip < self.windows_progress.window_rip_low) self.windows_progress.window_rip_low = rip;
                if (rip > self.windows_progress.window_rip_high) self.windows_progress.window_rip_high = rip;
                if (steps >= self.windows_progress.next_sample_step) self.checkWindowsProgress();
            }
            if (self.windows_main_wait_handle != 0) {
                if (self.windowsWaitObjectSignaled(self.windows_main_wait_handle)) {
                    // Leave RIP at the import stub.  The next ordinary step
                    // retries the wait and consumes the object's signal,
                    // producing the real WAIT_OBJECT_0 return path.
                    self.windows_main_wait_handle = 0;
                } else {
                    const serviced = self.serviceWindowsGuestThreads(self.windowsGuestWaitServiceSlice());
                    if (serviced != 0 and self.trace_windows_waits and
                        (self.windows_thread_service_calls <= 8 or self.windows_thread_service_calls % 1024 == 0))
                    {
                        log.info("PE64 main wait service: handle=0x{x} kind={s} steps={d} service_calls={d} yields={d} blocks={d} unblocks={d} completions={d} graphics_phase={s} vk_calls={d} submits={d} presents={d}", .{
                            self.windows_main_wait_handle,
                            self.windowsWaitObjectKindName(self.windows_main_wait_handle),
                            serviced,
                            self.windows_thread_service_calls,
                            self.windows_thread_yields,
                            self.windows_thread_blocks,
                            self.windows_thread_unblocks,
                            self.windows_thread_completions,
                            @tagName(self.windows_graphics.phase),
                            self.windows_graphics.vulkan_calls,
                            self.windows_graphics.queue_submits,
                            self.windows_graphics.presents,
                        });
                    }
                    if (serviced == 0) {
                        var request = std.c.timespec{ .sec = 0, .nsec = 1_000_000 };
                        _ = std.c.nanosleep(&request, null);
                    }
                    continue;
                }
            }
            if (steps >= next_checkpoint_step) {
                next_checkpoint_step +|= checkpoint_interval;
                log.info("step {d}: rip=0x{x}, rax=0x{x}, rbx=0x{x}, rcx=0x{x}, rsi=0x{x}, rdi=0x{x}", .{ steps, self.regs.rip, self.regs.rax, self.regs.rbx, self.regs.rcx, self.regs.rsi, self.regs.rdi });
                if (self.trace_graphics_progress and self.windows_runtime_enabled) self.logGraphicsProgress(steps);
                // The presentation chain at the same cadence as everything
                // else: a black window with a healthy present count is the
                // one failure whose evidence is entirely outside the counters
                // printed above, and it has to be readable without waiting
                // for the run to end.
                self.reportPresentChainCheckpoint();
                // Report a newly-degraded import at the checkpoint rather
                // than only at exit: a run that is killed while it is still
                // going would otherwise take that evidence with it.  A run
                // that degrades nothing new says nothing.
                if (self.windows_runtime_enabled) self.reportWindowsImportFallbacks(false);
                // Same reasoning for the refusal ledger, and the same rule:
                // only when a name that has not been reported yet is in it.
                if (self.windows_runtime_enabled and self.windows_import_refusals.unreported_count != 0) {
                    self.reportWindowsImportRefusals();
                    self.windows_import_refusals.markReported();
                }
                // The chain reports at the checkpoint too, not only at exit.
                // Every Xenia run so far has ended on SIGTERM from the
                // operator's own timeout, which never reaches the exit path -
                // so the one block that names the earliest unmet precondition
                // was the one thing every run threw away. They are collapsed
                // to their verdicts, and only re-emitted when a verdict moves.
                if (self.windows_runtime_enabled) self.reportRunChainsIfChanged(steps);
            }
            self.maybeRunWindowsGuestScheduler();
            if (self.terminated) break;
            if (!self.step()) break;
        }
        if (max_steps != 0 and steps >= max_steps) {
            log.warn("reached max steps ({d})", .{max_steps});
            self.logRegs();
            self.faulted = true;
            self.exit_code = 124;
            self.termination_reason = .max_steps_reached;
            self.terminated = true;
        }
        if (self.windows_runtime_enabled) self.flushWindowsGuestOutput();
        // The first authentic guest frame can arrive between the last
        // periodic checkpoint and the run's natural/forced exit. ExitProcess
        // bypasses this epilogue, so the loader's atexit summary calls the same
        // idempotent helper as a second authority.
        self.reportPresentChainFinal();
        if (self.trace_graphics_progress and self.windows_runtime_enabled) self.logGraphicsStop();
        if (self.windows_runtime_enabled and !self.trace_graphics_progress) self.logWindowsGuestFailurePointSummary();
        if (self.windows_runtime_enabled) {
            self.logWindowsAudioStop();
            // Always reported, including when nothing reached the wave
            // device: the zeroed counter line and the policy/query line make
            // an unstarted audio worker distinguishable from a silent device.
            self.reportAudioChain();
            self.reportWindowsImportFallbacks(true);
            self.reportWindowsImportRefusals();
            self.reportWindowsCrtState();
            self.reportWindowsUnexplainedZeros();
            self.reportGuestAddressSpace();
            self.reportWindowsFileFailures();
            self.reportWindowsDynamicRefusals();
            self.reportFirstFrameChain();
            self.reportGuestOutputChain();
            self.reportGuestMilestones();
            self.reportGuestThreads();
            // Keep the final report's wait graph complete even when the run
            // exits before a normal throughput report is requested.
            self.reportWindowsBlockedDiagnostics(self.windows_guest_threads.len);
            self.reportWindowsWaitCost();
            self.reportWindowsWaitFindings();
            self.reportWindowsUpstreamWaitPriority();
            self.reportWindowsScreenValidity();
            self.reportWindowsMemoryContract();
        }
        if (self.faulted) self.logExitDiagnostics();
    }

    fn logExitDiagnostics(self: *const ElfState) void {
        const regs = self.exit_fault_regs orelse self.regs;
        var detail_buffer: [256]u8 = undefined;
        const detail: []const u8 = if (self.exit_fault_thread_slot) |slot|
            std.fmt.bufPrint(&detail_buffer, "Rosette stopped while executing guest worker '{s}' (handle=0x{x}); the registers, stack and terminal instruction are that thread's at the fault, not the owner context restored after it.", .{
                self.guestThreadLabel(@intCast(@min(slot + 1, 255))),
                self.windows_guest_threads[slot].handle,
            }) catch "Rosette stopped while executing a guest worker thread."
        else
            "Rosette stopped while executing an x86-64 ELF program.";
        var terminal = exit_diagnostics.TerminalInstruction{
            .address = regs.rip,
            .op = switch (self.termination_reason) {
                .invalid_instruction => "invalid",
                .decode_failed => "decode_failed",
                .unimplemented_instruction => @tagName(self.last_decoded_op),
                else => "terminated",
            },
            .length = self.last_decoded_len,
        };
        var instruction_bytes: [16]u8 = undefined;
        const fetched = self.guestInstructionBytes(regs.rip, &instruction_bytes);
        terminal.byte_count = @intCast(fetched.len);
        @memcpy(terminal.bytes[0..fetched.len], fetched);

        var stack_entries: [16]exit_diagnostics.StackEntry = undefined;
        var stack_count: usize = 0;
        while (stack_count < stack_entries.len) : (stack_count += 1) {
            const slot = regs.rsp +| @as(u64, @intCast(stack_count * 8));
            if (self.addrToOffset(slot) == null) break;
            const value = self.read64(slot);
            stack_entries[stack_count] = .{ .slot_address = slot, .value = value };
            if (self.nearestLocalSymbol(value)) |symbol| {
                stack_entries[stack_count].symbol = symbol.symbol;
                stack_entries[stack_count].symbol_offset = symbol.symbol_offset;
            }
        }

        const trace_count = self.trace_ring.count();
        var trace: [TRACE_BUFFER_LEN]exit_diagnostics.TraceEntry = undefined;
        for (0..trace_count) |index| {
            const entry = self.trace_ring.chronological(index) orelse continue;
            trace[index] = .{
                .rip = entry.rip,
                .op = @tagName(entry.op),
                .len = entry.len,
                .rsp = entry.rsp,
                .rax = entry.rax,
                .rcx = entry.rcx,
                .rdx = entry.rdx,
            };
        }

        exit_diagnostics.logExitReport(.{
            .exit_code = self.exit_code,
            .reason = self.termination_reason,
            .faulted = self.faulted,
            .rip = regs.rip,
            .regs = .{
                .rax = regs.rax,
                .rbx = regs.rbx,
                .rcx = regs.rcx,
                .rdx = regs.rdx,
                .rsi = regs.rsi,
                .rdi = regs.rdi,
                .rbp = regs.rbp,
                .rsp = regs.rsp,
                .r8 = regs.r8,
                .r9 = regs.r9,
                .r10 = regs.r10,
                .r11 = regs.r11,
                .r12 = regs.r12,
                .r13 = regs.r13,
                .r14 = regs.r14,
                .r15 = regs.r15,
            },
            .last_instructions = trace[0..trace_count],
            .terminal_instruction = terminal,
            .stack_entries = stack_entries[0..stack_count],
            .terminal_symbol = self.nearestLocalSymbol(regs.rip),
            .runtime_context = .{ .phase = "elf_execution", .steps = self.executed_steps },
            .detail = detail,
        });
    }

    fn logRegs(self: *ElfState) void {
        log.info("  regs: rax=0x{x} rbx=0x{x} rcx=0x{x} rdx=0x{x} rsi=0x{x} rdi=0x{x} rsp=0x{x} rbp=0x{x} rip=0x{x}", .{
            self.regs.rax, self.regs.rbx, self.regs.rcx, self.regs.rdx,
            self.regs.rsi, self.regs.rdi, self.regs.rsp, self.regs.rbp,
            self.regs.rip,
        });
        log.info("  flags: cf={d} zf={d} sf={d} of={d}", .{
            @as(u1, @truncate(self.regs.rflags >> 0)),
            @as(u1, @truncate(self.regs.rflags >> 6)),
            @as(u1, @truncate(self.regs.rflags >> 7)),
            @as(u1, @truncate(self.regs.rflags >> 11)),
        });
    }

    pub fn regVal(self: *const ElfState, id: RegId, size: Size) u64 {
        return x64_decoder.regVal(&self.regs, id, size);
    }

    pub fn setReg(self: *ElfState, id: RegId, size: Size, val: u64) void {
        x64_decoder.setReg(&self.regs, id, size, val);
    }

    fn decodedRegVal(self: *const ElfState, id: RegId, high8: bool, size: Size) u64 {
        return x64_decoder.registerOperandValue(&self.regs, .{ .id = id, .high8 = high8 }, size);
    }

    fn setDecodedReg(self: *ElfState, id: RegId, high8: bool, size: Size, val: u64) void {
        x64_decoder.setRegisterOperand(&self.regs, .{ .id = id, .high8 = high8 }, size, val);
    }

    /// Record an interpreted access inside the null page and stop the run.
    ///
    /// Windows never maps the first 64 KiB of a process, so the real OS
    /// raises EXCEPTION_ACCESS_VIOLATION here and Xenia's vectored handler
    /// claims only its MMIO pages. Rosette answered these with zero, which
    /// let a null vtable load succeed and moved the failure one instruction
    /// on, to an indirect call through 0x20 that no longer said which
    /// pointer was null or who should have stored it.
    fn noteGuestNullPageAccess(self: *ElfState, address: u64, size: Size, is_write: bool) void {
        self.guest_null_page_accesses +|= 1;
        const occurrence = self.guest_null_page_accesses;
        if (comptime !@import("builtin").is_test) {
            if (shouldReportWindowsPointOccurrence(occurrence)) self.reportGuestNullPageAccess(address, size, is_write, occurrence);
        }
        if (!self.guest_null_page_fatal) return;
        if (occurrence == 1) self.windows_fatal_point_events +|= 1;
        self.terminateForWindowsFatalPointWith("guest-null-page-access", .memory_access_violation, 139);
    }

    fn reportGuestNullPageAccess(self: *const ElfState, address: u64, size: Size, is_write: bool, occurrence: u64) void {
        var at_text: [guest_symbol_text_bytes]u8 = undefined;
        const slot_plus_one: u8 = if (self.windows_active_guest_thread_slot) |slot| @intCast(@min(slot + 1, 255)) else 0;
        const bytes = self.guestMemoryConst(self.regs.rip, 16) orelse &[_]u8{};
        log.err("PE64 NULL-PAGE ACCESS: kind={s} address=0x{x} size={s} occurrence={d} step={d} rip=0x{x} at={s} last_op={s} thread={s} regs=[rax=0x{x},rbx=0x{x},rcx=0x{x},rdx=0x{x},rsi=0x{x},rdi=0x{x},rbp=0x{x},rsp=0x{x},r8=0x{x},r9=0x{x},r10=0x{x},r11=0x{x},r12=0x{x},r13=0x{x},r14=0x{x},r15=0x{x}] bytes={any}; the register holding a value at or below 0x{x} is the null pointer, and whatever was meant to store it is the finding", .{
            if (is_write) "write" else "read",
            address,
            @tagName(size),
            occurrence,
            self.executed_steps,
            self.regs.rip,
            self.describeGuestAddressOrUnnamed(self.regs.rip, &at_text),
            @tagName(self.last_decoded_op),
            self.guestThreadLabel(slot_plus_one),
            self.regs.rax,
            self.regs.rbx,
            self.regs.rcx,
            self.regs.rdx,
            self.regs.rsi,
            self.regs.rdi,
            self.regs.rbp,
            self.regs.rsp,
            self.regs.r8,
            self.regs.r9,
            self.regs.r10,
            self.regs.r11,
            self.regs.r12,
            self.regs.r13,
            self.regs.r14,
            self.regs.r15,
            bytes,
            address,
        });
        const slot = self.windows_active_guest_thread_slot orelse return;
        const thread = &self.windows_guest_threads[slot];
        var start_text: [guest_symbol_text_bytes]u8 = undefined;
        var creator_text: [guest_symbol_text_bytes]u8 = undefined;
        var creator_now_text: [guest_symbol_text_bytes]u8 = undefined;
        const creator_now: u64 = if (thread.creator_slot == 0)
            self.windows_parent_guest_context.regs.rip
        else
            self.windowsGuestThreadRip(thread.creator_slot - 1);
        const kernel = self.guest_kernel_calls.slotAt(thread.last_kernel_slot);
        log.err("PE64 NULL-PAGE ACCESS:   thread start={s} steps={d} created_step={d} ({d} steps before this access) creator={s} on {s}, which is now at {s}; last_kernel_call={s}!{s}. A thread that faults within a few thousand steps of its creation while its creator is still inside the creating call read a member the creator had not stored yet", .{
            self.describeGuestAddressOrUnnamed(thread.start_routine, &start_text),
            thread.executed_steps,
            thread.created_step,
            self.executed_steps -| thread.created_step,
            self.describeGuestAddressOrUnnamed(thread.creator_rip, &creator_text),
            self.guestThreadLabel(thread.creator_slot),
            self.describeGuestAddressOrUnnamed(creator_now, &creator_now_text),
            if (kernel) |entry| entry.module.moduleName() else "<none>",
            if (kernel) |entry| entry.export_name else "<none>",
        });
    }

    pub fn readMemVal(self: *ElfState, addr: u64, size: Size) u64 {
        if (addr < WINDOWS_NULL_PAGE_LIMIT and self.windows_runtime_enabled and self.addrToOffset(addr) == null) {
            self.noteGuestNullPageAccess(addr, size, false);
            return 0;
        }
        const value: u64 = switch (size) {
            .bits8 => self.read8(addr),
            .bits16 => self.read16(addr),
            .bits32 => self.read32(addr),
            .bits64 => self.read64(addr),
        };
        // One byte test when nothing is protected. A read still returns the
        // backing bytes: if no handler takes the fault the instruction has
        // already done exactly what Rosette always did, and if one does, it
        // overwrites the destination register from the CONTEXT it returns.
        if (self.guest_page_protection.active) _ = self.noteGuestOperandAccess(addr, size, false, value);
        return value;
    }

    pub fn writeMemVal(self: *ElfState, addr: u64, size: Size, val: u64) void {
        if (addr < WINDOWS_NULL_PAGE_LIMIT and self.windows_runtime_enabled and self.addrToOffset(addr) == null) {
            self.noteGuestNullPageAccess(addr, size, true);
            return;
        }
        // A protected store is withheld until the fault is resolved: a
        // handler for a register page wants the value delivered to a device,
        // not left in plain memory, and one that declines gets it replayed.
        if (self.guest_page_protection.active and self.noteGuestOperandAccess(addr, size, true, val)) return;
        switch (size) {
            .bits8 => self.write8(addr, @intCast(val & 0xFF)),
            .bits16 => self.write16(addr, @intCast(val & 0xFFFF)),
            .bits32 => self.write32(addr, @intCast(val & 0xFFFFFFFF)),
            .bits64 => self.write64(addr, val),
        }
    }

    fn writeExtendedInt80(destination: []u8, value: i64) void {
        std.debug.assert(destination.len >= 10);
        @memset(destination[0..10], 0);
        if (value == 0) return;

        const negative = value < 0;
        const raw: u64 = @bitCast(value);
        const magnitude = if (negative) (~raw +% 1) else raw;
        const leading: u6 = @intCast(@clz(magnitude));
        const msb_index: u6 = 63 - leading;
        const significand = magnitude << (63 - msb_index);
        const exponent: u16 = 16383 + @as(u16, msb_index);
        const sign_exponent: u16 = (if (negative) @as(u16, 0x8000) else 0) | exponent;
        std.mem.writeInt(u64, destination[0..8], significand, .little);
        std.mem.writeInt(u16, destination[8..10], sign_exponent, .little);
    }

    /// Encode an IEEE-754 binary64 value in the little-endian x87 80-bit
    /// memory format.  The PE runner does not need host floating-point state
    /// to survive across instructions, so values are converted at the
    /// operation boundary and the guest stack retains the exact ten bytes in
    /// between.
    fn writeExtendedFloat80(destination: []u8, value: f64) void {
        std.debug.assert(destination.len >= 10);
        @memset(destination[0..10], 0);
        const bits: u64 = @bitCast(value);
        const sign: u16 = if ((bits >> 63) != 0) 0x8000 else 0;
        const fraction = bits & 0x000F_FFFF_FFFF_FFFF;
        const exponent: u16 = @truncate((bits >> 52) & 0x7FF);
        if (exponent == 0 and fraction == 0) return;
        if (exponent == 0x7FF) {
            const significand: u64 = if (fraction == 0)
                0x8000_0000_0000_0000
            else
                0xC000_0000_0000_0000;
            std.mem.writeInt(u64, destination[0..8], significand, .little);
            std.mem.writeInt(u16, destination[8..10], sign | 0x7FFF, .little);
            return;
        }

        var significand: u64 = 0;
        var unbiased: i32 = 0;
        if (exponent == 0) {
            const shift: u6 = @intCast(@clz(fraction));
            significand = fraction << shift;
            unbiased = -1011 - @as(i32, shift);
        } else {
            significand = (fraction | (@as(u64, 1) << 52)) << 11;
            unbiased = @as(i32, exponent) - 1023;
        }
        std.mem.writeInt(u64, destination[0..8], significand, .little);
        std.mem.writeInt(u16, destination[8..10], sign | @as(u16, @intCast(unbiased + 16383)), .little);
    }

    /// Decode the x87 80-bit memory format to the binary64 precision used by
    /// the arithmetic fallback.  This is deliberately separate from the raw
    /// stack accessors: FLD/FSTP m80 use the raw path, while arithmetic and
    /// comparisons need a numerical view of the same value.
    fn readExtendedFloat80(source: []const u8) f64 {
        std.debug.assert(source.len >= 10);
        const significand = std.mem.readInt(u64, source[0..8], .little);
        const sign_exponent = std.mem.readInt(u16, source[8..10], .little);
        const negative = (sign_exponent & 0x8000) != 0;
        const exponent = sign_exponent & 0x7FFF;
        const sign_bit: u64 = if (negative) @as(u64, 1) << 63 else 0;

        if (exponent == 0x7FFF) {
            const special_bits = if ((significand & 0x7FFF_FFFF_FFFF_FFFF) == 0)
                sign_bit | 0x7FF0_0000_0000_0000
            else
                sign_bit | 0x7FF8_0000_0000_0000;
            return @bitCast(special_bits);
        }
        if (significand == 0) return @bitCast(sign_bit);

        const unbiased: i32 = if (exponent == 0) -16382 else @as(i32, exponent) - 16383;
        if (unbiased > 1023) return @bitCast(sign_bit | 0x7FF0_0000_0000_0000);
        if (unbiased >= -1022) {
            const binary64_exponent: u64 = @intCast(unbiased + 1023);
            const fraction = (significand >> 11) & 0x000F_FFFF_FFFF_FFFF;
            return @bitCast(sign_bit | (binary64_exponent << 52) | fraction);
        }
        if (unbiased < -1074) return @bitCast(sign_bit);
        const subnormal_shift: u6 = @intCast(-1011 - unbiased);
        const fraction = significand >> subnormal_shift;
        return @bitCast(sign_bit | (fraction & 0x000F_FFFF_FFFF_FFFF));
    }

    fn x87RawFromInt(value: i64) X87Raw {
        var raw: X87Raw = [_]u8{0} ** 10;
        writeExtendedInt80(&raw, value);
        return raw;
    }

    fn x87RawFromFloat(value: f64) X87Raw {
        var raw: X87Raw = [_]u8{0} ** 10;
        writeExtendedFloat80(&raw, value);
        return raw;
    }

    fn x87Physical(self: *const ElfState, logical: u3) u3 {
        return @truncate(self.x87_top +% logical);
    }

    fn x87StackFault(self: *ElfState, overflow: bool) void {
        // Invalid-operation and stack-fault bits are sticky.  C1 indicates
        // overflow, and is cleared for underflow, matching the masked x87
        // exception behavior used by the native execution path.
        self.x87_status |= 1 << 0;
        self.x87_status |= 1 << 6;
        if (overflow) {
            self.x87_status |= 1 << 9;
        } else {
            self.x87_status &= ~@as(u16, 1 << 9);
        }
    }

    fn x87PushRaw(self: *ElfState, value: X87Raw) bool {
        const next: u3 = @truncate(self.x87_top -% 1);
        if (self.x87_tags[next]) {
            self.x87StackFault(true);
            return false;
        }
        self.x87_top = next;
        self.x87_stack[next] = value;
        self.x87_tags[next] = true;
        return true;
    }

    fn x87GetRaw(self: *ElfState, logical: u3) ?X87Raw {
        const physical = self.x87Physical(logical);
        if (!self.x87_tags[physical]) {
            self.x87StackFault(false);
            return null;
        }
        return self.x87_stack[physical];
    }

    fn x87SetRaw(self: *ElfState, logical: u3, value: X87Raw) bool {
        const physical = self.x87Physical(logical);
        if (!self.x87_tags[physical]) {
            self.x87StackFault(false);
            return false;
        }
        self.x87_stack[physical] = value;
        return true;
    }

    fn x87PopRaw(self: *ElfState) ?X87Raw {
        const physical = self.x87_top;
        if (!self.x87_tags[physical]) {
            self.x87StackFault(false);
            return null;
        }
        const value = self.x87_stack[physical];
        self.x87_tags[physical] = false;
        self.x87_top +%= 1;
        return value;
    }

    fn x87StatusWord(self: *const ElfState) u16 {
        return (self.x87_status & ~@as(u16, 0x3800)) | (@as(u16, self.x87_top) << 11);
    }

    fn x87Reset(self: *ElfState) void {
        self.x87_stack = [_]X87Raw{[_]u8{0} ** 10} ** 8;
        self.x87_tags = [_]bool{false} ** 8;
        self.x87_top = 0;
        self.x87_status = 0;
        self.x87_control = 0x037F;
    }

    fn x87Exchange(self: *ElfState, logical: u3) void {
        const other = self.x87Physical(logical);
        if (!self.x87_tags[self.x87_top] or !self.x87_tags[other]) {
            self.x87StackFault(false);
            return;
        }
        std.mem.swap(X87Raw, &self.x87_stack[self.x87_top], &self.x87_stack[other]);
    }

    fn x87Free(self: *ElfState, logical: u3) void {
        self.x87_tags[self.x87Physical(logical)] = false;
    }

    fn x87Cos(self: *ElfState) void {
        const raw = self.x87GetRaw(0) orelse return;
        const value = readExtendedFloat80(&raw);
        if (!std.math.isFinite(value) or @abs(value) > 0x1p63) {
            self.x87_status |= 1 << 10;
            return;
        }
        self.x87_status &= ~@as(u16, (1 << 9) | (1 << 10));
        _ = self.x87SetRaw(0, x87RawFromFloat(@cos(value)));
    }

    fn x87Sin(self: *ElfState) void {
        const raw = self.x87GetRaw(0) orelse return;
        const value = readExtendedFloat80(&raw);
        if (!std.math.isFinite(value) or @abs(value) > 0x1p63) {
            self.x87_status |= 1 << 10;
            return;
        }
        self.x87_status &= ~@as(u16, (1 << 9) | (1 << 10));
        _ = self.x87SetRaw(0, x87RawFromFloat(@sin(value)));
    }

    fn x87Fchs(self: *ElfState) void {
        const raw = self.x87GetRaw(0) orelse return;
        _ = self.x87SetRaw(0, x87RawFromFloat(-readExtendedFloat80(&raw)));
    }

    fn x87Fabs(self: *ElfState) void {
        const raw = self.x87GetRaw(0) orelse return;
        _ = self.x87SetRaw(0, x87RawFromFloat(@abs(readExtendedFloat80(&raw))));
    }

    fn x87Test(self: *ElfState) void {
        const raw = self.x87GetRaw(0) orelse return;
        const value = readExtendedFloat80(&raw);
        self.x87_status &= ~@as(u16, (1 << 8) | (1 << 10) | (1 << 14));
        if (std.math.isNan(value)) {
            self.x87_status |= (1 << 8) | (1 << 10) | (1 << 14);
        } else if (value == 0.0) {
            self.x87_status |= 1 << 14;
        } else if (value < 0.0) {
            self.x87_status |= 1 << 8;
        }
    }

    fn x87CompareStatus(self: *ElfState, lhs: f64, rhs: f64, pop_result: bool) void {
        self.x87_status &= ~@as(u16, (1 << 8) | (1 << 10) | (1 << 14));
        if (std.math.isNan(lhs) or std.math.isNan(rhs)) {
            self.x87_status |= (1 << 8) | (1 << 10) | (1 << 14);
        } else if (lhs == rhs) {
            self.x87_status |= 1 << 14;
        } else if (lhs < rhs) {
            self.x87_status |= 1 << 8;
        }
        if (pop_result) _ = self.x87PopRaw();
    }

    fn x87F2xm1(self: *ElfState) void {
        const raw = self.x87GetRaw(0) orelse return;
        const value = readExtendedFloat80(&raw);
        if (!std.math.isFinite(value) or value < -1.0 or value > 1.0) {
            self.x87_status |= 1;
            return;
        }
        _ = self.x87SetRaw(0, x87RawFromFloat(std.math.exp2(value) - 1.0));
    }

    fn x87Fyl2x(self: *ElfState, add_one: bool) void {
        const x_raw = self.x87GetRaw(0) orelse return;
        const y_raw = self.x87GetRaw(1) orelse return;
        const x = readExtendedFloat80(&x_raw);
        const y = readExtendedFloat80(&y_raw);
        const argument = if (add_one) x + 1.0 else x;
        if (!std.math.isFinite(argument) or argument <= 0.0) {
            self.x87_status |= 1;
            return;
        }
        _ = self.x87SetRaw(1, x87RawFromFloat(y * std.math.log2(argument)));
        _ = self.x87PopRaw();
    }

    fn x87Fptan(self: *ElfState) void {
        const raw = self.x87GetRaw(0) orelse return;
        const value = readExtendedFloat80(&raw);
        if (!std.math.isFinite(value)) {
            self.x87_status |= 1;
            return;
        }
        _ = self.x87SetRaw(0, x87RawFromFloat(@tan(value)));
        _ = self.x87PushRaw(x87RawFromFloat(1.0));
    }

    fn x87Fpatan(self: *ElfState) void {
        const x_raw = self.x87GetRaw(0) orelse return;
        const y_raw = self.x87GetRaw(1) orelse return;
        const x = readExtendedFloat80(&x_raw);
        const y = readExtendedFloat80(&y_raw);
        _ = self.x87SetRaw(1, x87RawFromFloat(std.math.atan2(y, x)));
        _ = self.x87PopRaw();
    }

    fn x87Fxtract(self: *ElfState) void {
        const raw = self.x87GetRaw(0) orelse return;
        const value = readExtendedFloat80(&raw);
        const parts = std.math.frexp(value);
        _ = self.x87SetRaw(0, x87RawFromFloat(parts.significand * 2.0));
        _ = self.x87PushRaw(x87RawFromInt(parts.exponent - 1));
    }

    fn x87PartialRemainder(self: *ElfState, nearest: bool) void {
        const numerator_raw = self.x87GetRaw(0) orelse return;
        const denominator_raw = self.x87GetRaw(1) orelse return;
        const numerator = readExtendedFloat80(&numerator_raw);
        const denominator = readExtendedFloat80(&denominator_raw);
        if (!std.math.isFinite(numerator) or !std.math.isFinite(denominator) or denominator == 0.0) {
            self.x87_status |= 1 << 10;
            return;
        }

        const quotient = if (nearest) std.math.round(numerator / denominator) else @trunc(numerator / denominator);
        const remainder = numerator - quotient * denominator;
        self.x87_status &= ~@as(u16, (1 << 8) | (1 << 9) | (1 << 10) | (1 << 14));
        const quotient_bits: u64 = @bitCast(@as(i64, @intFromFloat(quotient)));
        if ((quotient_bits & 0x4) != 0) self.x87_status |= 1 << 8;
        if ((quotient_bits & 0x2) != 0) self.x87_status |= 1 << 9;
        if ((quotient_bits & 0x1) != 0) self.x87_status |= 1 << 14;
        _ = self.x87SetRaw(0, x87RawFromFloat(remainder));
    }

    fn x87PartialRemainderNearest(self: *ElfState) void {
        self.x87PartialRemainder(true);
    }

    fn x87PartialRemainderTrunc(self: *ElfState) void {
        self.x87PartialRemainder(false);
    }

    fn x87Fsincos(self: *ElfState) void {
        const raw = self.x87GetRaw(0) orelse return;
        const value = readExtendedFloat80(&raw);
        if (!std.math.isFinite(value)) {
            self.x87_status |= 1;
            return;
        }
        _ = self.x87SetRaw(0, x87RawFromFloat(@sin(value)));
        _ = self.x87PushRaw(x87RawFromFloat(@cos(value)));
    }

    fn x87Frndint(self: *ElfState) void {
        const raw = self.x87GetRaw(0) orelse return;
        const value = readExtendedFloat80(&raw);
        const rounding = (self.x87_control >> 10) & 3;
        const rounded = switch (rounding) {
            0 => std.math.round(value),
            1 => @floor(value),
            2 => @ceil(value),
            else => @trunc(value),
        };
        _ = self.x87SetRaw(0, x87RawFromFloat(rounded));
    }

    fn x87Fscale(self: *ElfState) void {
        const value_raw = self.x87GetRaw(0) orelse return;
        const scale_raw = self.x87GetRaw(1) orelse return;
        const value = readExtendedFloat80(&value_raw);
        const scale = readExtendedFloat80(&scale_raw);
        if (!std.math.isFinite(value) or !std.math.isFinite(scale)) return;
        const exponent: i32 = if (scale >= 2147483647.0)
            std.math.maxInt(i32)
        else if (scale <= -2147483648.0)
            std.math.minInt(i32)
        else
            @intFromFloat(@trunc(scale));
        _ = self.x87SetRaw(0, x87RawFromFloat(std.math.ldexp(value, exponent)));
    }

    fn x87Fclex(self: *ElfState) void {
        self.x87_status &= ~@as(u16, 0x00BF);
    }

    fn x87WriteRawMemory(self: *ElfState, addr: u64, raw: X87Raw) void {
        const output = self.guestMemory(addr, 10) orelse return;
        self.traceGuestWrite(addr, 10, std.mem.readInt(u64, raw[0..8], .little));
        @memcpy(output[0..10], raw[0..]);
    }

    fn x87Compare(self: *ElfState, source: u3, pop_result: bool) void {
        const lhs_raw = self.x87GetRaw(0) orelse return;
        const rhs_raw = self.x87GetRaw(source) orelse return;
        const lhs = readExtendedFloat80(&lhs_raw);
        const rhs = readExtendedFloat80(&rhs_raw);
        self.regs.rflags &= ~(RFL_ZF | RFL_PF | RFL_CF | RFL_OF | RFL_SF | RFL_AF);
        if (std.math.isNan(lhs) or std.math.isNan(rhs)) {
            self.regs.rflags |= RFL_ZF | RFL_PF | RFL_CF;
        } else if (lhs < rhs) {
            self.regs.rflags |= RFL_CF;
        } else if (lhs == rhs) {
            self.regs.rflags |= RFL_ZF;
        }
        if (pop_result) _ = self.x87PopRaw();
    }

    fn x87Divide(numerator: f64, denominator: f64, status: *u16) f64 {
        if (denominator != 0.0) return numerator / denominator;
        if (numerator == 0.0 or std.math.isNan(numerator)) return std.math.nan(f64);
        status.* |= 1 << 2;
        const sign = (@as(u64, @bitCast(numerator)) ^ @as(u64, @bitCast(denominator))) & (@as(u64, 1) << 63);
        return @bitCast(sign | 0x7FF0_0000_0000_0000);
    }

    fn x87MemoryValue(self: *ElfState, d: DecodedInsn, integer: bool) f64 {
        const bits = self.readMemVal(d.addr, d.size);
        if (integer) {
            return switch (d.size) {
                .bits16 => @floatFromInt(@as(i16, @bitCast(@as(u16, @truncate(bits))))),
                .bits32 => @floatFromInt(@as(i32, @bitCast(@as(u32, @truncate(bits))))),
                else => @floatFromInt(@as(i64, @bitCast(bits))),
            };
        }
        return switch (d.size) {
            .bits32 => @floatCast(@as(f32, @bitCast(@as(u32, @truncate(bits))))),
            .bits64 => @bitCast(bits),
            else => 0.0,
        };
    }

    fn x87Memory(self: *ElfState, d: DecodedInsn) void {
        const lhs_raw = self.x87GetRaw(0) orelse return;
        const lhs = readExtendedFloat80(&lhs_raw);
        const rhs = self.x87MemoryValue(d, (d.imm & (@as(u64, 1) << 3)) != 0);
        const operation: u3 = @truncate(d.imm & 7);
        if (operation == 6 or operation == 7) {
            self.x87CompareStatus(lhs, rhs, operation == 7);
            return;
        }
        const result = switch (operation) {
            0 => lhs + rhs,
            1 => lhs * rhs,
            2 => lhs - rhs,
            3 => rhs - lhs,
            4 => x87Divide(lhs, rhs, &self.x87_status),
            5 => x87Divide(rhs, lhs, &self.x87_status),
            else => unreachable,
        };
        _ = self.x87SetRaw(0, x87RawFromFloat(result));
    }

    fn x87Binary(self: *ElfState, d: DecodedInsn) void {
        const destination: u3 = @truncate((d.imm >> 3) & 7);
        const source: u3 = @truncate((d.imm >> 6) & 7);
        const operation: u3 = @truncate(d.imm & 7);
        const lhs_raw = self.x87GetRaw(destination) orelse return;
        const rhs_raw = self.x87GetRaw(source) orelse return;
        const lhs = readExtendedFloat80(&lhs_raw);
        const rhs = readExtendedFloat80(&rhs_raw);
        const result = switch (operation) {
            0 => lhs + rhs,
            1 => lhs * rhs,
            2 => lhs - rhs,
            3 => rhs - lhs,
            4 => x87Divide(lhs, rhs, &self.x87_status),
            5 => x87Divide(rhs, lhs, &self.x87_status),
            else => unreachable,
        };
        _ = self.x87SetRaw(destination, x87RawFromFloat(result));
        if ((d.imm & (1 << 9)) != 0) _ = self.x87PopRaw();
    }

    pub fn readMem128(self: *const ElfState, addr: u64) [16]u8 {
        var value = [_]u8{0} ** 16;
        const source = self.guestMemoryConst(addr, 16) orelse return value;
        @memcpy(value[0..], source);
        return value;
    }

    pub fn writeMem128(self: *ElfState, addr: u64, value: [16]u8) void {
        self.traceGuestVectorWrite(addr, value);
        const destination = self.guestMemory(addr, 16) orelse return;
        @memcpy(destination, value[0..]);
    }

    fn traceGuestVectorWrite(self: *const ElfState, addr: u64, value: [16]u8) void {
        const watch = self.trace_write_address orelse return;
        const write_end = addr +| 16;
        const watch_end = watch +| 8;
        if (addr >= watch_end or write_end <= watch) return;
        if (comptime @import("builtin").is_test) return;

        log.info("trace guest vector write address=0x{x} bytes={any} watch=0x{x} rip=0x{x} op={s} len={d} rsp=0x{x} ret=0x{x}", .{
            addr,
            value,
            watch,
            self.regs.rip,
            @tagName(self.last_decoded_op),
            self.last_decoded_len,
            self.regs.rsp,
            self.read64(self.regs.rsp),
        });
    }

    pub fn guestMemory(self: *ElfState, addr: u64, count: u64) ?[]u8 {
        if (count > std.math.maxInt(usize)) return null;
        const count_usize: usize = @intCast(count);
        if (self.addrToOffset(addr)) |off| {
            const off_usize: usize = @intCast(off);
            if (off_usize > self.mem.len or count_usize > self.mem.len - off_usize) return null;
            // A mutable borrow is a possible synchronous bulk write (CRT
            // memcpy/memset, file I/O, SIMD stores). Publish its generation
            // before returning storage, so these routes cannot leave a
            // previously cached instruction valid. Pure readers use Const.
            self.bumpWindowsImageCodeGeneration(addr, count);
            return self.mem[off_usize .. off_usize + count_usize];
        }
        const bytes = self.windowsMappedMemory(addr, count) orelse return null;
        self.bumpWindowsMappedCodeGeneration(addr, count);
        return bytes;
    }

    pub fn guestMemoryConst(self: *const ElfState, addr: u64, count: u64) ?[]const u8 {
        if (count > std.math.maxInt(usize)) return null;
        const count_usize: usize = @intCast(count);
        if (self.addrToOffset(addr)) |off| {
            const off_usize: usize = @intCast(off);
            if (off_usize > self.mem.len or count_usize > self.mem.len - off_usize) return null;
            return self.mem[off_usize .. off_usize + count_usize];
        }
        return self.windowsMappedMemoryConst(addr, count);
    }

    /// The readable bytes from `addr` to `maximum` or to the end of the
    /// region that holds it, whichever comes first.
    ///
    /// A C string's length is not known before it is read, so a fixed-size
    /// `guestMemoryConst` cannot fetch one; this is the region-aware version
    /// the C runtime's string imports need.
    pub fn guestMemoryTailConst(self: *const ElfState, addr: u64, maximum: usize) ?[]const u8 {
        if (maximum == 0) return null;
        if (self.nativeMemoryAlias(addr, 1) != null) {
            for (self.native_memory_aliases[0..self.native_memory_alias_count]) |alias| {
                const bytes = alias.bytes orelse continue;
                if (addr < alias.guest_base or addr >= alias.guest_base + bytes.len) continue;
                const offset: usize = @intCast(addr - alias.guest_base);
                return bytes[offset..@min(bytes.len, offset +| maximum)];
            }
        }
        if (self.addrToOffset(addr)) |off| {
            const start: usize = @intCast(off);
            if (start >= self.mem.len) return null;
            return self.mem[start..@min(self.mem.len, start +| maximum)];
        }
        for (self.windows_memory_views[0..self.windows_memory_view_count]) |view| {
            if (view.length == 0 or addr < view.guest_base) continue;
            const view_end = std.math.add(u64, view.guest_base, view.length) catch continue;
            if (addr >= view_end) continue;
            const mapping = self.windows_file_mappings[view.mapping_index];
            const backing = mapping.backing orelse continue;
            const backing_offset = std.math.add(u64, view.backing_offset, addr - view.guest_base) catch return null;
            const offset = std.math.cast(usize, backing_offset) orelse return null;
            if (offset >= backing.len) return null;
            const in_view = std.math.cast(usize, view_end - addr) orelse std.math.maxInt(usize);
            return backing[offset..@min(backing.len, offset +| @min(maximum, in_view))];
        }
        for (self.windows_virtual_allocations[0..self.windows_virtual_allocation_count]) |allocation| {
            if (allocation.length == 0 or addr < allocation.guest_base) continue;
            const allocation_end = std.math.add(u64, allocation.guest_base, allocation.length) catch continue;
            if (addr >= allocation_end) continue;
            const backing = allocation.backing orelse continue;
            const offset = std.math.cast(usize, addr - allocation.guest_base) orelse return null;
            if (offset >= backing.len) return null;
            return backing[offset..@min(backing.len, offset +| maximum)];
        }
        return null;
    }

    /// A NUL-terminated string anywhere Rosette serves guest memory.
    pub fn guestCStringConst(self: *const ElfState, addr: u64, maximum: usize) ?[]const u8 {
        if (addr == 0) return null;
        const tail = self.guestMemoryTailConst(addr, maximum) orelse return null;
        const length = std.mem.indexOfScalar(u8, tail, 0) orelse return null;
        return tail[0..length];
    }

    pub fn writeHostFd(self: *ElfState, fd: u64, data: []const u8) u64 {
        _ = self;
        const host_fd = hostFdFromGuest(fd) orelse return x64_syscalls.errnoValue(.bad_file_descriptor);
        var written: usize = 0;
        while (written < data.len) {
            const n = std.c.write(host_fd, data[written..].ptr, data.len - written);
            if (n <= 0) return x64_syscalls.errnoValue(.io);
            written += @intCast(n);
        }
        return @intCast(data.len);
    }

    pub fn traceGuestIo(self: *const ElfState, operation: []const u8, fd: u64, addr: u64, count: u64, result: u64) void {
        if (!self.shouldTraceFd(fd)) return;
        log.info("runtime io: {s}(fd={d}, buf=0x{x}, count={d}) -> {d}", .{
            operation,
            fd,
            addr,
            count,
            syscallResult(result),
        });
        if (!self.trace_syscall_bytes) return;
        if (syscallResult(result) <= 0) return;
        const available = @min(count, result);
        const data = self.guestMemoryConst(addr, available) orelse return;
        self.traceDataPreview(operation, fd, data);
    }

    fn traceSyscall(self: *const ElfState, comptime fmt: []const u8, args: anytype) void {
        if (!self.trace_syscalls) return;
        if (self.trace_fd_filter != null) return;
        log.info("syscall: " ++ fmt, args);
    }

    fn traceOpenResult(self: *const ElfState, path: []const u8, flags_raw: u64, mode_raw: u64, result: u64) void {
        if (!self.shouldTraceResultFd(result)) return;
        log.info("syscall: open(\"{s}\", flags=0x{x}, mode=0o{o}) -> {d}", .{
            path,
            flags_raw,
            mode_raw & 0o7777,
            syscallResult(result),
        });
    }

    fn traceCreatResult(self: *const ElfState, path: []const u8, mode_raw: u64, result: u64) void {
        if (!self.shouldTraceResultFd(result)) return;
        log.info("syscall: creat(\"{s}\", mode=0o{o}) -> {d}", .{
            path,
            mode_raw & 0o7777,
            syscallResult(result),
        });
    }

    fn shouldTraceFd(self: *const ElfState, fd: u64) bool {
        if (!self.trace_syscalls) return false;
        if (self.trace_fd_filter) |filter| return fd == filter;
        return true;
    }

    fn shouldTraceResultFd(self: *const ElfState, result: u64) bool {
        if (!self.trace_syscalls) return false;
        if (self.trace_fd_filter) |filter| {
            if (syscallResult(result) < 0) return false;
            return result == filter;
        }
        return true;
    }

    fn traceDataPreview(self: *const ElfState, operation: []const u8, fd: u64, data: []const u8) void {
        if (!self.trace_syscall_bytes) return;
        var preview: [96]u8 = undefined;
        const n = @min(preview.len, data.len);
        for (data[0..n], 0..) |byte, i| {
            preview[i] = switch (byte) {
                0x20...0x7e => byte,
                '\n' => '|',
                '\r', '\t' => ' ',
                else => '.',
            };
        }
        log.info("runtime io bytes: {s}(fd={d}) {d} byte preview \"{s}\"", .{
            operation,
            fd,
            data.len,
            preview[0..n],
        });
    }

    fn abiTraceConfig(self: *const ElfState) x64_guest_abi.TraceConfig {
        return .{
            .trace_calls = self.trace_calls,
            .diagnose = self.diagnose_abi,
        };
    }

    fn noteGuestCall(self: *ElfState, kind: x64_guest_abi.CallKind, target: u64, return_rip: u64) void {
        if (!self.trace_calls) return;
        self.call_stack.enter(self.allocator, self.abiTraceConfig(), .{
            .target = target,
            .return_rip = return_rip,
            .rsp_before_call = self.regs.rsp,
            .symbol = self.localSymbolNameAt(target),
            .kind = kind,
        });
    }

    fn noteGuestReturn(self: *ElfState, return_rip: u64) void {
        if (!self.trace_calls) return;
        self.call_stack.leave(self.abiTraceConfig(), return_rip, self.regs.rsp, self.regs.rax);
    }

    fn setFlagsSub(self: *ElfState, a: u64, b: u64, result: u64, size: Size) void {
        x64_decoder.applySub(&self.regs.rflags, a, b, result, size);
    }

    fn setFlagsAdd(self: *ElfState, a: u64, b: u64, result: u64, size: Size) void {
        x64_decoder.applyAdd(&self.regs.rflags, a, b, result, size);
    }

    fn setFlagsIncDec(self: *ElfState, input: u64, result: u64, size: Size, is_inc: bool) void {
        x64_decoder.applyIncDec(&self.regs.rflags, input, result, size, is_inc);
    }

    fn setFlagsLogic(self: *ElfState, result: u64, size: Size) void {
        x64_decoder.applyLogic(&self.regs.rflags, result, size);
    }

    fn bmiSource(self: *ElfState, d: DecodedInsn) u64 {
        return if (d.is_reg_form) self.regVal(d.src_reg, d.size) else self.readMemVal(d.addr, d.size);
    }

    fn executeBmi(self: *ElfState, d: DecodedInsn) void {
        const mask = maskForSize(d.size);
        const width: u7 = if (d.size == .bits64) 64 else 32;

        switch (d.op) {
            .andn => {
                const source1 = self.regVal(d.src_reg2, d.size);
                const source2 = self.bmiSource(d);
                const result = (~source1 & source2) & mask;
                self.setReg(d.dst_reg, d.size, result);
                self.setFlagsLogic(result, d.size);
            },
            .bzhi => {
                const source = self.bmiSource(d) & mask;
                const index = self.regVal(d.src_reg2, d.size) & 0xFF;
                const result = if (index >= width)
                    source
                else if (index == 0)
                    0
                else
                    source & ((@as(u64, 1) << @as(u6, @intCast(index))) - 1);
                self.setReg(d.dst_reg, d.size, result);
                self.setFlag(RFL_CF, index >= width);
            },
            .mulx => {
                const multiplicand = self.regVal(.dl_dx_edx_rdx, d.size);
                const source = self.bmiSource(d);
                const product = @as(u128, multiplicand) * @as(u128, source);
                const low = @as(u64, @truncate(product)) & mask;
                const high = @as(u64, @truncate(product >> width)) & mask;
                self.setReg(d.dst_reg, d.size, high);
                self.setReg(d.dst_reg2, d.size, low);
            },
            .rorx => {
                const source = self.bmiSource(d) & mask;
                const count: u6 = @intCast(d.imm & (width - 1));
                const result = if (count == 0) blk: {
                    break :blk source;
                } else blk: {
                    const rotate_back: u6 = @intCast((width - count) & 63);
                    break :blk ((source >> count) | (source << rotate_back)) & mask;
                };
                self.setReg(d.dst_reg, d.size, result);
            },
            .shlx => {
                const source = self.bmiSource(d) & mask;
                const count: u6 = @intCast(self.regVal(d.src_reg2, d.size) & (width - 1));
                self.setReg(d.dst_reg, d.size, (source << count) & mask);
            },
            .shrx => {
                const source = self.bmiSource(d) & mask;
                const count: u6 = @intCast(self.regVal(d.src_reg2, d.size) & (width - 1));
                self.setReg(d.dst_reg, d.size, source >> count);
            },
            .sarx => {
                const source = self.bmiSource(d) & mask;
                const count: u6 = @intCast(self.regVal(d.src_reg2, d.size) & (width - 1));
                const signed: i64 = if (d.size == .bits64)
                    @bitCast(source)
                else
                    @as(i32, @bitCast(@as(u32, @truncate(source))));
                self.setReg(d.dst_reg, d.size, @as(u64, @bitCast(signed >> count)) & mask);
            },
            else => unreachable,
        }
    }

    fn vectorAndAllZero(a: [16]u8, b: [16]u8) bool {
        for (a, b) |lhs, rhs| {
            if ((lhs & rhs) != 0) return false;
        }
        return true;
    }

    fn vectorAndNotAllZero(a: [16]u8, b: [16]u8) bool {
        for (a, b) |lhs, rhs| {
            if ((~lhs & rhs) != 0) return false;
        }
        return true;
    }

    fn executeVectorTest(self: *ElfState, d: DecodedInsn) void {
        const rhs_low = if (d.is_reg_form) self.xmm[d.xmm_src2] else self.readMem128(d.addr);
        const low_zf = vectorAndAllZero(self.xmm[d.xmm_src], rhs_low);
        const low_cf = vectorAndNotAllZero(self.xmm[d.xmm_src], rhs_low);
        self.regs.rflags &= ~(RFL_OF | RFL_SF | RFL_ZF | RFL_AF | RFL_PF | RFL_CF);
        if (d.vector_256) {
            const rhs_high = if (d.is_reg_form) self.ymm_hi[d.xmm_src2] else self.readMem128(d.addr + 16);
            if (low_zf and vectorAndAllZero(self.ymm_hi[d.xmm_src], rhs_high)) self.regs.rflags |= RFL_ZF;
            if (low_cf and vectorAndNotAllZero(self.ymm_hi[d.xmm_src], rhs_high)) self.regs.rflags |= RFL_CF;
        } else {
            if (low_zf) self.regs.rflags |= RFL_ZF;
            if (low_cf) self.regs.rflags |= RFL_CF;
        }
    }

    fn executeVpshufd(self: *ElfState, d: DecodedInsn) void {
        // VPSHUFD shuffles each independent 128-bit lane.  The VEX.128 form
        // also clears the destination's upper YMM half; legacy SSE callers
        // carry `legacy_sse` and must preserve that half.
        const source_low = if (d.is_reg_form) self.xmm[d.xmm_src] else self.readMem128(d.addr);
        var result_low = [_]u8{0} ** 16;
        for (0..4) |lane| {
            const selected: usize = @intCast((d.imm >> @intCast(lane * 2)) & 0x03);
            @memcpy(result_low[lane * 4 ..][0..4], source_low[selected * 4 ..][0..4]);
        }
        self.xmm[d.xmm_dst] = result_low;

        if (d.vector_256) {
            const source_high = if (d.is_reg_form) self.ymm_hi[d.xmm_src] else self.readMem128(d.addr +% 16);
            var result_high = [_]u8{0} ** 16;
            for (0..4) |lane| {
                const selected: usize = @intCast((d.imm >> @intCast(lane * 2)) & 0x03);
                @memcpy(result_high[lane * 4 ..][0..4], source_high[selected * 4 ..][0..4]);
            }
            self.ymm_hi[d.xmm_dst] = result_high;
        } else if (!d.legacy_sse) {
            @memset(&self.ymm_hi[d.xmm_dst], 0);
        }
    }

    fn vpdpbusdBlock(accumulator: [16]u8, unsigned_source: [16]u8, signed_source: [16]u8) [16]u8 {
        var result = accumulator;
        for (0..4) |lane| {
            const offset = lane * 4;
            var total: i64 = @as(i64, @as(i32, @bitCast(std.mem.readInt(u32, accumulator[offset..][0..4], .little))));
            for (0..4) |byte_index| {
                const unsigned_value: i64 = unsigned_source[offset + byte_index];
                const signed_value: i64 = @as(i8, @bitCast(signed_source[offset + byte_index]));
                total += unsigned_value * signed_value;
            }
            std.mem.writeInt(u32, result[offset..][0..4], @truncate(@as(u64, @bitCast(total))), .little);
        }
        return result;
    }

    fn executeVpdpbusd(self: *ElfState, d: DecodedInsn) void {
        const low_unsigned = self.xmm[d.xmm_src];
        const low_signed = if (d.is_reg_form) self.xmm[d.xmm_src2] else self.readMem128(d.addr);
        self.xmm[d.xmm_dst] = vpdpbusdBlock(self.xmm[d.xmm_dst], low_unsigned, low_signed);
        if (d.vector_256) {
            const high_unsigned = self.ymm_hi[d.xmm_src];
            const high_signed = if (d.is_reg_form) self.ymm_hi[d.xmm_src2] else self.readMem128(d.addr + 16);
            self.ymm_hi[d.xmm_dst] = vpdpbusdBlock(self.ymm_hi[d.xmm_dst], high_unsigned, high_signed);
        } else {
            @memset(&self.ymm_hi[d.xmm_dst], 0);
        }
    }

    fn executeVexLane128(self: *ElfState, d: DecodedInsn) void {
        if (d.op == .vextractf128) {
            const selected = if ((d.imm & 1) == 0) self.xmm[d.xmm_src] else self.ymm_hi[d.xmm_src];
            if (d.is_reg_form) {
                self.xmm[d.xmm_dst] = selected;
                @memset(&self.ymm_hi[d.xmm_dst], 0);
            } else {
                self.writeMem128(d.addr, selected);
            }
            return;
        }

        const source2 = if (d.is_reg_form) self.xmm[d.xmm_src2] else self.readMem128(d.addr);
        const source1_low = self.xmm[d.xmm_src];
        const source1_high = self.ymm_hi[d.xmm_src];
        const low = if ((d.imm & 1) == 0) source2 else source1_low;
        const high = if ((d.imm & 1) == 0) source1_high else source2;
        self.xmm[d.xmm_dst] = low;
        self.ymm_hi[d.xmm_dst] = high;
    }

    fn executeVexPermute2x128(self: *ElfState, d: DecodedInsn) void {
        const source1_low = self.xmm[d.xmm_src];
        const source1_high = self.ymm_hi[d.xmm_src];
        const source2_low = if (d.is_reg_form) self.xmm[d.xmm_src2] else self.readMem128(d.addr);
        const source2_high = if (d.is_reg_form) self.ymm_hi[d.xmm_src2] else self.readMem128(d.addr + 16);
        const selected_low = switch (d.imm & 0x03) {
            0 => source1_low,
            1 => source1_high,
            2 => source2_low,
            3 => source2_high,
            else => unreachable,
        };
        const selected_high = switch ((d.imm >> 4) & 0x03) {
            0 => source1_low,
            1 => source1_high,
            2 => source2_low,
            3 => source2_high,
            else => unreachable,
        };
        var result_low = selected_low;
        var result_high = selected_high;
        if ((d.imm & 0x08) != 0) @memset(&result_low, 0);
        if ((d.imm & 0x80) != 0) @memset(&result_high, 0);
        self.xmm[d.xmm_dst] = result_low;
        self.ymm_hi[d.xmm_dst] = result_high;
    }

    fn executeVphminposuw(self: *ElfState, d: DecodedInsn) void {
        const source = if (d.is_reg_form) self.xmm[d.xmm_src] else self.readMem128(d.addr);
        var minimum: u16 = std.math.maxInt(u16);
        var minimum_index: u16 = 0;
        for (0..8) |lane| {
            const value = std.mem.readInt(u16, source[lane * 2 ..][0..2], .little);
            if (value < minimum) {
                minimum = value;
                minimum_index = @intCast(lane);
            }
        }
        var result = [_]u8{0} ** 16;
        std.mem.writeInt(u16, result[0..2], minimum, .little);
        std.mem.writeInt(u16, result[2..4], minimum_index, .little);
        self.xmm[d.xmm_dst] = result;
        @memset(&self.ymm_hi[d.xmm_dst], 0);
    }

    fn executeVexInsertElement(self: *ElfState, d: DecodedInsn) void {
        const element_bytes: usize = switch (d.op) {
            .vpinsrb_xmm_xmm_reg32, .vpinsrb_xmm_xmm_mem8 => 1,
            .vpinsrw => 2,
            .vpinsrd => 4,
            .vpinsrq => 8,
            else => unreachable,
        };
        const destination_lane = @as(usize, @intCast(d.imm)) & ((16 / element_bytes) - 1);
        const source_size: Size = if (d.op == .vpinsrq) .bits64 else .bits32;
        const scalar = if (d.is_reg_form)
            self.regVal(d.src_reg, source_size)
        else
            self.readMemVal(d.addr, d.size);
        var result = self.xmm[d.xmm_src];
        switch (element_bytes) {
            1 => result[destination_lane] = @truncate(scalar),
            2 => std.mem.writeInt(u16, result[destination_lane * 2 ..][0..2], @truncate(scalar), .little),
            4 => std.mem.writeInt(u32, result[destination_lane * 4 ..][0..4], @truncate(scalar), .little),
            8 => std.mem.writeInt(u64, result[destination_lane * 8 ..][0..8], scalar, .little),
            else => unreachable,
        }
        self.xmm[d.xmm_dst] = result;
        @memset(&self.ymm_hi[d.xmm_dst], 0);
    }

    fn executeVexExtractElement(self: *ElfState, d: DecodedInsn) void {
        const element_bytes: usize = switch (d.op) {
            .vpextrb => 1,
            .vpextrw => 2,
            .vpextrd => 4,
            .vpextrq => 8,
            else => unreachable,
        };
        const source_lane = @as(usize, @intCast(d.imm)) & ((16 / element_bytes) - 1);
        const value: u64 = switch (element_bytes) {
            1 => self.xmm[d.xmm_src][source_lane],
            2 => std.mem.readInt(u16, self.xmm[d.xmm_src][source_lane * 2 ..][0..2], .little),
            4 => std.mem.readInt(u32, self.xmm[d.xmm_src][source_lane * 4 ..][0..4], .little),
            8 => std.mem.readInt(u64, self.xmm[d.xmm_src][source_lane * 8 ..][0..8], .little),
            else => unreachable,
        };
        if (d.is_reg_form) {
            const destination_size: Size = if (d.op == .vpextrq) .bits64 else .bits32;
            self.setReg(d.dst_reg, destination_size, value);
        } else {
            self.writeMemVal(d.addr, d.size, value);
        }
    }

    fn executeVinsertps(self: *ElfState, d: DecodedInsn) void {
        var result = self.xmm[d.xmm_src];
        const source_lane = @as(usize, @intCast((d.imm >> 6) & 0x03));
        const destination_lane = @as(usize, @intCast((d.imm >> 4) & 0x03));
        const scalar: u32 = if (d.is_reg_form)
            std.mem.readInt(u32, self.xmm[d.xmm_src2][source_lane * 4 ..][0..4], .little)
        else
            @truncate(self.readMemVal(d.addr, .bits32));
        std.mem.writeInt(u32, result[destination_lane * 4 ..][0..4], scalar, .little);
        for (0..4) |lane| {
            if ((d.imm & (@as(u8, 1) << @intCast(lane))) != 0) {
                @memset(result[lane * 4 ..][0..4], 0);
            }
        }
        self.xmm[d.xmm_dst] = result;
        @memset(&self.ymm_hi[d.xmm_dst], 0);
    }

    fn executeVectorSpecial(self: *ElfState, d: DecodedInsn) bool {
        switch (d.op) {
            .vptest, .vtestps, .vtestpd => self.executeVectorTest(d),
            .vextractf128, .vinsertf128, .vinserti128 => self.executeVexLane128(d),
            .vperm2f128 => self.executeVexPermute2x128(d),
            .vphminposuw => self.executeVphminposuw(d),
            .vpinsrb_xmm_xmm_reg32, .vpinsrb_xmm_xmm_mem8, .vpinsrd, .vpinsrq, .vpinsrw => self.executeVexInsertElement(d),
            .vpextrb, .vpextrw, .vpextrd, .vpextrq => self.executeVexExtractElement(d),
            .vinsertps => self.executeVinsertps(d),
            else => return false,
        }
        return true;
    }

    fn isVectorOperationRuntime(op: Op) bool {
        const name = @tagName(op);
        return (name.len != 0 and name[0] == 'v') or op == .pmovmskb;
    }

    fn isLegacyVectorTransfer(op: Op) bool {
        return switch (op) {
            .vmovd_xmm_reg32,
            .vmovd_xmm_mem32,
            .vmovd_reg32_xmm,
            .vmovd_mem32_xmm,
            .vmovq_xmm_reg64,
            .vmovq_xmm_mem64,
            .vmovq_reg64_xmm,
            .vmovq_mem64_xmm,
            .vmovq_xmm_xmm,
            => true,
            else => false,
        };
    }

    fn cleoVectorFromSource(self: *ElfState, d: DecodedInsn, index: u8, memory: bool, comptime bits: usize) cleo_routing.wide.Wide(bits) {
        var result = cleo_routing.wide.Wide(bits).zero();
        const low = if (memory) self.readMem128(d.addr) else self.xmm[index];
        @memcpy(result.bytes[0..16], low[0..]);
        if (comptime bits == 256) {
            const high = if (memory) self.readMem128(d.addr +% 16) else self.ymm_hi[index];
            @memcpy(result.bytes[16..32], high[0..]);
        }
        return result;
    }

    fn writeCleoVector(self: *ElfState, d: DecodedInsn, comptime bits: usize, value: cleo_routing.wide.Wide(bits)) void {
        @memcpy(self.xmm[d.xmm_dst][0..], value.bytes[0..16]);
        if (comptime bits == 256) {
            @memcpy(self.ymm_hi[d.xmm_dst][0..], value.bytes[16..32]);
        } else if (!d.legacy_sse) {
            // VEX.128 is a zeroing form. Legacy SSE leaves the architectural
            // upper YMM half untouched, which is why the decoder carries the
            // explicit legacy_sse bit.
            @memset(&self.ymm_hi[d.xmm_dst], 0);
        }
    }

    fn cleoIsFma(operation: cleo_routing.types.Operation) bool {
        return switch (operation) {
            .fma_ps,
            .fma_pd,
            .fms_ps,
            .fms_pd,
            .fnma_ps,
            .fnma_pd,
            .fnms_ps,
            .fnms_pd,
            .fma_addsub_ps,
            .fma_addsub_pd,
            .fma_subadd_ps,
            .fma_subadd_pd,
            => true,
            else => false,
        };
    }

    fn cleoIsUnary(operation: cleo_routing.types.Operation) bool {
        return switch (operation) {
            .sqrt_ps,
            .sqrt_pd,
            .cvt_pd2ps,
            .cvt_ps2pd,
            .cvt_dq2ps,
            .cvt_ps2dq,
            .cvtt_ps2dq,
            .pabs,
            .pnot,
            .compress_ps,
            .compress_pd,
            .expand_ps,
            .expand_pd,
            .cvt_pd2dq,
            .cvtt_pd2dq,
            .cvt_dq2pd,
            .cvt_ph2ps,
            .cvt_ps2ph,
            .cvt_bf16,
            => true,
            else => false,
        };
    }

    fn cleoIsImmediate(operation: cleo_routing.types.Operation) bool {
        return switch (operation) {
            .cmp_ps,
            .cmp_pd,
            .blend_ps,
            .blend_pd,
            .shuf_ps,
            .shuf_pd,
            .dpps,
            .range_ps,
            .range_pd,
            .fixup_ps,
            .fixup_pd,
            .permil,
            .byte_shift_left,
            .byte_shift_right,
            .insert_block,
            .insert_element,
            .insert_ps,
            .rotate_left,
            .rotate_right,
            .ternary_logic,
            .gf2p8_affine,
            .gf2p8_affine_inv,
            .sha1_rnds4,
            => true,
            else => false,
        };
    }

    fn cleoIsBinary(operation: cleo_routing.types.Operation) bool {
        return switch (operation) {
            .add_ps,
            .add_pd,
            .sub_ps,
            .sub_pd,
            .mul_ps,
            .mul_pd,
            .div_ps,
            .div_pd,
            .addsub_ps,
            .addsub_pd,
            .or_ps,
            .or_pd,
            .xor_ps,
            .xor_pd,
            .and_ps,
            .and_pd,
            .andn_ps,
            .andn_pd,
            .cmp_ps,
            .cmp_pd,
            .pmin_signed,
            .pmin_unsigned,
            .pmax_signed,
            .pmax_unsigned,
            .padd,
            .psub,
            .pcmpeq,
            .pcmpgt,
            .pmull,
            .psubs,
            .psubus,
            .psll,
            .psra,
            .psrl,
            .psign,
            .unpck_low,
            .unpck_high,
            .avg,
            .rotate_left_variable,
            .rotate_right_variable,
            .gf2p8_mul,
            .sha1_msg1,
            .sha1_msg2,
            .sha1_nexte,
            .sha256_msg1,
            .sha256_msg2,
            .sha256_rnds2,
            .scale_ps,
            .scale_pd,
            .permute_d,
            .permute_q,
            => true,
            else => false,
        };
    }

    fn executeCleoAtWidth(self: *ElfState, d: DecodedInsn, meta: cleo_routing.types.InstructionMeta, features: cleo_routing.types.FeatureSet, comptime bits: usize) ?cleo_routing.wide.Wide(bits) {
        if (cleoIsUnary(meta.operation)) {
            const source_is_memory = !d.is_reg_form;
            const source_index = if (d.legacy_sse) d.xmm_src2 else d.xmm_src;
            const source = self.cleoVectorFromSource(d, source_index, source_is_memory, bits);
            return cleo_routing.ops.executeUnary(bits, meta, source, features) catch null;
        }

        const source1_index = if (d.legacy_sse) d.xmm_dst else d.xmm_src;
        const source1 = self.cleoVectorFromSource(d, source1_index, false, bits);
        const source2 = self.cleoVectorFromSource(d, d.xmm_src2, !d.is_reg_form, bits);

        if (cleoIsFma(meta.operation)) {
            const op_name = @tagName(d.op);
            const has_132 = std.mem.indexOf(u8, op_name, "132") != null;
            const has_213 = std.mem.indexOf(u8, op_name, "213") != null;
            const destination = self.cleoVectorFromSource(d, d.xmm_dst, false, bits);

            // VEX FMA operand roles are encoded by the mnemonic suffix:
            //   132: dst = (dst * src2) + src1
            //   213: dst = (src1 * dst) + src2
            //   231: dst = (src1 * src2) + dst
            // `source1` is VEX.vvvv and `source2` is ModRM.r/m here.  Keep
            // the role mapping explicit because the operations are not
            // commutative once subtraction/negation is involved.
            const accum = if (has_132) source1 else if (has_213) source2 else destination;
            const lhs = if (has_132) destination else source1;
            const rhs = if (has_213) destination else source2;
            return cleo_routing.ops.executeAccumulate(bits, meta, accum, lhs, rhs, features) catch null;
        }

        if (d.uses_imm and cleoIsImmediate(meta.operation)) {
            return cleo_routing.ops.executeBinaryImmediate(bits, meta, source1, source2, @truncate(d.imm), features) catch null;
        }
        if (cleoIsBinary(meta.operation)) {
            return cleo_routing.ops.executeBinary(bits, meta, source1, source2, features) catch null;
        }
        return null;
    }

    fn executeCleoVectorMove(self: *ElfState, d: DecodedInsn) bool {
        switch (d.op) {
            .vmovntps, .vmovntdq => {
                // A non-temporal store is a store; the hint only concerns the
                // host cache, which an interpreter does not have.
                self.writeMem128(d.addr, self.xmm[d.xmm_src]);
                if (d.vector_256) self.writeMem128(d.addr +% 16, self.ymm_hi[d.xmm_src]);
                return true;
            },
            .vpsadbw => {
                // Each quadword becomes the sum of |a - b| over its eight
                // unsigned bytes, as a word, with the rest of it zero.
                const lanes: usize = if (d.vector_256) 2 else 1;
                var result = [_]u8{0} ** 32;
                for (0..lanes) |lane| {
                    const lhs = if (lane == 0) self.xmm[d.xmm_src] else self.ymm_hi[d.xmm_src];
                    const rhs = if (!d.is_reg_form)
                        self.readMem128(d.addr +% lane * 16)
                    else if (lane == 0)
                        self.xmm[d.xmm_src2]
                    else
                        self.ymm_hi[d.xmm_src2];
                    for (0..2) |quad| {
                        var sum: u16 = 0;
                        for (0..8) |index| {
                            const a: u16 = lhs[quad * 8 + index];
                            const b: u16 = rhs[quad * 8 + index];
                            sum += if (a > b) a - b else b - a;
                        }
                        std.mem.writeInt(u16, result[lane * 16 + quad * 8 ..][0..2], sum, .little);
                    }
                }
                @memcpy(&self.xmm[d.xmm_dst], result[0..16]);
                if (!d.legacy_sse) @memcpy(&self.ymm_hi[d.xmm_dst], result[16..32]);
                return true;
            },
            .vmovntdqa => {
                const low = self.readMem128(d.addr);
                self.ymm_hi[d.xmm_dst] = if (d.vector_256) self.readMem128(d.addr +% 16) else [_]u8{0} ** 16;
                self.xmm[d.xmm_dst] = low;
                return true;
            },
            .vcvtdq2pd => {
                // Two dwords become two doubles (VEX.128); four, from an XMM
                // or m128 source, become four (VEX.256).
                const count: usize = if (d.vector_256) 4 else 2;
                var result = [_]u8{0} ** 32;
                for (0..count) |index| {
                    const dword: u32 = if (d.is_reg_form)
                        std.mem.readInt(u32, self.xmm[d.xmm_src][index * 4 ..][0..4], .little)
                    else
                        @truncate(self.readMemVal(d.addr +% index * 4, .bits32));
                    const value: f64 = @floatFromInt(@as(i32, @bitCast(dword)));
                    std.mem.writeInt(u64, result[index * 8 ..][0..8], @bitCast(value), .little);
                }
                @memcpy(&self.xmm[d.xmm_dst], result[0..16]);
                @memcpy(&self.ymm_hi[d.xmm_dst], result[16..32]);
                return true;
            },
            .vcvttpd2dq => {
                const count: usize = if (d.vector_256) 4 else 2;
                var result = [_]u8{0} ** 16;
                for (0..count) |index| {
                    const bits: u64 = if (!d.is_reg_form)
                        self.readMemVal(d.addr +% index * 8, .bits64)
                    else if (index < 2)
                        std.mem.readInt(u64, self.xmm[d.xmm_src][index * 8 ..][0..8], .little)
                    else
                        std.mem.readInt(u64, self.ymm_hi[d.xmm_src][(index - 2) * 8 ..][0..8], .little);
                    const value: f64 = @bitCast(bits);
                    const dword: i32 = if (std.math.isNan(value) or value >= 0x1p31 or value < -0x1p31)
                        std.math.minInt(i32)
                    else
                        @intFromFloat(@trunc(value));
                    std.mem.writeInt(u32, result[index * 4 ..][0..4], @bitCast(dword), .little);
                }
                self.xmm[d.xmm_dst] = result;
                @memset(&self.ymm_hi[d.xmm_dst], 0);
                return true;
            },
            .vmovss_xmm_xmm_xmm, .vmovsd_xmm_xmm_xmm => {
                // Low element from xmm_src2, the rest of the lane from
                // VEX.vvvv, upper YMM lane cleared. Both sources are read
                // before the store because the destination may be either.
                var merged = self.xmm[d.xmm_src];
                const width: usize = if (d.op == .vmovss_xmm_xmm_xmm) 4 else 8;
                @memcpy(merged[0..width], self.xmm[d.xmm_src2][0..width]);
                self.xmm[d.xmm_dst] = merged;
                @memset(&self.ymm_hi[d.xmm_dst], 0);
                return true;
            },
            .vmovss_xmm_mem => {
                // MOVSS/VEX.MOVSS from memory clears the rest of XMM.  A
                // legacy SSE form leaves the architectural YMM upper half
                // alone, while VEX.128 also clears that upper half.
                @memset(&self.xmm[d.xmm_dst], 0);
                std.mem.writeInt(u32, self.xmm[d.xmm_dst][0..4], @truncate(self.readMemVal(d.addr, .bits32)), .little);
                if (!d.legacy_sse) @memset(&self.ymm_hi[d.xmm_dst], 0);
                return true;
            },
            .vmovsd_xmm_mem => {
                // The scalar double-precision memory form has the same
                // upper-lane rule, with an eight-byte low element.
                @memset(&self.xmm[d.xmm_dst], 0);
                std.mem.writeInt(u64, self.xmm[d.xmm_dst][0..8], self.readMemVal(d.addr, .bits64), .little);
                if (!d.legacy_sse) @memset(&self.ymm_hi[d.xmm_dst], 0);
                return true;
            },
            .vmovss_mem_xmm => {
                self.writeMemVal(d.addr, .bits32, std.mem.readInt(u32, self.xmm[d.xmm_src][0..4], .little));
                return true;
            },
            .vmovsd_mem_xmm => {
                self.writeMemVal(d.addr, .bits64, std.mem.readInt(u64, self.xmm[d.xmm_src][0..8], .little));
                return true;
            },
            .vmovss_xmm_xmm => {
                const source = std.mem.readInt(u32, self.xmm[d.xmm_src][0..4], .little);
                if (!d.legacy_sse) @memset(&self.xmm[d.xmm_dst], 0);
                std.mem.writeInt(u32, self.xmm[d.xmm_dst][0..4], source, .little);
                if (!d.legacy_sse) @memset(&self.ymm_hi[d.xmm_dst], 0);
                return true;
            },
            .vmovsd_xmm_xmm => {
                const source = std.mem.readInt(u64, self.xmm[d.xmm_src][0..8], .little);
                if (!d.legacy_sse) @memset(&self.xmm[d.xmm_dst], 0);
                std.mem.writeInt(u64, self.xmm[d.xmm_dst][0..8], source, .little);
                if (!d.legacy_sse) @memset(&self.ymm_hi[d.xmm_dst], 0);
                return true;
            },
            .vmovq_xmm_xmm => {
                var result = self.xmm[d.xmm_src];
                @memset(result[8..16], 0);
                self.xmm[d.xmm_dst] = result;
                if (!d.legacy_sse) @memset(&self.ymm_hi[d.xmm_dst], 0);
                return true;
            },
            .vmovlps_xmm_xmm_mem64, .vmovlpd_xmm_xmm_mem64 => {
                self.xmm[d.xmm_dst] = self.xmm[d.xmm_src];
                std.mem.writeInt(u64, self.xmm[d.xmm_dst][0..8], self.readMemVal(d.addr, .bits64), .little);
                if (!d.legacy_sse) @memset(&self.ymm_hi[d.xmm_dst], 0);
                return true;
            },
            .vmovlps_mem64_xmm, .vmovlpd_mem64_xmm => {
                self.writeMemVal(d.addr, .bits64, std.mem.readInt(u64, self.xmm[d.xmm_src][0..8], .little));
                return true;
            },
            .vmovhps_xmm_xmm_mem64, .vmovhpd_xmm_xmm_mem64 => {
                self.xmm[d.xmm_dst] = self.xmm[d.xmm_src];
                std.mem.writeInt(u64, self.xmm[d.xmm_dst][8..16], self.readMemVal(d.addr, .bits64), .little);
                if (!d.legacy_sse) @memset(&self.ymm_hi[d.xmm_dst], 0);
                return true;
            },
            .vmovhps_mem64_xmm, .vmovhpd_mem64_xmm => {
                self.writeMemVal(d.addr, .bits64, std.mem.readInt(u64, self.xmm[d.xmm_src][8..16], .little));
                return true;
            },
            .vmovhlps => {
                @memcpy(self.xmm[d.xmm_dst][0..8], self.xmm[d.xmm_src][8..16]);
                if (!d.legacy_sse) @memset(&self.ymm_hi[d.xmm_dst], 0);
                return true;
            },
            .vmovlhps => {
                @memcpy(self.xmm[d.xmm_dst][8..16], self.xmm[d.xmm_src][0..8]);
                if (!d.legacy_sse) @memset(&self.ymm_hi[d.xmm_dst], 0);
                return true;
            },
            else => {},
        }

        const is_load = switch (d.op) {
            .vmovdqu_xmm_mem,
            .vmovdqa_xmm_mem,
            .vmovups_xmm_mem,
            .vmovaps_xmm_mem,
            .vmovupd_xmm_mem,
            .vmovapd_xmm_mem,
            .vmovdqu_ymm_mem,
            .vmovdqa_ymm_mem,
            .vmovups_ymm_mem,
            .vmovaps_ymm_mem,
            .vmovupd_ymm_mem,
            .vmovapd_ymm_mem,
            => true,
            else => false,
        };
        const is_store = switch (d.op) {
            .vmovdqu_mem_xmm,
            .vmovdqa_mem_xmm,
            .vmovups_mem_xmm,
            .vmovaps_mem_xmm,
            .vmovupd_mem_xmm,
            .vmovapd_mem_xmm,
            .vmovdqu_mem_ymm,
            .vmovdqa_mem_ymm,
            .vmovups_mem_ymm,
            .vmovaps_mem_ymm,
            .vmovupd_mem_ymm,
            .vmovapd_mem_ymm,
            => true,
            else => false,
        };
        const is_register = switch (d.op) {
            .vmovdqu_xmm_xmm,
            .vmovdqa_xmm_xmm,
            .vmovups_xmm_xmm,
            .vmovaps_xmm_xmm,
            .vmovupd_xmm_xmm,
            .vmovapd_xmm_xmm,
            .vmovdqu_ymm_ymm,
            .vmovdqa_ymm_ymm,
            .vmovups_ymm_ymm,
            .vmovaps_ymm_ymm,
            .vmovupd_ymm_ymm,
            .vmovapd_ymm_ymm,
            => true,
            else => false,
        };
        if (!is_load and !is_store and !is_register) return false;

        if (is_load) {
            self.xmm[d.xmm_dst] = self.readMem128(d.addr);
            if (d.vector_256) {
                self.ymm_hi[d.xmm_dst] = self.readMem128(d.addr +% 16);
            } else if (!d.legacy_sse) {
                @memset(&self.ymm_hi[d.xmm_dst], 0);
            }
        } else if (is_store) {
            self.writeMem128(d.addr, self.xmm[d.xmm_src]);
            if (d.vector_256) self.writeMem128(d.addr +% 16, self.ymm_hi[d.xmm_src]);
        } else {
            self.xmm[d.xmm_dst] = self.xmm[d.xmm_src];
            if (d.vector_256) self.ymm_hi[d.xmm_dst] = self.ymm_hi[d.xmm_src] else @memset(&self.ymm_hi[d.xmm_dst], 0);
        }
        return true;
    }

    fn tryExecuteCleo(self: *ElfState, d: DecodedInsn) bool {
        // CLEO is an SIMD/VEX/EVEX fallback. Scalar instructions can never
        // route to its registry, so keep them out of this hot path. Legacy
        // scalar-vector move tags are handled by the explicit executor.
        if (!isVectorOperationRuntime(d.op)) return false;
        const route = cleo_routing.CleoRouter.route(
            @tagName(d.op),
            cleo_routing.types.FeatureSet.cleoEmulated(),
            if (d.vector_256) 256 else 128,
        );
        const meta = route.meta orelse return false;
        if (!route.can_route) return false;
        if (!cleoIsFma(meta.operation) and !cleoIsUnary(meta.operation) and
            !(d.uses_imm and cleoIsImmediate(meta.operation)) and !cleoIsBinary(meta.operation)) return false;

        if (d.vector_256) {
            if (self.executeCleoAtWidth(d, meta, route.features, 256)) |result| {
                self.writeCleoVector(d, 256, result);
                return true;
            }
        } else if (self.executeCleoAtWidth(d, meta, route.features, 128)) |result| {
            self.writeCleoVector(d, 128, result);
            return true;
        }
        return false;
    }

    fn vexArithmeticForOp(op: Op) vector_helpers.VexArithmetic {
        return switch (op) {
            .vaddss, .vaddsd, .vaddps, .vaddpd => .add,
            .vmulss, .vmulsd, .vmulps, .vmulpd => .multiply,
            .vsubss, .vsubsd, .vsubps, .vsubpd => .subtract,
            .vdivss, .vdivsd, .vdivps, .vdivpd => .divide,
            .vminss, .vminsd, .vminps, .vminpd => .minimum,
            .vmaxss, .vmaxsd, .vmaxps, .vmaxpd => .maximum,
            else => unreachable,
        };
    }

    fn vexBitwiseForOp(op: Op) vector_helpers.VexBitwise {
        return switch (op) {
            .vandps, .vandpd, .vpand => .@"and",
            .vandnps, .vandnpd, .vpandn => .and_not,
            .vorps, .vorpd, .vpor => .@"or",
            .vxorps, .vxorpd, .vpxor => .xor,
            else => unreachable,
        };
    }

    fn executeVexShufflePd(self: *ElfState, d: DecodedInsn) void {
        // A control bit picks an element within a source, never a source:
        // element 0 is SRC1[bit 0], element 1 is SRC2[bit 1], and the upper
        // lane repeats that with bits 2 and 3. Treating the bit as the source
        // made libstdc++'s mt19937_64 twist and its u64-to-double conversion
        // wrong, and with them every std::uniform_real_distribution.
        const source1_low = self.xmm[d.xmm_src];
        const source2_low = if (d.is_reg_form) self.xmm[d.xmm_src2] else self.readMem128(d.addr);
        const result_low = shufflePackedDoublesLane(source1_low, source2_low, @truncate(d.imm));

        if (d.vector_256) {
            const source1_high = self.ymm_hi[d.xmm_src];
            const source2_high = if (d.is_reg_form) self.ymm_hi[d.xmm_src2] else self.readMem128(d.addr +% 16);
            self.ymm_hi[d.xmm_dst] = shufflePackedDoublesLane(source1_high, source2_high, @truncate(d.imm >> 2));
            self.xmm[d.xmm_dst] = result_low;
        } else {
            self.xmm[d.xmm_dst] = result_low;
            // All VEX.128 instructions zero the destination register's YMM
            // upper half, unlike legacy SSE encodings.
            if (!d.legacy_sse) @memset(&self.ymm_hi[d.xmm_dst], 0);
        }
    }

    /// Execute the VEX floating-point/bitwise subset shared with Mach-O.
    /// Keeping this before the fallback switch is important: the fallback is
    /// intentionally conservative and must never turn an arithmetic vector
    /// instruction into a flags-only operation.
    fn executeSharedVex(self: *ElfState, d: DecodedInsn) bool {
        switch (d.op) {
            .vcvtsi2ss_xmm_reg, .vcvtsi2ss_xmm_mem => {
                self.xmm[d.xmm_dst] = self.xmm[d.xmm_src];
                if (!d.legacy_sse) @memset(&self.ymm_hi[d.xmm_dst], 0);
                const integer: i64 = if (d.size == .bits64)
                    @bitCast(if (d.op == .vcvtsi2ss_xmm_reg) self.regVal(d.src_reg, .bits64) else self.readMemVal(d.addr, .bits64))
                else
                    @as(i32, @bitCast(@as(u32, @truncate(if (d.op == .vcvtsi2ss_xmm_reg) self.regVal(d.src_reg, .bits32) else self.readMemVal(d.addr, .bits32)))));
                std.mem.writeInt(u32, self.xmm[d.xmm_dst][0..4], @bitCast(@as(f32, @floatFromInt(integer))), .little);
                return true;
            },
            .vcvtsi2sd_xmm_reg, .vcvtsi2sd_xmm_mem => {
                self.xmm[d.xmm_dst] = self.xmm[d.xmm_src];
                if (!d.legacy_sse) @memset(&self.ymm_hi[d.xmm_dst], 0);
                const integer: i64 = if (d.size == .bits64)
                    @bitCast(if (d.op == .vcvtsi2sd_xmm_reg) self.regVal(d.src_reg, .bits64) else self.readMemVal(d.addr, .bits64))
                else
                    @as(i32, @bitCast(@as(u32, @truncate(if (d.op == .vcvtsi2sd_xmm_reg) self.regVal(d.src_reg, .bits32) else self.readMemVal(d.addr, .bits32)))));
                std.mem.writeInt(u64, self.xmm[d.xmm_dst][0..8], @bitCast(@as(f64, @floatFromInt(integer))), .little);
                return true;
            },
            .vcvtss2sd => {
                self.xmm[d.xmm_dst] = self.xmm[d.xmm_src];
                if (!d.legacy_sse) @memset(&self.ymm_hi[d.xmm_dst], 0);
                const source_bits: u32 = if (d.is_reg_form)
                    std.mem.readInt(u32, self.xmm[d.xmm_src2][0..4], .little)
                else
                    @truncate(self.readMemVal(d.addr, .bits32));
                const converted: f64 = @floatCast(@as(f32, @bitCast(source_bits)));
                std.mem.writeInt(u64, self.xmm[d.xmm_dst][0..8], @bitCast(converted), .little);
                return true;
            },
            .vcvtsd2ss => {
                self.xmm[d.xmm_dst] = self.xmm[d.xmm_src];
                if (!d.legacy_sse) @memset(&self.ymm_hi[d.xmm_dst], 0);
                const source_bits: u64 = if (d.is_reg_form)
                    std.mem.readInt(u64, self.xmm[d.xmm_src2][0..8], .little)
                else
                    self.readMemVal(d.addr, .bits64);
                const converted: f32 = @floatCast(@as(f64, @bitCast(source_bits)));
                std.mem.writeInt(u32, self.xmm[d.xmm_dst][0..4], @bitCast(converted), .little);
                return true;
            },
            .vcvtps2pd => {
                vector_helpers.executeVexConvertFloatPacked(self, d, .single_to_double);
                return true;
            },
            .vcvtpd2ps => {
                vector_helpers.executeVexConvertFloatPacked(self, d, .double_to_single);
                return true;
            },
            .vaddss, .vmulss, .vsubss, .vdivss, .vminss, .vmaxss => {
                vector_helpers.executeVexScalarF32(self, d, vexArithmeticForOp(d.op));
                return true;
            },
            .vaddsd, .vmulsd, .vsubsd, .vdivsd, .vminsd, .vmaxsd => {
                vector_helpers.executeVexScalarF64(self, d, vexArithmeticForOp(d.op));
                return true;
            },
            .vaddps, .vmulps, .vsubps, .vdivps, .vminps, .vmaxps => {
                vector_helpers.executeVexPackedF32(self, d, vexArithmeticForOp(d.op));
                return true;
            },
            .vaddpd, .vmulpd, .vsubpd, .vdivpd, .vminpd, .vmaxpd => {
                vector_helpers.executeVexPackedF64(self, d, vexArithmeticForOp(d.op));
                return true;
            },
            .vpacksswb, .vpackuswb, .vpackssdw, .vpackusdw => {
                const operation: vector_helpers.PackedPackOperation = switch (d.op) {
                    .vpacksswb => .signed_words_to_bytes,
                    .vpackuswb => .unsigned_words_to_bytes,
                    .vpackssdw => .signed_dwords_to_words,
                    .vpackusdw => .unsigned_dwords_to_words,
                    else => unreachable,
                };
                vector_helpers.executeVexPackedPack(self, d, operation);
                return true;
            },
            .vsqrtss => {
                vector_helpers.executeVexSqrtScalarF32(self, d);
                return true;
            },
            .vsqrtsd => {
                vector_helpers.executeVexSqrtScalarF64(self, d);
                return true;
            },
            .vsqrtps => {
                vector_helpers.executeVexSqrtPackedF32(self, d);
                return true;
            },
            .vsqrtpd => {
                vector_helpers.executeVexSqrtPackedF64(self, d);
                return true;
            },
            .vcmpps => {
                if (!vector_helpers.executeVexComparePacked(self, d, false)) self.terminateUnimplemented(d);
                return true;
            },
            .vcmppd => {
                if (!vector_helpers.executeVexComparePacked(self, d, true)) self.terminateUnimplemented(d);
                return true;
            },
            .vcmpss => {
                if (!vector_helpers.executeVexCompareScalar(self, d, false)) self.terminateUnimplemented(d);
                return true;
            },
            .vcmpsd => {
                if (!vector_helpers.executeVexCompareScalar(self, d, true)) self.terminateUnimplemented(d);
                return true;
            },
            .vshufpd => {
                self.executeVexShufflePd(d);
                return true;
            },
            .vunpcklps, .vunpckhps, .vunpcklpd, .vunpckhpd => {
                vector_helpers.executeVexPackedUnpack(self, d);
                return true;
            },
            .vrcpps => {
                vector_helpers.executeVexReciprocalPacked(self, d, false);
                return true;
            },
            .vrsqrtps => {
                vector_helpers.executeVexReciprocalPacked(self, d, true);
                return true;
            },
            .vrcpss => {
                vector_helpers.executeVexReciprocalScalar(self, d, false);
                return true;
            },
            .vrsqrtss => {
                vector_helpers.executeVexReciprocalScalar(self, d, true);
                return true;
            },
            .vcvtdq2ps => {
                vector_helpers.executeVexConvertPacked(self, d, .dword_to_float);
                return true;
            },
            .vcvtps2dq => {
                vector_helpers.executeVexConvertPacked(self, d, .float_to_dword_round);
                return true;
            },
            .vcvttps2dq => {
                vector_helpers.executeVexConvertPacked(self, d, .float_to_dword_truncate);
                return true;
            },
            .vucomiss => {
                const lhs: f32 = @bitCast(std.mem.readInt(u32, self.xmm[d.xmm_src][0..4], .little));
                const rhs_bits: u32 = if (d.is_reg_form)
                    std.mem.readInt(u32, self.xmm[d.xmm_src2][0..4], .little)
                else
                    @truncate(self.readMemVal(d.addr, .bits32));
                vector_helpers.setVexComparisonFlags(self, lhs, @as(f32, @bitCast(rhs_bits)));
                return true;
            },
            .vucomisd => {
                const lhs: f64 = @bitCast(std.mem.readInt(u64, self.xmm[d.xmm_src][0..8], .little));
                const rhs_bits: u64 = if (d.is_reg_form)
                    std.mem.readInt(u64, self.xmm[d.xmm_src2][0..8], .little)
                else
                    self.readMemVal(d.addr, .bits64);
                vector_helpers.setVexComparisonFlags(self, lhs, @as(f64, @bitCast(rhs_bits)));
                return true;
            },
            .vandps, .vandpd, .vandnps, .vandnpd, .vorps, .vorpd, .vxorps, .vxorpd, .vpor, .vpand, .vpandn, .vpxor => {
                vector_helpers.executeVexBitwise(self, d, vexBitwiseForOp(d.op));
                return true;
            },
            .vroundss => {
                vector_helpers.executeVexRoundScalarF32(self, d);
                return true;
            },
            .vroundsd => {
                vector_helpers.executeVexRoundScalarF64(self, d);
                return true;
            },
            .vroundps => {
                vector_helpers.executeVexRoundPackedF32(self, d);
                return true;
            },
            .vroundpd => {
                vector_helpers.executeVexRoundPackedF64(self, d);
                return true;
            },
            .vcvttss2si => {
                vector_helpers.executeVexFloatToSigned(self, d, false, true);
                return true;
            },
            .vcvtss2si => {
                vector_helpers.executeVexFloatToSigned(self, d, false, false);
                return true;
            },
            .vcvttsd2si => {
                vector_helpers.executeVexFloatToSigned(self, d, true, true);
                return true;
            },
            .vcvtsd2si => {
                vector_helpers.executeVexFloatToSigned(self, d, true, false);
                return true;
            },
            .pmovmskb, .vpmovmskb, .vpmovmskb_ymm, .vmovmskps, .vmovmskpd => {
                vector_helpers.executeVexMoveMask(self, d);
                return true;
            },
            .vpmuludq => {
                vector_helpers.executeVexMultiplyUnsignedEvenDwords(self, d);
                return true;
            },
            .vpblendw => {
                vector_helpers.executeVexBlendWords(self, d);
                return true;
            },
            .vblendvps => {
                vector_helpers.executeVexBlendVariable(self, d, 32);
                return true;
            },
            .vblendvpd => {
                vector_helpers.executeVexBlendVariable(self, d, 64);
                return true;
            },
            .vpblendvb => {
                vector_helpers.executeVexBlendVariable(self, d, 8);
                return true;
            },
            .vpsllw => {
                vector_helpers.executeVexPackedShift(self, d, 16, true, false, false);
                return true;
            },
            .vpsrlw => {
                vector_helpers.executeVexPackedShift(self, d, 16, false, false, false);
                return true;
            },
            .vpsraw => {
                vector_helpers.executeVexPackedShift(self, d, 16, false, true, false);
                return true;
            },
            .vpslld => {
                vector_helpers.executeVexPackedShift(self, d, 32, true, false, false);
                return true;
            },
            .vpsrld => {
                vector_helpers.executeVexPackedShift(self, d, 32, false, false, false);
                return true;
            },
            .vpsrad => {
                vector_helpers.executeVexPackedShift(self, d, 32, false, true, false);
                return true;
            },
            .vpsllq => {
                vector_helpers.executeVexPackedShift(self, d, 64, true, false, false);
                return true;
            },
            .vpsrlq => {
                vector_helpers.executeVexPackedShift(self, d, 64, false, false, false);
                return true;
            },
            .vpslldq => {
                vector_helpers.executeVexPackedShift(self, d, 8, true, false, true);
                return true;
            },
            .vpsrldq => {
                vector_helpers.executeVexPackedShift(self, d, 8, false, false, true);
                return true;
            },
            .vpmullw => {
                vector_helpers.executeVexPackedInteger(self, d, 16, .mul_low);
                return true;
            },
            .vpmulld_38 => {
                vector_helpers.executeVexPackedInteger(self, d, 32, .mul_low);
                return true;
            },
            .vpmulhw => {
                vector_helpers.executeVexPackedMulHigh(self, d, true);
                return true;
            },
            .vpmulhuw => {
                vector_helpers.executeVexPackedMulHigh(self, d, false);
                return true;
            },
            // Decoded but refused as unimplemented, or not decoded at all,
            // before the Xenia JIT corpus test named them.
            .vpaddsb => {
                vector_helpers.executeVexPackedInteger(self, d, 8, .add_signed_saturate);
                return true;
            },
            .vpaddsw => {
                vector_helpers.executeVexPackedInteger(self, d, 16, .add_signed_saturate);
                return true;
            },
            .vpaddusb => {
                vector_helpers.executeVexPackedInteger(self, d, 8, .add_unsigned_saturate);
                return true;
            },
            .vpaddusw => {
                vector_helpers.executeVexPackedInteger(self, d, 16, .add_unsigned_saturate);
                return true;
            },
            .vpsubusb => {
                vector_helpers.executeVexPackedInteger(self, d, 8, .sub_unsigned_saturate);
                return true;
            },
            .vpavgb => {
                vector_helpers.executeVexPackedInteger(self, d, 8, .average_unsigned);
                return true;
            },
            .vpavgw => {
                vector_helpers.executeVexPackedInteger(self, d, 16, .average_unsigned);
                return true;
            },
            .vpminsw => {
                vector_helpers.executeVexPackedMinMax(self, d, .{ .lane_bits = 16, .signed = true, .take_max = false });
                return true;
            },
            .vpmaxsw => {
                vector_helpers.executeVexPackedMinMax(self, d, .{ .lane_bits = 16, .signed = true, .take_max = true });
                return true;
            },
            .vpminsb => {
                vector_helpers.executeVexPackedMinMax(self, d, .{ .lane_bits = 8, .signed = true, .take_max = false });
                return true;
            },
            .vpminsd => {
                vector_helpers.executeVexPackedMinMax(self, d, .{ .lane_bits = 32, .signed = true, .take_max = false });
                return true;
            },
            .vpminuw => {
                vector_helpers.executeVexPackedMinMax(self, d, .{ .lane_bits = 16, .signed = false, .take_max = false });
                return true;
            },
            .vpminud => {
                vector_helpers.executeVexPackedMinMax(self, d, .{ .lane_bits = 32, .signed = false, .take_max = false });
                return true;
            },
            .vpminub => {
                vector_helpers.executeVexPackedMinMax(self, d, .{ .lane_bits = 8, .signed = false, .take_max = false });
                return true;
            },
            .vpmaxsb => {
                vector_helpers.executeVexPackedMinMax(self, d, .{ .lane_bits = 8, .signed = true, .take_max = true });
                return true;
            },
            .vpmaxsd => {
                vector_helpers.executeVexPackedMinMax(self, d, .{ .lane_bits = 32, .signed = true, .take_max = true });
                return true;
            },
            .vpmaxuw => {
                vector_helpers.executeVexPackedMinMax(self, d, .{ .lane_bits = 16, .signed = false, .take_max = true });
                return true;
            },
            .vpmaxud => {
                vector_helpers.executeVexPackedMinMax(self, d, .{ .lane_bits = 32, .signed = false, .take_max = true });
                return true;
            },
            .vpmaxub => {
                vector_helpers.executeVexPackedMinMax(self, d, .{ .lane_bits = 8, .signed = false, .take_max = true });
                return true;
            },
            else => return false,
        }
    }

    fn executeHighwayRegisterBinary(self: *ElfState, d: DecodedInsn, op: x64_decoder.highway.BinaryOp) void {
        const width: x64_decoder.highway.Width = switch (d.size) {
            .bits8 => .bits8,
            .bits16 => .bits16,
            .bits32 => .bits32,
            .bits64 => .bits64,
        };
        const lhs = self.decodedRegVal(d.dst_reg, d.dst_high8, d.size);
        const rhs = self.decodedRegVal(d.src_reg, d.src_high8, d.size);
        const evaluated = x64_decoder.highway.evaluate(op, width, lhs, rhs, self.regs.rflags);
        if (shouldTraceRip(self, self.regs.rip)) {
            log.info("trace highway binary rip=0x{x} op={s} size={s} lhs=0x{x} rhs=0x{x} input_flags=0x{x} output_flags=0x{x} writeback={}", .{
                self.regs.rip,
                @tagName(op),
                @tagName(width),
                lhs,
                rhs,
                self.regs.rflags,
                evaluated.rflags,
                evaluated.writeback,
            });
        }
        self.regs.rflags = evaluated.rflags;
        if (evaluated.writeback) self.setDecodedReg(d.dst_reg, d.dst_high8, d.size, evaluated.value);
    }

    fn terminateForMemoryAccess(self: *ElfState, d: DecodedInsn, check: x64_decoder.highway.MemoryCheck) void {
        self.faulted = true;
        self.terminated = true;
        self.exit_code = 127;
        self.termination_reason = .memory_access_violation;
        log.err(
            "PE64 memory access violation: rip=0x{x} op={s} address=0x{x} bytes={d} access={s} fault={s} guest_range=[0x{x},0x{x}) regs(rax=0x{x} rbx=0x{x} rcx=0x{x} rdx=0x{x} rsp=0x{x})",
            .{
                self.regs.rip,
                @tagName(d.op),
                check.address,
                check.bytes,
                @tagName(check.access),
                if (check.fault) |fault| @tagName(fault) else "none",
                self.mem_base,
                self.mem_base +| self.mem.len,
                self.regs.rax,
                self.regs.rbx,
                self.regs.rcx,
                self.regs.rdx,
                self.regs.rsp,
            },
        );
    }

    fn validateGuestMemoryRange(
        self: *const ElfState,
        address: u64,
        width: x64_decoder.highway.Width,
        access: x64_decoder.highway.MemoryAccess,
        permitted: bool,
    ) x64_decoder.highway.MemoryCheck {
        const bytes: u8 = width.bits() / 8;
        if (self.windowsGuestRangeContains(address, bytes)) {
            return .{
                .address = address,
                .bytes = bytes,
                .access = access,
                .fault = if (permitted) null else .permission_denied,
            };
        }
        return x64_decoder.highway.validateRange(self.mem_base, self.mem.len, address, width, access, permitted);
    }

    fn executeHighwayMemoryBinary(
        self: *ElfState,
        d: DecodedInsn,
        op: x64_decoder.highway.BinaryOp,
        direction: x64_decoder.highway.MemoryDirection,
    ) void {
        const width: x64_decoder.highway.Width = switch (d.size) {
            .bits8 => .bits8,
            .bits16 => .bits16,
            .bits32 => .bits32,
            .bits64 => .bits64,
        };
        const access: x64_decoder.highway.MemoryAccess = if (direction == .register_to_memory and op != .cmp and op != .test_bits) .write else .read;
        const check = self.validateGuestMemoryRange(d.addr, width, access, true);
        if (!check.allowed()) {
            self.terminateForMemoryAccess(d, check);
            return;
        }
        const reg = if (direction == .memory_to_register) d.dst_reg else d.src_reg;
        const high8 = if (direction == .memory_to_register) d.dst_high8 else d.src_high8;
        const evaluated = x64_decoder.highway.evaluateMemory(op, width, self.decodedRegVal(reg, high8, d.size), self.readMemVal(d.addr, d.size), direction, self.regs.rflags);
        self.regs.rflags = evaluated.rflags;
        if (evaluated.write_register) self.setDecodedReg(reg, high8, d.size, evaluated.value);
        if (evaluated.write_memory) self.writeMemVal(d.addr, d.size, evaluated.value);
    }

    fn executeHighwayImmediate(self: *ElfState, d: DecodedInsn, op: x64_decoder.highway.BinaryOp, memory: bool, immediate: u64) void {
        const width: x64_decoder.highway.Width = switch (d.size) {
            .bits8 => .bits8,
            .bits16 => .bits16,
            .bits32 => .bits32,
            .bits64 => .bits64,
        };
        if (memory) {
            const access: x64_decoder.highway.MemoryAccess = if (op == .cmp or op == .test_bits) .read else .write;
            const check = self.validateGuestMemoryRange(d.addr, width, access, true);
            if (!check.allowed()) {
                self.terminateForMemoryAccess(d, check);
                return;
            }
        }
        const lhs = if (memory) self.readMemVal(d.addr, d.size) else self.decodedRegVal(d.dst_reg, d.dst_high8, d.size);
        const evaluated = x64_decoder.highway.evaluate(op, width, lhs, immediate, self.regs.rflags);
        self.regs.rflags = evaluated.rflags;
        if (evaluated.writeback) {
            if (memory) self.writeMemVal(d.addr, d.size, evaluated.value) else self.setDecodedReg(d.dst_reg, d.dst_high8, d.size, evaluated.value);
        }
    }

    fn executeAccumulatorImmediate(self: *ElfState, d: DecodedInsn) void {
        const op: x64_decoder.highway.BinaryOp = switch (d.op) {
            .add_accum_imm => .add,
            .or_accum_imm => .bit_or,
            .adc_accum_imm => .adc,
            .sbb_accum_imm => .sbb,
            .and_accum_imm => .bit_and,
            .sub_accum_imm => .sub,
            .xor_accum_imm => .bit_xor,
            .cmp_accum_imm => .cmp,
            else => unreachable,
        };
        self.executeHighwayImmediate(d, op, false, testImmForSize(d.imm, d.size));
    }

    fn isAccumulatorImmediate(op: Op) bool {
        return switch (op) {
            .add_accum_imm,
            .or_accum_imm,
            .adc_accum_imm,
            .sbb_accum_imm,
            .and_accum_imm,
            .sub_accum_imm,
            .xor_accum_imm,
            .cmp_accum_imm,
            => true,
            else => false,
        };
    }

    fn setFlag(self: *ElfState, flag: u32, enabled: bool) void {
        if (enabled) {
            self.regs.rflags |= flag;
        } else {
            self.regs.rflags &= ~flag;
        }
    }

    fn executeBitTestRegister(
        self: *ElfState,
        d: DecodedInsn,
        operation: x64_decoder.BitTestOperation,
        immediate_index: bool,
    ) void {
        const value = self.regVal(d.dst_reg, d.size);
        const raw_index = if (immediate_index) d.imm else self.regVal(d.src_reg, d.size);
        const result = x64_decoder.bitTestRegister(d.size, value, raw_index, operation);
        self.setFlag(RFL_CF, result.carry);
        if (operation != .probe) self.setReg(d.dst_reg, d.size, result.value);
    }

    fn executeBitTestMemory(
        self: *ElfState,
        d: DecodedInsn,
        operation: x64_decoder.BitTestOperation,
        immediate_index: bool,
    ) void {
        const operand = if (immediate_index)
            x64_decoder.bitTestMemoryOperandImmediate(d.size, d.addr, d.imm)
        else
            x64_decoder.bitTestMemoryOperand(d.size, d.addr, self.regVal(d.src_reg, d.size));
        const resolved = operand orelse {
            self.faulted = true;
            self.terminated = true;
            self.exit_code = 127;
            self.termination_reason = .memory_access_violation;
            log.err("PE64 bit-test memory operand overflow: rip=0x{x} op={s} address=0x{x} size={s} index=0x{x}", .{
                self.regs.rip,
                @tagName(d.op),
                d.addr,
                @tagName(d.size),
                if (immediate_index) d.imm else self.regVal(d.src_reg, d.size),
            });
            return;
        };
        const value = self.readMemVal(resolved.address, d.size);
        const result = x64_decoder.bitTestRegister(d.size, value, resolved.bit_index, operation);
        self.setFlag(RFL_CF, result.carry);
        if (operation != .probe) self.writeMemVal(resolved.address, d.size, result.value);
    }

    fn bitWidth(size: Size) u7 {
        return switch (size) {
            .bits8 => 8,
            .bits16 => 16,
            .bits32 => 32,
            .bits64 => 64,
        };
    }

    fn maskForSize(size: Size) u64 {
        return switch (size) {
            .bits8 => 0xFF,
            .bits16 => 0xFFFF,
            .bits32 => 0xFFFF_FFFF,
            .bits64 => 0xFFFF_FFFF_FFFF_FFFF,
        };
    }

    fn signBitForSize(size: Size) u64 {
        return switch (size) {
            .bits8 => 0x80,
            .bits16 => 0x8000,
            .bits32 => 0x8000_0000,
            .bits64 => 0x8000_0000_0000_0000,
        };
    }

    fn signedInteger(value: u64, size: Size) i128 {
        return switch (size) {
            .bits8 => @as(i128, @as(i8, @bitCast(@as(u8, @truncate(value))))),
            .bits16 => @as(i128, @as(i16, @bitCast(@as(u16, @truncate(value))))),
            .bits32 => @as(i128, @as(i32, @bitCast(@as(u32, @truncate(value))))),
            .bits64 => @as(i128, @as(i64, @bitCast(value))),
        };
    }

    fn imulImmediateSize(op: Op) Size {
        return switch (op) {
            .imul_reg16_mem16_imm8,
            .imul_reg16_reg16_imm8,
            .imul_reg16_mem16_imm16,
            .imul_reg16_reg16_imm16,
            => .bits16,
            .imul_reg32_mem32_imm8,
            .imul_reg32_reg32_imm8,
            .imul_reg32_mem32_imm32,
            .imul_reg32_reg32_imm32,
            => .bits32,
            .imul_reg64_mem64_imm8,
            .imul_reg64_reg64_imm8,
            .imul_reg64_mem64_imm32,
            .imul_reg64_reg64_imm32,
            => .bits64,
            else => unreachable,
        };
    }

    fn signedImulImmediate(instruction: DecodedInsn) i128 {
        return switch (instruction.op) {
            .imul_reg16_mem16_imm8,
            .imul_reg16_reg16_imm8,
            .imul_reg32_mem32_imm8,
            .imul_reg32_reg32_imm8,
            .imul_reg64_mem64_imm8,
            .imul_reg64_reg64_imm8,
            => @as(i128, @as(i8, @bitCast(@as(u8, @truncate(instruction.imm))))),
            .imul_reg16_mem16_imm16,
            .imul_reg16_reg16_imm16,
            => @as(i128, @as(i16, @bitCast(@as(u16, @truncate(instruction.imm))))),
            .imul_reg32_mem32_imm32,
            .imul_reg32_reg32_imm32,
            .imul_reg64_mem64_imm32,
            .imul_reg64_reg64_imm32,
            => @as(i128, @as(i32, @bitCast(@as(u32, @truncate(instruction.imm))))),
            else => unreachable,
        };
    }

    fn writeImulNarrowResult(self: *ElfState, destination: RegId, size: Size, product: i128) void {
        const product_bits: u128 = @bitCast(product);
        const result: u64 = @truncate(product_bits);
        self.setReg(destination, size, result);

        // Two- and three-operand IMUL retain only the destination width. CF
        // and OF report whether the full signed product cannot be represented
        // by that width; the remaining arithmetic flags are unaffected.
        const overflow = product != signedInteger(result, size);
        self.setFlag(RFL_CF, overflow);
        self.setFlag(RFL_OF, overflow);
    }

    fn shlCount(self: *ElfState, size: Size) u6 {
        const mask: u64 = if (size == .bits64) 0x3F else 0x1F;
        return @as(u6, @intCast(self.regVal(.cl_cx_ecx_rcx, .bits8) & mask));
    }

    fn shlValue(self: *ElfState, input: u64, size: Size, count: u6) u64 {
        _ = self;
        const mask = maskForSize(size);
        const result = (input & mask) << count;
        return result & mask;
    }

    fn setFlagsShl(self: *ElfState, input: u64, result: u64, size: Size, count: u6) void {
        if (count == 0) return;

        const width = bitWidth(size);
        const mask = maskForSize(size);
        const masked_input = input & mask;
        const masked_result = result & mask;

        if (count <= width) {
            const shift: u6 = @intCast(width - count);
            self.setFlag(RFL_CF, ((masked_input >> shift) & 1) != 0);
        } else {
            self.setFlag(RFL_CF, false);
        }

        if (count == 1) {
            const sign = signBitForSize(size);
            const msb_set = (masked_result & sign) != 0;
            const cf_set = (self.regs.rflags & RFL_CF) != 0;
            self.setFlag(RFL_OF, msb_set != cf_set);
        }

        self.setFlag(RFL_SF, (masked_result & signBitForSize(size)) != 0);
        self.setFlag(RFL_ZF, masked_result == 0);
    }

    fn immShiftCount(imm: u64, size: Size) u6 {
        const mask: u64 = if (size == .bits64) 0x3F else 0x1F;
        return @as(u6, @intCast(imm & mask));
    }

    fn executeRotate(self: *ElfState, d: DecodedInsn) void {
        const is_mem = switch (d.op) {
            .rol_mem_cl, .ror_mem_cl, .rol_mem_imm, .ror_mem_imm => true,
            else => false,
        };
        const rotate_left = switch (d.op) {
            .rol_reg_cl, .rol_mem_cl, .rol_reg_imm, .rol_mem_imm => true,
            else => false,
        };
        const uses_cl = switch (d.op) {
            .rol_reg_cl, .rol_mem_cl, .ror_reg_cl, .ror_mem_cl => true,
            else => false,
        };
        const raw_count = if (uses_cl) self.regVal(.cl_cx_ecx_rcx, .bits8) else d.imm;
        const width: u64 = bitWidth(d.size);
        const count: u6 = @intCast((raw_count & @as(u64, if (d.size == .bits64) 0x3F else 0x1F)) % width);
        if (count == 0) return;
        const mask = maskForSize(d.size);
        const old = (if (is_mem) self.readMemVal(d.addr, d.size) else self.regVal(d.dst_reg, d.size)) & mask;
        const inverse: u6 = @intCast(width - count);
        const result = if (rotate_left) ((old << count) | (old >> inverse)) & mask else ((old >> count) | (old << inverse)) & mask;
        if (is_mem) self.writeMemVal(d.addr, d.size, result) else self.setReg(d.dst_reg, d.size, result);
        if (rotate_left) {
            const carry = (result & 1) != 0;
            self.setFlag(RFL_CF, carry);
            if (count == 1) self.setFlag(RFL_OF, ((result & signBitForSize(d.size)) != 0) != carry);
        } else {
            const carry = (result & signBitForSize(d.size)) != 0;
            self.setFlag(RFL_CF, carry);
            if (count == 1) self.setFlag(RFL_OF, carry != ((result & (signBitForSize(d.size) >> 1)) != 0));
        }
    }

    fn shrValue(self: *ElfState, input: u64, size: Size, count: u6) u64 {
        _ = self;
        const mask = maskForSize(size);
        return (input & mask) >> count;
    }

    fn setFlagsShr(self: *ElfState, input: u64, result: u64, size: Size, count: u6) void {
        if (count == 0) return;

        const masked_input = input & maskForSize(size);
        const masked_result = result & maskForSize(size);
        const shifted_out: u6 = @intCast(count - 1);
        self.setFlag(RFL_CF, ((masked_input >> shifted_out) & 1) != 0);

        if (count == 1) {
            self.setFlag(RFL_OF, (masked_input & signBitForSize(size)) != 0);
        }

        self.setFlag(RFL_SF, (masked_result & signBitForSize(size)) != 0);
        self.setFlag(RFL_ZF, masked_result == 0);
    }

    fn sarValue(self: *ElfState, input: u64, size: Size, count: u6) u64 {
        _ = self;
        if (count == 0) return input & maskForSize(size);
        const sign_set = (input & signBitForSize(size)) != 0;
        if (count >= bitWidth(size)) return if (sign_set) maskForSize(size) else 0;
        return switch (size) {
            .bits8 => @as(u64, @as(u8, @bitCast(@as(i8, @bitCast(@as(u8, @truncate(input)))) >> @as(u3, @intCast(count))))),
            .bits16 => @as(u64, @as(u16, @bitCast(@as(i16, @bitCast(@as(u16, @truncate(input)))) >> @as(u4, @intCast(count))))),
            .bits32 => @as(u64, @as(u32, @bitCast(@as(i32, @bitCast(@as(u32, @truncate(input)))) >> @as(u5, @intCast(count))))),
            .bits64 => @as(u64, @bitCast(@as(i64, @bitCast(input)) >> count)),
        };
    }

    fn setFlagsSar(self: *ElfState, input: u64, result: u64, size: Size, count: u6) void {
        if (count == 0) return;

        const masked_input = input & maskForSize(size);
        const masked_result = result & maskForSize(size);
        if (count <= bitWidth(size)) {
            const shifted_out: u6 = @intCast(count - 1);
            self.setFlag(RFL_CF, ((masked_input >> shifted_out) & 1) != 0);
        }

        if (count == 1) self.setFlag(RFL_OF, false);

        self.setFlag(RFL_SF, (masked_result & signBitForSize(size)) != 0);
        self.setFlag(RFL_ZF, masked_result == 0);
    }

    fn evalCond(rflags: u32, cond: Cond) bool {
        return x64_decoder.evalCond(rflags, cond);
    }

    fn executeBitScan(self: *ElfState, d: DecodedInsn) void {
        const is_memory = switch (d.op) {
            .bsf_reg_mem, .bsr_reg_mem, .tzcnt_reg_mem, .lzcnt_reg_mem => true,
            else => false,
        };
        const kind: BitScanKind = switch (d.op) {
            .bsf_reg_reg, .bsf_reg_mem => .bsf,
            .bsr_reg_reg, .bsr_reg_mem => .bsr,
            .tzcnt_reg_reg, .tzcnt_reg_mem => .tzcnt,
            .lzcnt_reg_reg, .lzcnt_reg_mem => .lzcnt,
            else => unreachable,
        };
        const source = if (is_memory) self.readMemVal(d.addr, d.size) else self.regVal(d.src_reg, d.size);
        const result = x64_decoder.bitScan(d.size, kind, source);

        if (result.write_destination) self.setReg(d.dst_reg, d.size, result.value);
        self.setFlag(RFL_ZF, result.zero_flag);
        if (result.carry_flag) |carry| self.setFlag(RFL_CF, carry);
    }

    fn stringAddress(self: *const ElfState, index: RegId, address_size: Size, segment: x64_decoder.Segment) u64 {
        return x64_decoder.resolveMemoryAddress(&self.regs, .{
            .has_base = true,
            .base_reg = index,
            .segment = segment,
        }, 0, address_size, .long64, true);
    }

    fn executeStringOperation(self: *ElfState, d: DecodedInsn) void {
        const address_size: Size = if (d.has_0x67) .bits32 else .bits64;
        const stride: u64 = switch (d.size) {
            .bits8 => 1,
            .bits16 => 2,
            .bits32 => 4,
            .bits64 => 8,
        };
        const backwards = (self.regs.rflags & RFL_DF) != 0;
        const repeated = d.repeat != .none;
        var remaining: u64 = if (repeated)
            self.regVal(.cl_cx_ecx_rcx, address_size)
        else
            1;

        if (remaining == 0) return;

        while (remaining != 0) {
            switch (d.op) {
                .movs => {
                    const source_address = self.stringAddress(.dh_si_esi_rsi, address_size, d.segment);
                    const destination_address = self.stringAddress(.bh_di_edi_rdi, address_size, .es);
                    const value = self.readMemVal(source_address, d.size);
                    self.writeMemVal(destination_address, d.size, value);
                    const next_source = if (backwards)
                        self.regVal(.dh_si_esi_rsi, address_size) -% stride
                    else
                        self.regVal(.dh_si_esi_rsi, address_size) +% stride;
                    const next_destination = if (backwards)
                        self.regVal(.bh_di_edi_rdi, address_size) -% stride
                    else
                        self.regVal(.bh_di_edi_rdi, address_size) +% stride;
                    self.setReg(.dh_si_esi_rsi, address_size, next_source);
                    self.setReg(.bh_di_edi_rdi, address_size, next_destination);
                },
                .cmps => {
                    const source_address = self.stringAddress(.dh_si_esi_rsi, address_size, d.segment);
                    const destination_address = self.stringAddress(.bh_di_edi_rdi, address_size, .es);
                    const source = self.readMemVal(source_address, d.size);
                    const destination = self.readMemVal(destination_address, d.size);
                    const result = source -% destination;
                    self.setFlagsSub(source, destination, result, d.size);
                    const next_source = if (backwards)
                        self.regVal(.dh_si_esi_rsi, address_size) -% stride
                    else
                        self.regVal(.dh_si_esi_rsi, address_size) +% stride;
                    const next_destination = if (backwards)
                        self.regVal(.bh_di_edi_rdi, address_size) -% stride
                    else
                        self.regVal(.bh_di_edi_rdi, address_size) +% stride;
                    self.setReg(.dh_si_esi_rsi, address_size, next_source);
                    self.setReg(.bh_di_edi_rdi, address_size, next_destination);
                },
                .stos => {
                    const destination_address = self.stringAddress(.bh_di_edi_rdi, address_size, .es);
                    self.writeMemVal(destination_address, d.size, self.regVal(.al_ax_eax_rax, d.size));
                    const next_destination = if (backwards)
                        self.regVal(.bh_di_edi_rdi, address_size) -% stride
                    else
                        self.regVal(.bh_di_edi_rdi, address_size) +% stride;
                    self.setReg(.bh_di_edi_rdi, address_size, next_destination);
                },
                .lods => {
                    const source_address = self.stringAddress(.dh_si_esi_rsi, address_size, d.segment);
                    self.setReg(.al_ax_eax_rax, d.size, self.readMemVal(source_address, d.size));
                    const next_source = if (backwards)
                        self.regVal(.dh_si_esi_rsi, address_size) -% stride
                    else
                        self.regVal(.dh_si_esi_rsi, address_size) +% stride;
                    self.setReg(.dh_si_esi_rsi, address_size, next_source);
                },
                .scas => {
                    const destination_address = self.stringAddress(.bh_di_edi_rdi, address_size, .es);
                    const accumulator = self.regVal(.al_ax_eax_rax, d.size);
                    const destination = self.readMemVal(destination_address, d.size);
                    const result = accumulator -% destination;
                    self.setFlagsSub(accumulator, destination, result, d.size);
                    const next_destination = if (backwards)
                        self.regVal(.bh_di_edi_rdi, address_size) -% stride
                    else
                        self.regVal(.bh_di_edi_rdi, address_size) +% stride;
                    self.setReg(.bh_di_edi_rdi, address_size, next_destination);
                },
                else => unreachable,
            }

            if (!repeated) break;
            remaining -%= 1;
            self.setReg(.cl_cx_ecx_rcx, address_size, remaining);
            if ((d.op == .cmps or d.op == .scas) and remaining != 0) {
                const equal = (self.regs.rflags & RFL_ZF) != 0;
                const continue_repeating = switch (d.repeat) {
                    .rep => equal,
                    .repne => !equal,
                    .none => false,
                };
                if (!continue_repeating) break;
            }
        }
    }

    fn advanceAfterHandled(self: *ElfState, d: DecodedInsn) void {
        if (!self.terminated) self.regs.rip += d.len;
    }

    fn discoverXeniaRijndaelTarget(self: *const ElfState) ?u64 {
        const image_begin = self.image_low -| self.mem_base;
        const image_end = @min(self.image_high -| self.mem_base, @as(u64, @intCast(self.mem.len)));
        if (image_begin >= image_end) return null;
        const begin: usize = @intCast(image_begin);
        const end: usize = @intCast(image_end);
        const signature = [_]u8{
            0x41, 0x57, 0x41, 0x56, 0x41, 0x55, 0x41, 0x54,
            0x56, 0x57, 0x55, 0x53, 0x48, 0x83, 0xEC, 0x38,
            0x4C, 0x89, 0x4C, 0x24, 0x20,
        };
        var offset = begin;
        while (offset + signature.len <= end) : (offset += 1) {
            if (!std.mem.eql(u8, self.mem[offset .. offset + signature.len], &signature)) continue;
            // rijndaelEncrypt and rijndaelDecrypt share the entry prologue
            // and the initial block setup. Their first table load is the
            // stable discriminator: encryption loads Te1 through r13, while
            // decryption loads Td0 through r11. Ignore the RIP-relative
            // displacement that follows the opcode so a rebuilt PE remains
            // discoverable when its section layout changes.
            if (offset + 70 > end) continue;
            if (self.mem[offset + 67] != 0x4C or
                self.mem[offset + 68] != 0x8D or
                self.mem[offset + 69] != 0x1D)
            {
                continue;
            }
            return self.mem_base + offset;
        }
        return null;
    }

    fn discoverXeniaSha1Target(self: *const ElfState) ?u64 {
        const image_begin = self.image_low -| self.mem_base;
        const image_end = @min(self.image_high -| self.mem_base, @as(u64, @intCast(self.mem.len)));
        if (image_begin >= image_end) return null;
        const begin: usize = @intCast(image_begin);
        const end: usize = @intCast(image_end);

        // MinGW's TinySHA1 build has a stable entry prologue. The RIP
        // displacement of the byte-shuffle mask is intentionally excluded so
        // rebuilt Xenia binaries remain discoverable.
        const signature = [_]u8{
            0x41, 0x56, 0x56, 0x57, 0x55, 0x53,
            0x48, 0x81, 0xec, 0x40, 0x01, 0x00,
            0x00, 0xc5, 0xfa, 0x6f, 0x41, 0x1c,
        };
        var offset = begin;
        while (offset + signature.len <= end) : (offset += 1) {
            if (!std.mem.eql(u8, self.mem[offset .. offset + signature.len], &signature)) continue;
            // The next instruction loads the byte-shuffle mask with vmovdqa;
            // this secondary check avoids treating an unrelated AVX function
            // with the same register-save prologue as SHA1.
            if (offset + 25 > end or
                self.mem[offset + 18] != 0xc5 or
                self.mem[offset + 19] != 0xf9 or
                self.mem[offset + 20] != 0x6f or
                self.mem[offset + 21] != 0x0d)
            {
                continue;
            }
            return self.mem_base + offset;
        }
        return null;
    }

    fn discoverXeniaTabulateTarget(self: *const ElfState) ?u64 {
        const image_begin = self.image_low -| self.mem_base;
        const image_end = @min(self.image_high -| self.mem_base, @as(u64, @intCast(self.mem.len)));
        if (image_begin >= image_end) return null;
        const begin: usize = @intCast(image_begin);
        const end: usize = @intCast(image_end);

        // tabulate::Table::str() in the MinGW Xenia build begins with the
        // saved-register/0x1b0-byte stack frame below. The symbol lookup is
        // preferred, but this exact entry signature keeps rebuilt capsules
        // discoverable without matching ordinary string helpers.
        const signature = [_]u8{
            0x56, 0x57, 0x53, 0x48, 0x81, 0xec, 0xb0, 0x01,
            0x00, 0x00, 0x48, 0x89, 0xd7, 0x48, 0x89, 0xce,
            0x48, 0x8d, 0x4c, 0x24, 0x28,
        };
        var offset = begin;
        while (offset + signature.len <= end) : (offset += 1) {
            if (!std.mem.eql(u8, self.mem[offset .. offset + signature.len], &signature)) continue;
            // The first body call constructs a stringstream at rsp+0x28;
            // require the following relative-call opcode to avoid a generic
            // register-save false positive.
            if (offset + 25 > end or self.mem[offset + 21] != 0xe8) continue;
            return self.mem_base + offset;
        }
        return null;
    }

    fn tryXeniaRijndaelAccelerator(self: *ElfState, target: u64, return_rip: u64) bool {
        if (!self.xenia_rijndael_accelerator_enabled or !self.windows_runtime_enabled) return false;

        if (!self.xenia_rijndael_target_checked) {
            self.xenia_rijndael_target_checked = true;
            self.xenia_rijndael_target = self.localSymbolAddress("_Z15rijndaelDecryptPKjiPKhPh") orelse
                self.localSymbolAddress("__Z15rijndaelDecryptPKjiPKhPh") orelse
                self.localSymbolAddress("rijndaelDecrypt") orelse
                self.discoverXeniaRijndaelTarget();
            if (self.xenia_rijndael_target) |resolved| {
                log.info("PE64 Xenia Rijndael accelerator armed: target=0x{x} entry-signature-gated=true", .{resolved});
            } else {
                log.warn("PE64 Xenia Rijndael accelerator requested but the rijndaelDecrypt symbol and entry signature were not found; execution remains guest-interpreted", .{});
            }
        }

        if (self.xenia_rijndael_target == null or self.xenia_rijndael_target.? != target) return false;

        if (!xenia_accelerator.tryRijndaelDecrypt(self, self.regs.rcx, self.regs.rdx, self.regs.r8, self.regs.r9)) {
            self.xenia_rijndael_accelerator_failures +|= 1;
            if (self.xenia_rijndael_accelerator_failures == 1) {
                log.warn("PE64 Xenia Rijndael accelerator declined a block: target=0x{x} rk=0x{x} nr={d} ciphertext=0x{x} plaintext=0x{x} step={d}; falling back to the guest implementation", .{
                    target,
                    self.regs.rcx,
                    self.regs.rdx,
                    self.regs.r8,
                    self.regs.r9,
                    self.executed_steps,
                });
            }
            return false;
        }

        self.noteGuestCall(.direct, target, return_rip);
        self.regs.rip = return_rip;
        self.noteGuestReturn(return_rip);
        self.xenia_rijndael_accelerated_calls +|= 1;
        if (self.xenia_rijndael_accelerated_calls == 1) {
            log.info("PE64 Xenia Rijndael accelerator active: first 16-byte block completed at step={d} nr={d}", .{
                self.executed_steps,
                self.regs.rdx,
            });
        }
        return true;
    }

    fn tryXeniaSha1Accelerator(self: *ElfState, target: u64, return_rip: u64) bool {
        if (!self.xenia_sha1_accelerator_enabled or !self.windows_runtime_enabled) return false;

        if (!self.xenia_sha1_target_checked) {
            self.xenia_sha1_target_checked = true;
            self.xenia_sha1_target = self.localSymbolAddress("_ZN4sha14SHA112processBlockEv") orelse
                self.localSymbolAddress("__ZN4sha14SHA112processBlockEv") orelse
                self.localSymbolAddress("sha1::SHA1::processBlock") orelse
                self.discoverXeniaSha1Target();
            if (self.xenia_sha1_target) |resolved| {
                log.info("PE64 Xenia SHA1 accelerator armed: target=0x{x} entry-signature-gated=true", .{resolved});
            } else {
                log.warn("PE64 Xenia SHA1 accelerator requested but SHA1::processBlock was not found; execution remains guest-interpreted", .{});
            }
        }

        if (self.xenia_sha1_target == null or self.xenia_sha1_target.? != target) return false;

        if (!xenia_accelerator.trySha1ProcessBlock(self, self.regs.rcx)) {
            self.xenia_sha1_accelerator_failures +|= 1;
            if (self.xenia_sha1_accelerator_failures == 1) {
                log.warn("PE64 Xenia SHA1 accelerator declined a block: target=0x{x} this=0x{x} step={d}; falling back to guest implementation", .{
                    target,
                    self.regs.rcx,
                    self.executed_steps,
                });
            }
            return false;
        }

        self.noteGuestCall(.direct, target, return_rip);
        self.regs.rip = return_rip;
        self.noteGuestReturn(return_rip);
        self.xenia_sha1_accelerated_blocks +|= 1;
        if (self.xenia_sha1_accelerated_blocks == 1) {
            log.info("PE64 Xenia SHA1 accelerator active: first 64-byte block completed at step={d}", .{self.executed_steps});
        }
        self.tryXeniaSha1FeedLoop(return_rip);
        return true;
    }

    /// The byte-feed loop around an accelerated `processBlock`.
    ///
    /// Accelerating the compression alone leaves the expensive half
    /// interpreted: the compiler inlines TinySHA1's `processBytes` into its
    /// caller as eleven instructions per byte, so a twenty-megabyte guest
    /// image costs a couple of hundred million steps to hash. On 2026-09-11
    /// that was the whole visible frontier - `XexModule::Precompile+0x283` -
    /// when the run was killed.
    ///
    /// This is recognized by the loop's own instruction bytes rather than by
    /// an address, and the exit target is read out of the matched branch, so
    /// it is not tied to one Xenia link. It runs only from inside an already
    /// signature-gated `processBlock`, and it deliberately stops one byte
    /// short of the end: the guest executes the final iteration itself, which
    /// leaves every register the loop wrote holding the value the guest's own
    /// code would have left there. Nothing here has to reason about which of
    /// `rax`, `rcx` and `rdx` is live after the branch.
    fn tryXeniaSha1FeedLoop(self: *ElfState, return_rip: u64) void {
        if (!self.xenia_sha1_feed_enabled) return;
        // `jmp rel8` back to the loop's increment head.
        const tail = self.guestMemoryConst(return_rip, 2) orelse return;
        if (tail[0] != 0xEB) return;
        const back: i8 = @bitCast(tail[1]);
        if (back >= 0) return;
        const head = @as(u64, @bitCast(@as(i64, @bitCast(return_rip + 2)) + back));

        // inc %r15 ; cmp %r15,%rbx ; je rel32 ; ... ; movzbl (%r14,%r15,1),%eax
        const loop = self.guestMemoryConst(head, 17) orelse return;
        const precompile = std.mem.eql(u8, loop[0..6], &[_]u8{ 0x49, 0xFF, 0xC7, 0x4C, 0x39, 0xFB }) and
            std.mem.eql(u8, loop[6..8], &[_]u8{ 0x0F, 0x84 }) and
            std.mem.eql(u8, loop[12..17], &[_]u8{ 0x43, 0x0F, 0xB6, 0x04, 0x3E });
        // XeCryptShaUpdate's compiler-inlined feed uses RBX as source and
        // R12 as limit, not Precompile's R14/RBX. Match its *whole* body,
        // including stack offsets and branch targets; a prefix alone cannot
        // prove that the skipped instructions only update this SHA1 object.
        const kernel_loop = self.guestMemoryConst(head, xenia_sha1_kernel_feed_body.len + 4);
        const kernel_feed = !precompile and return_rip == head + xenia_sha1_kernel_feed_body.len + 4 and
            (if (kernel_loop) |body| std.mem.eql(u8, body[0..xenia_sha1_kernel_feed_body.len], &xenia_sha1_kernel_feed_body) else false);
        if (!precompile and !kernel_feed) return;
        if (kernel_feed) {
            const body = kernel_loop.?;
            const rel = std.mem.readInt(i32, body[xenia_sha1_kernel_feed_body.len..][0..4], .little);
            const call_target = return_rip +% @as(u64, @bitCast(@as(i64, rel)));
            if (self.xenia_sha1_target == null or call_target != self.xenia_sha1_target.?) return;
            // In this shape RDI is the stack object (digest +8, block +1C,
            // index +60, count +68). Prove that identity as well as RCX.
            if (self.regs.rdi != self.regs.rsp +| 0x20) return;
        }

        // The call site loaded the SHA1 object from `rdi`; if `rcx` no longer
        // agrees this is not the shape that was matched.
        if (self.regs.rcx != self.regs.rdi) return;

        const cursor = self.regs.r15;
        const limit = if (kernel_feed) self.regs.r12 else self.regs.rbx;
        const base = if (kernel_feed) self.regs.rbx else self.regs.r14;
        if (limit <= cursor) return;
        // Leave the last two iterations to the guest: one feeds the final
        // byte, the next takes the branch out.
        const remaining = limit - cursor;
        if (remaining < XENIA_SHA1_FEED_MINIMUM) return;
        // Bound one native turn so a large title hash cannot prevent event
        // pumping or other cooperative workers from getting a scheduling turn.
        const consume = @min(remaining - 2, 256 * 1024);
        const start = std.math.add(u64, base, cursor + 1) catch return;

        if (!xenia_accelerator.sha1ProcessBytes(self, self.regs.rdi, start, consume)) {
            self.xenia_sha1_feed_declines +|= 1;
            return;
        }
        self.regs.r15 = cursor + consume;
        self.xenia_sha1_feed_spans +|= 1;
        self.xenia_sha1_feed_bytes +|= consume;
        if (kernel_feed) {
            self.xenia_sha1_kernel_feed_spans +|= 1;
            self.xenia_sha1_kernel_feed_bytes +|= consume;
            if (self.xenia_sha1_kernel_feed_spans == 1) {
                log.info("PE64 Xenia kernel SHA1 feed accelerator active: consumed={d} loop_head=0x{x} bounded_turn_bytes=262144 computation=unchanged continuation=guest_owned", .{ consume, head });
            }
        }
        if (self.xenia_sha1_feed_spans == 1) {
            log.info("PE64 Xenia SHA1 feed accelerator active: consumed {d} byte(s) in one step at step={d} loop_head=0x{x}; the interpreted form of this loop costs about eleven instructions per byte", .{
                consume,
                self.executed_steps,
                head,
            });
        }
    }

    fn tryXeniaTabulateAccelerator(self: *ElfState, target: u64, return_rip: u64) bool {
        if (!self.xenia_tabulate_accelerator_enabled or !self.windows_runtime_enabled) return false;

        if (!self.xenia_tabulate_target_checked) {
            self.xenia_tabulate_target_checked = true;
            self.xenia_tabulate_target = self.localSymbolAddress("_ZN8tabulate5Table3strB5cxx11Ev") orelse
                self.localSymbolAddress("tabulate::Table::str[abi:cxx11]()") orelse
                self.discoverXeniaTabulateTarget();
            if (self.xenia_tabulate_target) |resolved| {
                log.info("PE64 Xenia metadata table accelerator armed: target=0x{x} entry-signature-gated=true", .{resolved});
            } else {
                log.warn("PE64 Xenia metadata table accelerator requested but tabulate::Table::str was not found; execution remains guest-interpreted", .{});
            }
        }

        if (self.xenia_tabulate_target == null or self.xenia_tabulate_target.? != target) return false;

        // basic_string's non-trivial return uses the hidden RCX result
        // pointer; RDX is the tabulate::Table object.
        if (!xenia_accelerator.tryXeniaTabulateString(self, self.regs.rcx, self.regs.rdx)) {
            self.xenia_tabulate_accelerator_failures +|= 1;
            if (self.xenia_tabulate_accelerator_failures == 1) {
                log.warn("PE64 Xenia metadata table accelerator declined a string: target=0x{x} result=0x{x} table=0x{x} step={d}; falling back to tabulate", .{
                    target,
                    self.regs.rcx,
                    self.regs.rdx,
                    self.executed_steps,
                });
            }
            return false;
        }

        self.noteGuestCall(.direct, target, return_rip);
        self.regs.rip = return_rip;
        self.noteGuestReturn(return_rip);
        self.xenia_tabulate_accelerated_strings +|= 1;
        if (self.xenia_tabulate_accelerated_strings == 1) {
            log.info("PE64 Xenia metadata table accelerator active: first table string bypassed at step={d}", .{self.executed_steps});
        }
        return true;
    }

    pub fn execute(self: *ElfState, d: DecodedInsn) void {
        if (d.is_evex or d.op == .movdir64b or evex.handles(d.op)) {
            // The EVEX register write clears everything above the operand,
            // which is the VEX rule. Legacy SSE forms routed here (PSHUFD,
            // SHUFPS/SHUFPD) must leave the destination's upper YMM lane as
            // it was, and a legacy instruction never changes it otherwise.
            const preserved_upper: ?[16]u8 = if (d.legacy_sse and !d.is_evex) self.ymm_hi[d.xmm_dst] else null;
            evex.execute(self, d);
            if (preserved_upper) |upper| self.ymm_hi[d.xmm_dst] = upper;
            self.advanceAfterHandled(d);
            return;
        }

        // Keep vector moves and VEX.128 upper-lane clearing outside the
        // arithmetic router. These operations have architectural state
        // effects that a generic CLEO arithmetic call cannot express.
        if (self.executeCleoVectorMove(d)) {
            self.advanceAfterHandled(d);
            return;
        }
        if (d.op == .vzeroupper) {
            for (&self.ymm_hi) |*upper| @memset(upper, 0);
            self.advanceAfterHandled(d);
            return;
        }
        if (self.executeSharedVex(d)) {
            self.advanceAfterHandled(d);
            return;
        }
        if (self.executeVectorSpecial(d)) {
            self.advanceAfterHandled(d);
            return;
        }
        if (self.tryExecuteCleo(d)) {
            self.advanceAfterHandled(d);
            return;
        }
        if (isVectorOperationRuntime(d.op) and !isLegacyVectorTransfer(d.op)) {
            self.terminateUnimplemented(d);
            return;
        }

        // Accumulator-immediate forms are scalar Group-1 operations. Handle
        // them before the broad legacy fallback, whose compatibility list also
        // contains these Op tags for older vector dispatch coverage.
        if (isAccumulatorImmediate(d.op)) {
            self.executeAccumulatorImmediate(d);
            self.advanceAfterHandled(d);
            return;
        }

        switch (d.op) {
            .invalid => self.terminateUnimplemented(d),
            .nop => {},
            .cmc => self.regs.rflags ^= RFL_CF,
            .clc => self.regs.rflags &= ~RFL_CF,
            .stc => self.regs.rflags |= RFL_CF,
            // Direction flag. The string operations read it for their stride,
            // so without these the guest was subject to a flag it could not set.
            .cld => self.regs.rflags &= ~RFL_DF,
            .std => self.regs.rflags |= RFL_DF,
            .xchg_accum_reg => {
                const sz = d.size;
                const left = self.regVal(.al_ax_eax_rax, sz);
                const right = self.regVal(d.src_reg, sz);
                self.setReg(.al_ax_eax_rax, sz, right);
                self.setReg(d.src_reg, sz, left);
            },
            .loopne, .loope, .loop, .jrcxz => {
                const counter_size: Size = if (d.has_0x67) .bits32 else .bits64;
                var taken = false;
                if (d.op == .jrcxz) {
                    taken = self.regVal(.cl_cx_ecx_rcx, counter_size) == 0;
                } else {
                    const next = self.regVal(.cl_cx_ecx_rcx, counter_size) -% 1;
                    self.setReg(.cl_cx_ecx_rcx, counter_size, next);
                    const zero = (self.regs.rflags & RFL_ZF) != 0;
                    taken = next != 0 and switch (d.op) {
                        .loope => zero,
                        .loopne => !zero,
                        else => true,
                    };
                }
                if (taken) {
                    self.regs.rip = self.regs.rip +% d.len +% d.imm;
                } else {
                    self.regs.rip +%= d.len;
                }
                return;
            },
            .xlat => {
                const table = self.regVal(.bl_bx_ebx_rbx, .bits64);
                const index = self.regVal(.al_ax_eax_rax, .bits8) & 0xFF;
                const value = self.readMemVal(table +% index, .bits8);
                self.setReg(.al_ax_eax_rax, .bits8, value & 0xFF);
            },
            .lahf => {
                const ah = @as(u64, x64_decoder.statusByteForLahf(self.regs.rflags));
                self.regs.rax = (self.regs.rax & 0xFFFF_FFFF_FFFF_00FF) | (ah << 8);
            },
            .sahf => x64_decoder.applySahf(&self.regs.rflags, @truncate(self.regs.rax >> 8)),

            // The D8-DF x87 arithmetic family (fadd/fmul/fsub/fsubr/fdiv/fdivr
            // with m32/m64, plus the fi* integer forms) is decoded by the shared
            // decoder into a single .x87_binary op with the operation packed in
            // x87.imm; the per-size members below are the only x87 ops the
            // shared Op enum exposes.
            .fild_mem16 => {
                const value = @as(i16, @bitCast(@as(u16, @truncate(self.readMemVal(d.addr, .bits16)))));
                _ = self.x87PushRaw(x87RawFromInt(value));
            },
            .fild_mem32 => {
