                self.setFlagsSub(accum, old, accum -% old, size);
                if ((accum & maskForSize(size)) == (old & maskForSize(size))) {
                    if (d.is_reg_form) {
                        self.setReg(d.dst_reg, size, self.regVal(d.src_reg, size));
                    } else {
